	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (engine == null || !loginReady)
		{
			return;
		}

		// Whose house a click leads into. The "Loading house" interface spends it.
		houseWatch.entryClicked(HouseEntry.of(clickKind(event.getMenuAction()),
			event.getMenuOption(), event.getMenuTarget(), dialogLine(event)), client.getTickCount());

		// Only armed here. The tick handler confirms whether the teleport happened.
		if (ArdougneFarmTeleportWatch.isFarmTeleportOption(event.getMenuOption())
			&& ArdougneFarmTeleportWatch.isCloak(clickedItemId(event)))
		{
			WorldPoint from = playerLocation();
			if (from != null)
			{
				ardougneFarmTeleport.clicked(client.getTickCount(), from.getX(), from.getY());
			}
		}
	}

	/** The kind of menu entry a click was, as {@link HouseEntry} tells house entries apart. */
	private static HouseEntry.Click clickKind(MenuAction action)
	{
		if (action == null)
		{
			return HouseEntry.Click.OTHER;
		}
		switch (action)
		{
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
				return HouseEntry.Click.OBJECT;
			case WIDGET_CONTINUE:
				return HouseEntry.Click.DIALOG;
			default:
				return HouseEntry.Click.OTHER;
		}
	}

	/** The clicked dialog option's line, or null when the click was no dialog option. */
	private static String dialogLine(MenuOptionClicked event)
	{
		if (event.getMenuAction() != MenuAction.WIDGET_CONTINUE)
		{
			return null;
		}
		Widget widget = event.getWidget();
		return widget != null ? widget.getText() : null;
	}

	/**
	 * The item a menu click was made on, whether it is being carried or worn.
	 *
	 * <p>{@code MenuOptionClicked.getItemId()} answers only for inventory item ops. A worn
	 * item's op carries no item id, so it is read off the equipment widget, as RuneLite's
	 * {@code MenuEntrySwapperPlugin} does. Most cloak teleports are made from the worn slot.
	 *
	 * @return the item id, or -1 when the click was not on an item
	 */
	private static int clickedItemId(MenuOptionClicked event)
	{
		int itemId = event.getItemId();
		if (itemId != -1)
		{
			return itemId;
		}
		Widget widget = event.getMenuEntry().getWidget();
		if (widget == null || WidgetUtil.componentToInterface(widget.getId()) != InterfaceID.WORNITEMS)
		{
			return -1;
		}
		// The slot widget holds the item in child 1.
		Widget child = widget.getChild(1);
		return child != null ? child.getItemId() : -1;
	}

	/**
	 * Charges the day's allowance when an armed Ardougne cloak teleport lands. See
	 * {@link ArdougneFarmTeleportWatch}.
	 */
	private void handleArdougneFarmTeleport()
	{
		if (!ardougneFarmTeleport.isArmed())
		{
			return;
		}
		WorldPoint at = playerLocation();
		if (at != null && ardougneFarmTeleport.arrived(client.getTickCount(), at.getX(), at.getY()))
		{
			planner.recordArdougneFarmTeleport();
		}
	}
}

package com.larryfarming.data;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;

/**
 * Reads Larry's tab-separated data tables from the plugin jar.
 *
 * <p>A table is a UTF-8 text resource with one row per line and cells split on tabs. Lines
 * starting with {@code #} are comments, and blank lines are skipped. A cell holding only
 * {@code -} is empty: it reads as the empty string, as null through {@link Row#optionalText},
 * as no constant through {@link Row#optionalConstant} or {@link Row#constants}, as no ints
 * through {@link Row#integers} and as false through {@link Row#flag}. It is not a number.
 *
 * <p>Tables load in static initialisers, where a bad row would otherwise surface as a bare
 * {@code ExceptionInInitializerError}. So every failure here, and every failure a caller
 * raises through {@link Row#error}, names the resource and the line. Callers index cells
 * from 0; messages count columns from 1, as a reader of the file does.
 *
 * <p>A table's owner may resolve constants only of enums whose own initialisers do not,
 * directly or through another class, read a table that names the owner. Such a cycle leaves
 * one enum uninitialised while the other reads it, and {@link Row#constant} reports it.
 */
public final class Tables {

    /** The cell text that stands for "nothing here". */
    public static final String EMPTY = "-";

    private Tables() {
    }

    /**
     * Every row of a classpath resource, in file order.
     *
     * @param resource an absolute resource path, such as {@code /com/larryfarming/patches.tsv}
     * @throws IllegalStateException if the resource is missing or unreadable
     */
    public static List<Row> read(String resource) {
        if (!resource.startsWith("/")) {
            throw new IllegalArgumentException(resource + ": not an absolute resource path");
        }
        InputStream in = Tables.class.getResourceAsStream(resource);
        if (in == null) {
            throw new IllegalStateException(resource + ": no such resource");
        }
        List<Row> rows = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            int lineNumber = 0;
            for (String line = reader.readLine(); line != null; line = reader.readLine()) {
                lineNumber++;
                if (line.isBlank() || line.startsWith("#")) {
                    continue;
                }
                rows.add(new Row(resource, lineNumber, line.split("\t", -1)));
            }
        } catch (IOException e) {
            throw new IllegalStateException(resource + ": unreadable", e);
        }
        return Collections.unmodifiableList(rows);
    }

    /**
     * Every row of a resource whose rows all have exactly {@code width} cells.
     *
     * @throws IllegalStateException naming the first row of another width
     */
    public static List<Row> read(String resource, int width) {
        List<Row> rows = read(resource);
        for (Row row : rows) {
            row.requireWidth(width);
        }
        return rows;
    }

    /**
     * The rows of an enum's attribute table, keyed by the constant name in their first cell.
     *
     * <p>An enum's constructor reads its own row from this by {@code name()}, so the enum
     * keeps its constants in Java and its attributes in data. Hold the map in a nested
     * class: the enum's own static fields are not set while its constructors run. Keyed by
     * name, not by constant, because the constants do not exist yet. Call
     * {@link Named#requireAll} once every constant is built, so a row naming no constant
     * fails too.
     *
     * @throws IllegalStateException naming a row of another width or a repeated name
     */
    public static Named byName(String resource, int width) {
        return new Named(resource, read(resource, width));
    }

    /** An enum's attribute rows, by constant name; see {@link #byName}. */
    public static final class Named {

        private final String resource;
        private final Map<String, Row> rows = new HashMap<>();
        private final Set<String> read = new HashSet<>();

        private Named(String resource, List<Row> table) {
            this.resource = resource;
            for (Row row : table) {
                if (rows.put(row.cell(0), row) != null) {
                    throw row.error("a second row for " + row.cell(0));
                }
            }
        }

        /** @throws IllegalStateException if no row names {@code name} */
        public Row of(String name) {
            Row row = rows.get(name);
            if (row == null) {
                // No line to name: the constant is in Java and the table lacks its row.
                throw new IllegalStateException(resource + ": no row for constant " + name);
            }
            read.add(name);
            return row;
        }

        /** @throws IllegalStateException if {@link #of} never asked for a row, such as a misspelt one */
        public void requireAllRead() {
            for (Row row : rows.values()) {
                if (!read.contains(row.cell(0))) {
                    throw row.error("nothing reads " + row.cell(0));
                }
            }
        }

        /** @throws IllegalStateException if a row names none of {@code constants} */
        public void requireAll(Enum<?>[] constants) {
            if (rows.size() != constants.length) {
                Map<String, Row> extra = new HashMap<>(rows);
                for (Enum<?> constant : constants) {
                    extra.remove(constant.name());
                }
                throw extra.values().iterator().next().error("names no constant");
            }
        }
    }

    /** One line of a table: its cells, and where it came from for error messages. */
    @AllArgsConstructor(access = AccessLevel.PRIVATE)
    public static final class Row {

        private final String resource;
        private final int line;
        private final String[] cells;

        public int width() {
            return cells.length;
        }

        /** @throws IllegalStateException if the row does not have exactly {@code width} cells */
        public Row requireWidth(int width) {
            if (cells.length != width) {
                throw error("expected " + width + " cells, found " + cells.length);
            }
            return this;
        }

        /** The cell's text, or "" for an {@link #EMPTY} cell. */
        public String text(int column) {
            String cell = cell(column);
            return cell.equals(EMPTY) ? "" : cell;
        }

        /** The cell's text, or null for an {@link #EMPTY} cell. */
        public String optionalText(int column) {
            String text = text(column);
            return text.isEmpty() ? null : text;
        }

        /** The cell as an int; an {@link #EMPTY} cell is not a number. */
        public int integer(int column) {
            String cell = cell(column);
            try {
                return Integer.parseInt(cell);
            } catch (NumberFormatException e) {
                throw error(columnName(column) + " is not a number: " + cell);
            }
        }

        /** The cell as ints separated by single spaces; an {@link #EMPTY} cell is no ints. */
        public int[] integers(int column) {
            String cell = text(column);
            if (cell.isEmpty()) {
                return new int[0];
            }
            String[] parts = cell.split(" ");
            int[] values = new int[parts.length];
            for (int i = 0; i < parts.length; i++) {
                try {
                    values[i] = Integer.parseInt(parts[i]);
                } catch (NumberFormatException e) {
                    throw error(columnName(column) + " is not a list of numbers: " + cell);
                }
            }
            return values;
        }

        /** The cell as a constant of {@code type}, by exact name. */
        public <E extends Enum<E>> E constant(Class<E> type, int column) {
            return constant(type, column, cell(column));
        }

        private <E extends Enum<E>> E constant(Class<E> type, int column, String cell) {
            if (type.getEnumConstants() == null) {
                // Enum.valueOf would call this "not an enum type", hiding the cycle.
                throw error(type.getSimpleName() + " is not initialised yet: a class-init cycle");
            }
            try {
                return Enum.valueOf(type, cell);
            } catch (IllegalArgumentException e) {
                throw error(columnName(column) + " names no " + type.getSimpleName() + ": " + cell);
            }
        }

        /** The cell as constants of {@code type} separated by single spaces; {@link #EMPTY} is none. */
        public <E extends Enum<E>> List<E> constants(Class<E> type, int column) {
            String cell = text(column);
            List<E> values = new ArrayList<>();
            for (String name : cell.isEmpty() ? new String[0] : cell.split(" ")) {
                values.add(constant(type, column, name));
            }
            return List.copyOf(values);
        }

        /** The cell as a constant of {@code type}, or null for an {@link #EMPTY} cell. */
        public <E extends Enum<E>> E optionalConstant(Class<E> type, int column) {
            return cell(column).equals(EMPTY) ? null : constant(type, column);
        }

        /**
         * Whether the cell holds {@code word}, for a yes/no column written as the word or
         * {@link #EMPTY}.
         */
        public boolean flag(int column, String word) {
            String cell = cell(column);
            if (cell.equals(word)) {
                return true;
            }
            if (cell.equals(EMPTY)) {
                return false;
            }
            throw error(columnName(column) + " must be " + word + " or " + EMPTY + ": " + cell);
        }

        /** An exception naming this row, for a caller rejecting what it holds. */
        public IllegalStateException error(String message) {
            return new IllegalStateException(resource + ":" + line + ": " + message);
        }

        private String cell(int column) {
            if (column < 0 || column >= cells.length) {
                throw error("no " + columnName(column) + " in " + Arrays.toString(cells));
            }
            return cells[column];
        }

        private static String columnName(int column) {
            return "column " + (column + 1);
        }
    }
}

package com.larryfarming.engine;

/**
 * Hears what the {@link StateEngine} does to the account it holds, for code that plans
 * against the same player state without the engine knowing what it plans.
 *
 * <p>Every call arrives on the thread driving the engine, which in the plugin is the client
 * thread, and from inside the engine call that caused it.
 */
public interface EngineListener {

    /**
     * The engine has just forgotten the last account and is about to load the next one's
     * saved state. Nothing has been announced for the new account yet, so state loaded here
     * is in place for the load's first {@link #stateChanged}.
     */
    default void accountLoading() {
    }

    /** A varbit the engine holds took a new value, from a live change event. */
    default void varbitChanged(int varbitId, int value) {
    }

    /**
     * The engine has folded in a batch of changes: a load, or the events of one tick. Fires
     * whether or not anything the listener reads moved.
     */
    default void stateChanged() {
    }
}

package com.larryfarming.engine;

import com.larryfarming.model.*;

import java.time.Instant;
import java.util.*;

/**
 * Folds one game event into the {@link PlayerState}. Stateless: every method takes the state
 * it changes.
 */
public final class EventApplier {

    private EventApplier() {
    }

    /** A skill's new level and XP. A skill this plugin does not know is skipped. */
    public static void applyStatChanged(PlayerState state, String skillName, long xp, int level) {
        putSkill(state, skillName, new SkillState(level, xp));
    }

    private static void putSkill(PlayerState state, String skillName, SkillState skillState) {
        Skill skill = Skill.fromString(skillName);
        if (skill != null) {
            state.getSkills().put(skill, skillState);
        }
    }

    /**
     * The account as the client reports it at login: every skill, and what the player is
     * carrying and wearing. The plugin writes every quest's state straight after.
     */
    public static void applyLoginState(PlayerState state, Map<String, SkillState> skills,
            List<ItemStack> inventory, Map<EquipmentSlot, ItemStack> equipment) {
        skills.forEach((name, skillState) -> putSkill(state, name, skillState));
        state.setInventory(inventory);
        applyEquipmentChanged(state, equipment);
    }

    /**
     * Replace the tracked seed box contents and stamp them as verified.
     *
     * <p>Fed by two sources. The item container ({@code SEED_BOX}, 573) has never been
     * observed to arrive. The chat listing from checking the box does arrive: an empty box
     * as an empty list, a full one as the seeds it names. Either is a whole-box statement, so
     * it replaces the tally rather than adjusting it. This is the only way an over-count
     * comes down.
     */
    public static void applySeedBoxChanged(PlayerState state, List<ItemStack> items) {
        state.setSeedBox(items);
        state.setSeedBoxLastSeen(Instant.now());
        // The only place verifiedAt is stamped: every other seed-box path adjusts a tally.
        state.setSeedBoxVerifiedAt(Instant.now());
    }

    /**
     * Adds seeds the player has just put in the box.
     *
     * <p>A running tally, unlike every other container here, because the game never sends
     * inventory {@code SEED_BOX} unasked. Seeds boxed before the plugin watched are
     * invisible and a missed movement is never corrected, so the tally drifts both ways.
     *
     * <p>{@link #applySeedBoxTaken} clamps at zero, which clears an under-count, but an
     * over-count survives every empty. Only {@link #applySeedBoxChanged} overwrites the whole
     * box.
     */
    public static void applySeedBoxStored(PlayerState state, ItemStack stored) {
        List<ItemStack> box = new ArrayList<>(state.getSeedBox());
        addStack(box, stored);
        commitSeedBox(state, box, stored.getItemId(), stored.getQuantity());
    }

    /** Adds a stack to the list, onto the stack of the same item when there is one. */
    private static void addStack(List<ItemStack> stacks, ItemStack added) {
        for (int i = 0; i < stacks.size(); i++) {
            ItemStack held = stacks.get(i);
            if (held.getItemId() == added.getItemId()) {
                stacks.set(i, new ItemStack(held.getItemId(), held.getQuantity() + added.getQuantity(), held.getName()));
                return;
            }
        }
        stacks.add(added);
    }

    /**
     * Removes seeds that have left the box, whether emptied into the bag or planted.
     *
     * <p>Matched by name, only against what the box holds. The chat line ("Emptied 1 x
     * Asgarnian seed to your inventory") does not name its container, so a name the box does
     * not hold is ignored rather than reported: the line came from another container.
     *
     * @param itemName as the game said it, which for a seed planted straight from the box is
     *                 lower-case and plural — see {@link #namesTheSameItem}
     * @param quantity how many left, as a positive number
     */
    public static void applySeedBoxTaken(PlayerState state, String itemName, int quantity) {
        List<ItemStack> box = new ArrayList<>(state.getSeedBox());
        for (int i = 0; i < box.size(); i++) {
            ItemStack held = box.get(i);
            if (!namesTheSameItem(held.getName(), itemName)) {
                continue;
            }
            int left = held.getQuantity() - quantity;
            if (left > 0) {
                box.set(i, new ItemStack(held.getItemId(), left, held.getName()));
            } else {
                // Clamp at empty: seeds boxed before the plugin watched can make more leave
                // than the tally knew went in.
                box.remove(i);
            }
            commitSeedBox(state, box, held.getItemId(), -quantity);
            return;
        }
    }

    /**
     * Case-insensitive name match with an optional trailing "s": the box says "Potato cactus
     * seed" when filled and "3 potato cactus seeds were taken" when planted from. A bush seed
     * planted from the box gains the word "bush": "A whiteberry bush seed was taken" for the
     * item "Whiteberry seed".
     */
    private static boolean namesTheSameItem(String held, String spoken) {
        if (held == null || spoken == null) {
            return false;
        }
        String said = spoken.replace(" bush seed", " seed");
        if (held.equalsIgnoreCase(said)) {
            return true;
        }
        return said.length() > 1 && (said.endsWith("s") || said.endsWith("S"))
                && held.equalsIgnoreCase(said.substring(0, said.length() - 1));
    }

    /**
     * @param movedId the seed the chat line moved
     * @param moved   how many went in, negative for out
     */
    private static void commitSeedBox(PlayerState state, List<ItemStack> box, int movedId, int moved) {
        state.setSeedBox(box);
        state.setSeedBoxLastSeen(Instant.now());
        // Any watched movement lets every kind in the tally take a place in the box; see
        // SeedBox#contentsCarried.
        state.setSeedBoxWatchedAt(Instant.now());
        // What the watched movements vouch for; see SeedBox#trustedOf.
        state.getSeedBoxWatchedNet().merge(movedId, moved, (was, change) -> Math.max(0, was + change));
        state.getSeedBoxWatchedNet().computeIfPresent(movedId, (id, net) -> net > 0 ? net : null);
    }

    /**
     * Merges deposit-box deposits into the existing bank state. A deposit box does not show
     * the bank, so the items that left the inventory are added to the last known bank. The
     * next real bank open corrects it.
     */
    public static void applyDepositInference(PlayerState state, List<ItemStack> depositedItems) {
        List<ItemStack> bank = new ArrayList<>(state.getBank());
        for (ItemStack deposited : depositedItems) {
            addStack(bank, deposited);
        }
        state.setBank(bank);
    }

    public static void applyEquipmentChanged(PlayerState state, Map<EquipmentSlot, ItemStack> equipment) {
        state.getEquipment().clear();
        state.getEquipment().putAll(equipment);
    }

    /**
     * A quest moving on: started or finished by its state, and its stage counter when the
     * quest has one this plugin reads.
     */
    public static void applyQuestProgress(PlayerState state, String questName, QuestStatus status, Integer stage) {
        QuestStatus current = state.getQuests().get(questName);
        if (status == QuestStatus.IN_PROGRESS) {
            if (current == null || current == QuestStatus.NOT_STARTED) {
                state.getQuests().put(questName, QuestStatus.IN_PROGRESS);
            }
        } else if (status == QuestStatus.COMPLETED) {
            state.getQuests().put(questName, QuestStatus.COMPLETED);
        }

        if (stage != null) {
            state.getQuestProgress().put(questName, stage);
        }
    }
}

package com.larryfarming.engine;

import com.larryfarming.data.Tables;
import com.larryfarming.model.*;
import lombok.Value;
import net.runelite.api.gameval.ItemID;

import java.util.*;

/**
 * How many of an item the player has, and where: carried, banked, or in storage they must
 * walk to.
 *
 * <p>Counts the inventory, the worn equipment and the bank, plus every container the farm
 * run cares about outside them: the rune pouch and the seed box travel with the player, so
 * their contents count wherever the container is; the seed vault and the tool leprechaun
 * are storage, so they count toward ownership only.
 *
 * <p>An item matches by id when the id is non-zero, otherwise by case-insensitive name.
 */
public final class ItemCounts {

    private ItemCounts() {
    }

    /**
     * How many of an item the player owns anywhere they can retrieve it from: inventory,
     * equipment, bank, rune pouch, seed box, seed vault or the tool leprechaun.
     */
    public static int countOwned(PlayerState state, int itemId, String itemName) {
        if (state == null || (itemId == 0 && itemName == null)) {
            return 0;
        }
        SideContainerCounts side = sideContainerCounts(state, itemId, itemName);
        return countIn(state.getInventory(), itemId, itemName) + countItemInStorage(state.getEquipment().values(), itemId, itemName)
                + countIn(state.getBank(), itemId, itemName) + side.carried + side.banked + side.stored;
    }

    /**
     * How many of an item the player has <em>on them</em> right now: inventory, worn, or in a
     * carried container such as the rune pouch, as opposed to owning something they would
     * have to fetch.
     */
    public static int countCarried(PlayerState state, int itemId, String itemName) {
        if (state == null || (itemId == 0 && itemName == null)) {
            return 0;
        }
        return countIn(state.getInventory(), itemId, itemName) + countItemInStorage(state.getEquipment().values(), itemId, itemName)
                + sideContainerCounts(state, itemId, itemName).carried;
    }

    /**
     * Whether the tool leprechaun takes this item into storage: the tools, the composts,
     * plant cure, buckets, either secateurs and the bottomless compost bucket.
     */
    public static boolean leprechaunStores(int itemId) {
        return LEPRECHAUN_STORAGE_VARBITS.containsKey(itemId) || itemId == ItemID.SECATEURS || itemId == ItemID.FAIRY_ENCHANTED_SECATEURS
                // The bottomless compost bucket's stored slot has varbits of its own.
                || itemId == ItemID.BOTTOMLESS_COMPOST_BUCKET || itemId == ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED;
    }

    /** Whether the player owns at least one of the item anywhere; see {@link #countOwned}. */
    public static boolean ownsAny(PlayerState state, int itemId) {
        return countOwned(state, itemId, null) > 0;
    }

    /** Whether the player owns at least one of any of these items anywhere. */
    public static boolean ownsAny(PlayerState state, Collection<Integer> itemIds) {
        return itemIds.stream().anyMatch(id -> ownsAny(state, id));
    }

    /** Counts items matching {@code itemId}/{@code itemName} in one container's snapshot. */
    static int countItemInStorage(Collection<ItemStack> storage, int itemId, String itemName) {
        if (storage == null) {
            return 0;
        }
        int total = 0;
        for (ItemStack item : storage) {
            if (itemMatches(item, itemId, itemName)) {
                total += item.getQuantity();
            }
        }
        return total;
    }

    private static boolean itemMatches(ItemStack item, int itemId, String itemName) {
        if (itemId != 0) {
            return item.getItemId() == itemId;
        }
        return itemName.equalsIgnoreCase(item.getName());
    }

    /** The inventory or the bank: loose items plus the contents of filled sacks and baskets. */
    private static int countIn(List<ItemStack> items, int itemId, String itemName) {
        return countItemInStorage(items, itemId, itemName) + countContainerContents(items, itemId);
    }

    /** Whether any of these stacks is one of the items. */
    static boolean holdsAny(Collection<ItemStack> items, Set<Integer> itemIds) {
        if (items == null) {
            return false;
        }
        for (ItemStack item : items) {
            if (item != null && itemIds.contains(item.getItemId())) {
                return true;
            }
        }
        return false;
    }

    // ---------------------------------------------------------------
    // Containers outside the inventory, equipment and bank
    // ---------------------------------------------------------------

    /**
     * One item's holdings across every side container, split by where the count belongs.
     * The buckets are exclusive, so an owned total never double-counts.
     */
    @Value
    private static class SideContainerCounts {
        /** Held in a container that travels, and that container is in the inventory. */
        int carried;
        /** Held in a container that travels, and that container is in the bank. */
        int banked;
        /** Held in storage the player owns and must travel to before use. */
        int stored;

        static final SideContainerCounts NONE = new SideContainerCounts(0, 0, 0);

        static SideContainerCounts of(int carried, int banked, int stored) {
            return (carried | banked | stored) == 0 ? NONE : new SideContainerCounts(carried, banked, stored);
        }
    }

    private static SideContainerCounts sideContainerCounts(PlayerState state, int itemId, String itemName) {
        int carried = 0;
        int banked = 0;
        int stored = 0;

        int pouched = runePouchQuantity(state, itemId);
        if (pouched > 0) {
            if (isPouchCarried(state)) {
                carried += pouched;
            } else if (holdsAny(state.getBank(), RunePouch.POUCH_ITEM_IDS)) {
                banked += pouched;
            }
        }

        // An untrusted seed box tally answers ownership but not "is it on me" (see
        // SeedBox#trustedOf). Under-counting carried seeds costs a needless withdrawal;
        // over-counting sends the player off without seeds to plant.
        int boxed = countItemInStorage(state.getSeedBox(), itemId, itemName);
        if (boxed > 0) {
            int trusted = SeedBox.trustedOf(state, itemId, boxed);
            carried += trusted;
            int unvouched = boxed - trusted;
            if (unvouched > 0 && SeedBox.banked(state)) {
                banked += unvouched;
            } else if (unvouched > 0 && (SeedBox.carried(state) || state.getBankLastSeen() == null)) {
                // Owned, whereabouts unsettled: an unread box in the bag, or a bank never seen.
                // A box absent from both the inventory and a seen bank is gone, seeds and all.
                stored += unvouched;
            }
        }

        stored += countItemInStorage(state.getSeedVault(), itemId, itemName) + countInLeprechaunStorage(state, itemId);

        return SideContainerCounts.of(carried, banked, stored);
    }

    private static int runePouchQuantity(PlayerState state, int itemId) {
        if (itemId == 0) {
            return 0;
        }
        Integer qty = state.getRunePouch().get(itemId);
        return (qty == null || qty <= 0) ? 0 : qty;
    }

    /** True when a rune pouch is in the inventory, or defensively worn. */
    private static boolean isPouchCarried(PlayerState state) {
        return holdsAny(state.getInventory(), RunePouch.POUCH_ITEM_IDS) || holdsAny(state.getEquipment().values(), RunePouch.POUCH_ITEM_IDS);
    }

    // ---------------------------------------------------------------
    // Filled sacks and baskets
    // ---------------------------------------------------------------

    /**
     * Maps a base item to its filled sack or basket variants, whose contents add to the loose
     * count ("Potatoes(10)" contributes 10 potatoes).
     *
     * <p>Variant IDs step by 2 from the container base:
     * {@code containerBaseId + (count - 1) * 2 = variantId}
     */
    @Value
    private static class ContainerType {
        int baseItemId;
        int containerBaseId;
        int maxCount;
    }

    private static final List<ContainerType> CONTAINER_TYPES = containerTypes();

    private static List<ContainerType> containerTypes() {
        List<ContainerType> types = new ArrayList<>();
        for (Tables.Row row : Tables.read("/com/larryfarming/sacks-and-baskets.tsv", 5)) {
            types.add(new ContainerType(row.integer(0), row.integer(2), row.integer(4)));
        }
        return List.copyOf(types);
    }

    private static int countContainerContents(List<ItemStack> items, int itemId) {
        if (itemId == 0) {
            return 0;
        }
        for (ContainerType ct : CONTAINER_TYPES) {
            if (ct.baseItemId != itemId) {
                continue;
            }
            int total = 0;
            int last = ct.containerBaseId + (ct.maxCount - 1) * 2;
            for (ItemStack item : items) {
                int id = item.getItemId();
                if (id >= ct.containerBaseId && id <= last) {
                    int offset = id - ct.containerBaseId;
                    if (offset % 2 == 0) {
                        total += (offset / 2 + 1) * item.getQuantity();
                    }
                }
            }
            return total;
        }
        return 0;
    }

    // ---------------------------------------------------------------
    // Tool leprechaun storage
    // ---------------------------------------------------------------

    /**
     * One slice of a tool-leprechaun stored count: a varbit, and where its value sits in
     * the assembled total.
     *
     * <p>The game holds each slot's count in one to three varbits: one wide field, or a narrow
     * low field in the farming varp plus "extra" varbits that carry the higher bits.
     */
    @Value
    private static class StoredSlice {
        int varbitId;
        /** Bit offset this slice occupies in the assembled total (0 for the low field). */
        int shift;
    }

    /**
     * Maps a farming item ID to the varbit slices holding how many of it the tool leprechaun
     * stores.
     *
     * <p>Varbit IDs are RuneLite's gameval FARMING_TOOLS_*. Each slice's shift is the width of
     * everything below it, and the slices compose to the documented caps: 1000 for supplies,
     * 100 for tools. The table's comments state each low field's width; the next slice's
     * shift equals it.
     */
    private static final Map<Integer, List<StoredSlice>> LEPRECHAUN_STORAGE_VARBITS = leprechaunSlices();

    private static Map<Integer, List<StoredSlice>> leprechaunSlices() {
        Map<Integer, List<StoredSlice>> slices = new HashMap<>();
        for (Tables.Row row : Tables.read("/com/larryfarming/leprechaun-storage.tsv", 5)) {
            slices.computeIfAbsent(row.integer(0), k -> new ArrayList<>()).add(new StoredSlice(row.integer(2), row.integer(4)));
        }
        return slices;
    }

    /**
     * Varbit slices holding the shared secateurs count. Plain and magic secateurs occupy
     * one storage slot between them, so the count alone cannot say which is in it.
     */
    private static final List<StoredSlice> SECATEURS_STORAGE_VARBITS = List.of(new StoredSlice(1438, 0), new StoredSlice(8359, 1));

    /** Which secateurs fill the shared slot: 1 for magic secateurs, 0 for plain. */
    private static final int SECATEURS_TYPE_VARBIT = 1848;

    /**
     * Varbit IDs backing tool-leprechaun storage, read at login so stored items count before
     * the next deposit changes a varbit.
     *
     * <p>Must stay declared below every table it is collected from: a static field initialised
     * from a later one reads null.
     */
    public static final Set<Integer> LEPRECHAUN_STORAGE_VARBIT_IDS = collectLeprechaunVarbitIds();

    private static Set<Integer> collectLeprechaunVarbitIds() {
        Set<Integer> ids = new HashSet<>();
        for (List<StoredSlice> slices : LEPRECHAUN_STORAGE_VARBITS.values()) {
            for (StoredSlice slice : slices) {
                ids.add(slice.getVarbitId());
            }
        }
        for (StoredSlice slice : SECATEURS_STORAGE_VARBITS) {
            ids.add(slice.getVarbitId());
        }
        ids.add(SECATEURS_TYPE_VARBIT);
        return Set.copyOf(ids);
    }

    /**
     * How many of an item the tool leprechaun is holding: 0 for items it does not store, or
     * for no state. Already part of {@link #countOwned}, but a packing list must tell it apart
     * from the bank: a spade at the leprechaun is already waiting at the patch. Storage is per
     * account: every leprechaun opens the same store.
     */
    public static int countInLeprechaunStorage(PlayerState state, int itemId) {
        if (state == null) {
            return 0;
        }
        if (itemId == ItemID.SECATEURS || itemId == ItemID.FAIRY_ENCHANTED_SECATEURS) {
            boolean magicStored = varbitValue(state, SECATEURS_TYPE_VARBIT) == 1;
            if (magicStored != (itemId == ItemID.FAIRY_ENCHANTED_SECATEURS)) {
                return 0;
            }
            return assemble(state, SECATEURS_STORAGE_VARBITS);
        }
        List<StoredSlice> slices = LEPRECHAUN_STORAGE_VARBITS.get(itemId);
        return slices == null ? 0 : assemble(state, slices);
    }

    private static int assemble(PlayerState state, List<StoredSlice> slices) {
        int total = 0;
        for (StoredSlice slice : slices) {
            total += varbitValue(state, slice.getVarbitId()) << slice.getShift();
        }
        return total;
    }

    /** A varbit as a count: unread (absent from the state) and negative read as zero. */
    private static int varbitValue(PlayerState state, int varbitId) {
        Integer value = state.getVarbits().get(varbitId);
        return (value != null && value > 0) ? value : 0;
    }
}

