package com.larryfarming.engine;

import net.runelite.api.gameval.VarbitID;

import java.util.*;
import java.util.function.IntUnaryOperator;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

/**
 * Reads the contents of a rune pouch (or divine rune pouch) from RuneLite varbits.
 *
 * <p>Runes in a pouch leave the inventory item array. Each of the six slots has a TYPE varbit
 * (an index into the {@code RUNEPOUCH_RUNE} enum, {@code 0} = empty) and an aligned QUANTITY
 * varbit, read the same way as RuneLite's {@code RunepouchOverlay}.
 *
 * <p>The caller supplies the index→item-id translation
 * ({@code client.getEnum(EnumID.RUNEPOUCH_RUNE)}), so this class needs no client and runs
 * on a plain lambda.
 */
public final class RunePouch {

    private RunePouch() {
    }

    /** Item IDs that count as a rune pouch occupying an inventory or bank slot. */
    public static final Set<Integer> POUCH_ITEM_IDS = Set.of(
            12791,  // Rune pouch
            24416,  // Rune pouch (Trouver-locked variant)
            27281,  // Divine rune pouch
            27509   // Divine rune pouch (Trouver-locked variant)
    );

    /** Per-slot rune TYPE varbits (index into the RUNEPOUCH_RUNE enum; 0 = empty slot). */
    private static final int[] TYPE_VARBITS = {
            VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
            VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6,
    };

    /** Per-slot rune QUANTITY varbits, index-aligned with {@link #TYPE_VARBITS}. */
    private static final int[] AMOUNT_VARBITS = {
            VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
            VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6,
    };

    /** Varbit IDs whose change means the pouch contents must be re-read. */
    private static final Set<Integer> CONTENT_VARBITS = IntStream.concat(Arrays.stream(TYPE_VARBITS), Arrays.stream(AMOUNT_VARBITS))
            .boxed().collect(Collectors.toUnmodifiableSet());

    public static boolean isContentVarbit(int varbitId) {
        return CONTENT_VARBITS.contains(varbitId);
    }

    /**
     * Reads the current rune pouch contents into a map of rune item ID → total quantity,
     * summing any rune that appears in more than one slot.
     *
     * @param varbitReader      reads a varbit value by ID (e.g. {@code client::getVarbitValue})
     * @param runeIndexToItemId maps a TYPE varbit value (rune index) to its rune item ID, e.g.
     *                          {@code client.getEnum(EnumID.RUNEPOUCH_RUNE)::getIntValue}; may
     *                          return a non-positive value for an unknown index
     * @return empty when the pouch is empty
     */
    public static Map<Integer, Integer> read(IntUnaryOperator varbitReader, IntUnaryOperator runeIndexToItemId) {
        Map<Integer, Integer> contents = new HashMap<>();
        for (int slot = 0; slot < TYPE_VARBITS.length; slot++) {
            int runeIndex = varbitReader.applyAsInt(TYPE_VARBITS[slot]);
            int amount = varbitReader.applyAsInt(AMOUNT_VARBITS[slot]);
            if (runeIndex <= 0 || amount <= 0) {
                continue;
            }
            int itemId = runeIndexToItemId.applyAsInt(runeIndex);
            if (itemId <= 0) {
                continue;
            }
            contents.merge(itemId, amount, Integer::sum);
        }
        return contents;
    }
}

package com.larryfarming.engine;

import java.util.Set;

import com.larryfarming.model.PlayerState;
import net.runelite.api.gameval.ItemID;

/**
 * The Tithe Farm seed box: what counts as one, and where it is.
 *
 * <p>Unlike the tackle box and the seed vault, the seed box is a carried container: seeds in
 * a box in the bag are in the bag. {@code ItemCounts} counts its contents toward
 * wherever the box is, as it does for the rune pouch.
 *
 * <p>The pouch is read from varbits and corrects itself every tick. The game never reports
 * the seed box's contents as a container, so its tally is summed from chat lines and can
 * drift.
 */
public final class SeedBox {

    private SeedBox() {
    }

    /**
     * Closed and open: one item in two states. Open and Close swap the id in place, and a
     * player may own only one box.
     *
     * <p>Named through {@code ItemID} because nearby ids are traps: {@code ItemID.SEEDBOX} is
     * a <em>seed pack</em>, and the box has a bank placeholder id too.
     */
    public static final Set<Integer> BOX_ITEM_IDS = Set.of(ItemID.SEED_BOX, ItemID.SEED_BOX_OPEN);

    /**
     * How many <em>kinds</em> of seed a box holds in its one slot. The wiki has it at "up to
     * 2,147,483,647 seeds of six different types", so only the type count binds.
     */
    public static final int KINDS_HELD = 6;

    /** True when a seed box is in the inventory, or defensively worn. */
    public static boolean carried(PlayerState state) {
        return state != null && (ItemCounts.holdsAny(state.getInventory(), BOX_ITEM_IDS)
                || ItemCounts.holdsAny(state.getEquipment().values(), BOX_ITEM_IDS));
    }

    /**
     * True when the box is in the bag and its tally's kinds are worth counting against the
     * box's six places: the box was listed this session, or seeds were watched moving.
     *
     * <p>Box-wide and loose on purpose. A stale kind wrongly counted costs one loose seed
     * slot, never a seed. {@link #trustedOf} answers how many of one seed count as carried.
     */
    public static boolean contentsCarried(PlayerState state) {
        return carried(state) && (state.getSeedBoxVerifiedAt() != null || state.getSeedBoxWatchedAt() != null);
    }

    /**
     * How many of one seed's tally count as carried: all of it once the whole box was listed
     * this session, otherwise only what was watched going in this session, less what was
     * watched leaving.
     *
     * <p>A tally carried over from an earlier session can hold seeds that left by a route no
     * chat line reported. Counting those as carried skips their withdrawal and sends the
     * player to the patch without them. A watched movement vouches only for what it moved,
     * so it never turns that stale part into carried seeds.
     *
     * @param itemId  the seed asked about, or 0 when only a name is known, which only a full
     *                listing can vouch for
     * @param tallied what the tally holds of it
     */
    public static int trustedOf(PlayerState state, int itemId, int tallied) {
        if (!carried(state) || tallied <= 0) {
            return 0;
        }
        if (state.getSeedBoxVerifiedAt() != null) {
            return tallied;
        }
        return itemId > 0 ? Math.min(tallied, state.getSeedBoxWatchedNet().getOrDefault(itemId, 0)) : 0;
    }

    /**
     * What the box's tally claims it holds of one item, trusted or not.
     *
     * <p>Deliberately ungated: where {@link #trustedOf} vouches for less than the tally, a
     * caller still needs this number to tell "checking the box would find something" from
     * "checking would change nothing".
     */
    public static int tallied(PlayerState state, int itemId) {
        // The name-matching path underneath dereferences the null name when the id is 0.
        return state == null || itemId == 0 ? 0 : ItemCounts.countItemInStorage(state.getSeedBox(), itemId, null);
    }

    /** True when a seed box is sitting in the bank. */
    public static boolean banked(PlayerState state) {
        return state != null && ItemCounts.holdsAny(state.getBank(), BOX_ITEM_IDS);
    }
}

package com.larryfarming.engine;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import lombok.Value;
import net.runelite.api.ChatMessageType;

/**
 * Reads the seed box's chat lines: seeds stored, emptied or planted, and the box's own
 * listing of what it holds.
 *
 * <p>All methods are static and side-effect-free. They parse a line into a result and leave
 * dispatch to the caller.
 */
public final class SeedBoxChat
{
	/**
	 * The seed box announcing that its contents moved, in each of the four wordings it uses.
	 *
	 * <p>The chat text is the only source for these counts: the game never sends the
	 * {@code SEED_BOX} item container, so {@code Client#getItemContainer} always answers null.
	 *
	 * <p>Filling and emptying give an exact item name and a count. Planting straight from the
	 * box gives a lower-case name, singular or plural depending on how many the patch takes.
	 * The emptying line never names the box ("Emptied 1 x Asgarnian seed to your inventory"),
	 * so a match on the box's name would miss it.
	 *
	 * <p>Digits are bounded to nine so a malformed line cannot overflow the parse.
	 */
	private static final Pattern SEED_BOX_STORED = Pattern.compile("^Stored (\\d{1,9}) x (.+?) in your seed box\\.?$",
			Pattern.CASE_INSENSITIVE);
	private static final Pattern SEED_BOX_EMPTIED = Pattern.compile("^Emptied (\\d{1,9}) x (.+?) to your inventory\\.?$",
			Pattern.CASE_INSENSITIVE);
	private static final Pattern SEED_BOX_TAKEN_ONE = Pattern.compile("^An? (.+?) was taken from your seed box\\.?$",
			Pattern.CASE_INSENSITIVE);
	private static final Pattern SEED_BOX_TAKEN_MANY = Pattern.compile("^(\\d{1,9}) (.+?) were taken from your seed box\\.?$",
			Pattern.CASE_INSENSITIVE);

	/**
	 * The box saying it holds nothing: answering Check empty, or emptied into the bank.
	 *
	 * <p>The four patterns above are movements, and a sum of movements cannot correct an
	 * over-count. This line is the box describing itself, so it replaces the tally rather
	 * than adjusting it.
	 *
	 * <p>Checking a box prints its contents to chat. This is one of that listing's two shapes; {@link #SEED_BOX_CONTENTS_HEADER} is
	 * the other. Emptying the box in the bank names no seed, only "Your seed box is now empty.",
	 * so this line is the only sign the seeds left.
	 *
	 * <p>The pattern accepts both "the" and "your"; nothing else in the game says "seed box
	 * is empty".
	 */
	private static final Pattern SEED_BOX_EMPTY = Pattern.compile("^(?:the|your) seed box is (?:now |already )?empty\\.?$", Pattern.CASE_INSENSITIVE);

	/**
	 * The box answering Check with something in it: a header, then one line per seed.
	 *
	 * <pre>
	 * The seed box contains:
	 * 1 x Harralander seed.
	 * 2 x Guam seed.
	 * 1 x Potato cactus seed.
	 * </pre>
	 *
	 * <p>Each line arrives as its own message, so reading the listing needs state across
	 * messages. {@code SeedBoxListing} holds that state.
	 */
	private static final Pattern SEED_BOX_CONTENTS_HEADER = Pattern.compile("^(?:the|your) seed box contains:?$", Pattern.CASE_INSENSITIVE);

	/**
	 * One line of a listing: a count, the separator, and the seed's name.
	 *
	 * <p>Only valid in the lines following a header. The game prints "1 x Harralander seed."
	 * in many places unrelated to a seed box. See {@link #parseSeedBoxContentsEntry}.
	 */
	private static final Pattern SEED_BOX_CONTENTS_ENTRY = Pattern.compile("^(\\d{1,9}) x (.+?)\\.?$", Pattern.CASE_INSENSITIVE);

	private SeedBoxChat()
	{
	}

	/**
	 * Seeds moving into or out of the box, by the game's name for them.
	 *
	 * <p>The name is the game's text, unresolved. Planting from the box reports a lower-case
	 * name that may be plural. The caller resolves it against the candidates it holds, which
	 * for a seed leaving the box are the box's own contents.
	 */
	@Value
	public static class SeedBoxMove
	{
		/** The item as the game named it, which may be lower-case or plural. */
		String itemName;
		/** How many moved: positive into the box, negative out of it. Never zero. */
		int quantity;
	}

	/**
	 * Whether the game's own announcements arrive under this chat type.
	 *
	 * <p>{@code SPAM} is easy to leave out. Jagex files repetitive item handling under it
	 * ("You catch a shrimp"), and every seed box line is {@code SPAM}, so a listener on
	 * {@code GAMEMESSAGE} alone never hears about the box.
	 *
	 * <p>The client raises these events even when the player filters game chat.
	 */
	public static boolean isReadableGameChat(ChatMessageType type)
	{
		return type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.SPAM;
	}

	/**
	 * Seeds moving into or out of a seed box, or empty when the line is about something else.
	 *
	 * <p>Anchored at both ends, so a line that merely mentions a seed box is not mistaken for
	 * an amount. This feeds a running tally with nothing to correct it.
	 *
	 * <p>"Emptied ... to your inventory" does not name the box, so another container's
	 * identically-worded line also matches. The caller narrows it by applying a take only
	 * against seeds the box is known to hold.
	 */
	public static Optional<SeedBoxMove> parseSeedBoxMove(String message)
	{
		if (message == null)
		{
			return Optional.empty();
		}

		Matcher stored = SEED_BOX_STORED.matcher(message);
		if (stored.matches())
		{
			return moveOf(stored.group(2), Integer.parseInt(stored.group(1)));
		}

		Matcher emptied = SEED_BOX_EMPTIED.matcher(message);
		if (emptied.matches())
		{
			return moveOf(emptied.group(2), -Integer.parseInt(emptied.group(1)));
		}

		Matcher takenOne = SEED_BOX_TAKEN_ONE.matcher(message);
		if (takenOne.matches())
		{
			return moveOf(takenOne.group(1), -1);
		}

		Matcher takenMany = SEED_BOX_TAKEN_MANY.matcher(message);
		if (takenMany.matches())
		{
			return moveOf(takenMany.group(2), -Integer.parseInt(takenMany.group(1)));
		}

		return Optional.empty();
	}

	/**
	 * True when the box has just told us it holds nothing.
	 *
	 * <p>Not a move: the caller replaces the tally with zero rather than subtracting, which
	 * corrects an over-count.
	 */
	public static boolean isSeedBoxReportedEmpty(String message)
	{
		return message != null && SEED_BOX_EMPTY.matcher(message).matches();
	}

	/** True when the box has begun listing what it holds; its seeds are the lines after. */
	public static boolean isSeedBoxContentsHeader(String message)
	{
		return message != null && SEED_BOX_CONTENTS_HEADER.matcher(message).matches();
	}

	/**
	 * One seed of a listing, read as a positive amount.
	 *
	 * <p><b>Only meaningful directly after {@link #isSeedBoxContentsHeader}</b> or another
	 * entry. On its own this matches any "2 x Thing." the game prints. The result reuses
	 * {@link SeedBoxMove}, but its quantity is an amount held, not an amount moved.
	 */
	public static Optional<SeedBoxMove> parseSeedBoxContentsEntry(String message)
	{
		if (message == null)
		{
			return Optional.empty();
		}
		Matcher entry = SEED_BOX_CONTENTS_ENTRY.matcher(message);
		return entry.matches() ? moveOf(entry.group(2), Integer.parseInt(entry.group(1))) : Optional.empty();
	}

	/** Empty for a zero quantity, which is not a change. */
	private static Optional<SeedBoxMove> moveOf(String itemName, int quantity)
	{
		return quantity == 0 ? Optional.empty() : Optional.of(new SeedBoxMove(itemName, quantity));
	}
}

package com.larryfarming.engine;

import com.larryfarming.model.ItemStack;
import java.util.*;

/**
 * A Check listing part way through arriving.
 *
 * <p>Checking the seed box prints a header line, then one chat message per seed, and no
 * closing line. {@link SeedBoxChat} stays stateless; the caller owns one of these while a
 * listing is open and drops it when a message arrives that is not an entry.
 *
 * <p><b>The entry wording is not self-identifying.</b> The game prints "2 x Guam seed." in
 * places unrelated to farming, so an entry counts only after the header has been seen.
 */
public final class SeedBoxListing {

    private final List<ItemStack> seeds = new ArrayList<>();
    private int lines;

    /**
     * How many entry lines this listing has printed, named or not.
     *
     * <p>Can exceed the size of {@link #getSeeds} when a name is unknown. A listing whose
     * names we could not place is not an empty box and must not be committed as one.
     */
    public int getLines() {
        return lines;
    }

    /** The seeds read so far, in the order the box listed them. */
    public List<ItemStack> getSeeds() {
        return seeds;
    }

    /**
     * Folds one message into this listing.
     *
     * @param known lower-cased name → item id, as the plugin learns names. A name absent from
     *              it is counted in {@link #getLines} and left out of {@link #getSeeds}:
     *              a missing seed costs a needless withdrawal, an invented one a planting the
     *              player cannot make
     * @return false when the message is not a listing entry, which means the listing has ended
     */
    public static boolean read(String message, SeedBoxListing into, Map<String, Integer> known) {
        Optional<SeedBoxChat.SeedBoxMove> entry = SeedBoxChat.parseSeedBoxContentsEntry(message);
        if (!entry.isPresent()) {
            return false;
        }
        into.lines++;
        String name = entry.get().getItemName();
        Integer itemId = known.get(name.toLowerCase(Locale.ROOT));
        if (itemId != null) {
            into.seeds.add(new ItemStack(itemId, entry.get().getQuantity(), name));
        }
        return true;
    }
}

package com.larryfarming.engine;

import com.larryfarming.engine.farming.*;
import com.larryfarming.model.*;
import com.larryfarming.persistence.StatePersistence;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import java.time.Instant;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Holds the logged-in account's state: the {@link PlayerState} read from game events, and
 * the {@link FarmingTracker} fed by patch scans.
 *
 * <p>Events change the state and mark it dirty. {@link #flushIfDirty()} runs once per game
 * tick and tells the {@link EngineListener} once, so a tick's events share one re-plan.
 *
 * <p>Client thread only.
 */
@Slf4j
public class StateEngine {

    private final StatePersistence persistence;

    @Getter
    private final FarmingTracker farmingTracker = new FarmingTracker();

    /** The logged-in account's state, or null before the first login of the session. */
    @Getter
    private PlayerState playerState;

    /** Hears account loads, varbit changes and flushes; null when nothing listens. */
    private EngineListener listener;

    /** An event changed the state since the last flush. */
    private boolean dirty;

    public StateEngine(StatePersistence persistence) {
        this.persistence = persistence;
    }

    /** Install the one listener, or null to remove it. Set before the first load. */
    public void setListener(EngineListener listener) {
        this.listener = listener;
    }

    /**
     * Load the current RS profile's saved state, replacing whatever the engine held.
     *
     * <p>Runs at every login, not once per client run. The engine outlives a logout, so the
     * account logging in may not be the one that left.
     */
    public void loadPersistedState() {
        clearAccountState();
        // Straight after the clear, so a listener's own per-account state is swapped at the
        // same moment as the engine's and is loaded before the announcement at the end.
        if (listener != null) {
            listener.accountLoading();
        }

        playerState = persistence.loadPlayerState();

        int[] farmTickOffset = persistence.loadFarmingTickOffset();
        farmingTracker.loadPersisted(persistence.loadFarmingPatches(), farmTickOffset[0], farmTickOffset[1], farmTickOffset[2]);

        announce();
    }

    /**
     * Forget everything held for the account that played last. Kept: the listener, which
     * clears its own per-account state in {@link EngineListener#accountLoading}.
     */
    private void clearAccountState() {
        playerState = null;
        dirty = false;
        farmingTracker.clear();
    }

    // ---------------------------------------------------------------
    // Events, from the plugin's subscribers
    // ---------------------------------------------------------------

    /** The account as the client reports it at login. Creates the state on a first login. */
    public void onLogin(Map<String, SkillState> skills, List<ItemStack> inventory, Map<EquipmentSlot, ItemStack> equipment) {
        if (playerState == null) {
            playerState = new PlayerState();
        }
        EventApplier.applyLoginState(playerState, skills, inventory, equipment);
        afterEvent();
    }

    public void onStatChanged(String skillName, long xp, int level) {
        change(() -> EventApplier.applyStatChanged(playerState, skillName, xp, level));
    }

    /** Applies a change to the player state, if an account is loaded. */
    private void change(Runnable apply) {
        if (playerState == null) return;
        apply.run();
        afterEvent();
    }

    public void onInventoryChanged(List<ItemStack> items) {
        change(() -> playerState.setInventory(items));
    }

    public void onBankChanged(List<ItemStack> items) {
        change(() -> {
            playerState.setBank(items);
            playerState.setBankLastSeen(Instant.now());
        });
    }

    /**
     * Replaces the tracked seed vault contents. Reported only when the player opens the
     * vault, so like the bank it is a snapshot of the last look, not a live figure.
     */
    public void onSeedVaultChanged(List<ItemStack> items) {
        change(() -> {
            playerState.setSeedVault(items);
            playerState.setSeedVaultLastSeen(Instant.now());
        });
    }

    public void onSeedBoxChanged(List<ItemStack> items) {
        change(() -> {
            // The tally before a listing replaces it shows what drifted, and so which
            // movement went unread.
            log.debug("Seed box listed {}; the tally said {}", tally(items), tally(playerState.getSeedBox()));
            EventApplier.applySeedBoxChanged(playerState, items);
        });
    }

    /** Records seeds the player has put in their seed box. */
    public void onSeedBoxStored(ItemStack stored) {
        change(() -> {
            EventApplier.applySeedBoxStored(playerState, stored);
            log.debug("Seed box stored {} x {}; tally now {}", stored.getQuantity(), stored.getName(), tally(playerState.getSeedBox()));
        });
    }

    /** "3 x Guam seed, 1 x Whiteberry seed", for the seed box debug lines. */
    private static String tally(List<ItemStack> box) {
        return box.isEmpty() ? "nothing"
                : box.stream().map(stack -> stack.getQuantity() + " x " + stack.getName()).collect(Collectors.joining(", "));
    }

    /**
     * Records seeds leaving the seed box, emptied into the bag or planted out of it.
     *
     * @param itemName as the game named it; a name the box is not holding is ignored
     * @param quantity how many left, as a positive number
     */
    public void onSeedBoxTaken(String itemName, int quantity) {
        change(() -> {
            EventApplier.applySeedBoxTaken(playerState, itemName, quantity);
            log.debug("Seed box gave up {} x {}; tally now {}", quantity, itemName, tally(playerState.getSeedBox()));
        });
    }

    /** The rune pouch contents (rune item ID → quantity), read from the pouch varbits. */
    public void onRunePouchChanged(Map<Integer, Integer> contents) {
        change(() -> playerState.setRunePouch(contents));
    }

    /** Called when items leave the inventory while a deposit box is open. */
    public void onDepositInferred(List<ItemStack> depositedItems) {
        change(() -> EventApplier.applyDepositInference(playerState, depositedItems));
    }

    public void onEquipmentChanged(Map<EquipmentSlot, ItemStack> equipment) {
        change(() -> EventApplier.applyEquipmentChanged(playerState, equipment));
    }

    /**
     * A quest started or finished, or a tracked quest's stage counter moved.
     *
     * @param status the quest's state now, or null when only the stage is reported
     * @param stage  the stage counter, or null for a quest whose stage is not read
     */
    public void onQuestProgress(String questName, QuestStatus status, Integer stage) {
        change(() -> EventApplier.applyQuestProgress(playerState, questName, status, stage));
    }

    public void onRegionChanged(int newRegionId) {
        change(() -> playerState.setRegionId(newRegionId));
    }

    /** A varbit took a new value. An unchanged value is a no-op. */
    public void onVarbitValueChanged(int varbitId, int value) {
        if (playerState == null) return;
        Integer prev = playerState.getVarbits().get(varbitId);
        if (prev != null && prev == value) return;
        playerState.getVarbits().put(varbitId, value);
        if (listener != null) {
            listener.varbitChanged(varbitId, value);
        }
        afterEvent();
    }

    /**
     * Fold live patch varbit values for one farming region into the tracker. Called per
     * game tick while the player stands in a tracked region, because the transmit varbits
     * are valid only near the patches. Persists immediately on change so offline growth
     * survives a crash.
     *
     * <p>Marks nothing dirty: the plan reads the tracker through at its next rebuild.
     */
    public void updateFarming(FarmingWorldMap.RegionDef region, Map<Integer, Integer> varbitValues,
                              boolean allowOffsetLearning, long nowEpochSec) {
        if (farmingTracker.observeRegion(region, varbitValues, allowOffsetLearning, nowEpochSec)) {
            persistence.saveFarmingPatches(farmingTracker.exportForPersist());
        }
        if (farmingTracker.consumeOffsetDirty()) {
            persistence.saveFarmingTickOffset(farmingTracker.getTickOffsetSeconds(), farmingTracker.getTickOffsetPrecisionMins(),
                    farmingTracker.getTickOffsetResolutionSeconds());
        }
    }

    // ---------------------------------------------------------------
    // Flushing and saving
    // ---------------------------------------------------------------

    /**
     * Mark the state changed after a bulk write straight into the player state, such as the
     * login varbit scan.
     */
    public void triggerResolve() {
        afterEvent();
    }

    /**
     * Ask for a re-plan at the next flush without changing the state: a game var moved that
     * the plan does not read. The plan's "ready in" lines are worked out when it is built, so
     * re-planning as the game moves keeps them current.
     */
    public void markStale() {
        dirty = true;
    }

    /** Tell the listener once if any event changed the state since the last flush. */
    public void flushIfDirty() {
        if (dirty) {
            announce();
        }
    }

    /** Save the player state if it changed and the debounce allows. Call once per tick. */
    public void tickSave() {
        persistence.saveIfNeeded(playerState);
    }

    /** Save the player state now. Call at logout and shutdown. */
    public void forceSave() {
        persistence.forceSave(playerState);
    }

    private void afterEvent() {
        persistence.markDirty();
        dirty = true;
    }

    private void announce() {
        dirty = false;
        if (listener != null) {
            listener.stateChanged();
        }
    }
}

package com.larryfarming.engine.farming;

import com.larryfarming.data.Tables;
import java.util.ArrayList;
import java.util.List;

/**
 * Decodes the farming contract varbit (7963) to the {@link Crop} the contract asks for.
 *
 * <p>The varbit values match RuneLite's Time Tracking {@code Produce} table, which decodes the
 * same varbit. The varbit arrives at login, so the crop is known without talking to
 * Guildmaster Jane.
 */
public final class ContractProduce {

    /** Indexed by varbit value; 0 is the empty contract slot. */
    private static final List<Crop> BY_VARBIT_VALUE = load();

    /** The table lists every value from 1 in order, so a missing or out-of-order value fails at load. */
    private static List<Crop> load() {
        List<Crop> crops = new ArrayList<>();
        crops.add(null);
        for (Tables.Row row : Tables.read("/com/larryfarming/contract-produce.tsv", 2)) {
            if (row.integer(0) != crops.size()) {
                throw row.error("expected value " + crops.size());
            }
            crops.add(row.constant(Crop.class, 1));
        }
        return crops;
    }

    private ContractProduce() {
    }

    /**
     * The crop a contract varbit value names.
     *
     * @return the crop, or null for the empty slot (0) and for a value the table does not
     *     know, so a new contract tier is never read as the wrong crop
     */
    public static Crop byVarbitValue(int value) {
        return value > 0 && value < BY_VARBIT_VALUE.size() ? BY_VARBIT_VALUE.get(value) : null;
    }
}

