package com.larryfarming.engine.farming;

import com.larryfarming.data.Tables;
import java.util.EnumSet;
import java.util.Set;
import lombok.Getter;

/**
 * A crop that can occupy a tracked farming patch: every plantable species across
 * all patch types (allotment, flower, bush, hops, herb, tree, fruit tree, cactus,
 * hardwood, anima, coral, and the one-off special patches), plus WEEDS (the
 * unplanted state) and ANYHERB (the game collapses all dead herbs into one varbit
 * range, so the species is unknowable).
 *
 * <p>Growth constants mirror RuneLite's Time Tracking {@code Produce} table and come from
 * the crops table, one row per constant: a crop advances one growth stage per farming
 * tick and finishes growing after {@code (stages - 1) * tickRateMinutes} minutes. Once
 * HARVESTABLE, some patch types (bushes, fruit trees, cacti, and a few specials) keep
 * producing: they hold {@code harvestStages} pickings and regrow one every
 * {@code regrowTickRateMinutes} minutes. A {@code regrowTickRateMinutes} of 0 means the
 * crop does not regrow. The item ID is only used for the sidebar row icon.
 */
@Getter
public enum Crop {
    /** Tick rate 0: weeds regrow, but a weedy patch has no timer worth showing. */
    WEEDS,

    // Allotment crops.
    POTATO,
    ONION,
    CABBAGE,
    TOMATO,
    SWEETCORN,
    STRAWBERRY,
    WATERMELON,
    SNAPE_GRASS,

    // Flower crops.
    MARIGOLD,
    ROSEMARY,
    NASTURTIUM,
    WOAD,
    LIMPWURT,
    WHITE_LILY,
    /** Occupies the flower patch; guards the adjacent allotments rather than being harvested. */
    SCARECROW,

    // Bush crops.
    REDBERRIES,
    CADAVABERRIES,
    DWELLBERRIES,
    JANGERBERRIES,
    WHITEBERRIES,
    POISON_IVY,

    // Hop crops.
    BARLEY,
    HAMMERSTONE,
    ASGARNIAN,
    JUTE,
    YANILLIAN,
    FLAX,
    KRANDORIAN,
    WILDBLOOD,
    HEMP,
    COTTON,

    // Herbs, in patch-varbit order.
    GUAM,
    MARRENTILL,
    TARROMIN,
    HARRALANDER,
    RANARR,
    TOADFLAX,
    IRIT,
    AVANTOE,
    HUASCA,
    KWUARM,
    SNAPDRAGON,
    CADANTINE,
    LANTADYME,
    DWARF_WEED,
    TORSTOL,
    GOUTWEED,
    /** Dead herbs share one varbit range; the species is lost. */
    ANYHERB,

    // Trees.
    OAK,
    WILLOW,
    MAPLE,
    YEW,
    MAGIC,

    // Fruit trees.
    APPLE,
    BANANA,
    ORANGE,
    CURRY,
    PINEAPPLE,
    PAPAYA,
    PALM,
    DRAGONFRUIT,

    // Cactus.
    CACTUS,
    POTATO_CACTUS,

    // Hardwood trees.
    TEAK,
    MAHOGANY,
    CAMPHOR,
    IRONWOOD,
    ROSEWOOD,

    // Anima.
    ATTAS,
    IASOR,
    KRONOS,

    // Coral (Sailing).
    ELKHORN_CORAL,
    PILLAR_CORAL,
    UMBRAL_CORAL,

    // Special single-patch crops.
    SEAWEED,
    GRAPE,
    MUSHROOM,
    BELLADONNA,
    CALQUAT,
    SPIRIT_TREE,
    CELASTRUS,
    REDWOOD,
    HESPORI,
    CRYSTAL_TREE,

    // Compost bins. The empty-bin entries stand in for Time Tracking's EMPTY state and are
    // never timed.
    EMPTY_COMPOST_BIN,
    COMPOST,
    SUPERCOMPOST,
    ULTRACOMPOST,
    ROTTEN_TOMATO,
    EMPTY_BIG_COMPOST_BIN,
    BIG_COMPOST,
    BIG_SUPERCOMPOST,
    BIG_ULTRACOMPOST,
    BIG_ROTTEN_TOMATO;

    static {
        Rows.TABLE.requireAll(values());
    }

    private final String displayName;
    private final int itemId;
    private final int tickRateMinutes;
    private final int stages;
    /** Minutes between regrown pickings while HARVESTABLE; 0 if the crop does not regrow. */
    private final int regrowTickRateMinutes;
    /** Number of harvest "lives" (berry/fruit pickings) once the crop is HARVESTABLE. */
    private final int harvestStages;

    Crop() {
        Tables.Row row = Rows.TABLE.of(name());
        this.displayName = row.text(1);
        this.itemId = row.integer(2);
        this.tickRateMinutes = row.integer(4);
        this.stages = row.integer(5);
        this.regrowTickRateMinutes = row.integer(6);
        this.harvestStages = row.integer(7);
    }

    /** The crops table, held apart so the constructors can read it; see {@link Tables#byName}. */
    private static final class Rows {
        static final Tables.Named TABLE = Tables.byName("/com/larryfarming/crops.tsv", 8);
    }

    /** Total wall-clock grow time from planting to done, in seconds. */
    public long totalGrowSeconds() {
        return (long) (stages - 1) * tickRateMinutes * 60L;
    }

    /**
     * Whether there is ever anything on this to pick.
     *
     * <p>False for everything that occupies a patch without producing: scarecrow, anima
     * plants, spirit tree, empty compost bins, weeds, and the unknown dead herb. None of
     * these has a HARVESTABLE value in {@link PatchType}.
     *
     * <p>Coral is produce although it has no HARVESTABLE value either: the game reports
     * grown coral as its last growing stage, and the player collects it there.
     *
     * <p>The tracker never predicts a crop forward into HARVESTABLE, so an expired timer is
     * the only "ready" signal a stale patch gives. A scarecrow's timer expires exactly like
     * a herb's, and this method tells the two apart.
     */
    public boolean isProduce() {
        return !NEVER_PICKED.contains(this);
    }

    private static final Set<Crop> NEVER_PICKED = EnumSet.of(WEEDS, ANYHERB, SCARECROW, SPIRIT_TREE, ATTAS, IASOR, KRONOS,
            EMPTY_COMPOST_BIN, EMPTY_BIG_COMPOST_BIN);

    /** The crop a saved setting names, or null when it is unset or no crop carries the name. */
    public static Crop named(String name) {
        if (name == null) {
            return null;
        }
        try {
            return valueOf(name);
        } catch (IllegalArgumentException ex) {
            return null;
        }
    }
}

package com.larryfarming.engine.farming;

/**
 * Health/lifecycle state of a farming patch, decoded from its transmit varbit.
 *
 * <p>DISEASED and DEAD are only ever set from a direct observation — the game
 * transmits patch varbits only while the player is near the patch, so a patch
 * last seen GROWING is predicted straight to harvest and any disease that
 * struck while unobserved stays invisible until the player next walks by.
 * This mirrors RuneLite's Time Tracking plugin, which never simulates disease.
 */
public enum CropState {
    GROWING,
    HARVESTABLE,
    DISEASED,
    DEAD,
    /** Compost bin being filled — an idle state with no timer, like a weedy patch. */
    FILLING,
    /** Compost bin standing empty — likewise idle. */
    EMPTY;
}

package com.larryfarming.engine.farming;

import lombok.AllArgsConstructor;
import lombok.Getter;

/**
 * The decoded meaning of a farming-patch transmit varbit: which crop occupies
 * the patch, its health/lifecycle {@link CropState}, and how far it has grown.
 *
 * <p>Immutable value object produced by {@link PatchType#decode(int)}. The stage
 * is the raw growth index the game reports for the current state — for GROWING it
 * counts up from 0 to {@code stages - 1}; for DISEASED/DEAD it is the game's 1-based
 * progression through that state. Callers that only care about "how grown" should
 * read {@link #getState()} first, since the stage number means different things
 * per state.
 *
 * <p>The HARVESTABLE stage has no single direction across decoders. A crop that restocks
 * (fruit trees, bushes, allotments) counts <em>up</em> toward {@code getStages() - 1}: the
 * stage is how much produce is on the plant, and a picked-clean fruit tree reads 0 of 7. A
 * crop picked a fixed number of times (herbs, hops) counts the remaining lives
 * <em>down</em>. {@link PatchPrediction#readinessAt} and {@code FarmingTracker.stagesRemain}
 * assume the count-up reading, so a caller building one of these by hand must use it too:
 * a picked fruit tree written at a full stage reads back as ready.
 */
@Getter
@AllArgsConstructor
public final class DecodedPatch {

    private final Crop crop;
    private final CropState state;
    private final int stage;
    /**
     * Whether a tree is still standing in this patch, as opposed to its stump or bare
     * ground.
     *
     * <p>{@link CropState} cannot say this. The game gives a checked tree ("Chop down") and
     * its stump ("Clear") different varbit values, but both decode to HARVESTABLE stage 0
     * because neither carries a timer. A standing tree must be felled before the patch can
     * take the next sapling.
     *
     * <p>True exactly where the patch object offers "Chop down": a checked regular or
     * hardwood tree, and a fruit tree at any point in its bearing life. False for the
     * stumps, for a redwood — which is cleared with a spade rather than felled — and for
     * everything that is not a tree.
     */
    private final boolean fellable;

    /**
     * Number of stages for the current state: harvest "lives" once HARVESTABLE
     * (regrowing crops cycle through these), otherwise the growth stage count.
     */
    public int getStages() {
        return state == CropState.HARVESTABLE ? crop.getHarvestStages() : crop.getStages();
    }

    /**
     * Minutes per tick while the patch still advances; 0 = no timer. GROWING
     * counts down the grow tick rate; HARVESTABLE counts the regrow tick rate
     * (0 for crops that are picked once and never regrow); DISEASED, DEAD, and
     * the idle bin states (FILLING/EMPTY) never tick.
     */
    public int tickRateMinutes() {
        switch (state) {
            case GROWING:
                return crop.getTickRateMinutes();
            case HARVESTABLE:
                return crop.getRegrowTickRateMinutes();
            default:
                return 0;
        }
    }

    /**
     * True when nothing is effectively in progress at the patch: weeds, or a
     * compost bin standing empty or still being filled. Idle patches carry no
     * timer and are hidden from the timer displays, exactly like unplanted soil.
     */
    public boolean isIdle() {
        return crop == Crop.WEEDS || state == CropState.FILLING || state == CropState.EMPTY;
    }
}

package com.larryfarming.engine.farming;

import java.util.*;
import lombok.Value;

/**
 * Holds one tick's patch scan until the next tick shows the player still among the patch
 * clusters it was read under.
 *
 * <p>Transmit varbits can lead the player's move: on the Ardougne cloak teleport from
 * Hosidius to the Monastery, the game sends the Monastery's values a tick before it moves
 * the player. A scan on that tick would record the Monastery bush's value on the Hosidius
 * north-east allotment and read the planted herb and flower patches as weeds (RuneLite's
 * Time Tracking makes the same mistake). The two-tick gate on region entry cannot catch
 * this, because the player has not moved yet. One tick is the lead on that teleport; other
 * teleports may differ.
 *
 * <p>Clusters, not map region ids, are compared: some varbits change meaning on a stair
 * climb or across a bounds line inside one map region (Catherby's fruit tree upstairs,
 * Fossil Island's ladders), and one cluster can span several map regions.
 */
public final class FarmingScanHold {

    /** One region's varbit values, read on one tick. Takes ownership of {@code values}. */
    @Value
    public static class Scan {
        FarmingWorldMap.RegionDef region;
        Map<Integer, Integer> values;
        boolean allowOffsetLearning;
        long observedAtEpochSec;
    }

    private Set<FarmingWorldMap.RegionDef> heldUnder = Set.of();
    private List<Scan> held = List.of();
    private boolean dropped;

    /** Holds this tick's scans, read while the player stood among {@code clusters}. */
    public void hold(Set<FarmingWorldMap.RegionDef> clusters, List<Scan> scans) {
        heldUnder = Set.copyOf(clusters);
        held = List.copyOf(scans);
    }

    /**
     * Releases the held scans if the player still stands among the clusters they were read
     * under, and drops them otherwise. Either way nothing stays held.
     *
     * @param clustersNow the clusters whose bounds hold the player this tick
     */
    public List<Scan> release(Set<FarmingWorldMap.RegionDef> clustersNow) {
        boolean keep = clustersNow.equals(heldUnder);
        List<Scan> scans = keep ? held : List.of();
        dropped = !keep && !held.isEmpty();
        clear();
        return scans;
    }

    /**
     * Whether the last {@link #release} threw a scan away. The next scan applied then follows
     * a gap, so it must not learn the farm-tick offset.
     */
    public boolean wasDropped() {
        return dropped;
    }

    public void clear() {
        heldUnder = Set.of();
        held = List.of();
    }
}

