package com.larryfarming.engine.farming;

import com.larryfarming.data.Tables;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Every kind of farming patch the plugin tracks, and the table that turns a patch's
 * transmit-varbit byte into a {@link DecodedPatch}.
 *
 * <p>OSRS encodes the full state of a nearby patch — crop species, health, and
 * growth stage — as a single value in the range 0-255. The mapping is dense and
 * irregular (weed filler ranges, one-off "check health" states, and gaps that
 * decode to nothing), so the authoritative source is RuneLite's Time Tracking
 * plugin ({@code PatchImplementation}); every boundary in {@code patch-states.tsv}
 * is transcribed from its per-type {@code forVarbitValue} case.
 *
 * <p>Declaration order is the order {@link FarmingWorldMap#allPatches()} groups patches in.
 */
@Getter
@RequiredArgsConstructor
public enum PatchType {
    HERB(false),
    TREE(true),
    HARDWOOD_TREE(true),
    ALLOTMENT(false),
    FLOWER(false),
    HOPS(false),
    BUSH(true),
    FRUIT_TREE(true),
    SEAWEED(false),
    CACTUS(true),
    MUSHROOM(false),
    BELLADONNA(false),
    CALQUAT(true),
    CELASTRUS(true),
    REDWOOD(true),
    CRYSTAL_TREE(true),
    SPIRIT_TREE(true),
    HESPORI(true),
    ANIMA(false),
    GRAPES(true),
    CORAL(false),
    COMPOST(true),
    BIG_COMPOST(true);

    private static final int VALUES = 256;

    /** Each type's 256 decoded states, by ordinal; a null slot decodes to nothing. */
    private static final DecodedPatch[][] STATES = loadStates();

    /**
     * Whether harvest needs a Check-health click first. For such patches the
     * check-health state decodes as GROWING at the crop's max stage.
     */
    private final boolean healthCheckRequired;

    /** Decode a patch transmit-varbit byte; null when the value is not a known state. */
    public DecodedPatch decode(int varbitValue) {
        return varbitValue < 0 || varbitValue >= VALUES ? null : STATES[ordinal()][varbitValue];
    }

    /**
     * Expands {@code patch-states.tsv}: each row gives values {@code lo..hi} of one type a
     * crop, a state and whether a tree stands there, with the stage at value {@code v} being
     * {@code stage + step * (v - lo)}.
     */
    private static DecodedPatch[][] loadStates() {
        DecodedPatch[][] states = new DecodedPatch[values().length][VALUES];
        for (Tables.Row row : Tables.read("/com/larryfarming/patch-states.tsv", 8)) {
            DecodedPatch[] into = states[row.constant(PatchType.class, 0).ordinal()];
            int lo = row.integer(1);
            int hi = row.integer(2);
            if (lo < 0 || hi >= VALUES || lo > hi) {
                throw row.error("values " + lo + ".." + hi + " are not within 0-255");
            }
            Crop crop = row.constant(Crop.class, 3);
            CropState state = row.constant(CropState.class, 4);
            int stage = row.integer(5);
            int step = row.integer(6);
            boolean fellable = row.flag(7, "fell");
            for (int v = lo; v <= hi; v++) {
                if (into[v] != null) {
                    throw row.error("value " + v + " is already decoded by an earlier row");
                }
                into[v] = new DecodedPatch(crop, state, stage + step * (v - lo), fellable);
            }
        }
        return states;
    }
}

package com.larryfarming.farming;

import com.larryfarming.engine.StateEngine;
import com.larryfarming.engine.EngineListener;
import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.detection.*;
import com.larryfarming.farming.engine.*;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.*;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import java.time.Instant;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Plans the farm runs for the account the {@link StateEngine} holds, and publishes the advice
 * the side panel and the advisor infobox draw.
 *
 * <p>Owns everything the plan needs beyond the engine's player state and patch tracker: the
 * crop settings, the day's spent teleports, the contract crop, what the house was seen to
 * hold and the previewed spellbook.
 *
 * <p>Listens to the engine, so the plan is rebuilt whenever the account's state changes, on
 * the same thread. Its own inputs only mark it dirty, and {@link #flushIfDirty()} rebuilds
 * once per tick. A rebuild that comes out equal to the last advice publishes nothing, so a
 * quiet tick leaves the panel alone.
 *
 * <p>Client thread only, apart from {@link #getAdvice()}, which reads a volatile field.
 */
@Slf4j
public class FarmingPlanner implements EngineListener {

    /** Builds the advice from the player state and planner inputs. */
    @FunctionalInterface
    interface Advisor {
        FarmingAdvice advise(PlayerState state, FarmingInputs inputs, long nowEpochSec);
    }

    /** The daily-teleport varbits the game reports, keyed for lookup on every varbit change. */
    private static final Map<Integer, Capability> DAILY_TELEPORT_VARBITS = CapabilitySources.dailyUsesCapabilitiesByVarbit();

    /**
     * A run this close is not worth a dedicated wake-up rebuild; the next event will
     * surface it anyway.
     */
    private static final long WAKE_FLOOR_SECONDS = 5L;

    private final StateEngine engine;
    private final FarmingPlannerPersistence persistence;
    private final Advisor advisor;

    /**
     * Which crops the player is willing to have suggested, as ticked in the panel's settings.
     *
     * <p>Starts at the defaults, so a planner built before the plugin reads its config plans
     * the default runs. The value is swapped whole.
     */
    private volatile FarmingPreferences preferences = FarmingPreferences.defaults();

    /**
     * How many of today's rationed teleports the player has spent (Explorer's ring cabbage
     * patch, Ardougne cloak farm patch), so a route used up today is not offered again. See
     * {@link DailyTeleportLedger} for the counting rules.
     */
    @Getter
    private final DailyTeleportLedger dailyTeleportLedger = new DailyTeleportLedger();

    /** The teleport spent on the way to the next stop, which that stop then reads as paid. */
    private final TravelWatch travelWatch = new TravelWatch();

    /** A seed going into the ground before the patch shows it, which holds the plan. */
    private final PlantingWatch plantingWatch = new PlantingWatch();

    /** A book the player asked to see the farm run planned for, or null for their own. */
    private Spellbook spellbookPreview;

    /** The panel's optional banks are switched off, so no withdrawal is listed at one. */
    private boolean offeredBanksHidden;

    /**
     * What Larry asked for that has been in this account's bag this trip, and the bag's low
     * marks: state no setting holds.
     */
    private DepositPlanner.TripRecord tripRecord = DepositPlanner.TripRecord.EMPTY;

    /** What the contract asks for, or null while the contract slot is empty. */
    @Getter
    private Crop contractCrop;

    /** What the player's own house was last seen to hold. Saved on every change. */
    @Getter
    private HouseSight house = HouseSight.unseen();

    /** The best compost step the account has reached, or null before one is saved. Saved on every change. */
    private Crop compostStep;

    /** Whether compost upkeep was last on, or null before it is decided. Saved on every change. */
    private Boolean compostUpkeep;

    /** What the bottomless bucket was last read holding, or null when never read. Saved on every change. */
    private BottomlessBucket.Reading bucketReading;

    /** Whether a compost threshold moved since the thermostat last decided, so it decides even mid-trip. */
    private boolean thresholdMoved;

    /**
     * The next second at which a farming run comes ready, or zero when none is waiting.
     * Set from each rebuild and consumed by {@link #flushIfDirty()}.
     */
    private long wakeAtEpochSec;

    /** An input changed since the last rebuild. */
    private boolean dirty;

    /**
     * The farm run as last planned, or null when there is nothing to plan for. Volatile: the
     * infobox reads it while rendering, so it is safe from any thread.
     */
    @Getter
    private volatile FarmingAdvice advice;

    /** Moves forward by one each time {@link #advice} changes, and never goes back. */
    @Getter
    private long adviceVersion;


    private FarmingPlanner(StateEngine engine, FarmingPlannerPersistence persistence, Advisor advisor) {
        this.engine = engine;
        this.persistence = persistence;
        this.advisor = advisor;
    }

    /**
     * A planner listening to {@code engine} and hiding the patches its settings switch off.
     * Attach before the engine's first load, so that load's rebuild is planned.
     */
    public static FarmingPlanner attachTo(StateEngine engine, FarmingPlannerPersistence persistence) {
        return attachTo(engine, persistence, FarmingAdviceBuilder::forPlayer);
    }

    static FarmingPlanner attachTo(StateEngine engine, FarmingPlannerPersistence persistence, Advisor advisor) {
        FarmingPlanner planner = new FarmingPlanner(engine, persistence, advisor);
        engine.setListener(planner);
        return planner;
    }

    // ---------------------------------------------------------------
    // Engine events
    // ---------------------------------------------------------------

    /** The account is changing: forget the last one's state and load the next one's. */
    @Override
    public void accountLoading() {
        clearAccountState();
        loadPersistedState();
    }

    /**
     * Feeds a live varbit change into {@link #dailyTeleportLedger} when the game uses that
     * varbit to count spent teleports. The game's count replaces the ledger's, because it
     * stays right across time the plugin was not watching.
     */
    @Override
    public void varbitChanged(int varbitId, int value) {
        Capability capability = DAILY_TELEPORT_VARBITS.get(varbitId);
        if (capability == null) {
            return;
        }
        dailyTeleportLedger.observeUsesSpent(capability, value, now());
        saveDailyTeleportLedger();
    }

    @Override
    public void stateChanged() {
        // A seed on its way into the ground: the plan on screen still counts it, and one
        // built now would send the player back to the bank for another.
        if (plantingWatch.holding()) {
            dirty = true;
            return;
        }
        rebuild(now());
    }

    /**
     * Forget everything held for the account that played last.
     *
     * <p>Kept across logins: the crop settings (client settings), the advice version (the
     * panel needs it to only move forward), and the wiring.
     */
    private void clearAccountState() {
        dailyTeleportLedger.clear();
        travelWatch.clear();
        plantingWatch.clear();
        contractCrop = null;
        house = HouseSight.unseen();
        compostStep = null;
        compostUpkeep = null;
        bucketReading = null;
        // The book this account is not on; another account may be on it.
        spellbookPreview = null;
        tripRecord = DepositPlanner.TripRecord.EMPTY;
        wakeAtEpochSec = 0L;
        dirty = false;
        publish(null);
    }

    /** Read this account's saved planner state. Runs after the clear, never before it. */
    private void loadPersistedState() {
        // The last contract seen, so the panel can name the crop before its varbit is readable.
        contractCrop = persistence.loadFarmingContract();

        house = persistence.loadHouse();
        compostStep = persistence.loadCompostStep();
        compostUpkeep = persistence.loadCompostUpkeep();
        bucketReading = persistence.loadBottomlessBucket();

        FarmingPlannerPersistence.DailyTeleportLedgerState ledgerState = persistence.loadDailyTeleportLedger();
        dailyTeleportLedger.loadPersisted(ledgerState.getDay(), ledgerState.getUsed());
    }

    // ---------------------------------------------------------------
    // Inputs
    // ---------------------------------------------------------------

    /**
     * Take the player's crop settings and plan against them.
     *
     * <p>A no-op when nothing changed, so unrelated settings in the config group do not cost
     * a re-plan. A new compost threshold keeps the thermostat's last decision while the
     * stock is inside the new pair, and decides at once, even mid-trip, outside it.
     */
    public void setPreferences(FarmingPreferences preferences) {
        FarmingPreferences wanted = preferences != null ? preferences : FarmingPreferences.defaults();
        if (wanted.equals(this.preferences)) {
            return;
        }
        thresholdMoved |= wanted.makeCompostBelow() != this.preferences.makeCompostBelow()
                || wanted.stopCompostAt() != this.preferences.stopCompostAt();
        this.preferences = wanted;
        dirty = true;
    }

    /**
     * The player has compost enough for now. The thermostat switches off and saves at once,
     * even mid-trip, and switches back on once the stock falls below "Restock below".
     */
    public void stopCompost() {
        if (!Boolean.FALSE.equals(compostUpkeep)) {
            compostUpkeep = false;
            persistence.saveCompostUpkeep(false);
            dirty = true;
        }
    }

    /**
     * Plan the farm run's teleports for a book the player is not on, because they asked
     * to see it. Null goes back to following the open book.
     *
     * <p>Not persisted, and cleared when the player swaps books.
     */
    public void setSpellbookPreview(Spellbook spellbook) {
        if (spellbookPreview == spellbook) {
            return;
        }
        spellbookPreview = spellbook;
        dirty = true;
    }

    /**
     * Whether the panel draws the banks the route only passes. A bank the player never sees
     * cannot hold a withdrawal, so the switch changes the plan, not just the drawing.
     */
    public void setOfferedBanksShown(boolean shown) {
        if (offeredBanksHidden == !shown) {
            return;
        }
        offeredBanksHidden = !shown;
        dirty = true;
    }

    /**
     * The crop the current farming contract asks for, decoded by the plugin from varbit 7963.
     * Saved on change, so a logout doesn't lose the name.
     *
     * <p>The scheduler needs it to know which guild patch holds the contract. Without it,
     * the guild reports ready whenever anything in it is.
     */
    public void setContractCrop(Crop crop) {
        if (contractCrop == crop) {
            return;
        }
        contractCrop = crop;
        persistence.saveFarmingContract(crop);
        dirty = true;
    }

    /**
     * One complete scan of the player's own house: everything a house feature was found
     * for while it loaded. Replaces the last scan, so furniture taken down reads absent.
     */
    public void houseScanned(Set<HouseFeature> found, long nowEpochSec) {
        observeHouse(house.scanned(found, nowEpochSec));
    }

    /**
     * The Portal Nexus read in full on its teleport menu, in the player's own house.
     * Replaces the attunement, so a destination since removed reads absent.
     */
    public void nexusRead(Set<Integer> destinations, long nowEpochSec) {
        observeHouse(house.nexusRead(destinations, nowEpochSec));
    }

    /**
     * Nexus destinations proven attuned by a slot read anywhere else. Only adds, since a
     * slot reading zero there may not have been sent yet.
     */
    public void nexusAttuned(Collection<Integer> destinations) {
        HouseSight next = house.attuning(destinations);
        if (next != house) {
            observeHouse(next);
        }
    }


    /** The bottomless bucket said what it holds, on a check or a fill. Replaces the last reading. */
    public void bottomlessBucketRead(BottomlessBucket.Reading reading) {
        if (takeBucket(reading)) {
            dirty = true;
        }
    }

    /**
     * Takes and saves a new bucket reading. Marks nothing dirty: the stock count calls it
     * from inside a rebuild.
     *
     * @return whether it differs from the last reading
     */
    private boolean takeBucket(BottomlessBucket.Reading reading) {
        if (reading.equals(bucketReading)) {
            return false;
        }
        bucketReading = reading;
        persistence.saveBottomlessBucket(reading);
        return true;
    }

    /**
     * Counts the compost stock and moves what it decides into the saved state.
     *
     * <p>A bucket stored at the leprechaun gives its reading exactly, so it replaces the last
     * one. While the trip is underway the thermostat keeps its saved state, so a stock that
     * crosses a threshold mid-trip does not add or drop bins, unless the player moved one.
     */
    private CompostStock compostStock(PlayerState state) {
        BottomlessBucket.Reading stored = BottomlessBucket.stored(state);
        if (stored != null) {
            takeBucket(stored);
        }
        CompostStock stock = CompostStock.of(state, compostStep, compostUpkeep, bucketReading, preferences);
        if (stock.getStep() != compostStep) {
            compostStep = stock.getStep();
            persistence.saveCompostStep(compostStep);
        }
        if (compostUpkeep != null && advice != null && advice.isUnderway() && !thresholdMoved) {
            return stock.withOn(compostUpkeep);
        }
        thresholdMoved = false;
        if (stock.isDecided() && !Boolean.valueOf(stock.isOn()).equals(compostUpkeep)) {
            log.debug("Compost upkeep {} at {} uses", stock.isOn() ? "on" : "off", stock.getUses());
            compostUpkeep = stock.isOn();
            persistence.saveCompostUpkeep(compostUpkeep);
        }
        return stock;
    }

    /** Takes and saves a new sight of the house, and re-plans against it. */
    private void observeHouse(HouseSight next) {
        house = next;
        persistence.saveHouse(next);
        dirty = true;
    }

    /**
     * Primes {@link #dailyTeleportLedger} from whatever the login scan already found in the
     * player state's varbits. The scan writes straight into the state, bypassing the engine's
     * varbit events, so this stands in for them. Safe to call every login:
     * {@link DailyTeleportLedger#observeUsesSpent} treats an unchanged value as a no-op.
     */
    public void primeDailyTeleportLedgerFromLogin() {
        PlayerState state = engine.getPlayerState();
        if (state == null || DAILY_TELEPORT_VARBITS.isEmpty()) {
            return;
        }
        long nowSec = now();
        for (Map.Entry<Integer, Capability> entry : DAILY_TELEPORT_VARBITS.entrySet()) {
            Integer value = state.getVarbits().get(entry.getKey());
            if (value != null) {
                dailyTeleportLedger.observeUsesSpent(entry.getValue(), value, nowSec);
            }
        }
        saveDailyTeleportLedger();
    }

    /**
     * Charges one Ardougne farm teleport against the cloak the player actually holds.
     *
     * <p>The counterpart to {@link #varbitChanged} for the rationed route with no
     * readable game counter. Called when {@link ArdougneFarmTeleportWatch} has seen a click
     * land, not when it was made.
     *
     * <p>The tier comes from the diary, because the allowance belongs to the cloak the player
     * owns. A cloak 4 has no daily limit; {@link DailyTeleportLedger#recordUse} treats it as
     * a no-op.
     */
    public void recordArdougneFarmTeleport() {
        PlayerState state = engine.getPlayerState();
        if (state == null) {
            return;
        }
        Capability held = DiaryRewards.bestEarnedTier(Capability.TierFamily.ARDOUGNE_CLOAK, state.getVarbits());
        if (held == null) {
            return;
        }
        dailyTeleportLedger.recordUse(held, now());
        log.debug("Ardougne cloak farm teleport charged against {}", held);
        saveDailyTeleportLedger();
    }

    /** Saves the ledger after a change, and re-plans against it. */
    private void saveDailyTeleportLedger() {
        persistence.saveDailyTeleportLedger(dailyTeleportLedger.exportDay(), dailyTeleportLedger.exportForPersist());
        dirty = true;
    }

    // ---------------------------------------------------------------
    // Planning
    // ---------------------------------------------------------------

    /**
     * Re-plan if an input changed since the last rebuild, or a run came due. Call once per
     * game tick, after the engine's own flush.
     */
    public void flushIfDirty() {
        flushIfDirty(now());
    }

    /** The epoch second now, from the wall clock. */
    private static long now() {
        return Instant.now().getEpochSecond();
    }

    /**
     * One tick of the teleport watch. Call once per game tick, before the engine's flush, so
     * a plan built this tick already knows the teleport is paid.
     */
    public void watchTravel() {
        PlayerState state = engine.getPlayerState();
        FarmingStopAdvice heading = headingStop(advice);
        if (state == null || !travelWatch.tick(state, nameOf(heading), landingOf(heading))) {
            return;
        }
        dirty = true;
        TravelTaken taken = travelWatch.taken();
        if (taken.isNone()) {
            log.debug("Teleport no longer paid for: the stop it was spent for is done");
        } else {
            log.debug("Teleport spent on the way to {}: {}", travelWatch.takenFor(), taken);
        }
    }

    /**
     * One tick of the planting watch. Call once per game tick, before the engine's flush, so
     * the rebuild that flush asks for waits while a seed is going in.
     */
    public void watchPlanting() {
        PlayerState state = engine.getPlayerState();
        if (state == null) {
            return;
        }
        boolean was = plantingWatch.holding();
        if (plantingWatch.tick(state, engine.getFarmingTracker().getChanges())) {
            // The flush after this rebuilds; dirty already says so.
            log.debug("A planting showed or its hold ran out; planning again");
        } else if (!was && plantingWatch.holding()) {
            log.debug("A seed left the bag; holding the plan until the patch shows it");
        }
    }

    private static String nameOf(FarmingStopAdvice stop) {
        return stop == null ? null : stop.getPatchName();
    }

    private static Destination landingOf(FarmingStopAdvice stop) {
        return stop == null || stop.getLanding() == null ? null : Destination.valueOf(stop.getLanding());
    }

    /** The stop this advice sends the player to next, or null for none. */
    private static FarmingStopAdvice headingStop(FarmingAdvice advice) {
        List<FarmingStopAdvice> visits = visits(advice);
        return visits.isEmpty() ? null : visits.get(0);
    }

    /** The patch stops this advice sends the player to, in its order. */
    private static List<FarmingStopAdvice> visits(FarmingAdvice advice) {
        List<FarmingStopAdvice> visits = new ArrayList<>();
        if (advice != null && advice.getStops() != null) {
            for (FarmingStopAdvice stop : advice.getStops()) {
                if (stop.getKind() == FarmingStopAdvice.Kind.PATCH && stop.getOutcome() == FarmingStopAdvice.Outcome.VISIT) {
                    visits.add(stop);
                }
            }
        }
        return visits;
    }

    /** {@link #flushIfDirty()} against a stated second rather than the clock. */
    void flushIfDirty(long nowEpochSec) {
        if (dueForWake(nowEpochSec)) {
            dirty = true;
        }
        if (dirty && !plantingWatch.holding()) {
            rebuild(nowEpochSec);
        }
    }

    /**
     * Whether a farming run has come due purely with the passage of time.
     *
     * <p>Nothing in the game announces a crop finishing, so without this the advisor would
     * learn a run is ready only when some unrelated event next fires.
     *
     * <p>Looks ahead rather than polling: the soonest ready time the scheduler computed is
     * the only future second at which the answer can change. This costs one comparison per
     * tick.
     */
    boolean dueForWake(long nowEpochSec) {
        if (wakeAtEpochSec <= 0 || nowEpochSec < wakeAtEpochSec) {
            return false;
        }
        // Cleared as it fires; the rebuild it triggers arms the next one.
        wakeAtEpochSec = 0L;
        return true;
    }

    /**
     * Plan against the engine's player state as it stands, and publish the result if it
     * differs from the last. With no player state there is nothing to plan, and the last
     * advice stands, as the engine keeps its last snapshot.
     */
    private void rebuild(long nowEpochSec) {
        dirty = false;
        PlayerState state = engine.getPlayerState();
        if (state == null) {
            return;
        }
        // The clock enters the farming layer here and nowhere below it. Everything under
        // the scheduler takes the epoch second as an argument, so the time can be fixed.
        CompostStock compost = compostStock(state);
        FarmingInputs inputs = inputs(nowEpochSec).withCompost(compost);
        FarmingAdvice next = advisor.advise(state, inputs, nowEpochSec);
        // The watch judged its teleport against the stop on screen. A plan that moves on to
        // another stop is judged again now, so the new stop never shows the old one's
        // teleport as paid. This runs before the trip record, which reads the final plan.
        FarmingStopAdvice heading = headingStop(next);
        if (travelWatch.retarget(state, nameOf(heading), landingOf(heading))) {
            log.debug("Teleport no longer paid for: the next stop is {}", nameOf(heading));
            inputs = inputs(nowEpochSec).withCompost(compost);
            next = advisor.advise(state, inputs, nowEpochSec);
        }
        // The trip record reads the advice it feeds. A changed packed set plans once more
        // before publishing, so the next bank's deposits see it at once. One more is enough:
        // the deposits feed no list the record reads.
        DepositPlanner.TripRecord record = DepositPlanner.record(state, next, tripRecord);
        boolean replan = !record.getPacked().equals(tripRecord.getPacked());
        tripRecord = record;
        if (replan) {
            next = advisor.advise(state, inputs.withPackedThisTrip(record.getPacked()), nowEpochSec);
        }
        armWake(next, nowEpochSec);
        publish(next);
    }

    /** Every field of the advice is drawn, so it compares whole. */
    private void publish(FarmingAdvice next) {
        if (Objects.equals(advice, next)) {
            return;
        }
        advice = next;
        adviceVersion++;
    }

    /**
     * What the farm run is planned against beyond the player state: the previewed book, the
     * contract, preferences, the patches' and the house's last-seen contents, what this trip
     * has packed and spent, and the stop the plan on screen heads for.
     *
     * <p>The patch lookup reads through to the tracker, so a run planned mid-tick sees the
     * same patches the timers do.
     */
    private FarmingInputs inputs(long nowSec) {
        FarmingTracker tracker = engine.getFarmingTracker();
        return FarmingInputs.of(spellbookPreview, patch -> {
                    FarmingWorldMap.PatchDef def = patch.resolve();
                    return def != null ? tracker.predict(def, nowSec) : null;
                },
                dailyTeleportLedger,
                nowSec)
                .withContractCrop(contractCrop)
                .withPreferences(preferences)
                .withHouse(house)
                .withOfferedBanksHidden(offeredBanksHidden)
                .withPackedThisTrip(tripRecord.getPacked())
                .withTravelTaken(travelWatch.taken())
                .withAhead(visits(advice).stream().map(FarmingStopAdvice::getArrival).collect(Collectors.toList()));
    }

    /**
     * When to look at the farming runs again, from the advice just built: the soonest
     * moment any waiting run comes ready, or zero when nothing is waiting on a clock.
     */
    void armWake(FarmingAdvice built, long nowEpochSec) {
        wakeAtEpochSec = 0L;
        if (built == null || built.getRuns() == null) {
            return;
        }
        for (FarmingRunStatus run : built.getRuns()) {
            long readyAt = run.getReadyAtEpochSec();
            // Skip anything all but arrived. A patch whose estimate has been overtaken keeps
            // reporting itself due imminently, and waking on it would rebuild every second.
            if (readyAt <= nowEpochSec + WAKE_FLOOR_SECONDS) {
                continue;
            }
            if (wakeAtEpochSec == 0L || readyAt < wakeAtEpochSec) {
                wakeAtEpochSec = readyAt;
            }
        }
    }
}

package com.larryfarming.farming;

import com.larryfarming.LarryConfig;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.detection.*;
import com.larryfarming.farming.model.Capability;
import com.larryfarming.persistence.ConfigStore;

import java.util.*;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

/**
 * What the farm-run planner saves: per RS profile, the farming contract, the day's spent
 * teleports, what the player's house was seen to hold; in regular config, the side
 * panel's display toggles. The crop settings live in their own config keys, read through
 * {@code ConfiguredCrops}.
 *
 * <p>Keys sit in the plugin's config group beside the account state and the settings.
 */
public class FarmingPlannerPersistence {

    private static final String CONFIG_GROUP = LarryConfig.GROUP;

    private static final String KEY_FARMING_CONTRACT = "farmingContract";
    private static final String KEY_DAILY_TELEPORT_PREFIX = "farming.dailyTeleport.";
    private static final String KEY_DAILY_TELEPORT_DAY = "farming.dailyTeleportDay";
    private static final String KEY_HOUSE = "farming.house";
    private static final String KEY_HOUSE_NEXUS = "farming.houseNexus";
    private static final String KEY_COMPOST_UPKEEP = "farming.compostUpkeep";
    private static final String KEY_COMPOST_STEP = "farming.compostStep";
    private static final String KEY_BOTTOMLESS_BUCKET = "farming.bottomlessBucket";

    // The side panel's remembered flags, read through flag(). Regular (non-RS-profile)
    // config keys, readable before login.
    /** Whether the side panel shows the stops the trip is not making. Off when unset. */
    public static final String SHOW_SKIPPED = "farmingShowSkipped";
    /** Whether the side panel draws the banks the route passes. The one flag on when unset. */
    public static final String SHOW_BANKS = "farmingShowBanks";
    /** Whether the side panel's travel fold is open. Shut when unset. */
    public static final String TRAVEL_OPEN = "farmingTravelOpen";
    /** Whether the side panel's settings fold is open. Shut when unset. */
    public static final String SETTINGS_OPEN = "farmingSettingsOpen";
    /** Whether the side panel's house fold is open. Shut when unset. */
    public static final String HOUSE_OPEN = "farmingHouseOpen";

    private final ConfigStore store;

    public FarmingPlannerPersistence(ConfigStore store) {
        this.store = store;
    }

    /** This RS profile's value for {@code key}, or null when unset. */
    private String get(String key) {
        return store.getRSProfileConfiguration(CONFIG_GROUP, key);
    }

    /** Saves {@code value} under {@code key} for this RS profile; null clears the key. */
    private void put(String key, Object value) {
        if (value == null) {
            store.unsetRSProfileConfiguration(CONFIG_GROUP, key);
        } else {
            store.setRSProfileConfiguration(CONFIG_GROUP, key, value.toString());
        }
    }

    /** A saved whole number, or null when unset or malformed. */
    private static Integer parseInt(String stored) {
        try {
            return Integer.parseInt(stored);
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    /**
     * Persist the crop named by the current farming contract, by enum name.
     *
     * <p>Stored so the panel can name the contract before login, when the varbit is not yet
     * readable. A null crop clears the key.
     */
    public void saveFarmingContract(Crop crop) {
        put(KEY_FARMING_CONTRACT, crop != null ? crop.name() : null);
    }

    /** Load the persisted contract crop for the current RS profile, or null if unknown. */
    public Crop loadFarmingContract() {
        // A name no crop carries reads as unknown until the contract varbit is read again.
        return Crop.named(get(KEY_FARMING_CONTRACT));
    }

    /**
     * Persist how many of today's rationed teleports have been spent, per capability,
     * plus the day the counts belong to. Each capability has its own key, so a key no
     * capability names goes unread and leaves the other counts intact.
     *
     * <p>The Ardougne cloak has no usage varbit, so its observed count survives a client
     * restart only through this store. The Explorer's ring is stored the same way, though
     * its varbit corrects the count at login anyway.
     */
    public void saveDailyTeleportLedger(long day, Map<Capability, Integer> usedToday) {
        put(KEY_DAILY_TELEPORT_DAY, day);
        for (Capability capability : Capability.values()) {
            if (capability.isRationedDaily()) {
                Integer spent = usedToday != null ? usedToday.get(capability) : null;
                put(KEY_DAILY_TELEPORT_PREFIX + capability.name(), spent == null || spent == 0 ? null : spent);
            }
        }
    }

    /**
     * Load the persisted daily-teleport ledger. A profile that never saved one returns an
     * empty count map and {@code Long.MIN_VALUE} as the day, which
     * {@link com.larryfarming.farming.engine.DailyTeleportLedger#loadPersisted} reads as "nothing
     * saved yet" and rolls over to today's allowance.
     */
    public DailyTeleportLedgerState loadDailyTeleportLedger() {
        String dayStored = get(KEY_DAILY_TELEPORT_DAY);
        long day;
        try {
            day = dayStored != null ? Long.parseLong(dayStored) : Long.MIN_VALUE;
        } catch (NumberFormatException ex) {
            day = Long.MIN_VALUE;
        }
        Map<Capability, Integer> used = new EnumMap<>(Capability.class);
        for (Capability capability : Capability.values()) {
            // A malformed entry is skipped.
            Integer spent = capability.isRationedDaily() ? parseInt(get(KEY_DAILY_TELEPORT_PREFIX + capability.name())) : null;
            if (spent != null) {
                used.put(capability, spent);
            }
        }
        return new DailyTeleportLedgerState(day, used);
    }

    /**
     * Persist what the player's own house was last seen to hold, as two keys: the last scan
     * as "scannedAtEpochSec:FEATURE,FEATURE" and the Nexus attunement as
     * "readAtEpochSec:key,key", where a read stamp of 0 means only passive reads. A house
     * never seen leaves both keys unset.
     *
     * <p>Features are stored by name. Load skips a name no feature carries and keeps the
     * rest.
     */
    public void saveHouse(HouseSight house) {
        if (house == null || !house.isScanned()) {
            put(KEY_HOUSE, null);
        } else {
            List<String> names = new ArrayList<>();
            for (HouseFeature feature : house.getBuilt()) {
                names.add(feature.name());
            }
            put(KEY_HOUSE, house.getScannedAtEpochSec() + ":" + String.join(",", names));
        }
        if (house == null || (!house.isNexusRead() && house.getAttuned().isEmpty())) {
            put(KEY_HOUSE_NEXUS, null);
        } else {
            List<String> keys = new ArrayList<>();
            for (Integer key : house.getAttuned()) {
                keys.add(key.toString());
            }
            put(KEY_HOUSE_NEXUS, house.getNexusReadAtEpochSec() + ":" + String.join(",", keys));
        }
    }

    /**
     * Load what the current RS profile's house was last seen to hold. A profile with
     * nothing saved, or with a malformed value, reads as a house never seen.
     */
    public HouseSight loadHouse() {
        long scannedAt = 0L;
        Set<HouseFeature> built = EnumSet.noneOf(HouseFeature.class);
        String[] scan = stampAndList(get(KEY_HOUSE));
        // A scan without a real stamp is no scan, so none of its furniture is credited.
        long scanStamp = scan != null ? parseStamp(scan[0]) : -1L;
        if (scanStamp > 0L) {
            scannedAt = scanStamp;
            for (String name : scan[1].split(",")) {
                try {
                    built.add(HouseFeature.valueOf(name));
                } catch (IllegalArgumentException ex) {
                    // A feature dropped since the write, or an empty list.
                }
            }
        }
        long readAt = 0L;
        Set<Integer> attuned = new TreeSet<>();
        String[] nexus = stampAndList(get(KEY_HOUSE_NEXUS));
        long nexusStamp = nexus != null ? parseStamp(nexus[0]) : -1L;
        if (nexusStamp >= 0L) {
            readAt = nexusStamp;
            for (String key : nexus[1].split(",")) {
                // A malformed entry is skipped.
                Integer parsed = parseInt(key);
                if (parsed != null) {
                    attuned.add(parsed);
                }
            }
        }
        return HouseSight.of(built, scannedAt, attuned, readAt);
    }

    /**
     * Persist whether compost upkeep was last on, so the gap between the two thresholds keeps
     * its state across a logout. Null clears the key.
     */
    public void saveCompostUpkeep(Boolean on) {
        put(KEY_COMPOST_UPKEEP, on);
    }

    /** Whether compost upkeep was last on, or null when it has never been decided. */
    public Boolean loadCompostUpkeep() {
        String stored = get(KEY_COMPOST_UPKEEP);
        return stored == null ? null : Boolean.valueOf(stored);
    }

    /** Persist the best compost step the account has reached. Null clears the key. */
    public void saveCompostStep(Crop step) {
        put(KEY_COMPOST_STEP, step);
    }

    /** The best compost step saved, or null when unset or not a compost kind. */
    public Crop loadCompostStep() {
        return compostKind(get(KEY_COMPOST_STEP));
    }

    /** The compost kind a saved name holds, or null when it names no compost kind. */
    private static Crop compostKind(String stored) {
        Crop kind = Crop.named(stored);
        return kind != null && BottomlessBucket.KINDS.contains(kind) ? kind : null;
    }

    /** Persist the bottomless bucket's last reading as "KIND USES". Null clears the key. */
    public void saveBottomlessBucket(BottomlessBucket.Reading reading) {
        put(KEY_BOTTOMLESS_BUCKET, reading != null ? reading.getKind().name() + " " + reading.getUses() : null);
    }

    /** The bucket's last reading, or null when unset or malformed. */
    public BottomlessBucket.Reading loadBottomlessBucket() {
        String[] parts = String.valueOf(get(KEY_BOTTOMLESS_BUCKET)).split(" ");
        Integer uses = parts.length == 2 ? parseInt(parts[1]) : null;
        Crop kind = compostKind(parts[0]);
        return uses != null && uses >= 0 && kind != null ? new BottomlessBucket.Reading(kind, uses) : null;
    }

    /** A saved "stamp:list" split in two, or null when unset or malformed. */
    private static String[] stampAndList(String stored) {
        if (stored == null || stored.isEmpty()) {
            return null;
        }
        String[] parts = stored.split(":", 2);
        return parts.length == 2 ? parts : null;
    }

    /** A saved epoch-second stamp, or -1 when it is not one. */
    private static long parseStamp(String stamp) {
        try {
            long parsed = Long.parseLong(stamp);
            return parsed >= 0L ? parsed : -1L;
        } catch (NumberFormatException ex) {
            return -1L;
        }
    }

    /**
     * What was saved of the daily-teleport ledger: the day the counts belong to, and how
     * many of each rationed capability's allowance were spent that day.
     */
    @lombok.Value
    public static class DailyTeleportLedgerState {
        long day;
        Map<Capability, Integer> used;
    }

    // The panel's display toggles. Regular config, not RS-profile config: each is a display
    // preference, not a fact about an account, so it should not be per-account. The panel is
    // also first drawn in startUp(), before any RS profile exists. None is a @ConfigItem: the
    // controls live on the side panel itself.

    /**
     * Remembers one of the side panel's flags.
     *
     * @param key one of the flag keys above, such as {@link #SHOW_SKIPPED}
     */
    public void saveFlag(String key, boolean on) {
        store.setConfiguration(CONFIG_GROUP, key, Boolean.toString(on));
    }

    /**
     * One of the side panel's remembered flags, off when unset, except {@link #SHOW_BANKS},
     * which is on until the player turns it off.
     *
     * <p>For the banks, an unset key must read as true, so it checks for the literal "false"
     * instead of using {@code Boolean.parseBoolean}, which reads an unset key as false.
     *
     * @param key one of the flag keys above, such as {@link #SHOW_SKIPPED}
     */
    public boolean flag(String key) {
        String saved = store.getConfiguration(CONFIG_GROUP, key);
        return SHOW_BANKS.equals(key) ? !"false".equalsIgnoreCase(saved) : Boolean.parseBoolean(saved);
    }

    /**
     * Hands a panel control its flag's remembered value, and a callback that remembers each
     * change the player makes to it.
     *
     * @param key     one of the flag keys above, such as {@link #SHOW_SKIPPED}
     * @param restore receives the saved value and the saving callback
     */
    public void bindFlag(String key, BiConsumer<Boolean, Consumer<Boolean>> restore) {
        restore.accept(flag(key), on -> saveFlag(key, on));
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.farming.model.*;
import java.util.*;

/**
 * The arrival table: each arrival's seat on the circuit, and how to reach it when more than
 * one patch there is being worked.
 *
 * <p>The seats are the order a farm trip visits places in, authored once over every arrival
 * so a player walks the same learnable circuit each time, on every spellbook. Lunar keeps it
 * too: every Lunar herb stop is a teleport that works from anywhere, and the circuit keeps
 * walked neighbours from other families together. A trip is this order with the arrivals it
 * has no work at removed. The order is fixed; the travel is not.
 *
 * <p>Most arrivals need no combined chain. The exception is an arrival whose landing spots
 * fall between its patches, so the rung closest to one is furthest from the other. Combined
 * chains do not replace the stops' own chains: a trip working one patch still uses that
 * patch's ranking.
 */
public final class Arrivals {

    private Arrivals() {
    }

    /** Every arrival's seat on the one circuit, which every book walks. */
    private static final Map<Arrival, Integer> SEATS = seats(CatalogueLoader.loaded().circuit);

    /** The circuit's seats, refusing an arrival listed twice or never. */
    private static Map<Arrival, Integer> seats(List<Arrival> circuit) {
        Map<Arrival, Integer> seats = new EnumMap<>(Arrival.class);
        for (int i = 0; i < circuit.size(); i++) {
            if (seats.put(circuit.get(i), i) != null) {
                throw new IllegalStateException(circuit.get(i) + " has two seats");
            }
        }
        for (Arrival arrival : Arrival.values()) {
            if (!seats.containsKey(arrival)) {
                throw new IllegalStateException(arrival + " has no seat");
            }
        }
        return Collections.unmodifiableMap(seats);
    }

    /**
     * Where this arrival sits on the circuit. Lower comes first. Seats run 0..n-1 with no
     * gaps, and the table refuses to load if an {@link Arrival} has none.
     */
    public static int seat(Arrival arrival) {
        return SEATS.get(arrival);
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.data.Tables;
import com.larryfarming.farming.model.Capability;
import java.util.*;

/**
 * What a capability means in the inventory: the thing to bring so the route works, one row
 * of the carry items table per capability.
 *
 * <p>Chains name what the player can do ("icy basalt to Weiss"). This table maps that to
 * the item to pack, so the carry list derives from the chosen route.
 *
 * <p>Each line lists every variant and draws one. The sprite names the item as the player
 * looks for it in the bank, while ticking it off must accept any charge tier.
 *
 * <p>Worn items are listed too: an Ardougne cloak left in the bank fails the run as surely
 * as a forgotten spade.
 *
 * <p>Capabilities that are not objects (a quest, a house portal, a spell, the fairy ring
 * network) stay absent, and lookups return null for them.
 */
public final class CarryItems {

    private CarryItems() {
    }

    /** Something to bring, with the sprite to draw for it. */
    public static final class Carry {
        private final int[] itemIds;
        private final String name;

        /**
         * @param itemIds every id that counts as having this, the first being the one drawn;
         *     never empty, since the table refuses a row without ids
         */
        Carry(String name, int... itemIds) {
            this.name = name;
            this.itemIds = itemIds;
        }

        /** The id to draw the line by, by convention the full-charge one. */
        public int getItemId() {
            return itemIds[0];
        }

        /** Every id that satisfies this line, the drawn one included. */
        public int[] getItemIds() {
            return itemIds.clone();
        }

        public String getName() {
            return name;
        }
    }

    private static final Map<Capability, Carry> ITEMS = load();

    /** What to pack for this capability, or null when it is not something you carry. */
    public static Carry forCapability(Capability capability) {
        return ITEMS.get(capability);
    }

    /**
     * The item to draw beside a route taken on this capability rather than cast, or 0 when
     * there is nothing honest to draw: the item packed for it, worn items such as an
     * Ardougne cloak or a Farming cape included, so a route and its bag line draw the same
     * sprite.
     *
     * <p>A capability with no entry draws nothing. Networks such as fairy rings, spirit trees
     * and minecarts have no honest sprite, and a wrong one is worse than none.
     */
    public static int iconFor(Capability capability) {
        Carry carry = ITEMS.get(capability);
        return carry != null ? carry.getItemId() : 0;
    }

    /**
     * Every id of the travel item this id is a form of, every charge tier included, or null
     * when no route packs it.
     */
    public static int[] formsOf(int itemId) {
        for (Carry carry : ITEMS.values()) {
            for (int id : carry.itemIds) {
                if (id == itemId) {
                    return carry.getItemIds();
                }
            }
        }
        return null;
    }

    private static Map<Capability, Carry> load() {
        Map<Capability, Carry> items = new EnumMap<>(Capability.class);
        for (Tables.Row row : Tables.read("/com/larryfarming/carry-items.tsv", 4)) {
            Capability capability = row.constant(Capability.class, 0);
            int[] ids = row.integers(2);
            if (ids.length == 0) {
                throw row.error("no item ids for " + capability);
            }
            if (items.put(capability, new Carry(row.text(1), ids)) != null) {
                throw row.error("a second row for " + capability);
            }
        }
        return Collections.unmodifiableMap(items);
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.data.Tables;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.Skill;
import java.util.*;

/**
 * Reads the stops table: the approaches onto the travel networks, the arrivals in circuit
 * order, and every site with the stop each spellbook works it by.
 *
 * <p>Each line is a verb and its cells. A stop's lines name the {@link RunStop.Builder}
 * method they call ({@code at}, {@code accessGate}, {@code skipIfUnreachable},
 * {@code plants}, ...). A rung line names the {@link TravelOption} it makes ({@code via},
 * {@code to}, {@code swapTo}), and the lines after it until the next rung
 * change that rung ({@code walks}, {@code banks}, {@code fare}, {@code floor}, ...). Rungs
 * under an {@code arrival} line are its combined chain.
 *
 * <p>A requirement is a capability's name, {@code reach:DESTINATION},
 * {@code swap:DESTINATION}, {@code patch:KEY}, {@code zone:ZONE}, an approach's way as
 * {@code @NAME}, or {@code all(...)} and {@code any(...)} over those, comma-separated.
 *
 * <p>The file keeps each ladder as written; {@link Ladders} ranks them here.
 */
final class CatalogueLoader {

    private static final String RESOURCE = "/com/larryfarming/stops.tsv";

    /** The approach whose way is some way to stand at a fairy ring. */
    static final String FAIRY_RING_APPROACH = "RING";

    private static final CatalogueLoader LOADED = new CatalogueLoader(RESOURCE);

    /** Every approach a rung's walk leaves out, by the name rungs cite it by, in file order. */
    final Map<String, Approach> approaches;
    /** The same approaches, in the same order. */
    final List<Approach> approachList;
    /** The way of the {@link #FAIRY_RING_APPROACH}, the instance every ring rung holds. */
    final Requirement toAfairyRing;
    /** Every arrival, in circuit order. */
    final List<Arrival> circuit;
    /** Each arrival's combined chain, ranked; empty for most. */
    final Map<Arrival, List<TravelOption>> combined;
    /** Every site, in declaration order. */
    final List<Site> sites;
    /** The guild patches a contract can name. */
    final List<PatchRef> contractPatches;
    /** The patch that settles each capability that is a patch question. */
    final Map<Capability, PatchRef> patchFor;

    private CatalogueLoader(String resource) {
        Parser parser = new Parser();
        for (Tables.Row row : Tables.read(resource)) {
            try {
                parser.apply(row);
            } catch (IllegalArgumentException e) {
                // A model check refusing a value names no line; the row's error does.
                throw located(row, e);
            }
        }
        parser.finishSite();
        approaches = Collections.unmodifiableMap(parser.approaches);
        approachList = List.copyOf(approaches.values());
        Approach ring = approaches.get(FAIRY_RING_APPROACH);
        if (ring == null) {
            throw new IllegalStateException(resource + ": no approach " + FAIRY_RING_APPROACH);
        }
        toAfairyRing = ring.getWay();
        circuit = List.copyOf(parser.circuit);
        Map<Arrival, List<TravelOption>> ranked = new EnumMap<>(Arrival.class);
        parser.combined.forEach((arrival, chain) -> ranked.put(arrival, Ladders.ranked(chain, approaches.values())));
        combined = Collections.unmodifiableMap(ranked);
        sites = List.copyOf(parser.sites);
        contractPatches = List.copyOf(parser.contractPatches);
        patchFor = Collections.unmodifiableMap(parser.patchFor);
    }

    static CatalogueLoader loaded() {
        return LOADED;
    }

    /** {@code cause}'s message, located at {@code row}. */
    private static IllegalStateException located(Tables.Row row, RuntimeException cause) {
        IllegalStateException located = row.error(cause.getMessage());
        located.initCause(cause);
        return located;
    }

    /** One pass over the rows; each line adds to the approach, site, stop or rung above it. */
    private static final class Parser {

        final Map<String, Approach> approaches = new LinkedHashMap<>();
        final List<Arrival> circuit = new ArrayList<>();
        final Map<Arrival, List<TravelOption>> combined = new EnumMap<>(Arrival.class);
        final List<Site> sites = new ArrayList<>();
        final List<PatchRef> contractPatches = new ArrayList<>();
        final Map<Capability, PatchRef> patchFor = new EnumMap<>(Capability.class);

        private String approach;
        private List<Approach.Leg> legs;

        /** Where rung lines go: an arrival's combined chain or the open stop's ladder. */
        private List<TravelOption> rungs;

        private final Set<String> siteKeys = new HashSet<>();
        private final Set<String> switchKeys = new HashSet<>();
        private Tables.Row siteRow;
        private String siteKey;
        private RunId family;
        private Map<Spellbook, RunStop> siteStops;
        private Tables.Row attributes;
        private final List<PatchAttributes.BonusTier> yieldTiers = new ArrayList<>();
        private final List<PatchAttributes.BonusTier> xpTiers = new ArrayList<>();
        private SeedPolicy.DiaryOverride claim;
        private Tables.Row siteSwitch;
        private boolean picked;

        private Tables.Row stopRow;
        private RunStop.Builder stop;
        private List<Spellbook> books;

        void apply(Tables.Row row) {
            String verb = row.text(0);
            switch (verb) {
                case "approach":
                    finishSite();
                    approach = row.requireWidth(2).text(1);
                    if (approaches.containsKey(approach)) {
                        throw row.error("a second approach " + approach);
                    }
                    legs = new ArrayList<>();
                    break;
                case "leg":
                    if (legs == null) {
                        throw row.error("a leg outside an approach");
                    }
                    legs.add(Approach.leg(requirement(row.requireWidth(4), 1), row.integer(2), row.constant(TravelOption.Cost.class, 3)));
                    approaches.put(approach, Approach.of(legs.toArray(new Approach.Leg[0])));
                    break;
                case "arrival":
                    finishSite();
                    Arrival arrival = row.requireWidth(2).constant(Arrival.class, 1);
                    circuit.add(arrival);
                    rungs = new ArrayList<>();
                    combined.put(arrival, rungs);
                    break;
                case "contract":
                    finishSite();
                    rungs = null;
                    contractPatches.add(patch(row, row.requireWidth(2).text(1)));
                    break;
                case "patchFor":
                    finishSite();
                    rungs = null;
                    patchFor.put(row.requireWidth(3).constant(Capability.class, 1), patch(row, row.text(2)));
                    break;

                // --- A site and what is true of its patch ---------------------------
                case "site":
                    finishSite();
                    siteKey = row.requireWidth(3).text(1);
                    if (!siteKeys.add(siteKey)) {
                        throw row.error("a second site " + siteKey);
                    }
                    siteRow = row;
                    family = row.constant(RunId.class, 2);
                    siteStops = new EnumMap<>(Spellbook.class);
                    rungs = null;
                    break;
                case "switch":
                    openSite(row);
                    siteSwitch = row.requireWidth(3);
                    if (!switchKeys.add(row.text(1))) {
                        throw row.error("a second switch " + row.text(1));
                    }
                    break;
                // FarmingKeys reads the pick's keys; here it marks the site's stops picked.
                case "pick":
                    openSite(row);
                    picked = true;
                    break;
                case "attributes":
                    openSite(row);
                    attributes = row.requireWidth(7);
                    break;
                case "yieldTier":
                case "xpTier":
                    if (attributes == null) {
                        throw row.error("a bonus tier before the site's attributes");
                    }
                    row.requireWidth(4);
                    (verb.equals("yieldTier") ? yieldTiers : xpTiers).add(
                            new PatchAttributes.BonusTier(row.text(1), row.text(2), row.integer(3)));
                    break;
                case "claim":
                    openSite(row);
                    claim = new SeedPolicy.DiaryOverride(row.requireWidth(5).text(1), row.text(2),
                            patch(row, row.text(3)), row.constant(Crop.class, 4));
                    break;

                // --- A stop, one RunStop.Builder call a line ------------------------
                case "stop":
                    openSite(row);
                    finishStop();
                    row.requireWidth(3);
                    books = row.constants(Spellbook.class, 1);
                    String[] keys = row.text(2).split(",");
                    PatchRef[] patches = new PatchRef[keys.length];
                    for (int i = 0; i < keys.length; i++) {
                        patches[i] = patch(row, keys[i]);
                    }
                    stop = RunStop.builder(patches);
                    if (picked) {
                        stop.picked();
                    }
                    stopRow = row;
                    rungs = new ArrayList<>();
                    break;
                case "at":
                    stop(row).at(row.requireWidth(2).constant(Arrival.class, 1));
                    break;
                case "accessGate":
                    stop(row).accessGate(row.requireWidth(2).constant(Capability.class, 1));
                    break;
                case "gate":
                    stop(row).gate(UnlockGate.builder().skill(row.requireWidth(7).optionalConstant(Skill.class, 1)).level(row.integer(2))
                            .boostedFromLevel(row.integer(3)).recommendedFromLevel(row.integer(4)).diaryArea(row.optionalText(5))
                            .diaryTier(row.optionalText(6)).build());
                    break;
                case "actions":
                    stop(row).actions(row.requireWidth(2).constants(RunStop.StopAction.class, 1).toArray(new RunStop.StopAction[0]));
                    break;
                case "plants":
                    stop(row).plants(row.requireWidth(2).constant(Crop.class, 1));
                    break;
                case "optional":
                    stop(row).optional(row.requireWidth(2).text(1));
                    break;
                case "errand":
                    stop(row).errand(row.requireWidth(2).text(1));
                    break;
                case "everyNthRun":
                    stop(row).everyNthRun(row.requireWidth(2).integer(1));
                    break;
                case "skipIfUnreachable":
                    stop(row.requireWidth(1)).skipIfUnreachable();
                    break;
                case "noAlternative":
                    stop(row.requireWidth(1)).noAlternative();
                    break;
                case "noFallbackGiven":
                    stop(row.requireWidth(1)).noFallbackGiven();
                    break;

                // --- A rung, and the lines that change the rung above them ----------
                case "via":
                    rungs(row).add(TravelOption.via(requirement(row, 1), row.requireWidth(3).text(2)));
                    break;
                case "to":
                    Destination to = row.constant(Destination.class, 1);
                    rungs(row).add(row.width() == 4 ? TravelOption.to(to, requirement(row, 2), row.text(3))
                            : TravelOption.to(to, row.requireWidth(3).text(2)));
                    break;
                case "swapTo":
                    rungs(row).add(TravelOption.swapTo(row.constant(Destination.class, 1), row.requireWidth(3).text(2)));
                    break;
                case "walks":
                    change(row, last(row).withWalk(row.requireWidth(3).integer(1), row.constant(TravelOption.Cost.class, 2)));
                    break;
                case "banks":
                case "banksUpstairs":
                    change(row, last(row).withBank(row.requireWidth(3).integer(1), verb.equals("banksUpstairs"),
                            row.constant(Bank.class, 2)));
                    break;
                case "fare":
                    change(row, last(row).withFare(row.requireWidth(2).integer(1)));
                    break;
                case "floor":
                    change(row, last(row.requireWidth(1)).asFloor());
                    break;
                case "onlyWhenCertain":
                    change(row, last(row.requireWidth(1)).onlyWhenCertain());
                    break;
                case "onlyFromAstart":
                    change(row, last(row.requireWidth(1)).onlyFromAstart());
                    break;
                default:
                    throw row.error("no verb " + verb);
            }
        }

        private void openSite(Tables.Row row) {
            if (siteKey == null) {
                throw row.error("no site above this line");
            }
        }

        private RunStop.Builder stop(Tables.Row row) {
            if (stop == null) {
                throw row.error("no stop above this line");
            }
            return stop;
        }

        private List<TravelOption> rungs(Tables.Row row) {
            if (rungs == null) {
                throw row.error("a rung outside an arrival or a stop");
            }
            return rungs;
        }

        private TravelOption last(Tables.Row row) {
            if (rungs(row).isEmpty()) {
                throw row.error("no rung above this line");
            }
            return rungs.get(rungs.size() - 1);
        }

        private void change(Tables.Row row, TravelOption changed) {
            rungs(row).set(rungs.size() - 1, changed);
        }

        private void finishStop() {
            if (stop == null) {
                return;
            }
            RunStop built;
            try {
                built = stop.chain(rungs).build();
            } catch (IllegalArgumentException | IllegalStateException e) {
                // The builder checks the whole stop, so its errors belong to the stop line.
                throw located(stopRow, e);
            }
            for (Spellbook book : books) {
                siteStops.put(book, Ladders.ranked(built, approaches.values()));
            }
            stop = null;
            rungs = null;
        }

        void finishSite() {
            finishStop();
            if (siteKey == null) {
                return;
            }
            PatchAttributes.Entry entry = attributes == null ? null : new PatchAttributes.Entry(attributes.flag(1, "immune"),
                            attributes.optionalText(2), attributes.optionalText(3), attributes.optionalText(4), List.copyOf(yieldTiers),
                            List.copyOf(xpTiers), attributes.flag(5, "easy"), attributes.flag(6, "reserved"));
            try {
                sites.add(new Site(siteKey, family, siteStops, entry, claim, siteSwitch == null ? null : siteSwitch.text(1),
                        siteSwitch == null ? null : siteSwitch.text(2)));
            } catch (IllegalStateException e) {
                throw located(siteRow, e);
            }
            siteKey = null;
            attributes = null;
            yieldTiers.clear();
            xpTiers.clear();
            claim = null;
            siteSwitch = null;
            picked = false;
        }

        private static PatchRef patch(Tables.Row row, String key) {
            try {
                return PatchRef.named(key);
            } catch (IllegalArgumentException e) {
                throw row.error(e.getMessage());
            }
        }

        private Requirement requirement(Tables.Row row, int column) {
            String text = row.text(column);
            int[] at = {0};
            Requirement parsed = requirement(row, text, at);
            if (at[0] != text.length()) {
                throw row.error("trailing text in requirement " + text);
            }
            return parsed;
        }

        /** The requirement starting at {@code at[0]}, leaving {@code at[0]} just past it. */
        private Requirement requirement(Tables.Row row, String text, int[] at) {
            int start = at[0];
            while (at[0] < text.length() && "(),".indexOf(text.charAt(at[0])) < 0) {
                at[0]++;
            }
            String word = text.substring(start, at[0]);
            if (at[0] < text.length() && text.charAt(at[0]) == '(') {
                List<Requirement> parts = new ArrayList<>();
                do {
                    at[0]++;
                    parts.add(requirement(row, text, at));
                } while (at[0] < text.length() && text.charAt(at[0]) == ',');
                if (at[0] >= text.length() || text.charAt(at[0]) != ')') {
                    throw row.error("unclosed " + word + "( in " + text);
                }
                at[0]++;
                Requirement[] array = parts.toArray(new Requirement[0]);
                if (word.equals("all")) {
                    return Requirement.all(array);
                }
                if (word.equals("any")) {
                    return Requirement.any(array);
                }
                throw row.error("no requirement group " + word);
            }
            if (word.startsWith("@")) {
                Approach named = approaches.get(word.substring(1));
                if (named == null) {
                    throw row.error("no approach " + word + " above this line");
                }
                return named.getWay();
            }
            int colon = word.indexOf(':');
            String value = word.substring(colon + 1);
            try {
                switch (colon < 0 ? "" : word.substring(0, colon)) {
                    case "":
                        return Requirement.cap(Capability.valueOf(word));
                    case "reach":
                        return Requirement.reach(Destination.valueOf(value));
                    case "swap":
                        return Requirement.reachBySwap(Destination.valueOf(value));
                    case "patch":
                        return Requirement.reachedPatch(PatchRef.named(value));
                    case "zone":
                        return Requirement.standingIn(Zone.valueOf(value));
                    default:
                        throw row.error("no requirement kind in " + word);
                }
            } catch (IllegalArgumentException e) {
                throw row.error("no requirement " + word);
            }
        }
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.engine.farming.Crop;
import com.larryfarming.engine.farming.PatchType;
import java.util.*;

/**
 * The crops a player may grow instead of the default crop at a stop with one default crop,
 * and how often a herb run should call at the patch for each.
 *
 * <p>A stop takes this list when its patch type is here and the default crop is in it. The
 * list is best first by Farming level, so a stop plants the highest-level ticked crop the
 * player can grow and has the seed for.
 */
final class CropChoices {

    /**
     * Herb runs between visits, from each crop's growth time against a herb's 80 minutes
     * (4 × 20 minutes). Growth times are the wiki's: whiteberries and poison ivy 8 × 20 (Bush
     * patch, Seeds); cactus 7 × 80 and potato cactus 7 × 10 (Special patches, Cactus
     * patches). A bush or cactus is replanted each visit, so its growth time, not its
     * regrowth, sets the pacing. The picked allotments and flower patches need no figure:
     * every crop of theirs grows within a herb run.
     *
     * <p>Every crop here keys a patch family, but its figure is read only where the crop
     * stands in for the default crop. A stop's own default crop takes the stop's figure
     * ({@link FarmingCatalogue#everyNthRun}), so the catalogue has one source for it.
     */
    private static final Map<Crop, Integer> EVERY_NTH_RUN = Map.of(Crop.WHITEBERRIES, 2,
            Crop.POISON_IVY, 2, Crop.POTATO_CACTUS, 1, Crop.CACTUS, 7);

    private static final Map<PatchType, List<Crop>> BY_PATCH = byPatch();

    private CropChoices() {
    }

    private static Map<PatchType, List<Crop>> byPatch() {
        Map<PatchType, List<Crop>> byPatch = new EnumMap<>(PatchType.class);
        for (Crop crop : EVERY_NTH_RUN.keySet()) {
            PatchType type = CropData.forCrop(crop).getPatchType();
            // The patch's crops best first, less those offered nowhere.
            List<Crop> crops = new ArrayList<>(CropData.plantableIn(type));
            crops.retainAll(EVERY_NTH_RUN.keySet());
            byPatch.put(type, List.copyOf(crops));
        }
        return Collections.unmodifiableMap(byPatch);
    }

    /**
     * The anima plants, in the order the settings show them. A player who ticks several
     * plants the first of them they hold seeds for.
     */
    private static final List<Crop> ANIMA_PLANTS = List.of(Crop.ATTAS, Crop.IASOR, Crop.KRONOS);

    /** The crops this kind of patch offers in place of the default crop, best first, or empty. */
    static List<Crop> forPatch(PatchType type) {
        if (type == PatchType.ANIMA) {
            return ANIMA_PLANTS;
        }
        return BY_PATCH.getOrDefault(type, List.of());
    }

    /** How many herb runs pass between visits for this crop, or 0 when it has no choice. */
    static int everyNthRun(Crop crop) {
        return EVERY_NTH_RUN.getOrDefault(crop, 0);
    }
}

