import com.larryfarming.data.Tables;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.engine.farming.PatchType;
import java.util.*;
import lombok.Getter;

/**
 * What it takes to plant each crop the runs plant: the seed to carry, the Farming
 * level to plant it, the patch it goes in, and the tag that tells one seed from another
 * at a glance. One row of the crop data table per crop.
 *
 * <p>{@link Crop} mirrors RuneLite's table (its {@code itemId} is the produce, not the
 * seed), so the columns this plugin adds live here to keep that mirror diffable against
 * upstream.
 *
 * <p>Tree-family crops carry their potted-stage ids (seedling, watered seedling,
 * sapling) beside the seed. Crops planted straight from seed leave those at zero, which
 * {@link #isSaplingPlanted()} reads.
 */
@Getter
public final class CropData {

    private static final List<CropData> ALL = load();

    private final Crop crop;
    private final int seedItemId;
    private final int seedlingItemId;
    private final int wateredSeedlingItemId;
    private final int saplingItemId;
    private final int farmingLevel;
    private final PatchType patchType;
    private final String tag;
    private final String seedName;
    /** The herb's name on its square in the settings' herb grid, or "" for every other crop. */
    private final String gridTag;

    private CropData(Tables.Row row) {
        this.crop = row.constant(Crop.class, 0);
        this.farmingLevel = row.integer(1);
        this.patchType = row.constant(PatchType.class, 2);
        this.tag = row.text(3);
        this.seedName = row.text(4);
        this.seedItemId = row.integer(5);
        this.seedlingItemId = optionalId(row, 7);
        this.wateredSeedlingItemId = optionalId(row, 9);
        this.saplingItemId = optionalId(row, 11);
        this.gridTag = row.text(14);
    }

    private static int optionalId(Tables.Row row, int column) {
        return row.text(column).isEmpty() ? 0 : row.integer(column);
    }

    private static List<CropData> load() {
        List<CropData> rows = new ArrayList<>();
        Set<Crop> seen = EnumSet.noneOf(Crop.class);
        for (Tables.Row row : Tables.read("/com/larryfarming/crop-data.tsv", 15)) {
            CropData data = new CropData(row);
            if (!seen.add(data.crop)) {
                throw row.error("a second row for " + data.crop);
            }
            rows.add(data);
        }
        return List.copyOf(rows);
    }

    /** Every row, in the table's order. */
    public static List<CropData> values() {
        return ALL;
    }

    /** "Oak sapling", or null for a crop planted straight from its seed. */
    public String getSaplingName() {
        return isSaplingPlanted() ? crop.getDisplayName() + " sapling" : null;
    }

    /** "Oak seedling", or null for a crop planted straight from its seed. */
    public String getSeedlingName() {
        return isSaplingPlanted() ? crop.getDisplayName() + " seedling" : null;
    }

    /** True when this crop is planted as a sapling rather than straight from the seed. */
    public boolean isSaplingPlanted() {
        return saplingItemId != 0;
    }

    /**
     * Every form this crop's planting stock comes in, earliest first.
     *
     * <p>Any of the four forms can fill the patch, so a player midway through potting a
     * stack still counts as holding planting stock.
     */
    public List<Integer> getPlantingForms() {
        if (!isSaplingPlanted()) {
            return List.of(seedItemId);
        }
        return List.of(seedItemId, seedlingItemId, wateredSeedlingItemId, saplingItemId);
    }

    /**
     * How many seeds one patch of this crop swallows.
     *
     * <p>Three for an allotment, one for everything else.
     */
    public int getSeedsPerPatch() {
        return seedsPerPatch(patchType);
    }

    /**
     * The one-to-five letter tag drawn over the seed, or "" for the crops that do not
     * take one.
     *
     * <p>Herb seeds and sapling-planted crops only: herb seeds differ by a few pixels of
     * colour and the saplings share one pot sprite. Everything else is distinguishable at a
     * glance, so a tag there is clutter. This also keeps snape grass ("SNA") from reading
     * like snapdragon ("S").
     */
    public String getTag() {
        return patchType == PatchType.HERB || isSaplingPlanted() ? tag : "";
    }

    /**
     * The tag as RuneLite's Item Identification writes it, for every crop. {@link #getTag}
     * draws it only where a bag needs it; a lone square in a settings grid always does.
     */
    public String getStoredTag() {
        return tag;
    }

    /**
     * The tag for any form of a crop's planting stock, or empty for anything else. Every
     * potted stage is tagged because all of them share the same pot sprite.
     */
    public static String tagForPlantable(int itemId) {
        // Seed-planted crops store 0 in their potted columns, so 0 must not match.
        if (itemId <= 0) {
            return "";
        }
        for (CropData data : ALL) {
            if (data.getPlantingForms().contains(itemId)) {
                return data.getTag();
            }
        }
        return "";
    }

    /**
     * Every crop that goes in this kind of patch, best first.
     *
     * <p>A fact about the patch with no route opinion; the player's ticks are applied by
     * {@link com.larryfarming.farming.model.FarmingPreferences#ticked}.
     *
     * <p>Best-first means descending level, a true ranking only for the tree families.
     * Herbs rank by the seed policy's tier list, and the other families are not rankings.
     *
     * <p>Unfiltered by the player's level; callers apply that.
     */
    public static List<Crop> plantableIn(PatchType patchType) {
        return BY_PATCH_TYPE.getOrDefault(patchType, List.of());
    }

    /** Computed once: every planting stop asks this on every snapshot rebuild. */
    private static final Map<PatchType, List<Crop>> BY_PATCH_TYPE = indexByPatchType();

    private static Map<PatchType, List<Crop>> indexByPatchType() {
        Map<PatchType, List<CropData>> matching = new EnumMap<>(PatchType.class);
        for (CropData data : ALL) {
            matching.computeIfAbsent(data.patchType, type -> new ArrayList<>()).add(data);
        }
        Map<PatchType, List<Crop>> index = new EnumMap<>(PatchType.class);
        for (Map.Entry<PatchType, List<CropData>> entry : matching.entrySet()) {
            List<CropData> rows = entry.getValue();
            rows.sort(Comparator.comparingInt(CropData::getFarmingLevel).reversed());
            List<Crop> crops = new ArrayList<>(rows.size());
            for (CropData data : rows) {
                crops.add(data.crop);
            }
            index.put(entry.getKey(), List.copyOf(crops));
        }
        return Collections.unmodifiableMap(index);
    }

    /**
     * How many seeds one patch of this kind swallows. Three for an allotment, one for
     * everything else.
     */
    public static int seedsPerPatch(PatchType patchType) {
        return patchType == PatchType.ALLOTMENT ? 3 : 1;
    }

    /**
     * Whether a seed box would take this item.
     *
     * <p>The box holds seeds only. Seedlings and saplings are not seeds, so each takes its
     * own inventory slot however many boxes the player carries. Asked of the item, not the
     * crop: an acorn boxes, an oak sapling does not.
     *
     * <p>Mushroom spores box by a game exception and are covered by the mushroom row.
     */
    public static boolean boxesAsAseed(int itemId) {
        return itemId != 0 && SEED_ITEM_IDS.contains(itemId);
    }

    /** Computed once: this is asked per carry line. */
    private static final Set<Integer> SEED_ITEM_IDS = seedItemIds();

    private static Set<Integer> seedItemIds() {
        Set<Integer> ids = new HashSet<>();
        for (CropData data : ALL) {
            ids.add(data.seedItemId);
        }
        return Collections.unmodifiableSet(ids);
    }

    /** The row for a crop, or null if no run plants it. */
    public static CropData forCrop(Crop crop) {
        return BY_CROP.get(crop);
    }

    private static final Map<Crop, CropData> BY_CROP = byCrop();

    private static Map<Crop, CropData> byCrop() {
        Map<Crop, CropData> rows = new EnumMap<>(Crop.class);
        for (CropData data : ALL) {
            rows.put(data.crop, data);
        }
        return Collections.unmodifiableMap(rows);
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.data.Tables;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.engine.farming.PatchType;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.Skill;
import java.util.ArrayList;
import java.util.List;

/**
 * What a run family holds beside its sites: the gate, the respawn town and the seeds, one
 * row of the families table per run. The herb family is written once per spellbook; every
 * other family once.
 */
final class Families {

    private Families() {
    }

    /**
     * Every run, in the order the catalogue lists them, as its family data alone: everything
     * a run carries but its stops, which {@link RunAssembler} adds. The preset's ticks, not
     * the family, say which crops a seed patch type plants.
     */
    static final List<FarmingRun> ALL = load();

    private static List<FarmingRun> load() {
        List<FarmingRun> families = new ArrayList<>();
        for (Tables.Row row : Tables.read("/com/larryfarming/families.tsv", 8)) {
            PatchType seeds = row.optionalConstant(PatchType.class, 7);
            Skill skill = row.optionalConstant(Skill.class, 2);
            UnlockGate unlock = seeds != null && skill == null ? plantsFrom(seeds) : UnlockGate.builder().skill(skill).level(row.integer(3))
                            .boostedFromLevel(row.integer(4)).recommendedFromLevel(row.integer(5)).build();
            families.add(FarmingRun.builder().id(row.constant(RunId.class, 0)).spellbook(row.constant(Spellbook.class, 1)).unlock(unlock)
                    .respawnTown(row.optionalText(6)).seedPatchType(seeds).build());
        }
        return List.copyOf(families);
    }

    /**
     * The level at which the game first lets a crop of this family into its patch: the
     * cheapest crop's. The scheduler raises it to the cheapest crop the player has ticked.
     */
    static UnlockGate plantsFrom(PatchType family) {
        List<Crop> crops = CropData.plantableIn(family);
        // Best first, so the cheapest is last.
        Crop cheapest = crops.get(crops.size() - 1);
        return UnlockGate.skill(Skill.FARMING, CropData.forCrop(cheapest).getFarmingLevel());
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.model.*;
import java.util.*;
import lombok.Value;

/**
 * Every farm run, encoded: its stops, the routes to each, and the crops it plants.
 *
 * <p>Each run is assembled from its family in {@link Families} and its sites in
 * {@link Site}, read from the stops table, which fails to load on any patch, crop or
 * capability it does not know.
 *
 * <p>Everything here is data. Deciding which runs are due, which rung a player can take
 * and what to show them belongs elsewhere.
 */
public final class FarmingCatalogue {

    private FarmingCatalogue() {
    }

    /** Assembled once, so every caller sees the same run objects. */
    private static final List<FarmingRun> RUNS = RunAssembler.assemble();

    private static final SeedPolicy SEED_POLICY = Seeds.policy();

    private static final Map<RunId, List<FarmingRun>> RUNS_BY_ID = collectRunsById();

    private static Map<RunId, List<FarmingRun>> collectRunsById() {
        Map<RunId, List<FarmingRun>> byId = new EnumMap<>(RunId.class);
        for (FarmingRun run : RUNS) {
            byId.computeIfAbsent(run.getId(), id -> new ArrayList<>()).add(run);
        }
        byId.replaceAll((id, runs) -> List.copyOf(runs));
        return Collections.unmodifiableMap(byId);
    }

    /**
     * Every variant of each run, in run-id order. The herb run is in the catalogue once per
     * spellbook.
     */
    public static Map<RunId, List<FarmingRun>> runsById() {
        return RUNS_BY_ID;
    }

    /**
     * This run's stops in the order {@link Site} declares them. Reordering a run's walk
     * does not move this order, so a list the player reads, such as a crop grid, draws
     * from it to keep one fixed order.
     */
    public static List<RunStop> stopsInRegistryOrder(FarmingRun run) {
        List<RunStop> stops = new ArrayList<>(run.getStops().size());
        for (Site site : Site.values()) {
            if (site.family() == run.getId() && site.books().contains(run.getSpellbook())) {
                RunStop stop = site.stop(run.getSpellbook());
                if (run.getStops().contains(stop)) {
                    stops.add(stop);
                }
            }
        }
        return List.copyOf(stops);
    }

    /** A site the player may drop from a run: its key, its name, and one of its stops. */
    @Value
    public static class SiteSwitch {
        /** The {@code FarmingKeys} key that holds whether the runs visit it. */
        String key;
        /** Named for a player, as the run's settings list it: "Weiss". */
        String label;
        /** The site's stop on any book, for the gates every book's stop shares. */
        RunStop stop;
    }

    /**
     * The sites of this run the player may drop, in the order {@link Site} declares them,
     * which never moves. Empty for a run with no such sites.
     */
    public static List<SiteSwitch> siteSwitches(RunId run) {
        List<SiteSwitch> sites = new ArrayList<>();
        for (Site site : Site.values()) {
            if (site.switchKey() != null && site.family() == run) {
                sites.add(new SiteSwitch(site.switchKey(), site.switchLabel(), site.anyStop()));
            }
        }
        return List.copyOf(sites);
    }

    /** The keys of {@link #siteSwitches}, in the same order, read without allocating. */
    public static List<String> siteKeys(RunId run) {
        return SITE_KEYS.getOrDefault(run, List.of());
    }

    private static final Map<RunId, List<String>> SITE_KEYS = collectSiteKeys();

    private static Map<RunId, List<String>> collectSiteKeys() {
        Map<RunId, List<String>> keys = new EnumMap<>(RunId.class);
        for (RunId run : RunId.values()) {
            List<String> ofRun = new ArrayList<>();
            for (SiteSwitch site : siteSwitches(run)) {
                ofRun.add(site.getKey());
            }
            keys.put(run, List.copyOf(ofRun));
        }
        return Collections.unmodifiableMap(keys);
    }

    /**
     * The key of the switchable site this patch belongs to, or null when it has none. A herb
     * farm's picked patches belong to its herb site, so they go only where it goes.
     */
    public static String siteKey(PatchRef patch) {
        return SITE_KEYS_BY_PATCH.get(patch);
    }

    private static final Map<PatchRef, String> SITE_KEYS_BY_PATCH = collectSiteKeysByPatch();

    private static Map<PatchRef, String> collectSiteKeysByPatch() {
        Map<PatchRef, String> keys = new HashMap<>();
        // A farm's patches share its herb patch's map region, and the stops table lists each
        // herb site before its farm's picks.
        Map<Integer, String> farms = new HashMap<>();
        for (Site site : Site.values()) {
            int region = site.patch().getRegionId();
            String key = FarmingKeys.PICKS.containsKey(site.name()) ? farms.get(region) : site.switchKey();
            if (key != null) {
                for (PatchRef patch : site.patches()) {
                    keys.put(patch, key);
                }
                if (site.family() == RunId.HERB) {
                    farms.put(region, key);
                }
            }
        }
        return Collections.unmodifiableMap(keys);
    }

    /** The pick that chooses this stop's crop, or null for a stop that isn't picked. */
    public static PatchPick pickOf(RunStop stop) {
        return PICKS_BY_PATCH.get(stop.primaryPatch());
    }

    /** Every picked patch and its pick, in the stops table's order. */
    public static Map<PatchRef, PatchPick> picksByPatch() {
        return PICKS_BY_PATCH;
    }

    private static final Map<PatchRef, PatchPick> PICKS_BY_PATCH = collectPicksByPatch();

    private static Map<PatchRef, PatchPick> collectPicksByPatch() {
        Map<PatchRef, PatchPick> picks = new LinkedHashMap<>();
        for (Site site : Site.values()) {
            PatchPick pick = FarmingKeys.PICKS.get(site.name());
            if (pick != null) {
                picks.put(site.patch(), pick);
            }
        }
        return Collections.unmodifiableMap(picks);
    }

    /**
     * The crops this stop may grow, best first: the default crop and any the player may
     * tick in its place, or for a picked stop every crop of its patch. Empty for a stop the
     * run's seeds fill.
     */
    public static List<Crop> cropChoices(RunStop stop) {
        if (!stop.isFixedCrop()) {
            return List.of();
        }
        if (stop.isPicked()) {
            return CropData.plantableIn(stop.patchType());
        }
        List<Crop> family = CropChoices.forPatch(stop.patchType());
        return family.contains(stop.getFixedCrop()) ? family : List.of(stop.getFixedCrop());
    }

    /**
     * How many herb runs pass between visits to this stop while it grows this crop.
     *
     * <p>The stop's own figure is the one source for its default crop, and answers for a
     * stop with no choice. {@link CropChoices} carries the figure only for the crops a
     * player may switch on in the default crop's place.
     */
    public static int everyNthRun(RunStop stop, Crop crop) {
        if (crop == null || crop == stop.getFixedCrop()) {
            return stop.getEveryNthRun();
        }
        int ofCrop = CropChoices.everyNthRun(crop);
        return ofCrop > 0 && cropChoices(stop).contains(crop) ? ofCrop : stop.getEveryNthRun();
    }

    /**
     * The run for this activity on this spellbook, or null if there is none.
     *
     * <p>{@link Spellbook#ANY} means "it does not matter" in both directions: a run
     * declared for ANY matches whatever is asked for, and asking for ANY takes the
     * first run with that id.
     */
    public static FarmingRun run(RunId id, Spellbook spellbook) {
        for (FarmingRun run : RUNS) {
            if (run.getId() != id) {
                continue;
            }
            if (spellbook == Spellbook.ANY || run.getSpellbook() == spellbook || run.getSpellbook() == Spellbook.ANY) {
                return run;
            }
        }
        return null;
    }

    public static SeedPolicy seedPolicy() {
        return SEED_POLICY;
    }

    /**
     * Some way to stand at a fairy ring, the half of every fairy ring rung that the player's
     * items and switches decide. The same instance every chain uses, so the planner can find
     * it inside a rung.
     */
    public static Requirement toAfairyRing() {
        return CatalogueLoader.loaded().toAfairyRing;
    }

    /**
     * Every approach a rung's walk leaves out: the ways onto the fairy rings and the spirit
     * trees, each with its walk from landing to network. The planner adds the walk of the way
     * in this account takes, which is why a ladder with such a rung is ranked per account.
     */
    public static List<Approach> approaches() {
        return CatalogueLoader.loaded().approachList;
    }

    /**
     * How to reach an arrival when several of its patches are being worked at once, or
     * empty when the lead stop's own chain serves (see {@link Arrivals}).
     *
     * <p>Empty is the common answer, not an error. Never hand the empty list to a route
     * resolver: it would report the place unreachable. Fall back to the lead stop's chain.
     */
    public static List<TravelOption> combinedRoute(Arrival arrival) {
        return CatalogueLoader.loaded().combined.get(arrival);
    }

    /**
     * Every Farming Guild patch a contract can name, which is everywhere a contracted crop
     * could be growing.
     *
     * <p>The spirit tree and anima patch are left out because no contract
     * asks for them.
     *
     * <p>The scheduler reads these patches to tell whether a contract has grown: the
     * contract varbits name the assigned crop but not whether it is ready.
     */
    public static List<PatchRef> contractPatches() {
        return CatalogueLoader.loaded().contractPatches;
    }

    /**
     * The patch that settles this capability, or null if it is not a patch question.
     *
     * <p>A few capabilities are patch states: a grown spirit tree is a travel option, and a
     * usable Weiss herb patch proves the fire of nourishment is lit. {@code PatchSight}
     * reads them. Only the spirit trees a chain offers a rung for count.
     */
    public static PatchRef patchFor(Capability capability) {
        return CatalogueLoader.loaded().patchFor.get(capability);
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.farming.model.*;
import java.util.Collection;
import java.util.List;

/**
 * Every ladder the registry holds, ranked by its rungs' walks as far as the catalogue alone
 * can rank them ({@link RungOrder}).
 *
 * <p>A rung asking for an {@link Approach} has no total until the account says which way in
 * the player takes, so here it keeps its written place, and the planner ranks it per account.
 * Every other rung's figure is the same for everyone, so its place is settled once.
 */
final class Ladders {

    private Ladders() {
    }

    /** The stop with its ladder ranked. */
    static RunStop ranked(RunStop stop, Collection<Approach> approaches) {
        return stop.withLadder(ranked(stop.getTravel(), approaches));
    }

    /** The ladder ranked, each rung leaning on one of these approaches kept in its place. */
    static List<TravelOption> ranked(List<TravelOption> ladder, Collection<Approach> approaches) {
        return List.copyOf(RungOrder.rank(ladder, new RungOrder.Figures() {
            @Override
            public int walk(int rung) {
                TravelOption option = ladder.get(rung);
                return asksForAnApproach(option, approaches) && option.hasWalkFigure() ? TravelOption.UNMEASURED : option.getWalk();
            }

            @Override
            public TravelOption.Cost cost(int rung) {
                return ladder.get(rung).getCost();
            }
        }));
    }

    private static boolean asksForAnApproach(TravelOption rung, Collection<Approach> approaches) {
        for (Approach approach : approaches) {
            if (rung.getRequires().contains(approach.getWay())) {
                return true;
            }
        }
        return false;
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.data.Tables;
import com.larryfarming.farming.model.GearPick;
import com.larryfarming.farming.model.LoadoutSlot;
import com.larryfarming.model.EquipmentSlot;
import java.util.*;
import net.runelite.api.gameval.ItemID;

/**
 * What to wear on a farm run, read from {@code loadouts.tsv}.
 *
 * <p>Gear comes as ordered fallbacks ("Max cape → Farming cape → Ardougne cloak"), plus
 * magic secateurs and the farmer's outfit. Encoded as tiers, not a fixed kit.
 *
 * <p>Only two things must be worn to work (wiki): the Farmer's outfit, whose experience
 * bonus counts only while worn, and a dramen or lunar staff, which a fairy ring needs
 * wielded unless the elite Lumbridge &amp; Draynor diary is done. Everything else works
 * from the inventory: the Explorer's ring and Ardougne cloak teleport from it, Xeric's
 * talisman is rubbed, and magic secateurs raise yield from it. Wearing those only saves
 * inventory slots. The log basket, worn on a tree run that needs no cape, is asked for
 * only worn, since the slot it frees is all it adds.
 *
 * <p>The weapon slot holds the staff on a run that needs one, and the secateurs
 * otherwise. Swapping them mid-run buys nothing, so with the staff wielded the secateurs
 * ride in the inventory and the packing list names them.
 *
 * <p>Slots with nothing useful to say are left out.
 */
public final class Loadouts {

    private Loadouts() {
    }

    /** Magic secateurs, which raise yield from the inventory as well as the hand. */
    public static final int MAGIC_SECATEURS = ItemID.FAIRY_ENCHANTED_SECATEURS;
    public static final int DRAMEN_STAFF = 772;
    public static final int LUNAR_STAFF = 9084;

    /** The one sentence for an outfit owned but not all worn. */
    public static final String OUTFIT_TIP = "Wear the Farmer's outfit for 2.5% more Farming experience.";

    /** The weapon and log-basket slots, which {@link #forRun} chooses between; the rest always show. */
    private static final Set<String> CHOSEN = Set.of("SECATEURS", "STAFF", "LOG_BASKET");

    /** Every slot by its key, in the table's order, which is the order the panel shows. */
    private static final Map<String, LoadoutSlot> SLOTS = read(Tables.read("/com/larryfarming/loadouts.tsv"));

    private static Map<String, LoadoutSlot> read(List<Tables.Row> rows) {
        Map<String, List<Tables.Row>> byKey = new LinkedHashMap<>();
        for (Tables.Row row : rows) {
            byKey.computeIfAbsent(row.text(1), k -> new ArrayList<>()).add(row);
        }
        Map<String, LoadoutSlot> slots = new LinkedHashMap<>();
        byKey.forEach((key, group) -> slots.put(key, slot(group)));
        if (!slots.keySet().containsAll(CHOSEN)) {
            throw new IllegalStateException("loadouts.tsv: needs a slot for each of " + CHOSEN);
        }
        return Collections.unmodifiableMap(slots);
    }

    /** One slot from its rows: the slot row first, then its forms, tiers and goal. */
    private static LoadoutSlot slot(List<Tables.Row> rows) {
        Tables.Row head = rows.get(0);
        if (!head.text(0).equals("slot")) {
            throw head.error("a slot's rows start with its slot row");
        }
        head.requireWidth(7);
        List<GearPick> tiers = new ArrayList<>();
        List<GearPick> forms = new ArrayList<>();
        GearPick goal = null;
        String sentence = null;
        for (Tables.Row row : rows.subList(1, rows.size())) {
            switch (row.text(0)) {
                case "form":
                    forms.add(pick(row));
                    break;
                case "tier":
                    tiers.add(row.requireWidth(6).integers(4).length > 0 ? pick(row)
                            : GearPick.anyOf(row.text(2), row.text(3), forms.toArray(new GearPick[0])));
                    break;
                case "goal":
                    goal = forms.stream().filter(f -> f.getDisplayName().equals(row.text(2))).findFirst()
                            .orElseThrow(() -> row.error("no form " + row.text(2)));
                    sentence = row.requireWidth(4).text(3);
                    break;
                default:
                    throw row.error("no row kind " + row.text(0) + " within a slot");
            }
        }
        if (tiers.isEmpty()) {
            throw head.error("nothing to put in the slot");
        }
        // Without a goal row, the goal is the cheapest tier, the one within reach.
        GearPick target = goal != null ? goal : tiers.get(tiers.size() - 1);
        return new LoadoutSlot(head.constant(EquipmentSlot.class, 2), List.copyOf(tiers), head.flag(4, "yes"),
                head.optionalText(6), head.flag(5, "yes"), head.text(3), target,
                sentence != null ? sentence : "Earn " + target.getDisplayName() + " for " + target.getBenefit() + ".");
    }

    private static GearPick pick(Tables.Row row) {
        return GearPick.of(row.requireWidth(6).text(2), row.text(3), row.integers(4));
    }

    /**
     * The slots worth filling on a run, in the order the panel shows them.
     *
     * @param staffWielded whether the run uses a fairy ring that needs a staff in hand,
     *     which then takes the weapon slot from the secateurs
     * @param basketWorn whether the log basket takes the cape slot
     */
    public static List<LoadoutSlot> forRun(boolean staffWielded, boolean basketWorn) {
        List<LoadoutSlot> slots = new ArrayList<>(SLOTS.size());
        slots.add(SLOTS.get(staffWielded ? "STAFF" : "SECATEURS"));
        SLOTS.forEach((key, slot) -> {
            if (!CHOSEN.contains(key)) {
                slots.add(basketWorn && slot.getSlot() == EquipmentSlot.CAPE ? SLOTS.get("LOG_BASKET") : slot);
            }
        });
        return slots;
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.farming.model.PatchRef;
import java.util.*;
import lombok.Value;

/**
 * What makes one patch a better home for a seed than another: a view of the attributes
 * each {@link Site} carries.
 *
 * <p>Records facts and gates only; {@link com.larryfarming.farming.engine.PatchPriority} turns
 * them into a score.
 *
 * <p>Ortus Farm's disease
 * protection is deliberately left out: it depends on Champion rank at the Fortis
 * Colosseum, which nothing detects, and crediting immunity a player lacks is the error
 * this ranking exists to prevent.
 *
 * <p>An absent patch scores as ordinary.
 */
public final class PatchAttributes {

    /** One diary tier and the percentage bonus it grants at this patch. */
    @Value
    public static class BonusTier {
        String diaryArea;
        String diaryTier;
        int percent;
    }

    /** Everything the ranking knows about one patch. */
    @Value
    public static class Entry {
        /** Immune by the game's own design, needing no unlock. */
        boolean alwaysDiseaseFree;
        /** Diary that grants immunity here, or null. */
        String diseaseFreeDiaryArea;
        String diseaseFreeDiaryTier;
        /** Quest that grants immunity here, or null. */
        String diseaseFreeQuest;
        /** Harvest-life bonuses, one per qualifying diary tier. Never null. */
        List<BonusTier> yieldTiers;
        /**
         * Experience bonuses, one per qualifying diary tier. Never null. Separate from
         * {@link #yieldTiers} because extra herbs outrank extra experience.
         */
        List<BonusTier> xpTiers;
        /**
         * Reachable cheaply and reliably. Only a tie-break among patches with neither a
         * bonus nor immunity; not a stand-in for
         * {@link com.larryfarming.farming.detection.TeleportPlanner}.
         */
        boolean easyTravel;
        /**
         * Held back for farming contracts. Sinks the patch below patches with no bonus at
         * all.
         */
        boolean reservedForContracts;
    }

    private static final Map<PatchRef, Entry> BY_PATCH = table();

    private PatchAttributes() {
    }

    /** This patch's attributes, or null when it has none worth ranking on. */
    public static Entry of(PatchRef patch) {
        return patch == null ? null : BY_PATCH.get(patch);
    }

    /**
     * Read off the sites, in {@link Site} order. Nothing in {@link Site}'s own
     * initialisation may call into this class, or this would read the sites half-built.
     */
    private static Map<PatchRef, Entry> table() {
        Map<PatchRef, Entry> entries = new LinkedHashMap<>();
        for (Site site : Site.values()) {
            if (site.attributes() != null && entries.put(site.patch(), site.attributes()) != null) {
                throw new IllegalStateException(site + ": a second site ranks its patch");
            }
        }
        return Collections.unmodifiableMap(entries);
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.farming.model.FarmingRun;
import java.util.*;

/**
 * Builds every run from the registry: a family's data from {@link Families}, and the sites
 * of that family on that book from {@link Site}, each worked by that book's stop.
 *
 * <p>A run lists its sites in the circuit's seat order, by the seat of each site's arrival,
 * and at one arrival in the order {@link Site} declares them.
 */
final class RunAssembler {

    private RunAssembler() {
    }

    /** Every run, in the order {@link Families#ALL} lists the families. */
    static List<FarmingRun> assemble() {
        List<FarmingRun> runs = new ArrayList<>(Families.ALL.size());
        for (FarmingRun family : Families.ALL) {
            runs.add(assemble(family));
        }
        return List.copyOf(runs);
    }

    /** The family's run with its stops added; the family itself holds none. */
    private static FarmingRun assemble(FarmingRun family) {
        List<Site> sites = new ArrayList<>();
        for (Site site : Site.values()) {
            if (site.family() == family.getId() && site.books().contains(family.getSpellbook())) {
                sites.add(site);
            }
        }
        // Stable, so sites at one arrival keep their declared order.
        sites.sort(Comparator.comparingInt(site -> Arrivals.seat(site.arrival())));
        FarmingRun.FarmingRunBuilder run = family.toBuilder();
        for (Site site : sites) {
            run.stop(site.stop(family.getSpellbook()));
        }
        return run.build();
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.farming.model.Preset;
import com.larryfarming.farming.model.SeedPolicy;

/**
 * The herb seed rotation, read from the preset's choices, and the diary claims the sites
 * carry.
 */
final class Seeds {

    private Seeds() {
    }

    static SeedPolicy policy() {
        Preset preset = Preset.DEFAULT;
        SeedPolicy.SeedPolicyBuilder policy = SeedPolicy.builder().herbTierList(preset.getHerbRanking())
                .goodSeedsPerRun(preset.getGoodSeedsPerRun());
        // The one claim is Falador's magic, which the preset can switch off.
        if (preset.isMagicAtFaladorWithEliteDiary()) {
            for (Site site : Site.values()) {
                if (site.diaryClaim() != null) {
                    policy.override(site.diaryClaim());
                }
            }
        }
        return policy.build();
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.farming.model.*;
import java.util.*;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * One place a run visits, as the stops table lists it: the family it belongs to, the stop
 * each spellbook works it by, what is true of its patch beyond the route there, and the
 * switch that drops it from its run.
 *
 * <p>A site has one identity whatever the book. Weiss on Arceuus and Weiss on Lunar are one
 * site with two stops, which differ only in their ladder and their terminal. A site outside
 * the herb family is on {@link Spellbook#ANY}.
 *
 * <p>The table's order is the order the sites at one arrival are worked in.
 *
 * <p>{@link PatchAttributes} and {@link Seeds} build their tables from {@link #values()}, so
 * nothing loading the sites may reach either of them, or {@link FarmingCatalogue}, whose
 * policy {@link Seeds} builds. Such a cycle reads the sites half-built.
 */
@Accessors(fluent = true)
final class Site {

    private final String key;
    @Getter
    private final RunId family;
    private final Map<Spellbook, RunStop> stops;
    /** What makes this site's patch a better home for a seed, or null when nothing does. */
    @Getter
    private final PatchAttributes.Entry attributes;
    /** The crop a diary keeps for this site's patch, or null when none does. */
    @Getter
    private final SeedPolicy.DiaryOverride diaryClaim;
    /** The {@code FarmingKeys} key that holds whether the runs visit it, or null for none. */
    @Getter
    private final String switchKey;
    /** The site named for a player, as its run's settings list it: "Weiss". */
    @Getter
    private final String switchLabel;

    Site(String key, RunId family, Map<Spellbook, RunStop> stops, PatchAttributes.Entry attributes, SeedPolicy.DiaryOverride diaryClaim,
            String switchKey, String switchLabel) {
        if (stops.isEmpty()) {
            throw new IllegalStateException(key + ": no stop on any book");
        }
        this.key = key;
        this.family = family;
        this.stops = Collections.unmodifiableMap(new EnumMap<>(stops));
        this.attributes = attributes;
        this.diaryClaim = diaryClaim;
        this.switchKey = switchKey;
        this.switchLabel = switchLabel;
        // One place: every book's stop works the same patches from the same arrival.
        RunStop first = anyStop();
        for (RunStop stop : this.stops.values()) {
            if (!stop.getPatches().equals(first.getPatches()) || stop.getArrival() != first.getArrival()) {
                throw new IllegalStateException(key + ": the books' stops are two places");
            }
        }
        // Attributes and a claim describe one patch, so the site must work only that one.
        if ((attributes != null || diaryClaim != null) && first.getPatches().size() != 1) {
            throw new IllegalStateException(key + ": per-patch data on a site of " + first.getPatches().size() + " patches");
        }
        if (diaryClaim != null && !diaryClaim.getPatch().equals(first.primaryPatch())) {
            throw new IllegalStateException(key + ": its diary claim names another patch");
        }
    }

    /** Every site, in the table's order. */
    static List<Site> values() {
        return CatalogueLoader.loaded().sites;
    }

    /** The site's key, which never changes. */
    String name() {
        return key;
    }

    @Override
    public String toString() {
        return key;
    }

    /** The patch this site works, the first where it works several. */
    PatchRef patch() {
        return anyStop().primaryPatch();
    }

    /** Every patch this site works, the same on every book. */
    List<PatchRef> patches() {
        return anyStop().getPatches();
    }

    /** A stop of this site's, for what every book's stop shares: its patches and gates. */
    RunStop anyStop() {
        return stops.values().iterator().next();
    }

    /** The books whose run lists this site, in enum order. */
    Set<Spellbook> books() {
        return stops.keySet();
    }

    Arrival arrival() {
        return anyStop().getArrival();
    }

    /**
     * The stop this book's run works the site by: its ladder and terminal for that book.
     *
     * @throws IllegalArgumentException if no run on this book lists the site
     */
    RunStop stop(Spellbook book) {
        RunStop stop = stops.get(book);
        if (stop == null) {
            throw new IllegalArgumentException(key + " is on no " + book + " run");
        }
        return stop;
    }
}

package com.larryfarming.farming.catalogue;

import com.larryfarming.data.Tables;
import com.larryfarming.farming.model.*;
import java.util.*;

/**
 * Every way the runs know of reaching each place: the spell, and the tablet that lands in
 * the same spot, read from the teleports table.
 *
 * <p>Levels and rune costs come from the OSRS wiki spellbook pages
 * (<a href="https://oldschool.runescape.wiki/w/Standard_spellbook">standard</a>,
 * <a href="https://oldschool.runescape.wiki/w/Lunar_spellbook">Lunar</a>,
 * <a href="https://oldschool.runescape.wiki/w/Arceuus_spellbook">Arceuus</a>).
 *
 * <p>Teleport to House is a standard-book spell, so a player on Arceuus or Lunar reaches
 * their house only by tablet. The runs therefore ask for a place rather than an item.
 *
 * <p>Spellbook Swap's level, quest and runes come from the wiki's
 * <a href="https://oldschool.runescape.wiki/w/Spellbook_Swap">Spellbook Swap</a> page.
 */
public final class Teleports {

    private Teleports() {
    }

    private static final String RESOURCE = "/com/larryfarming/teleports.tsv";

    private static final Map<Destination, List<TeleportMeans>> MEANS;
    private static final Map<Capability, Map<Rune, Integer>> SPELL_COSTS;

    /**
     * Spellbook Swap: Lunar, 96 Magic, Dream Mentor. It opens another book the player has
     * unlocked for one cast within two minutes, then returns them to Lunar.
     */
    public static final TeleportMeans SPELLBOOK_SWAP;

    // The teleports table, read once. Assigned here rather than in initialisers because one
    // pass over the rows fills all three.
    static {
        Map<Destination, List<TeleportMeans>> byPlace = new EnumMap<>(Destination.class);
        Map<Capability, Map<Rune, Integer>> byCapability = new EnumMap<>(Capability.class);
        TeleportMeans swapRow = null;
        for (Tables.Row row : Tables.read(RESOURCE)) {
            switch (row.text(0)) {
                case "spell":
                case "swap":
                    TeleportMeans spell = TeleportMeans.spell(row.requireWidth(9).text(2),
                            row.constant(Spellbook.class, 3), row.integer(4), row.optionalText(5), row.integer(6), runes(row, 8));
                    if (row.text(0).equals("swap")) {
                        if (swapRow != null) {
                            throw row.error("a second swap row");
                        }
                        swapRow = spell;
                    } else {
                        byPlace.computeIfAbsent(row.constant(Destination.class, 1), place -> new ArrayList<>()).add(spell);
                    }
                    break;
                case "tablet":
                    byPlace.computeIfAbsent(row.requireWidth(6).constant(Destination.class, 1),
                            place -> new ArrayList<>()).add(TeleportMeans.tablet(row.text(2), row.integer(3), row.optionalText(5)));
                    break;
                case "same":
                    List<TeleportMeans> shared = byPlace.get(row.requireWidth(3).constant(Destination.class, 2));
                    if (shared == null) {
                        throw row.error("no means above this line to share");
                    }
                    byPlace.put(row.constant(Destination.class, 1), shared);
                    break;
                case "runes":
                    byCapability.put(row.constant(Capability.class, 1),
                            Collections.unmodifiableMap(runes(row.requireWidth(3), 2)));
                    break;
                default:
                    throw row.error("no kind " + row.text(0));
            }
        }
        if (swapRow == null) {
            throw new IllegalStateException(RESOURCE + ": no swap row");
        }
        // Places that share means share one list, as the table says.
        Map<List<TeleportMeans>, List<TeleportMeans>> frozen = new IdentityHashMap<>();
        byPlace.replaceAll((place, list) -> frozen.computeIfAbsent(list, List::copyOf));
        MEANS = Collections.unmodifiableMap(byPlace);
        SPELL_COSTS = Collections.unmodifiableMap(byCapability);
        SPELLBOOK_SWAP = swapRow;
    }

    // After the table, which BY_SWAP reads.
    private static final Map<Destination, TeleportMeans> BY_SWAP = bySwap();

    /** Every way of reaching this place, spells before tablets. Never null. */
    public static List<TeleportMeans> to(Destination destination) {
        List<TeleportMeans> means = MEANS.get(destination);
        return means != null ? means : Collections.emptyList();
    }

    /**
     * Spellbook Swap then this place's spell from another book, or null when no spell off
     * Lunar reaches it. Not among {@link #to}: only a rung that names the swap offers it.
     */
    public static TeleportMeans bySwap(Destination destination) {
        return BY_SWAP.get(destination);
    }

    private static Map<Destination, TeleportMeans> bySwap() {
        Map<Destination, TeleportMeans> swaps = new EnumMap<>(Destination.class);
        for (Map.Entry<Destination, List<TeleportMeans>> place : MEANS.entrySet()) {
            for (TeleportMeans means : place.getValue()) {
                if (means.isSpell() && means.getSpellbook() != SPELLBOOK_SWAP.getSpellbook()) {
                    swaps.put(place.getKey(), TeleportMeans.afterSwap(SPELLBOOK_SWAP, means));
                    break;
                }
            }
        }
        return Collections.unmodifiableMap(swaps);
    }

    /**
     * What one cast of a capability spell costs, or empty for anything that is not cast.
     *
     * <p>Covers the spells with no destination: three cast at a patch, and the respawn
     * teleport, which lands wherever the player set it.
     */
    public static Map<Rune, Integer> runesFor(Capability capability) {
        Map<Rune, Integer> cost = SPELL_COSTS.get(capability);
        return cost != null ? cost : Collections.emptyMap();
    }

    /** The cell's rune-count pairs, each rune with its count. */
    private static Map<Rune, Integer> runes(Tables.Row row, int column) {
        String[] words = row.text(column).split(" ");
        if (words.length % 2 != 0) {
            throw row.error("runes come in rune-count pairs: " + row.text(column));
        }
        Map<Rune, Integer> runes = new EnumMap<>(Rune.class);
        for (int i = 0; i < words.length; i += 2) {
            try {
                runes.put(Rune.valueOf(words[i]), Integer.parseInt(words[i + 1]));
            } catch (IllegalArgumentException e) {
                throw row.error("not a rune and a count: " + words[i] + " " + words[i + 1]);
            }
        }
        return runes;
    }
}

package com.larryfarming.farming.detection;

import java.util.Arrays;
import java.util.stream.IntStream;

/**
 * Notices when an Ardougne cloak has actually spent one of its farm teleports.
 *
 * <p>The farm teleport is capped at three a day on a cloak 2 and five on a cloak 3. The game
 * reports no usable count: varbit 6069, the one named for the cloak, is a single bit and
 * cannot hold either number. So {@link com.larryfarming.farming.engine.DailyTeleportLedger}
 * counts uses as they happen, and this watch feeds it.
 *
 * <p><b>A click alone is not counted.</b> Clicking the option in the Wilderness, or with
 * the allowance gone, spends nothing, and overcounting would skip a patch silently. The
 * click only arms the watch. The use is recorded when the player arrives at the farm patch
 * within a few ticks, and an unanswered click times out. An arrival with no click behind it
 * (walking, fairy ring) is ignored.
 *
 * <p>No RuneLite types.
 */
public final class ArdougneFarmTeleportWatch {

    /** The option's name in the inventory, and when worn. */
    private static final String[] TELEPORT_OPTIONS = {"Farm Teleport", "Ardougne Farm"};

    private static final int[] CLOAK_ITEM_IDS = {13121, 13122, 13123, 13124};

    /**
     * Where the cloak drops the player: between the wiki's (2665, 3376) and RuneLite's world
     * map (2673, 3375), since the game scatters arrivals anyway.
     */
    private static final int LANDING_X = 2669;
    private static final int LANDING_Y = 3376;

    /**
     * Covers both published tiles and the scatter. It can be generous because nothing fires
     * without a {@link #clicked} from outside the square.
     */
    private static final int LANDING_RADIUS = 16;

    /**
     * A teleport resolves in three or four ticks. Ten allows for lag and still expires
     * before the player could walk in from outside the square.
     */
    private static final int WINDOW_TICKS = 10;

    private static final int NOT_ARMED = Integer.MIN_VALUE;

    private int armedAtTick = NOT_ARMED;

    /**
     * Whether this option is the farm teleport, under either name the game gives it.
     *
     * <p>Separate from {@link #isCloak} on purpose. The option is on the event, but the item
     * id is on the menu entry for an inventory click and on the equipment widget for a worn
     * cloak. The id on {@code MenuOptionClicked} is wrong for a worn cloak, so the caller
     * must look up the worn id itself. Check this cheap half first.
     */
    public static boolean isFarmTeleportOption(String option) {
        return option != null && Arrays.stream(TELEPORT_OPTIONS).anyMatch(option::equalsIgnoreCase);
    }

    /** Whether this item is an Ardougne cloak of any tier. */
    public static boolean isCloak(int itemId) {
        return IntStream.of(CLOAK_ITEM_IDS).anyMatch(id -> id == itemId);
    }

    /**
     * Arms the watch for a click made from {@code (x, y)}. Ignored when the player is already
     * at the patch, where an arrival would otherwise confirm itself at once.
     */
    public void clicked(int tick, int x, int y) {
        if (atLanding(x, y)) {
            return;
        }
        armedAtTick = tick;
    }

    /**
     * Offers the player's current position, and answers whether a teleport just landed.
     * True once per teleport, because the watch disarms as it answers.
     */
    public boolean arrived(int tick, int x, int y) {
        if (armedAtTick == NOT_ARMED) {
            return false;
        }
        if (tick - armedAtTick > WINDOW_TICKS || tick < armedAtTick) {
            armedAtTick = NOT_ARMED;
            return false;
        }
        if (!atLanding(x, y)) {
            return false;
        }
        armedAtTick = NOT_ARMED;
        return true;
    }

    /** Whether a click is waiting to be confirmed, so a quiet tick can skip the rest. */
    public boolean isArmed() {
        return armedAtTick != NOT_ARMED;
    }

    /** Forgets a pending click, for a logout or an account switch. */
    public void clear() {
        armedAtTick = NOT_ARMED;
    }

    private static boolean atLanding(int x, int y) {
        return Math.abs(x - LANDING_X) <= LANDING_RADIUS && Math.abs(y - LANDING_Y) <= LANDING_RADIUS;
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.model.PlayerState;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * The bottomless compost bucket: what it holds, read from the chat and dialogue lines that
 * state its uses, and whether it is stored at the tool leprechaun, which a varbit says
 * exactly.
 *
 * <p>No RuneLite client types.
 */
public final class BottomlessBucket {

    /** The compost kinds the bucket holds, weakest first. */
    public static final List<Crop> KINDS = List.of(Crop.COMPOST, Crop.SUPERCOMPOST, Crop.ULTRACOMPOST);

    /**
     * What the leprechaun is holding in the bucket's slot. The game's own
     * {@code farming_tools_getstored} script draws no bucket for 0, an empty one for 1 and a
     * filled one above 1.
     */
    private static final int STORED_TYPE_VARBIT = VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE;

    /** The uses in a bucket stored at the leprechaun. */
    private static final int STORED_USES_VARBIT = VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_QUANTITY;

    private static final int STORED_EMPTY = 1;

    /** The leprechaun's bucket varbits, read at login with the rest of its store. */
    public static final Set<Integer> STORED_VARBITS = Set.of(STORED_TYPE_VARBIT, STORED_USES_VARBIT);

    /** The three chat shapes that state the bucket's uses: checked, treated from, filled. */
    private static final Pattern USES = Pattern.compile(
            "compost bucket (?:is currently holding|has|now contains a total of) (one|a single|\\d[\\d,]{0,8}) uses?");

    /** The kind of compost a line names: the bucket's contents, or what was poured in. */
    private static final Pattern KIND = Pattern.compile("of (ultra|super|)compost");

    /** The lines that leave the bucket empty. */
    private static final Pattern EMPTIED = Pattern.compile(
            "compost bucket (?:is currently empty|doesn't currently have|has run out)|discard the contents");

    /**
     * The bucket empty and filled: one item in two states, either of which counts as owning
     * it. The leprechaun holds one, so a second is never taken.
     */
    public static final Set<Integer> ITEM_IDS = Set.of(ItemID.BOTTOMLESS_COMPOST_BUCKET, ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED);

    /** What the bucket was last read holding: the compost kind and the uses of it. */
    @Value
    public static class Reading {
        Crop kind;
        int uses;
    }

    private BottomlessBucket() {
    }

    /**
     * What a chat line or dialogue box says the bucket holds, or null when it is not a line
     * about the bucket's uses. A line that leaves the bucket empty reads as 0 uses.
     */
    public static Reading read(String text) {
        if (text == null || !text.contains("compost bucket")) {
            return null;
        }
        String plain = text.replace("<br>", " ").replaceAll("<[^>]*>", "");
        Matcher uses = USES.matcher(plain);
        Matcher kind = KIND.matcher(plain);
        if (!uses.find() || !kind.find()) {
            return EMPTIED.matcher(plain).find() ? new Reading(Crop.COMPOST, 0) : null;
        }
        String count = uses.group(1);
        int n = Character.isDigit(count.charAt(0)) ? Integer.parseInt(count.replace(",", "")) : 1;
        return new Reading(Crop.valueOf(kind.group(1).toUpperCase() + "COMPOST"), n);
    }

    /**
     * What the leprechaun's bucket holds, or null when it keeps none. An empty one reads as 0
     * uses of compost, so the bucket withdrawn and filled is not counted at an older reading.
     */
    public static Reading stored(PlayerState state) {
        Map<Integer, Integer> varbits = state == null ? Map.of() : state.getVarbits();
        int type = varbits.getOrDefault(STORED_TYPE_VARBIT, 0);
        if (type == STORED_EMPTY) {
            return new Reading(Crop.COMPOST, 0);
        }
        // Types 2, 3 and 4 are compost, supercompost and ultracompost.
        return type < 2 || type > 4 ? null
                : new Reading(KINDS.get(type - 2), varbits.getOrDefault(STORED_USES_VARBIT, 0));
    }

    /** Whether the player owns the bucket, carried, banked or at the tool leprechaun. */
    public static boolean owned(PlayerState state) {
        return toHand(state) || isStored(state);
    }

    /**
     * Whether the player owns the bucket as an item, carried or banked, so the bag can pack
     * it. One stored at the tool leprechaun is not to hand.
     */
    public static boolean toHand(PlayerState state) {
        return ItemCounts.ownsAny(state, ITEM_IDS);
    }

    /** Whether the bucket is at the tool leprechaun, empty or not. */
    public static boolean isStored(PlayerState state) {
        Integer type = state == null ? null : state.getVarbits().get(STORED_TYPE_VARBIT);
        return type != null && type >= STORED_EMPTY;
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.farming.catalogue.CarryItems;
import com.larryfarming.farming.engine.DailyTeleportLedger;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import java.util.*;
import lombok.AccessLevel;
import lombok.With;

/**
 * Answers what a player can currently do, both for single capabilities and for the
 * boolean expressions travel rungs are written as.
 *
 * <p>The game is the source, and the player is never asked; they may only declare what
 * their house holds before Larry has seen it. What cannot be read yet is either taken to be
 * absent (a house interior neither seen nor declared) or left
 * {@link CapabilityState#UNKNOWN}. An unknown route is still offered, but never preferred
 * over a certain one.
 */
public final class CapabilityResolver {

    /** Decides which teleport spells are castable without a swap. Defaults to Standard. */
    private final Spellbook onBook;

    /**
     * Today's spent rationed teleports, or null to skip allowance checks entirely. See
     * {@link #applyDailyLimit}.
     */
    private final DailyTeleportLedger dailyLedger;

    /** The instant {@link #dailyLedger} is read against, so its day rolls over correctly. */
    private final long nowEpochSec;

    /** Never null: a caller with nothing to offer gets {@link PatchSight#blind()}. */
    private final PatchSight sight;

    /** Never null: a caller with nothing to offer gets {@link HouseSight#unseen()}. */
    private final HouseSight house;

    /**
     * Whether the player's own position may answer a question. True for the stop they are
     * travelling to and false for every later stop, which they will have left by then.
     * Governs both {@link #teleport}'s already-there check and {@code STANDING_IN}, which
     * must switch together. See {@link #blindToPosition()}.
     */
    @With(AccessLevel.PRIVATE)
    private final boolean readsPosition;

    /** Travel methods the player has switched off. See {@link #switchingOff}. */
    @With(AccessLevel.PRIVATE)
    private final Set<TravelMethod> switchedOff;

    /** House items the player has declared built. See {@link #declaringHouse}. */
    @With(AccessLevel.PRIVATE)
    private final Set<Capability> houseDeclared;

    /**
     * The teleport already spent on the way to the next stop. Read only with
     * {@link #readsPosition}: it pays for the stop it was cast for, never a later one.
     */
    @With(AccessLevel.PRIVATE)
    private final TravelTaken taken;

    /** The book this resolver plans for: the one the trip will be walked on. */
    public Spellbook getBook() {
        return onBook;
    }

    /**
     * A resolver for this book, weighing daily teleport allowances (a null ledger never finds
     * one exhausted), what is growing in the player's patches, and what their house was last
     * seen to hold. Without a sight, patch capabilities such as a grown spirit tree read as
     * absent; without a house, every house capability does.
     */
    public CapabilityResolver(Spellbook onBook, DailyTeleportLedger dailyLedger, long nowEpochSec, PatchSight sight, HouseSight house) {
        this(onBook, dailyLedger, nowEpochSec, sight, house, true, Set.of(), Set.of(), TravelTaken.NONE);
    }

    /**
     * Every field in declaration order, which the {@code with} copies call. The Lombok copies
     * return this resolver only for an identical value, so the derivations below keep their
     * own {@code equals} checks for an equal one.
     */
    private CapabilityResolver(Spellbook onBook, DailyTeleportLedger dailyLedger,
            long nowEpochSec, PatchSight sight, HouseSight house, boolean readsPosition,
            Set<TravelMethod> switchedOff, Set<Capability> houseDeclared, TravelTaken taken) {
        this.onBook = onBook != null ? onBook : Spellbook.STANDARD;
        this.dailyLedger = dailyLedger;
        this.nowEpochSec = nowEpochSec;
        this.sight = sight != null ? sight : PatchSight.blind();
        this.house = house != null ? house : HouseSight.unseen();
        this.readsPosition = readsPosition;
        this.switchedOff = switchedOff;
        this.houseDeclared = houseDeclared;
        this.taken = taken;
    }

    /**
     * The same resolver, answering as though it did not know where the player was. Use it
     * for stops further down the trip, where the player's position will have changed.
     * Derived from this resolver so the two cannot drift in anything else they carry.
     */
    public CapabilityResolver blindToPosition() {
        return withReadsPosition(false);
    }

    /**
     * The same resolver, with these travel methods switched off. Feed it
     * {@code FarmingPreferences.travelOff()}.
     *
     * <p>A switched-off method fails every rung that needs it, wherever the rung leads: its
     * capabilities resolve as lacking, with the switch as the reason, and switched-off
     * tablets or Spellbook Swap never answer for a place. Routes, packing and skip reasons
     * all ask here, so all three follow the switch.
     */
    public CapabilityResolver switchingOff(Set<TravelMethod> methods) {
        Set<TravelMethod> wanted = methods == null || methods.isEmpty() ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(methods));
        return wanted.equals(switchedOff) ? this : withSwitchedOff(wanted);
    }

    /**
     * The same resolver, taking the player's word for these house items. Feed it
     * {@code FarmingPreferences.houseDeclared()}.
     *
     * <p>A declaration counts only for an item the house has not been seen to settle:
     * what was seen always wins, and a level or quest the player lacks still rules an item
     * out.
     */
    public CapabilityResolver declaringHouse(Set<Capability> declared) {
        Set<Capability> wanted = declared == null || declared.isEmpty() ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(declared));
        return wanted.equals(houseDeclared) ? this : withHouseDeclared(wanted);
    }

    /**
     * The same resolver, knowing the teleport the player has spent on the way to the stop
     * they are heading for. That stop reads the teleport as taken: no runes, tablet or ring
     * to bring for it.
     */
    public CapabilityResolver travelling(TravelTaken spent) {
        TravelTaken wanted = spent != null ? spent : TravelTaken.NONE;
        return wanted.equals(taken) ? this : withTaken(wanted);
    }

    /** Whether a spent teleport may answer for the stop this resolver plans. */
    public boolean hasTravelTaken() {
        return readsPosition && !taken.isNone();
    }

    /**
     * Whether this requirement names a travel item used up, or a place already teleported
     * to, on the way to the stop.
     */
    public boolean leansOnTravelTaken(Requirement requirement) {
        return hasTravelTaken() && (!Collections.disjoint(taken.getItems(), requirement.leafCapabilities())
                || !Collections.disjoint(taken.getPlaces(), requirement.leaves(Requirement.Kind.DESTINATION, Requirement::getDestination)));
    }

    /** The travel switch that fails this capability, or null while none does. */
    private TravelMethod switchFailing(Capability capability) {
        TravelMethod method = TravelMethod.of(capability);
        return method != null && switchedOff.contains(method) ? method : null;
    }

    /** Whether this resolver may answer from where the player is standing. */
    public boolean readsPosition() {
        return readsPosition;
    }

    /**
     * How this player would reach a place today: standing there already, then spell, then
     * a tablet they have not switched off.
     */
    public TeleportPlanner.Choice teleport(Destination destination, PlayerState state) {
        if (readsPosition && taken.reached(destination)) {
            return teleported(destination);
        }
        return TeleportPlanner.best(destination, state, onBook, readsPosition, tabletsOff(destination));
    }

    /**
     * {@link #teleport}, for the place a rung arrives at: by Spellbook Swap where the rung
     * names the swap.
     */
    public TeleportPlanner.Choice teleportFor(Requirement rung, Destination destination, PlayerState state) {
        if (rung.contains(Requirement.reachBySwap(destination))) {
            return bySwap(destination, state);
        }
        return teleport(destination, state);
    }

    /**
     * Taken already: no means, so the bag asks for nothing, as for a player standing in the
     * place's zone.
     */
    private static TeleportPlanner.Choice teleported(Destination destination) {
        return new TeleportPlanner.Choice(null, CapabilityState.HAVE, "you have teleported to " + destination.getDisplayName());
    }

    /**
     * The switch that refuses this place's tablet, or null while the tablet is allowed:
     * tablets are on, and so is this place's own tablet where it has a switch of its own.
     */
    private TravelMethod tabletsOff(Destination destination) {
        if (switchedOff.contains(TravelMethod.TELEPORT_TABLETS)) {
            return TravelMethod.TELEPORT_TABLETS;
        }
        if (destination == Destination.SALVE_GRAVEYARD && switchedOff.contains(TravelMethod.SALVE_GRAVEYARD_TABLETS)) {
            return TravelMethod.SALVE_GRAVEYARD_TABLETS;
        }
        return null;
    }

    /** {@link TeleportPlanner#bySwap}, unless the player has switched the swap off. */
    private TeleportPlanner.Choice bySwap(Destination destination, PlayerState state) {
        if (switchedOff.contains(TravelMethod.SPELLBOOK_SWAP)) {
            return new TeleportPlanner.Choice(null, CapabilityState.LACK, TravelMethod.SPELLBOOK_SWAP.switchedOffReason());
        }
        if (readsPosition && taken.reached(destination)) {
            return teleported(destination);
        }
        return TeleportPlanner.bySwap(destination, state, onBook, readsPosition);
    }

    /**
     * What the player can do about this one capability, and why we think so. A capability
     * whose travel method the player switched off is lacking, whatever they own.
     */
    public CapabilityVerdict resolve(Capability capability, PlayerState state) {
        TravelMethod off = switchFailing(capability);
        if (off != null) {
            return CapabilityVerdict.lack(CapabilityVerdict.Source.DECLARED, off.switchedOffReason());
        }
        if (readsPosition && taken.used(capability)) {
            return CapabilityVerdict.have(CapabilityVerdict.Source.DETECTED,
                    "you have used your " + capability.getDisplayName() + " on the way");
        }
        CapabilityVerdict verdict = resolveOwnership(capability, state);
        if (verdict.getState() != CapabilityState.HAVE) {
            return verdict;
        }
        CapabilityVerdict rationed = applyDailyLimit(capability, state);
        return rationed != null ? rationed : verdict;
    }

    /** {@link #resolve}, before today's teleport allowance gets a say. */
    private CapabilityVerdict resolveOwnership(Capability capability, PlayerState state) {
        // A spell on another book is a LACK for this plan, whatever the account has
        // unlocked. ANY means no book is settled, so it falls through to the rules.
        Spellbook needs = CapabilitySources.spellbookFor(capability);
        if (needs != null && onBook != Spellbook.ANY && needs != onBook) {
            return CapabilityVerdict.lack(CapabilityVerdict.Source.DETECTED,
                    capability.getDisplayName() + " is on the " + needs.getDisplayName()
                            + " spellbook. You are on the " + onBook.getDisplayName() + " spellbook");
        }
        if (CapabilitySources.isDetectable(capability)) {
            CapabilityVerdict detected = CapabilitySources.resolve(capability, state, sight, house, houseDeclared);
            // A rule can still answer UNKNOWN, e.g. a varbit the login scan has not read.
            if (detected.getState() != CapabilityState.UNKNOWN) {
                return detected;
            }
        }
        return CapabilityVerdict.unknown("not sure whether you have " + capability.getDisplayName());
    }

    /**
     * Downgrades an owned capability to {@code LACK} when today's allowance for it is
     * spent, or returns null to leave the ownership verdict standing.
     *
     * <p>The allowance belongs to the tier the player holds, not the tier a chain names: a
     * chain asking for Explorer's ring 2 from a player holding ring 3 has no daily limit.
     * Every tier of the family is re-resolved through {@link #resolveOwnership} (not
     * {@link #resolve}, which would recurse) and {@link Capability#bestHeldTier} picks the
     * one to ask the ledger about.
     */
    private CapabilityVerdict applyDailyLimit(Capability capability, PlayerState state) {
        if (dailyLedger == null) {
            return null;
        }
        Capability held = capability;
        // Substituting the held tier may only relax a ration, never impose one. An
        // Ardougne cloak 1's Monastery teleport is unlimited, and must not inherit cloak 2's
        // farm-teleport limit.
        if (capability.isRationedDaily() && capability.getTierFamily() != Capability.TierFamily.NONE) {
            Set<Capability> owned = new HashSet<>();
            for (Capability tier : Capability.values()) {
                if (tier.getTierFamily() == capability.getTierFamily()
                        && resolveOwnership(tier, state).getState() == CapabilityState.HAVE) {
                    owned.add(tier);
                }
            }
            held = Capability.bestHeldTier(capability.getTierFamily(), owned);
        }
        if (held == null || !held.isRationedDaily()) {
            return null;
        }
        if (dailyLedger.isExhausted(held, nowEpochSec)) {
            return CapabilityVerdict.lack(CapabilityVerdict.Source.DETECTED,
                    "you have used today's " + held.getDisplayName() + " teleports");
        }
        return null;
    }

    /**
     * Whether a travel rung's requirement holds.
     *
     * <p>{@code reachedPatches} maps the stops already planned for this run to how sure each
     * one is, so a rung like "run north from the Falador tree patch" is free for a player
     * going there anyway. A rung standing on an uncertain stop inherits its uncertainty.
     */
    public CapabilityState evaluate(Requirement requirement, PlayerState state, Map<PatchRef, CapabilityState> reachedPatches) {
        return evaluateGranting(requirement, null, state, reachedPatches);
    }

    /**
     * {@link #evaluate}, reading one sub-expression as held. Asks whether a rung would hold
     * but for that part, such as a fairy ring rung but for a way to stand at a ring.
     *
     * @param granted the part read as held, or null for none
     */
    public CapabilityState evaluateGranting(Requirement requirement, Requirement granted,
            PlayerState state, Map<PatchRef, CapabilityState> reachedPatches) {
        if (granted != null && requirement.equals(granted)) {
            return CapabilityState.HAVE;
        }
        switch (requirement.getKind()) {
            case CAPABILITY:
                return resolve(requirement.getCapability(), state).getState();
            case DESTINATION:
                return (requirement.isBySwap() ? bySwap(requirement.getDestination(), state)
                        : teleport(requirement.getDestination(), state)).getState();
            case REACHED_PATCH:
                return reachedPatches == null ? CapabilityState.LACK : reachedPatches.getOrDefault(requirement.getPatch(),
                                CapabilityState.LACK);
            // Never UNKNOWN: a wrongly assumed position costs the teleport the player did
            // not pack, so an unread region is a no.
            case STANDING_IN:
                return readsPosition && state != null && requirement.getZone().covers(state.getRegionId()) ? CapabilityState.HAVE
                        : CapabilityState.LACK;
            case ALL:
                return CapabilityState.all(evaluateParts(requirement, granted, state, reachedPatches));
            case ANY:
                return CapabilityState.any(evaluateParts(requirement, granted, state, reachedPatches));
            default:
                throw new IllegalArgumentException("unknown requirement kind " + requirement.getKind());
        }
    }

    private List<CapabilityState> evaluateParts(Requirement requirement, Requirement granted,
            PlayerState state, Map<PatchRef, CapabilityState> reachedPatches) {
        List<CapabilityState> states = new ArrayList<>(requirement.getParts().size());
        for (Requirement part : requirement.getParts()) {
            states.add(evaluateGranting(part, granted, state, reachedPatches));
        }
        return states;
    }

    /**
     * The capabilities this rung leans on for this player, which can be fewer than it
     * mentions. Under an "or" only the taken branch counts (see {@link #takenBranch}).
     * When no branch is settled, every capability the "or" mentions stands.
     */
    public Set<Capability> reliedOn(Requirement requirement, PlayerState state, Map<PatchRef, CapabilityState> reachedPatches) {
        switch (requirement.getKind()) {
            // A travel item already used up on the way has nothing left to pack.
            case CAPABILITY:
                return readsPosition && taken.used(requirement.getCapability()) ? Collections.emptySet()
                        : Collections.singleton(requirement.getCapability());
            // A destination is packed for from the teleport the planner chooses (see
            // reliedOnDestination). The other two name ground, not anything to bring.
            case DESTINATION:
            case REACHED_PATCH:
            case STANDING_IN:
                return Collections.emptySet();
            case ALL: {
                Set<Capability> needed = new LinkedHashSet<>();
                for (Requirement part : requirement.getParts()) {
                    needed.addAll(reliedOn(part, state, reachedPatches));
                }
                return needed;
            }
            case ANY: {
                Requirement taken = takenBranch(requirement, state, reachedPatches);
                if (taken != null) {
                    return reliedOn(taken, state, reachedPatches);
                }
                return requirement.leafCapabilities();
            }
            default:
                throw new IllegalArgumentException("unknown requirement kind " + requirement.getKind());
        }
    }

    /**
     * The place this rung actually travels to for this player, or null when it names none.
     *
     * <p>The counterpart of {@link #reliedOn} for rungs that are an "or" of items and a place,
     * such as the fairy ring approaches with a Salve graveyard teleport among them. The bag
     * packs the teleport chosen to reach the place.
     *
     * <p>Only the taken branch counts. An "or" nothing settles contributes no destination,
     * unlike {@code reliedOn}'s widest-answer fallback, because a teleport named in error is a
     * consumable withdrawn and spent.
     */
    public Destination reliedOnDestination(Requirement requirement, PlayerState state, Map<PatchRef, CapabilityState> reachedPatches) {
        switch (requirement.getKind()) {
            case DESTINATION:
                return requirement.getDestination();
            case ALL:
                for (Requirement part : requirement.getParts()) {
                    Destination found = reliedOnDestination(part, state, reachedPatches);
                    if (found != null) {
                        return found;
                    }
                }
                return null;
            case ANY: {
                Requirement taken = takenBranch(requirement, state, reachedPatches);
                return taken == null ? null : reliedOnDestination(taken, state, reachedPatches);
            }
            default:
                return null;
        }
    }

    /**
     * The branch of an "or" the player would take: the first {@code HAVE}, else the first
     * {@code UNKNOWN}, or null when every branch is a {@code LACK}.
     *
     * <p>That picks the branch the route took only while the unknowns under one "or" are
     * interchangeable, so the catalogue must keep {@code REACHED_PATCH} out from under an
     * "or".
     *
     * <p>Public so the planner can rank a rung by the walk of the way in it takes, from the
     * same answer the bag packs for.
     */
    public Requirement takenBranch(Requirement requirement, PlayerState state, Map<PatchRef, CapabilityState> reachedPatches) {
        Requirement taken = firstMatching(requirement, state, reachedPatches, CapabilityState.HAVE);
        return taken != null ? taken : firstMatching(requirement, state, reachedPatches, CapabilityState.UNKNOWN);
    }

    /** The first part of an "or" in the state asked for. */
    private Requirement firstMatching(Requirement requirement, PlayerState state,
            Map<PatchRef, CapabilityState> reachedPatches, CapabilityState wanted) {
        for (Requirement part : requirement.getParts()) {
            if (evaluate(part, state, reachedPatches) == wanted) {
                return part;
            }
        }
        return null;
    }

    /**
     * How far a rung is from holding, nearest first after {@link #NONE}. A skip names the
     * best-ranked rung with the nearest gap.
     */
    public enum Gap {
        /** Nothing to name: the rung holds, or it wants only ground the run does not cover. */
        NONE,
        /**
         * Only a restock of what the player already has: runes for a spell on the open book
         * whose level and quest are met, or charges for an item they own.
         */
        RESTOCK,
        /**
         * Only a teleport to a place: a spell short of its Magic level, or a tablet to buy.
         */
        TELEPORT,
        /** Items the player has none of, and could buy, make or win today. */
        ITEM,
        /**
         * A quest, diary, level or other flag, or a switch the player turned off. Also an
         * item or a place behind one the player lacks: a skill cape below 99, a quest's
         * reward, a tablet whose quest is unfinished.
         */
        UNLOCK
    }

    /**
     * The gap between a rung and this player. An "all" is as far as its farthest part, an
     * "or" as near as its nearest, and an "or" with a branch held has no gap. Reached patches
     * and positions count as no gap, as in {@link #explainShortfall}.
     */
    public Gap gapTo(Requirement requirement, PlayerState state) {
        switch (requirement.getKind()) {
            case CAPABILITY:
                return gapToCapability(requirement.getCapability(), state);
            case DESTINATION:
                return gapToPlace(requirement, state);
            case REACHED_PATCH:
            case STANDING_IN:
                return Gap.NONE;
            case ALL: {
                Gap farthest = Gap.NONE;
                for (Requirement part : requirement.getParts()) {
                    Gap gap = gapTo(part, state);
                    if (gap.compareTo(farthest) > 0) {
                        farthest = gap;
                    }
                }
                return farthest;
            }
            case ANY: {
                Gap nearest = Gap.NONE;
                for (Requirement part : requirement.getParts()) {
                    if (evaluate(part, state, null) == CapabilityState.HAVE) {
                        return Gap.NONE;
                    }
                    Gap gap = gapTo(part, state);
                    if (gap != Gap.NONE && (nearest == Gap.NONE || gap.compareTo(nearest) < 0)) {
                        nearest = gap;
                    }
                }
                return nearest;
            }
            default:
                throw new IllegalArgumentException("unknown requirement kind " + requirement.getKind());
        }
    }

    /**
     * A carried item the player owns yet cannot use is a restock: an empty Book of the Dead,
     * or an Explorer's ring with today's teleports spent. An item whose source asks for
     * something the player lacks, such as a cape behind every diary, is an unlock, and so is
     * an item the player switched off. Any other item read from the bank is one to get, and
     * anything read from a flag is an unlock.
     */
    private Gap gapToCapability(Capability capability, PlayerState state) {
        if (resolve(capability, state).getState() == CapabilityState.HAVE) {
            return Gap.NONE;
        }
        if (switchFailing(capability) != null) {
            return Gap.UNLOCK;
        }
        CarryItems.Carry carry = CarryItems.forCapability(capability);
        if (carry != null && state != null) {
            for (int itemId : carry.getItemIds()) {
                if (ItemCounts.ownsAny(state, itemId)) {
                    return Gap.RESTOCK;
                }
            }
        }
        return capability.getDetectability() == Capability.Detectability.ITEM && !CapabilitySources.isBarredFromGetting(capability, state)
                ? Gap.ITEM : Gap.UNLOCK;
    }

    /**
     * A spell on the open book short only of runes is a restock, and any other way in that
     * no unfinished quest bars is a teleport to get. A place whose every way in waits on a
     * quest, or on tablets or a swap the player switched off, is an unlock.
     */
    private Gap gapToPlace(Requirement place, PlayerState state) {
        Destination destination = place.getDestination();
        boolean tablets = tabletsOff(destination) == null;
        TeleportPlanner.Choice choice = place.isBySwap() ? bySwap(destination, state) : teleport(destination, state);
        if (choice.getState() == CapabilityState.HAVE) {
            return Gap.NONE;
        }
        if (place.isBySwap()) {
            return !switchedOff.contains(TravelMethod.SPELLBOOK_SWAP) && TeleportPlanner.isOpenBySwap(destination, state, onBook)
                    ? Gap.TELEPORT : Gap.UNLOCK;
        }
        if (TeleportPlanner.wantsOnlyRunes(destination, state, onBook)) {
            return Gap.RESTOCK;
        }
        return TeleportPlanner.isOpenToGet(destination, state, onBook, tablets) ? Gap.TELEPORT : Gap.UNLOCK;
    }

    /**
     * What stands between a rung and the player, to explain a skip: the reasons for the
     * first two unmet destinations and capabilities, or "" when nothing is missing.
     *
     * <p>Ignores reached patches. A rung that fell through because the run skips its
     * neighbouring patch has no item to name.
     */
    public String explainShortfall(Requirement requirement, PlayerState state) {
        Set<Destination> places = new LinkedHashSet<>();
        Set<Capability> capabilities = new LinkedHashSet<>();
        collectExplained(requirement, state, places, capabilities);
        List<String> missing = new ArrayList<>();
        for (Destination destination : places) {
            TeleportPlanner.Choice choice = teleportFor(requirement, destination, state);
            // Varrock and the Grand Exchange share a spell and a tablet, so both can give
            // the same reason; it reads once.
            if (choice.getState() != CapabilityState.HAVE && !missing.contains(choice.getBecause())) {
                missing.add(choice.getBecause());
            }
        }
        for (Capability capability : capabilities) {
            CapabilityVerdict verdict = resolve(capability, state);
            if (verdict.getState() != CapabilityState.HAVE) {
                missing.add(verdict.getBecause());
            }
        }
        // Empty for nothing missing, the one reason alone, or the first two joined.
        return String.join(", and ", missing.subList(0, Math.min(2, missing.size())));
    }

    /**
     * The places and capabilities a shortfall names, in the order the requirement lists
     * them. Under an "or", a way in that also asks for a capability the player lacks is left
     * out while another way stays open. Without the medium Varrock diary the Grand Exchange
     * landing is no way in, and naming it would point the player at a landing they cannot
     * choose, or spend one of the two reasons on it.
     */
    private void collectExplained(Requirement requirement, PlayerState state, Set<Destination> places, Set<Capability> capabilities) {
        switch (requirement.getKind()) {
            case DESTINATION:
                places.add(requirement.getDestination());
                return;
            case CAPABILITY:
                capabilities.add(requirement.getCapability());
                return;
            case ALL:
                for (Requirement part : requirement.getParts()) {
                    collectExplained(part, state, places, capabilities);
                }
                return;
            case ANY: {
                List<Requirement> open = new ArrayList<>();
                for (Requirement way : requirement.getParts()) {
                    if (!asksForALack(way, state)) {
                        open.add(way);
                    }
                }
                for (Requirement way : open.isEmpty() ? requirement.getParts() : open) {
                    collectExplained(way, state, places, capabilities);
                }
                return;
            }
            default:
                return;
        }
    }

    /** Whether this "and" asks, directly, for a capability the player lacks. */
    private boolean asksForALack(Requirement way, PlayerState state) {
        if (way.getKind() != Requirement.Kind.ALL) {
            return false;
        }
        for (Requirement part : way.getParts()) {
            if (part.getKind() == Requirement.Kind.CAPABILITY && resolve(part.getCapability(), state).getState() == CapabilityState.LACK) {
                return true;
            }
        }
        return false;
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.data.Tables;
import com.larryfarming.engine.ItemCounts;
import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.*;
import com.larryfarming.farming.detection.CapabilityVerdict.Source;
import com.larryfarming.farming.model.Capability;
import com.larryfarming.farming.model.Spellbook;
import com.larryfarming.model.*;
import java.util.*;
import java.util.stream.IntStream;
import java.util.stream.Stream;
import net.runelite.api.gameval.ItemID;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Value;
import net.runelite.api.gameval.VarbitID;

/**
 * How each capability is answered from game state.
 *
 * <p>Kept apart from the capability vocabulary so detection rules change without touching
 * the catalogue.
 *
 * <p>A capability with no rule resolves {@link CapabilityState#UNKNOWN}, which the planner
 * still offers. Adding a rule only narrows an unknown into a definite answer.
 *
 * <p>Item ownership goes through {@link ItemCounts}, which knows about the bank, the
 * tool leprechaun and the rune pouch.
 */
public final class CapabilitySources {

    private CapabilitySources() {
    }

    /** Answers one capability, or returns null to leave it unknown. */
    @FunctionalInterface
    private interface Detector {
        CapabilityVerdict detect(PlayerState state);
    }

    /**
     * Answers one capability that is really a farming patch, given what has been seen in it.
     * Separate from {@link Detector} because only a few rules need a patch.
     */
    @FunctionalInterface
    private interface PatchDetector {
        CapabilityVerdict detect(PlayerState state, PatchSight sight);
    }

    /** Which spellbook is open. */
    public static final int SPELLBOOK_VARBIT = 4070;

    /**
     * What {@link #SPELLBOOK_VARBIT} reads on each book. Being on a book proves its unlock
     * (Lunar Diplomacy for Lunar, Sins of the Father for Arceuus), so a caller gating a spell
     * on the book needs no separate quest check.
     */
    public static final int STANDARD_SPELLBOOK = 0;
    public static final int LUNAR_SPELLBOOK = 2;
    public static final int ARCEUUS_SPELLBOOK = 3;

    /**
     * The Knight Waves Training Grounds, which opens Camelot as a respawn point. Value 8 is
     * the finished state.
     */
    private static final int KNIGHT_WAVES_VARBIT = 3909;
    private static final int KNIGHT_WAVES_DONE = 8;

    /**
     * Fairytale II's progress value (varbit 2326) once the Fairy Godfather grants the
     * fairy rings. See {@code fairyRings} for the sources.
     */
    public static final int FAIRY_RING_PERMISSION_STAGE = 40;

    /**
     * Where the player respawns, as one flag per town. At most one is set.
     *
     * <p>Lumbridge needs no unlock and has no flag: every scanned flag reading zero means
     * Lumbridge.
     *
     * <p>The towns come from the client's names for these ids. Edgeville and the Wilderness
     * also carry a separate {@code _UNLOCKED} varbit, which indicates the bare flag records
     * the choice rather than the unlock.
     *
     * <p>Unordered: one set flag names one town, and two set flags name none, whichever is
     * read first.
     */
    private static final Map<Integer, String> RESPAWN_TOWNS = Map.of(
            VarbitID.FALADOR_SPAWN, "Falador",
            VarbitID.EDGEVILLE_SPAWN, "Edgeville",
            VarbitID.CAMELOT_SPAWN, "Camelot",
            VarbitID.WILDERNESS_SPAWN, "Ferox Enclave",
            VarbitID.CIVITAS_SPAWN, "Civitas illa Fortis",
            VarbitID.KOUREND_SPAWN, "Kourend Castle");

    /** What opens each respawn town, separate from whether it is the chosen one. */
    private static final Map<String, Detector> RESPAWN_UNLOCKS = respawnUnlocks();

    private static Map<String, Detector> respawnUnlocks() {
        Map<String, Detector> unlocks = new LinkedHashMap<>();
        unlocks.put("Falador", quest("Recruitment Drive", "respawning at Falador"));
        unlocks.put("Camelot", state -> {
            Integer done = state.getVarbits().get(KNIGHT_WAVES_VARBIT);
            if (done != null) {
                return done >= KNIGHT_WAVES_DONE ? CapabilityVerdict.have(Source.DETECTED,
                                "you have finished the Knight Waves Training Grounds") : CapabilityVerdict.lack(Source.DETECTED,
                                "the Knight Waves Training Grounds unlocks respawning at Camelot");
            }
            return quest("King's Ransom", "respawning at Camelot").detect(state);
        });
        return Collections.unmodifiableMap(unlocks);
    }

    /**
     * Whether the account could choose this respawn town, ignoring the one it is on.
     * {@code RESPAWN_AVAILABLE_*} answers "do you respawn there" instead, so it cannot
     * suggest a switch.
     */
    public static CapabilityState canSelectRespawn(String town, PlayerState state) {
        Detector unlock = RESPAWN_UNLOCKS.get(town);
        return unlock == null ? CapabilityState.UNKNOWN : unlock.detect(state).getState();
    }

    /**
     * The town the player respawns in, or null when the flags have not been read yet or
     * contradict each other. Null is not Lumbridge.
     */
    public static String selectedRespawnTown(PlayerState state) {
        if (state == null) {
            return null;
        }
        boolean scanned = false;
        String chosen = null;
        for (Map.Entry<Integer, String> town : RESPAWN_TOWNS.entrySet()) {
            Integer value = state.getVarbits().get(town.getKey());
            if (value == null) {
                continue;
            }
            scanned = true;
            if (value == 0) {
                continue;
            }
            // Two towns set at once is a contradiction. Answer nothing, so callers fall back
            // to judging by the unlock.
            if (chosen != null) {
                return null;
            }
            chosen = town.getValue();
        }
        if (chosen != null) {
            return chosen;
        }
        return scanned ? "Lumbridge" : null;
    }

    /** The assigned farming contract's crop, and whether it has finished growing. */
    public static final int CONTRACT_PRODUCE_VARBIT = 7963;
    public static final int CONTRACT_COMPLETE_VARBIT = 7961;

    /** Set once the Lunch by the Lancalliums page is in Kharedst's memoirs. */
    public static final int LANCALLIUMS_PAGE_VARBIT = VarbitID.HOSIDIUS_PAGE;

    /** Charges left in Kharedst's memoirs or the Book of the Dead. */
    public static final int MEMOIRS_CHARGES_VARBIT = VarbitID.VEOS_MEMOIR_CHARGES;

    /** Kharedst's memoirs and the Book of the Dead, which share the page and the charges. */
    private static final int[] LANCALLIUMS_BOOK_IDS = {
        ItemID.VEOS_KHAREDSTS_MEMOIRS, ItemID.BOOK_OF_THE_DEAD,
    };

    /**
     * The simple rules, one row each, and two tables of facts: the quest gating an item only
     * that quest hands out ({@code gate}), and the skill each Cape of Accomplishment needs at
     * 99 ({@code cape}). The first cell names the kind, which fixes the columns after it.
     *
     * <p>Declared above {@link #LOGIN_SCAN_VARBIT_IDS}, which scans the flags its varbit and
     * balloon rows read.
     */
    private static final List<Tables.Row> TABLE = Tables.read("/com/larryfarming/capability-rules.tsv");

    /**
     * The varbits this package reads that nothing else in the plugin asks for. Most are set
     * once and silent afterwards, so without a login scan they read as unset for players who
     * set them before installing the plugin.
     */
    public static final int[] LOGIN_SCAN_VARBIT_IDS = loginScanVarbitIds();

    private static int[] loginScanVarbitIds() {
        // The table's flags: Ates statues, quetzal landing sites, balloon stations, the
        // bare-handed planting lesson.
        IntStream flags = TABLE.stream()
                .filter(row -> row.text(0).equals("varbit") || row.text(0).equals("balloon"))
                .mapToInt(row -> row.integer(2));
        int[] own = {
            HouseLocation.HOUSE_LOCATION_VARBIT,
            SPELLBOOK_VARBIT,
            KNIGHT_WAVES_VARBIT,
            // A contract assigned before login never announces itself.
            CONTRACT_PRODUCE_VARBIT,
            CONTRACT_COMPLETE_VARBIT,
        };
        int[] books = {LANCALLIUMS_PAGE_VARBIT, MEMOIRS_CHARGES_VARBIT};
        IntStream fixed = Stream.of(own, books, DiaryTiers.allVarbits()).flatMapToInt(IntStream::of);
        // The respawn flags, and the counters of rationed teleports spent today: a day's
        // allowance can be part spent before the plugin starts.
        IntStream keyed = Stream.concat(RESPAWN_TOWNS.keySet().stream(), DiaryRewards.USES_SPENT_BY_VARBIT.keySet().stream())
                .mapToInt(Integer::intValue);
        return IntStream.concat(IntStream.concat(fixed, keyed), flags).toArray();
    }

    /** A quest, and how far along it a player must be. */
    @Value
    private static class QuestGate {
        String quest;
        QuestStatus reached;

        /** True when the player is seen short of the quest. An unread quest bars nothing. */
        boolean bars(PlayerState state) {
            QuestStatus status = state.getQuests().get(quest);
            return status != null && !hasReached(status, reached);
        }
    }

    /** Items only a quest hands out, or that work only once it is done; {@link #questItems} checks the gate. */
    private static final Map<Capability, QuestGate> QUEST_GATES = new EnumMap<>(Capability.class);

    /** Capes of Accomplishment, sold only to a player with 99 in the skill. */
    private static final Map<Capability, Skill> SKILL_CAPES = new EnumMap<>(Capability.class);

    static {
        for (Tables.Row row : TABLE) {
            if (row.text(0).equals("gate")) {
                QUEST_GATES.put(row.requireWidth(4).constant(Capability.class, 1),
                        new QuestGate(row.text(2), row.constant(QuestStatus.class, 3)));
            } else if (row.text(0).equals("cape")) {
                SKILL_CAPES.put(row.requireWidth(3).constant(Capability.class, 1), row.constant(Skill.class, 2));
            }
        }
    }

    private static final int SKILL_MASTERY = 99;

    /**
     * Whether the player is seen short of what an item's source asks before it hands one
     * over: a skill cape's 99, a quest's reward. Such an item is an unlock to earn, not an
     * errand. False for anything a shop, a craft or a drop gives anyone.
     *
     * <p>The Achievement diary cape and the Quest point cape always answer true. Larry reads
     * neither every diary nor every quest, so a player without the cape is taken not to
     * have earned it.
     */
    public static boolean isBarredFromGetting(Capability capability, PlayerState state) {
        if (capability == Capability.DIARY_CAPE || capability == Capability.QUEST_CAPE) {
            return true;
        }
        if (state == null) {
            return false;
        }
        Skill skill = SKILL_CAPES.get(capability);
        if (skill != null) {
            return state.getSkillLevel(skill) < SKILL_MASTERY;
        }
        QuestGate gate = QUEST_GATES.get(capability);
        return gate != null && gate.bars(state);
    }

    private static final Map<Capability, Detector> RULES = rules();

    private static final Map<Capability, PatchDetector> PATCH_RULES = patchRules();

    private static final Map<Capability, HouseRule> HOUSE_RULES = houseRules();

    /**
     * The capabilities that are farming patches, answered from the patch.
     *
     * <p>The spirit-tree rules treat an unseen patch as empty, unlike
     * {@code FarmingInputs.patchAt}'s "no reason to change the plan". A wrong no costs a
     * slower route until the player next walks past. {@link #weissHerbPatch} is the exception.
     */
    private static Map<Capability, PatchDetector> patchRules() {
        Map<Capability, PatchDetector> rules = new EnumMap<>(Capability.class);
        rules.put(Capability.SPIRIT_TREE_GROWN_BRIMHAVEN, grownSpiritTree(Capability.SPIRIT_TREE_GROWN_BRIMHAVEN, 83, "Brimhaven"));
        // 85 rather than 83: the patch is in the guild's north wing.
        rules.put(Capability.SPIRIT_TREE_GROWN_FARMING_GUILD, grownSpiritTree(Capability.SPIRIT_TREE_GROWN_FARMING_GUILD, 85,
                        "Farming Guild"));
        rules.put(Capability.SPIRIT_TREE_GROWN_PORT_SARIM, grownSpiritTree(Capability.SPIRIT_TREE_GROWN_PORT_SARIM, 83, "Port Sarim"));
        rules.put(Capability.WEISS_HERB_PATCH, weissHerbPatch());
        return rules;
    }

    /**
     * The capabilities built in the player's house, answered from what was seen there.
     *
     * <p>Levels are base levels. The Nexus refuses a boosted Magic level, but the portal
     * chamber accepts one (wiki), so a chamber portal's floor names no Magic level.
     *
     * @see HouseRule#detect for the order the answers are given in
     */
    private static Map<Capability, HouseRule> houseRules() {
        Map<Capability, HouseRule> rules = new EnumMap<>(Capability.class);
        // Chamber portals all need 50 Construction. The Troll Stronghold portal is directed
        // with salts and basalt, so it asks for no Magic level.
        rules.put(Capability.POH_PORTAL_WEISS, portal(HouseFeature.PORTAL_WEISS, "a Weiss portal", "Making Friends with My Arm"));
        rules.put(Capability.POH_PORTAL_TROLL_STRONGHOLD, portal(HouseFeature.PORTAL_TROLL_STRONGHOLD, "a Troll Stronghold portal",
                        "Making Friends with My Arm"));
        rules.put(Capability.POH_PORTAL_KOUREND, portal(HouseFeature.PORTAL_KOUREND, "a Kourend portal", "Client of Kourend"));
        rules.put(Capability.POH_PORTAL_FENKENSTRAIN, portal(HouseFeature.PORTAL_FENKENSTRAIN,
                "a Fenkenstrain's Castle portal", "Priest in Peril"));
        rules.put(Capability.POH_PORTAL_HARMONY, portal(HouseFeature.PORTAL_HARMONY, "a Harmony Island portal", "The Great Brain Robbery"));
        // The Nexus room needs 72 Construction, and the Nexus asks for the teleport's own
        // Magic level on top.
        rules.put(Capability.POH_NEXUS_WEISS, nexus(PortalNexus.WEISS, "Weiss", "Making Friends with My Arm", 66));
        rules.put(Capability.POH_NEXUS_TROLL_STRONGHOLD, nexus(PortalNexus.TROLL_STRONGHOLD,
                "the Troll Stronghold", "Making Friends with My Arm", 66));
        rules.put(Capability.POH_NEXUS_HARMONY, nexus(PortalNexus.HARMONY_ISLAND, "Harmony Island", "The Great Brain Robbery", 65));
        rules.put(Capability.POH_SPIRIT_TREE, built(HouseFeature.SPIRIT_TREE, "a spirit tree", floor("a spirit tree in your house")
                        .construction(75).skill(Skill.FARMING, 83)));
        rules.put(Capability.POH_FAIRY_RING, built(HouseFeature.FAIRY_RING, "a fairy ring", floor("a fairy ring in your house")
                        .construction(85)));
        return Collections.unmodifiableMap(rules);
    }

    private static HouseRule portal(HouseFeature feature, String what, String quest) {
        return built(feature, what, floor(what).construction(50).quest(quest));
    }

    private static HouseRule nexus(int destination, String where, String quest, int magic) {
        return attuned(destination, where, floor(where + " in your Portal Nexus")
                .construction(72).quest(quest).skill(Skill.MAGIC, magic));
    }

    /** How a player who has not been seen with a house item can make it count. */
    private static final String TICK_IT = " or tick it under Your house";

    /**
     * One capability built in the player's house: what settles it from a sighting, the
     * levels and quests below which it cannot exist, and the words for each answer.
     *
     * <p>Either a piece of furniture, answered from the last scan of the house, or a Portal
     * Nexus destination, answered from the Nexus. See {@link #built} and {@link #attuned}.
     */
    @AllArgsConstructor(access = AccessLevel.PRIVATE)
    private static final class HouseRule {
        private final Floor floor;

        /** The furniture looked for, or null for a Portal Nexus destination. */
        private final HouseFeature feature;

        /** The Nexus destination's enum 1377 key; unused for furniture. */
        private final int destination;

        /** What the rule counts, as the "isn't counted until you …" answer names it: "a Weiss portal". */
        private final String subject;

        /** Why it counts once seen: "your house has a Weiss portal". */
        private final String seenBuilt;

        /** Why it does not once seen without it: "your house has no Weiss portal". */
        private final String seenAbsent;

        /** What the house as last seen says about this item. */
        HouseSighting sighting(HouseSight house) {
            if (feature != null) {
                if (house.has(feature)) {
                    return HouseSighting.BUILT;
                }
                return house.isScanned() ? HouseSighting.ABSENT : HouseSighting.UNSEEN;
            }
            if (house.isAttuned(destination)) {
                return HouseSighting.BUILT;
            }
            return nexusGone(house) || house.isNexusRead() ? HouseSighting.ABSENT : HouseSighting.UNSEEN;
        }

        /** Whether this is a Nexus destination in a house scanned without a Nexus. */
        private boolean nexusGone(HouseSight house) {
            return feature == null && house.isScanned() && !house.has(HouseFeature.PORTAL_NEXUS);
        }

        /**
         * The answer, in this order. Seen built is a yes, whatever the levels say. Then the
         * floor answers no when a level or quest rules the item out, since its reason names
         * what the player is missing. Then seen without it is a detected no, which no
         * declaration overrides. Then a declaration is a yes. A house never seen is a no
         * too, marked {@code INFERRED}: assuming absence costs at worst a slower route. The
         * "isn't counted until" answer names what would settle it: opening a Nexus that stands
         * but was never read, otherwise visiting the house.
         */
        CapabilityVerdict detect(PlayerState state, HouseSight house, boolean declared) {
            HouseSighting seen = sighting(house);
            if (seen == HouseSighting.BUILT) {
                return CapabilityVerdict.have(Source.DETECTED, seenBuilt);
            }
            CapabilityVerdict tooEarly = floor.detect(state);
            if (tooEarly.getState() == CapabilityState.LACK) {
                return tooEarly;
            }
            if (seen == HouseSighting.ABSENT) {
                return CapabilityVerdict.lack(Source.DETECTED, nexusGone(house) ? "your house has no Portal Nexus" : seenAbsent);
            }
            if (declared) {
                return CapabilityVerdict.have(Source.DECLARED, "you said " + seenBuilt);
            }
            String settle = feature == null && house.has(HouseFeature.PORTAL_NEXUS) ? "open the Nexus" : "visit your house";
            return CapabilityVerdict.lack(Source.INFERRED, subject + " isn't counted until you " + settle + TICK_IT);
        }
    }

    /** A piece of furniture, answered from the last scan of the house. */
    private static HouseRule built(HouseFeature feature, String what, Floor floor) {
        return new HouseRule(floor, feature, 0, what, "your house has " + what, "your house has no " + bare(what));
    }

    /**
     * A Portal Nexus destination, by its enum 1377 key.
     *
     * <p>A slot holding the key is a yes from any read. A full read of the Nexus without it
     * is a no, and so is a scanned house with no Nexus at all. A Nexus seen but never read
     * is not seen yet: the scan shows the Nexus stands, not what it is attuned to.
     */
    private static HouseRule attuned(int destination, String where, Floor floor) {
        return new HouseRule(floor, null, destination, where + " in your Portal Nexus",
                "your Portal Nexus is attuned to " + where, "your Portal Nexus isn't attuned to " + where);
    }

    /**
     * What the house as last seen says about one house capability, the same reading the
     * resolver answers from. {@link HouseSighting#UNSEEN} for anything not built in a house.
     */
    public static HouseSighting houseSighting(Capability capability, HouseSight house) {
        HouseRule rule = HOUSE_RULES.get(capability);
        return rule == null ? HouseSighting.UNSEEN : rule.sighting(house != null ? house : HouseSight.unseen());
    }

    /**
     * Whether a level or quest this account is seen short of rules out a house capability,
     * whatever is declared. False for anything not built in a house.
     */
    public static boolean isHouseItemOutOfReach(Capability capability, PlayerState state) {
        HouseRule rule = HOUSE_RULES.get(capability);
        return rule != null && state != null && rule.floor.detect(state).getState() == CapabilityState.LACK;
    }

    /**
     * The level a house capability's floor names as short: its Construction level, else its
     * Magic or Farming level. 0 when no level is short, though a quest may still be.
     */
    public static int houseItemLevelShort(Capability capability, PlayerState state) {
        HouseRule rule = HOUSE_RULES.get(capability);
        return rule == null || state == null ? 0 : rule.floor.levelShort(state);
    }

    /**
     * A spirit tree the player planted, read from the patch it stands in.
     *
     * <p>The quest and level answer no first. Above them the patch decides:
     * the patch-states table's spirit tree rows read raw 20 and 44 as the last of thirteen
     * stages, the fully grown, ridable state.
     */
    private static PatchDetector grownSpiritTree(Capability capability, int farmingLevel, String where) {
        Detector cannotExist = floor("a grown spirit tree in the " + where + " patch").skill(Skill.FARMING, farmingLevel)
                .quest("Tree Gnome Village");
        return (state, sight) -> {
            CapabilityVerdict tooEarly = cannotExist.detect(state);
            if (tooEarly.getState() == CapabilityState.LACK) {
                return tooEarly;
            }
            PatchPrediction seen = sight.at(FarmingCatalogue.patchFor(capability));
            if (seen == null) {
                return CapabilityVerdict.lack(Source.INFERRED, "check the " + where + " spirit tree patch");
            }
            if (seen.getCrop() == Crop.SPIRIT_TREE && seen.getState() == CropState.GROWING && seen.getStage() >= seen.getStages() - 1) {
                return CapabilityVerdict.have(Source.DETECTED, "a grown spirit tree was seen in the " + where + " patch");
            }
            return CapabilityVerdict.lack(Source.DETECTED, "the " + where + " spirit tree patch holds no grown tree");
        };
    }

    /**
     * The Weiss herb patch, which the fire of nourishment unlocks.
     *
     * <p>Seeing the patch at all settles it, since it only exists once the fire is lit.
     *
     * <p>Not seeing it settles nothing, unlike the spirit-tree rules. The patch is its own
     * only reason to visit Weiss, so reading it absent would shut the stop out and the patch
     * would never be seen.
     */
    private static PatchDetector weissHerbPatch() {
        Detector unlit = floor("a fire of nourishment at Weiss").quest("Making Friends with My Arm");
        return (state, sight) -> sight.at(FarmingCatalogue.patchFor(Capability.WEISS_HERB_PATCH)) != null
                        ? CapabilityVerdict.have(Source.DETECTED, "the Weiss herb patch has been seen, so the fire is lit")
                        : unlit.detect(state);
    }

    /** The verdict for this capability, never null. Anything without a rule is UNKNOWN. */
    public static CapabilityVerdict resolve(Capability capability, PlayerState state) {
        return resolve(capability, state, PatchSight.blind());
    }

    /**
     * The same, for a caller that can say what is growing in the player's patches. Pass it
     * wherever available; see {@link PatchSight#blind()}.
     */
    public static CapabilityVerdict resolve(Capability capability, PlayerState state, PatchSight sight) {
        return resolve(capability, state, sight, HouseSight.unseen(), Set.of());
    }

    /**
     * The same, also knowing what the player's house was seen to hold (a null house is one
     * never seen) and which house items the player has declared built. A declaration counts
     * only for an item the house has not been seen to settle.
     *
     * @param houseDeclared the declared house capabilities, never null
     */
    public static CapabilityVerdict resolve(Capability capability, PlayerState state,
            PatchSight sight, HouseSight house, Set<Capability> houseDeclared) {
        CapabilityVerdict verdict = null;
        if (state != null) {
            HouseRule houseRule = HOUSE_RULES.get(capability);
            if (houseRule != null) {
                return houseRule.detect(state, house != null ? house : HouseSight.unseen(), houseDeclared.contains(capability));
            }
            PatchDetector patchRule = PATCH_RULES.get(capability);
            Detector detector = RULES.get(capability);
            if (patchRule != null) {
                verdict = patchRule.detect(state, sight != null ? sight : PatchSight.blind());
            } else if (detector != null) {
                verdict = detector.detect(state);
            }
        }
        return verdict != null ? verdict : CapabilityVerdict.unknown("the game doesn't show this");
    }

    /** True when this capability has a way of being answered from the game. */
    public static boolean isDetectable(Capability capability) {
        return RULES.containsKey(capability) || PATCH_RULES.containsKey(capability) || HOUSE_RULES.containsKey(capability);
    }

    private static Map<Capability, Detector> rules() {
        Map<Capability, Detector> rules = new EnumMap<>(Capability.class);

        // --- Diary reward items -------------------------------------------------
        // Read from the diary rather than the item, since the reward can sit in a bank
        // this plugin has not seen.
        for (Capability capability : Capability.values()) {
            if (capability.getTierFamily() != Capability.TierFamily.NONE) {
                rules.put(capability, diaryReward(capability));
            }
        }

        // Tablets and teleport spells are answered together by TeleportPlanner.
        for (Tables.Row row : TABLE) {
            Detector rule = tableRule(row, row.constant(Capability.class, 1));
            if (rule != null && rules.put(row.constant(Capability.class, 1), rule) != null) {
                throw row.error("a second rule for " + row.text(1));
            }
        }
        rules.put(Capability.KHAREDSTS_MEMOIRS, lancalliumsBook("Kharedst's memoirs", Capability.KHAREDSTS_MEMOIRS));
        rules.put(Capability.BOOK_OF_THE_DEAD, lancalliumsBook("a Book of the Dead", Capability.BOOK_OF_THE_DEAD));

        // --- Respawn points --------------------------------------------------------
        rules.put(Capability.RESPAWN_AVAILABLE_FALADOR, respawnPoint("Falador", "Sir Tiffy Cashien in Falador Park"));
        rules.put(Capability.RESPAWN_AVAILABLE_CAMELOT, respawnPoint("Camelot", "Merlin in Camelot Castle"));

        // --- Quest-gated networks -------------------------------------------------
        // The table's diary row answers whether the staff is needed.
        rules.put(Capability.FAIRY_RINGS, fairyRings(rules.get(Capability.STAFFLESS_FAIRY_RINGS)));
        // House items and planted trees are answered from the house and the patch; see
        // houseRules() and patchRules().
        return Collections.unmodifiableMap(rules);
    }

    /**
     * A diary tier, answered from its completion flag, with the reason for each answer. An
     * unread flag answers UNKNOWN.
     */
    private static Detector diaryTier(String area, String tier, String have, String lack, String unsure) {
        return state -> {
            switch (DiaryTiers.completed(area, tier, state)) {
                case HAVE:
                    return CapabilityVerdict.have(Source.DETECTED, have);
                case LACK:
                    return CapabilityVerdict.lack(Source.DETECTED, lack);
                default:
                    return CapabilityVerdict.unknown(unsure);
            }
        };
    }

    /**
     * One row of the rule table as its detector, or null for a row of facts. The row's
     * first cell names the kind, which fixes its width and what each cell holds.
     */
    private static Detector tableRule(Tables.Row row, Capability capability) {
        switch (row.text(0)) {
            case "carried":
                return carried(row.requireWidth(3).text(2), capability);
            case "items":
                return items(row.requireWidth(5).text(2), row.integers(3));
            case "questItem":
                if (!QUEST_GATES.containsKey(capability)) {
                    throw row.error("no gate row for " + row.text(1));
                }
                return questItems(capability, row.requireWidth(4).text(2), row.text(3));
            case "quest":
                return quest(row.requireWidth(4).text(2), row.text(3));
            case "progress":
                return questProgressAtLeast(row.requireWidth(5).text(2), row.integer(3), row.text(4));
            case "varbit":
                return varbitAtLeast(row.requireWidth(7).integer(2), row.integer(4), row.text(5), row.text(6));
            case "balloon":
                return balloonStation(row.requireWidth(5).integer(2), row.text(4));
            case "spell":
                return spell(row.requireWidth(5).integer(2), row.optionalText(3), row.text(4));
            case "skill":
                return skill(row.requireWidth(5).constant(Skill.class, 2), row.integer(3), row.text(4));
            case "houseIn":
                return houseIn(capability, row.requireWidth(3).text(2));
            case "diary":
                if (DiaryTiers.varbitFor(row.requireWidth(7).text(2), row.text(3)) == null) {
                    throw row.error("no diary flag for " + row.text(2) + " " + row.text(3));
                }
                return diaryTier(row.text(2), row.text(3), row.text(4), row.text(5), row.text(6));
            case "open":
                String because = row.requireWidth(3).text(2);
                return state -> CapabilityVerdict.have(Source.DETECTED, because);
            case "gate":
            case "cape":
                return null;
            default:
                throw row.error("no rule kind " + row.text(0));
        }
    }

    /**
     * The book a spell capability lives on, or null when it is not a spell.
     *
     * <p>Kept apart from the rules, which answer "has this player unlocked it". The resolver
     * applies this against the book being planned for, so a Lunar preview can offer Fertile
     * Soil to a player currently on Arceuus.
     */
    public static Spellbook spellbookFor(Capability capability) {
        switch (capability) {
            case RESPAWN_TELEPORT:
                return Spellbook.ARCEUUS;
            case FERTILE_SOIL:
                return Spellbook.LUNAR;
            default:
                return null;
        }
    }

    /**
     * {@link #items}, with the ids read from the packing list so the two cannot disagree.
     *
     * @param capability the {@link CarryItems} row to take ids from
     */
    private static Detector carried(String description, Capability capability) {
        CarryItems.Carry carry = CarryItems.forCapability(capability);
        if (carry == null) {
            throw new IllegalStateException("no carry item for " + capability);
        }
        return items(description, carry.getItemIds());
    }

    /**
     * Kharedst's memoirs or the Book of the Dead, able to cast Lunch by the Lancalliums: the
     * book held, its Hosidius page added, and a charge left.
     *
     * <p>Both books read the same two varbits, since the game keeps the page and the charges
     * on the player (a destroyed book keeps its charges, per the wiki). The page is varbit
     * 6030 ({@code HOSIDIUS_PAGE}), not the quest's reward flag 6028: the quest's reward
     * flags can all be set while the book holds only two pages. Charges are varbit 6035 ({@code VEOS_MEMOIR_CHARGES}).
     */
    private static Detector lancalliumsBook(String description, Capability book) {
        Detector held = carried(description, book);
        // The shared page and charges also explain this book's rung failing for a player
        // holding the other book, whose rung fails on the same varbits.
        Detector eitherBook = items("Kharedst's memoirs or a Book of the Dead", LANCALLIUMS_BOOK_IDS);
        return state -> {
            CapabilityVerdict holding = held.detect(state);
            // "Your book" only for a player seen holding one; otherwise the holding answer
            // says what is known.
            if (eitherBook.detect(state).getState() != CapabilityState.HAVE) {
                return holding;
            }
            Integer page = state.getVarbits().get(LANCALLIUMS_PAGE_VARBIT);
            if (page != null && page == 0) {
                return CapabilityVerdict.lack(Source.DETECTED, "your book is missing the Lunch by the Lancalliums page");
            }
            Integer charges = state.getVarbits().get(MEMOIRS_CHARGES_VARBIT);
            if (charges != null && charges == 0) {
                return CapabilityVerdict.lack(Source.DETECTED, "your book has no charges. Recharge it at the Old Memorial");
            }
            if (holding.getState() != CapabilityState.HAVE) {
                return holding;
            }
            if (page == null || charges == null) {
                return CapabilityVerdict.unknown("not sure whether your book has a charge");
            }
            return holding;
        };
    }

    /**
     * Held anywhere the player can retrieve it from — bank and leprechaun included.
     *
     * <p>"Not found" is UNKNOWN until the bank has been seen, since an unseen bank reads as
     * empty.
     */
    private static Detector items(String description, int... itemIds) {
        return state -> {
            for (int itemId : itemIds) {
                if (ItemCounts.ownsAny(state, itemId)) {
                    return CapabilityVerdict.have(Source.DETECTED, "you have " + description);
                }
            }
            if (state.getBankLastSeen() == null) {
                return CapabilityVerdict.unknown("not sure whether you have " + description + " until you open your bank");
            }
            return CapabilityVerdict.lack(Source.DETECTED, "you have no " + bare(description));
        };
    }

    /**
     * The fairy ring network: Fairytale I finished and Fairytale II started as far as the
     * Fairy Godfather's permission (wiki "Fairy ring": "Partially completed Fairytale II -
     * Cure a Queen (up until you're 'granted permission' to use them)"). Every ring then
     * needs a dramen or lunar staff wielded unless the elite Lumbridge &amp; Draynor diary
     * is done.
     *
     * <p>A player known to have neither the diary nor a staff anywhere cannot use a ring,
     * so the answer is LACK and the planner drops every fairy-ring rung. Either one unread
     * keeps the quests' answer rather than shutting the rungs on a guess.
     */
    private static Detector fairyRings(Detector staffless) {
        Detector growingPains = quest("Fairytale I - Growing Pains", "the fairy ring network");
        // Varbit 2326 reaches 40 once the player has talked to the Godfather, the talk in
        // which he grants the permission. The wiki walkthrough also sends the
        // player to the Co-ordinator and Fairy Fixit before "You may now use the fairy
        // rings", but neither talk has a stage of its own, and the next stage (45) comes
        // only after riding the rings to the hideout, so 40 is the latest stage that can
        // gate them.
        Detector permission = questProgressAtLeast("Fairytale II - Cure a Queen", FAIRY_RING_PERMISSION_STAGE, "the fairy ring network");
        Detector staff = items("a dramen or lunar staff", Loadouts.DRAMEN_STAFF, Loadouts.LUNAR_STAFF);
        return state -> {
            CapabilityVerdict opened = allOf(growingPains.detect(state), permission.detect(state));
            if (opened.getState() != CapabilityState.HAVE) {
                return opened;
            }
            CapabilityVerdict noStaffNeeded = staffless.detect(state);
            if (noStaffNeeded.getState() == CapabilityState.HAVE) {
                return noStaffNeeded;
            }
            CapabilityVerdict held = staff.detect(state);
            if (held.getState() == CapabilityState.HAVE) {
                return opened;
            }
            if (noStaffNeeded.getState() == CapabilityState.LACK && held.getState() == CapabilityState.LACK) {
                return CapabilityVerdict.lack(Source.DETECTED, "you need a dramen or lunar staff to use fairy rings");
            }
            // Unread diary or unseen bank: keep the rungs. The packing list still names the
            // staff, so a player who has one is not sent off without it.
            return opened;
        };
    }

    /**
     * Every gate held. A known LACK outranks an unread gate, because one shut gate shuts
     * the whole. With none shut, the first unread gate gives the answer.
     */
    private static CapabilityVerdict allOf(CapabilityVerdict... gates) {
        for (CapabilityVerdict gate : gates) {
            if (gate.getState() == CapabilityState.LACK) {
                return gate;
            }
        }
        for (CapabilityVerdict gate : gates) {
            if (gate.getState() != CapabilityState.HAVE) {
                return gate;
            }
        }
        return gates[gates.length - 1];
    }

    /** Strips a leading article, so "a ring of dueling" reads "you have no ring of dueling". */
    private static String bare(String description) {
        for (String article : new String[]{"a ", "an ", "the "}) {
            if (description.regionMatches(true, 0, article, 0, article.length())) {
                return description.substring(article.length());
            }
        }
        return description;
    }

    /**
     * A carried item behind its {@link #QUEST_GATES} quest. Short of the quest the answer is a
     * certain no that names the quest. An unobserved quest falls through to the item check.
     *
     * @param unlocks what the quest gives, named as the player would think of it
     */
    private static Detector questItems(Capability capability, String unlocks, String description) {
        QuestGate gate = QUEST_GATES.get(capability);
        Detector held = carried(description, capability);
        return state -> {
            if (gate.bars(state)) {
                return CapabilityVerdict.lack(Source.INFERRED, gate.getQuest() + " gives you " + unlocks);
            }
            return held.detect(state);
        };
    }

    /**
     * Whether quest progress has got at least as far as a given point. Not compared by
     * ordinal, so reordering {@link QuestStatus} cannot change the answer.
     */
    private static boolean hasReached(QuestStatus status, QuestStatus wanted) {
        if (wanted == QuestStatus.COMPLETED) {
            return status == QuestStatus.COMPLETED;
        }
        return status != QuestStatus.NOT_STARTED;
    }

    private static Detector quest(String questName, String description) {
        return state -> {
            QuestStatus status = state.getQuests().get(questName);
            if (status == QuestStatus.COMPLETED) {
                return CapabilityVerdict.have(Source.DETECTED, "you have finished " + questName);
            }
            if (status == null) {
                // Quest state arrives as it is observed, so silence is not a no.
                return CapabilityVerdict.unknown("not sure whether you have finished " + questName);
            }
            return CapabilityVerdict.lack(Source.DETECTED, questName + " unlocks " + description);
        };
    }

    /**
     * A place that opens partway through a quest, at a known value of its progress counter.
     * Reads the counter, not the status, since the status only says "started". The login
     * scan reads every non-zero counter.
     *
     * <p>A counter above zero but below the threshold answers UNKNOWN, not LACK: the place
     * may open at the next quest step.
     */
    private static Detector questProgressAtLeast(String questName, int opensAt, String unlocks) {
        return state -> {
            if (state.getQuests().get(questName) == QuestStatus.COMPLETED) {
                return CapabilityVerdict.have(Source.DETECTED, "you have finished " + questName);
            }
            Integer progress = state.getQuestProgress().get(questName);
            if (progress == null) {
                // The login scan stores only non-zero counters, so an absent one means
                // untouched or unscanned. The status tells them apart when present.
                return state.getQuests().get(questName) == QuestStatus.NOT_STARTED ? CapabilityVerdict.lack(Source.DETECTED,
                                questName + " opens " + unlocks) : CapabilityVerdict.unknown(
                                "not sure how far you have got in " + questName);
            }
            if (progress >= opensAt) {
                return CapabilityVerdict.have(Source.DETECTED, "you are far enough into " + questName);
            }
            return CapabilityVerdict.unknown("you have started " + questName + ", which opens " + unlocks + " partway through");
        };
    }

    /**
     * A spell, which needs a Magic level and sometimes a quest. An unobserved quest answers
     * UNKNOWN.
     */
    private static Detector spell(int magicLevel, String questName, String spellName) {
        return state -> {
            int magic = state.getSkillLevel(Skill.MAGIC);
            if (magic < magicLevel) {
                return CapabilityVerdict.lack(Source.DETECTED, spellName + " needs " + magicLevel + " Magic and you have " + magic);
            }
            QuestStatus status = questName == null ? null : state.getQuests().get(questName);
            if (questName == null || status == QuestStatus.COMPLETED) {
                return CapabilityVerdict.have(Source.DETECTED, "you can cast " + spellName);
            }
            if (status == null) {
                return CapabilityVerdict.unknown("not sure whether you have finished " + questName + ", which " + spellName + " needs");
            }
            return CapabilityVerdict.lack(Source.DETECTED, spellName + " needs " + questName);
        };
    }

    /**
     * One balloon station, flagged once the player has flown there. The flag already
     * implies Enlightened Journey and its Firemaking level.
     */
    private static Detector balloonStation(int varbitId, String where) {
        return varbitAtLeast(varbitId, 1, "you have unlocked the balloon station at " + where,
                "you have not unlocked the balloon station at " + where);
    }

    /**
     * A one-way varbit that has reached a given value. UNKNOWN while unread, since a varbit
     * enters the state map only once it is scanned or changes.
     */
    private static Detector varbitAtLeast(int varbitId, int value, String have, String lack) {
        return state -> {
            Integer current = state.getVarbits().get(varbitId);
            if (current == null) {
                return CapabilityVerdict.unknown("not sure whether " + have);
            }
            return current >= value ? CapabilityVerdict.have(Source.DETECTED, have) : CapabilityVerdict.lack(Source.DETECTED, lack);
        };
    }

    /**
     * The answer read off the player's respawn setting, or null when it has not been read.
     * A player respawns in exactly one place, so every other town is a definite no.
     */
    private static CapabilityVerdict fromSelection(String town, PlayerState state) {
        String selected = selectedRespawnTown(state);
        if (selected == null) {
            return null;
        }
        return selected.equals(town) ? CapabilityVerdict.have(Source.DETECTED, "your respawn point is " + town)
                : CapabilityVerdict.lack(Source.DETECTED, "your respawn point is " + selected + ", not " + town);
    }

    /**
     * A respawn town, unlocked as {@link #RESPAWN_UNLOCKS} answers for it, and selected at
     * {@code where}.
     *
     * <p>The selected respawn town answers outright when it has been read. Otherwise an
     * unlocked town answers UNKNOWN, with a reason telling the player where to select it,
     * and a locked one gives the unlock's own reason.
     */
    private static Detector respawnPoint(String town, String where) {
        Detector unlocked = RESPAWN_UNLOCKS.get(town);
        return state -> {
            String selectIt = "set your respawn point to " + town + " by talking to " + where + " to use this";
            // The setting outranks the unlock, which only says they could choose it.
            CapabilityVerdict settled = fromSelection(town, state);
            if (settled != null) {
                return settled;
            }
            CapabilityVerdict verdict = unlocked.detect(state);
            return verdict.getState() == CapabilityState.HAVE ? CapabilityVerdict.unknown(selectIt) : verdict;
        };
    }

    private static Floor floor(String what) {
        return new Floor(what);
    }

    /**
     * The requirements below which a player cannot have built a thing. Set up once, through
     * its builder methods, while the rule tables are built.
     *
     * <p>A floor never answers yes or null: meeting every requirement makes a thing possible,
     * not actual. Falling short of one is LACK; otherwise the answer is UNKNOWN. An
     * unobserved quest is not a shortfall.
     */
    private static final class Floor implements Detector {
        private final String what;

        /**
         * Each skill's level, checked and named in the order the builder added them. Every
         * floor adds Construction first, so a Construction shortfall is the one named.
         */
        private final Map<Skill, Integer> levels = new LinkedHashMap<>();
        private String questName;

        Floor(String what) {
            this.what = what;
        }

        Floor construction(int level) {
            return skill(Skill.CONSTRUCTION, level);
        }

        Floor quest(String questName) {
            this.questName = questName;
            return this;
        }

        Floor skill(Skill skill, int level) {
            levels.put(skill, level);
            return this;
        }

        @Override
        public CapabilityVerdict detect(PlayerState state) {
            for (Map.Entry<Skill, Integer> needed : levels.entrySet()) {
                int level = state.getSkillLevel(needed.getKey());
                if (level < needed.getValue()) {
                    return CapabilityVerdict.lack(Source.INFERRED, what + " needs " + needed.getValue() + " "
                                    + needed.getKey().getDisplayName() + " and you have " + level);
                }
            }
            if (questName != null) {
                QuestStatus status = state.getQuests().get(questName);
                if (status != null && status != QuestStatus.COMPLETED) {
                    return CapabilityVerdict.lack(Source.INFERRED, what + " needs " + questName);
                }
            }
            return CapabilityVerdict.unknown("not sure whether you have " + what);
        }

        /** The first level {@link #detect} would name as short, or 0 for none. */
        int levelShort(PlayerState state) {
            for (Map.Entry<Skill, Integer> needed : levels.entrySet()) {
                if (state.getSkillLevel(needed.getKey()) < needed.getValue()) {
                    return needed.getValue();
                }
            }
            return 0;
        }
    }

    private static Detector skill(Skill skill, int level, String description) {
        return state -> {
            int current = state.getSkillLevel(skill);
            if (current >= level) {
                return CapabilityVerdict.have(Source.DETECTED, "your " + skill.getDisplayName() + " is high enough");
            }
            return CapabilityVerdict.lack(Source.DETECTED, description + " needs " + level + " " + skill.getDisplayName()
                            + " and you have " + current);
        };
    }

    /**
     * A house in a named town. UNKNOWN only until the login scan reads the location varbit;
     * every reading after that is a yes or a no.
     */
    private static Detector houseIn(Capability location, String town) {
        return state -> {
            Boolean here = HouseLocation.isHouseIn(location, state.getVarbits());
            if (here == null) {
                return CapabilityVerdict.unknown("not sure where your house is");
            }
            if (Boolean.FALSE.equals(HouseLocation.ownsHouse(state.getVarbits()))) {
                return CapabilityVerdict.lack(Source.DETECTED, "you do not own a house");
            }
            return here ? CapabilityVerdict.have(Source.DETECTED, "your house is in " + town) : CapabilityVerdict.lack(Source.DETECTED,
                            "your house is not in " + town);
        };
    }

    /**
     * A diary reward, answered by whether its diary tier is finished. A higher tier replaces
     * the reward, so the best completed tier is the one the player holds.
     */
    private static Detector diaryReward(Capability capability) {
        return state -> {
            Capability earned = DiaryRewards.bestEarnedTier(capability.getTierFamily(), state.getVarbits());
            if (earned == null) {
                return CapabilityVerdict.lack(Source.DETECTED, "you have not earned " + capability.getDisplayName() + " yet");
            }
            if (capability.isSatisfiedBy(earned)) {
                String because = earned == capability ? "you have " + capability.getDisplayName()
                        : "you have " + earned.getDisplayName() + ", which does the same";
                return CapabilityVerdict.have(Source.INFERRED, because);
            }
            return CapabilityVerdict.lack(Source.DETECTED, "you have " + earned.getDisplayName() + ", not " + capability.getDisplayName());
        };
    }

    /**
     * Every capability whose daily teleport allowance the game itself counts, keyed by the
     * counting varbit. Used for live varbit changes and to prime a fresh login. Owned by
     * {@link DiaryRewards}, which holds the varbit facts.
     */
    public static Map<Integer, Capability> dailyUsesCapabilitiesByVarbit() {
        return DiaryRewards.USES_SPENT_BY_VARBIT;
    }
}

package com.larryfarming.farming.detection;

import java.util.Collection;

/**
 * Whether a player can do something, allowing for the fact that a plugin often cannot
 * tell.
 *
 * <p>{@link #UNKNOWN} is a real answer, and it must never be treated as {@link #LACK}.
 * Much of what the routes lean on is invisible to the plugin, such as house layout,
 * portal attunements and whether a spirit tree is grown. A player with a fully built house
 * must not be told to skip half their patches because the plugin could not see inside it.
 */
public enum CapabilityState {
    HAVE,
    LACK,
    UNKNOWN;

    /**
     * Combines alternatives, where any one will do. One HAVE settles it even if everything
     * else is unknown. Empty yields LACK.
     */
    public static CapabilityState any(Collection<CapabilityState> states) {
        boolean sawUnknown = false;
        for (CapabilityState state : states) {
            if (state == HAVE) {
                return HAVE;
            }
            if (state == UNKNOWN) {
                sawUnknown = true;
            }
        }
        return sawUnknown ? UNKNOWN : LACK;
    }

    /**
     * Combines requirements that must all hold. One LACK settles it. Otherwise a single
     * UNKNOWN leaves the whole result UNKNOWN. Empty yields HAVE, so a rung that asks for
     * nothing is available to everyone.
     */
    public static CapabilityState all(Collection<CapabilityState> states) {
        boolean sawUnknown = false;
        for (CapabilityState state : states) {
            if (state == LACK) {
                return LACK;
            }
            if (state == UNKNOWN) {
                sawUnknown = true;
            }
        }
        return sawUnknown ? UNKNOWN : HAVE;
    }
}

package com.larryfarming.farming.detection;

import lombok.Value;

/**
 * An answer about one capability, together with where the answer came from and a clause
 * explaining it.
 *
 * <p>The advisor shows the reason when it tells a player to skip a patch, so the skip reads
 * as a judgement rather than a fault. The reason also makes a wrong answer diagnosable.
 */
@Value
public class CapabilityVerdict {

    /** Where an answer came from, which decides how much to trust it. */
    public enum Source {
        /** Read from game state: an item held, a varbit set, a level reached. */
        DETECTED,
        /**
         * Set by the player in the panel: a house item declared before Larry has seen it, or
         * a travel method switched off.
         */
        DECLARED,
        /** Worked out from something else, such as a diary tier implying its reward. */
        INFERRED,
        /** Nothing to go on. */
        UNDETERMINED
    }

    CapabilityState state;
    Source source;

    /** One clause, phrased for a player rather than a developer. */
    String because;

    public static CapabilityVerdict have(Source source, String because) {
        return new CapabilityVerdict(CapabilityState.HAVE, source, because);
    }

    public static CapabilityVerdict lack(Source source, String because) {
        return new CapabilityVerdict(CapabilityState.LACK, source, because);
    }

    public static CapabilityVerdict unknown(String because) {
        return new CapabilityVerdict(CapabilityState.UNKNOWN, Source.UNDETERMINED, because);
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.farming.model.Capability;
import java.util.*;
import net.runelite.api.gameval.VarbitID;

/**
 * How to tell, from game flags alone, which tier of a diary reward item a player has
 * earned and how much of today's allowance they have spent.
 *
 * <p>The tier is read from the diary rather than from the item. The plugin sees the bank only
 * once the player opens it, so a banked ring is invisible for most of a session. The diary
 * flag is readable at login wherever the item is. The cost runs the safe way: a player who
 * never reclaimed the reward is offered a teleport they lack, notices at once and drops to
 * the next rung. Reading the item instead would silently skip patches.
 */
public final class DiaryRewards {

    private DiaryRewards() {
    }

    /**
     * The diary completion varbit that grants each tier. The highest completed tier names
     * what the player has.
     */
    private static final Map<Capability, Integer> GRANTED_BY = grantedBy();

    /**
     * Each varbit counting a capability's uses spent today, upward from zero, and the
     * capability it counts. The login scan reads each, so a part-spent day is seen.
     *
     * <p>Only the Explorer's ring has one: 4552 counts its cabbage-patch teleports (4553
     * counts energy restores, 4554 free alchs). Varbit 6069 ({@code ARDOUGNE_CLOAK_LOWBITS})
     * is a single bit and cannot hold the cloak's three or five daily farm teleports, so the
     * cloak's uses are counted as they happen (see {@link ArdougneFarmTeleportWatch}).
     */
    static final Map<Integer, Capability> USES_SPENT_BY_VARBIT = Map.of(
            VarbitID.LUMBRIDGE_CABBAGE_TELEPORT, Capability.EXPLORERS_RING_2);

    private static Map<Capability, Integer> grantedBy() {
        Map<Capability, Integer> granted = new EnumMap<>(Capability.class);
        // Lumbridge & Draynor: medium, hard, elite give Explorer's ring 2, 3 and 4.
        granted.put(Capability.EXPLORERS_RING_2, DiaryTiers.varbitFor("Lumbridge", DiaryTiers.MEDIUM));
        granted.put(Capability.EXPLORERS_RING_3, DiaryTiers.varbitFor("Lumbridge", DiaryTiers.HARD));
        granted.put(Capability.EXPLORERS_RING_4, DiaryTiers.varbitFor("Lumbridge", DiaryTiers.ELITE));
        // Ardougne: easy gives cloak 1, then the same three tiers give 2, 3 and 4. Cloak 1
        // matters because its Monastery teleport lands beside a fairy ring.
        granted.put(Capability.ARDOUGNE_CLOAK_1, DiaryTiers.varbitFor("Ardougne", DiaryTiers.EASY));
        granted.put(Capability.ARDOUGNE_CLOAK_2, DiaryTiers.varbitFor("Ardougne", DiaryTiers.MEDIUM));
        granted.put(Capability.ARDOUGNE_CLOAK_3, DiaryTiers.varbitFor("Ardougne", DiaryTiers.HARD));
        granted.put(Capability.ARDOUGNE_CLOAK_4, DiaryTiers.varbitFor("Ardougne", DiaryTiers.ELITE));
        return Collections.unmodifiableMap(granted);
    }

    /** The best tier of this family the player has earned, or null if none. */
    public static Capability bestEarnedTier(Capability.TierFamily family, Map<Integer, Integer> varbits) {
        if (family == Capability.TierFamily.NONE || varbits == null) {
            return null;
        }
        Capability best = null;
        for (Map.Entry<Capability, Integer> entry : GRANTED_BY.entrySet()) {
            Capability capability = entry.getKey();
            if (capability.getTierFamily() != family) {
                continue;
            }
            Integer done = varbits.get(entry.getValue());
            if (done == null || done == 0) {
                continue;
            }
            if (best == null || capability.getTier() > best.getTier()) {
                best = capability;
            }
        }
        return best;
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.data.Tables;
import com.larryfarming.model.PlayerState;
import java.util.*;

/**
 * Achievement diary tiers: the game's completion flag for each tier, read as a
 * {@link CapabilityState}.
 *
 * <p>Every area keeps one varbit per tier, set when the tier is finished and readable from
 * login onwards. Unlike the one-shot chat message announcing the diary, the varbit also
 * reveals tiers finished before the plugin was installed. A flag reading zero is
 * {@link CapabilityState#LACK}, and a flag nobody has read yet is
 * {@link CapabilityState#UNKNOWN}. {@link CapabilitySources#LOGIN_SCAN_VARBIT_IDS} includes
 * {@link #allVarbits()}, so most diary unknowns resolve at login.
 *
 * <p>The ids live in the diary-tiers table, transcribed from RuneLite's {@code Varbits}
 * (DIARY_&lt;AREA&gt;_&lt;TIER&gt;,
 * {@code runelite-api/src/main/java/net/runelite/api/Varbits.java}; Copyright (c) 2017, Adam;
 * BSD 2-Clause License).
 */
public final class DiaryTiers {

    private DiaryTiers() {
    }

    public static final String EASY = "Easy";
    public static final String MEDIUM = "Medium";
    public static final String HARD = "Hard";
    public static final String ELITE = "Elite";

    /** The tiers in the order the table's id columns hold them. */
    private static final String[] TIERS = {EASY, MEDIUM, HARD, ELITE};

    /**
     * Long-form area names folded onto the short key the table is written with.
     *
     * <p>The table keys each area by its one-word name; the wiki uses the full title.
     * Without the alias, a catalogue entry naming "Lumbridge &amp; Draynor" would read as
     * unknown forever. Both "&amp;" and "and" are accepted.
     */
    private static final Map<String, String> AREA_ALIASES = new HashMap<>();

    /**
     * Completion varbit per area and tier, keyed case-insensitively because the callers
     * are hand-written catalogue entries.
     */
    private static final Map<String, Integer> BY_AREA_AND_TIER = new HashMap<>();

    static {
        for (Tables.Row row : Tables.read("/com/larryfarming/diary-tiers.tsv", 10)) {
            String area = row.text(0).toLowerCase(Locale.ROOT);
            String fullTitle = row.optionalText(9);
            if (fullTitle != null) {
                String folded = fullTitle.toLowerCase(Locale.ROOT);
                AREA_ALIASES.put(folded, area);
                AREA_ALIASES.put(folded.replace(" & ", " and "), area);
            }
            for (int tier = 0; tier < TIERS.length; tier++) {
                BY_AREA_AND_TIER.put(key(area, TIERS[tier]), row.integer(1 + 2 * tier));
            }
        }
    }

    private static String key(String area, String tier) {
        String folded = area.toLowerCase(Locale.ROOT).trim();
        return AREA_ALIASES.getOrDefault(folded, folded) + "/" + tier.toLowerCase(Locale.ROOT).trim();
    }

    /**
     * The completion varbit for one diary tier, or null when the area or tier is not one
     * the game keeps a flag for.
     *
     * <p>Accepts both the short name ("Kourend") and the full title via {@link #AREA_ALIASES}.
     */
    public static Integer varbitFor(String area, String tier) {
        if (area == null || tier == null) {
            return null;
        }
        return BY_AREA_AND_TIER.get(key(area, tier));
    }

    /**
     * Whether this diary tier is finished: {@code HAVE} when the flag is set, {@code LACK}
     * when it reads zero, and {@code UNKNOWN} when nothing has reported the varbit or no id
     * is known for the area and tier. An absent varbit means nobody has looked yet, not
     * "not done".
     */
    public static CapabilityState completed(String area, String tier, PlayerState state) {
        Integer varbit = state == null ? null : varbitFor(area, tier);
        Integer value = varbit == null ? null : state.getVarbits().get(varbit);
        if (value == null) {
            return CapabilityState.UNKNOWN;
        }
        return value > 0 ? CapabilityState.HAVE : CapabilityState.LACK;
    }

    /** Every completion varbit, for the login scan that makes past diaries visible. */
    public static int[] allVarbits() {
        return BY_AREA_AND_TIER.values().stream().mapToInt(Integer::intValue).toArray();
    }
}

package com.larryfarming.farming.detection;

import java.util.Locale;
import java.util.regex.Pattern;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Getter;

/**
 * How a click leads into a house: the player's own, someone else's, or a way in whose
 * house cannot be told.
 *
 * <p>No variable names a house's owner, so a house is known to be the player's own only from
 * how they got in. The game's own wording decides it, matched loosely: case is ignored, and
 * colour tags and spacing are stripped from the target.
 *
 * <ul>
 *   <li>A house portal ({@code Portal}, any object op): "Home" and "Build mode" enter the
 *       player's own house, "Friend's house" someone else's. Any other op, "Enter" among
 *       them, opens a dialog or leaves, so its house is unknown until the dialog answers.
 *   <li>The House Advertisement board, any op: someone else's house.
 *   <li>A dialog option: "a friend's house" is someone else's, "your house" the player's.
 *   <li>Teleport to House, the spell or the tablet: "Cast", "Break" and "Inside" go to the
 *       player's own house, "Group" to a group member's, and any other op is unknown.
 *   <li>"Tele to POH", the Construction and Max capes' house teleport, and the Construction
 *       cape's "Home" teleport: the player's own house.
 * </ul>
 *
 * <p>An op renamed in a game update falls to unknown, or to no match, and an unknown entry
 * learns nothing. So a rename can stop the scan but never credit a friend's house.
 */
@Getter
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public final class HouseEntry {

    /** Whose house the click leads into. */
    public enum Owner {
        OWN,
        GUEST,
        UNKNOWN
    }

    /** What kind of menu entry was clicked, from its menu action. */
    public enum Click {
        /** An op on a game object in the scene. */
        OBJECT,
        /** A dialog option, which carries its line as the clicked widget's text. */
        DIALOG,
        /** Anything else: a spell, an item in the inventory or worn, a widget. */
        OTHER
    }

    private static final Pattern TAG = Pattern.compile("<[^>]*>");
    private static final Pattern SPACING = Pattern.compile("\\s+");

    private static final String PORTAL = "portal";
    private static final String ADVERTISEMENT = "house advertisement";
    private static final String HOUSE_TELEPORT = "teleport to house";

    private final Owner owner;
    /**
     * Which rule matched, in fixed words. Never a target's own text, so logging it can
     * never write a player's name.
     */
    private final String signal;

    /**
     * The house a click leads into, or null when it is no way into a house at all.
     *
     * @param widgetText the clicked widget's text, read only for a dialog option; may be null
     */
    public static HouseEntry of(Click click, String option, String target, String widgetText) {
        String op = plain(option);
        String on = plain(target);
        switch (click) {
            case OBJECT:
                if (on.equals(PORTAL)) {
                    if (op.equals("home") || op.equals("build mode")) {
                        return new HouseEntry(Owner.OWN, "house portal \"" + option(op) + "\"");
                    }
                    if (op.equals("friend's house")) {
                        return new HouseEntry(Owner.GUEST, "house portal \"Friend's house\"");
                    }
                    return new HouseEntry(Owner.UNKNOWN, "a portal op that names no house");
                }
                if (on.equals(ADVERTISEMENT)) {
                    return new HouseEntry(Owner.GUEST, "the House Advertisement board");
                }
                return null;
            case DIALOG: {
                String line = plain(widgetText);
                if (line.contains("friend's house")) {
                    return new HouseEntry(Owner.GUEST, "a dialog naming a friend's house");
                }
                if (line.contains("your house")) {
                    return new HouseEntry(Owner.OWN, "a dialog naming your house");
                }
                return null;
            }
            default:
                if (on.equals(HOUSE_TELEPORT)) {
                    if (op.equals("cast") || op.equals("break") || op.equals("inside")) {
                        return new HouseEntry(Owner.OWN, "Teleport to House");
                    }
                    if (op.equals("group")) {
                        return new HouseEntry(Owner.GUEST, "Teleport to House \"Group\"");
                    }
                    return new HouseEntry(Owner.UNKNOWN, "a house teleport op that lands outside");
                }
                if (op.equals("tele to poh")) {
                    return new HouseEntry(Owner.OWN, "\"Tele to POH\"");
                }
                if (op.equals("home")) {
                    return new HouseEntry(Owner.OWN, "a \"Home\" teleport");
                }
                return null;
        }
    }

    private static String option(String op) {
        return op.equals("home") ? "Home" : "Build mode";
    }

    /**
     * Lower case, without colour tags, with runs of spacing folded to one space. The game
     * writes some menu text with non-breaking spaces, which {@code \s} does not match.
     */
    private static String plain(String text) {
        if (text == null) {
            return "";
        }
        String bare = text.indexOf('<') < 0 ? text : TAG.matcher(text).replaceAll("");
        String spaced = bare.replace(' ', ' ').trim();
        return SPACING.matcher(spaced).replaceAll(" ").toLowerCase(Locale.ROOT);
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.data.Tables;
import java.util.Arrays;
import java.util.Set;

/**
 * The built furniture a house scan looks for: what the farm runs' house routes stand on.
 *
 * <p>Each is matched by the object ids of the built thing, one per frame or skin. Build-mode
 * hotspots carry ids of their own and match nothing here: the portal spaces
 * ({@code POH_TELEROOM_1} to {@code _3} and {@code _7}), the Nexus spaces
 * ({@code POH_TELENEXUS_*}, {@code POH_NEXUS_4_AMULET}, {@code POH_NEXUS_5_AMULET}) and the
 * superior garden's centrepiece space ({@code POH_SUPERIOR_GARDEN_HOTSPOT_TREERING}).
 *
 * <p>None of these portals is a multiloc, so the spawned id is the built one.
 */
public enum HouseFeature {

    PORTAL_WEISS,
    /**
     * The Troll Stronghold portal. Not the Trollheim portal
     * ({@code POH_PORTAL_*_TROLLHEIM}), which lands on the mountain far from the patch.
     */
    PORTAL_TROLL_STRONGHOLD,
    PORTAL_KOUREND,
    PORTAL_FENKENSTRAIN,
    PORTAL_HARMONY,
    /**
     * A Portal Nexus of any tier. It proves the Nexus stands, not what it is attuned to,
     * which the slot varbits answer ({@link PortalNexus}).
     */
    PORTAL_NEXUS,
    /** The spirit tree, alone or as the spiritual fairy tree, in every skin. */
    SPIRIT_TREE,
    /** The fairy ring, alone or as the spiritual fairy tree, which is both. */
    FAIRY_RING;

    static {
        Rows.TABLE.requireAll(values());
    }

    private static final HouseFeature[] ALL = values();

    /** Every id any feature matches, sorted, so a miss costs one binary search. */
    private static final int[] ANY_ID = anyId();

    private final int[] objectIds;

    HouseFeature() {
        this.objectIds = Rows.TABLE.of(name()).integers(1);
    }

    /** The feature table, held apart so the constructors can read it; see {@link Tables#byName}. */
    private static final class Rows {
        static final Tables.Named TABLE = Tables.byName("/com/larryfarming/house-features.tsv", 3);
    }

    private static int[] anyId() {
        return Arrays.stream(values()).flatMapToInt(feature -> Arrays.stream(feature.objectIds)).distinct().sorted().toArray();
    }

    /**
     * Adds what this object proves built, which for most objects is nothing. Allocates
     * nothing on a miss: every object in every loaded scene passes through here.
     */
    public static void addBuilt(int objectId, Set<HouseFeature> into) {
        if (Arrays.binarySearch(ANY_ID, objectId) < 0) {
            return;
        }
        for (HouseFeature feature : ALL) {
            for (int id : feature.objectIds) {
                if (id == objectId) {
                    into.add(feature);
                    break;
                }
            }
        }
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.farming.model.Capability;
import java.util.Map;

/**
 * Where the player's house is, read from the game.
 *
 * <p>A rung that needs POH_IN_&lt;town&gt; is a house teleport, which only helps if the house
 * is in that town.
 *
 * <p>Varbit 2187 ({@code POH_HOUSE_LOCATION}) holds the town. Zero means no house: client
 * script 3809 refuses the Construction lamp option with "You must own a house" on zero.
 * The town values agree with the Shortest Path plugin's house teleports, and Quest
 * Helper's {@code KourendEasy} also requires 8 for Hosidius.
 *
 * <p>A house is in exactly one place, so once the varbit has been read every question has
 * an answer: any value but the town's own is a no.
 */
public final class HouseLocation {

    private HouseLocation() {
    }

    public static final int HOUSE_LOCATION_VARBIT = 2187;

    /** What the varbit reads for a player who owns no house. */
    public static final int NO_HOUSE = 0;

    /** The varbit's value for each town a chain asks about. */
    private static final Map<Capability, Integer> TOWN_VALUES = Map.of(Capability.POH_IN_TAVERLEY, 2, Capability.POH_IN_BRIMHAVEN, 5,
            Capability.POH_IN_HOSIDIUS, 8);

    /**
     * Whether the house is in the town this capability names.
     *
     * @return true when the house is there, false when it is anywhere else or there is no
     *     house, and null only when the varbit has not been read
     * @throws IllegalArgumentException when the capability names no house town
     */
    public static Boolean isHouseIn(Capability location, Map<Integer, Integer> varbits) {
        Integer wanted = TOWN_VALUES.get(location);
        if (wanted == null) {
            throw new IllegalArgumentException(location + " is not a house location");
        }
        Integer value = reading(varbits);
        return value == null ? null : value.intValue() == wanted;
    }

    /** Whether the player owns a house at all, or null when the varbit has not been read. */
    public static Boolean ownsHouse(Map<Integer, Integer> varbits) {
        Integer value = reading(varbits);
        return value == null ? null : value != NO_HOUSE;
    }

    private static Integer reading(Map<Integer, Integer> varbits) {
        return varbits != null ? varbits.get(HOUSE_LOCATION_VARBIT) : null;
    }
}

package com.larryfarming.farming.detection;

import java.util.*;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Value;

/**
 * What the player's own house was last seen to hold, for the rules that answer a house
 * capability: the furniture of the last complete scan, and the Portal Nexus's attunement.
 *
 * <p>Absence means something only once it has been looked for. Furniture is absent when the
 * last scan of the house lacked it. A Nexus destination is absent when the last full read of
 * the Nexus lacked it. Before either, nothing is known and the rules keep their "not seen"
 * answer.
 *
 * <p>Immutable. Each observation returns a new sight.
 */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public final class HouseSight {

    /** A stamp meaning "never". Real stamps are epoch seconds, so always above it. */
    private static final long NEVER = 0L;

    private static final HouseSight UNSEEN = new HouseSight(Collections.emptySet(), NEVER, Collections.emptySet(), NEVER);

    Set<HouseFeature> built;
    /** When the furniture was last scanned, or 0 for never. */
    long scannedAtEpochSec;
    /** The destination keys known to be attuned, in key order. */
    Set<Integer> attuned;
    /** When the Nexus was last read in full, or 0 for never. */
    long nexusReadAtEpochSec;

    /** A house never seen, which is every house until its owner walks in. */
    public static HouseSight unseen() {
        return UNSEEN;
    }

    /**
     * A sight as saved.
     *
     * @param scannedAtEpochSec when the furniture was scanned, or 0 for never
     * @param nexusReadAtEpochSec when the Nexus was fully read, or 0 for never
     */
    public static HouseSight of(Set<HouseFeature> built, long scannedAtEpochSec, Set<Integer> attuned, long nexusReadAtEpochSec) {
        return new HouseSight(copyOf(built), Math.max(NEVER, scannedAtEpochSec), keysOf(attuned), Math.max(NEVER, nexusReadAtEpochSec));
    }

    /**
     * This house as one complete scan found it. Replaces the furniture, so a portal taken
     * down since the last visit reads absent. Leaves the Nexus attunement alone: the slot
     * varbits answer that.
     */
    public HouseSight scanned(Set<HouseFeature> found, long nowEpochSec) {
        return new HouseSight(copyOf(found), stamp(nowEpochSec), attuned, nexusReadAtEpochSec);
    }

    /** This house with the Nexus read in full. Replaces the attunement. */
    public HouseSight nexusRead(Set<Integer> destinations, long nowEpochSec) {
        return new HouseSight(built, scannedAtEpochSec, keysOf(destinations), stamp(nowEpochSec));
    }

    /**
     * This house with these destinations proven attuned, by a slot read outside a full read.
     * Only adds. Returns this sight when nothing is new, so a caller can tell a change by
     * identity.
     */
    public HouseSight attuning(Collection<Integer> destinations) {
        if (destinations.isEmpty() || attuned.containsAll(destinations)) {
            return this;
        }
        Set<Integer> more = new TreeSet<>(attuned);
        more.addAll(destinations);
        return new HouseSight(built, scannedAtEpochSec, Collections.unmodifiableSet(more), nexusReadAtEpochSec);
    }

    /** Whether the house has been scanned at least once. */
    public boolean isScanned() {
        return scannedAtEpochSec != NEVER;
    }

    /** Whether the last scan found this. False for a house never scanned. */
    public boolean has(HouseFeature feature) {
        return built.contains(feature);
    }

    /** Whether the Nexus has been read in full at least once. */
    public boolean isNexusRead() {
        return nexusReadAtEpochSec != NEVER;
    }

    /**
     * Whether this destination key, from enum 1377, is known to be attuned. Never while the
     * last scan found no Portal Nexus: a slot read from before the Nexus came down counts for
     * nothing.
     */
    public boolean isAttuned(int destination) {
        return attuned.contains(destination) && !(isScanned() && !built.contains(HouseFeature.PORTAL_NEXUS));
    }

    /** Stamps an observation. A clock at or before the epoch would read as "never". */
    private static long stamp(long nowEpochSec) {
        return Math.max(NEVER + 1, nowEpochSec);
    }

    private static Set<HouseFeature> copyOf(Set<HouseFeature> features) {
        return features == null || features.isEmpty() ? Collections.emptySet() : Collections.unmodifiableSet(EnumSet.copyOf(features));
    }

    private static Set<Integer> keysOf(Collection<Integer> destinations) {
        return destinations == null || destinations.isEmpty() ? Collections.emptySet()
                : Collections.unmodifiableSet(new TreeSet<>(destinations));
    }
}

package com.larryfarming.farming.detection;

/** What the player's house, as last seen, says about one thing that might be built in it. */
public enum HouseSighting {
    /** Seen built, or a Nexus slot read holding it. */
    BUILT,
    /** Looked for and not there. */
    ABSENT,
    /** Not looked for yet, so nothing is known. */
    UNSEEN
}

package com.larryfarming.farming.detection;

import java.util.*;
import lombok.Value;

/**
 * Reads what is built in the player's own house as it loads, and nothing from anyone else's.
 *
 * <p>The sequence: a click into a house, then the "Loading house" interface opens, then a
 * scene load, then the interface closes once the house is sent. The click decides whose
 * house it is. Object spawns are collected into a pending set from the load until the
 * interface closes, so furniture sent after the scene itself still counts. The first tick
 * with the interface closed commits the set as a complete scan, but only when a scene load
 * belongs to that interface, the player stands in a house region, and the house is confirmed
 * as their own. Any other house, a load the interface never announced, or an interface that
 * never closes before a logout or hop, learns nothing.
 *
 * <p>A solo ironman can enter no house but their own, so their every house load is theirs.
 * A group ironman can enter their group's houses and is judged by the click like anyone.
 *
 * <p>No RuneLite types. Client thread only.
 */
public final class HouseWatch {

    /**
     * How long a click into a house stays fresh, in ticks. A teleport lands in four or five,
     * and running to a portal from across a town takes some twenty. A click older than this
     * leaves the load unknown, which learns nothing.
     */
    static final int ENTRY_WINDOW_TICKS = 50;

    /**
     * The map regions a house is built from, by instance template: every house, wherever
     * its portal stands, is copied from these.
     */
    private static final int[] HOUSE_REGIONS = {7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303};

    /** {@code VarbitID.IRONMAN}'s values for the ironman, ultimate and hardcore modes. */
    private static final int FIRST_SOLO_IRONMAN = 1;
    private static final int LAST_SOLO_IRONMAN = 3;

    /** A finished scan of the player's own house, and the signal that proved it theirs. */
    @Value
    public static class Scan {
        Set<HouseFeature> found;
        String signal;
    }

    private HouseEntry lastEntry;
    private int lastEntryTick;

    /** Whether the house the player is in, or is loading, is known to be their own. */
    private boolean ownHouse;
    /** What proved {@link #ownHouse}, for the log. */
    private String ownSignal;
    /** Whether the player is in, or is loading, a house, whoever's it is. */
    private boolean inHouse;

    /** The "Loading house" interface opened and has not yet been seen closed. */
    private boolean awaitingClose;
    /** A scene load belongs to the open interface, so its close ends a real house load. */
    private boolean loadAttached;

    /** A scene is loading. */
    private boolean loading;
    /** A scene finished loading, and no tick has passed since. */
    private boolean loaded;

    private final Set<HouseFeature> pending = EnumSet.noneOf(HouseFeature.class);

    /** Whether this map region, by instance template, is part of a house. */
    public static boolean isHouseRegion(int templateRegionId) {
        for (int region : HOUSE_REGIONS) {
            if (region == templateRegionId) {
                return true;
            }
        }
        return false;
    }

    /** Whether an {@code IRONMAN} varbit value is a mode that visits no other house. */
    public static boolean isSoloIronman(int ironmanVarbit) {
        return ironmanVarbit >= FIRST_SOLO_IRONMAN && ironmanVarbit <= LAST_SOLO_IRONMAN;
    }

    /**
     * A click that leads into a house, or null for any other click, which changes nothing.
     *
     * <p>A click that may lead into someone else's house, guest or unknown, also ends the
     * player's claim on the house they stand in at once. So a group teleport out of their own
     * house can never commit the group member's house, whatever order the load's events
     * arrive in.
     */
    public void entryClicked(HouseEntry entry, int tick) {
        if (entry == null) {
            return;
        }
        lastEntry = entry;
        lastEntryTick = tick;
        if (entry.getOwner() != HouseEntry.Owner.OWN) {
            notOwn();
        }
    }

    /**
     * The "Loading house" interface opened: decide whose house is loading, and spend the
     * click that led here.
     *
     * <p>A house reloading around a player already confirmed in their own, with no click
     * into a house since, stays theirs: only the owner can switch building mode, and leaving
     * the house shows on the next tick outside a house region. Any click into a house since,
     * however old, voids that: a click too old to judge says nothing about where it led.
     *
     * <p>An interface that opens again before a tick saw it close belongs to the same load,
     * so it can end the claim but never make one: an own-house click that went nowhere,
     * made in someone else's house, cannot claim that house when its interface reopens.
     *
     * @return what was decided, in fixed words, for the log
     */
    public String houseLoading(boolean soloIronman, int tick) {
        HouseEntry entry = lastEntry;
        boolean fresh = isFresh(tick);
        boolean reopened = awaitingClose;
        lastEntry = null;
        inHouse = true;
        awaitingClose = true;
        // The interface may open before the load starts, during it, or just after it ends.
        loadAttached = (reopened && loadAttached) || loading || loaded;
        if (soloIronman) {
            return own("solo ironman");
        }
        if (reopened) {
            boolean keepsClaim = entry == null || (fresh && entry.getOwner() == HouseEntry.Owner.OWN);
            if (ownHouse && keepsClaim) {
                return "your own house still, its loading interface reopened";
            }
            notOwn();
            return "a house not known as yours, its loading interface reopened";
        }
        if (entry == null) {
            if (ownHouse) {
                return own("reloaded inside your own house");
            }
            return "an unknown house, entered by no recognised click";
        }
        if (fresh && entry.getOwner() == HouseEntry.Owner.OWN) {
            return own(entry.getSignal());
        }
        notOwn();
        if (!fresh) {
            return "an unknown house, by a click too old to judge";
        }
        return (entry.getOwner() == HouseEntry.Owner.GUEST ? "someone else's house, by " : "an unknown house, by ") + entry.getSignal();
    }

    /** The game state went to LOADING: a new scene is coming, so start the set afresh. */
    public void sceneLoading() {
        pending.clear();
        loading = true;
        loaded = false;
    }

    /** The game state went to LOGGED_IN after a load. */
    public void sceneLoaded() {
        if (loading) {
            loading = false;
            loaded = true;
            if (awaitingClose) {
                loadAttached = true;
            }
        }
    }

    /**
     * A game object spawned. Collected from the start of a scene load until the "Loading
     * house" interface closes, whoever's house it may turn out to be: the commit, not the
     * collection, checks the owner. Allocates nothing.
     */
    public void objectSpawned(int objectId) {
        if (loading || loaded || awaitingClose) {
            HouseFeature.addBuilt(objectId, pending);
        }
    }

    /** Whether {@link #tick} needs to know where the player stands this tick. */
    public boolean wantsRegion() {
        return loaded || ownHouse || inHouse || awaitingClose;
    }

    /** Whether {@link #tick} needs to know if the "Loading house" interface is still open. */
    public boolean awaitsInterfaceClose() {
        return awaitingClose;
    }

    /**
     * A game tick, with whether the player stands in a house region and whether the
     * "Loading house" interface is still open. The interface is read only while
     * {@link #awaitsInterfaceClose()}; pass false otherwise.
     *
     * @return the scan to commit, replacing the stored one, or null
     */
    public Scan tick(boolean inHouseRegion, boolean loadingInterfaceOpen) {
        boolean waiting = awaitingClose && (loadingInterfaceOpen || loading);
        // Before its load the interface can open with the player still outside, so standing
        // outside ends nothing while it waits on a load. Once it has closed, it does.
        if (!inHouseRegion && !(waiting && !loadAttached)) {
            notOwn();
            inHouse = false;
        }
        boolean justLoaded = loaded;
        loaded = false;
        if (!awaitingClose) {
            if (justLoaded) {
                // A load no interface announced: no house this can vouch for.
                pending.clear();
            }
            return null;
        }
        if (waiting) {
            return null;
        }
        boolean complete = loadAttached && ownHouse && inHouseRegion;
        awaitingClose = false;
        loadAttached = false;
        if (!complete) {
            pending.clear();
            return null;
        }
        Set<HouseFeature> found = pending.isEmpty() ? Collections.emptySet() : Collections.unmodifiableSet(EnumSet.copyOf(pending));
        pending.clear();
        return new Scan(found, ownSignal);
    }

    /** Whether the player stands in a house known to be their own, for the Nexus read. */
    public boolean isInOwnHouse() {
        return ownHouse && !loading && !loaded && !awaitingClose;
    }

    /**
     * Whether the player is in, or is loading, a house not known to be their own. Its
     * Nexus may write the slot varbits, so no slot read there is credited to the player.
     */
    public boolean isInOtherHouse() {
        return inHouse && !ownHouse;
    }

    /**
     * Forgets everything, for a logout, a world hop or the plugin stopping. A load whose
     * interface had not closed by then commits nothing.
     */
    public void clear() {
        lastEntry = null;
        notOwn();
        inHouse = false;
        awaitingClose = false;
        loadAttached = false;
        loading = false;
        loaded = false;
        pending.clear();
    }

    private boolean isFresh(int tick) {
        return lastEntry != null && tick >= lastEntryTick && tick - lastEntryTick <= ENTRY_WINDOW_TICKS;
    }

    private String own(String signal) {
        ownHouse = true;
        ownSignal = signal;
        return "your own house, by " + signal;
    }

    private void notOwn() {
        ownHouse = false;
        ownSignal = null;
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.engine.farming.PatchPrediction;
import com.larryfarming.farming.model.PatchRef;

/**
 * What the player has been seen to have in a farming patch, for the rules that answer a
 * capability from one, such as a grown spirit tree or an unlocked Weiss patch.
 *
 * <p>{@code FarmingTracker} decodes and persists patch observations. This one-method view
 * stands in for {@code FarmingInputs} so the detection layer knows nothing about run planning.
 */
@FunctionalInterface
public interface PatchSight {

    /**
     * What this patch was last seen holding, or null when the player has not walked past it
     * since the plugin was installed.
     */
    PatchPrediction at(PatchRef patch);

    /**
     * Sees nothing, for callers with no patch observations to offer.
     *
     * <p>Rules treat "never seen" as absent, so a blind sight answers every patch capability
     * with a no. Pass the real observations wherever a {@code FarmingInputs} is in scope.
     */
    static PatchSight blind() {
        return patch -> null;
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.model.ItemStack;
import com.larryfarming.model.PlayerState;
import java.util.*;

/**
 * Notices a seed going into the ground before the patch says so, and holds the plan until
 * it does.
 *
 * <p>Planting takes the seed from the bag, or the seed box, a few ticks before the patch's
 * varbit shows the crop. In between, a plan sees the seed gone and the patch still empty, and
 * asks the player to fetch another from the bank. Holding the plan over those ticks keeps
 * the one already on screen, which still counted the seed.
 *
 * <p>The hold ends when the tracker records a patch change, or after {@link #HOLD_TICKS}. A
 * seed leaving in a tick when the bank changed was banked, and holds nothing.
 *
 * <p>No RuneLite types.
 */
public final class PlantingWatch {

    /** The patch shows a planting two to four ticks after the seed leaves. */
    static final int HOLD_TICKS = 5;

    private Map<Integer, Integer> carriedBefore;
    private List<ItemStack> bankBefore;
    private long patchChangesBefore;
    private int holdLeft;

    /** Whether a plan built now would miss a seed that is going into the ground. */
    public boolean holding() {
        return holdLeft > 0;
    }

    /** Forget every reading, as at logout. */
    public void clear() {
        carriedBefore = null;
        bankBefore = null;
        patchChangesBefore = 0;
        holdLeft = 0;
    }

    /**
     * One game tick.
     *
     * @param patchChanges how many times the tracker has recorded a patch change, which
     *     moves when the planting shows
     * @return whether the hold ended this tick
     */
    public boolean tick(PlayerState state, long patchChanges) {
        boolean was = holding();
        Map<Integer, Integer> carried = seedsCarried(state);
        boolean banked = bankBefore != null && state.getBank() != bankBefore;
        if (holdLeft > 0) {
            holdLeft = patchChanges != patchChangesBefore ? 0 : holdLeft - 1;
        }
        if (carriedBefore != null && !banked && lostASeed(carriedBefore, carried)) {
            holdLeft = HOLD_TICKS;
        }
        carriedBefore = carried;
        bankBefore = state.getBank();
        patchChangesBefore = patchChanges;
        return was && !holding();
    }

    private static boolean lostASeed(Map<Integer, Integer> before, Map<Integer, Integer> after) {
        for (Map.Entry<Integer, Integer> seed : before.entrySet()) {
            if (after.getOrDefault(seed.getKey(), 0) < seed.getValue()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Each crop's planting item on the player, the seed box included: the sapling for a crop
     * planted as one, otherwise the seed.
     */
    private static Map<Integer, Integer> seedsCarried(PlayerState state) {
        Map<Integer, Integer> carried = new HashMap<>();
        for (CropData data : CropData.values()) {
            // A crop planted as a sapling goes in as the sapling, not its seed.
            int planted = data.isSaplingPlanted() ? data.getSaplingItemId() : data.getSeedItemId();
            int held = ItemCounts.countCarried(state, planted, null);
            if (held > 0) {
                carried.merge(planted, held, Math::max);
            }
        }
        return carried;
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.data.Tables;
import java.util.*;
import java.util.function.IntUnaryOperator;

/**
 * What the Portal Nexus is attuned to, read from its slot varbits.
 *
 * <p>The Nexus holds up to 45 slots. Each slot is a varbit holding a destination key from
 * enum 1377, or zero for an empty slot. The enum keys each destination's alternate arrival at
 * its key plus 150, reached through the destination's struct. A slot is six bits wide, so it
 * never holds such a key, but one would still fold to its destination. Destinations are
 * matched on keys, never on names: other plugins rename
 * the Nexus's destinations at runtime.
 *
 * <p>Two sets of slot varbits exist. The plain set is the attunement the player saved, which the
 * game reads when it checks whether a destination is already in the Nexus. The
 * {@code _TEMP} set is a working copy, which the teleport menu redraws from. So the plain
 * set is authoritative, and the working copy stands in for it only on the teleport menu of
 * the player's own Nexus, when every plain slot reads zero.
 */
public final class PortalNexus {

    /** Enum 1377's keys for the destinations the farm runs use. */
    public static final int TROLL_STRONGHOLD = 15;
    public static final int WEISS = 19;
    public static final int HARMONY_ISLAND = 27;

    /** Added to a key for the destination's alternate arrival. */
    private static final int ALTERNATE_ARRIVAL = 150;

    /** Each slot's saved and working-copy varbits, slots 1 to 45 in order. */
    private static final List<Tables.Row> TABLE = Tables.read("/com/larryfarming/portal-nexus.tsv", 5);

    /** The saved attunement, slots 1 to 45 in order. */
    private static final int[] SLOTS = column(1);

    /** The interfaces' working copy, in the same slot order. */
    private static final int[] WORKING_COPY = column(3);

    private static int[] column(int column) {
        int[] ids = new int[TABLE.size()];
        for (int i = 0; i < ids.length; i++) {
            Tables.Row row = TABLE.get(i);
            if (row.integer(0) != i + 1) {
                throw row.error("slot out of order");
            }
            ids[i] = row.integer(column);
        }
        return ids;
    }

    /** {@link #SLOTS}, sorted for lookup on every varbit change. */
    private static final int[] SLOTS_SORTED = sorted(SLOTS);

    private PortalNexus() {
    }

    private static int[] sorted(int[] ids) {
        int[] copy = ids.clone();
        Arrays.sort(copy);
        return copy;
    }

    /** Whether this varbit is one of the saved attunement's slots. */
    public static boolean isSlot(int varbitId) {
        return Arrays.binarySearch(SLOTS_SORTED, varbitId) >= 0;
    }

    /** The destination a slot value names, with an alternate arrival folded in, or 0. */
    public static int destination(int slotValue) {
        return slotValue > ALTERNATE_ARRIVAL ? slotValue - ALTERNATE_ARRIVAL : slotValue;
    }

    /**
     * The destinations the saved slots name, read anywhere. Zero proves nothing here, since
     * a slot may not have been sent yet, so the answer only ever adds.
     */
    public static Set<Integer> attunedIn(IntUnaryOperator varbits) {
        return keys(SLOTS, varbits);
    }

    /**
     * Every destination the Nexus holds, read while its teleport menu is open in the
     * player's own house, where a zero slot is a real empty slot. Falls back to the working
     * copy when every saved slot reads zero, since the menu is drawn from that copy.
     *
     * @return the destinations, or null when both sets read empty, which this cannot tell
     *     apart from slots not yet sent, so it settles nothing
     */
    public static Set<Integer> fullRead(IntUnaryOperator varbits) {
        Set<Integer> saved = keys(SLOTS, varbits);
        if (!saved.isEmpty()) {
            return saved;
        }
        Set<Integer> working = keys(WORKING_COPY, varbits);
        return working.isEmpty() ? null : working;
    }

    private static Set<Integer> keys(int[] slots, IntUnaryOperator varbits) {
        Set<Integer> keys = new TreeSet<>();
        for (int slot : slots) {
            int key = destination(varbits.applyAsInt(slot));
            if (key > 0) {
                keys.add(key);
            }
        }
        return Collections.unmodifiableSet(keys);
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.farming.catalogue.Teleports;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.*;
import java.util.*;
import lombok.Value;

/**
 * Decides how this player, on the book they are actually on, should reach a place.
 *
 * <p>Ranking:
 * <ol>
 *   <li>Already inside the destination's {@link com.larryfarming.farming.model.Zone}: free, and
 *       nothing for the bag to carry.</li>
 *   <li>A castable spell on the open book. It spends runes the player carries anyway and
 *       saves the tablet for a run on the wrong book.</li>
 *   <li>A tablet, which works from any book.</li>
 * </ol>
 * {@link #best} never ranks a spell on another book: changing book is a decision for the
 * whole run, and the run already names its book.
 *
 * <p>Spellbook Swap is the one way to borrow such a spell for a single cast, and only a rung
 * that names it asks: {@link #bySwap}. The rung's place in its chain ranks the swap against
 * the tablet and the house, so this class never weighs one against the others.
 */
public final class TeleportPlanner {

    private TeleportPlanner() {
    }

    /** How to get there, how sure we are, and what to tell the player about it. */
    @Value
    public static class Choice {
        /** The way to go, or null when there is none. */
        TeleportMeans means;
        CapabilityState state;
        String because;
    }

    /**
     * The best way to reach this place.
     *
     * @param onBook the book the player is on, which decides which spells are castable
     *               without a swap
     * @param readsPosition whether the player's own position may answer this. False for a
     *               stop further down the trip, which the player will have left this place
     *               long before reaching — see {@link CapabilityResolver#blindToPosition()}
     * @param tabletsOff the switch refusing this place's tablet, or null while it is allowed.
     *               A refused tablet never answers, owned or not, and with no spell on the
     *               open book the place is out of reach whatever the bank holds. Naming the
     *               switch lets a shortfall say which one the player turned off.
     *               {@link CapabilityResolver} passes the standard book until the login read
     *               of the spellbook varbit, so a refused tablet answers LACK in that window
     *               even for a player on the Arceuus book.
     */
    public static Choice best(Destination destination, PlayerState state, Spellbook onBook,
            boolean readsPosition, TravelMethod tabletsOff) {
        boolean tablets = tabletsOff == null;
        if (state == null) {
            return new Choice(null, CapabilityState.UNKNOWN, "not sure how you would reach " + destination.getDisplayName());
        }

        // Already there: no means, so the bag asks for no runes or tablet. This removes a
        // consumable from the bag, so it must fire only on a position the game reported;
        // Zone.covers reads an unknown region as a no.
        Zone zone = destination.getZone();
        if (readsPosition && zone != null && zone.covers(state.getRegionId())) {
            return new Choice(null, CapabilityState.HAVE, "you are already at " + zone.getDisplayName());
        }

        TeleportMeans unconfirmed = null;
        String unconfirmedBecause = null;
        for (TeleportMeans means : Teleports.to(destination)) {
            if (!means.isSpell() || means.getSpellbook() != onBook) {
                continue;
            }
            Choice cast = castable(means, state);
            if (cast.getState() == CapabilityState.HAVE) {
                return cast;
            }
            if (cast.getState() == CapabilityState.UNKNOWN && unconfirmed == null) {
                unconfirmed = means;
                unconfirmedBecause = cast.getBecause();
            }
        }

        for (TeleportMeans means : Teleports.to(destination)) {
            if (!tablets || !means.isTablet() || !owns(means, state)) {
                continue;
            }
            // A tablet behind a quest breaks only once the quest is finished.
            Choice locked = locked(means, state);
            if (locked == null) {
                return new Choice(means, CapabilityState.HAVE,
                        // Tablets lead with a place, so the name keeps its capital.
                        "you have a " + means.getDisplayName());
            }
            if (locked.getState() == CapabilityState.UNKNOWN && unconfirmed == null) {
                unconfirmed = means;
                unconfirmedBecause = locked.getBecause();
            }
        }

        if (unconfirmed != null) {
            return new Choice(unconfirmed, CapabilityState.UNKNOWN, unconfirmedBecause);
        }
        // Checked before the unseen bank: with the tablet refused and no spell on this
        // book, nothing the bank could hold would change the answer.
        if (!tablets && !hasSpellOn(destination, onBook)) {
            return new Choice(null, CapabilityState.LACK, "you switched off tablets to " + destination.getDisplayName());
        }
        // An unseen bank cannot prove the player is out of tablets or runes, so answer
        // UNKNOWN like every item rule. LACK here drops the stop's patches from the run.
        if (state.getBankLastSeen() == null) {
            return new Choice(null, CapabilityState.UNKNOWN, "open your bank to check your teleports to " + destination.getDisplayName());
        }
        return new Choice(null, CapabilityState.LACK, shortfall(destination, state, onBook, tabletsOff));
    }

    private static boolean owns(TeleportMeans tablet, PlayerState state) {
        return ItemCounts.countOwned(state, tablet.getItemId(), null) > 0;
    }

    private static boolean hasSpellOn(Destination destination, Spellbook onBook) {
        for (TeleportMeans means : Teleports.to(destination)) {
            if (means.isSpell() && means.getSpellbook() == onBook) {
                return true;
            }
        }
        return false;
    }

    /**
     * The best way to reach this place by Spellbook Swap and its spell from another book,
     * for a rung written with {@code TravelOption.swapTo}.
     *
     * <p>Both casts must be open to the player: the swap's 96 Magic and Dream Mentor, and the
     * second spell's own level and quest. Levels are true levels, as everywhere here. The
     * runes are both casts' together; banked runes count. With the bank unseen, a shortfall
     * reads UNKNOWN as it does in {@link #best}, but the means stays named so the bag still
     * lists every rune.
     *
     * @param onBook the book the swap is cast from, which must be the swap's own
     */
    public static Choice bySwap(Destination destination, PlayerState state, Spellbook onBook, boolean readsPosition) {
        if (state == null) {
            return new Choice(null, CapabilityState.UNKNOWN, "not sure how you would reach " + destination.getDisplayName());
        }
        Zone zone = destination.getZone();
        if (readsPosition && zone != null && zone.covers(state.getRegionId())) {
            return new Choice(null, CapabilityState.HAVE, "you are already at " + zone.getDisplayName());
        }
        TeleportMeans swap = Teleports.bySwap(destination);
        if (swap == null) {
            return new Choice(null, CapabilityState.LACK, "no spell on another spellbook reaches " + destination.getDisplayName());
        }
        if (onBook != swap.getSpellbook()) {
            return new Choice(null, CapabilityState.LACK, Teleports.SPELLBOOK_SWAP.getDisplayName() + " is on the "
                            + swap.getSpellbook().getDisplayName() + " spellbook");
        }
        Choice locked = locked(swap, state);
        if (locked == null) {
            locked = locked(swap.getSwappedSpell(), state);
        }
        if (locked != null) {
            return new Choice(swap, locked.getState(), locked.getBecause());
        }
        Rune missing = shortOf(swap, state);
        if (missing == null) {
            return new Choice(swap, CapabilityState.HAVE, "you can cast " + swap.getDisplayName());
        }
        return state.getBankLastSeen() == null ? new Choice(swap, CapabilityState.UNKNOWN,
                        "open your bank to check your runes for " + swap.getDisplayName())
                : new Choice(swap, CapabilityState.LACK, shortReason(missing, swap));
    }

    /**
     * Whether this spell can be cast, runes included. Banked runes count, since this is read
     * before setting off.
     */
    private static Choice castable(TeleportMeans means, PlayerState state) {
        Choice locked = locked(means, state);
        if (locked != null) {
            return locked;
        }
        Rune missing = shortOf(means, state);
        if (missing != null) {
            return new Choice(means, CapabilityState.LACK, shortReason(missing, means));
        }
        return new Choice(means, CapabilityState.HAVE, "you can cast " + means.getDisplayName());
    }

    /**
     * Why the player cannot use this spell or tablet whatever runes they hold, or null when
     * its level and quest are met. A tablet asks for no level. An unobserved quest answers
     * UNKNOWN.
     */
    private static Choice locked(TeleportMeans means, PlayerState state) {
        int magic = state.getSkillLevel(Skill.MAGIC);
        if (magic < means.getMagicLevel()) {
            return new Choice(means, CapabilityState.LACK, means.getDisplayName() + " needs " + means.getMagicLevel()
                            + " Magic and you have " + magic);
        }
        if (means.getQuestName() != null) {
            QuestStatus status = state.getQuests().get(means.getQuestName());
            if (status == null) {
                return new Choice(means, CapabilityState.UNKNOWN, "not sure whether you have finished " + means.getQuestName()
                                + ", which " + means.getDisplayName() + " needs");
            }
            if (status != QuestStatus.COMPLETED) {
                return new Choice(means, CapabilityState.LACK, means.getDisplayName() + " needs " + means.getQuestName());
            }
        }
        return null;
    }

    /** The first rune the player owns too few of for one cast, or null when none is short. */
    private static Rune shortOf(TeleportMeans means, PlayerState state) {
        for (Map.Entry<Rune, Integer> cost : means.getRunes().entrySet()) {
            Rune rune = cost.getKey();
            if (ItemCounts.countOwned(state, rune.getItemId(), null) < cost.getValue()) {
                return rune;
            }
        }
        return null;
    }

    /**
     * Whether a spell on the open book reaches this place and only runes keep the player from
     * casting it: its level and quest are met. False with no state to read.
     */
    public static boolean wantsOnlyRunes(Destination destination, PlayerState state, Spellbook onBook) {
        if (state == null) {
            return false;
        }
        for (TeleportMeans means : Teleports.to(destination)) {
            if (means.isSpell() && means.getSpellbook() == onBook && locked(means, state) == null && shortOf(means, state) != null) {
                return true;
            }
        }
        return false;
    }

    /**
     * Whether some way to this place waits on no quest the player is seen short of: a
     * tablet they allow, or a spell on the open book whatever its Magic level. True with no
     * state to read.
     *
     * @param tablets false when the player refuses this place's tablet
     */
    public static boolean isOpenToGet(Destination destination, PlayerState state, Spellbook onBook, boolean tablets) {
        if (state == null) {
            return true;
        }
        for (TeleportMeans means : Teleports.to(destination)) {
            boolean offered = means.isTablet() ? tablets : means.isSpell() && means.getSpellbook() == onBook;
            if (offered && !questBarred(means, state)) {
                return true;
            }
        }
        return false;
    }

    /**
     * {@link #isOpenToGet} for a Spellbook Swap rung: the swap is cast from the open book,
     * and neither it nor the spell it borrows waits on an unfinished quest.
     */
    public static boolean isOpenBySwap(Destination destination, PlayerState state, Spellbook onBook) {
        TeleportMeans swap = Teleports.bySwap(destination);
        if (swap == null || swap.getSpellbook() != onBook) {
            return false;
        }
        return state == null || (!questBarred(swap, state) && !questBarred(swap.getSwappedSpell(), state));
    }

    /** True when the player is seen short of this spell's or tablet's quest. */
    private static boolean questBarred(TeleportMeans means, PlayerState state) {
        if (means.getQuestName() == null) {
            return false;
        }
        QuestStatus status = state.getQuests().get(means.getQuestName());
        return status != null && status != QuestStatus.COMPLETED;
    }

    private static String shortReason(Rune rune, TeleportMeans means) {
        return "you are short of " + rune.getDisplayName().toLowerCase() + "s for " + means.getDisplayName();
    }

    /**
     * Why nothing works, one reason per means. An off-book spell is reported as being on
     * another spellbook, never as a missing requirement the player may already have.
     */
    private static String shortfall(Destination destination, PlayerState state, Spellbook onBook, TravelMethod tabletsOff) {
        // A set: one switch can refuse several tablets, and its reason reads once.
        Set<String> reasons = new LinkedHashSet<>();
        for (TeleportMeans means : Teleports.to(destination)) {
            if (means.isTablet()) {
                Choice locked = tabletsOff == null && owns(means, state) ? locked(means, state) : null;
                reasons.add(tabletsOff != null ? tabletsOff.switchedOffReason() : locked != null ? locked.getBecause()
                                // Tablets lead with a place, so the name keeps its capital.
                                : "you have no " + means.getDisplayName());
            } else if (means.getSpellbook() != onBook) {
                reasons.add(means.getDisplayName() + " is on the " + means.getSpellbook().getDisplayName() + " spellbook");
            } else {
                reasons.add(castable(means, state).getBecause());
            }
        }
        if (reasons.isEmpty()) {
            return "nothing you have reaches " + destination.getDisplayName();
        }
        return String.join(", and ", reasons);
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.farming.model.Capability;
import com.larryfarming.farming.model.Destination;
import java.util.Set;
import lombok.Value;

/**
 * A teleport the player has already spent on the way to the stop they are heading for: the
 * places its runes or tablet reach, or the travel item it used up.
 *
 * <p>Spent is paid. The runes, the tablet or the ring's last charge left the bag when the
 * player cast or rubbed it, so asking for them again would send the player back to the
 * bank for a teleport they have already taken. See {@link TravelWatch}.
 */
@Value
public class TravelTaken {

    public static final TravelTaken NONE = new TravelTaken(Set.of(), Set.of());

    /**
     * Every place the spent runes or tablet could have reached. Usually one; a staff that
     * pays the elemental runes can leave two spells with the same law runes.
     */
    Set<Destination> places;

    /** The travel item the teleport used up: a ring's last charge, a broken tablet. */
    Set<Capability> items;

    public static TravelTaken to(Set<Destination> places) {
        return places.isEmpty() ? NONE : new TravelTaken(Set.copyOf(places), Set.of());
    }

    public static TravelTaken using(Capability item) {
        return new TravelTaken(Set.of(), Set.of(item));
    }

    public boolean isNone() {
        return places.isEmpty() && items.isEmpty();
    }

    /** Whether the player has already teleported towards this place. */
    public boolean reached(Destination destination) {
        return places.contains(destination);
    }

    /** Whether the player has already used this travel item up on the way. */
    public boolean used(Capability capability) {
        return items.contains(capability);
    }
}

package com.larryfarming.farming.detection;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.farming.catalogue.CarryItems;
import com.larryfarming.farming.catalogue.Teleports;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.ItemStack;
import com.larryfarming.model.PlayerState;
import java.util.*;

/**
 * Notices a teleport spent on the way to the next stop, so the plan stops asking for it.
 *
 * <p>The cast takes the runes, the tablet or a ring's last charge out of the bag before the
 * player lands. Without this watch, the next plan would see them gone and send the player to
 * the bank for more, all the way from the landing to the patch.
 *
 * <p><b>Spent, then landed.</b> A tick whose losses match one teleport's whole cost, and fit
 * no other spell or tablet, marks it spent at once, so the bank row never flashes the runes
 * back while the player is in the air. The player must then land: a jump to a region that
 * does not border the last one within {@link #LANDING_TICKS}. Runes or a ring that leave
 * without one went somewhere else, and the mark is dropped.
 *
 * <p><b>Paid until the stop is worked.</b> Once landed, the teleport stays paid while the
 * plan's next patch is the one it was cast for, or that patch's route lands where the cast
 * did while the player is still in or beside the region it landed in. A player who has
 * walked off to a patch is no longer where the cast put them, so the next stop prices its
 * own way there. A route can go on from the landing by a glider or a fairy ring, which a
 * jump alone would read as a second teleport. Another spent teleport replaces the mark, the
 * trip ending forgets it, and {@link #MAX_TICKS} ends one the player wandered off from.
 *
 * <p>Losses in a tick when the bank changed are never a teleport: that is the player
 * banking.
 *
 * <p>No RuneLite types.
 */
public final class TravelWatch {

    /** A teleport lands three or four ticks after its cast. Ten allows for lag. */
    static final int LANDING_TICKS = 10;

    /** Ten minutes. No stop is that far from the place its teleport lands. */
    static final int MAX_TICKS = 1000;

    private static final Set<Rune> ELEMENTAL = EnumSet.of(Rune.AIR, Rune.WATER, Rune.EARTH, Rune.FIRE);

    /**
     * The travel items a teleport can use up: jewellery crumbling or going uncharged on its
     * last charge, a basalt or tablet broken. A cape, a cloak, an eternal glory or a ring of
     * unlimited use leaves the bag only when the player puts it somewhere, never on a
     * teleport. Nor does the ectophial: emptied, it still counts, and it refills itself on
     * arrival.
     */
    private static final Set<Capability> USED_UP = EnumSet.of(
            Capability.RING_OF_DUELING, Capability.GAMES_NECKLACE, Capability.COMBAT_BRACELET,
            Capability.DIGSITE_PENDANT, Capability.RING_OF_WEALTH, Capability.AMULET_OF_GLORY,
            Capability.SKILLS_NECKLACE,
            Capability.SLAYER_RING, Capability.NECKLACE_OF_PASSAGE,
            Capability.TELEPORT_CRYSTAL, Capability.ICY_BASALT, Capability.STONY_BASALT, Capability.BRIMHAVEN_TABLET);

    private Map<Integer, Integer> carriedBefore;
    private List<ItemStack> bankBefore;
    private Integer regionBefore;

    private TravelTaken spent = TravelTaken.NONE;
    /** The patch the teleport pays for: the next patch when it was spent, or a later one whose route lands where the cast did. */
    private String spentFor;
    private int ticksSinceSpent;
    private boolean landed;
    /**
     * The region the teleport landed in: non-null exactly while {@link #landed} is true. A tick
     * with no region reads as away from it, so the mark never moves on to another stop
     * unchecked.
     */
    private Integer landedIn;

    /** The teleport spent on the way to the next stop, or {@link TravelTaken#NONE}. */
    public TravelTaken taken() {
        return spent;
    }

    /** The patch the teleport was spent for, or null with none spent. */
    public String takenFor() {
        return spentFor;
    }

    /** Forget the teleport and every reading, as at logout. */
    public void clear() {
        forget();
        carriedBefore = null;
        bankBefore = null;
        regionBefore = null;
    }

    /**
     * One game tick.
     *
     * @param heading the patch the plan sends the player to next, or null for none
     * @param landing where that stop's route lands, or null for a route taken on an item.
     *     A teleport spent for one stop stays paid for the next while this is its place and
     *     the player is in or beside the region it landed in: the Falador park tree and the
     *     Falador farm are a walk apart, not two casts
     * @return whether {@link #taken()} or {@link #takenFor()} changed
     */
    public boolean tick(PlayerState state, String heading, Destination landing) {
        TravelTaken was = spent;
        String wasFor = spentFor;
        Map<Integer, Integer> carried = carried(state);
        Integer region = state.getRegionId();
        boolean jumped = regionBefore != null && region != null && !bordering(regionBefore, region);
        boolean banked = bankBefore != null && state.getBank() != bankBefore;

        if (!spent.isNone()) {
            ticksSinceSpent++;
            boolean movedOn = !stillPaidFor(heading, landing, region);
            if (!landed && jumped) {
                landed = true;
                landedIn = region;
            } else if (!landed && ticksSinceSpent > LANDING_TICKS || movedOn || ticksSinceSpent > MAX_TICKS) {
                forget();
            }
        }
        if (carriedBefore != null && !banked) {
            TravelTaken now = spentBetween(carriedBefore, carried);
            if (!now.isNone()) {
                spent = now;
                spentFor = heading;
                ticksSinceSpent = 0;
                landed = jumped;
                landedIn = jumped ? region : null;
            }
        }

        carriedBefore = carried;
        bankBefore = state.getBank();
        regionBefore = region;
        return !spent.equals(was) || !Objects.equals(spentFor, wasFor);
    }

    /**
     * Judges the mark again against the next stop of a plan built this tick, with no tick
     * counted. {@link #tick} judged it against the stop on screen, before the plan was built.
     * A stop the mark no longer pays for prices its own teleport in that same tick's plan.
     *
     * @return whether the mark went
     */
    public boolean retarget(PlayerState state, String heading, Destination landing) {
        if (spent.isNone() || stillPaidFor(heading, landing, state.getRegionId())) {
            return false;
        }
        forget();
        return true;
    }

    /**
     * Whether the mark still pays for this next stop. It moves the mark on to that stop when
     * the stop's route lands where the cast did and the player is in or beside the region it
     * landed in.
     */
    private boolean stillPaidFor(String heading, Destination landing, Integer region) {
        // Before the landing, no next patch says nothing: the plan may not be rebuilt yet.
        // After it, no next patch means the trip is done, and a mark left over would pay for
        // the first stop of the next one.
        boolean movedOn = heading == null ? landed : !heading.equals(spentFor);
        if (movedOn && landed && landing != null && spent.reached(landing) && region != null
                && bordering(landedIn, region)) {
            spentFor = heading;
            return true;
        }
        return !movedOn;
    }

    private void forget() {
        spent = TravelTaken.NONE;
        spentFor = null;
        ticksSinceSpent = 0;
        landed = false;
        landedIn = null;
    }

    /**
     * The teleport whose whole cost these losses are, or {@link TravelTaken#NONE}.
     *
     * <p>A spell matches when every rune lost is one it takes, in exactly its amount, and
     * every rune but the elementals was lost: a staff or tome pays those. A tablet matches
     * on one tablet gone. A travel item matches when one of its forms is gone and none
     * came in its place: a ring crumbling on its last charge, not a ring of dueling (8)
     * becoming a (7), which the plan still counts as a ring.
     */
    static TravelTaken spentBetween(Map<Integer, Integer> before, Map<Integer, Integer> after) {
        Map<Rune, Integer> runesLost = new HashMap<>();
        for (Rune rune : Rune.values()) {
            int lost = lost(before, after, rune.getItemId());
            if (lost > 0) {
                runesLost.put(rune, lost);
            }
        }
        Set<Destination> places = EnumSet.noneOf(Destination.class);
        Set<String> means = new HashSet<>();
        for (Destination destination : Destination.values()) {
            for (TeleportMeans way : Teleports.to(destination)) {
                if (way.isSpell() ? paidFor(way.getRunes(), runesLost) : way.isTablet() && lost(before, after, way.getItemId()) == 1) {
                    places.add(destination);
                    means.add(way.getDisplayName());
                }
            }
        }
        // One spell or tablet, which may reach two places (Varrock and the Grand Exchange).
        // A law rune alone, with a staff paying the rest, fits half the standard book: that
        // is no telling which, and a wrong guess drops a teleport the player still needs.
        if (means.size() == 1) {
            return TravelTaken.to(places);
        }
        if (!means.isEmpty()) {
            return TravelTaken.NONE;
        }
        for (Capability capability : USED_UP) {
            CarryItems.Carry carry = CarryItems.forCapability(capability);
            if (carry != null && usedUp(carry.getItemIds(), before, after)) {
                return TravelTaken.using(capability);
            }
        }
        return TravelTaken.NONE;
    }

    private static boolean paidFor(Map<Rune, Integer> cost, Map<Rune, Integer> lost) {
        if (lost.isEmpty()) {
            return false;
        }
        for (Map.Entry<Rune, Integer> rune : lost.entrySet()) {
            if (!rune.getValue().equals(cost.get(rune.getKey()))) {
                return false;
            }
        }
        for (Rune rune : cost.keySet()) {
            if (!ELEMENTAL.contains(rune) && !lost.containsKey(rune)) {
                return false;
            }
        }
        return true;
    }

    private static boolean usedUp(int[] forms, Map<Integer, Integer> before, Map<Integer, Integer> after) {
        int lost = 0;
        for (int id : forms) {
            int change = after.getOrDefault(id, 0) - before.getOrDefault(id, 0);
            if (change > 0) {
                return false;
            }
            lost -= change;
        }
        return lost == 1;
    }

    private static int lost(Map<Integer, Integer> before, Map<Integer, Integer> after, int id) {
        return before.getOrDefault(id, 0) - after.getOrDefault(id, 0);
    }

    /** What the player has on them of every rune, tablet and travel item a route can spend. */
    private static Map<Integer, Integer> carried(PlayerState state) {
        Map<Integer, Integer> carried = new HashMap<>();
        for (int id : WATCHED) {
            int held = ItemCounts.countCarried(state, id, null);
            if (held > 0) {
                carried.put(id, held);
            }
        }
        return carried;
    }

    /** Whether two map regions touch, sides or corners: walking crosses only these. */
    static boolean bordering(int a, int b) {
        return Math.abs((a >> 8) - (b >> 8)) <= 1 && Math.abs((a & 0xFF) - (b & 0xFF)) <= 1;
    }

    private static final int[] WATCHED = watched();

    private static int[] watched() {
        Set<Integer> ids = new TreeSet<>();
        for (Rune rune : Rune.values()) {
            ids.add(rune.getItemId());
        }
        for (Destination destination : Destination.values()) {
            for (TeleportMeans means : Teleports.to(destination)) {
                if (means.isTablet()) {
                    ids.add(means.getItemId());
                }
            }
        }
        for (Capability capability : Capability.values()) {
            CarryItems.Carry carry = CarryItems.forCapability(capability);
            if (carry != null) {
                for (int id : carry.getItemIds()) {
                    ids.add(id);
                }
            }
        }
        return ids.stream().mapToInt(Integer::intValue).toArray();
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.farming.model.Arrival;
import com.larryfarming.farming.model.Bank;
import com.larryfarming.snapshot.FarmingCarryItem;
import com.larryfarming.snapshot.FarmingStopAdvice;
import java.util.*;

/**
 * The bank rows of a walkthrough: a prescribed bank in front of every leg that needs one,
 * the banks the trip passes on offer, the bag to set off with, and a row where the bag
 * overflows with no bank in reach.
 *
 * <p>A bank row stands where the player meets the bank. A prescribed bank, and an offered
 * bank on the route from the landing to the patch, come before the arrival's row: the
 * player banks on the way in.
 *
 * <p>Works on rows {@link FarmingAdviceBuilder} has already drawn, and on the bag
 * {@link InventorySim} simulated over them.
 */
final class BankStopSplicer {

    private BankStopSplicer() {
    }

    /**
     * The walkthrough with a bank stop in front of every leg that needs one.
     *
     * <p>Spliced in after every row exists, because where the bag runs out depends on what
     * every earlier arrival took out of the inventory.
     *
     * <p>The first leg never gets one: the player packs before setting out, so leg zero
     * begins at a bank. A later leg with no bank is the sim reporting that the bag fills
     * with nothing in reach to empty it into; it draws an overflow row and is detailed by
     * {@link InventorySim.Leg#getOverflow()}.
     *
     * @param rowOf where each arrival the bag was planned over sits in {@code stops}. Leg
     *     indices count only arrivals being made, while {@code stops} also holds skipped
     *     rows. A mis-sized {@code rowOf} throws rather than splicing a bank into the wrong
     *     place.
     * @param withdrawals what each bank row says to take out, or
     *     {@link WithdrawalPlanner.Withdrawals#none()} where the caller has not worked them
     *     out
     * @param underway whether the player is partway round, which changes only how the
     *     starting row is headed and lets it stand on a trip with no bank to splice
     */
    static List<FarmingStopAdvice> withBankStops(List<FarmingStopAdvice> stops, InventorySim.Plan bag, List<Integer> rowOf,
            WithdrawalPlanner.Withdrawals withdrawals, boolean underway) {
        // Asks what the legs say, not how many there are: a single leg can still be an
        // arrival nobody could carry. Partway round, the starting row can be the only bank
        // row there is, so the walk below still runs to place it.
        if (nothingToSplice(bag) && !underway) {
            return stops;
        }
        // Keyed by the row of the arrival they sit at. A prescribed bank and an offered bank
        // on the way in go *before* their arrival's row; an offered bank graded only by its
        // arrival goes *after* it. A prescribed bank is spliced at its leg's break, so it
        // keeps its own cursor.
        Map<Integer, FarmingStopAdvice> offeredBefore = new HashMap<>();
        Map<Integer, FarmingStopAdvice> offeredAfter = new HashMap<>();
        for (InventorySim.Leg leg : bag.getLegs()) {
            for (InventorySim.Opportunity passed : leg.getPassableBanks()) {
                // put is safe: rowOf is strictly increasing, legs partition the demand
                // indices contiguously, and passableBanksIn excludes each leg's first
                // arrival, so no two offers share a row. Break either and an offer
                // silently disappears.
                (passed.isOnTheWayIn() ? offeredBefore : offeredAfter).put(rowOf.get(passed.getIndex()),
                        optionalBankStop(passed, withdrawals.offeredAt(passed.getIndex())));
            }
        }

        List<FarmingStopAdvice> withBanks = new ArrayList<>(stops.size() + bag.getLegs().size()
                + offeredBefore.size() + offeredAfter.size() + 1);
        addStartingBag(withBanks, withdrawals, underway);
        int next = 0;
        for (int index = 0; index < bag.getLegs().size(); index++) {
            InventorySim.Leg leg = bag.getLegs().get(index);
            int breaksAt = rowOf.get(leg.getFrom());
            while (next < breaksAt) {
                addWithItsOffers(withBanks, stops, offeredBefore, offeredAfter, next++);
            }
            if (leg.getBankAt() != null) {
                withBanks.add(bankStop(leg, withdrawals.atLeg(index)));
            } else if (leg.getOverflow() != null) {
                withBanks.add(overflowStop(leg));
            }
        }
        while (next < stops.size()) {
            addWithItsOffers(withBanks, stops, offeredBefore, offeredAfter, next++);
        }
        return withBanks;
    }

    /** The starting row's heading before the trip begins. */
    static final String SETTING_OFF_HEADING = "Withdraw before you set off";

    /** The starting row's heading once the player is partway round, with only deposits. */
    static final String NEXT_BANK_HEADING = "Next time you bank";

    /**
     * The starting row's heading partway round when it lists withdrawals. They are for the
     * stretch the player is on, which no bank row splits, so they are fetched before going on.
     */
    static final String BANK_FIRST_HEADING = "Bank first";

    /**
     * The bag to set off with, when the trip passes a bank later and some items can wait
     * there until the stop that wants them. A trip with no bank packs the whole "Take with
     * you" list, so it gets no row until the player is partway round, when the row is the
     * only list measured against the bag they carry now.
     *
     * <p><b>Not a shorter "Take with you".</b> That grid is a checklist of everything the
     * trip needs; this row lists the withdrawals for the first stretch only.
     * {@link WithdrawalPlanner} decides whether it is worth drawing.
     *
     * <p>Headed "Withdraw before you set off" because nothing has been routed yet, so there is no
     * bank to name. Partway round, the row stands for whichever bank the player opens next:
     * "Bank first" while it lists something to fetch, which the panel draws ahead of the next
     * stop, and "Next time you bank" for deposits alone. It stays unnamed there too: a stop
     * skipped as growing carries no route, so the bank the player last passed is not known
     * here.
     */
    private static void addStartingBag(List<FarmingStopAdvice> into, WithdrawalPlanner.Withdrawals withdrawals, boolean underway) {
        List<FarmingCarryItem> first = withdrawals.getBeforeSettingOff();
        // Partway round, deposits alone are reason enough for the row.
        if (first.isEmpty() && withdrawals.getDeposits().isEmpty()) {
            return;
        }
        into.add(row(FarmingStopAdvice.Kind.BANK_START, !underway ? SETTING_OFF_HEADING
                        : first.isEmpty() ? NEXT_BANK_HEADING : BANK_FIRST_HEADING, "").withdraw(first).deposit(withdrawals.getDeposits())
                .depositUrgent(withdrawals.isDepositsUrgent()).build());
    }

    /**
     * One row of the walkthrough, between the bank offered on the way in to it and the bank
     * offered once its patches are worked.
     *
     * <p>A bank before the patches cannot take their harvest. No offered row relies on it:
     * an offered row only withdraws. The bag simulation sheds a harvest only at a prescribed
     * bank, which stands after it, before the next leg's first arrival.
     */
    private static void addWithItsOffers(List<FarmingStopAdvice> into, List<FarmingStopAdvice> stops,
            Map<Integer, FarmingStopAdvice> offeredBefore, Map<Integer, FarmingStopAdvice> offeredAfter, int row) {
        if (offeredBefore.containsKey(row)) {
            into.add(offeredBefore.get(row));
        }
        into.add(stops.get(row));
        if (offeredAfter.containsKey(row)) {
            into.add(offeredAfter.get(row));
        }
    }

    /**
     * One bank stop: where to break, and how full the inventory was going to get if they
     * did not.
     *
     * <p>The slot count ("26 of 28 slots full") gives the player a claim to check against
     * their own inventory, so the row does not read as mere caution. It goes in the route
     * line under the heading: the panel draws {@code because} only for skipped stops, and
     * {@code note} only as a hover. The bank sits at an arrival already on the circuit, so
     * there is no journey for that line to describe otherwise.
     */
    private static FarmingStopAdvice bankStop(InventorySim.Leg leg, List<FarmingCarryItem> withdraw) {
        // Named by the bank, never by the arrival: Ortus Farm has no bank, and its rungs
        // bank at the Hunter Guild or in Civitas illa Fortis.
        return row(FarmingStopAdvice.Kind.BANK, bankNamed(leg.getBankPlace()),
                leg.getPeakSlots() + " of " + InventorySim.SLOTS + " slots full." + whyHere(leg)).withdraw(withdraw).build();
    }

    /** A row of this kind under this heading, with nothing planted or set aside. */
    private static FarmingStopAdvice.FarmingStopAdviceBuilder row(FarmingStopAdvice.Kind kind, String heading, String instruction) {
        return FarmingStopAdvice.builder().kind(kind).patchName(heading)
                .outcome(FarmingStopAdvice.Outcome.VISIT).instruction(instruction).because("")
                .plants(Collections.emptyList()).setAside(Collections.emptyList());
    }

    /**
     * A bank the trip walks past: offered, with what the detour costs, and nothing else.
     *
     * <p><b>No slot count</b>, unlike {@link #bankStop}: the bag fits without this stop, so
     * a comfortable number would only make the row look like a weaker prescribed bank.
     *
     * <p>Outcome {@code VISIT} because the bank sits at an arrival already on the circuit.
     * The kind makes it read as optional: the panel draws it muted and unnumbered.
     */
    private static FarmingStopAdvice optionalBankStop(InventorySim.Opportunity passed, List<FarmingCarryItem> withdraw) {
        String cost = costOfDetour(passed.getCost());
        // Named by the bank, as in {@link #bankStop}. Offered banks carry withdrawals too.
        // Most trips never fill the bag, so every bank row on them is an offered one. A long
        // detour carries none: WithdrawalPlanner sends its items out with the bank before it.
        return row(FarmingStopAdvice.Kind.BANK_OPTIONAL, bankNamed(passed.getBankPlace()), cost.isEmpty() ? "" : cost + ".")
                .withdraw(withdraw).build();
    }

    /**
     * The head of a bank row: the bank by name where one is known, and a bare "Bank" where
     * none is.
     *
     * <p>A bank is known only where the catalogue carries a measured figure. "Bank" alone
     * cannot send the player to the wrong one of Falador's two. The arrival's name never
     * stands in for a bank's.
     *
     * <p>A named bank can be shared: every rung at a stop may carry the stop's one figure and
     * bank.
     */
    private static String bankNamed(Bank bank) {
        return bank == null ? "Bank" : bank.getRowTitle();
    }

    /**
     * What reaching this bank costs, on one scale for every bank row: "On the way", "Short
     * detour", "Long detour". Empty for an unmeasured rung; the row is still drawn.
     */
    private static String costOfDetour(Arrival.BankProximity cost) {
        if (cost == null) {
            return "";
        }
        switch (cost) {
            case AT_ARRIVAL:
                return "On the way";
            case SHORT_WALK:
                return "Short detour";
            case FAR:
                return "Long detour";
            default:
                return "";
        }
    }

    /**
     * Why this bank and not a later one, in the player's terms, as sentences that follow
     * the slot count.
     *
     * <p>The slot count says the stop is necessary; this says whether it is cheap, which
     * decides whether the player follows the row. A brought-forward bank says so, because
     * stopping with the inventory half empty otherwise looks like a mistake.
     *
     * <p>Empty unless the rung the player is taking carries a measured figure. Unmeasured
     * rungs grade from the arrival's constant, which plans the split but is not shown;
     * {@code getBankCost} is null for them.
     */
    private static String whyHere(InventorySim.Leg leg) {
        if (leg.getBankCost() == null) {
            return "";
        }
        // Never brought forward at FAR: the cut only moves for a strictly better grade, so a
        // leg that still grades FAR is one the inventory picked rather than the route.
        String early = leg.isBankBroughtForward() && leg.getBankCost() != Arrival.BankProximity.FAR
                ? " Bank here early. This bank is closer." : "";
        String cost = costOfDetour(leg.getBankCost());
        return cost.isEmpty() ? "" : " " + cost + "." + early;
    }

    /** Whether every leg is one the player just walks, with nothing to say in front of it. */
    private static boolean nothingToSplice(InventorySim.Plan bag) {
        // Offered banks count: a trip needing no stop still offers the banks it passes.
        return bag.getLegs().stream().allMatch(leg -> leg.getBankAt() == null && leg.getOverflow() == null && leg.getPassableBanks().isEmpty());
    }

    /**
     * The row for a leg the bag does not survive and no bank can be reached on.
     *
     * <p>Outcome {@code VISIT} so the fold never hides it behind the skipped patches.
     */
    private static FarmingStopAdvice overflowStop(InventorySim.Leg leg) {
        return row(FarmingStopAdvice.Kind.OVERFLOW, leg.isHarvestRoomOnly() ? "No room left for the harvest here"
                        : "Your inventory fills up here", "")
                // What the sim found, then what the player can do about it.
                .actions(List.of(leg.getOverflow(), "Drop what you can spare, or leave the rest for another trip.")).build();
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.engine.SeedBox;
import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.*;
import com.larryfarming.farming.detection.*;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.*;
import com.larryfarming.snapshot.FarmingCarryItem;
import java.util.*;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;

/**
 * What to take on the run: tools, seeds, and whatever the chosen routes depend on.
 *
 * <p>Derived from the plan, so the travel lines name only the teleports this player is
 * actually taking today.
 *
 * <p>Held items stay on the list rather than being filtered out: the list is a pre-run
 * checklist, and a line that vanishes once owned cannot be checked off.
 *
 * <p>Throughout, the list errs towards packing a tool it cannot prove is unneeded. A tool
 * packed unused costs a slot; a tool left behind can cost the trip.
 */
public final class CarryPlanner {

    private CarryPlanner() {
    }

    /**
     * Breathing gear for the underwater patches. Both pieces must be worn (helmet on the
     * head, apparatus in the cape slot) or oxygen drains. Unlocked by the Freeing Pirate
     * Pete subquest of Recipe for Disaster, so the lines stay on the list unowned.
     *
     * <p>MISSING here means "not seen", not "not owned": Murphy re-issues both free, and
     * both can sit in a boat's cargo hold, which nothing here models.
     *
     * <p>Not the 2017 Halloween apparatus (21723), which shares the name and does nothing.
     */
    private static final int FISHBOWL_HELMET = 7534;
    private static final int DIVING_APPARATUS = 7535;

    /**
     * A neck-slot item that replaces both the helmet and the apparatus. Listed only for a
     * player who owns one, since it needs Sailing 63 and eight fragments.
     */
    private static final int MEDALLION_OF_THE_DEEP = 32386;

    /**
     * Every axe, best first; the line draws whichever one the player has.
     *
     * <p>Ordered by metal tier, with each Forestry two-handed felling axe right after the
     * one-handed axe of the same metal. Within a tier the one-handed axe comes first because
     * it leaves the shield slot free.
     */
    private static final int[] AXES = {
        20011, 28226, // 3rd age
        23673, 28220, // crystal
        13241,        // infernal
        6739, 28217,  // dragon
        23279,        // gilded
        1359, 28214,  // rune
        1357, 28211,  // adamant
        1355, 28208,  // mithril
        1361, 28205,  // black
        1353, 28202,  // steel
        1349, 28199,  // iron
        1351, 28196,  // bronze
    };

    /**
     * What to draw when the player has no axe: the bronze axe, not the first of
     * {@link #AXES}, which would show a third age axe as the thing to fetch.
     */
    private static final int PLAIN_AXE = ItemID.BRONZE_AXE;

    /** The log basket and the forestry basket, each in its open and closed form. */
    private static final int[] LOG_BASKETS = {28140, 28142, 28143, 28145};

    /**
     * The seed box, closed and open. Must match the ids {@code SeedBox} gates its contents
     * on, or the line never ticks.
     */
    private static final int[] SEED_BOX_IDS = {ItemID.SEED_BOX, ItemID.SEED_BOX_OPEN};

    /**
     * The bag for a trip, which may be one run or several walked as one circuit.
     *
     * <p>Takes every stop at once rather than being called per run: runes and tablets are
     * deduplicated per <em>arrival</em>, and that dedupe must span run boundaries. Seeds
     * arrive already split per run and are merged here.
     *
     * @param plans   the stops as planned, so only routes actually being taken are packed
     *                for; in any order
     * @param seeds   one allocation per run, in any order
     * @param cropFor what goes in the ground at each stop, index-aligned with {@code plans},
     *                or null where the caller does not know. The seed lines and the axe both
     *                read it. Null falls back to the allocation, which packs every seed
     *                dealt and keeps the axe on the list
     * @param inputs what has been seen at each patch: decides whether a patch holds a tree to
     *               fell and whether it is diseased. An unseen patch keeps the axe on the list
     */
    public static List<FarmingCarryItem> plan(List<StopPlan> plans, List<SeedPlan> seeds,
            List<List<Crop>> cropFor, PlayerState state, CapabilityResolver resolver, FarmingInputs inputs) {
        if (inputs == null) {
            inputs = FarmingInputs.none();
        }
        List<FarmingCarryItem> carry = new ArrayList<>();

        carry.add(tool(ItemID.SPADE, "Spade", state));
        // Otto's planting lesson retires the dibber permanently.
        if (resolver.resolve(Capability.BARE_HAND_PLANTING, state).getState() != CapabilityState.HAVE) {
            carry.add(tool(ItemID.DIBBER, "Seed dibber", state));
        }
        // A Fertile Soil caster carries the spell's runes and ash instead of compost; see
        // addTravel and addCompostUpgrades.
        boolean fertile = FertileSoil.inUse(inputs.getPreferences(), state, resolver.getBook());
        int fertileCasts = fertile ? FertileSoil.castsFor(plans, cropFor) : 0;
        CompostBins.Needs bins = CompostBins.over(plans, inputs, state);
        // Otherwise one compost line: the bottomless bucket if owned, loose ultracompost.
        if (packsBucket(plans, fertile, bins, state)) {
            // No AT_LEPRECHAUN branch: only a bucket owned as an item, carried or banked,
            // packs. One stored at the leprechaun shows only in its varbits (7915/7916).
            boolean inTheBag = BottomlessBucket.ITEM_IDS.stream().anyMatch(id -> ItemCounts.countCarried(state, id, null) > 0);
            carry.add(new FarmingCarryItem(FarmingCarryItem.Kind.TOOL,
                    ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED, "Bottomless compost bucket", 0, inTheBag
                            ? FarmingCarryItem.Availability.CARRIED : FarmingCarryItem.Availability.BANKED,
                    // Carried count is capped at one: a second bottomless bucket is no spare.
                    "", "", inTheBag ? 1 : 0));
        } else if (packsCompost(plans, fertile)) {
            carry.add(tool(ItemID.BUCKET_ULTRACOMPOST, "Ultracompost", state));
        }

        int clearingCoins = addTreeTools(carry, plans, cropFor, state, inputs);
        addFairyRingGear(carry, plans, state, resolver);
        int curePlantCasts = addCureTools(carry, plans, state, inputs);
        addDivingGear(carry, plans, state);
        addProtectionPayments(carry, plans, cropFor, state);
        // What is actually going in the ground, not what the rotation dealt out: a seat can
        // decline its dealt seed, such as a fruit tree left standing because no sapling on
        // hand matches or beats it, as the replant setting asks.
        List<SeedAllocation.Tally> planting = cropFor == null ? SeedPlan.shoppingList(seeds) : SeedPlan.goingInTheGround(plans, cropFor);
        addSeedBox(carry, planting, state);
        addSeeds(carry, planting, state);
        addFixedSeeds(carry, plans, cropFor, state, inputs);
        addTravel(carry, plans, state, curePlantCasts, fertileCasts);
        addCoins(carry, plans, state, clearingCoins);
        addCompostUpgrades(carry, bins, fertileCasts * FertileSoil.ASH_PER_CAST, state);
        carry.addAll(emptyBuckets(bins, state));

        // Less the seeds the player owns none of. The stop that wanted an unowned seed
        // already names the shortfall, so listing the seed here would ask for a planting the
        // run has dropped. Seeds only: an unowned tool stays on the list, because a missing
        // spade or axe costs the whole trip.
        carry.removeIf(item -> !item.isOwned() && item.getKind() == FarmingCarryItem.Kind.SEED);
        return carry;
    }

    /**
     * What it takes to reach these stops and nothing more: the travel items, runes and
     * fares, plus the fairy-ring staff and the secateurs it pushes out of the weapon slot.
     *
     * <p>A bank at a stop's arrival opens only once the player is there, so the way there
     * has to come out of an earlier bank. {@link #withoutTravel} strips the same things from
     * the stop, so the two halves add up to {@link #plan}.
     */
    static List<FarmingCarryItem> travelFor(List<StopPlan> plans, PlayerState state, CapabilityResolver resolver) {
        List<FarmingCarryItem> carry = new ArrayList<>();
        addFairyRingGear(carry, plans, state, resolver);
        addTravel(carry, plans, state, 0, 0);
        addCoins(carry, plans, state, 0);
        return carry;
    }

    /**
     * Whether a {@link #travelFor} line costs an inventory slot. With a rune pouch the runes
     * ride in it, and {@code InventorySim} charges the pouch as a fixture; without one, each
     * rune type is a stack of its own. The staff and the ring of charos(a) are worn. A line
     * the leprechaun holds is not in the bag either.
     *
     * <p>A pouch is assumed to hold every rune type the trip casts. It holds three, or four
     * for the divine pouch, which covers the teleports Larry routes by.
     */
    static boolean takesAbagSlot(FarmingCarryItem line, boolean ownsRunePouch) {
        if (line.getKind() == FarmingCarryItem.Kind.RUNES) {
            return !ownsRunePouch;
        }
        if (line.getItemId() == RING_OF_CHAROS_ACTIVATED || line.getAvailability() == FarmingCarryItem.Availability.AT_LEPRECHAUN) {
            return false;
        }
        for (int staff : STAFF_IDS) {
            if (line.getItemId() == staff) {
                return false;
            }
        }
        return true;
    }

    /**
     * Whether a {@link #travelFor} line is used up on the way: a stack of tablets, one
     * broken per arrival, or runes, withdrawn to the cast. Coins carry a count too, but a
     * fare leaves the stack in the bag.
     */
    static boolean spentOnTheWay(FarmingCarryItem line) {
        return line.getKind() == FarmingCarryItem.Kind.RUNES || line.getKind() == FarmingCarryItem.Kind.TRAVEL && line.getQuantity() > 0
                        && line.getItemId() != ItemID.COINS;
    }

    /**
     * Every item id that counts for the same packing-list line as this one: each axe, basket,
     * staff and bucket form, each dose of compost potion, an empty bucket and its note, every
     * charge tier of a travel item, and a crop's seed, seedlings and sapling. A line names one
     * id; the bag may hold any of these.
     */
    static Set<Integer> formsOf(int itemId) {
        if (BottomlessBucket.ITEM_IDS.contains(itemId)) {
            return BottomlessBucket.ITEM_IDS;
        }
        for (int[] family : new int[][]{AXES, LOG_BASKETS, STAFF_IDS, CompostBins.POTIONS, CompostBins.EMPTY_BUCKETS}) {
            for (int id : family) {
                if (id == itemId) {
                    return idsOf(family);
                }
            }
        }
        int[] travel = CarryItems.formsOf(itemId);
        if (travel != null) {
            return idsOf(travel);
        }
        for (CropData data : CropData.values()) {
            List<Integer> forms = data.getPlantingForms();
            if (itemId > 0 && forms.contains(itemId)) {
                Set<Integer> planting = new HashSet<>(forms);
                // Seed-planted crops store 0 in their potted columns.
                planting.remove(0);
                return planting;
            }
        }
        return Set.of(itemId);
    }

    private static Set<Integer> idsOf(int[] family) {
        return Arrays.stream(family).boxed().collect(Collectors.toCollection(HashSet::new));
    }

    /** The same stop with no way of getting there, for a stretch already standing at it. */
    static StopPlan withoutTravel(StopPlan plan) {
        return plan.withRoute(null).withNeeds(Set.of()).withTeleport(null);
    }

    /**
     * One coins line for everything the day charges: the chosen routes' fares and the fees
     * for trees someone else clears.
     *
     * <p>Boat fares come from each route. The minecart toll comes from the
     * {@link Capability#LOVAKENGJ_MINECART} capability instead, because it belongs to the
     * network and The Forsaken Tower waives it for good. An unobserved quest still packs
     * the fare.
     *
     * @param clearingCoins the gardeners' fees to clear trees, from {@link #addTreeTools}
     */
    private static void addCoins(List<FarmingCarryItem> carry, List<StopPlan> plans, PlayerState state, int clearingCoins) {
        int rides = 0;
        int charters = 0;
        int fares = 0;
        // The same total priced as though the ring of charos(a) were worn.
        int wornFares = 0;
        for (StopPlan plan : plans) {
            if (!plan.isVisit()) {
                continue;
            }
            if (plan.getNeeds() != null && plan.getNeeds().contains(Capability.LOVAKENGJ_MINECART)) {
                rides++;
            }
            if (plan.getRoute() == null || plan.getRoute().getFareCoins() == 0) {
                continue;
            }
            int fare = plan.getRoute().getFareCoins();
            if (!isCharter(plan)) {
                fares += fare;
                wornFares += fare;
                continue;
            }
            boolean cabinFever = finished(state, "Cabin Fever");
            fares += charterFare(fare, cabinFever, isWearingCharos(state));
            wornFares += charterFare(fare, cabinFever, true);
            charters++;
        }
        if (rides > 0 && !finished(state, "The Forsaken Tower")) {
            fares += rides * MINECART_FARE;
            wornFares += rides * MINECART_FARE;
        }
        if (fares == 0 && clearingCoins == 0) {
            return;
        }
        // Priced as the player stands. The worn-ring price rides along as a note, which the
        // panel shows on hover.
        int total = fares + clearingCoins;
        FarmingCarryItem coins = item(FarmingCarryItem.Kind.TRAVEL, ItemID.COINS, "Coins", total, total, state);
        String trees = clearingCoins > GARDENER_FEE ? "trees" : "a tree";
        String note = clearingCoins == 0 ? "For boat and minecart fares." : fares == 0 ? "To have " + trees + " cleared."
                : "For fares, and to have " + trees + " cleared.";
        if (charters > 0 && ownsCharos(state) && !isWearingCharos(state)) {
            note = note + " Only " + (wornFares + clearingCoins) + " coins if you wear your ring of charos(a).";
        }
        carry.add(coins.withNote(note));
        // The ring gets its own line, kept once worn. Only for a player who owns one, since
        // it is a Garden of Tranquillity reward.
        if (charters > 0 && ownsCharos(state)) {
            carry.add(item(FarmingCarryItem.Kind.TRAVEL, RING_OF_CHAROS_ACTIVATED,
                    "Ring of charos(a)", 0, 1, state).withNote("Halves charter fares when worn."));
        }
    }

    /** Whether this route pays a charter captain, the only fares the discounts apply to. */
    private static boolean isCharter(StopPlan plan) {
        return plan.getNeeds() != null && plan.getNeeds().contains(Capability.CHARTER_SHIP);
    }

    /**
     * What a charter costs: halved by Cabin Fever, and halved again by a worn ring of
     * charos(a). Rounded up at each halving, so the packed coins are never one short.
     */
    private static int charterFare(int base, boolean cabinFever, boolean wearingCharos) {
        int fare = base;
        if (cabinFever) {
            fare = (fare + 1) / 2;
        }
        if (wearingCharos) {
            fare = (fare + 1) / 2;
        }
        return fare;
    }

    private static boolean finished(PlayerState state, String quest) {
        return state != null && state.getQuests().get(quest) == QuestStatus.COMPLETED;
    }

    /** Worn, not merely owned: the discount needs the ring on the finger. */
    private static boolean isWearingCharos(PlayerState state) {
        if (state == null) {
            return false;
        }
        ItemStack ring = state.getEquipment().get(EquipmentSlot.RING);
        return ring != null && ring.getItemId() == RING_OF_CHAROS_ACTIVATED;
    }

    /** Holds one anywhere it could be fetched from, the bank included. */
    private static boolean ownsCharos(PlayerState state) {
        return ItemCounts.ownsAny(state, RING_OF_CHAROS_ACTIVATED);
    }

    /** Coins per Lovakengj minecart ride. */
    private static final int MINECART_FARE = 20;

    /** The activated ring. The plain one (4202) discounts nothing. */
    private static final int RING_OF_CHAROS_ACTIVATED = 6465;

    /**
     * The two ways to cure a diseased crop, and which patches take which.
     *
     * <p>From the wiki: "Players may treat plants in diseased herb, flower, allotment, hops,
     * hardwood tree, celastrus, belladonna, cactus, and mushroom patches with plant cure...
     * For diseased trees, fruit trees, spirit trees and bushes, the player may use secateurs
     * on the plant to trim the diseased branch." Hardwood trees take plant cure, so the
     * split cannot be derived from whether the patch grows a tree.
     *
     * <p>Deliberately not exhaustive over {@link PatchType}. A patch the wiki sentence does
     * not name draws no cure line, because a wrong cure is a wasted slot.
     */
    private static final Set<PatchType> PRUNED_WITH_SECATEURS = EnumSet.of(
            PatchType.TREE, PatchType.FRUIT_TREE, PatchType.SPIRIT_TREE, PatchType.BUSH);

    private static final Set<PatchType> CURED_WITH_PLANT_CURE = EnumSet.of(
            PatchType.HERB, PatchType.FLOWER, PatchType.ALLOTMENT, PatchType.HOPS,
            PatchType.HARDWOOD_TREE, PatchType.CELASTRUS, PatchType.BELLADONNA, PatchType.CACTUS, PatchType.MUSHROOM);

    /** Either opens a fairy ring; the dramen staff first, as the one a player meets first. */
    private static final int[] STAFF_IDS = {Loadouts.DRAMEN_STAFF, Loadouts.LUNAR_STAFF};

    /**
     * Cure Plant, the Lunar spell that cures one patch per cast for no inventory slot.
     *
     * <p>Elemental staves are not modelled for any spell, so a staff of earth user is
     * over-asked eight earth runes a cast.
     */
    private static final int CURE_PLANT_MAGIC_LEVEL = 66;
    private static final int EARTH_PER_CURE_PLANT = 8;
    private static final int ASTRAL_PER_CURE_PLANT = 1;


    /** The gardener's fee to clear a regular, fruit or hardwood tree. */
    private static final int GARDENER_FEE = 200;

    /**
     * The Woodcutting level to chop each lumber or hardwood tree once grown, the same as the
     * wild tree. Fruit trees chop at any level.
     */
    private static final Map<Crop, Integer> WOODCUTTING_LEVEL = Map.of(Crop.OAK, 15, Crop.WILLOW, 30, Crop.TEAK, 35,
            Crop.MAPLE, 45, Crop.MAHOGANY, 50, Crop.YEW, 60, Crop.CAMPHOR, 66, Crop.MAGIC, 75, Crop.IRONWOOD, 80, Crop.ROSEWOOD, 92);

    /** How a grown tree comes out of its patch before the next one goes in. */
    private enum Clearing {
        /** Chopped down, then the stump dug up. */
        AXE,
        /** Cleared by the patch's gardener for {@link #GARDENER_FEE}, no logs given. */
        GARDENER
    }

    /** What the trees being replaced ask of the bag. */
    private static final class TreeWork {
        private boolean axe;
        private boolean logs;
        private int coins;
    }

    /**
     * The axe for any tree being chopped, the log basket for runs that produce logs, and
     * the gardener's coins for any tree {@link #gardenerClears} names.
     *
     * <p>A grown tree must come out before the patch takes the next sapling, so the axe is
     * required and listed even when unowned. The basket is optional, so it is listed only
     * when owned. Fruit trees yield fruit, which a log basket will not hold.
     *
     * @return the coins the clearing costs, for the one coins line
     */
    private static int addTreeTools(List<FarmingCarryItem> carry, List<StopPlan> plans,
            List<List<Crop>> cropFor, PlayerState state, FarmingInputs inputs) {
        TreeWork work = treeWorkIn(plans, cropFor, state, inputs);
        if (work.axe) {
            carry.add(tool(bestOwned(state, AXES, PLAIN_AXE), "Axe", state, AXES));
        }
        if (work.logs) {
            FarmingCarryItem basket = tool(LOG_BASKETS[0], "Log basket", state, LOG_BASKETS);
            if (basket.isOwned()) {
                carry.add(basket);
            }
        }
        return work.coins;
    }

    /** Where the log basket rides on a trip. */
    enum BasketPlace {
        /** Left in the bank: no logs come off, or the player owns no basket. */
        NONE,
        /** In the inventory, because a route needs the cape slot for its teleport. */
        BAG,
        /** Worn in the cape slot, which no route on the trip needs. */
        BACK
    }

    /** Teleports from items worn in the cape slot. */
    private static final Set<Capability> CAPE_SLOT_TELEPORTS = EnumSet.of(Capability.ARDOUGNE_CLOAK_1, Capability.ARDOUGNE_CLOAK_2,
            Capability.ARDOUGNE_CLOAK_3, Capability.ARDOUGNE_CLOAK_4,
            Capability.FARMING_CAPE, Capability.CONSTRUCTION_CAPE, Capability.FISHING_CAPE,
            Capability.HUNTER_CAPE, Capability.QUEST_CAPE, Capability.DIARY_CAPE);

    /**
     * Where the log basket goes on this trip.
     *
     * <p>The basket is wearable in the cape slot, so worn it costs no inventory slot. A
     * route that teleports by a cape-slot item takes the slot first. Either way one of the
     * two takes an inventory slot, so the cape is worn for its teleport and the basket
     * rides in the bag.
     */
    static BasketPlace basketPlace(List<StopPlan> plans, List<List<Crop>> cropFor, PlayerState state, FarmingInputs inputs) {
        if (state == null || bestOwned(state, LOG_BASKETS, 0) == 0 || !treeWorkIn(plans, cropFor, state, inputs).logs) {
            return BasketPlace.NONE;
        }
        for (StopPlan plan : plans) {
            if (plan.isVisit() && !Collections.disjoint(plan.getNeeds(), CAPE_SLOT_TELEPORTS)) {
                return BasketPlace.BAG;
            }
        }
        return BasketPlace.BACK;
    }

    /**
     * The items clearing these stops' trees puts in the bag, by item id: the plain axe
     * standing for any axe, and coins for a fee.
     */
    static Set<Integer> treeToolsFor(List<StopPlan> plans, List<List<Crop>> cropFor, PlayerState state, FarmingInputs inputs) {
        TreeWork work = treeWorkIn(plans, cropFor, state, inputs);
        Set<Integer> tools = new HashSet<>();
        if (work.axe) {
            tools.add(PLAIN_AXE);
        }
        if (work.coins > 0) {
            tools.add(ItemID.COINS);
        }
        return tools;
    }

    /** What clearing these stops' grown trees asks of the bag, patch by patch. */
    private static TreeWork treeWorkIn(List<StopPlan> plans, List<List<Crop>> cropFor, PlayerState state, FarmingInputs inputs) {
        TreeWork work = new TreeWork();
        for (int index = 0; index < plans.size(); index++) {
            StopPlan plan = plans.get(index);
            if (!plan.isVisit()) {
                continue;
            }
            // The axe follows the planting, not the patch: a tree left standing is not
            // cleared, so it needs no axe.
            if (nothingIsPlantedAt(cropFor, index)) {
                continue;
            }
            for (PatchRef ref : plan.getStop().getPatches()) {
                PatchType type = ref.type();
                if (type == null) {
                    continue;
                }
                // Asked per patch, because one stop can cover several patches (the three
                // Fossil Island hardwoods are one stop).
                Clearing clearing = clearingAt(type, ref, state, inputs);
                if (clearing == Clearing.AXE) {
                    work.axe = true;
                    work.logs |= type != PatchType.FRUIT_TREE;
                } else if (clearing == Clearing.GARDENER) {
                    work.coins += GARDENER_FEE;
                }
            }
        }
        return work;
    }

    /**
     * How the tree in this patch comes out, or null when nothing stands to be cleared.
     *
     * <p>Calquat is absent: per the wiki it is cleared with a spade like a bush, even though
     * it is classified as a tree. No run visits a redwood, celastrus or crystal tree patch.
     */
    private static Clearing clearingAt(PatchType type, PatchRef ref, PlayerState state, FarmingInputs inputs) {
        if (!treeStandsAt(type, ref, inputs)) {
            return null;
        }
        PatchPrediction seen = inputs.patchAt(ref);
        return gardenerClears(type, seen == null ? null : seen.getCrop(), state) ? Clearing.GARDENER : Clearing.AXE;
    }

    /**
     * Whether a tree may stand in this patch and has to come out before the next one goes in:
     * a tree patch not known to hold nothing to fell. A grown tree still owed its health
     * check stands, as a checked one does. The row's clearing line asks the same question,
     * so the line and the bag agree.
     */
    static boolean treeStandsAt(PatchType type, PatchRef ref, FarmingInputs inputs) {
        return (type == PatchType.TREE || type == PatchType.HARDWOOD_TREE || type == PatchType.FRUIT_TREE)
                && !nothingToFellAt(inputs, ref);
    }

    /**
     * Whether the gardener clears this grown tree for {@link #GARDENER_FEE}, rather than the
     * player chopping it. The row's wording asks the same question, so the line and the bag
     * agree.
     *
     * <p>Only for a lumber tree or hardwood above the player's Woodcutting level: chopping
     * is free and gives the logs, so the fee is the last resort. An unseen tree keeps the
     * axe. A fruit tree chops at any level.
     *
     * @param crop the tree standing there, or null when unseen
     */
    static boolean gardenerClears(PatchType type, Crop crop, PlayerState state) {
        if (type != PatchType.TREE && type != PatchType.HARDWOOD_TREE || crop == null || state == null) {
            return false;
        }
        Integer needs = WOODCUTTING_LEVEL.get(crop);
        return needs != null && state.getSkillLevel(Skill.WOODCUTTING) < needs;
    }

    /**
     * Breathing gear, for a trip with any underwater stop.
     *
     * <p>Asked of the patch, not the planting (unlike the axe): visiting the patch at all
     * needs it.
     *
     * <p>No inventory slot is charged and no {@code InventorySim.Fixture} exists for it,
     * because all of it is worn on the dive.
     */
    private static void addDivingGear(List<FarmingCarryItem> carry, List<StopPlan> plans, PlayerState state) {
        if (!anyDiveAmong(plans)) {
            return;
        }
        if (ItemCounts.ownsAny(state, MEDALLION_OF_THE_DEEP)) {
            carry.add(tool(MEDALLION_OF_THE_DEEP, "Medallion of the deep", state).withNote("Wear it instead of the helmet and apparatus."));
            return;
        }
        carry.add(tool(FISHBOWL_HELMET, "Fishbowl helmet", state).withNote("Wear both. The oxygen lasts only while you wear them."));
        carry.add(tool(DIVING_APPARATUS, "Diving apparatus", state));
    }

    /**
     * The farmers' fees, for the stops that pay one. {@link Protection} pays only from a fee
     * the player already owns, so this line never asks for something to gather, and
     * {@code InventoryDemands} keeps a slot for exactly these.
     *
     * @param cropFor what goes in the ground at each stop, or null, which pays for every
     *                patch at the stop
     */
    private static void addProtectionPayments(List<FarmingCarryItem> carry,
            List<StopPlan> plans, List<List<Crop>> cropFor, PlayerState state) {
        for (int index = 0; index < plans.size(); index++) {
            StopPlan plan = plans.get(index);
            if (!plan.isVisit()) {
                continue;
            }
            int planting = cropFor == null ? plan.getStop().getPatches().size() : cropFor.get(index).size();
            Protection.Fee fee = Protection.paymentAt(plan.getStop(), planting, state);
            if (fee == null) {
                continue;
            }
            carry.add(item(FarmingCarryItem.Kind.TOOL, fee.itemId, fee.name,
                    fee.amount, fee.amount, state).withNote(fee.farmer + "'s protection fee."));
        }
    }

    /**
     * Whether the bag packs its compost line, the bottomless bucket or loose ultracompost.
     * The packing list and the bag simulation both ask this, so they agree on the bucket's
     * slot. A trip of only anima plants takes no compost and leaves the line off, and so
     * does a Fertile Soil trip, whose casts treat every patch.
     *
     * @param fertile whether the trip casts Fertile Soil
     */
    static boolean packsCompost(List<StopPlan> plans, boolean fertile) {
        return usesCompost(plans) && !fertile;
    }

    /**
     * Whether the bag packs the bottomless bucket: the player owns it as an item, and the
     * compost line packs or a bin empties into it. The packing list and the bag simulation
     * both ask this.
     */
    static boolean packsBucket(List<StopPlan> plans, boolean fertile, CompostBins.Needs bins, PlayerState state) {
        return BottomlessBucket.toHand(state) && (packsCompost(plans, fertile) || bins.isBucket());
    }

    /** Whether any visited stop on this trip treats its patch, whatever its patch type. */
    private static boolean usesCompost(List<StopPlan> plans) {
        return plans.stream().anyMatch(FertileSoil::composts);
    }

    /**
     * Whether any visited stop on this trip covers a seaweed patch. Asked of every patch the
     * stop covers, not of its own patch type.
     */
    private static boolean anyDiveAmong(List<StopPlan> plans) {
        return plans.stream().filter(StopPlan::isVisit).flatMap(plan -> plan.getStop().getPatches().stream())
                .anyMatch(ref -> ref.type() == PatchType.SEAWEED);
    }

    /**
     * Whether this stop puts nothing in the ground, so nothing there needs clearing first.
     * A null or short {@code cropFor} answers false, keeping the axe.
     */
    private static boolean nothingIsPlantedAt(List<List<Crop>> cropFor, int index) {
        return cropFor != null && index < cropFor.size() && cropFor.get(index).isEmpty();
    }

    /**
     * What it takes to cure the patches seen diseased.
     *
     * <p>Drawn only for disease actually seen, unlike the axe's pack-by-default. A cure is
     * per patch and per kind, so packing against the chance of disease would add both items
     * to every trip. Disease does not kill on the cycle it appears, so a patch that turns
     * sick en route is caught on the next run.
     *
     * <p>A player who can cast Cure Plant and owns the runes is packed runes instead of
     * either item. The spell cures any patch type, including ones the tables above do not
     * place.
     *
     * @return how many casts the trip needs, for {@code addTravel} to price in runes; zero
     *         when the items were named instead or nothing is sick. The caller prices them
     *         so the cure runes merge with a Lunar run's teleport runes into one line each
     */
    private static int addCureTools(List<FarmingCarryItem> carry, List<StopPlan> plans, PlayerState state, FarmingInputs inputs) {
        boolean prune = false;
        // Counted once per patch: two runs on one trip can name the same patch.
        Set<PatchRef> counted = new HashSet<>();
        int cures = 0;
        int sick = 0;
        for (StopPlan plan : plans) {
            if (!plan.isVisit()) {
                continue;
            }
            for (PatchRef ref : plan.getStop().getPatches()) {
                PatchType type = ref.type();
                if (type == null || !standsDiseased(inputs, ref) || !counted.add(ref)) {
                    continue;
                }
                // Counted before the tables: a cast cures any patch type.
                sick++;
                if (PRUNED_WITH_SECATEURS.contains(type)) {
                    // Secateurs are not used up, so one pair covers the run.
                    prune = true;
                } else if (CURED_WITH_PLANT_CURE.contains(type)) {
                    cures++;
                }
            }
        }
        if (sick > 0 && canCastCurePlant(state) && hasRunesToCure(state, sick)) {
            return sick;
        }
        // Magic secateurs prune as well as any pair, and a player who owns them already
        // brings them: the weapon slot asks for them, or the bag does beside the staff.
        // The plain pair shares one leprechaun slot with magic secateurs, which ItemCounts
        // tells apart with the type varbit.
        if (prune && !ItemCounts.ownsAny(state, Loadouts.MAGIC_SECATEURS)) {
            carry.add(tool(ItemID.SECATEURS, "Secateurs", state));
        }
        // Consumed per patch cured, so this line carries a count.
        if (cures > 0) {
            carry.add(item(FarmingCarryItem.Kind.TOOL, ItemID.PLANT_CURE, "Plant cure", cures, cures, state));
        }
        return 0;
    }

    /**
     * Whether the player owns the runes for every cast, the bank included.
     *
     * <p>Without the runes the bag names the items instead: a gardener sells plant cure
     * beside the patch, where missing runes leave the player unable to cure at all.
     */
    private static boolean hasRunesToCure(PlayerState state, int casts) {
        return ItemCounts.countOwned(state, Rune.EARTH.getItemId(), null)
                        >= casts * EARTH_PER_CURE_PLANT && ItemCounts.countOwned(state, Rune.ASTRAL.getItemId(), null)
                        >= casts * ASTRAL_PER_CURE_PLANT;
    }

    /**
     * Whether this player can cure a patch with a spell rather than a bottle.
     *
     * <p>Being on the Lunar spellbook implies Lunar Diplomacy is done. The book comes from
     * the varbit, not the resolver, which carries the book the <em>run</em> is written for.
     * Uses the real Magic level, so a boost or an unread level falls back to the bottle.
     */
    private static boolean canCastCurePlant(PlayerState state) {
        return FarmingAdviceBuilder.openBookOf(state) == Spellbook.LUNAR && state.getSkillLevel(Skill.MAGIC) >= CURE_PLANT_MAGIC_LEVEL;
    }

    /** Whether this patch has been seen diseased. */
    private static boolean standsDiseased(FarmingInputs inputs, PatchRef ref) {
        PatchPrediction seen = inputs.patchAt(ref);
        return seen != null && seen.getState() == CropState.DISEASED;
    }

    /**
     * Whether this patch is <em>known</em> to hold nothing an axe could fell. An unseen patch
     * answers false.
     *
     * <ul>
     * <li>Dead: comes out with a spade.</li>
     * <li>Diseased: cured, not felled; {@code addCureTools} packs for it.</li>
     * <li>Idle: weeds decode as state {@code GROWING}, so this relies on
     *     {@link PatchPrediction#isIdle()} rather than the state.</li>
     * <li>A stump: shares a {@code CropState} with the standing tree, so
     *     {@link PatchPrediction#isFellable()} separates them ("Chop down" vs "Clear").</li>
     * <li>Part-grown: decided by readiness, not state, because a tree still owed its health
     *     check also decodes {@code GROWING} and does need the axe.
     *     {@code LIKELY_READY} keeps the axe.</li>
     * </ul>
     */
    private static boolean nothingToFellAt(FarmingInputs inputs, PatchRef ref) {
        PatchPrediction seen = inputs.patchAt(ref);
        if (seen == null) {
            return false;
        }
        if (seen.getState() == CropState.DEAD || seen.getState() == CropState.DISEASED || seen.isIdle()) {
            return true;
        }
        // A HARVESTABLE patch that is not fellable is a stump or a spade-cleared crop.
        if (seen.getState() == CropState.HARVESTABLE && !seen.isFellable()) {
            return true;
        }
        // GROWING only: a fruit tree restocking fruit is HARVESTABLE with a timer running,
        // which readiness would call growing while the tree is fellable. A zero clock would
        // read every timer as growing, so it keeps the axe.
        //
        // The tree owed its health check keeps the axe only because its finish time is past
        // and reads READY. This relies on every tree crop having a growth rate.
        long now = inputs.getNowEpochSec();
        return seen.getState() == CropState.GROWING && now > 0 && seen.readinessAt(now) == PatchPrediction.Readiness.GROWING;
    }

    /**
     * What the finished compost bins and Fertile Soil take to come out ultracompost: the
     * potion and one ash line for both.
     *
     * @param fertileAsh the ash Fertile Soil casts take
     */
    private static void addCompostUpgrades(List<FarmingCarryItem> carry, CompostBins.Needs bins, int fertileAsh, PlayerState state) {
        if (bins.getDoses() > 0) {
            carry.add(potion(bins.getDoses(), state).withNote("One dose turns a finished bin of compost into supercompost."));
        }
        // The bins empty only on ash the player owns, so with bins to upgrade the bag takes
        // what is owned and Fertile Soil's last casts give supercompost.
        int ash = bins.getAsh() > 0 ? Math.min(bins.getAsh() + fertileAsh, ItemCounts.countOwned(state, ItemID.FOSSIL_VOLCANIC_ASH, null))
                : fertileAsh;
        if (ash > 0) {
            carry.add(item(FarmingCarryItem.Kind.TOOL, ItemID.FOSSIL_VOLCANIC_ASH, "Volcanic ash", ash, ash, state)
                    .withNote("For ultracompost: 25 per finished bin, two per Fertile Soil cast."));
        }
    }

    /** A stack of empty buckets to store at the leprechaun, asked for when they run low. */
    static final int BUCKET_RESTOCK = 100;

    /**
     * The empty buckets the bins empty into, which the leprechaun hands out at the farm.
     * Those carried count first, then those it stores, and the bag packs only the rest,
     * noted, in one slot. When the player's empty buckets run low, the lines ask for a noted
     * stack of {@link #BUCKET_RESTOCK} to store there instead: what the bank holds of it, and
     * the rest to buy, under the plain bucket so the two lines stay apart.
     *
     * <p>The packing list and the bag simulation both read these lines, so the bag charges
     * the noted slot only for a {@code BANKED} line.
     */
    static List<FarmingCarryItem> emptyBuckets(CompostBins.Needs bins, PlayerState state) {
        int need = bins.getBuckets();
        if (need == 0 && !bins.isRestock()) {
            return List.of();
        }
        int carried = CompostBins.emptyBuckets(state, true);
        int stored = ItemCounts.countInLeprechaunStorage(state, ItemID.BUCKET_EMPTY);
        if (!bins.isRestock()) {
            // The bins share only the buckets the player owns, so the bank covers a shortfall.
            FarmingCarryItem.Availability availability = carried >= need ? FarmingCarryItem.Availability.CARRIED
                    : carried + stored >= need ? FarmingCarryItem.Availability.AT_LEPRECHAUN : FarmingCarryItem.Availability.BANKED;
            boolean banked = availability == FarmingCarryItem.Availability.BANKED;
            return List.of(bucketLine(ItemID.Cert.BUCKET_EMPTY, banked ? need - stored : need, availability, carried,
                    banked ? "Noted, for the compost bins." : "For the compost bins."));
        }
        int inBank = CompostBins.emptyBuckets(state, false) - carried - stored;
        int toHand = Math.min(BUCKET_RESTOCK, carried + inBank);
        boolean banked = carried < toHand;
        List<FarmingCarryItem> lines = new ArrayList<>(2);
        if (toHand > 0) {
            lines.add(bucketLine(ItemID.Cert.BUCKET_EMPTY, toHand,
                    banked ? FarmingCarryItem.Availability.BANKED : FarmingCarryItem.Availability.CARRIED, carried,
                    banked ? "Noted, to store with the leprechaun." : "For the compost bins."));
        }
        if (toHand < BUCKET_RESTOCK) {
            lines.add(bucketLine(ItemID.BUCKET_EMPTY, BUCKET_RESTOCK - toHand, FarmingCarryItem.Availability.MISSING, 0,
                    (banked ? "" : "Noted, to store with the leprechaun. ") + "Farming shops sell them."));
        }
        return lines;
    }

    /** One empty bucket line: the noted or plain sprite, how many, and where they are. */
    private static FarmingCarryItem bucketLine(int itemId, int quantity, FarmingCarryItem.Availability availability, int carried,
            String note) {
        return new FarmingCarryItem(FarmingCarryItem.Kind.TOOL, itemId, "Empty bucket", quantity, availability, "", "", carried)
                .withNote(note);
    }

    /** Whether the bag packs noted empty buckets from the bank, which take a slot. */
    static boolean bringsBuckets(CompostBins.Needs bins, PlayerState state) {
        return emptyBuckets(bins, state).stream().anyMatch(line -> line.getAvailability() == FarmingCarryItem.Availability.BANKED);
    }

    /**
     * The compost potion line, counted in doses: one slot holds up to four doses. The
     * sprite is the full vial. The leprechaun cannot store potions, so there is no
     * {@code AT_LEPRECHAUN} branch.
     */
    private static FarmingCarryItem potion(int doses, PlayerState state) {
        int carried = CompostBins.doses(state, true);
        FarmingCarryItem.Availability availability = carried >= doses ? FarmingCarryItem.Availability.CARRIED
                : CompostBins.doses(state, false) >= doses ? FarmingCarryItem.Availability.BANKED : FarmingCarryItem.Availability.MISSING;
        return new FarmingCarryItem(FarmingCarryItem.Kind.TOOL, ItemID.SUPERCOMPOST_POTION_4, "Compost potion", doses, availability, "", "", carried);
    }

    /**
     * The first of these the player owns, or {@code none} when they own none, including
     * before the bank has been seen.
     */
    private static int bestOwned(PlayerState state, int[] itemIds, int none) {
        for (int itemId : itemIds) {
            if (ItemCounts.ownsAny(state, itemId)) {
                return itemId;
            }
        }
        return none;
    }

    /**
     * Whether the trip needs a fairy-ring staff wielded: a visit rides a fairy ring, and
     * {@link Capability#STAFFLESS_FAIRY_RINGS} (the elite Lumbridge &amp; Draynor diary) is
     * not known to be held. UNKNOWN keeps the staff.
     *
     * <p>The staff then holds the loadout plan's weapon slot, and the bag lists
     * it too unless it is already on the player (see {@code addFairyRingGear}).
     */
    public static boolean staffWielded(List<StopPlan> plans, PlayerState state, CapabilityResolver resolver) {
        boolean ringsUsed = plans.stream().anyMatch(plan -> plan.isVisit() && plan.getNeeds().contains(Capability.FAIRY_RINGS));
        return ringsUsed && resolver.resolve(Capability.STAFFLESS_FAIRY_RINGS, state).getState() != CapabilityState.HAVE;
    }

    /**
     * What a trip that needs a fairy-ring staff wielded ({@link #staffWielded}) adds to the
     * bag; nothing otherwise.
     *
     * <p>The staff, when the player has none on them. The weapon slot asks for it as well,
     * but a ring refuses the player without it, so the bag names it like any tool the trip
     * cannot do without. Either staff serves; the line names the one the player owns, and
     * the dramen staff when they own neither.
     *
     * <p>Magic secateurs, when the player owns a pair, whether or not the staff is already
     * on them: the staff holds the weapon slot either way. They raise yield from the
     * inventory, so they ride there. Without the staff the loadout plan puts them in the
     * weapon slot instead, never both.
     */
    private static void addFairyRingGear(List<FarmingCarryItem> carry, List<StopPlan> plans, PlayerState state, CapabilityResolver resolver) {
        if (!staffWielded(plans, state, resolver)) {
            return;
        }
        if (!carriedAny(state, STAFF_IDS)) {
            int staff = bestOwned(state, STAFF_IDS, Loadouts.DRAMEN_STAFF);
            String name = staff == Loadouts.LUNAR_STAFF ? "Lunar staff" : "Dramen staff";
            carry.add(tool(staff, name, state, STAFF_IDS).withNote("Wield it to use fairy rings."));
        }
        if (ItemCounts.ownsAny(state, Loadouts.MAGIC_SECATEURS)) {
            carry.add(tool(Loadouts.MAGIC_SECATEURS, "Magic secateurs", state).withNote("More herbs, allotment crops and berries."));
        }
    }

    /**
     * The seed box, on a trip with seeds to put in it, listed only when owned.
     *
     * <p>Where the kinds it holds and the kinds the trip plants come to more than it fits,
     * the line names the kinds the trip does not plant, to empty at the bank: the plan
     * gives their room to the trip's seeds.
     *
     * <p>{@code InventorySim} charges the box a slot on the same test.
     */
    private static void addSeedBox(List<FarmingCarryItem> carry, List<SeedAllocation.Tally> planting, PlayerState state) {
        if (planting.isEmpty()) {
            return;
        }
        FarmingCarryItem box = tool(SEED_BOX_IDS[0], "Seed box", state, SEED_BOX_IDS);
        if (!box.isOwned()) {
            return;
        }
        Set<Integer> kinds = new HashSet<>();
        planting.forEach(tally -> Optional.ofNullable(CropData.forCrop(tally.getCrop())).map(CropData::getSeedItemId)
                .filter(CropData::boxesAsAseed).ifPresent(kinds::add));
        List<String> idle = new ArrayList<>();
        for (ItemStack stack : SeedBox.contentsCarried(state) ? state.getSeedBox() : List.<ItemStack>of()) {
            if (CropData.boxesAsAseed(stack.getItemId()) && kinds.add(stack.getItemId())) {
                idle.add(stack.getName().toLowerCase(Locale.ROOT));
            }
        }
        // A trip planting more kinds than the box holds, with nothing idle in it, has nothing
        // to empty: the planner already sends the overflow to later banks.
        carry.add(!idle.isEmpty() && kinds.size() > SeedBox.KINDS_HELD ? box.withNote("Empty out the " + String.join(", ", idle) + ".") : box);
    }

    /**
     * One line per crop, with how many patches take it, across every run on the trip. The
     * tally is the same one the panel's seed line prints.
     */
    private static void addSeeds(List<FarmingCarryItem> carry, List<SeedAllocation.Tally> planting, PlayerState state) {
        for (SeedAllocation.Tally tally : planting) {
            CropData data = CropData.forCrop(tally.getCrop());
            if (data == null) {
                continue;
            }
            carry.add(seedLine(data, tally.getCount(), state));
        }
    }

    /**
     * One bag line for a crop's planting stock, in whichever form the player has it.
     *
     * <p>For a sapling-planted crop, seeds, seedlings and saplings all count towards the line.
     * The row names the potted form only when potted stock alone fills the run, and
     * "Oak sapling or acorn" (or "Oak seedling or acorn") when the rest must still be
     * potted. Every name is the game's own, from {@link CropData}.
     */
    private static FarmingCarryItem seedLine(CropData data, int count, PlayerState state) {
        int seed = data.getSeedItemId();
        if (!data.isSaplingPlanted()) {
            return item(FarmingCarryItem.Kind.SEED, seed, data.getSeedName(), count, count, state);
        }
        // Furthest-along first, so the line is named and drawn for the furthest stage they
        // hold any of.
        int[] stages = {data.getSaplingItemId(), data.getWateredSeedlingItemId(), data.getSeedlingItemId()};
        int potted = 0;
        for (int stage : stages) {
            potted += ItemCounts.countOwned(state, stage, null);
        }
        String pottedName = ItemCounts.ownsAny(state, stages[0]) ? data.getSaplingName() : data.getSeedlingName();
        String name;
        if (potted >= count) {
            name = pottedName;
        } else if (potted > 0) {
            name = pottedName + " or " + data.getSeedName().toLowerCase(Locale.ROOT);
        } else {
            name = data.getSeedName();
        }
        return item(FarmingCarryItem.Kind.SEED, bestOwned(state, stages, seed), name, count, count, state, ids(data.getPlantingForms()));
    }

    private static int[] ids(List<Integer> itemIds) {
        return itemIds.stream().mapToInt(Integer::intValue).toArray();
    }

    /**
     * Seeds for the stops that plant one particular thing: snape grass, a white lily, a
     * potato cactus, or the crop the player ticked in its place.
     *
     * <p>These stops bypass the seed allocation, so their seeds are packed here.
     *
     * <p>The count is {@code seedsPerPatch} times the patches the stop plants, because one
     * stop can cover several patches (the two seaweed patches are one dive). Those are the
     * patches dealt a seed, which the stock bounds across the trip, so one crop picked at
     * many patches packs what is owned and a later stretch asks for no more. Without the
     * deal, every open patch: a patch holding any living crop takes no seed.
     */
    private static void addFixedSeeds(List<FarmingCarryItem> carry, List<StopPlan> plans, List<List<Crop>> cropFor, PlayerState state,
            FarmingInputs inputs) {
        FarmingPreferences prefs = inputs.getPreferences();
        Map<Crop, Integer> needed = new LinkedHashMap<>();
        for (int index = 0; index < plans.size(); index++) {
            StopPlan plan = plans.get(index);
            if (!plan.isVisit() || !plan.getStop().isFixedCrop()) {
                continue;
            }
            Crop crop = FixedCrops.cropFor(plan.getStop(), prefs, state);
            if (crop == null) {
                continue;
            }
            int open = cropFor != null ? cropFor.get(index).size() : CropAssigner.openFixedPatches(plan.getStop(), inputs, state);
            CropData data = CropData.forCrop(crop);
            if (data != null && open > 0) {
                needed.merge(crop, data.getSeedsPerPatch() * open, Integer::sum);
            }
        }

        for (Map.Entry<Crop, Integer> entry : needed.entrySet()) {
            carry.add(seedLine(CropData.forCrop(entry.getKey()), entry.getValue(), state));
        }
    }

    /**
     * The items behind the routes being taken, each listed once however many stops use it.
     *
     * <p>A spell rung is packed as runes, totalled across every stop that casts; the rune
     * pouch gets no line of its own. A Spellbook Swap rung packs the swap's runes and the
     * second spell's together. Reads each route's chosen needs, so an "or" contributes
     * only the branch being taken.
     */
    private static void addTravel(List<FarmingCarryItem> carry, List<StopPlan> plans,
            PlayerState state, int curePlantCasts, int fertileCasts) {
        Map<Integer, FarmingCarryItem> byItem = new LinkedHashMap<>();
        Map<Integer, Integer> tabletsNeeded = new LinkedHashMap<>();
        Map<Integer, String> tabletNames = new LinkedHashMap<>();
        Map<Rune, Integer> runesNeeded = new EnumMap<>(Rune.class);
        // Cure Plant runes merge here with the teleport runes, so each rune gets one line.
        if (curePlantCasts > 0) {
            runesNeeded.merge(Rune.EARTH, curePlantCasts * EARTH_PER_CURE_PLANT, Integer::sum);
            runesNeeded.merge(Rune.ASTRAL, curePlantCasts * ASTRAL_PER_CURE_PLANT, Integer::sum);
        }
        // Places already paid for, so several stops at one of them cost one trip.
        Set<Arrival> arrivedAt = EnumSet.noneOf(Arrival.class);

        for (StopPlan plan : plans) {
            if (!plan.isVisit() || plan.getRoute() == null) {
                continue;
            }
            // Teleports are counted per arrival, not per stop: Catherby's three patches cost
            // one teleport. Arrival is the same key the itinerary groups visits on.
            boolean firstTimeHere = arrivedAt.add(plan.getStop().getArrival());

            for (Capability capability : plan.getNeeds()) {
                CarryItems.Carry carryItem = CarryItems.forCapability(capability);
                if (carryItem != null) {
                    // One line per item for the whole trip. Every charge tier counts towards
                    // it, since each tier is a different item id. computeIfAbsent avoids
                    // rescanning every container at each later stop.
                    byItem.computeIfAbsent(carryItem.getItemId(), id -> item(FarmingCarryItem.Kind.TRAVEL, id,
                                    carryItem.getName(), 0, 1, state, carryItem.getItemIds()));
                    continue;
                }
                // A spell capability with no item, such as the respawn teleport: runes,
                // one cast per arrival.
                if (!firstTimeHere) {
                    continue;
                }
                Teleports.runesFor(capability).forEach((rune, n) -> runesNeeded.merge(rune, n, Integer::sum));
            }

            TeleportMeans means = plan.getTeleport();
            if (means == null || !firstTimeHere) {
                continue;
            }
            if (means.isTablet()) {
                tabletsNeeded.merge(means.getItemId(), 1, Integer::sum);
                tabletNames.putIfAbsent(means.getItemId(), means.getDisplayName());
            } else {
                means.getRunes().forEach((rune, n) -> runesNeeded.merge(rune, n, Integer::sum));
            }
        }

        // Fertile Soil's runes, one cast a composted patch, in place of carried compost. Not
        // capped: the player chose the spell, so a shortfall shows as runes to fetch.
        if (fertileCasts > 0) {
            FertileSoil.runesPerCast().forEach((rune, n) -> runesNeeded.merge(rune, fertileCasts * n, Integer::sum));
        }
        carry.addAll(byItem.values());

        for (Map.Entry<Integer, Integer> tablet : tabletsNeeded.entrySet()) {
            int itemId = tablet.getKey();
            carry.add(item(FarmingCarryItem.Kind.TRAVEL, itemId, tabletNames.get(itemId), tablet.getValue(), tablet.getValue(), state));
        }

        for (Map.Entry<Rune, Integer> rune : runesNeeded.entrySet()) {
            int itemId = rune.getKey().getItemId();
            carry.add(item(FarmingCarryItem.Kind.RUNES, itemId, rune.getKey().getDisplayName(), rune.getValue(), rune.getValue(), state));
        }
    }

    /** True when any of these ids is on the player right now. */
    private static boolean carriedAny(PlayerState state, int... itemIds) {
        return Arrays.stream(itemIds).anyMatch(itemId -> ItemCounts.countCarried(state, itemId, null) > 0);
    }

    /**
     * A tool line: no count shown, satisfied by one.
     *
     * @param acceptedIds as for {@link #item}; none means only {@code itemId}
     */
    private static FarmingCarryItem tool(int itemId, String name, PlayerState state, int... acceptedIds) {
        return item(FarmingCarryItem.Kind.TOOL, itemId, name, 0, 1, state, acceptedIds);
    }

    /**
     * One line of the bag, with the item's availability: carried, at the tool leprechaun,
     * in the seed box, banked, or missing.
     *
     * @param iconItemId  the item drawn and tagged, which is one of the accepted ids
     * @param quantity    what the run needs, or 0 when the count is not the point
     * @param needed      how many make the line satisfied — one, for the lines that show no
     *                    count at all
     * @param acceptedIds every id that counts towards the line, for a line more than one item
     *                    can satisfy — a tree needs a seed <em>or</em> the sapling it becomes,
     *                    and either one fills the patch. None means only {@code iconItemId}
     */
    private static FarmingCarryItem item(FarmingCarryItem.Kind kind, int iconItemId,
            String name, int quantity, int needed, PlayerState state, int... acceptedIds) {
        int[] ids = acceptedIds.length == 0 ? new int[]{iconItemId} : acceptedIds;
        int carried = 0;
        int stored = 0;
        int owned = 0;
        for (int itemId : ids) {
            carried += ItemCounts.countCarried(state, itemId, null);
            stored += ItemCounts.countInLeprechaunStorage(state, itemId);
            owned += ItemCounts.countOwned(state, itemId, null);
        }
        FarmingCarryItem.Availability availability;
        if (carried >= needed) {
            availability = FarmingCarryItem.Availability.CARRIED;
        } else if (carried + stored >= needed) {
            // Ranked above BANKED: the leprechaun is at the patch, so nothing needs fetching.
            availability = FarmingCarryItem.Availability.AT_LEPRECHAUN;
        } else if (owned >= needed) {
            availability = theBoxWouldFinishIt(state, needed - carried - stored, owned - carried - stored, ids)
                    ? FarmingCarryItem.Availability.IN_SEED_BOX : FarmingCarryItem.Availability.BANKED;
        } else {
            availability = FarmingCarryItem.Availability.MISSING;
        }
        return new FarmingCarryItem(kind, iconItemId, name, quantity, availability, CropData.tagForPlantable(iconItemId), "", carried);
    }

    /**
     * True when only a carried seed box with unconfirmed contents could, by its tally, cover
     * the shortfall: the bank and seed vault cannot, and the box would cover all of it.
     *
     * <p>The tally is summed from chat lines and trusted per seed ({@code SeedBox.trustedOf}).
     * An unconfirmed tally may hold seeds that are long gone, so where the bank or vault holds
     * enough the line stays a withdrawal: a needless withdrawal costs a click; a skipped one
     * costs the planting. {@code IN_SEED_BOX} asks the player to check the box only where both fall
     * short. Checking prints the contents to chat, which settles the tally.
     *
     * <p>Whole shortfall or nothing: the bank row drops an {@code IN_SEED_BOX} item from its
     * fetch list, so a partial cover falls through to {@code BANKED}. Downstream counts still
     * treat the line as a withdrawal, in case the box turns out empty.
     *
     * @param shortOf how many the line still wants after loose carried items and leprechaun
     *                storage are counted
     * @param ownedElsewhere what the player owns beyond those, untrusted box seeds included
     */
    private static boolean theBoxWouldFinishIt(PlayerState state, int shortOf, int ownedElsewhere, int... acceptedIds) {
        if (shortOf <= 0 || !SeedBox.carried(state)) {
            return false;
        }
        int unconfirmed = 0;
        for (int itemId : acceptedIds) {
            int tallied = SeedBox.tallied(state, itemId);
            unconfirmed += tallied - SeedBox.trustedOf(state, itemId, tallied);
        }
        return unconfirmed >= shortOf && ownedElsewhere - unconfirmed < shortOf;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.detection.CapabilityResolver;
import com.larryfarming.farming.detection.CapabilityState;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import java.util.*;

/**
 * The Ardougne cloak's Monastery teleport as the way onto the fairy rings, with the
 * Monastery bushes worked on the way.
 *
 * <p>The cloak lands nine tiles from the bushes, and the bushes are 43 tiles from ring DJP
 * against 50 straight from the landing, so working them costs two tiles on a walk a player
 * entering the network by cloak makes anyway. A player
 * who visits the bushes by cloak is therefore standing at a ring for nothing, and two
 * things follow:
 *
 * <ul>
 * <li>The leg straight after such a visit starts at the ring: no approach teleport is
 * packed, and its sentence opens with the walk to DJP.</li>
 * <li>On a trip, the Monastery visit moves to just before the first leg taken by fairy
 * ring, so that leg is the one it serves. The circuit's own seat for the bushes, beside the
 * Ardougne farm, saves nothing: the farm is reached by its own teleport.</li>
 * </ul>
 *
 * <p>Only while the player may use the cloak to stand at a ring: they own cloak 1 and have
 * not switched the cloak off under "Travel". With the switch off they have said never to use
 * the cloak, so the bushes keep their seat.
 *
 * <p>The Mort Myre mushroom patch leaves the player beside ring CKS the same way, by
 * whatever route they reached it, so the leg after it starts there too. The mushrooms are
 * never moved: the circuit already seats them just before Canifis.
 */
final class CloakToTheRings {

    private CloakToTheRings() {
    }

    /**
     * What a Monastery visit by cloak gives the leg after it: 43 walked tiles from the
     * bushes' west face (2616, 3226), where the walk from the cloak arrives, to DJP.
     */
    static final RunPlanner.Start FROM_THE_BUSHES = new RunPlanner.Start(FarmingCatalogue.toAfairyRing(),
            "Walk east past the Tower of Life to fairy ring DJP. ", 43);

    /**
     * What a Mort Myre mushroom visit gives the leg after it, however the player got there.
     * The patch (3452, 3473) is two walked tiles from fairy ring CKS (3447, 3470), from the
     * face nearest the ring.
     */
    static final RunPlanner.Start FROM_THE_MUSHROOMS = new RunPlanner.Start(FarmingCatalogue.toAfairyRing(),
            "Walk west to fairy ring CKS. ", 2);

    /**
     * The cloak as a way to a ring, the catalogue's own arm. The resolver fails it while the
     * player has the cloak switched off.
     */
    private static final Requirement CLOAK_TO_A_RING = Requirement.cap(Capability.ARDOUGNE_CLOAK_1);

    /**
     * What the next leg starts from once this group is walked: the bushes' start after a
     * Monastery visit by cloak, the mushrooms' start after a Mort Myre visit, nothing after
     * any other journey, and {@code before} unchanged after a group the player does not
     * travel to ({@link StopRowWriter#isJourney}).
     */
    static RunPlanner.Start after(RunPlanner.Start before, List<Integer> group,
            List<StopPlan> plans, CapabilityResolver resolver, PlayerState state) {
        if (!StopRowWriter.isJourney(group, plans)) {
            return before;
        }
        for (int index : group) {
            StopPlan plan = plans.get(index);
            if (plan.isVisit() && reachedByCloak(plan) && mayEnterByCloak(resolver, state)) {
                return FROM_THE_BUSHES;
            }
            if (plan.isVisit() && plan.getStop().getArrival() == Arrival.MORT_MYRE) {
                return FROM_THE_MUSHROOMS;
            }
        }
        return null;
    }

    /**
     * The trip with its Monastery visit moved to just before the first leg taken by fairy
     * ring, when that visit is made by cloak. Otherwise the same trip.
     *
     * <p>Whole visits move, as {@link Itinerary#bestHomesFirst} moves them. The bushes are
     * never a herb rotation seat, so moving them leaves the seed order alone.
     *
     * <p>Reads each run's own routes, before the circuit re-decides them. A leg that went by
     * ring only for its run's order can lose the ring on re-planning, and then the bushes
     * start a leg with no use for it. That costs nothing against their old seat: both legs
     * are reached by their own teleports. Re-decided routes are no better a guide, since a
     * leg already started from the bushes no longer names a way to a ring.
     */
    static Itinerary.Trip bushesBeforeTheFirstRing(Itinerary.Trip trip, CapabilityResolver resolver, PlayerState state) {
        List<List<Integer>> visits = trip.getVisits();
        List<StopPlan> plans = trip.getPlans();
        int bushes = -1;
        for (int position = 0; position < visits.size(); position++) {
            if (after(null, visits.get(position), plans, resolver, state) == FROM_THE_BUSHES) {
                bushes = position;
                break;
            }
        }
        if (bushes < 0) {
            return trip;
        }
        int ring = -1;
        for (int position = 0; position < visits.size(); position++) {
            if (position != bushes && byFairyRing(StopRowWriter.leadOf(visits.get(position), plans))) {
                ring = position;
                break;
            }
        }
        if (ring < 0 || ring == bushes + 1) {
            return trip;
        }
        List<List<Integer>> moved = new ArrayList<>(visits);
        List<Integer> monastery = moved.remove(bushes);
        moved.add(bushes < ring ? ring - 1 : ring, monastery);
        return trip.revisited(moved);
    }

    /** Whether a stop is reached on the cloak's own Monastery teleport, not by a ring. */
    private static boolean reachedByCloak(StopPlan plan) {
        TravelOption option = plan.getRoute();
        return plan.getStop().getArrival() == Arrival.ARDOUGNE_MONASTERY && option != null
                && !option.getRequires().contains(FarmingCatalogue.toAfairyRing()) && option.getRequires().leafCapabilities()
                        .contains(Capability.ARDOUGNE_CLOAK_1);
    }

    private static boolean mayEnterByCloak(CapabilityResolver resolver, PlayerState state) {
        return resolver.evaluate(CLOAK_TO_A_RING, state, Map.of()) != CapabilityState.LACK;
    }

    /** Whether a visit's route enters the fairy ring network. */
    private static boolean byFairyRing(StopPlan plan) {
        return plan.isVisit() && plan.getRoute() != null && plan.getRoute().getRequires().contains(FarmingCatalogue.toAfairyRing());
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.detection.BottomlessBucket;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.FarmingPlantAdvice;
import java.util.*;
import java.util.stream.Collectors;
import lombok.Value;
import net.runelite.api.gameval.ItemID;

/**
 * The compost bin beside each herb farm's allotments, and what the player is to do about it.
 * A bin is not a stop: it is the compost patch in the map region of the farm whose
 * allotments are picked for compost.
 */
final class CompostBins {

    /** Volcanic ash that lifts a bin of supercompost to ultracompost. */
    static final int ASH_PER_BIN = 25;
    /** A bin closes on 15 items, and 15 buckets of compost come out of it. */
    static final int BIN_HOLDS = 15;
    /** Compost potion of one to four doses. */
    static final int[] POTIONS = {
        ItemID.SUPERCOMPOST_POTION_1, ItemID.SUPERCOMPOST_POTION_2,
        ItemID.SUPERCOMPOST_POTION_3, ItemID.SUPERCOMPOST_POTION_4};
    /** An empty bucket and its note. */
    static final int[] EMPTY_BUCKETS = {ItemID.BUCKET_EMPTY, ItemID.Cert.BUCKET_EMPTY};

    /** A farm's bin, the arrival it is worked from, and the allotments that feed it, by site. */
    @Value
    static class Farm {
        PatchRef bin;
        Arrival arrival;
        Map<PatchRef, String> allotments;
    }

    /** What to do at a farm's bin. */
    enum Verdict {
        /** Empty, filling or unseen: harvest the allotments into it. */
        FILL,
        /** Finished, its upgrade covered: upgrade it and empty it. */
        EMPTY,
        /**
         * Left as it stands this run, with the crops standing beside it: rotting, full and
         * still open, short of its upgrade or of empty buckets, or at Ortus Farm with no
         * bottomless bucket to take it.
         */
        LEAVE
    }

    /**
     * A bin's verdict, what the farm's row says of it, the empty buckets its compost goes
     * into, and the volcanic ash it takes. Both counts are what the bin empties into or uses,
     * or what it waits for.
     *
     * <p>The line is null for none. For {@link Verdict#EMPTY} it is the steps the row's
     * "Compost:" line opens with ("add 25 volcanic ash, empty into buckets"); for
     * {@link Verdict#LEAVE} it is the row's whole sentence.
     */
    @Value
    static class Judged {
        Verdict verdict;
        String line;
        int buckets;
        int ash;
    }

    /**
     * What the bins at a set of arrivals want carried: the potion and ash, whether any
     * empties into the bottomless bucket, the empty buckets the rest fill, and whether the
     * player's empty buckets run low.
     */
    @Value
    static class Needs {
        int doses;
        int ash;
        boolean bucket;
        int buckets;
        boolean restock;
    }

    /** The farms with a bin, by map region, in the stops table's order. */
    static final Map<Integer, Farm> FARMS = farms();

    private CompostBins() {
    }

    /** Each herb farm with allotments that can feed a bin, in the order the herb sites are listed. */
    private static Map<Integer, Farm> farms() {
        Map<Integer, Farm> farms = new LinkedHashMap<>();
        for (FarmingCatalogue.SiteSwitch site : FarmingCatalogue.siteSwitches(RunId.HERB)) {
            // The allotments, bin and herb patch of a farm share its map region.
            int region = site.getStop().primaryPatch().getRegionId();
            Map<PatchRef, String> allotments = new LinkedHashMap<>();
            FarmingCatalogue.picksByPatch().forEach((ref, pick) -> {
                if (ref.getRegionId() == region && pick.getCompostKey() != null) {
                    allotments.put(ref, pick.getSite());
                }
            });
            for (FarmingWorldMap.PatchDef def : FarmingWorldMap.allPatches()) {
                if (def.getRegionId() == region && def.getType() == PatchType.COMPOST && !allotments.isEmpty()) {
                    farms.put(region, new Farm(PatchRef.of(region, def.getVarbitId(), def.displayName()), site.getStop().getArrival(),
                            Collections.unmodifiableMap(allotments)));
                }
            }
        }
        return Collections.unmodifiableMap(farms);
    }

    /** The farm any stop of this arrival belongs to, or null for an arrival with no bin. */
    static Farm farmAt(List<Integer> group, List<StopPlan> plans) {
        for (int index : group) {
            Farm farm = farmOf(plans.get(index));
            if (farm != null) {
                return farm;
            }
        }
        return null;
    }

    /** The farm whose map region holds this stop's patch, or null. */
    private static Farm farmOf(StopPlan plan) {
        return FARMS.get(plan.getStop().primaryPatch().getRegionId());
    }

    /**
     * Whether a bucket has come out of this finished bin. The upgrade costs the whole bin's
     * potion or ash however little is left, so a started bin is only emptied.
     */
    private static boolean started(PatchPrediction bin) {
        return bin.getState() == CropState.HARVESTABLE && bin.getStage() + 1 < BIN_HOLDS;
    }

    /** Doses of compost potion to lift a finished bin to the account's step. */
    static int dosesFor(PatchPrediction bin, Crop step) {
        return !started(bin) && bin.getCrop() == Crop.COMPOST && step.ordinal() >= Crop.SUPERCOMPOST.ordinal() ? 1 : 0;
    }

    /** Volcanic ash to lift a finished bin to the account's step. */
    static int ashFor(PatchPrediction bin, Crop step) {
        return !started(bin) && step == Crop.ULTRACOMPOST && (bin.getCrop() == Crop.COMPOST || bin.getCrop() == Crop.SUPERCOMPOST)
                ? ASH_PER_BIN : 0;
    }

    /**
     * The empty buckets the player owns anywhere, the leprechaun's included, or only those
     * carried, noted or not.
     */
    static int emptyBuckets(PlayerState state, boolean carried) {
        int buckets = 0;
        for (int itemId : EMPTY_BUCKETS) {
            buckets += carried ? ItemCounts.countCarried(state, itemId, null) : ItemCounts.countOwned(state, itemId, null);
        }
        return buckets;
    }

    /**
     * The verdict at each farm Larry works. The finished bins share the potion, ash and
     * empty buckets the player owns, in the order the plan on screen reaches their farms,
     * and a farm off that plan comes after them. The bins are judged before the trip is
     * planned, so the plan on screen is the trip; before there is one, they share in table
     * order. Fertile Soil's casts take their ash first, and the bins share what is left. A
     * bin the stock doesn't cover waits.
     *
     * <p>A bin empties into the bottomless bucket when the player owns it as an item, it has
     * been read, and it is empty or holds the bin's compost once upgraded. In game the plain
     * empty buckets in the inventory fill first, and the bottomless bucket takes the rest of
     * the bin. Those carried buckets are used up for later bins, and the row doesn't name
     * them. When the carried buckets alone hold every item left in the bin, the bin empties
     * into plain buckets, and the carried ones count first toward it. Every other bin empties
     * into plain buckets, carried, brought noted or taken from the leprechaun, and the compost
     * is stored at the leprechaun. Ortus Farm has no leprechaun, so its bin is emptied only
     * into the bottomless bucket and otherwise waits without a line.
     *
     * <p>{@link FarmingInputs#seeing} judges them once, and the holds, the rows and the bag
     * all read that judgement.
     */
    static Map<Farm, Judged> verdicts(FarmingInputs inputs, PlayerState state) {
        return verdicts(inputs, state, RunSettings.quietPicks(inputs.getPreferences(), state, inputs::patchAt));
    }

    /**
     * The verdicts, given the preset picks the account can't plant yet, which work no bin.
     *
     * @param quiet {@link RunSettings#quietPicks} for these inputs and this player
     */
    static Map<Farm, Judged> verdicts(FarmingInputs inputs, PlayerState state, Set<String> quiet) {
        Map<Farm, Judged> verdicts = new LinkedHashMap<>();
        CompostStock compost = inputs.getCompost();
        // Before the bank is seen the stock is a floor, so the bins stand quietly.
        if (!compost.isOn() || state == null || state.getBankLastSeen() == null) {
            return verdicts;
        }
        List<String> ahead = inputs.getAhead();
        List<Farm> order = new ArrayList<>(FARMS.values());
        order.sort(Comparator.comparingInt(farm -> ahead.contains(farm.getArrival().name()) ? ahead.indexOf(farm.getArrival().name())
                : ahead.size()));
        Crop step = compost.getStep();
        // What the player owns, and what is left of it for the next bin.
        int ownedDoses = doses(state, false);
        int ownedAsh = ItemCounts.countOwned(state, ItemID.FOSSIL_VOLCANIC_ASH, null);
        int ownedEmpties = emptyBuckets(state, false);
        int doses = ownedDoses;
        int ash = Math.max(0, ownedAsh - inputs.getFertileAsh());
        int empties = ownedEmpties;
        int carried = ItemCounts.countCarried(state, ItemID.BUCKET_EMPTY, null);
        // An unread bucket may hold any kind, so no bin goes into it.
        boolean bottomless = BottomlessBucket.toHand(state) && !compost.isBucketUnread();
        // The bucket holds one kind at a time: what it holds now, then what the bins put in it.
        Crop into = compost.getBucketKind();
        for (Farm farm : order) {
            if (!worked(farm, inputs.getPreferences(), quiet)) {
                continue;
            }
            PatchPrediction seen = inputs.patchAt(farm.getBin());
            CropState at = seen == null ? CropState.EMPTY : seen.getState();
            boolean full = at == CropState.FILLING && seen.getStage() + 1 >= BIN_HOLDS;
            // A closed bin reads harvestable only beside it. From anywhere else it reads
            // growing with its timer run out.
            if (!full && at != CropState.HARVESTABLE && at != CropState.GROWING) {
                verdicts.put(farm, new Judged(Verdict.FILL, null, 0, 0));
                continue;
            }
            int binDoses = dosesFor(seen, step);
            int binAsh = ashFor(seen, step);
            // The compost the bin gives once upgraded. A started bin below the step stays
            // out of the bottomless bucket, which holds the step's compost.
            Crop kind = binDoses + binAsh > 0 ? step : seen.getCrop();
            boolean compostKind = kind != Crop.ROTTEN_TOMATO;
            int left = started(seen) ? seen.getStage() + 1 : BIN_HOLDS;
            // The carried empty buckets fill first. When they hold the whole bin, the bin
            // empties into them; otherwise the bottomless bucket takes the rest.
            boolean intoBucket = compostKind && bottomless && carried < left
                    && (into != null ? kind == into : kind.compareTo(step) >= 0 || !started(seen));
            // One plain bucket for each item left in the bin.
            int buckets = compostKind && !intoBucket ? left : 0;
            // The carried buckets a bottomless-bucket bin fills first are used up all the same.
            int firstFilled = intoBucket ? carried : 0;
            // Ortus Farm has no leprechaun to take buckets from or store the compost with.
            if (buckets > 0 && !LeprechaunPlanner.hasLeprechaun(farm.getArrival())) {
                verdicts.put(farm, new Judged(Verdict.LEAVE, null, 0, 0));
                continue;
            }
            boolean rots = at == CropState.GROWING && !seen.isReadyAt(inputs.getNowEpochSec());
            boolean shortOfDose = binDoses > doses;
            boolean shortOfAsh = binAsh > ash;
            boolean shortOfBuckets = !full && !rots && !shortOfDose && !shortOfAsh && buckets > empties;
            String leave = full ? "Close the compost bin and leave the crops beside it for next run"
                    : rots ? "Leave the compost bin while it rots"
                    // Some they own may be spoken for, so the line asks for the shortfall as more.
                    : shortOfDose || shortOfAsh ? "Leave the compost bin until you have "
                            + upgrade(!shortOfDose ? null : ownedDoses > 0 ? "another dose of compost potion" : DOSE,
                                    !shortOfAsh ? null : binAsh - ash + (ownedAsh > 0 ? " more" : "") + " volcanic ash")
                    : shortOfBuckets ? "Leave the compost bin until you have " + (buckets - empties) + (ownedEmpties > 0 ? " more" : "")
                            + (buckets - empties == 1 ? " empty bucket" : " empty buckets") : null;
            if (leave != null) {
                verdicts.put(farm, new Judged(Verdict.LEAVE, leave, shortOfBuckets ? buckets : 0, !full && !rots && shortOfAsh ? binAsh : 0));
                continue;
            }
            doses -= binDoses;
            ash -= binAsh;
            empties -= buckets + firstFilled;
            carried = Math.max(0, carried - buckets - firstFilled);
            into = intoBucket ? kind : into;
            String upgrade = upgrade(binDoses > 0 ? DOSE : null, binAsh > 0 ? ASH_PER_BIN + " volcanic ash" : null);
            String where = intoBucket ? " into your bottomless bucket" : buckets > 0 ? " into buckets" : " the bin";
            // The upgrade leads when there is one: it is the step a player forgets, where
            // emptying the bin is obvious. The row joins these steps with its fill.
            verdicts.put(farm, new Judged(Verdict.EMPTY, (upgrade.isEmpty() ? "" : "add " + upgrade + ", ") + "empty" + where,
                    buckets, binAsh));
        }
        return verdicts;
    }

    /**
     * Whether the trip's Fertile Soil casts change what the bins are told, so the bins are
     * judged again on the ash the casts leave them: the casts and the bins emptied together
     * want more volcanic ash than the player owns, or a bin waits for ash, whose line counts
     * what it is short of. Bins that need no ash never change, and nor do bins on a trip
     * that casts nothing.
     *
     * @param fertileAsh the ash the trip's casts take
     */
    static boolean outrunTheAsh(FarmingInputs inputs, PlayerState state, int fertileAsh) {
        if (fertileAsh == 0) {
            return false;
        }
        int ash = fertileAsh;
        boolean leans = false;
        for (Judged judged : inputs.bins(state).values()) {
            if (judged.getAsh() > 0 && judged.getVerdict() == Verdict.LEAVE) {
                return true;
            }
            leans |= judged.getAsh() > 0;
            ash += judged.getAsh();
        }
        return leans && ash > ItemCounts.countOwned(state, ItemID.FOSSIL_VOLCANIC_ASH, null);
    }

    /** One dose of compost potion, as a row names it. */
    private static final String DOSE = "a dose of compost potion";

    /** The potion and ash as a row names them: "a dose of compost potion and 25 volcanic ash", or "". Either may be null. */
    private static String upgrade(String dose, String ash) {
        return dose == null ? ash == null ? "" : ash : ash == null ? dose : dose + " and " + ash;
    }

    /**
     * The picked sites Larry holds back. With the thermostat off or the bank unseen, every
     * allotment marked for compost. Otherwise the allotments with a crop standing beside a
     * bin Larry leaves, since they cannot feed it; an empty one plants, so it is grown by
     * the time the bin is worked again.
     */
    static Set<String> holding(FarmingInputs inputs, Map<Farm, Judged> verdicts) {
        Set<String> sites = new HashSet<>();
        // No farm is worked with the thermostat off or the bank unseen. Nor is one while
        // every for-compost pick is quiet or Off, which plant nothing either way.
        boolean idle = verdicts.isEmpty();
        for (Farm farm : FARMS.values()) {
            Judged judged = verdicts.get(farm);
            if (idle || judged != null && judged.getVerdict() == Verdict.LEAVE) {
                farm.getAllotments().forEach((ref, site) -> {
                    PatchPrediction seen = inputs.patchAt(ref);
                    if (inputs.getPreferences().plantsForCompost(site) && (idle || seen == null || !seen.isIdle())) {
                        sites.add(site);
                    }
                });
            }
        }
        return sites;
    }

    /**
     * What the bins at the visited farms want in the bag: the potion and ash of every bin
     * about to be emptied, and the bottomless bucket or empty buckets it empties into. A bin
     * left as it stands asks for nothing; its row names what it needs. The empty buckets run
     * low when a bin here wants them and fewer than a bin's worth would be left after the
     * trip.
     */
    static Needs over(List<StopPlan> plans, FarmingInputs inputs, PlayerState state) {
        Map<Farm, Judged> verdicts = inputs.bins(state);
        // Null for a stop at no farm, which has no verdict.
        Set<Farm> visited = new HashSet<>();
        for (StopPlan plan : plans) {
            if (plan.isVisit()) {
                visited.add(farmOf(plan));
            }
        }
        int doses = 0;
        int ash = 0;
        boolean bucket = false;
        int buckets = 0;
        boolean wanted = false;
        for (Farm farm : visited) {
            Judged judged = verdicts.get(farm);
            wanted |= judged != null && judged.getBuckets() > 0;
            if (judged != null && judged.getVerdict() == Verdict.EMPTY) {
                PatchPrediction bin = inputs.patchAt(farm.getBin());
                doses += dosesFor(bin, inputs.getCompost().getStep());
                ash += judged.getAsh();
                buckets += judged.getBuckets();
                bucket |= judged.getBuckets() == 0 && bin.getCrop() != Crop.ROTTEN_TOMATO;
            }
        }
        return new Needs(doses, ash, bucket, buckets, wanted && emptyBuckets(state, false) - buckets < BIN_HOLDS);
    }

    /** What the row says about the bin at an arrival. */
    @Value
    static class Row {
        List<String> lines;
        /** Plan indices of the for-compost allotments harvested into the bin. */
        Set<Integer> fills;

        /** No bin here, or nothing to do at it. */
        static final Row NONE = new Row(List.of(), Set.of());
    }

    /**
     * Among allotment crops, every one needing 47 Farming or more makes supercompost and
     * every one below makes plain compost (OSRS wiki, "Compost Bin").
     */
    private static final int SUPERCOMPOSTABLE_LEVEL = 47;

    /**
     * The bin's lines for the arrival, in the order the player does them. The patches that
     * fill the bin replant with the row's other plantings, so a patch with no seed to plant
     * is harvested and left empty.
     */
    static Row rowAt(List<Integer> group, List<StopPlan> plans, FarmingInputs inputs, PlayerState state) {
        Farm farm = farmAt(group, plans);
        Judged judged = judgedAt(group, plans, inputs, state);
        if (judged == null) {
            return Row.NONE;
        }
        // A bin Larry leaves is a state rather than steps, and it holds the crops beside it,
        // so its sentence is all the row says of them.
        if (judged.getVerdict() == Verdict.LEAVE) {
            return new Row(judged.getLine() == null ? List.of() : List.of(judged.getLine()), Set.of());
        }
        // The bin's steps and its fill are one chain, so the row spends one line on them.
        List<String> steps = new ArrayList<>();
        if (judged.getLine() != null) {
            steps.add(judged.getLine());
        }
        PatchPrediction bin = inputs.patchAt(farm.getBin());
        boolean filling = bin != null && bin.getState() == CropState.FILLING;
        List<Integer> supers = new ArrayList<>();
        List<Integer> plain = new ArrayList<>();
        boolean onlyTomatoes = true;
        for (int index : group) {
            StopPlan plan = plans.get(index);
            PatchPick pick = FarmingCatalogue.pickOf(plan.getStop());
            if (!plan.isVisit() || pick == null || !inputs.getPreferences().plantsForCompost(pick.getSite())) {
                continue;
            }
            PatchPrediction seen = inputs.patchAt(plan.getStop().primaryPatch());
            if (PatchWork.at(seen, plan.getStop(), inputs.getPreferences(), inputs.getNowEpochSec()) == PatchWork.Act.HARVEST) {
                boolean high = CropData.forCrop(seen.getCrop()).getFarmingLevel() >= SUPERCOMPOSTABLE_LEVEL;
                (high ? supers : plain).add(index);
                onlyTomatoes &= seen.getCrop() == Crop.TOMATO;
            }
        }
        // A bin filling with more than plain compost takes no ordinary crop, and a tomato
        // makes compost only beside another compostable: another patch's crop, or the
        // compost already filling the bin.
        boolean aimsHigh = judged.getVerdict() == Verdict.FILL && filling && bin.getCrop() != Crop.COMPOST;
        Set<Integer> fills = new LinkedHashSet<>(!supers.isEmpty() ? supers : aimsHigh || onlyTomatoes && !filling ? List.of() : plain);
        if (!fills.isEmpty()) {
            // The patches are named by their crop, which tells them apart where a compass point
            // would not, and a crop grown on both reads as a count. Each fill was seen ready to
            // harvest, so its crop is known. The game stops the harvest when the bin is full and
            // the rest of that patch takes another harvest, which the line leaves out. The
            // replanting joins the row's plantings, so each crop is planted in one line.
            List<Crop> crops = fills.stream().map(index -> inputs.patchAt(plans.get(index).getStop().primaryPatch()).getCrop())
                    .collect(Collectors.toList());
            Set<Crop> distinct = new LinkedHashSet<>(crops);
            // "Fill", not "Harvest", so the line does not read as a repeat of the row's own harvest line.
            steps.add("fill with " + distinct.stream().map(CropNames::inSentence).collect(Collectors.joining(" and "))
                    + (distinct.size() == 1 ? FarmingPlantAdvice.countOf(crops.size()) : ""));
        }
        // The plan counts both allotments as needed, so the bag never packs short. A bin the
        // first one fills is full on the next read, which holds the second standing as next
        // run's fill, so no line has to say which to plant.
        return new Row(steps.isEmpty() ? List.of() : List.of("Compost: " + String.join(", ", steps)), fills);
    }

    /** The verdict on the bin at an arrival, or null for none. A null player has none. */
    private static Judged judgedAt(List<Integer> group, List<StopPlan> plans, FarmingInputs inputs, PlayerState state) {
        Farm farm = farmAt(group, plans);
        return farm == null ? null : inputs.bins(state).get(farm);
    }

    /** Whether the bin at an arrival is emptied into empty buckets this visit, or waits for them. */
    static boolean wantsBucketsAt(List<Integer> group, List<StopPlan> plans, FarmingInputs inputs, PlayerState state) {
        Judged judged = judgedAt(group, plans, inputs, state);
        return judged != null && judged.getBuckets() > 0;
    }

    /** Doses of compost potion the player owns, or only those carried. */
    static int doses(PlayerState state, boolean carried) {
        int doses = 0;
        for (int i = 0; i < POTIONS.length; i++) {
            doses += (i + 1) * (carried ? ItemCounts.countCarried(state, POTIONS[i], null) : ItemCounts.countOwned(state, POTIONS[i], null));
        }
        return doses;
    }

    /** Whether Larry works this farm's bin: some allotment there {@link #composts}. */
    private static boolean worked(Farm farm, FarmingPreferences prefs, Set<String> quiet) {
        return farm.getAllotments().values().stream().anyMatch(site -> composts(site, prefs, quiet));
    }

    /**
     * Whether this allotment plants for compost: picked for compost with a crop the account
     * can plant. A preset pick quiet for its level or its seed does not count. The bins' own
     * hold is left out, since it follows from their verdicts.
     */
    static boolean composts(String site, FarmingPreferences prefs, Set<String> quiet) {
        return prefs.plantsForCompost(site) && prefs.picks().get(site) != null && !quiet.contains(site);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.detection.BottomlessBucket;
import com.larryfarming.farming.model.FarmingPreferences;
import com.larryfarming.model.PlayerState;
import java.util.EnumSet;
import java.util.Locale;
import lombok.Value;
import lombok.With;
import net.runelite.api.gameval.ItemID;

/**
 * The account's compost: the best step it has reached, how many patches its stock can treat,
 * and whether the thermostat has Larry making more.
 */
@Value
public class CompostStock {

    /** A plan made with no reading: compost, nothing counted, making more. */
    public static final CompostStock NONE = new CompostStock(Crop.COMPOST, 0, true, false, false, null);

    /** COMPOST, SUPERCOMPOST or ULTRACOMPOST; the ordinal is the ladder. */
    Crop step;
    /** Patches the stock can treat. */
    int uses;
    /** Whether the allotments marked for compost plant and the bins are worked; {@code withOn} holds it. */
    @With
    boolean on;
    /** Whether {@link #uses} counts the whole stock, rather than a floor under it. */
    boolean whole;
    /** Whether a filled bottomless bucket away from the leprechaun has no reading, or reads empty. */
    boolean bucketUnread;
    /** The compost in the bucket the player carries or banks, or null when it is empty or unread. */
    Crop bucketKind;

    /** Whether the stock decided {@link #on}, rather than a thermostat never decided. */
    public boolean isDecided() {
        return whole || !on;
    }

    /**
     * The stock this player holds. The count never reads high: a reading counts only while a
     * filled bucket is owned, and a count that may read short is a floor, which can switch the
     * thermostat off but never on. Between the thresholds the thermostat keeps its last state.
     *
     * @param savedStep the best step reached so far, or null
     * @param wasOn the thermostat's last decision, or null when it has made none
     * @param reading what a carried or banked bucket was last read holding, or null
     */
    public static CompostStock of(PlayerState state, Crop savedStep, Boolean wasOn, BottomlessBucket.Reading reading,
            FarmingPreferences prefs) {
        boolean stored = BottomlessBucket.isStored(state);
        boolean filled = ItemCounts.ownsAny(state, ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED);
        BottomlessBucket.Reading held = stored ? BottomlessBucket.stored(state) : filled ? reading : null;
        Crop inBucket = held != null ? held.getKind() : Crop.COMPOST;
        // The ladder steps up on stock the account owns: the compost itself, or what makes it.
        Crop seen = Crop.COMPOST;
        if (ItemCounts.ownsAny(state, ItemID.BUCKET_SUPERCOMPOST) || inBucket == Crop.SUPERCOMPOST || CompostBins.doses(state, false) > 0) {
            seen = Crop.SUPERCOMPOST;
        }
        if (ItemCounts.ownsAny(state, ItemID.BUCKET_ULTRACOMPOST) || inBucket == Crop.ULTRACOMPOST
                || ItemCounts.countOwned(state, ItemID.FOSSIL_VOLCANIC_ASH, null) >= CompostBins.ASH_PER_BIN) {
            seen = Crop.ULTRACOMPOST;
        }
        Crop step = savedStep != null && savedStep.compareTo(seen) > 0 ? savedStep : seen;
        int perBucket = BottomlessBucket.owned(state) ? 2 : 1;
        int uses = held != null && held.getKind().compareTo(step) >= 0 ? held.getUses() : 0;
        for (Crop kind : EnumSet.range(step, Crop.ULTRACOMPOST)) {
            uses += perBucket * ItemCounts.countOwned(state, kind.getItemId(), null);
        }
        // A filled bucket read empty was read before it was filled.
        boolean unread = !stored && filled && (reading == null || reading.getUses() == 0);
        boolean whole = state != null && state.getBankLastSeen() != null && !unread;
        boolean on = wasOn == null || wasOn;
        if (uses >= prefs.stopCompostAt()) {
            on = false;
        } else if (whole && uses < prefs.makeCompostBelow()) {
            on = true;
        }
        return new CompostStock(step, uses, on, whole, unread, !stored && filled && !unread ? reading.getKind() : null);
    }

    /**
     * The herb run's paused line, or null while compost is being made or the count is only a
     * floor. An unread bucket comes first, since the count it leaves is only a floor.
     *
     * @param resumeBelow the threshold the thermostat switches back on below
     */
    public String pausedLine(int resumeBelow) {
        if (bucketUnread) {
            return "Check your bottomless bucket";
        }
        // Grouped as the threshold picks show their numbers.
        return on || !whole ? null : String.format(Locale.ENGLISH, "Compost: %,d uses stocked, resumes below %,d", uses, resumeBelow);
    }

    /**
     * The stock beside the thresholds while compost is being made and the player could stop
     * early, or null. Null while compost is not being made, while the count is only a floor,
     * and below {@code resumeBelow}, where the thermostat would switch straight back on.
     */
    public String stockedLine(int resumeBelow) {
        return on && whole && uses >= resumeBelow ? String.format(Locale.ENGLISH, "%,d uses", uses) : null;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.Arrivals;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import java.util.*;
import lombok.AllArgsConstructor;

/**
 * Which crop goes into which patch: the run's seeds dealt down the patches best home first,
 * a living tree traded only for a better one unless grown trees are replanted, and a
 * contract's crop put where the contract wants it.
 *
 * <p>Also answers the questions the allocation asks of a single patch (is it held for the
 * next contract, is a living crop in the way), so the quota count and the allocation read
 * the ground the same way.
 */
final class CropAssigner {

    private CropAssigner() {
    }

    /**
     * Whether this patch is being kept empty until the next contract has a crop.
     *
     * <p>A reserved patch otherwise takes a filler seed, but not while the next contract's
     * crop is unknown: planting then would occupy the patch Jane is about to ask for. The
     * guild visit hands in the contract and takes the next before planting (see
     * {@link StopRowWriter#adviseOnGroup}), so the hold usually lasts one conversation.
     */
    static boolean heldForTheNextContract(PatchRef patch, PlayerState state) {
        return PatchPriority.isReservedForContracts(patch) && RunScheduler.nextContractCropUnknown(state);
    }

    /**
     * The crop an outstanding contract needs put in this patch, or null.
     *
     * <p>The other half of {@link #heldForTheNextContract}: once Jane names a crop, that crop
     * goes into the reserved patch instead of a filler seed. Only where the crop belongs in
     * <em>this</em> patch type.
     *
     * <p>Null once the contract's crop stands there alive (diseased counts: a cure keeps the
     * crop). A dead one does not count, because the player digs it up and replants the
     * contract's crop. A living crop that is not the contract's is left to
     * {@link #assignCrops}, which drops occupied ground before asking.
     *
     * <p>Null too when the player provably has no such seed, the rule {@link #assignCrops}
     * applies to fixed-crop stops: holding the patch empty would also cost a rotation herb.
     */
    static Crop contractedInto(PatchRef patch, PlayerState state, FarmingInputs inputs) {
        if (!PatchPriority.isReservedForContracts(patch) || heldForTheNextContract(patch, state)) {
            return null;
        }
        Crop crop = inputs.getContractCrop();
        CropData data = crop == null ? null : CropData.forCrop(crop);
        if (data == null || patch.type() != data.getPatchType()) {
            return null;
        }
        PatchPrediction seen = inputs.patchAt(patch);
        if (seen != null && seen.getCrop() == crop && seen.getState() != CropState.DEAD) {
            return null;
        }
        return SeedSelector.definitelyOutOf(crop, state, data.getSeedsPerPatch()) ? null : crop;
    }

    /**
     * How many of the run's good-seed seats already have a crop in them.
     *
     * <p>Once the quota of good seeds is in the ground, the rest of the run is filler. A
     * spent seat stays spent, so the allocation holds still as patches are planted.
     *
     * <p><b>Ranked over the whole run, not over what is left</b>, or the worst patch would
     * become the best of what remains and draw the player's best herb. Scored through
     * {@link PatchPriority} as {@link #assignCrops} scores its seats.
     *
     * <p>A seat is a patch the run could seed today <em>or</em> already has growing. Leaving
     * out occupied patches would free a seat the moment it was planted. Leaving out
     * unreachable ones would hold a seat nothing can fill. A ready crop is harvested and
     * replanted, so its seat is open (see {@link #occupiedByAlivingCrop}).
     *
     * <p><b>Only as still as the run is.</b> {@link PatchPriority#scoreOf} depends on player
     * state, so an unlock gained mid-run re-ranks the seats and can let the quota over-spend.
     *
     * <p>Read from {@code plans}, so a stop ruled out by a gate the player lacks holds no
     * seat. Skipped stops are kept: a patch skipped because it is growing is exactly a spent
     * seat.
     */
    static int goodSeatsSpent(List<StopPlan> plans, PlayerState state, FarmingInputs inputs, int quota, int[] walk) {
        List<Seat> seats = new ArrayList<>();
        Set<PatchRef> filled = new LinkedHashSet<>();
        for (int index = 0; index < plans.size(); index++) {
            StopPlan plan = plans.get(index);
            if (!plan.getStop().isPlanting() || plan.getStop().isFixedCrop()) {
                continue;
            }
            List<PatchRef> patches = plan.getStop().getPatches();
            for (int patchIndex = 0; patchIndex < patches.size(); patchIndex++) {
                PatchRef ref = patches.get(patchIndex);
                // A patch held for the next contract is reserved for contracts too.
                if (PatchPriority.isReservedForContracts(ref)) {
                    continue;
                }
                boolean occupied = occupiedByAlivingCrop(ref, inputs);
                if (occupied) {
                    filled.add(ref);
                }
                if (occupied || plan.isVisit()) {
                    seats.add(new Seat(index, patchIndex, walk[index], PatchPriority.scoreOf(ref, state), null, ref));
                }
            }
        }
        // The comparator and walk assignCrops deals by. The seat sets differ (this one keeps
        // occupied patches, which assignCrops drops or sends to its upgrade pass), but the
        // shared seats must sort alike, or the quota counts a seat spent that the
        // allocation never offered a good seed to.
        seats.sort(BEST_HOME_FIRST);

        int spent = 0;
        // Bounded by the quota, so the caller's subtraction can never go negative.
        for (int i = 0; i < Math.min(quota, seats.size()); i++) {
            if (filled.contains(seats.get(i).patch)) {
                spent++;
            }
        }
        return spent;
    }

    /**
     * True while a patch holds a living crop, so nothing new can go in it today.
     *
     * <p>Growing and diseased both, as in {@link StopSkipRules#stillStandingIn}: a cure keeps
     * the crop, while a dead one is dug out and leaves the patch bare. Weeds, and a
     * prediction with no crop, are not occupied.
     */
    private static boolean occupiedByAlivingCrop(PatchRef ref, FarmingInputs inputs) {
        PatchPrediction seen = inputs.patchAt(ref);
        if (seen == null || seen.getCrop() == null || seen.isIdle()) {
            return false;
        }
        return seen.getState() == CropState.DISEASED || StopSkipRules.isStillGrowing(seen);
    }

    /**
     * How many of a fixed-crop stop's patches can take a seed this visit: those not holding
     * a living crop, growing or diseased, nor a bush or cactus that stays standing.
     *
     * <p>Any crop, not only the stop's own: a redberry bush growing in the whiteberry patch
     * blocks the whiteberry seed as a growing whiteberry bush would.
     *
     * <p>A crop that regrows after picking, a bush or a cactus, stays in the patch when it is
     * ready too: picking it, or checking its health, leaves the plant standing. Death clears
     * it, and so does digging it up once it is grown ({@link PatchWork#comesOut}).
     *
     * <p>The bag packs the stop's seeds and fees by this count, so it packs what the
     * planting uses.
     */
    static int openFixedPatches(RunStop stop, FarmingInputs inputs, PlayerState state) {
        int open = 0;
        for (PatchRef ref : stop.getPatches()) {
            boolean free = !occupiedByAlivingCrop(ref, inputs) && !staysAfterPicking(ref, inputs);
            if (free || PatchWork.comesOut(inputs.patchAt(ref), stop, inputs.getPreferences(), state)) {
                open++;
            }
        }
        return open;
    }

    /** Whether this patch holds a living crop that regrows, which picking leaves standing. */
    private static boolean staysAfterPicking(PatchRef ref, FarmingInputs inputs) {
        PatchPrediction seen = inputs.patchAt(ref);
        return seen != null && seen.getCrop() != null && !seen.isIdle() && seen.getCrop().getRegrowTickRateMinutes() > 0
                && seen.getState() != CropState.DEAD;
    }

    /**
     * What each stop plants, one entry per patch, keyed by position in {@code plans}.
     *
     * <p>Per patch because a stop is a visit: Fossil Island's three hardwood patches take
     * three saplings, possibly of different crops.
     *
     * <p><b>One entry per patch a seed can go into</b>, so a list is shorter than its stop's
     * patches wherever one is held for the next contract or holds a living crop. Readers
     * count and tally entries; they never line them up against patch positions.
     *
     * <p><b>The better seeds go to the better patches, not the earlier ones.</b> Patches are
     * ranked by {@link PatchPriority} (which reflects diaries and other yield and disease
     * bonuses) and dealt down that ranking, both ends best seed first. Ties keep the
     * catalogue's order.
     *
     * <p>{@link Itinerary} lifts the better homes forward from the same ranking, so a seed
     * box lands correctly. This deals to patches, never to positions, so it does not depend
     * on that.
     *
     * <p>Also reports which patch each seed landed in. The per-stop lists cannot say which of Fossil Island's three patches a teak goes
     * into. {@code StopRowWriter.treesMakingWay} needs the patch to decide which trees to
     * fell.
     *
     * @param plantedIn <b>filled by this method</b>, one entry per seed that found a home
     */
    static List<List<Crop>> assignCrops(List<StopPlan> plans, SeedPlan seeds, PlayerState state, FarmingInputs inputs, int[] walk,
            Map<PatchRef, Crop> plantedIn) {
        List<List<Crop>> cropFor = new ArrayList<>(plans.size());
        // Every patch drawing on the run's seeds. Collected on the way past so the
        // fixed-crop stops are filled in the same walk.
        List<Seat> drawing = new ArrayList<>();
        // Grown trees, fruit or lumber, which clearing is a trade for. They are offered only
        // what the ground above did not take, and only as an upgrade. A living crop anywhere
        // else gets no seat.
        List<Seat> replacing = new ArrayList<>();
        // Patches an outstanding contract or a diary has spoken for, which draw no seed. Folded
        // back in below in the stop's own patch order.
        Map<Seat, Crop> claimed = new LinkedHashMap<>();
        // The fixed crops' patches dealt so far, one entry each.
        List<Crop> fixedDealt = new ArrayList<>();
        for (int index = 0; index < plans.size(); index++) {
            StopPlan plan = plans.get(index);
            List<Crop> atThisStop = new ArrayList<>();
            cropFor.add(atThisStop);
            if (!plan.isVisit()) {
                continue;
            }
            if (plan.getStop().isFixedCrop()) {
                Crop fixed = FixedCrops.cropFor(plan.getStop(), inputs.getPreferences(), state);
                // A crop no run plants has no seed to deal.
                CropData data = CropData.forCrop(fixed);
                if (data == null) {
                    continue;
                }
                // Only where the player provably holds the seed, shared down the run's stops,
                // so a patch past the stock takes none. {@link StopSkipRules#skipIfNoSeed}
                // drops the stop only when nothing else is waiting; here a harvest can keep
                // the visit while the planting goes. A patch holding any living crop takes no
                // seed: one seaweed patch growing beside a ready one plants one, and packs one
                // lot of spores and one protection fee.
                for (int open = openFixedPatches(plan.getStop(), inputs, state); open > 0 && !SeedSelector.definitelyOutOf(fixed, state,
                        (Collections.frequency(fixedDealt, fixed) + 1) * data.getSeedsPerPatch()); open--) {
                    atThisStop.add(fixed);
                    fixedDealt.add(fixed);
                }
                continue;
            }
            if (!plan.getStop().isPlanting()) {
                continue;
            }
            List<PatchRef> patches = plan.getStop().getPatches();
            for (int patchIndex = 0; patchIndex < patches.size(); patchIndex++) {
                PatchRef ref = patches.get(patchIndex);
                // Held, not skipped: the errand still stands; only the planting waits.
                if (heldForTheNextContract(ref, state)) {
                    continue;
                }
                Crop standing = StopSkipRules.stillStandingIn(ref, plan.getStop(), inputs);
                // A living crop that felling is not a trade for: a lumber tree still growing
                // (clearing it loses the tree before its check) or a diseased crop (cured, not dug
                // out). Grown trees, checked or not, come through {@code standing} and go to
                // the upgrade pass.
                //
                // No seat at all, or an unfillable seat would hold its rank and starve a
                // plantable patch. This also agrees with {@link #goodSeatsSpent}, which
                // counts this patch's seed as already spent.
                //
                // Ahead of the contract's claim below: a contract cannot plant through a
                // living crop either, and the guild's errand stop never reaches
                // {@link StopSkipRules#skipIfPatchesStillFull}.
                if (standing == null && occupiedByAlivingCrop(ref, inputs)) {
                    continue;
                }
                // An immature tree is not traded away: felling it wastes the seed and the
                // growth, and waiting costs only the wait. A grown tree awaiting its health
                // check stays a candidate, because the row asks for the felling only after
                // the check turns it HARVESTABLE. It also covers a fruit tree stop with
                // several patches. Disease does not hold it: a diseased tree dies unless
                // cured, so felling it for a better one is a reasonable trade.
                if (standing != null && StopSkipRules.isStillGrowing(inputs.patchAt(ref))) {
                    continue;
                }
                // A contract's named crop claims its patch ahead of the rotation's filler,
                // and so does a crop a diary keeps for this patch (magic at Falador).
                Crop contracted = contractedInto(ref, state, inputs);
                if (contracted == null) {
                    contracted = DiaryPlantings.claimedBy(ref, state, inputs.getPreferences());
                }
                Seat seat = new Seat(index, patchIndex, walk[index],
                        PatchPriority.scoreOf(ref, state), contracted == null ? standing : null, ref);
                if (contracted != null) {
                    claimed.put(seat, contracted);
                } else if (standing == null) {
                    drawing.add(seat);
                } else {
                    replacing.add(seat);
                }
            }
        }

        // The k-th patch the player stands at takes the k-th seed. See BEST_HOME_FIRST.
        drawing.sort(BEST_HOME_FIRST);
        // Where each seed landed, re-sorted below into patch order because a stop's list is
        // the order its plant lines print in.
        Map<Seat, Crop> landed = new LinkedHashMap<>();
        int dealt = 0;
        for (; dealt < drawing.size(); dealt++) {
            Crop crop = seatCrop(seeds, dealt);
            if (crop != null) {
                landed.put(drawing.get(dealt), crop);
            }
        }
        dealOutUpgrades(replacing, seeds, dealt, landed, inputs);
        landed.putAll(claimed);

        List<Seat> planted = new ArrayList<>(landed.keySet());
        planted.sort(Comparator.comparingInt((Seat seat) -> seat.planIndex).thenComparingInt(seat -> seat.patchIndex));
        for (Seat seat : planted) {
            cropFor.get(seat.planIndex).add(landed.get(seat));
            plantedIn.put(seat.patch, landed.get(seat));
        }
        return cropFor;
    }

    /**
     * Spends what the ground seats left over on patches worth upgrading, worst first.
     *
     * <p>While grown trees are kept, a living fruit tree is felled only for a <em>better</em>
     * one, so a palm never makes way for a palm. Replanting them, a fruit tree is matched as
     * a lumber tree is, except a diseased one. The worst tree goes first, so one sapling
     * upgrades the pineapple rather than the papaya.
     *
     * <p>Upgrades are dealt after the ground Larry has seen bare: a seed in bare soil costs
     * only the seed, while here it also costs a producing tree. Ground never seen is only a guess, and gives its
     * seed up to a tree here that finds none spare ({@link #guessHolding}), a kept tree
     * included: a sure planting now beats one that may send the player back later.
     *
     * @param from the seat number the ground ran to, so the two draws share one allocation
     *             rather than each dealing the best seed again
     * @param inputs whose preferences say whether a grown fruit tree need only be matched,
     *             as a lumber tree is, so its own kind replaces it
     */
    private static void dealOutUpgrades(List<Seat> replacing, SeedPlan seeds, int from, Map<Seat, Crop> landed, FarmingInputs inputs) {
        boolean replantsGrownTrees = inputs.getPreferences().replantsGrownTrees();
        // Worst standing crop first; ties by the better home, as the ground seats rank.
        replacing.sort(Comparator.comparingInt((Seat seat) -> tierOf(seat.standing, seat.patch)).reversed()
                .thenComparing(Comparator.comparingInt((Seat seat) -> seat.score).reversed()));
        // What the ground left over, as a pool rather than in order, bounded by the seats.
        List<Crop> spare = new ArrayList<>();
        for (int seat = from; seat < from + replacing.size(); seat++) {
            Crop crop = seatCrop(seeds, seat);
            if (crop != null) {
                spare.add(crop);
            }
        }

        for (Seat candidate : replacing) {
            int standing = tierOf(candidate.standing, candidate.patch);
            // A tree that goes on giving must be beaten outright. A spent lumber tree (check
            // banked) need only be matched: replanting a yew with a yew is the ordinary tree
            // run. A downgrade is refused even there, on purpose: a yew patch is worth more
            // empty than holding an oak, and seedRanOutAt then drops the stop.
            // Replanting grown trees, a fruit tree is matched too: its fruit is worth less
            // than a fresh tree's health check. Not a diseased one, which a cure keeps.
            boolean kept = keepsGiving(candidate.standing) && !(replantsGrownTrees && isFruitTree(candidate.patch)
                            && !diseased(candidate.patch, inputs));
            int floor = kept ? standing - 1 : standing;
            // The <em>worst</em> sapling that still improves this patch, not the best: a
            // dragonfruit spent on a pineapple leaves nothing to beat the palm, while the
            // palm sapling there and the dragonfruit at the palm upgrades both.
            int pick = -1;
            for (int i = 0; i < spare.size(); i++) {
                int tier = tierOf(spare.get(i), candidate.patch);
                if (tier > floor) {
                    continue;
                }
                if (pick < 0 || tier > tierOf(spare.get(pick), candidate.patch)) {
                    pick = i;
                }
            }
            if (pick < 0) {
                // No spare sapling, but one may sit on a patch never seen, dealt as bare ground
                // only because nothing is known of it. A guess never outbids a tree the player
                // can see and replant: otherwise the sapling leaves this patch the moment it is
                // seen, and comes back once the guesses turn out to hold trees too, sending the
                // player back to a patch they already left.
                Seat guess = guessHolding(landed, candidate.patch, floor, inputs);
                if (guess != null) {
                    landed.put(candidate, landed.remove(guess));
                }
                // Otherwise the tree stays. Seats run worst-standing-first, so later ones are
                // harder still to improve on.
                continue;
            }
            landed.put(candidate, spare.remove(pick));
        }
    }

    /**
     * The unseen patch to take a crop from for {@code patch}: the one holding the worst crop
     * that still serves there, as the spare pool picks, and of those the worst home.
     *
     * @param landed the ground seats in the order they were dealt, best home first, then the
     *               upgrades dealt so far this pass, which stand on a tree and are skipped
     * @param patch  the seen patch whose tree finds no spare crop
     * @param floor  the worst tier {@code patch} accepts, as {@link #dealOutUpgrades} reckons it
     * @param inputs what Larry has seen; a seat with no reading is a guess
     * @return the seat to take the crop from, or null when no guess holds one that serves
     */
    private static Seat guessHolding(Map<Seat, Crop> landed, PatchRef patch, int floor, FarmingInputs inputs) {
        Seat worst = null;
        int worstTier = -1;
        for (Map.Entry<Seat, Crop> entry : landed.entrySet()) {
            Seat seat = entry.getKey();
            int tier = tierOf(entry.getValue(), patch);
            // A crop of another family has no tier here, and must never pass a floor that an
            // unranked standing crop leaves at the same no-tier value.
            if (seat.standing != null || inputs.patchAt(seat.patch) != null || tier == Integer.MAX_VALUE || tier > floor) {
                continue;
            }
            // At equal tiers the later seat wins, the worse home.
            if (tier >= worstTier) {
                worst = seat;
                worstTier = tier;
            }
        }
        return worst;
    }

    /**
     * Whether this crop is still worth something to its owner where it stands.
     *
     * <p>A fruit tree bears again and again, so felling it is a loss, unless the player
     * replants grown trees for the health check. A lumber tree pays out once, at its health
     * check. Regrow tells them apart, as in {@link RunStop.StopAction#defaultsFor}.
     */
    private static boolean keepsGiving(Crop crop) {
        return crop != null && crop.getRegrowTickRateMinutes() > 0;
    }

    private static boolean diseased(PatchRef patch, FarmingInputs inputs) {
        PatchPrediction seen = inputs.patchAt(patch);
        return seen != null && seen.getState() == CropState.DISEASED;
    }

    private static boolean isFruitTree(PatchRef patch) {
        return patch.type() == PatchType.FRUIT_TREE;
    }

    /**
     * Where a crop sits in its family's ranking, best first — so smaller is better.
     *
     * <p>{@link CropData#plantableIn} is ordered by Farming level descending, which for the
     * tree families is also the order of worth. An unknown crop sorts to the bottom, so it
     * is replaced rather than protected.
     */
    private static int tierOf(Crop crop, PatchRef patch) {
        PatchType type = patch.type();
        if (crop == null || type == null) {
            return Integer.MAX_VALUE;
        }
        int index = CropData.plantableIn(type).indexOf(crop);
        return index < 0 ? Integer.MAX_VALUE : index;
    }

    /**
     * One patch a seed could go in: where it sits, what it is worth, and what is in the way.
     *
     * <p>{@code standing} is null for bare ground. {@link #goodSeatsSpent} builds seats only
     * to count the quota, reading {@code patch} and the sort keys.
     */
    @AllArgsConstructor
    private static final class Seat {
        private final int planIndex;
        /** Position within the stop's own patch list, which is the order readers expect. */
        private final int patchIndex;
        /** How far along the walk this patch is reached. See {@link #walkPositions}. */
        private final int walkPosition;
        private final int score;
        /** What is growing here that would have to go, or null for bare ground. */
        private final Crop standing;
        private final PatchRef patch;
    }

    /**
     * The order seats are dealt down: best home first, and among equal homes the one the
     * player reaches first.
     *
     * <p><b>A tie is the common case:</b> every reason one herb patch beats another is a
     * diary or a quest, so an account with none has every patch scoring alike. The
     * tie-break must then be walk order, so the k-th patch reached takes the k-th seed out
     * of the seed box.
     *
     * <p>Walk position, not plan-list position: a trip walks the circuit's {@link Arrivals}
     * seats across every family's plans, so where a plan sits in the list says nothing about
     * when the player gets there. {@link #walkPositions} gives the same order
     * {@link Itinerary#bestHomesFirst} is handed its visits in. Plan and patch index make the
     * order total.
     *
     * <p><b>An optional stop can draw a good seed, and that is intended.</b> Ortus Farm sits
     * second on the circuit, so it takes the second seed out of the box.
     */
    private static final Comparator<Seat> BEST_HOME_FIRST = Comparator.comparingInt((Seat seat) -> seat.score).reversed()
                    .thenComparingInt(seat -> seat.walkPosition).thenComparingInt(seat -> seat.planIndex)
                    .thenComparingInt(seat -> seat.patchIndex);

    /**
     * How far along the walk each stop is reached, indexed by position in {@code plans}.
     *
     * <p>A trip walks the circuit; a single run walks the catalogue's order with woven-in
     * extras beside their stop. The allocation must follow whichever order is drawn.
     * {@code bestHomesFirst} breaks ties on the order it is handed, so it and this must be
     * handed the same one.
     *
     * @param tripBook set when the run is walked on a merged trip, which follows the
     *     circuit's seats, or null for a run walked on its own; only whether it is null
     *     matters
     */
    static int[] walkPositions(List<StopPlan> plans, Spellbook tripBook) {
        int[] position = new int[plans.size()];
        if (tripBook != null) {
            for (int i = 0; i < plans.size(); i++) {
                position[i] = Arrivals.seat(plans.get(i).getStop().getArrival());
            }
            return position;
        }
        // The drawn order, which lifts woven-in extras beside their stop.
        List<Integer> order = TripOrder.inTripOrder(plans);
        for (int seat = 0; seat < order.size(); seat++) {
            position[order.get(seat)] = seat;
        }
        return position;
    }

    /**
     * The seed for the nth-best patch, or null where the stock ran out.
     *
     * <p>The good end keeps the seats it was sized for even when short; filler never slides
     * up into them.
     */
    private static Crop seatCrop(SeedPlan seeds, int seat) {
        return seat < seeds.getGood().getWanted() ? seeds.getGood().at(seat) : seeds.getBad().at(seat - seeds.getGood().getWanted());
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.Crop;
import java.util.*;

/**
 * Crops named for the player: as the game names what stands in the patch, and as a word
 * mid-sentence. One place, so the runs list, the rows and the skip reasons spell a crop the
 * same way.
 */
final class CropNames {

    private CropNames() {
    }

    /**
     * Every crop of a bush patch, those Larry never plants included: the game can show any
     * of them standing in a patch whose crop the player has since switched.
     */
    private static final Set<Crop> BUSHES = EnumSet.of(Crop.REDBERRIES, Crop.CADAVABERRIES,
            Crop.DWELLBERRIES, Crop.JANGERBERRIES, Crop.WHITEBERRIES, Crop.POISON_IVY);

    /**
     * The crop as the game names what stands in the patch: "Dwarf weed", "Whiteberry bush".
     * A bush crop's own name ("Whiteberry") reads as one berry, so the bush is named.
     */
    static String displayNameOf(Crop crop) {
        return BUSHES.contains(crop) ? crop.getDisplayName() + " bush" : crop.getDisplayName();
    }

    /** A crop name for mid-sentence: lower case, except Hespori, which is a name. */
    static String inSentence(Crop crop) {
        return inSentence(displayNameOf(crop));
    }

    /**
     * A crop or seed name for mid-sentence: lower case, except a name led by Hespori, which
     * is a proper noun ("no Hespori seed").
     */
    static String inSentence(String name) {
        return name.startsWith(Crop.HESPORI.getDisplayName()) ? name : name.toLowerCase(Locale.ROOT);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.farming.model.Capability;
import java.util.*;

/**
 * Counts how many of a day's rationed teleports the player has spent, so that a route
 * they have run out of can be stepped over rather than offered again.
 *
 * <p>Two sources feed it. Where the game keeps spent uses in a varbit, the count is read
 * and handed to {@link #observeUsesSpent}, which stays right across logouts and other
 * clients. Otherwise uses are counted with {@link #recordUse} as they are seen. Uses made
 * while the plugin is not watching go unseen, so a counted allowance can look healthier
 * than it is. That error is the safe one: the player tries a spent teleport and moves down
 * the chain, where an undercount would silently skip a patch they could have farmed.
 *
 * <p>Counts belong to the tier the player <em>holds</em>, not the tier a chain asks for: a
 * chain naming an Explorer's ring 2 may be served by a held ring 3, which has no daily
 * limit. Resolve the held tier with
 * {@link Capability#bestHeldTier(Capability.TierFamily, java.util.Collection)} before
 * recording or asking.
 *
 * <p>Uses are recorded against an explicit epoch second, so the caller's clock decides the
 * daily rollover.
 */
public final class DailyTeleportLedger {

    private static final long SECONDS_PER_DAY = 86_400L;

    private final Map<Capability, Integer> usedToday = new EnumMap<>(Capability.class);

    /**
     * Which day the counts belong to, as whole days since the epoch. Day boundaries fall
     * at midnight UTC, matching the game's daily reset.
     */
    private long day = Long.MIN_VALUE;

    /** Records one use, ignoring capabilities the game does not ration. */
    public void recordUse(Capability capability, long nowEpochSec) {
        if (!capability.isRationedDaily()) {
            return;
        }
        rollOver(nowEpochSec);
        int spent = usedToday.getOrDefault(capability, 0);
        // Never count past the allowance, so a use seen twice cannot overstate the spend.
        if (spent < capability.getDailyUses()) {
            usedToday.put(capability, spent + 1);
        }
    }

    /**
     * Takes the game's own count of uses spent today, replacing whatever was counted here
     * rather than adding to it.
     *
     * <p>Feed this a varbit from
     * {@link com.larryfarming.farming.detection.CapabilitySources#dailyUsesCapabilitiesByVarbit()},
     * which counts upward from zero as uses are spent.
     */
    public void observeUsesSpent(Capability capability, int spent, long nowEpochSec) {
        if (!capability.isRationedDaily()) {
            return;
        }
        rollOver(nowEpochSec);
        usedToday.put(capability, clampToAllowance(capability, spent));
    }

    /**
     * True when today's allowance is spent, so the route should be stepped over. A
     * capability the game does not ration never runs out.
     */
    public boolean isExhausted(Capability capability, long nowEpochSec) {
        if (!capability.isRationedDaily()) {
            return false;
        }
        rollOver(nowEpochSec);
        return usedToday.getOrDefault(capability, 0) >= capability.getDailyUses();
    }

    /** Forgets everything, for a player switching accounts. */
    public void clear() {
        usedToday.clear();
        day = Long.MIN_VALUE;
    }

    // --- persistence ---------------------------------------------------------

    /** The day the stored counts belong to, to be handed back to {@link #loadPersisted}. */
    public long exportDay() {
        return day;
    }

    public Map<Capability, Integer> exportForPersist() {
        return Collections.unmodifiableMap(new EnumMap<>(usedToday));
    }

    /**
     * Restores counts saved earlier. Counts from a day that has since ended are dropped
     * rather than carried forward, so a player returning tomorrow starts fresh.
     */
    public void loadPersisted(long savedDay, Map<Capability, Integer> saved) {
        usedToday.clear();
        day = savedDay;
        if (saved == null) {
            return;
        }
        for (Map.Entry<Capability, Integer> entry : saved.entrySet()) {
            Capability capability = entry.getKey();
            if (capability == null || !capability.isRationedDaily() || entry.getValue() == null) {
                continue;
            }
            usedToday.put(capability, clampToAllowance(capability, entry.getValue()));
        }
    }

    private static int clampToAllowance(Capability capability, int spent) {
        return Math.max(0, Math.min(spent, capability.getDailyUses()));
    }

    private void rollOver(long nowEpochSec) {
        long today = Math.floorDiv(nowEpochSec, SECONDS_PER_DAY);
        if (today != day) {
            usedToday.clear();
            day = today;
        }
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.*;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.catalogue.CarryItems;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.model.ItemStack;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.*;
import java.util.*;
import java.util.stream.Collectors;
import lombok.*;
import net.runelite.api.gameval.ItemID;

/**
 * What to put back at the next bank: the trip's own things that the rest of the trip has no
 * more use for.
 *
 * <p>Worked out from the bag the player holds now, for the next bank only. A later bank's
 * list would be a guess at a bag that does not exist yet.
 *
 * <p>Only the trip's own things are named: what Larry asked the player to bring and they
 * fetched for it, what the run left behind (empty pots and buckets, produce, roots), and
 * loose seeds and saplings the rest of the trip does not plant, however they came. The
 * player's own kit stays theirs: the rune pouch, the seed box and its seeds, their coins,
 * anything else they carried before packing, and anything worn, which never sits in the
 * inventory. Produce they brought from elsewhere, fruit for eating say, reads as left behind
 * and may be named.
 */
public final class DepositPlanner {

    private DepositPlanner() {
    }

    /** What the trip has packed so far, and the bag it was packed from. */
    @Getter
    @AllArgsConstructor(access = AccessLevel.PRIVATE)
    public static final class TripRecord {

        /** Nothing seen yet. */
        public static final TripRecord EMPTY = new TripRecord(Set.of(), Map.of(), true);

        /** The item ids Larry asked for that the player fetched for this trip. */
        private final Set<Integer> packed;
        /** The fewest of each item the bag held while packing, by item id. */
        private final Map<Integer, Integer> lowest;
        /** Whether the advice this record last read was underway. */
        private final boolean underway;

        /** A record as {@link #getPacked}, {@link #getLowest} and {@link #isUnderway} read it. */
        public static TripRecord of(Set<Integer> packed, Map<Integer, Integer> lowest, boolean underway) {
            return new TripRecord(Set.copyOf(packed), Map.copyOf(lowest), underway);
        }
    }

    /**
     * The trip record after the advice just built.
     *
     * <p>An item counts as packed when Larry lists it and the bag holds more of it than the
     * fewest it held while packing: the player fetched it. A ring they always wear in the
     * bag, or a coin stack, never dips, so it stays theirs. The low marks reset when a new
     * packing list follows a trip. Underway the packed set only grows, since a thing only
     * finished stops used drops off every list yet is still the trip's to put back.
     */
    public static TripRecord record(PlayerState state, FarmingAdvice built, TripRecord before) {
        if (state == null || built == null || state.getInventory() == null) {
            return before;
        }
        Map<Integer, Integer> counts = new HashMap<>();
        for (ItemStack stack : held(state)) {
            counts.merge(stack.getItemId(), stack.getQuantity(), Integer::sum);
        }
        Map<Integer, Integer> lowest;
        if (built.isUnderway()) {
            lowest = before.lowest;
        } else if (before.underway) {
            // A new packing list: the bag as it stands is the player's own.
            lowest = counts;
        } else {
            lowest = new HashMap<>();
            for (Map.Entry<Integer, Integer> low : before.lowest.entrySet()) {
                int now = counts.getOrDefault(low.getKey(), 0);
                if (now > 0) {
                    lowest.put(low.getKey(), Math.min(now, low.getValue()));
                }
            }
        }
        Set<Integer> asked = askedFor(built);
        Set<Integer> packed = built.isUnderway() ? new HashSet<>(before.packed) : new HashSet<>();
        for (Map.Entry<Integer, Integer> held : counts.entrySet()) {
            int itemId = held.getKey();
            if (itemId != ItemID.COINS && asked.contains(itemId) && held.getValue() > lowest.getOrDefault(itemId, 0)) {
                packed.add(itemId);
            }
        }
        return TripRecord.of(packed, lowest, built.isUnderway());
    }

    /** Every form of everything the packing list and the bank rows name. */
    private static Set<Integer> askedFor(FarmingAdvice built) {
        Set<Integer> asked = new HashSet<>();
        List<List<FarmingCarryItem>> lists = new ArrayList<>();
        lists.add(built.getCarry() == null ? List.of() : built.getCarry());
        for (FarmingStopAdvice stop : built.getStops() == null ? List.<FarmingStopAdvice>of() : built.getStops()) {
            if (stop.getWithdraw() != null) {
                lists.add(stop.getWithdraw());
            }
        }
        for (List<FarmingCarryItem> list : lists) {
            for (FarmingCarryItem line : list) {
                asked.addAll(CarryPlanner.formsOf(line.getItemId()));
            }
        }
        return asked;
    }

    /** The roots a regular tree's stump gives when dug up. */
    private static final Set<Integer> ROOTS = Set.of(ItemID.OAK_ROOTS, ItemID.WILLOW_ROOTS,
            ItemID.MAPLE_ROOTS, ItemID.YEW_ROOTS, ItemID.MAGIC_ROOTS);

    /**
     * A herb patch's harvest, which comes grimy. The crop table names the clean herb, which
     * the patch never gives.
     */
    private static final Set<Integer> GRIMY_HERBS = Set.of(ItemID.UNIDENTIFIED_GUAM,
            ItemID.UNIDENTIFIED_MARENTILL, ItemID.UNIDENTIFIED_TARROMIN, ItemID.UNIDENTIFIED_HARRALANDER, ItemID.UNIDENTIFIED_RANARR,
            ItemID.UNIDENTIFIED_TOADFLAX, ItemID.UNIDENTIFIED_IRIT, ItemID.UNIDENTIFIED_AVANTOE, ItemID.UNIDENTIFIED_KWUARM,
            ItemID.UNIDENTIFIED_SNAPDRAGON, ItemID.UNIDENTIFIED_HUASCA, ItemID.UNIDENTIFIED_CADANTINE, ItemID.UNIDENTIFIED_LANTADYME,
            ItemID.UNIDENTIFIED_DWARF_WEED, ItemID.UNIDENTIFIED_TORSTOL);

    /** What farming hands back: each produce id, the logs of a felled tree among them. */
    private static final Set<Integer> PRODUCE = produceIds();

    private static Set<Integer> produceIds() {
        Set<Integer> ids = new HashSet<>();
        for (Crop crop : Crop.values()) {
            if (crop.isProduce() && crop.getItemId() > 0) {
                ids.add(crop.getItemId());
            }
        }
        return ids;
    }

    /**
     * The deposits for the next bank, in the bag's own order, one line per item.
     *
     * @param packedThisTrip the item ids Larry asked for that have been in the bag this trip
     * @param neededLater    what the trip still needs from that bank on; nothing a later
     *     stretch uses is put back
     * @param lastBank       whether no bank worth fetching at follows this one, so a travel
     *     item may be the player's way home and stays
     */
    static List<FarmingCarryItem> atNextBank(PlayerState state, Set<Integer> packedThisTrip,
            List<FarmingCarryItem> neededLater, boolean lastBank) {
        if (state == null || state.getInventory() == null) {
            return List.of();
        }
        Set<Integer> keep = new HashSet<>(RunePouch.POUCH_ITEM_IDS);
        keep.addAll(SeedBox.BOX_ITEM_IDS);
        // How many of each thing the rest of the trip uses, by every form of it.
        Map<Integer, Integer> later = new HashMap<>();
        for (FarmingCarryItem line : neededLater) {
            keep.addAll(CarryPlanner.formsOf(line.getItemId()));
            CarryPlanner.formsOf(line.getItemId()).forEach(form -> later.merge(form, line.getQuantity(), Integer::sum));
        }

        Map<Integer, Integer> counts = new LinkedHashMap<>();
        Map<Integer, String> names = new LinkedHashMap<>();
        for (ItemStack stack : held(state)) {
            counts.merge(stack.getItemId(), stack.getQuantity(), Integer::sum);
            names.putIfAbsent(stack.getItemId(), stack.getName());
        }

        List<FarmingCarryItem> deposits = new ArrayList<>();
        for (Map.Entry<Integer, Integer> held : counts.entrySet()) {
            int itemId = held.getKey();
            // A seed or sapling is planting stock whoever packed it: what the rest of the trip
            // does not plant goes back, and only that many when some of it still goes in.
            boolean stock = !CropData.tagForPlantable(itemId).isEmpty();
            int spare = held.getValue() - later.getOrDefault(itemId, 0);
            if (stock ? spare <= 0 : keep.contains(itemId)) {
                continue;
            }
            boolean travel = CarryItems.formsOf(itemId) != null;
            if (travel && lastBank) {
                continue;
            }
            // A packed farming tool goes back to the leprechaun at its last stop, as that
            // stop's card says, not to a bank: two places for one thing would be one too many.
            if (packedThisTrip.contains(itemId) && ItemCounts.leprechaunStores(itemId)) {
                continue;
            }
            if (!stock && !packedThisTrip.contains(itemId) && !leftBehind(itemId)) {
                continue;
            }
            // No count on the tile while the whole stack goes back: a count that ticks up with
            // every herb picked would redraw the route mid-harvest. Spare planting stock beside
            // what still goes in says how many.
            deposits.add(new FarmingCarryItem(travel ? FarmingCarryItem.Kind.TRAVEL : FarmingCarryItem.Kind.TOOL,
                    itemId, names.get(itemId), spare < held.getValue() ? spare : 0, FarmingCarryItem.Availability.CARRIED,
                    CropData.tagForPlantable(itemId), "", held.getValue()));
        }
        return deposits;
    }

    /** What the run itself leaves in the bag: pots, buckets, produce and roots. */
    static boolean leftBehind(int itemId) {
        return itemId == ItemID.PLANTPOT_EMPTY || itemId == ItemID.BUCKET_EMPTY || ROOTS.contains(itemId) || PRODUCE.contains(itemId)
                || GRIMY_HERBS.contains(itemId);
    }

    /** Items that take a slot each however many: compost buckets and plant cure. */
    private static final Set<Integer> ONE_SLOT_EACH = Set.of(ItemID.BUCKET_COMPOST,
            ItemID.BUCKET_SUPERCOMPOST, ItemID.BUCKET_ULTRACOMPOST, ItemID.PLANT_CURE);

    /**
     * The inventory slots a bank's withdrawals take. A seed going into a carried box takes
     * none, nor do runes in an owned pouch or a seed-box check; a compost bucket or a
     * sapling takes one each; anything else stacks into one.
     */
    static int slotsFor(List<FarmingCarryItem> withdrawals, PlayerState state, boolean ownsRunePouch) {
        int slots = 0;
        for (FarmingCarryItem line : withdrawals) {
            if (line.getAvailability() == FarmingCarryItem.Availability.IN_SEED_BOX
                    || (line.getKind() == FarmingCarryItem.Kind.RUNES && ownsRunePouch)
                    || (line.getKind() == FarmingCarryItem.Kind.SEED && SeedBox.carried(state)
                            && CropData.boxesAsAseed(line.getItemId()))) {
                continue;
            }
            // A seed the box does not take is a sapling or a tree seed: counted one each,
            // which over-counts the tree seeds, the safe way.
            boolean eachTakesOne = ONE_SLOT_EACH.contains(line.getItemId()) || (line.getKind() == FarmingCarryItem.Kind.SEED
                            && !CropData.boxesAsAseed(line.getItemId()));
            slots += eachTakesOne ? Math.max(1, line.getQuantity()) : 1;
        }
        return slots;
    }

    /**
     * Whether the bag is short of room at that bank: fewer free slots than the bank's
     * withdrawals take plus the harvest headroom. Until then, depositing is a tidy-up the
     * player may skip.
     */
    static boolean bagWouldFill(PlayerState state, List<FarmingCarryItem> withdrawals) {
        boolean pouch = ItemCounts.ownsAny(state, RunePouch.POUCH_ITEM_IDS);
        return bagWouldFill(state, slotsFor(withdrawals, state, pouch));
    }

    /** The same, given the slots the withdrawals take. */
    static boolean bagWouldFill(PlayerState state, int withdrawals) {
        if (state == null || state.getInventory() == null) {
            return false;
        }
        return InventorySim.SLOTS - held(state).size() < withdrawals + InventorySim.HARVEST_HEADROOM;
    }

    /** The inventory's occupied slots, in slot order; the caller has checked it was read. */
    private static List<ItemStack> held(PlayerState state) {
        return state.getInventory().stream().filter(stack -> stack != null && stack.getItemId() > 0).collect(Collectors.toList());
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.detection.CapabilityState;
import com.larryfarming.farming.detection.DiaryTiers;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import java.util.*;

/**
 * The seed policy's diary overrides in force: one patch that takes a crop every other patch
 * of its family gives up once a diary is done.
 *
 * <p>The elite Falador diary makes the Falador Park tree patch disease-free, so magic
 * saplings go there and nowhere else. Before the diary a ticked magic is an ordinary rung
 * of the tree run's ladder.
 *
 * <p>An override never plants an unticked crop, and an unknown diary reads as not done, as
 * in {@link PatchPriority}.
 */
final class DiaryPlantings {

    private DiaryPlantings() {
    }

    /**
     * The crop this patch takes ahead of its run's ladder, or null.
     *
     * <p>Only while the player holds one, so a player out of magic saplings plants the
     * ladder's next crop at Falador rather than leaving it bare.
     */
    static Crop claimedBy(PatchRef patch, PlayerState state, FarmingPreferences prefs) {
        for (SeedPolicy.DiaryOverride override : inForce(state, prefs)) {
            if (override.getPatch().equals(patch) && SeedSelector.knownToHold(override.getCrop(), state, 1)) {
                return override.getCrop();
            }
        }
        return null;
    }

    /** The crops kept for an override's patch, which every other patch goes without. */
    static Set<Crop> withheld(PlayerState state, FarmingPreferences prefs) {
        Set<Crop> withheld = EnumSet.noneOf(Crop.class);
        for (SeedPolicy.DiaryOverride override : inForce(state, prefs)) {
            withheld.add(override.getCrop());
        }
        return withheld;
    }

    /**
     * What this stop could be filled from: the run's ladder less the withheld crops, with
     * the stop's own claimed crop put back.
     */
    static List<Crop> ladderAt(List<Crop> ladder, RunStop stop, PlayerState state, FarmingPreferences prefs) {
        List<SeedPolicy.DiaryOverride> overrides = inForce(state, prefs);
        if (overrides.isEmpty()) {
            return ladder;
        }
        List<Crop> crops = new ArrayList<>(ladder.size());
        for (Crop crop : ladder) {
            if (!withheldFrom(stop, crop, overrides)) {
                crops.add(crop);
            }
        }
        return crops;
    }

    private static boolean withheldFrom(RunStop stop, Crop crop, List<SeedPolicy.DiaryOverride> overrides) {
        boolean withheld = false;
        for (SeedPolicy.DiaryOverride override : overrides) {
            if (override.getCrop() != crop) {
                continue;
            }
            if (stop.getPatches().contains(override.getPatch())) {
                return false;
            }
            withheld = true;
        }
        return withheld;
    }

    private static List<SeedPolicy.DiaryOverride> inForce(PlayerState state, FarmingPreferences prefs) {
        List<SeedPolicy.DiaryOverride> inForce = new ArrayList<>();
        for (SeedPolicy.DiaryOverride override : FarmingCatalogue.seedPolicy().getDiaryOverrides()) {
            if (prefs.allows(override.getCrop()) && DiaryTiers.completed(override.getDiaryArea(), override.getDiaryTier(),
                            state) == CapabilityState.HAVE) {
                inForce.add(override);
            }
        }
        return inForce;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.detection.*;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Turns a planned run into the flat, already-decided shape the panel renders.
 *
 * <p>Holds the entry points and the orchestration: which runs make the trip, the one book
 * it is walked on, the arrivals in walking order, and everything the panel shows around the
* rows. The parts live beside it: {@link RunPlanning} plans each run, with
 * {@link StopSkipRules} and {@link CropAssigner} deciding stops and crops;
 * {@link StopRowWriter} writes each arrival's row; {@link BankStopSplicer} adds the bank
 * rows.
 */
public final class FarmingAdviceBuilder {

    private FarmingAdviceBuilder() {
    }

    /**
     * The farming this player should go and do, walked through in full, with every run's
     * standing alongside it.
     *
     * <p>The trip covering every family with work waiting, or otherwise a run to walk through
     * on a quiet day, usually the herb run, so a quiet day still shows what the feature does.
     */
    public static FarmingAdvice forPlayer(PlayerState state, FarmingInputs inputs, long nowEpochSec) {
        // The caller's clock overrides the inputs' clock, so one second is in play. Inputs
        // built without a clock would otherwise never say what any stop was for.
        FarmingInputs given = (inputs != null ? inputs : FarmingInputs.none()).withNowEpochSec(nowEpochSec).seeing(state);
        FarmingAdvice advice = advise(state, given, nowEpochSec);
        // The bins are first judged on all the ash, before the trip's Fertile Soil casts are
        // counted. When the two together want more than the player owns, the casts keep their
        // ash and the trip is planned again with the bins sharing the rest. Each build decides
        // this from scratch, so the plan never swings between the two answers.
        int fertileAsh = advice != null ? advice.getFertileAsh() : 0;
        if (CompostBins.outrunTheAsh(given, state, fertileAsh)) {
            return advise(state, given.withFertileAsh(fertileAsh).seeing(state), nowEpochSec);
        }
        return advice;
    }

    /** The advice for these inputs, already seen for this player. */
    private static FarmingAdvice advise(PlayerState state, FarmingInputs given, long nowEpochSec) {
        Spellbook openBook = openBookOf(state);
        List<FarmingRunStatus> runs = RunScheduler.schedule(state, given, openBook, nowEpochSec);
        // Both paths below read the contract's row from the runs list's verdict, so the trip
        // and the quiet-day run cannot disagree about the contract.
        // Seen again, so the copy judges its bins once rather than at every reader.
        given = given.withContractRun(statusOf(runs, RunId.CONTRACT)).seeing(state);

        FarmingAdvice trip = adviseOnTrip(runs, state, given);
        if (trip != null) {
            return withRuns(trip, runs, state, given);
        }

        RunId walk = runForAquietDay(runs, RunScheduler.herbRunsWaitForTheLevel(given.getPreferences(), state));
        return walk == null ? null : withRuns(adviseOnAquietDay(walk, state, given), runs, state, given);
    }

    /**
     * The quiet day's run, walked as a trip of one family so its stops come in the order
     * they will keep once the run falls due and joins a real trip.
     *
     * <p>Once a run falls due, the walkthrough becomes the trip. Walked as a trip here too,
     * the run keeps its order and its routes at that moment.
     *
     * <p>Planned on its own only when the trip draws no row at all.
     */
    private static FarmingAdvice adviseOnAquietDay(RunId id, PlayerState state, FarmingInputs given) {
        RunVariants.Choice pick = variantFor(id, state, given);
        if (pick == null) {
            return null;
        }
        FarmingAdvice trip = walkTrip(List.of(pick), id.getDisplayName(), state, given);
        return trip != null ? trip : adviseOn(pick.getRun(), state, given, pick.getPlanFor());
    }

    /** {@link RunId#DISPLAY_ORDER} as the ids the snapshot carries. */
    private static final List<String> RUN_ORDER = namesOf(RunId.DISPLAY_ORDER);

    /** The walkthrough with every run's standing and the panel's settings added. */
    private static FarmingAdvice withRuns(FarmingAdvice advice, List<FarmingRunStatus> runs, PlayerState state, FarmingInputs inputs) {
        if (advice == null) {
            return null;
        }
        FarmingPreferences prefs = inputs.getPreferences();
        FarmingHouse house = RunSettings.house(prefs, state, inputs.getHouse());
        return advice.toBuilder().lookOnce(LookOnce.sentence(state, house)).runs(runs).runOrder(RUN_ORDER)
                .switchedOff(RunSettings.switchedOff(prefs)).runSettings(RunSettings.forRuns(prefs, state, inputs::patchAt, inputs.getCompost(),
                        inputs.quietPicks(state)))
                .runFirst(RunSettings.runFirst(prefs)).waitForEveryPatch(RunSettings.waitForEveryPatch(prefs))
                .travelGroups(RunSettings.travelGroups(prefs, state, inputs.getHouse())).house(house)
                .fairyRingBlocked(fairyRingBlocked(advice, state, inputs)).build();
    }

    /**
     * Whether nothing the player uses reaches a fairy ring, while the network itself is
     * open to them. Asked on the book the run is planned for, since spells are approaches
     * too: Varrock on the standard book, Salve graveyard and the library on Arceuus.
     */
    private static boolean fairyRingBlocked(FarmingAdvice advice, PlayerState state, FarmingInputs inputs) {
        Spellbook book = advice.getCarryFor() != null ? Spellbook.valueOf(advice.getCarryFor()) : Spellbook.STANDARD;
        CapabilityResolver asked = inputs.resolverOn(book);
        return asked.evaluate(FarmingCatalogue.toAfairyRing(), state, Map.of()) == CapabilityState.LACK
                && asked.resolve(Capability.FAIRY_RINGS, state).getState()
                        != CapabilityState.LACK;
    }

    /**
     * What to show when there is nothing to walk: the herb run, or else the first round of
     * patches offered, such as the fruit trees, ahead of the errands.
     *
     * <p>Herb, not whatever sorts first, because with nothing due the ranking means little.
     * Herb is the run a player most likely already does, unless
     * the herb run waits for the player's Farming level. A held herb run is still shown when
     * nothing else is offered, rather than nothing.
     *
     * @param herbsWait whether the herb run waits for the level, which passes it over
     */
    private static RunId runForAquietDay(List<FarmingRunStatus> runs, boolean herbsWait) {
        RunId herb = statusOf(runs, RunId.HERB) != null ? RunId.HERB : null;
        if (herb != null && !herbsWait) {
            return herb;
        }
        // A round of patches first: the contract and Hespori are single errands and make
        // a poor quiet-day walkthrough.
        RunId fallback = null;
        for (FarmingRunStatus run : runs) {
            RunId id = RunId.valueOf(run.getRunId());
            if (id == RunId.HERB) {
                continue;
            }
            if (!ERRANDS.contains(id)) {
                return id;
            }
            if (fallback == null) {
                fallback = id;
            }
        }
        return fallback != null ? fallback : herb;
    }

    /** The runs that are not a round of patches, which a quiet day walks only for want of one. */
    private static final Set<RunId> ERRANDS = EnumSet.of(RunId.CONTRACT, RunId.HESPORI, RunId.ANIMA);

    /**
     * The runs list's verdict on one family, or null when the player has switched that
     * family's crops off.
     */
    private static FarmingRunStatus statusOf(List<FarmingRunStatus> runs, RunId wanted) {
        for (FarmingRunStatus run : runs) {
            if (wanted.name().equals(run.getRunId())) {
                return run;
            }
        }
        return null;
    }

    /**
     * @param book the spellbook to plan the routes on, or null to follow the preview book
     *             and then the open one. Callers that already chose a variant pass the
     *             book it was chosen on, so the walkthrough and the runs list plan the
     *             same run on the same book even before the player swaps.
     */
    public static FarmingAdvice adviseOn(FarmingRun run, PlayerState state, FarmingInputs given, Spellbook book) {
        FarmingInputs inputs = given.seeing(state);
        Spellbook openBook = openBookOf(state);
        Spellbook planFor = book != null ? book : inputs.getPreviewBook() != null ? inputs.getPreviewBook() : openBook;
        // Without the ledger every route resolves as though the day's limited teleports
        // were unspent.
        CapabilityResolver resolver = inputs.resolverOn(planFor);
        // Planned in the catalogue's order, not as part of the merged circuit.
        SeedSelector.Stock rotationStock = SeedSelector.rotationStock(inputs.getPreferences(), state);
        RunPlanning.RunPlan planned = RunPlanning.planRun(run, state, inputs, resolver, rotationStock, null, false);
        RunPlanner planner = new RunPlanner(resolver);
        // Routed again against the best-homes-first order, as the circuit is. planRun
        // settled its routes in the catalogue's order, so a rung leaning on another stop or
        // on where the player stands was decided for a position the stop no longer holds.
        Itinerary.Trip trip = RunPlanning.replanAcrossTheCircuit(Itinerary.alone(planned.forTrip(), state), planner, state);
        // A one-element seed list so the bag takes the same calls as on a trip.
        return drawTrip(trip, false, run.getId().getDisplayName(), run, planned.plantedIn,
                List.of(planned.seeds), state, planner, inputs, planFor);
    }

    // --- Planning a trip -----------------------------------------------------

    /**
     * Every family with work waiting, walked as one circuit.
     *
     * <p>Plans every due family and hands the stops to {@link Itinerary}, which puts them
     * in circuit order so a place is visited once.
     *
     * <p><b>One spellbook for the whole trip</b>, chosen by {@link #bookForTrip}. Planning
     * each family on its own best book would produce a circuit no single player could walk.
     *
     * @return null when nothing is due
     */
    private static FarmingAdvice adviseOnTrip(List<FarmingRunStatus> runs, PlayerState state, FarmingInputs inputs) {
        // Shared across families: building a resolver is the expensive half of scoring a
        // variant, and this scores every due family on every snapshot.
        Map<Spellbook, CapabilityResolver> resolvers = RunVariants.newResolverCache();
        List<RunVariants.Choice> due = new ArrayList<>();
        for (FarmingRunStatus status : runs) {
            // An unfinished trip counts as due. Planting the last herb takes the herb run
            // out of DUE, and a trip built on DUE alone would drop its woven-in stops
            // (Ortus Farm, the Monastery bushes) before the player reached them.
            if (!RunStatus.DUE.name().equals(status.getStatus()) && !status.isTripUnfinished()) {
                continue;
            }
            RunVariants.Choice choice = variantFor(RunId.valueOf(status.getRunId()), state, inputs, resolvers);
            if (choice != null) {
                due.add(choice);
            }
        }
        if (due.isEmpty()) {
            return null;
        }
        return walkTrip(due, "Farm run", state, inputs);
    }

    /**
     * The trip over these families, or null when it draws no row.
     *
     * @param due the families on the trip, in the scheduler's ranking, which picks the
     *     respawn suggestion. The stops are merged in priority order instead, so a family
     *     coming due or going quiet never re-decides which family's stop leads an arrival
     *     or wins a patch two families name.
     * @param runName the walkthrough's title
     */
    private static FarmingAdvice walkTrip(List<RunVariants.Choice> due, String runName, PlayerState state, FarmingInputs inputs) {
        List<RunVariants.Choice> merged = new ArrayList<>(due);
        // The preset's order, even for a player who runs herbs first.
        merged.sort(Comparator.comparingInt(choice -> choice.getRun().getId().getPriority()));

        Spellbook planFor = bookForTrip(merged, openBookOf(state));
        CapabilityResolver resolver = inputs.resolverOn(planFor);

        List<Itinerary.Planned> planned = new ArrayList<>(merged.size());
        List<SeedPlan> seeds = new ArrayList<>(merged.size());
        // One map for the whole trip. Patches are globally unique, and the rows are drawn
        // off the merged circuit, where a family is no longer indexable.
        Map<PatchRef, Crop> plantedIn = new HashMap<>();
        // Counted once and drawn down as the families take from it, so two families
        // drawing the rotation cannot each claim the same stack in full.
        SeedSelector.Stock rotationStock = SeedSelector.rotationStock(inputs.getPreferences(), state);
        // The contract's named seed leaves the stock before anything draws, so no herb patch
        // is offered it. Then the families that draw only filler (the contract's reserved
        // guild patch) draw last: filler takes carried seeds first, and must not take the
        // good seeds the player withdrew for the herb run.
        boolean[] contractSeedTaken = new boolean[merged.size()];
        List<Integer> drawOrder = new ArrayList<>(merged.size());
        for (int i = 0; i < merged.size(); i++) {
            contractSeedTaken[i] = RunPlanning.takeTheContractsSeedFirst(merged.get(i).getRun(), state, inputs, resolver, rotationStock);
            drawOrder.add(i);
        }
        drawOrder.sort(Comparator.comparing((Integer i) -> RunPlanning.drawsOnlyFiller(merged.get(i).getRun())));
        RunPlanning.RunPlan[] runs = new RunPlanning.RunPlan[merged.size()];
        for (int i : drawOrder) {
            runs[i] = RunPlanning.planRun(merged.get(i).getRun(), state, inputs, resolver, rotationStock, planFor, contractSeedTaken[i]);
        }
        for (RunPlanning.RunPlan run : runs) {
            planned.add(run.forTrip());
            seeds.add(run.seeds);
            plantedIn.putAll(run.plantedIn);
        }

        RunPlanner planner = new RunPlanner(resolver);
        // Merged, then routed again against the merged order. Each run chose its routes
        // knowing only its own stops in its own order; the circuit interleaves families
        // and lifts best homes forward, so a rung leaning on a patch can now come before it.
        // The Monastery bushes move first, so the leg they start is routed from them. Once a
        // trip is underway, the stops on screen keep their order, from the first still
        // to visit.
        Itinerary.Trip trip = RunPlanning.replanAcrossTheCircuit(headingFirst(
                CloakToTheRings.bushesBeforeTheFirstRing(Itinerary.merge(planned, state), resolver, state), inputs), planner, state);
        // The respawn suggestion follows the family the ranking puts first.
        return drawTrip(trip, true, runName, due.get(0).getRun(), plantedIn, seeds, state, planner, inputs, planFor);
    }

    /**
     * The walkthrough of a planned trip: a row per arrival, then the bag and everything
     * around the rows.
     *
     * @param merged true for a merged trip, which plans a combined route for an arrival
     *     working two patches; false for a single run, which keeps each lead's own route
     * @param respawnFor the run whose respawn point the suggestion follows
     * @return the walkthrough, or null when a merged trip draws no row; a single run is the
     *     trip even with no row
     */
    private static FarmingAdvice drawTrip(Itinerary.Trip trip, boolean merged,
            String runName, FarmingRun respawnFor, Map<PatchRef, Crop> plantedIn,
            List<SeedPlan> seeds, PlayerState state, RunPlanner planner, FarmingInputs inputs, Spellbook planFor) {
        CapabilityResolver resolver = planner.resolver();
        List<FarmingStopAdvice> stops = new ArrayList<>(trip.getVisits().size());
        // Grown as the circuit is walked, for visits that earn an arrival's combined route
        // (planned here, not in replanAcrossTheCircuit). Filled for any combined chain with a
        // rung that leans on a patch.
        Map<PatchRef, CapabilityState> reached = new LinkedHashMap<>();
        // The families the player will see rows for, in circuit order.
        Set<RunId> covered = new LinkedHashSet<>();
        // The visits the player is making, and where each one's row sits in {@code stops}.
        // The bag is simulated over the shorter list, and its leg indices must map back to
        // a row.
        List<List<Integer>> made = new ArrayList<>();
        List<Integer> rowOf = new ArrayList<>();
        // Only the first arrival made may be routed from where the player stands. Cleared on
        // the first VISIT row, the same journey replanLeaningRungs spends it on
        // (StopRowWriter.isJourney).
        boolean mayStandHere = true;
        // What the last journey leaves the next, as replanLeaningRungs tracks it.
        RunPlanner.Start start = null;
        // The trip's plans, less the way to the first arrival when the player already stands there.
        List<StopPlan> tripPlans = new ArrayList<>(trip.getPlans());
        for (List<Integer> visit : trip.getVisits()) {
            // Standing in the first arrival made, its visits need no route to read and no
            // teleport to pack, so the row leads with its work.
            boolean here = mayStandHere && StopRowWriter.isJourney(visit, tripPlans) && standsIn(visit, tripPlans, state);
            if (here) {
                visit.forEach(index -> tripPlans.set(index, standingAt(tripPlans.get(index))));
            }
            StopPlan route = merged && !here ? StopRowWriter.routeForVisit(visit, tripPlans,
                    StopRowWriter.leadOf(visit, tripPlans), planner, state, reached, mayStandHere, start) : null;
            FarmingStopAdvice row = StopRowWriter.adviseOnGroup(visit, tripPlans, trip.getCropFor(), plantedIn, inputs, route, state);
            start = CloakToTheRings.after(start, visit, tripPlans, resolver, state);
            stops.add(row);
            // Only VISIT rows feed the bag and the reached patches. The sim banks at any
            // arrival on a leg that has a bank, so a skipped visit would let it break the
            // trip somewhere the walkthrough is not sending the player. A rung leaning on a
            // patch is free only once the player has stood there.
            if (row.getOutcome() == FarmingStopAdvice.Outcome.VISIT) {
                made.add(visit);
                rowOf.add(stops.size() - 1);
                // The patches the visit works, each as sure as its own stop's plan (not the
                // arrival plan routeForVisit may have found).
                for (int index : visit) {
                    RunPlanner.stood(reached, tripPlans.get(index));
                }
                mayStandHere = false;
            }
            for (int index : visit) {
                covered.add(trip.getRunFor().get(index));
            }
        }

        // No arrival drew a row, so there is no trip and the caller falls back to its
        // quiet-day run.
        if (stops.isEmpty() && merged) {
            return null;
        }
        boolean underway = underway(trip.getVisits(), trip.getPlans(), trip.getRunFor(), inputs);
        // A single run is itself the trip, so the panel has one rule for "which families am
        // I looking at?".
        List<String> tripRuns = merged ? namesOf(covered) : List.of(respawnFor.getId().name());

        // The bag is simulated over the arrivals made, the bank stops spliced in, and
        // everything the panel shows around the rows added.
        List<StopPlan> plans = onTheJourneys(tripPlans, made);
        List<List<Crop>> cropFor = trip.getCropFor();
        // One answer for the loadout and the bag simulation. The packing list names the
        // basket either way.
        CarryPlanner.BasketPlace basket = CarryPlanner.basketPlace(plans, cropFor, state, inputs);
        InventorySim.Plan bag = InventorySim.plan(InventoryDemands.forTrip(made, plans, cropFor, inputs, state, resolver),
                InventoryDemands.fixturesFor(state, resolver, plans, inputs, basket == CarryPlanner.BasketPlace.BAG));
        List<SlotAdvice> loadout = LoadoutPlanner.plan(state, CarryPlanner.staffWielded(plans, state, resolver),
                teleportsByExplorersRing(plans), basket == CarryPlanner.BasketPlace.BACK);
        WithdrawalPlanner.Withdrawals withdrawals = WithdrawalPlanner.forBankStops(bag, made,
                plans, cropFor, seeds, state, resolver, inputs, underway);
        List<FarmingCarryItem> carry = CarryPlanner.plan(plans, seeds, cropFor, state, resolver, inputs);
        int fertileAsh = FertileSoil.inUse(inputs.getPreferences(), state, resolver.getBook())
                ? FertileSoil.castsFor(plans, cropFor) * FertileSoil.ASH_PER_CAST : 0;
        return FarmingAdvice.builder().runName(runName).tripRuns(tripRuns).fertileAsh(fertileAsh)
                // A leg's ends index {@code made}, whose entries index {@code plans}.
                .stops(BankStopSplicer.withBankStops(withCardNotes(stops, bag, made, rowOf,
                        plans, cropFor, carry, underway, state, resolver, inputs), bag, rowOf, withdrawals, underway))
                .carryNow(underway ? List.of() : nowHalf(withdrawals.getFirstStretch(), carry)).underway(underway)
                .upgrades(LoadoutPlanner.upgrades(loadout)).carry(carry).herbNote(untickedHerbNote(state, inputs, plans))
                .respawnAction(respawnAction(respawnFor, state, resolver)).carryFor(planFor.name())
                .spellbookOpen(openBookOf(state).name()).build();
    }

    /**
     * The plans with every visit off the arrivals made turned into a skip. A visit under a
     * skipped lead, such as an allotment beside a herb patch with no seed, sends nobody to
     * its farm ({@link StopRowWriter#isJourney}), so the bag packs no teleport, seed or
     * compost for it.
     */
    private static List<StopPlan> onTheJourneys(List<StopPlan> plans, List<List<Integer>> made) {
        List<StopPlan> going = new ArrayList<>(plans.size());
        for (StopPlan plan : plans) {
            going.add(plan.isVisit() ? StopPlan.skip(plan.getStop(), "", FarmingSkipReason.NOT_WORTH_TRIP, plan.getReadyAtEpochSec()) : plan);
        }
        for (List<Integer> visit : made) {
            for (int index : visit) {
                going.set(index, plans.get(index));
            }
        }
        return going;
    }

    /**
     * The trip walked on in the order the plan on screen gave, from the first stop on it
     * still to visit. Before the trip is underway the circuit's order stands.
     *
     * <p>The stop on screen first can be one just worked, and a worked stop can move its
     * neighbours on the trip: Kastori follows Ortus Farm while its cheapest route starts from
     * that patch, and once the patch is done that route is gone and Kastori's place on the
     * trip can change. So the trip starts at the first stop on screen still to visit, never
     * at a worked one. The stops on screen also keep their order, so a stop whose circuit
     * seat lies earlier, such as a run that comes due partway round, never jumps ahead of the
     * player's plan and what they packed for it. A seat behind the player goes to the end
     * rather than turning them round. Stops match by arrival, since two rows can share a
     * name.
     */
    private static Itinerary.Trip headingFirst(Itinerary.Trip trip, FarmingInputs inputs) {
        List<String> ahead = inputs.getAhead();
        List<List<Integer>> visits = new ArrayList<>(trip.getVisits());
        if (ahead.isEmpty() || !underway(visits, trip.getPlans(), trip.getRunFor(), inputs)) {
            return trip;
        }
        // The seats the stops on screen hold now, refilled with those stops in screen order.
        // A plan has one row per arrival, so no two stops share a place on screen.
        List<Integer> seats = new ArrayList<>();
        TreeMap<Integer, List<Integer>> byPlaceOnScreen = new TreeMap<>();
        for (int i = 0; i < visits.size(); i++) {
            List<Integer> group = visits.get(i);
            int placeOnScreen = ahead.indexOf(trip.getPlans().get(group.get(0)).getStop().getArrival().name());
            if (placeOnScreen >= 0 && !StopRowWriter.visitsIn(group, trip.getPlans()).isEmpty()) {
                seats.add(i);
                byPlaceOnScreen.put(placeOnScreen, group);
            }
        }
        if (seats.isEmpty()) {
            return trip;
        }
        Iterator<List<Integer>> inScreenOrder = byPlaceOnScreen.values().iterator();
        for (int seat : seats) {
            visits.set(seat, inScreenOrder.next());
        }
        Collections.rotate(visits, -seats.get(0));
        return trip.revisited(visits);
    }

    /** Run ids as the snapshot speaks them, immutable, in the given (circuit) order. */
    private static List<String> namesOf(Collection<RunId> runs) {
        return runs.stream().map(RunId::name).collect(Collectors.toUnmodifiableList());
    }

    /** Whether the player stands in the map region of a patch this arrival visits. */
    private static boolean standsIn(List<Integer> visit, List<StopPlan> plans, PlayerState state) {
        Integer region = state == null ? null : state.getRegionId();
        return region != null && StopRowWriter.visitsIn(visit, plans).stream()
                .anyMatch(plan -> plan.getStop().getPatches().stream().anyMatch(ref -> ref.getRegionId() == region));
    }

    /** A visit made from where the player stands: no route, no teleport, nothing it leans on. */
    private static StopPlan standingAt(StopPlan plan) {
        return plan.isVisit() ? new StopPlan(plan.getStop(), StopPlan.Outcome.VISIT, null, CapabilityState.HAVE, "", null,
                plan.getReadyAtEpochSec(), Set.of(), null) : plan;
    }

    /**
     * Whether the player is partway round the walkthrough on screen: some stop on it is off
     * the walkthrough with a crop growing that was seen within one trip's span, and the
     * family that stop belongs to still has an arrival to make.
     *
     * <p>The family check keeps a finished run from leaking into the next one. Straight
     * after a herb run every herb patch is freshly growing, and a later trip or the
     * quiet-day herb walkthrough still lists them as skipped. Those sightings belong to a
     * trip that is over unless the herb family has somewhere left to go.
     *
     * @param arrivals the arrivals that drew a row, as indices into {@code plans}
     * @param runFor the family each plan belongs to, index for index with {@code plans}
     */
    static boolean underway(List<List<Integer>> arrivals, List<StopPlan> plans, List<RunId> runFor, FarmingInputs inputs) {
        // Without a clock every sighting would read as moments ago.
        if (inputs.getNowEpochSec() <= 0) {
            return false;
        }
        Set<RunId> stillVisiting = EnumSet.noneOf(RunId.class);
        for (List<Integer> group : arrivals) {
            for (int index : group) {
                if (plans.get(index).isVisit()) {
                    stillVisiting.add(runFor.get(index));
                }
            }
        }
        for (List<Integer> group : arrivals) {
            for (int index : group) {
                if (stillVisiting.contains(runFor.get(index)) && grewThisTrip(plans.get(index), inputs)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Whether this stop is off the walkthrough with a crop still growing in its patch that
     * was seen within one trip's span.
     *
     * <p>Patches report only while the player stands near them, so a fresh sighting of a
     * growing crop means they planted it or walked past it on this trip. The window is the
     * runs list's ({@link RunScheduler#seenThisTrip}), so the two agree on when a trip ends:
     * one sighting within it is enough, as the latest patch of a running trip always is.
     *
     * <p>Read off the patch, not off the skip reason. Route skips are settled before growth
     * is checked, so a patch the player has just planted can still be skipped as not worth
     * the trip when the planner does not know the way the player came.
     *
     * <p>Standing crops do not count: a bush left standing is passed on every run and says
     * nothing about this one.
     */
    private static boolean grewThisTrip(StopPlan plan, FarmingInputs inputs) {
        if (plan.isVisit() || plan.getSkipReason() == FarmingSkipReason.STANDING_CROP) {
            return false;
        }
        for (PatchRef ref : plan.getStop().getPatches()) {
            PatchPrediction seen = inputs.patchAt(ref);
            if (StopSkipRules.isStillGrowing(seen) && RunScheduler.seenThisTrip(seen.getObservedAtEpochSec(), inputs.getNowEpochSec())) {
                return true;
            }
        }
        return false;
    }

    /**
     * The one book the whole trip is walked on. Its rungs route every stop, and its seats
     * order every family's stops on the circuit.
     *
     * <p>The first book any family <em>asked</em> for, otherwise the open one. Only the herb
     * run comes in per-book variants; every other {@link RunVariants.Choice} names the open
     * book. Taking the top-ranked family's book instead would plan a trailing herb run's
     * Arceuus route on Standard and silently drop patches.
     *
     * <p><b>Not measured:</b> what the swap costs the other families. A swap may turn
     * another family's spell into a tablet. That cost is bounded, because a teleport with no
     * spell falls back to a tablet, and the player is told to swap.
     */
    private static Spellbook bookForTrip(List<RunVariants.Choice> due, Spellbook openBook) {
        for (RunVariants.Choice choice : due) {
            if (choice.getPlanFor() != openBook && choice.getPlanFor() != Spellbook.ANY) {
                return choice.getPlanFor();
            }
        }
        return openBook;
    }

    // --- Seeds ---------------------------------------------------------------

    /**
     * A note for the player carrying herb seeds the rotation will not plant because they
     * are switched off in the herb run's grid, or empty. The grid stays the rule, so the run
     * says why the seeds in the inventory are passed over instead of quietly planting them.
     *
     * <p>Empty when no visit plants a herb patch: with no herb planting on screen the seeds
     * are not being passed over.
     */
    private static String untickedHerbNote(PlayerState state, FarmingInputs inputs, List<StopPlan> plans) {
        if (!plantsTheHerbRotation(plans)) {
            return "";
        }
        List<Crop> unticked = SeedSelector.carriedButUnticked(inputs.getPreferences(), state);
        if (unticked.isEmpty()) {
            return "";
        }
        List<String> names = unticked.stream().map(CropNames::inSentence).collect(Collectors.toList());
        return "You carry " + LookOnce.joined(names, "and") + " seeds. Turn them on under "
                + RunId.HERB.getDisplayName() + " to plant them.";
    }

    /** Whether any visit plants a herb patch the rotation fills. */
    private static boolean plantsTheHerbRotation(List<StopPlan> plans) {
        for (StopPlan plan : plans) {
            if (plan.isVisit() && plan.getStop().isPlanting() && !plan.getStop().isFixedCrop()
                    && plan.getStop().patchType() == PatchType.HERB) {
                return true;
            }
        }
        return false;
    }

    // --- Spellbook -----------------------------------------------------------

    /**
     * Which version of a run to show, decided as the runs list decides it: by which reaches
     * the most patches for this player, not by the book the default route prefers.
     *
     * <p>A preview book picks the variant written for it outright.
     */
    static RunVariants.Choice variantFor(RunId id, PlayerState state, FarmingInputs inputs) {
        return variantFor(id, state, inputs, RunVariants.newResolverCache());
    }

    /**
     * @param resolvers one resolver per book, shared across calls because building them is
     *                  the expensive half of the answer
     */
    private static RunVariants.Choice variantFor(RunId id, PlayerState state,
            FarmingInputs inputs, Map<Spellbook, CapabilityResolver> resolvers) {
        List<FarmingRun> variants = FarmingCatalogue.runsById().getOrDefault(id, List.of());
        if (variants.isEmpty()) {
            return null;
        }
        Spellbook preview = inputs.getPreviewBook();
        if (preview != null) {
            for (FarmingRun run : variants) {
                if (run.getSpellbook() == preview) {
                    return new RunVariants.Choice(run, preview, 0, 0, List.of());
                }
            }
            // A book this run has no version of (Standard, for the herb run). The best
            // variant is still planned on the named book.
            return RunVariants.best(variants, state, preview, inputs, resolvers).withPlanFor(preview);
        }
        return RunVariants.best(variants, state, openBookOf(state), inputs, resolvers);
    }

    /** The book the player has open, as the vocabulary the teleport model speaks. */
    static Spellbook openBookOf(PlayerState state) {
        Map<Integer, Integer> varbits = state == null ? null : state.getVarbits();
        Integer book = varbits == null ? null : varbits.get(CapabilitySources.SPELLBOOK_VARBIT);
        switch (book == null ? CapabilitySources.STANDARD_SPELLBOOK : book) {
            case CapabilitySources.LUNAR_SPELLBOOK:
                return Spellbook.LUNAR;
            case CapabilitySources.ARCEUUS_SPELLBOOK:
                return Spellbook.ARCEUUS;
            default:
                // Ancients included: the runs use none of its spells.
                return Spellbook.STANDARD;
        }
    }

    /**
     * The rows with their card notes: the tools to leave with the leprechaun at the last
     * stop that uses each, and, partway round, what the next stop needs that the bag lacks.
     *
     * @param rowOf where each arrival in {@code made} sits in {@code stops}
     */
    private static List<FarmingStopAdvice> withCardNotes(List<FarmingStopAdvice> stops,
            InventorySim.Plan bag, List<List<Integer>> made, List<Integer> rowOf,
            List<StopPlan> plans, List<List<Crop>> cropFor, List<FarmingCarryItem> carry,
            boolean underway, PlayerState state, CapabilityResolver resolver, FarmingInputs inputs) {
        List<FarmingStopAdvice> rows = new ArrayList<>(stops);
        for (Map.Entry<Integer, List<FarmingCarryItem>> leave : LeprechaunPlanner.leaveAt(made,
                plans, cropFor, carry, underway, state).entrySet()) {
            int row = rowOf.get(leave.getKey());
            rows.set(row, rows.get(row).toBuilder().leprechaun(LeprechaunPlanner.sentence(leave.getValue())).build());
        }
        if (underway && !made.isEmpty()) {
            List<StopPlan> here = new ArrayList<>();
            List<List<Crop>> plantedHere = new ArrayList<>();
            for (int index : made.get(0)) {
                here.add(plans.get(index));
                plantedHere.add(cropFor.get(index));
            }
            String missing = MissingItems.at(here, plantedHere, LeprechaunPlanner.hasLeprechaun(made.get(0), plans),
                    bankBefore(bag, here), state, resolver, inputs);
            if (!missing.isEmpty()) {
                int row = rowOf.get(0);
                rows.set(row, rows.get(row).toBuilder().warning(missing).build());
            }
        }
        return rows;
    }

    /**
     * The bank the warning on the next stop names: the bank row drawn before it, when the
     * bag simulation banks there, else the bank on the stop's own route, else none.
     */
    private static Bank bankBefore(InventorySim.Plan bag, List<StopPlan> here) {
        for (InventorySim.Leg leg : bag.getLegs()) {
            if (leg.getFrom() == 0 && leg.getBankAt() != null && leg.getBankPlace() != null) {
                return leg.getBankPlace();
            }
        }
        for (StopPlan plan : here) {
            if (plan.isVisit() && plan.getRoute() != null && plan.getRoute().getBank() != null) {
                return plan.getRoute().getBank();
            }
        }
        return null;
    }

    /**
     * The packing list's "now" half: the first stretch's lines, in the whole list's order so
     * the grid does not reorder when the split comes and goes.
     *
     * <p>A line the player owns nowhere stays in, whichever stretch needs it: no bank hands
     * it over, so no Later band would name it, and the grid is the only place it shows.
     *
     * @return empty when no later bank splits the trip
     */
    static List<FarmingCarryItem> nowHalf(List<FarmingCarryItem> firstStretch, List<FarmingCarryItem> carry) {
        if (firstStretch.isEmpty()) {
            return List.of();
        }
        Map<Integer, FarmingCarryItem> stretch = new LinkedHashMap<>();
        for (FarmingCarryItem line : firstStretch) {
            stretch.put(line.getItemId(), line);
        }
        List<FarmingCarryItem> now = new ArrayList<>(firstStretch.size());
        for (FarmingCarryItem line : carry) {
            FarmingCarryItem mine = stretch.remove(line.getItemId());
            if (mine != null) {
                now.add(mine);
            } else if (line.getAvailability() == FarmingCarryItem.Availability.MISSING) {
                now.add(line);
            }
        }
        // Anything the whole list does not name keeps its own order at the end.
        now.addAll(stretch.values());
        return now;
    }

    /**
     * Whether a visited stop teleports by the Explorer's ring. The planner offers such a rung
     * only while the ring has a teleport left today, so this also says one is left.
     */
    private static boolean teleportsByExplorersRing(List<StopPlan> plans) {
        for (StopPlan plan : plans) {
            if (!plan.isVisit() || plan.getNeeds() == null) {
                continue;
            }
            for (Capability need : plan.getNeeds()) {
                if (need.getTierFamily() == Capability.TierFamily.EXPLORERS_RING) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * The respawn point worth setting before this run, or empty when there is nothing
     * useful to say.
     *
     * <p>Silent when the run has no respawn town, when the player already respawns there,
     * when they cannot select the town (its unlock is not definitely held), when they
     * cannot cast Respawn Teleport, or while the setting is unread.
     */
    private static String respawnAction(FarmingRun run, PlayerState state, CapabilityResolver resolver) {
        String wanted = run.getRespawnTown();
        if (wanted == null || wanted.isEmpty()) {
            return "";
        }
        // Respawn Teleport (Arceuus, 34 Magic) is the only thing a respawn point helps.
        if (resolver.resolve(Capability.RESPAWN_TELEPORT, state).getState() == CapabilityState.LACK) {
            return "";
        }
        String selected = CapabilitySources.selectedRespawnTown(state);
        if (selected == null || selected.equals(wanted)) {
            return "";
        }
        // Suggest only on a definite yes; UNKNOWN (including a town with no unlock rule)
        // stays silent.
        if (CapabilitySources.canSelectRespawn(wanted, state) != CapabilityState.HAVE) {
            return "";
        }
        return "Set your respawn point to " + wanted + " to shorten this run. It is " + selected + " now.";
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.Crop;
import com.larryfarming.engine.farming.PatchPrediction;
import com.larryfarming.farming.detection.*;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.FarmingRunStatus;
import java.util.*;
import java.util.function.Function;
import lombok.*;

/**
 * Everything a farm run is planned against beyond the player's own state: the book the
 * panel previews, answers persisted per account, and what the patches were last seen doing.
 *
 * <p>{@link #getContractRun} differs from the rest: this planner produces it between
 * scheduling and planning, rather than receiving it from outside. It rides here so it need
 * not be threaded through {@code planRun}, {@code leaveStandingCrops} and
 * {@code adviseOnGroup} by hand.
 *
 * <p>Every field is optional. {@link #none()} plans for the open spellbook, assumes
 * nothing has been declared, and treats every patch and the house as unseen.
 *
 * <p>Copies go through a builder or a generated {@code with}, each of which names its field,
 * and both pass through the constructor's null normalisations. Several fields share a type,
 * so a positional call could transpose two of them and still compile.
 */
@Getter
@With
public final class FarmingInputs {

    private static final FarmingInputs NONE = builder().build();

    /** The book to plan teleports for, or null to follow the one the player is on. */
    @With(AccessLevel.NONE)
    private final Spellbook previewBook;
    @Getter(AccessLevel.NONE)
    @With(AccessLevel.NONE)
    private final Function<PatchRef, PatchPrediction> patches;
    /** Today's spent teleport allowances, or null when nothing has been counted. */
    @With(AccessLevel.NONE)
    private final DailyTeleportLedger ledger;
    /**
     * The second this advice is being built for, or zero when the caller did not say.
     *
     * <p>The farming layer takes the current second as an argument everywhere rather than
     * reading a clock.
     *
     * <p>Zero means "no clock was given", and readers must survive it. A finish time
     * compared against zero reads as not ready yet, which is the safe direction.
     */
    private final long nowEpochSec;
    /**
     * The crop the current contract asks for, decoded from varbit 7963, or null when no
     * contract is taken or its value is not one the plugin knows.
     *
     * <p>Without it the scheduler cannot identify the contract's patch and falls back to reading the whole
     * guild, which reports the contract ready whenever <em>anything</em> in the guild is.
     */
    private final Crop contractCrop;
    /**
     * The runs list's own verdict on the contract, or null before it has been reached.
     *
     * <p>The walkthrough's contract row derives from this verdict rather than judging the
     * contract again. The contract's stop names the guild herb patch only as a stand-in, so
     * patch-shaped rules answer the wrong question about it. One verdict keeps the runs list
     * and the walkthrough in agreement (the invariant {@code anythingToDoAt} documents).
     *
     * <p>Set after {@link RunScheduler#schedule} and before the trip is planned: the verdict
     * does not exist until the runs are scheduled, and the planning has to see it.
     */
    private final FarmingRunStatus contractRun;
    /**
     * Which crops the player is willing to have suggested. Never null: an absent value
     * reads as the default crop choices.
     */
    private final FarmingPreferences preferences;
    /**
     * What the player's own house was last seen to hold. Never null: a house never seen
     * reads as {@link HouseSight#unseen()}, whose every piece of furniture is absent.
     */
    private final HouseSight house;
    /** @see #hidesOfferedBanks */
    @Getter(AccessLevel.NONE)
    private final boolean offeredBanksHidden;
    /**
     * The item ids Larry asked for that have been seen in the bag since the trip was
     * packed, so a bank can say which of them to put back. Never null; empty when nothing
     * has been seen.
     */
    private final Set<Integer> packedThisTrip;
    /** The teleport the player has spent on the way to the next stop; see {@code TravelWatch}. */
    private final TravelTaken travelTaken;
    /**
     * The arrivals the plan on screen sends the player to, by constant name, in its order.
     * Once a trip is underway, the trip keeps that order. Never null.
     */
    private final List<String> ahead;
    /** The account's compost step, stock and thermostat. Never null: absent reads {@link CompostStock#NONE}. */
    private final CompostStock compost;
    /**
     * The volcanic ash this trip's Fertile Soil casts take, which the compost bins leave to
     * them. Zero until a plan of this snapshot has counted the casts.
     */
    private final int fertileAsh;
    /**
     * The compost bins' verdicts and the quiet picks, judged once by {@link #seeing} for
     * every reader of the copy it returns. Null before then. A generated {@code with} copy
     * carries this judgement along, but it was made for the original inputs, so the copy
     * works out its bins' verdicts and quiet picks afresh.
     */
    @Getter(AccessLevel.NONE)
    @With(AccessLevel.PRIVATE)
    private final Judgement bins;

    /**
     * What {@link #seeing} judged for one player: the bins' verdicts and the preset picks the
     * account can't plant yet. Owned by the one copy of the inputs that reads them.
     */
    @RequiredArgsConstructor
    private static final class Judgement {
        private final Map<CompostBins.Farm, CompostBins.Judged> verdicts;
        private final Set<String> quiet;
        private final PlayerState state;
        private FarmingInputs owner;
    }

    // On the constructor rather than the class, so every builder path goes through the
    // null normalisations below.
    @Builder(access = AccessLevel.PRIVATE)
    private FarmingInputs(Spellbook previewBook, Function<PatchRef, PatchPrediction> patches, DailyTeleportLedger ledger, long nowEpochSec,
            Crop contractCrop, FarmingRunStatus contractRun,
            FarmingPreferences preferences, HouseSight house, boolean offeredBanksHidden, Set<Integer> packedThisTrip, TravelTaken travelTaken,
            List<String> ahead, CompostStock compost, int fertileAsh, Judgement bins) {
        this.compost = compost != null ? compost : CompostStock.NONE;
        this.fertileAsh = fertileAsh;
        this.bins = bins;
        this.packedThisTrip = packedThisTrip != null ? Set.copyOf(packedThisTrip) : Set.of();
        this.travelTaken = travelTaken != null ? travelTaken : TravelTaken.NONE;
        this.previewBook = previewBook;
        this.patches = patches;
        this.ledger = ledger;
        this.nowEpochSec = nowEpochSec;
        this.contractCrop = contractCrop;
        this.contractRun = contractRun;
        // A caller with no preferences wants the default crops, not "plant nothing".
        this.preferences = preferences != null ? preferences : FarmingPreferences.defaults();
        this.house = house != null ? house : HouseSight.unseen();
        this.offeredBanksHidden = offeredBanksHidden;
        this.ahead = ahead != null ? List.copyOf(ahead) : List.of();
    }

    /** Nothing chosen, nothing seen. */
    public static FarmingInputs none() {
        return NONE;
    }

    /**
     * @param ledger      how much of today's rationed teleports is already spent, or null
     *                    to plan as though every allowance were untouched
     * @param nowEpochSec which day the ledger's counts should be read against
     */
    public static FarmingInputs of(Spellbook previewBook, Function<PatchRef, PatchPrediction> patches, DailyTeleportLedger ledger,
            long nowEpochSec) {
        return builder().previewBook(previewBook).patches(patches).ledger(ledger).nowEpochSec(nowEpochSec).build();
    }

    /**
     * A route resolver for this book over these inputs: today's ledger, the clock, the
     * patches and the house as last seen, the player's travel switches, and what they
     * declare their house holds. Building one is the expensive half of scoring a run, so
     * callers share it where they can.
     */
    public CapabilityResolver resolverOn(Spellbook book) {
        return new CapabilityResolver(book, ledger, nowEpochSec, this::patchAt, house).switchingOff(preferences.travelOff())
                .declaringHouse(preferences.houseDeclared()).travelling(travelTaken);
    }

    /**
     * Whether the panel leaves out the banks the route only passes. Their rows are not
     * drawn, so nothing may be fetched at them. Defaults to false: every bank is shown.
     */
    public boolean hidesOfferedBanks() {
        return offeredBanksHidden;
    }

    /**
     * Whether the contract is knowingly waiting on a crop to finish growing.
     *
     * <p>Asked negatively on purpose. "Is the contract due?" answers false for a contract
     * nobody has read yet, and would drop the Farming Guild from the run of every player
     * whose varbits have not arrived. Only PENDING says a crop is growing and when it will
     * be ready, so only PENDING is a reason not to go.
     */
    public boolean contractIsStillGrowing() {
        return contractRun != null && RunStatus.PENDING.name().equals(contractRun.getStatus());
    }

    /** The contract's one-line instruction, such as "hand the contract to Guildmaster Jane", or "". */
    public String contractDetail() {
        String detail = contractRun == null ? null : contractRun.getDetail();
        return detail == null ? "" : detail;
    }

    /**
     * Whether the contract's instruction is one its own patch will also be saying.
     *
     * @see FarmingRunStatus#isAboutThePatch()
     */
    public boolean contractIsAboutThePatch() {
        return contractRun != null && contractRun.isAboutThePatch();
    }

    /** When the contract's crop finishes, or 0 when there is nothing to count down to. */
    public long contractReadyAtEpochSec() {
        return contractRun == null ? 0L : contractRun.getReadyAtEpochSec();
    }

    /**
     * These inputs with the sites this account is seen unable to reach marked on the
     * preferences, so a run whose every reachable site is dropped switches off, and the
     * preset's picks the account can't plant marked quiet. Each entry point asks this of the
     * state it plans, so the marks follow the account: a site that opens up holds its run
     * open again, and a pick starts planting at its level or with its seed in stock. Sites
     * are read only while some site is dropped. The compost bins are judged here too, and
     * every reader of the copy reads those verdicts. A copy this returned comes back as it
     * is when asked again for the same player.
     */
    FarmingInputs seeing(PlayerState state) {
        if (isSeenFor(state)) {
            return this;
        }
        Set<String> shut = preferences.sitesOff().isEmpty() ? Set.of() : RunSettings.shutSites(state, this::patchAt);
        Set<String> quiet = Set.copyOf(RunSettings.quietPicks(preferences, state, this::patchAt));
        // Neither the bins' verdicts nor the quiet picks read the marks set below, so the
        // verdicts judged here hold for the marked copy, and seeing that copy again for the
        // same player changes nothing.
        Map<CompostBins.Farm, CompostBins.Judged> judged = CompostBins.verdicts(this, state, quiet);
        Set<String> held = new HashSet<>(quiet);
        held.addAll(CompostBins.holding(this, judged));
        FarmingPreferences marked = preferences.withSitesShut(shut).withPicksQuiet(held);
        Judgement judgement = new Judgement(judged, quiet, state);
        FarmingInputs seen = (marked == preferences ? this : withPreferences(marked)).withBins(judgement);
        judgement.owner = seen;
        return seen;
    }

    /** Whether {@link #seeing} returned this copy for this player. */
    private boolean isSeenFor(PlayerState state) {
        return bins != null && bins.owner == this && bins.state == state;
    }

    /**
     * The compost bins' verdicts: those {@link #seeing} judged for this copy and player, or
     * judged now for any other.
     */
    Map<CompostBins.Farm, CompostBins.Judged> bins(PlayerState state) {
        return isSeenFor(state) ? bins.verdicts : CompostBins.verdicts(this, state);
    }

    /**
     * The preset picks the account can't plant yet ({@link RunSettings#quietPicks}): those
     * {@link #seeing} read for this copy and player, or read now for any other.
     */
    Set<String> quietPicks(PlayerState state) {
        return isSeenFor(state) ? bins.quiet : RunSettings.quietPicks(preferences, state, this::patchAt);
    }

    /**
     * What this patch was last seen holding, or null when it has never been seen.
     *
     * <p>Null is the common case and not a failure: patch varbits only read true while
     * the player is in the region, so a patch is unknown until they have been there since
     * the plugin was installed. Callers must treat unknown as "no reason to change the
     * plan" rather than as an empty patch.
     */
    public PatchPrediction patchAt(PatchRef patch) {
        return patches != null && patch != null ? patches.apply(patch) : null;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.catalogue.Teleports;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.*;
import java.util.List;
import java.util.Map;

/**
 * Whether the player treats their patches with the Lunar Fertile Soil spell instead of
 * carrying ultracompost, and what that costs.
 *
 * <p>The spell alone gives supercompost, worse than the ultracompost the bucket holds. A
 * player who has read the Ash covered tome casts it with two volcanic ash in the bag to get
 * ultracompost instead. Nothing in the game state says whether the tome has been read, so
 * the player says so with the setting, and Larry plans the spell only then. It is cast on
 * the underwater seaweed patches too.
 *
 * <p>Not modelled: the spell's rune stacks taking bag slots for a player without a rune
 * pouch, as for Cure Plant.
 */
final class FertileSoil {

    /** The Magic level Fertile Soil needs. */
    static final int MAGIC_LEVEL = 83;

    /** Volcanic ash each cast consumes to give ultracompost. */
    static final int ASH_PER_CAST = 2;

    private FertileSoil() {
    }

    /**
     * Whether the trip casts the spell rather than carrying compost: the player has asked
     * for it, has the real Magic level, and walks the trip on the Lunar book. A trip planned
     * for no particular book reads the book the player has open.
     *
     * @param tripBook the book the trip is planned for
     */
    static boolean inUse(FarmingPreferences prefs, PlayerState state, Spellbook tripBook) {
        if (prefs == null || !prefs.compostsWithFertileSoil() || state == null || state.getSkillLevel(Skill.MAGIC) < MAGIC_LEVEL) {
            return false;
        }
        if (tripBook != Spellbook.ANY) {
            return tripBook == Spellbook.LUNAR;
        }
        return FarmingAdviceBuilder.openBookOf(state) == Spellbook.LUNAR;
    }

    /**
     * Whether the player could cast the spell after switching to the Lunar book: 83 Magic
     * and Lunar Diplomacy done. The setting shows only then, since it does nothing otherwise.
     */
    static boolean couldCast(PlayerState state) {
        return state != null && state.getSkillLevel(Skill.MAGIC) >= MAGIC_LEVEL
                && state.getQuests().get("Lunar Diplomacy") == QuestStatus.COMPLETED;
    }

    /**
     * One cast for every patch planted at a stop that composts. So the limpwurt patch, which
     * takes no compost, costs nothing.
     * Zero when {@code cropFor} is null, as it is for a bag planned without the patches.
     *
     * @param cropFor what each stop is planting, index-aligned with {@code plans}
     */
    static int castsFor(List<StopPlan> plans, List<List<Crop>> cropFor) {
        if (cropFor == null) {
            return 0;
        }
        int casts = 0;
        for (int i = 0; i < plans.size() && i < cropFor.size(); i++) {
            if (composts(plans.get(i))) {
                casts += cropFor.get(i).size();
            }
        }
        return casts;
    }

    /** Whether the spell would treat a patch at any of these stops, so ash is carried. */
    static boolean treatsAny(List<StopPlan> plans) {
        return plans.stream().anyMatch(plan -> composts(plan) && plan.getStop().isPlanting());
    }

    /**
     * Whether this stop is visited and composts its patch. A skipped or unreachable stop
     * does nothing there, so it takes neither compost nor a cast.
     */
    static boolean composts(StopPlan plan) {
        return plan.isVisit() && plan.getStop().getActions().contains(RunStop.StopAction.COMPOST);
    }

    /** The runes one cast takes. */
    static Map<Rune, Integer> runesPerCast() {
        return Teleports.runesFor(Capability.FERTILE_SOIL);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import java.util.ArrayList;
import java.util.List;

/**
 * What goes in a stop with one default crop: that crop or another crop of the same
 * patch, whichever of them the player has switched on.
 *
 * <p>Every reader of a fixed-crop stop's crop asks here, so the walkthrough, the bag, the
 * runs list and the switches agree on one answer.
 */
final class FixedCrops {

    private FixedCrops() {
    }

    /**
     * The stop's crops the player has ticked, best first, or a picked stop's pick. Empty
     * silences the stop.
     */
    static List<Crop> ticked(RunStop stop, FarmingPreferences prefs) {
        PatchPick pick = FarmingCatalogue.pickOf(stop);
        if (pick != null) {
            Crop crop = prefs.pickAt(pick.getSite());
            return crop == null ? List.of() : List.of(crop);
        }
        List<Crop> ticked = new ArrayList<>();
        for (Crop crop : FarmingCatalogue.cropChoices(stop)) {
            if (prefs.allows(crop)) {
                ticked.add(crop);
            }
        }
        return ticked;
    }

    /**
     * The crop this stop plants: the highest-level ticked crop the player can grow and is not
     * known to be out of, falling to the next ticked crop as each runs out.
     *
     * <p>With every growable crop out, the best growable one, so the walkthrough's seed skip
     * names the seed to fetch. With none growable, the lowest-level ticked crop, so its level
     * skip names the level to reach (see {@link #belowLevel}). Null only for a stop with
     * nothing ticked, which the planting gate silences.
     */
    static Crop cropFor(RunStop stop, FarmingPreferences prefs, PlayerState state) {
        List<Crop> ticked = ticked(stop, prefs);
        if (ticked.isEmpty()) {
            return null;
        }
        Crop growable = null;
        for (Crop crop : ticked) {
            CropData data = CropData.forCrop(crop);
            // An unread Farming level grows anything, so it never moves the choice.
            if (data == null || belowLevel(state, data)) {
                continue;
            }
            if (!SeedSelector.definitelyOutOf(crop, state, data.getSeedsPerPatch())) {
                return crop;
            }
            if (growable == null) {
                growable = crop;
            }
        }
        return growable != null ? growable : ticked.get(ticked.size() - 1);
    }

    /**
     * Whether this crop is one the stop may grow, ticked or not. A crop the player has
     * since unticked is still theirs while it stands in the patch.
     */
    static boolean grows(RunStop stop, Crop crop) {
        return crop != null && FarmingCatalogue.cropChoices(stop).contains(crop);
    }

    /**
     * Whether this crop stands in the stop's patch once grown, wanting nothing while it
     * lives: the stop's own standing crop, or a white lily picked for its patch, which guards
     * the allotments beside it. A lily left from an earlier pick is harvested for the new one.
     */
    static boolean stands(RunStop stop, Crop crop, FarmingPreferences prefs) {
        return stop.isPicked() ? crop == Crop.WHITE_LILY && ticked(stop, prefs).contains(crop) : stop.isStandingCrop();
    }

    /**
     * Whether the player's Farming level is known and short of this crop's. An unread level
     * is never short, so it never skips a stop.
     */
    static boolean belowLevel(PlayerState state, CropData data) {
        return RunSettings.farmingLevel(state) < data.getFarmingLevel();
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.*;
import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.farming.detection.CapabilityResolver;
import com.larryfarming.farming.detection.CapabilityState;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.FarmingCarryItem;
import java.util.*;
import net.runelite.api.gameval.ItemID;

/**
 * Reads a planned trip and a player, and says what each arrival wants out of the bag.
 *
 * <p>{@link InventorySim} is arithmetic that knows nothing about the catalogue or the
 * player. Everything that looks up a crop, reads a patch or checks what the player owns
 * lives here instead.
 *
 * <p>The three rules that decide most of the answer: seeds stack so a crop costs one
 * slot however many patches take it, saplings do not stack so they cost one each, and a
 * farmer accepts a noted payment so protection costs one slot per kind of patch paid for.
 */
final class InventoryDemands {

    private InventoryDemands() {
    }

    /**
     * What one arrival wants, for every visit the trip is actually making.
     *
     * <p>One demand per visit, in the order given, so the indices in an
     * {@link InventorySim.Leg} point straight into the caller's list.
     *
     * <p>Relies on three {@link Itinerary.Trip} invariants without guarding them: a visit is
     * never empty ({@code groupByArrival} opens each with its first index), every stop in a
     * visit shares one arrival, and {@code cropFor} is as long as {@code plans}
     * ({@code Itinerary.Planned} enforces it).
     *
     * @param visits   the stop indices at each arrival, in circuit order, filtered to the
     *                 arrivals the player is actually reaching. An unreached arrival takes
     *                 nothing from the bag, but left in the list it could be chosen as the
     *                 bank stop
     * @param plans    every planned stop, indexed by the numbers in {@code visits}
     * @param cropFor  what each stop is planting, index-aligned with {@code plans}
     * @param state    the player, whose owned payments decide which farmers are paid
     * @param resolver decides the travel items, as it does for the packing list
     */
    static List<InventorySim.Demand> forTrip(List<List<Integer>> visits, List<StopPlan> plans,
            List<List<Crop>> cropFor, FarmingInputs inputs, PlayerState state, CapabilityResolver resolver) {
        List<InventorySim.Demand> demands = new ArrayList<>(visits.size());
        boolean pouched = ItemCounts.ownsAny(state, RunePouch.POUCH_ITEM_IDS);
        // The packing list's noted empty buckets, which come out at the first bank.
        boolean bringsBuckets = CarryPlanner.bringsBuckets(CompostBins.over(plans, inputs, state), state);
        for (List<Integer> visit : visits) {
            List<StopPlan> here = StopPlan.pick(plans, visit);
            // The packing list's own lines, so the bag charges what it is told to carry.
            // Kept to the end like any tool, coins included: the stack may outlast the fee,
            // and charging a slot too many costs at most a spare bank stop.
            Set<Integer> tools = CarryPlanner.treeToolsFor(here, StopPlan.pick(cropFor, visit), state, inputs);
            Set<Integer> travel = new HashSet<>();
            Set<Integer> spent = new HashSet<>();
            // With no player read there is nothing to price a route's items against.
            List<FarmingCarryItem> travelLines = state == null ? List.of() : CarryPlanner.travelFor(here, state, resolver);
            for (FarmingCarryItem line : travelLines) {
                if (!CarryPlanner.takesAbagSlot(line, pouched)) {
                    continue;
                }
                travel.add(line.getItemId());
                if (CarryPlanner.spentOnTheWay(line)) {
                    spent.add(line.getItemId());
                }
            }
            // The noted buckets ride like a tablet: in the bag on the way to the first bin that
            // wants them, and stored there with the leprechaun, whom every later bin draws on.
            if (bringsBuckets && CompostBins.wantsBucketsAt(visit, plans, inputs, state)) {
                travel.add(ItemID.Cert.BUCKET_EMPTY);
                spent.add(ItemID.Cert.BUCKET_EMPTY);
                bringsBuckets = false;
            }
            Arrival at = null;
            Set<Crop> seeds = EnumSet.noneOf(Crop.class);
            Set<Crop> produce = EnumSet.noneOf(Crop.class);
            Set<PatchType> protections = EnumSet.noneOf(PatchType.class);
            int saplings = 0;
            int bankTiles = TravelOption.UNMEASURED;
            boolean bankUpstairs = false;
            Bank bank = null;
            for (int index : visit) {
                StopPlan plan = plans.get(index);
                if (!plan.isVisit()) {
                    // A skipped stop takes nothing out of the bag. If every stop is skipped,
                    // the arrival falls back to the visit's first stop below.
                    continue;
                }
                RunStop stop = plan.getStop();
                at = stop.getArrival();
                saplings += sort(cropFor.get(index), seeds);
                collectProduce(stop, inputs, produce);
                collectProtection(stop, cropFor.get(index).size(), state, protections);
                // The cheapest bank the player passes while here. A visit works every patch
                // at its arrival, so a bank on the way to any one of them serves the visit.
                // Unmeasured rungs are skipped, which can only overstate the cost.
                // Compared on the cost BankProximity grades, so an upstairs bank pays for its
                // staircase and the bank chosen is judged on the number the player is told.
                TravelOption route = plan.getRoute();
                if (route != null && route.hasBankFigure() && (bankTiles == TravelOption.UNMEASURED
                        || Arrival.BankProximity.costInTiles(route.getBankDetour(), route.isBankUpstairs())
                                < Arrival.BankProximity.costInTiles(bankTiles, bankUpstairs))) {
                    bankTiles = route.getBankDetour();
                    bankUpstairs = route.isBankUpstairs();
                    // Always from the same rung as the figure: different rungs at one visit
                    // can reach different bank buildings.
                    bank = route.getBank();
                }
            }
            if (at == null) {
                at = plans.get(visit.get(0)).getStop().getArrival();
            }
            demands.add(new InventorySim.Demand(at, seeds, saplings, produce, protections,
                    bankTiles, bankUpstairs, bank, tools, travel, spent));
        }
        return demands;
    }

    /**
     * Splits what is being planted into stacking seeds (added to {@code seeds}) and
     * non-stacking saplings, and returns the sapling count. A sapling is a plant pot, and
     * two pots never share a slot.
     */
    private static int sort(List<Crop> planting, Set<Crop> seeds) {
        int saplings = 0;
        for (Crop crop : planting) {
            CropData data = CropData.forCrop(crop);
            if (data != null && data.isSaplingPlanted()) {
                saplings++;
            } else {
                seeds.add(crop);
            }
        }
        return saplings;
    }

    /**
     * What is picked here, one entry per kind.
     *
     * <p>Asked of {@link PatchWork}, so the bag and the walkthrough row agree about what is
     * being harvested.
     *
     * <p>Logs must not be added. The tool leprechaun will not note them, so logs go in a
     * log basket (a fixture) or on the floor, and never take a produce slot.
     */
    private static void collectProduce(RunStop stop, FarmingInputs inputs, Set<Crop> produce) {
        for (PatchRef ref : stop.getPatches()) {
            PatchPrediction seen = inputs.patchAt(ref);
            PatchWork.Act act = PatchWork.at(seen, stop, inputs.getPreferences(), inputs.getNowEpochSec());
            // A check where the stop also picks fills the plant at once: a bush, cactus or
            // fruit tree bears its full load the moment it is checked.
            boolean picked = act == PatchWork.Act.HARVEST || (act == PatchWork.Act.CHECK
                            && stop.getActions().contains(RunStop.StopAction.HARVEST));
            if (!picked) {
                continue;
            }
            if (seen.getCrop() != null && seen.getCrop().isProduce()) {
                produce.add(seen.getCrop());
            }
        }
    }

    /**
     * Which kinds of patch are paid for here.
     *
     * <p>By patch type rather than by patch, because a farmer takes a noted payment: eight
     * allotments across the trip is one slot of noted produce, not eight.
     *
     * <p>Only where something is planted and the player owns a fee for it (see
     * {@link Protection}), since the payment is not worth gathering for the trip.
     *
     * @param planting how many of the stop's patches are planted this visit
     */
    private static void collectProtection(RunStop stop, int planting, PlayerState state, Set<PatchType> protections) {
        if (Protection.paymentAt(stop, planting, state) == null) {
            return;
        }
        for (PatchRef ref : stop.getPatches()) {
            PatchType type = ref.type();
            if (type != null) {
                protections.add(type);
            }
        }
    }

    /**
     * What this player carries the whole way.
     *
     * <p>The spade is always counted: no run happens without one.
     *
     * <p><b>Owned, not held.</b> The trip starts at a bank, so an item in the bank will be
     * carried. {@link CarryPlanner} draws the same line: {@code countCarried} decides whether
     * a withdrawal is needed, {@code countOwned} decides whether the item comes along.
     *
     * <p>Over-counting costs an unneeded bank stop; under-counting leaves the player unable
     * to plant at the last patch. Before the bank has been seen every count reads zero, so
     * fixtures appear once the player opens a bank. A basket in the bag beside a cape whose
     * teleport the route uses is charged as well as the cape, though the player wears one
     * of the two: the same safe over-count as any worn travel item.
     *
     * <p>The bucket and rune pouch cost a slot <em>because</em> the player owns them: each
     * replaces several slots (compost, loose runes) on a run that uses it. The log basket
     * costs one only on a trip that cuts logs, and not when worn in the cape slot.
     *
     * <p>The axe and the travel items are not fixtures. {@link #forTrip} puts them on the
     * arrivals that use them, so each is charged only from the leg that first needs it.
     */
    static Set<InventorySim.Fixture> fixturesFor(PlayerState state, CapabilityResolver resolver, List<StopPlan> plans, FarmingInputs inputs,
            boolean basketInTheBag) {
        Set<InventorySim.Fixture> carried = EnumSet.of(InventorySim.Fixture.SPADE);
        // Barbarian Training allows bare-handed planting. Anything short of a definite HAVE
        // carries the dibber: an unknown costs a slot here, never a skipped patch.
        if (resolver.resolve(Capability.BARE_HAND_PLANTING, state).getState() != CapabilityState.HAVE) {
            carried.add(InventorySim.Fixture.SEED_DIBBER);
        }
        if (basketInTheBag) {
            carried.add(InventorySim.Fixture.LOG_BASKET);
        }
        // CarryPlanner.packsBucket decides the bucket for the packing list too.
        boolean fertile = FertileSoil.inUse(inputs.getPreferences(), state, resolver.getBook());
        CompostBins.Needs bins = CompostBins.over(plans, inputs, state);
        if (CarryPlanner.packsBucket(plans, fertile, bins, state)) {
            carried.add(InventorySim.Fixture.BOTTOMLESS_BUCKET);
        }
        if (ItemCounts.ownsAny(state, RunePouch.POUCH_ITEM_IDS)) {
            carried.add(InventorySim.Fixture.RUNE_POUCH);
        }
        if (ItemCounts.ownsAny(state, SeedBox.BOX_ITEM_IDS)) {
            carried.add(InventorySim.Fixture.SEED_BOX);
        }
        // The ash and the potion are errands, not owned savings. Each is charged on the same
        // condition CarryPlanner uses to list it, and one ash stack serves the bins and
        // Fertile Soil alike.
        if (bins.getAsh() > 0 || fertile && FertileSoil.treatsAny(plans)) {
            carried.add(InventorySim.Fixture.VOLCANIC_ASH);
        }
        if (bins.getDoses() > 0) {
            carried.add(InventorySim.Fixture.COMPOST_POTION);
        }
        // No underwater breathing gear on purpose: it only works worn, so it costs
        // equipment slots, not inventory. See CarryPlanner.addDivingGear.
        return carried;
    }

}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.SeedBox;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.engine.farming.PatchType;
import com.larryfarming.farming.model.*;
import java.util.*;
import lombok.*;

/**
 * How full the bag gets as the trip is walked, and therefore where it has to break at a
 * bank.
 *
 * <p>Seeds stack, so a crop costs one slot of seed however many patches take it. Produce
 * does not stack, but the tool leprechaun notes it for free, so a harvest costs one slot
 * per <em>kind</em> picked. Saplings do not stack, and each leaves an empty pot behind:
 * they create nearly all the pressure. Every figure here is a game fact checked against the
 * game or the wiki.
 *
 * <p>Pure arithmetic over a list of {@link Demand}s, with no catalogue and no player state.
 */
public final class InventorySim {

    private InventorySim() {
    }

    /** Inventory size. */
    public static final int SLOTS = 28;

    /**
     * How far off the route a bank may be and still be worth <em>offering</em>.
     *
     * <p>Set in the middle of the widest gap in the walked detour figures, so no bank sits
     * close to the line. It keeps detours such as the Fishing Guild and excludes the Ortus
     * Farm quetzal rungs, whose bank chest lies back south-west of the landing.
     */
    public static final int OFFERED_WITHIN_TILES = 75;

    /**
     * Slots kept free for produce the player has not picked yet.
     *
     * <p>A harvest is charged one slot per <em>kind</em>, which is the bag after a trip to
     * the leprechaun, not while picking. Loose produce piles up until the player notes it,
     * so free slots set the batch size between leprechaun trips.
     *
     * <p>An ultracompost herb patch yields a guaranteed minimum of six herbs before bonuses. Ten clears that with room
     * for bonus lives and leaves eighteen working slots. Yield is random per life, so a flat
     * floor replaces a per-patch model. The advisory bank rows let the player adjust in
     * context, so this is not configurable.
     */
    public static final int HARVEST_HEADROOM = 10;

    /**
     * The most a leg may be planned to reach before a bank stop is placed.
     *
     * <p>This decides where the trip breaks; {@link #SLOTS} still decides whether an arrival
     * is possible at all. An arrival needing more than this but no more than {@code SLOTS}
     * is tight, not impossible.
     */
    public static final int WORKING_SLOTS = SLOTS - HARVEST_HEADROOM;

    /** Something carried the whole way, costing one slot from the first arrival to the last. */
    public enum Fixture {
        /** Carried every run. Nothing else digs a patch up. */
        SPADE,
        /** Left behind once Barbarian Training (15 Farming) allows bare-handed planting. */
        SEED_DIBBER,
        /**
         * Twenty-eight logs in one slot. The leprechaun will not note logs, so without a
         * basket they are dropped.
         */
        LOG_BASKET,
        /**
         * Ten thousand uses in one slot. Without it the compost is drawn from the
         * leprechaun at each farm and the bucket handed straight back, which costs a slot
         * only while standing there.
         */
        BOTTOMLESS_BUCKET,
        /**
         * Three rune types in one slot (four for the divine pouch, which costs the same).
         * Runes already stack, so the pouch saves two slots net.
         */
        RUNE_POUCH,
        /**
         * Six seed <em>kinds</em> in one slot, any quantity of each. A seventh kind costs a
         * slot like any loose seed. Holds seeds only, not saplings.
         */
        SEED_BOX,
        /**
         * Volcanic ash for Fertile Soil cast to give ultracompost. Ash stacks, so one slot
         * covers any amount.
         */
        VOLCANIC_ASH,
        /** Compost potion to lift a finished bin a tier. One slot holds up to four doses. */
        COMPOST_POTION
    }

    /**
     * What one arrival wants out of the bag.
     *
     * <p>Sets rather than counts, because each costs one slot per <em>kind</em>: seeds
     * stack, noted produce stacks, and a farmer takes a noted payment.
     */
    @Getter
    public static final class Demand {

        private final Arrival at;
        /** Distinct seed types planted here. One slot each however many patches take one. */
        private final Set<Crop> seeds;
        /** Saplings carried in. One slot each, since saplings do not stack. */
        private final int saplings;
        /** Distinct kinds of thing picked here. One slot each, once noted. */
        private final Set<Crop> produce;
        /**
         * Patch types paid for here. One slot per kind of payment, since a farmer takes a
         * noted one. Never herbs or flowers, which no farmer will protect.
         */
        private final Set<PatchType> protections;
        @Getter(AccessLevel.NONE)
        private final int bankTiles;
        @Getter(AccessLevel.NONE)
        private final boolean bankUpstairs;
        @Getter(AccessLevel.NONE)
        private final Bank bank;
        /**
         * Items used here, by item id. One slot each, from the bank of the leg that first
         * needs one to the end of the trip, since nothing is deposited.
         */
        private final Set<Integer> tools;
        /**
         * Items that bring the player here, by item id. Charged like {@link #getTools()},
         * but from the arrival before: the way to a bank has to be in the bag before the
         * bank is reached.
         */
        private final Set<Integer> travel;
        /** Those of {@link #getTravel()} used up on the way here. */
        private final Set<Integer> spentOnTheWay;

        /**
         * @param bankTiles     extra tiles the cheapest bank stop here costs on the route the
         *                      player is actually taking, or {@link TravelOption#UNMEASURED}
         * @param bankUpstairs  whether reaching that bank changes floor
         * @param bank          which bank those tiles were walked to, or null when unmeasured
         * @param tools        items used here, such as the axe, by item id
         * @param travel        items that bring the player here, such as the ectophial or a
         *                      stack of tablets, by item id
         * @param spentOnTheWay those of {@code travel} used up getting here, such as a
         *                      tablet. The stack leaves the bag at the last arrival that
         *                      spends one
         */
        public Demand(Arrival at, Set<Crop> seeds, int saplings, Set<Crop> produce,
                Set<PatchType> protections, int bankTiles, boolean bankUpstairs, Bank bank,
                Set<Integer> tools, Set<Integer> travel, Set<Integer> spentOnTheWay) {
            this.tools = copyOf(tools);
            this.travel = copyOf(travel);
            this.spentOnTheWay = copyOf(spentOnTheWay);
            if (!this.travel.containsAll(this.spentOnTheWay)) {
                throw new IllegalArgumentException("only a travel item is spent on the way");
            }
            if (at == null) {
                throw new IllegalArgumentException("a demand belongs to an arrival");
            }
            if (saplings < 0) {
                throw new IllegalArgumentException("saplings cannot be negative");
            }
            this.at = at;
            this.seeds = copyOf(seeds);
            this.saplings = saplings;
            this.produce = copyOf(produce);
            this.protections = copyOf(protections);
            this.bankTiles = bankTiles;
            this.bankUpstairs = bankUpstairs;
            this.bank = bank;
        }

        /**
         * An immutable copy, not a view: {@link InventorySim#plan} reads each demand many
         * times, so a caller mutating its set would change the answer mid-plan.
         * {@code Set.copyOf} also rejects null members up front.
         */
        private static <T> Set<T> copyOf(Set<T> set) {
            return set == null ? Collections.emptySet() : Set.copyOf(set);
        }

        /**
         * What a bank costs here, on the route this player is taking rather than on average.
         *
         * <p>Prefers the measured figure and falls back to the {@link Arrival}'s constant for
         * an unmeasured rung.
         */
        public Arrival.BankProximity getBank() {
            return bankTiles == TravelOption.UNMEASURED ? at.getBank() : Arrival.BankProximity.of(bankTiles, bankUpstairs);
        }

        /**
         * Whether that grade came from walking this player's own route.
         *
         * <p>Deciding <em>where</em> to break may use the arrival's constant. Telling the
         * player about the bank may not: the constant grades the whole arrival, not this
         * route, so only a measured figure is shown.
         */
        public boolean isBankMeasured() {
            return bankTiles != TravelOption.UNMEASURED;
        }

        /**
         * What a bank stop here costs in walked tiles, the floor change included, or
         * {@link TravelOption#UNMEASURED} where the rung has no figure.
         *
         * <p>Offering a bank needs the figure, not the grade: {@link Arrival.BankProximity#FAR}
         * spans banks on the way and banks that are an errand. Choosing where the trip
         * breaks can work in grades.
         */
        public int bankCostInTiles() {
            return bankTiles == TravelOption.UNMEASURED ? TravelOption.UNMEASURED : Arrival.BankProximity.costInTiles(bankTiles, bankUpstairs);
        }

        /**
         * Which bank the cheapest walked rung here goes to, or null when none was walked.
         *
         * <p>Non-null only when {@link #isBankMeasured()}: the name comes off the same rung
         * as the figure.
         */
        public Bank getBankPlace() {
            // Gated here so the invariant holds for every constructor.
            return isBankMeasured() ? bank : null;
        }
    }

    /**
     * A bank the player passes on a leg without being told to stop at it.
     *
     * <p>Shown as an offer so the player can overrule the plan: they know how much they are
     * about to pick, and the sim only knows a flat reserve.
     */
    @Getter
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    public static final class Opportunity {

        /** Index of the arrival, into the list handed to {@link #plan}. */
        private final int index;
        private final Arrival at;
        /**
         * What the detour costs on the rung this player took, or null when it has no figure
         * (see {@link Demand#isBankMeasured()}).
         */
        private final Arrival.BankProximity cost;
        /**
         * Which bank this is, or null when the rung that reaches it has no figure.
         *
         * <p>Not {@code getBank()}: {@link Demand#getBank()} returns a grade, not a place.
         */
        private final Bank bankPlace;

        /**
         * Whether the player passes this bank between the landing and the patch, and so
         * banks on the way in, before the patches here are worked.
         *
         * <p>True wherever the rung carries a figure, because the figure is walked from the
         * landing to the bank and on to the patch. A bank graded only by its arrival could
         * lie on either side of the patch, so it is offered once the patches are worked.
         */
        public boolean isOnTheWayIn() {
            return cost != null;
        }
    }

    /**
     * One unbroken leg of the trip: what the player sets out from a bank carrying, and how
     * far they get before they need another.
     */
    @Getter
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    public static final class Leg {

        /**
         * Index of the first demand on this leg, into the list handed to {@link #plan}. The
         * leg runs to the arrival before the next leg's first, or to the trip's end.
         */
        private final int from;
        /**
         * Where the player banks before setting out, or null when nobody banks them onto
         * this leg.
         *
         * <p>Null on the first leg because the trip starts at a bank. Null on a later leg
         * means the previous leg ran out of room with no bank in reach, and
         * {@link #getOverflow()} says why.
         */
        private final Arrival bankAt;
        /**
         * What that bank costs to reach on the route the player is taking, or null when
         * nobody banks them onto this leg.
         *
         * <p>Stored rather than looked up from {@link #getBankAt()}: the same place can be a
         * free stop off one rung and a long detour off another.
         */
        private final Arrival.BankProximity bankCost;
        /**
         * Which bank that is, or null when the rung this player took to it has no figure.
         *
         * <p>Null whenever {@link #getBankCost()} is null: both come off an unmeasured rung.
         */
        private final Bank bankPlace;
        /**
         * Whether the trip stopped here sooner than the bag made it.
         *
         * <p>True when the split was moved back to reach a cheaper bank than the last one
         * the bag would have allowed. The player is told so that an early bank stop does not
         * look like a mistake.
         */
        private final boolean bankBroughtForward;
        /** The fullest the bag gets on this leg, which is what had to fit. */
        private final int peakSlots;
        /**
         * Why this leg does not fit, or null when it does.
         *
         * <p>{@code getBankAt() == null && getFrom() > 0} implies this is non-null.
         */
        private final String overflow;
        /**
         * Whether the shortfall only eats into the room kept for the harvest, with every
         * item still fitting. False when nothing overflows.
         */
        private final boolean harvestRoomOnly;
        /**
         * Banks on this leg the trip is not stopping at, in the order they are passed.
         *
         * <p>Empty rather than null when there are none. Excludes the arrival this leg
         * starts from, which is where {@link #getBankAt()} already sends them.
         */
        private final List<Opportunity> passableBanks;
    }

    /**
     * Where the trip breaks, and where it could not be made to.
     *
     * <p>An overflowing leg with no bank in reach is reported on that leg, not silently
     * split, so the player can shed something or plan a second trip.
     */
    @Getter
    public static final class Plan {

        private final List<Leg> legs;

        Plan(List<Leg> legs) {
            this.legs = List.copyOf(legs);
        }
    }

    /**
     * Breaks the trip into legs that fit, banking as late as each leg allows.
     *
     * <p>Banking late avoids detours the player does not need. The trip starts at a bank,
     * so the first leg runs as far as it can.
     *
     * @param demands  every arrival being visited, in the order the circuit visits them
     * @param fixtures what the player carries the whole way
     */
    public static Plan plan(List<Demand> demands, Set<Fixture> fixtures) {
        List<Demand> stops = demands == null ? Collections.emptyList() : demands;
        int carried = fixtures == null ? 0 : fixtures.size();
        // The seed box is charged only on a trip that plants seeds, the same condition
        // CarryPlanner uses to list it.
        boolean seedsBoxed = fixtures != null && fixtures.contains(Fixture.SEED_BOX) && plantsSeeds(stops);
        if (fixtures != null && fixtures.contains(Fixture.SEED_BOX) && !seedsBoxed) {
            carried--;
        }

        List<Leg> legs = new ArrayList<>();
        int from = 0;
        Arrival bankAt = null;
        // These describe the next leg to be built: the iteration that chooses a cut sets
        // them one turn before that leg exists. A shortfall belongs to the leg the player
        // carries on into over-full.
        Arrival.BankProximity bankCost = null;
        Bank bankPlace = null;
        boolean broughtForward = false;
        String unbanked = null;
        boolean harvestRoomOnly = false;
        while (from < stops.size()) {
            int to = furthestThatFits(stops, from, carried, seedsBoxed);
            if (to < from && peakOver(stops, from, from, carried, seedsBoxed) <= SLOTS) {
                // Tight, not impossible: one arrival over WORKING_SLOTS but within SLOTS.
                // Taken as a leg of one rather than reported. Every path below still
                // advances `from`, so the loop still terminates.
                to = from;
            }
            if (to < from) {
                // One arrival alone exceeds the bag. Nothing to split, so report it.
                //
                // Required for termination: this branch must advance `from`. The paths
                // below all advance it too, since latestBankIn searches [from + 1, to + 1].
                // Without this branch the loop builds legs for the same arrival forever.
                Demand alone = stops.get(from);
                int wanted = peakOver(stops, from, from, carried, seedsBoxed);
                String said = alone.getAt().getDisplayName() + " alone needs " + wanted + " inventory slots.";
                // An earlier shortfall and this one can both apply; report both.
                legs.add(new Leg(from, bankAt, bankCost, bankPlace, broughtForward,
                        wanted, unbanked == null ? said : unbanked + " " + said, false, passableBanksIn(stops, from, from)));
                from++;
                bankAt = null;
                bankCost = null;
                bankPlace = null;
                broughtForward = false;
                unbanked = null;
                harvestRoomOnly = false;
                continue;
            }
            boolean last = to + 1 >= stops.size();
            int cut = last ? -1 : latestBankIn(stops, from + 1, to + 1);
            if (cut < 0) {
                legs.add(new Leg(from, bankAt, bankCost, bankPlace, broughtForward,
                        peakOver(stops, from, to, carried, seedsBoxed), unbanked,
                        harvestRoomOnly, passableBanksIn(stops, from, to)));
                if (last) {
                    break;
                }
                // The next arrival does not fit and no bank is in reach. Name both ends.
                // Exceeding SLOTS is a real shortfall. Eating into the harvest reserve only
                // means picking less, and must not be reported as a full bag.
                boolean beyondTheBag = peakOver(stops, from, to + 1, carried, seedsBoxed) > SLOTS;
                String full = stops.get(to + 1).getAt().getDisplayName();
                unbanked = (beyondTheBag ? "Your inventory fills at " : "Your inventory has no room left for the harvest at ")
                        + full + ". No bank lies between " + stops.get(from).getAt().getDisplayName() + " and " + full + ".";
                harvestRoomOnly = !beyondTheBag;
                from = to + 1;
                bankAt = null;
                bankCost = null;
                bankPlace = null;
                broughtForward = false;
                continue;
            }
            int latest = cut;
            cut = orAcheaperBankNoLater(stops, from, cut, carried, seedsBoxed);
            // The leg ends before the cut, not at `to`. The bank arrival opens the next leg,
            // since its demands come out of the bank. Ending at `to` would put arrivals on
            // two legs and charge their saplings twice.
            legs.add(new Leg(from, bankAt, bankCost, bankPlace, broughtForward,
                    peakOver(stops, from, cut - 1, carried, seedsBoxed),
                    unbanked, harvestRoomOnly, passableBanksIn(stops, from, cut - 1)));
            unbanked = null;
            harvestRoomOnly = false;
            from = cut;
            bankAt = stops.get(cut).getAt();
            // Null where the rung has no figure; see Demand#isBankMeasured.
            bankCost = stops.get(cut).isBankMeasured() ? stops.get(cut).getBank() : null;
            bankPlace = stops.get(cut).getBankPlace();
            broughtForward = cut < latest;
        }
        return new Plan(legs);
    }

    /**
     * The last arrival this leg can reach before the bag is fuller than it holds.
     *
     * <p>Returns {@code from - 1} when the first arrival alone exceeds
     * {@link #WORKING_SLOTS}.
     */
    private static int furthestThatFits(List<Demand> stops, int from, int carried, boolean seedsBoxed) {
        int to = from - 1;
        for (int end = from; end < stops.size(); end++) {
            if (peakOver(stops, from, end, carried, seedsBoxed) > WORKING_SLOTS) {
                break;
            }
            to = end;
        }
        return to;
    }

    /**
     * The fullest the bag gets over one leg, walked rather than counted.
     *
     * <p>Order matters: seeds and payments leave as they are spent, and produce arrives as
     * it is picked. Within one arrival the harvest comes first, because a patch must be
     * emptied before it takes a seed.
     */
    private static int peakOver(List<Demand> stops, int from, int to, int carried, boolean seedsBoxed) {
        // Withdrawn before setting out: one slot per kind, for the whole leg's worth. A
        // planted sapling leaves its empty pot in the bag, so each costs its slot the whole
        // leg, planted or not. Barbarian Training can destroy the pot, but the player can
        // turn that setting off and nothing reports it. Assuming the pots gone would plan
        // legs that overflow in the field; assuming they stay costs at most a spare bank stop.
        Set<Crop> seedsLeft = EnumSet.noneOf(Crop.class);
        Set<PatchType> paymentsLeft = EnumSet.noneOf(PatchType.class);
        int saplings = 0;
        for (int i = from; i <= to; i++) {
            seedsLeft.addAll(stops.get(i).getSeeds());
            paymentsLeft.addAll(stops.get(i).getProtections());
            saplings += stops.get(i).getSaplings();
        }

        Items items = Items.over(stops, to);
        Set<Crop> picked = EnumSet.noneOf(Crop.class);
        // Setting off: from the trip's starting bank on the opening leg, otherwise from the
        // bank at the leg's first arrival, reached already.
        int peak = carried + items.heldAt(from == 0 ? -1 : from) + seedSlots(seedsLeft.size(), seedsBoxed)
                + paymentsLeft.size() + saplings;
        for (int i = from; i <= to; i++) {
            Demand stop = stops.get(i);
            // Peak read after picking and before spending: the fullest moment at an arrival
            // is the harvest in hand with this stop's seed and payment still held.
            picked.addAll(stop.getProduce());
            peak = Math.max(peak, carried + items.heldAt(i) + seedSlots(seedsLeft.size(), seedsBoxed)
                    + paymentsLeft.size() + saplings + picked.size());

            // Spent on the way out. Nothing below raises the total, so the peak is not re-read.
            seedsLeft.removeAll(stop.getSeeds());
            paymentsLeft.removeAll(stop.getProtections());
        }
        return peak;
    }

    /**
     * The tools and travel items in the bag on a leg, one slot each.
     *
     * <p>Each comes out at the bank of the leg that first needs it, as the seeds do, and
     * stays to the end of the trip, because nothing is deposited. A travel item is needed
     * from the arrival before the one it reaches. A stack of tablets alone leaves the bag,
     * at the last arrival this leg's withdrawal reaches: each bank fetches only its own
     * stretch's tablets, so a later use comes out of a later bank.
     */
    private static final class Items {

        /** Each item the leg has withdrawn by its end, and the arrival it is gone at. */
        private final List<Integer> goneAt;

        private Items(List<Integer> goneAt) {
            this.goneAt = goneAt;
        }

        /** Over a leg ending at {@code to}. */
        static Items over(List<Demand> stops, int to) {
            Map<Integer, Integer> firstNeeded = new HashMap<>();
            Map<Integer, Integer> lastSpent = new HashMap<>();
            for (int i = 0; i < stops.size(); i++) {
                Demand stop = stops.get(i);
                for (int item : stop.getTools()) {
                    firstNeeded.merge(item, i, Math::min);
                }
                for (int item : stop.getTravel()) {
                    firstNeeded.merge(item, Math.max(0, i - 1), Math::min);
                }
                // Up to the arrival after the leg, whose tablet is spent reaching the next
                // bank. Tablets for beyond it are fetched there.
                if (i <= to + 1) {
                    for (int item : stop.getSpentOnTheWay()) {
                        lastSpent.merge(item, i, Math::max);
                    }
                }
            }
            List<Integer> goneAt = new ArrayList<>();
            for (Map.Entry<Integer, Integer> needed : firstNeeded.entrySet()) {
                if (needed.getValue() <= to) {
                    goneAt.add(lastSpent.getOrDefault(needed.getKey(), Integer.MAX_VALUE));
                }
            }
            return new Items(goneAt);
        }

        /** How many are in the bag while standing at this arrival, -1 for the first bank. */
        int heldAt(int arrival) {
            int held = 0;
            for (int gone : goneAt) {
                if (gone > arrival) {
                    held++;
                }
            }
            return held;
        }
    }

    /**
     * What a leg's seed kinds cost in slots. With the box along, only kinds beyond
     * {@link SeedBox#KINDS_HELD} cost a slot; the box's own slot is charged with the fixtures.
     */
    private static int seedSlots(int kinds, boolean seedsBoxed) {
        return seedsBoxed ? Math.max(0, kinds - SeedBox.KINDS_HELD) : kinds;
    }

    /** Whether any stop on the trip puts a seed in the ground, as opposed to a sapling. */
    private static boolean plantsSeeds(List<Demand> stops) {
        return stops.stream().anyMatch(stop -> !stop.getSeeds().isEmpty());
    }

    /**
     * The latest arrival in this window the player can bank at, or -1 when none can.
     *
     * <p>Latest rather than cheapest, so the leg count stays minimal; a {@code FAR} bank
     * still counts. {@link #orAcheaperBankNoLater} then moves the cut to a cheaper bank
     * where that costs no extra leg. An arrival whose bank grades {@code NONE} is never a
     * candidate.
     */
    private static int latestBankIn(List<Demand> stops, int from, int to) {
        for (int i = Math.min(to, stops.size() - 1); i >= from; i--) {
            if (stops.get(i).getBank() != Arrival.BankProximity.NONE) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Every bank on a leg the trip is walking past.
     *
     * <p>Starts at {@code from + 1}: the leg's first arrival is where it was banked onto (or,
     * on the opening leg, the trip's starting bank).
     *
     * <p>Unmeasured rungs come back with a null cost rather than being dropped.
     *
     * <p>Not gated on how full the bag is. These rows are offers: banking is convenient when
     * passing, and the player judges whether to take one.
     *
     * <p>Only banks the trip genuinely walks past are offered; see {@link #offeredHere}.
     */
    private static List<Opportunity> passableBanksIn(List<Demand> stops, int from, int to) {
        List<Opportunity> passed = new ArrayList<>();
        for (int i = from + 1; i <= to && i < stops.size(); i++) {
            Demand stop = stops.get(i);
            if (!offeredHere(stop)) {
                continue;
            }
            passed.add(new Opportunity(i, stop.getAt(), stop.isBankMeasured() ? stop.getBank() : null, stop.getBankPlace()));
        }
        return List.copyOf(passed);
    }

    /**
     * Whether this arrival's bank is worth putting a row in front of the player.
     *
     * <p>A measured route is judged on its tiles against {@link #OFFERED_WITHIN_TILES},
     * since the {@code FAR} grade spans banks on the way and banks that are an errand. An
     * unmeasured bank is offered only when the arrival's constant says it is on the way,
     * because that constant grades the whole arrival.
     *
     * <p>This narrows only what is <em>offered</em>. A forced break still uses
     * {@link #latestBankIn}, which may pick a real detour.
     */
    private static boolean offeredHere(Demand stop) {
        int walked = stop.bankCostInTiles();
        return walked == TravelOption.UNMEASURED ? stop.getBank().onTheWay() : walked <= OFFERED_WITHIN_TILES;
    }

    /**
     * The same cut, moved back to a better bank when moving it costs the trip nothing.
     *
     * <p>{@link #latestBankIn} minimises the number of legs and ignores walking cost. This
     * moves the cut to an earlier, cheaper bank <b>as long as the trip does not gain a leg
     * by cutting sooner</b>.
     *
     * <p>Only a strictly better <em>grade</em> moves the cut, never a few tiles inside one.
     * Grades exist for measured and unmeasured rungs alike, so both compare on equal terms.
     * Ties keep the later arrival.
     */
    private static int orAcheaperBankNoLater(List<Demand> stops, int from, int cut, int carried, boolean seedsBoxed) {
        Arrival.BankProximity best = stops.get(cut).getBank();
        if (best == Arrival.BankProximity.AT_ARRIVAL) {
            return cut;
        }
        int allowed = legsFrom(stops, cut, carried, seedsBoxed);
        int chosen = cut;
        for (int i = cut - 1; i > from; i--) {
            Arrival.BankProximity here = stops.get(i).getBank();
            if (here.compareTo(best) < 0 && legsFrom(stops, i, carried, seedsBoxed) <= allowed) {
                best = here;
                chosen = i;
            }
        }
        return chosen;
    }

    /**
     * How many legs the rest of the trip takes from here, cutting as late as it can.
     *
     * <p>The yardstick for {@link #orAcheaperBankNoLater}. Deliberately the plain
     * latest-bank walk, not a recursive copy of the caller, so it terminates and is
     * deterministic. Latest-bank cutting gives the minimal count.
     */
    private static int legsFrom(List<Demand> stops, int start, int carried, boolean seedsBoxed) {
        int legs = 0;
        int from = start;
        while (from < stops.size()) {
            int to = furthestThatFits(stops, from, carried, seedsBoxed);
            legs++;
            if (to < from) {
                // Covers both plan()'s tight-arrival and impossible-arrival branches, which
                // each emit one leg and advance one arrival.
                from++;
                continue;
            }
            if (to + 1 >= stops.size()) {
                break;
            }
            int cut = latestBankIn(stops, from + 1, to + 1);
            from = cut < 0 ? to + 1 : cut;
        }
        return legs;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.Arrivals;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import java.util.*;
import lombok.Value;

/**
 * One trip, made of every crop family that has work waiting.
 *
 * <p>Every run is planned, then the stops share one circuit, so a place is visited once
 * however many families sent the player there.
 *
 * <p>Per-run planning (rungs, seed allocation, seed shortfalls) happens before this, per run
 * and in run order, because the seed rotation is allocated in the catalogue's patch order.
 * Merging first would hand a patch the seed meant for another. This class takes planned
 * runs, drops duplicate patches, puts the stops in the circuit's seat order, which every
 * book walks, groups them by arrival, and moves the patches that earn the better seeds to
 * the front of the herb rotation.
 */
public final class Itinerary {

    /** No herb patch here takes a rotation seed, so the visit has no rank and stays put. */
    private static final int UNRANKED = Integer.MIN_VALUE;

    private Itinerary() {
    }

    /** One run's stops, already planned, with the crops its patches take. */
    @Value
    public static class Planned {

        RunId run;
        /** Parallel to {@link #cropFor}; never reordered, because the seeds were not. */
        List<StopPlan> plans;
        List<List<Crop>> cropFor;

        public Planned(RunId run, List<StopPlan> plans, List<List<Crop>> cropFor) {
            if (plans.size() != cropFor.size()) {
                throw new IllegalArgumentException(run + " planned " + plans.size() + " stops but named crops for " + cropFor.size());
            }
            this.run = run;
            this.plans = List.copyOf(plans);
            this.cropFor = List.copyOf(cropFor);
        }
    }

    /**
     * The trip as one flat list of stops in circuit order, plus how they group into
     * visits.
     *
     * <p>Flat because downstream code, such as {@code adviseOnGroup}, takes indices into a
     * plan list.
     */
    @Value
    public static class Trip {

        List<StopPlan> plans;
        List<List<Crop>> cropFor;
        /** Which family put each stop on the list, parallel to {@link #plans}. */
        List<RunId> runFor;
        /**
         * Indices into {@link #plans}, one group per arrival, in circuit order.
         *
         * <p>Read with {@link #runFor} to learn which families the trip covers. There is no
         * separate family set: it would be settled before the caller drops unreached
         * arrivals, and would name families the player is shown nothing for.
         */
        List<List<Integer>> visits;

        private Trip(List<StopPlan> plans, List<List<Crop>> cropFor, List<RunId> runFor, List<List<Integer>> visits) {
            this.plans = List.copyOf(plans);
            this.cropFor = List.copyOf(cropFor);
            this.runFor = List.copyOf(runFor);
            this.visits = List.copyOf(visits);
        }

        /**
         * The same trip with its routes decided again, once the circuit has said what order
         * the stops are reached in.
         *
         * <p>Routes only. The stops, their families and the visits are carried over
         * unchanged. The new lists must hold the same stops in the same order, since the
         * visits index them; a mismatch throws rather than showing a row with another
         * stop's route.
         *
         * @param cropFor carried alongside because a stop that loses its route plants
         *     nothing, and the bag is packed from this
         */
        public Trip rerouted(List<StopPlan> plans, List<List<Crop>> cropFor) {
            if (plans.size() != this.plans.size() || cropFor.size() != this.cropFor.size()) {
                throw new IllegalArgumentException("re-routing changed the trip's "
                        + this.plans.size() + " stops and " + this.cropFor.size()
                        + " crop lists into " + plans.size() + " and " + cropFor.size());
            }
            // Same stops in the same order, not merely the same count.
            for (int index = 0; index < plans.size(); index++) {
                if (plans.get(index).getStop() != this.plans.get(index).getStop()) {
                    throw new IllegalArgumentException("re-routing moved " + this.plans.get(index).getStop().primaryPatch().getLabel()
                            + " to where " + plans.get(index).getStop().primaryPatch().getLabel() + " now sits");
                }
            }
            return new Trip(plans, cropFor, runFor, visits);
        }

        /**
         * The same trip walked in another order: the same visits, each kept whole, put in
         * a different sequence. Anything else throws, since a visit split or dropped here
         * would lose or duplicate a stop's row.
         */
        Trip revisited(List<List<Integer>> visits) {
            if (visits.size() != this.visits.size() || !new HashSet<>(visits).equals(new HashSet<>(this.visits))) {
                throw new IllegalArgumentException("re-ordering changed the trip's visits " + this.visits + " into " + visits);
            }
            return new Trip(plans, cropFor, runFor, visits);
        }
    }

    /**
     * Merge planned runs into one trip.
     *
     * @param planned one entry per run with work waiting, in the order the scheduler
     *     ranked them — which decides who wins a duplicated patch
     * @param state the player, whose diaries and quests decide which patches earn the
     *     better seeds and therefore which are reached first. Null before anything has
     *     been reported, which scores every patch alike and leaves the circuit as authored
     */
    public static Trip merge(List<Planned> planned, PlayerState state) {
        List<StopPlan> plans = new ArrayList<>();
        List<List<Crop>> cropFor = new ArrayList<>();
        List<RunId> runFor = new ArrayList<>();
        Set<PatchRef> alreadyWorked = new HashSet<>();

        for (Planned run : planned) {
            for (int i = 0; i < run.getPlans().size(); i++) {
                StopPlan plan = run.getPlans().get(i);
                // Some earlier run already claimed a patch this stop works. The run passed
                // first (the scheduler's higher-ranked run) keeps it: arbitrary but stable.
                // Tested against the whole patch list, so a multi-patch stop is dropped whole.
                if (!Collections.disjoint(plan.getStop().getPatches(), alreadyWorked)) {
                    continue;
                }
                alreadyWorked.addAll(plan.getStop().getPatches());
                plans.add(plan);
                cropFor.add(run.getCropFor().get(i));
                runFor.add(run.getRun());
            }
        }

        // Grouping consecutive stops suffices: an arrival has a single seat, so the sort
        // has already put its stops together.
        List<List<Integer>> visits = TripOrder.groupByArrival(inSeatOrder(plans), plans);
        return new Trip(plans, cropFor, runFor, bestHomesFirst(visits, plans, state));
    }

    /**
     * One run walked on its own, in the catalogue's order rather than the seats', with its
     * best homes re-dealt first as a merged trip's are.
     */
    static Trip alone(Planned run, PlayerState state) {
        List<List<Integer>> visits = TripOrder.groupByArrival(TripOrder.inTripOrder(run.getPlans()), run.getPlans());
        return new Trip(run.getPlans(), run.getCropFor(), Collections.nCopies(run.getPlans().size(), run.getRun()),
                bestHomesFirst(visits, run.getPlans(), state));
    }

    /**
     * Stop indices in the order the trip walks them.
     *
     * <p>Sorted by the circuit's seats. The sort is stable, so ties keep each run's own patch
     * order and the trip does not reshuffle between snapshots.
     *
     * <p>Every {@link Arrival} constant has a seat in {@link Arrivals}, which refuses to load
     * otherwise.
     */
    private static List<Integer> inSeatOrder(List<StopPlan> plans) {
        List<Integer> order = new ArrayList<>(plans.size());
        for (int i = 0; i < plans.size(); i++) {
            order.add(i);
        }
        order.sort(Comparator.comparingInt(index -> Arrivals.seat(plans.get(index).getStop().getArrival())));
        return order;
    }

    /**
     * The herb rotation's own visits re-dealt best home first, so the seeds land where they
     * were meant to even when a seed box is doing the planting.
     *
     * <p>A seed box plants the first seed in it that the patch will take, in the order the
     * seeds were put in the box; it only skips seeds the patch would refuse. So the order
     * the patches are reached decides which seed each gets. {@code assignCrops} deals the
     * better seeds down the {@link PatchPriority} ranking, and this makes the walk follow
     * that ranking too.
     *
     * <p><b>Whole visits move, never single stops</b>, so an arrival's other patches are not
     * left behind for a second trip. An arrival ranks by the best herb patch it holds.
     *
     * <p><b>Only the herb rotation's seats are re-dealt</b>: arrivals with a herb patch the
     * rotation plants. Every other arrival keeps its position, except one that rides with a
     * seat: a circuit neighbour reached by the same teleport moves with it, so the Falador
     * park tree stays beside the Falador farm. The Farming Guild's herb patch
     * is {@linkplain PatchPriority#isReservedForContracts reserved}, so the Guild is never a
     * seat and keeps its lead for banking.
     *
     * <p><b>A seat is a fact of the catalogue, never of the ground.</b> A patch found growing,
     * or past the end of the seeds, keeps its seat, so the order holds still while the player
     * walks round seeing patches for the first time: a finished stop drops off and nothing
     * else moves. The patches that do get a seed are a subset of the seats, so they are still
     * reached best first and the seed box still lands each seed where it was dealt.
     *
     * <p>The extra travel is accepted: a misplanted seed is lost for the whole grow, and the
     * walk is paid once. The order follows {@link PatchPriority#scoreOf}, so it changes with
     * a diary or a quest, not with what is in the ground.
     *
     * <p>A moved stop can be reached before a rung that leans on it.
     * {@code replanAcrossTheCircuit} handles that, on a trip and on a run walked alone.
     *
     * <p>Two paths reach it: {@link #merge} for a trip, and {@link #alone} for a single run
     * in catalogue order. Both must re-deal, or a seed box would plant the seeds in walking
     * order on one of them.
     *
     * @param visits stops grouped by arrival <b>in the order the caller walks them</b>,
     *     which is what the ranking's ties fall back to and therefore what the allocation
     *     has to be keyed on as well. Returned as a permutation with the groups themselves
     *     untouched — or returned as the very same list when there is nothing to reorder,
     *     so a caller that intends to keep hold of it should copy
     */
    static List<List<Integer>> bestHomesFirst(List<List<Integer>> visits, List<StopPlan> plans, PlayerState state) {
        int[] rank = new int[visits.size()];
        List<Integer> seats = new ArrayList<>();
        for (int visit = 0; visit < visits.size(); visit++) {
            rank[visit] = rankOf(visits.get(visit), plans, state);
            if (rank[visit] != UNRANKED) {
                seats.add(visit);
            }
        }
        // One seat cannot be out of order with itself, and neither can none.
        if (seats.size() < 2) {
            return visits;
        }

        List<Integer> byRank = new ArrayList<>(seats);
        // Stable, so equal ranks keep the caller's walking order and an account that has
        // earned nothing walks the identity permutation. Ties stay unbroken by seat: a run
        // walked alone follows the catalogue's order, not the circuit, and the allocation
        // shares the caller's walk.
        byRank.sort(Comparator.comparingInt((Integer visit) -> rank[visit]).reversed());

        int[] walk = new int[visits.size()];
        for (int position = 0; position < walk.length; position++) {
            walk[position] = position;
        }
        for (int seat = 0; seat < seats.size(); seat++) {
            walk[seats.get(seat)] = byRank.get(seat);
        }
        return withRidersBesideTheirSeats(walk, visits, ridersOf(seats, visits, plans));
    }

    /**
     * Each visit that rides with a seat: a circuit neighbour reached by the same teleport,
     * such as the Falador park tree beside the Falador farm. Keyed by the rider, valued by
     * its seat. Moving the seat without it would cast the same teleport twice, nine stops
     * apart.
     *
     * <p>A neighbour on the walk, not on the list: an arrival the player is not making and
     * that is no seat lies between them unwalked. Otherwise a family coming due partway round
     * would slot its skipped arrivals in between, part the rider from its seat, and move it.
     */
    private static Map<Integer, Integer> ridersOf(List<Integer> seats, List<List<Integer>> visits, List<StopPlan> plans) {
        Set<Integer> isSeat = new HashSet<>(seats);
        Map<Integer, Integer> riders = new HashMap<>();
        for (int seat : seats) {
            Destination landing = landingOf(visits.get(seat), plans);
            if (landing == null) {
                continue;
            }
            for (int step : new int[] {-1, 1}) {
                int neighbour = seat + step;
                while (neighbour >= 0 && neighbour < visits.size() && !isSeat.contains(neighbour)
                        && StopRowWriter.visitsIn(visits.get(neighbour), plans).isEmpty()) {
                    neighbour += step;
                }
                if (neighbour >= 0 && neighbour < visits.size() && !isSeat.contains(neighbour) && !riders.containsKey(neighbour)
                        && landing == landingOf(visits.get(neighbour), plans)) {
                    riders.put(neighbour, seat);
                }
            }
        }
        return riders;
    }

    /** The place a visit's teleport lands at, or null for a route that names none. */
    private static Destination landingOf(List<Integer> visit, List<StopPlan> plans) {
        for (int index : visit) {
            StopPlan plan = plans.get(index);
            if (plan.isVisit() && plan.getRoute() != null && plan.getRoute().getDestination() != null) {
                return plan.getRoute().getDestination();
            }
        }
        return null;
    }

    /**
     * The walk with every rider taken out of its own place and put back beside its seat, on
     * the side of it the circuit had it.
     */
    private static List<List<Integer>> withRidersBesideTheirSeats(int[] walk, List<List<Integer>> visits, Map<Integer, Integer> riders) {
        List<List<Integer>> placed = new ArrayList<>(visits.size());
        for (int visit : walk) {
            if (riders.containsKey(visit)) {
                continue;
            }
            addRiders(placed, visit, visits, riders, true);
            placed.add(visits.get(visit));
            addRiders(placed, visit, visits, riders, false);
        }
        return placed;
    }

    private static void addRiders(List<List<Integer>> placed, int seat,
            List<List<Integer>> visits, Map<Integer, Integer> riders, boolean before) {
        for (Map.Entry<Integer, Integer> rider : new TreeMap<>(riders).entrySet()) {
            if (rider.getValue() == seat && rider.getKey() < seat == before) {
                placed.add(visits.get(rider.getKey()));
            }
        }
    }

    /**
     * How good a home for a seed the best herb patch at this arrival is, or
     * {@link #UNRANKED} when the herb rotation plants nothing here.
     *
     * <p>The best rather than a sum or average: an arrival is one journey.
     *
     * <p>Read off the stop alone: whether it is visited today, or what its ground holds,
     * would move it as patches are seen (see {@link #bestHomesFirst}).
     *
     * <p>Stops with a fixed crop are not seats; their seed cannot be misdealt.
     *
     * <p>Herbs only, by name. Herbs are the one family planted from a shared seed rotation,
     * and the only one {@link com.larryfarming.farming.catalogue.PatchAttributes} ranks. Tree
     * patches have no better or worse home, so ranking them would only add travel.
     */
    private static int rankOf(List<Integer> visit, List<StopPlan> plans, PlayerState state) {
        int best = UNRANKED;
        for (int index : visit) {
            StopPlan plan = plans.get(index);
            // A herb patch per the world map rather than the run that named it; an
            // unresolvable reference is no herb patch, so it never reorders the trip. A stop's
            // patches all share one type (RunStop's builder enforces it), so the primary
            // answers for them all.
            if (plan.getStop().isFixedCrop() || !plan.getStop().isPlanting() || plan.getStop().primaryPatch().type() != PatchType.HERB) {
                continue;
            }
            for (PatchRef patch : plan.getStop().getPatches()) {
                // A patch reserved for contracts is not a rotation seat. Ranking it would
                // move the Farming Guild out of its banking lead.
                if (!PatchPriority.isReservedForContracts(patch)) {
                    best = Math.max(best, PatchPriority.scoreOf(patch, state));
                }
            }
        }
        return best;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.detection.BottomlessBucket;
import com.larryfarming.farming.model.Arrival;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.FarmingCarryItem;
import java.util.*;
import net.runelite.api.gameval.ItemID;

/**
 * Which farming tools to leave with the tool leprechaun, and where: at the last arrival that
 * uses each one.
 *
 * <p>Every leprechaun opens one shared store, so a spade left at the last patch comes back
 * out at the first patch of the next trip, and the rest of this trip carries it no further.
 * A tool is left only where a leprechaun stands, and only once nothing after that arrival
 * wants it.
 */
final class LeprechaunPlanner {

    private LeprechaunPlanner() {
    }

    /** Farming places the wiki lists no tool leprechaun at. */
    private static final Set<Arrival> NO_LEPRECHAUN = EnumSet.of(Arrival.ORTUS_FARM, Arrival.GREAT_CONCH);

    /**
     * Used only to plant, so free once the last planting is done: the dibber and loose
     * compost. Not the bottomless bucket, which is left after its last use like any tool.
     */
    private static final Set<Integer> PLANTING_ONLY = Set.of(ItemID.DIBBER, ItemID.BUCKET_COMPOST,
            ItemID.BUCKET_SUPERCOMPOST, ItemID.BUCKET_ULTRACOMPOST);

    /**
     * What to leave at each arrival, keyed by its index in {@code made}.
     *
     * @param made    each arrival's stop indices into {@code plans}, in walk order
     * @param carry   the trip's packing list; only storable lines the player brings count
     * @param underway whether the player is partway round, when only what the bag holds
     *     now can still be left
     */
    static Map<Integer, List<FarmingCarryItem>> leaveAt(List<List<Integer>> made,
            List<StopPlan> plans, List<List<Crop>> cropFor, List<FarmingCarryItem> carry, boolean underway, PlayerState state) {
        Map<Integer, List<FarmingCarryItem>> leave = new HashMap<>();
        for (FarmingCarryItem line : carry) {
            if (!ItemCounts.leprechaunStores(line.getItemId()) || !broughtAlong(line, underway)) {
                continue;
            }
            // The leprechaun holds one bucket, so a second is not taken.
            if (BottomlessBucket.ITEM_IDS.contains(line.getItemId()) && BottomlessBucket.isStored(state)) {
                continue;
            }
            int last = lastUse(made, plans, cropFor, PLANTING_ONLY.contains(line.getItemId()));
            if (last < 0 || !hasLeprechaun(made.get(last), plans)) {
                continue;
            }
            leave.computeIfAbsent(last, at -> new ArrayList<>()).add(line);
        }
        return leave;
    }

    /** In the bag now, or, before setting off, about to be. */
    private static boolean broughtAlong(FarmingCarryItem line, boolean underway) {
        return line.getAvailability() == FarmingCarryItem.Availability.CARRIED
                || (!underway && line.getAvailability() == FarmingCarryItem.Availability.BANKED);
    }

    /**
     * The last arrival that uses the tool: any visit for the spade and the like, a planting
     * for the dibber and the composts. -1 when none does.
     */
    private static int lastUse(List<List<Integer>> made, List<StopPlan> plans, List<List<Crop>> cropFor, boolean plantingOnly) {
        for (int arrival = made.size() - 1; arrival >= 0; arrival--) {
            for (int index : made.get(arrival)) {
                if (!plans.get(index).isVisit()) {
                    continue;
                }
                if (!plantingOnly || !cropFor.get(index).isEmpty()) {
                    return arrival;
                }
            }
        }
        return -1;
    }

    /** Whether a tool leprechaun stands at this arrival. */
    static boolean hasLeprechaun(List<Integer> arrival, List<StopPlan> plans) {
        return hasLeprechaun(plans.get(arrival.get(0)).getStop().getArrival());
    }

    /** Whether a tool leprechaun stands at this arrival. */
    static boolean hasLeprechaun(Arrival arrival) {
        return !NO_LEPRECHAUN.contains(arrival);
    }

    /** "Leave your spade and seed dibber with the leprechaun." */
    static String sentence(List<FarmingCarryItem> tools) {
        return "Leave your " + LoadoutPlanner.inSentence(tools, "and") + " with the leprechaun.";
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.farming.catalogue.Loadouts;
import com.larryfarming.farming.model.GearPick;
import com.larryfarming.farming.model.LoadoutSlot;
import com.larryfarming.model.*;
import com.larryfarming.snapshot.FarmingCarryItem;
import com.larryfarming.snapshot.FarmingUpgrade;
import java.util.*;

/**
 * Works out what the player should be wearing or carrying, and what they have instead.
 *
 * <p>Each tier is worn, carried, owned elsewhere or unearned: "your Ardougne cloak is in
 * the bank" is actionable before the run, and "you do not have one" is not.
 *
 * <p>Only the Farmer's outfit and a fairy-ring staff must be worn (see {@link Loadouts}).
 * Every other item works from the inventory, so carrying it fills its slot as far as the
 * run is concerned and earns no advice. Owning it elsewhere earns a tip to wear it, which
 * saves a slot.
 *
 * <p>Nothing here is a requirement. A farm run with an empty cape slot still works, so
 * the output is graded advice, and unearned tiers are reported as goals.
 */
public final class LoadoutPlanner {

    private LoadoutPlanner() {
    }

    /**
     * Item names that start with a proper noun keep their capital mid-sentence ("your
     * Explorer's ring 2"). Every other name is lower-cased there ("your magic secateurs").
     */
    private static final Set<String> PROPER_FIRST_WORDS = Set.of("Farming", "Ardougne", "Explorer's", "Xeric's", "Farmer's");

    /**
     * Every slot worth filling, in catalogue order.
     *
     * <p>The ring slot earns its place only while the route takes the Explorer's ring's
     * Falador farm teleport. Otherwise the slot is left out, so the ring earns no tip and no
     * nag.
     *
     * @param staffWielded whether the run needs a fairy-ring staff in hand, which then
     *     holds the weapon slot (see {@link Loadouts#forRun})
     * @param ringTeleports whether the route teleports to the Falador farm by the ring,
     *     which the planner only allows while the ring has a teleport left today
     * @param basketWorn whether the trip cuts logs with the player's own basket and no route
     *     needs a cape's teleport (see {@code CarryPlanner.basketPlace})
     */
    public static List<SlotAdvice> plan(PlayerState state, boolean staffWielded, boolean ringTeleports, boolean basketWorn) {
        List<LoadoutSlot> slots = Loadouts.forRun(staffWielded, basketWorn);
        List<SlotAdvice> advice = new ArrayList<>(slots.size());
        for (LoadoutSlot slot : slots) {
            if (slot.getSlot() == EquipmentSlot.RING) {
                if (ringTeleports) {
                    advice.add(withRingNote(planSlot(slot, state)));
                }
                continue;
            }
            advice.add(planSlot(slot, state));
        }
        return advice;
    }

    /** The ring slot's tip, with "Teleport to the Falador farm with it." added. */
    private static SlotAdvice withRingNote(SlotAdvice advice) {
        String tip = advice.getTip();
        return tip.isEmpty() ? advice : advice.withTip(tip + " Teleport to the Falador farm with it.");
    }

    /**
     * The slot's verdict, decided by the first tier the player holds: best-first order
     * makes it the best they own, on hand or not. Nothing held is a goal, whether or not the
     * bank has been seen.
     */
    private static SlotAdvice planSlot(LoadoutSlot slot, PlayerState state) {
        ItemStack worn = state != null ? state.getEquipment().get(slot.getSlot()) : null;
        for (GearPick pick : slot.getTiers()) {
            // The form held, so a lunar staff is named and drawn as one.
            if (worn != null && pick.getItemIds().contains(worn.getItemId())) {
                return new SlotAdvice(slot, SlotAdvice.Verdict.SET, pick.formHolding(worn.getItemId()), "");
            }
            int carried = first(state, pick, true);
            if (carried > 0) {
                // Carrying serves the run for every item that need not be worn.
                GearPick held = pick.formHolding(carried);
                return slot.isMustWear() ? swap(slot, held) : new SlotAdvice(slot, SlotAdvice.Verdict.SET, held, "");
            }
            int owned = first(state, pick, false);
            if (owned > 0) {
                return swap(slot, pick.formHolding(owned));
            }
        }
        return new SlotAdvice(slot, SlotAdvice.Verdict.NOTHING_YET, null, "");
    }

    /** Advice to put on or bring {@code best}, which the player owns but not where the run wants it. */
    private static SlotAdvice swap(LoadoutSlot slot, GearPick best) {
        return new SlotAdvice(slot, SlotAdvice.Verdict.SWAP, best, String.format(slot.getTip(), inSentence(best.getDisplayName())));
    }

    /** An item name for mid-sentence, as the game writes it there. */
    static String inSentence(String name) {
        int space = name.indexOf(' ');
        String first = space < 0 ? name : name.substring(0, space);
        if (PROPER_FIRST_WORDS.contains(first)) {
            return name;
        }
        return Character.toLowerCase(name.charAt(0)) + name.substring(1);
    }

    /** These items' names mid-sentence: "spade, seed dibber and ultracompost". */
    static String inSentence(List<FarmingCarryItem> items, String conjunction) {
        List<String> names = new ArrayList<>(items.size());
        for (FarmingCarryItem item : items) {
            names.add(inSentence(item.getName()));
        }
        return LookOnce.joined(names, conjunction);
    }

    /**
     * The first charge level, trim or form of this pick's item the player has, or 0 when
     * they have none.
     *
     * @param carried true to look only on the player, false to count the bank and every
     *                other place they own items
     */
    private static int first(PlayerState state, GearPick pick, boolean carried) {
        for (int itemId : pick.getItemIds()) {
            int count = carried ? ItemCounts.countCarried(state, itemId, null) : ItemCounts.countOwned(state, itemId, null);
            if (count > 0) {
                return itemId;
            }
        }
        return 0;
    }

    /**
     * The gear list as rows, ready to render: what to put on or bring now, then what to
     * work toward. Every row's detail is the whole sentence to show.
     *
     * <p>Slots that are already right are left out. Grouped slots collapse to one row: the
     * Farmer's outfit is one decision across four slots.
     *
     * <p>Things to act on come first, and among them the essential slots before the
     * nice-to-have ones.
     */
    public static List<FarmingUpgrade> upgrades(List<SlotAdvice> plan) {
        List<FarmingUpgrade> rows = new ArrayList<>();
        // Which groups already have their one row. Row order is kept by rows, not here.
        Set<String> groupsDone = new HashSet<>();
        addEquips(plan, rows, false, groupsDone);
        addEquips(plan, rows, true, groupsDone);
        addGoals(plan, rows, groupsDone);
        return rows;
    }

    private static void addEquips(List<SlotAdvice> plan, List<FarmingUpgrade> rows, boolean niceToHave, Set<String> groupsDone) {
        for (SlotAdvice advice : plan) {
            String group = advice.getSlot().getGroup();
            if (advice.getVerdict() != SlotAdvice.Verdict.SWAP || advice.getSlot().isNiceToHave() != niceToHave) {
                continue;
            }
            if (group == null) {
                rows.add(new FarmingUpgrade(FarmingUpgrade.Kind.EQUIP, advice.getBest().getIconItemId(), advice.getBest().getDisplayName(),
                        advice.getTip()));
            } else if (groupsDone.add(group)) {
                // One row for the outfit, drawn as the first piece to put on.
                rows.add(new FarmingUpgrade(FarmingUpgrade.Kind.EQUIP,
                        advice.getBest().getIconItemId(), group, Loadouts.OUTFIT_TIP));
            }
        }
    }

    private static void addGoals(List<SlotAdvice> plan, List<FarmingUpgrade> rows, Set<String> groupsDone) {
        for (SlotAdvice advice : plan) {
            LoadoutSlot slot = advice.getSlot();
            if (advice.getVerdict() != SlotAdvice.Verdict.NOTHING_YET) {
                continue;
            }
            if (slot.getGroup() == null) {
                GearPick goal = slot.getGoal();
                rows.add(new FarmingUpgrade(FarmingUpgrade.Kind.GOAL, goal.getIconItemId(), goal.getDisplayName(), slot.getGoalSentence()));
            } else if (groupsDone.add(slot.getGroup())) {
                rows.add(groupRow(plan, slot.getGroup()));
            }
        }
    }

    /** One row standing for every slot in a group, counting how far along the player is. */
    private static FarmingUpgrade groupRow(List<SlotAdvice> plan, String group) {
        int total = 0;
        int have = 0;
        int icon = 0;
        for (SlotAdvice advice : plan) {
            if (!group.equals(advice.getSlot().getGroup())) {
                continue;
            }
            total++;
            if (advice.getVerdict() == SlotAdvice.Verdict.NOTHING_YET) {
                // Draw the group as the first piece still missing.
                if (icon == 0) {
                    icon = advice.getSlot().getGoal().getIconItemId();
                }
            } else {
                have++;
            }
        }
        String progress = group + ": you have " + have + " of " + total + " pieces. The set gives 2.5% more Farming experience.";
        return new FarmingUpgrade(FarmingUpgrade.Kind.GOAL, icon, group, progress);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.farming.detection.HouseLocation;
import com.larryfarming.model.PlayerState;
import com.larryfarming.model.Skill;
import com.larryfarming.snapshot.FarmingHouse;
import java.util.ArrayList;
import java.util.List;

/**
 * The stores Larry has never looked in, asked for in one line: "Check your bank, seed vault
 * and house." Larry assumes nothing about a store he has not seen, so its contents can
 * change the packing list and the routes once the player opens it.
 *
 * <p>Only stores the player can reach: the seed vault from the Farming Guild's level, the
 * house once the game says the player owns one.
 */
final class LookOnce {

    private LookOnce() {
    }

    /** The line, or empty when Larry has seen every store the player can reach. */
    static String sentence(PlayerState state, FarmingHouse house) {
        if (state == null) {
            return "";
        }
        List<String> stores = new ArrayList<>();
        if (state.getBankLastSeen() == null) {
            stores.add("bank");
        }
        // An unread level never asks: getSkillLevel answers 1 for it.
        if (state.getSeedVaultLastSeen() == null && state.getSkillLevel(Skill.FARMING) >= SeedSelector.FARMING_GUILD_LEVEL) {
            stores.add("seed vault");
        }
        if (Boolean.TRUE.equals(HouseLocation.ownsHouse(state.getVarbits())) && house != null) {
            if (house.getSight() == FarmingHouse.Sight.NOT_SEEN) {
                stores.add("house");
            } else if (house.getSight() == FarmingHouse.Sight.NEXUS_NOT_SEEN) {
                stores.add("Portal Nexus");
            }
        }
        if (stores.isEmpty()) {
            return "";
        }
        return "Check your " + joined(stores, "and") + ".";
    }

    /** "bank", "bank and house", "bank, seed vault and house", with {@code and} as given. */
    static String joined(List<String> names, String and) {
        int last = names.size() - 1;
        return last == 0 ? names.get(0) : String.join(", ", names.subList(0, last)) + " " + and + " " + names.get(last);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.detection.CapabilityResolver;
import com.larryfarming.farming.model.Bank;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.FarmingCarryItem;
import java.util.*;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;

/**
 * Partway round, the warning on the next stop's card when the bag lacks something the stop
 * cannot be done without. It also catches a player who walked past the bank that held it.
 */
final class MissingItems {

    private MissingItems() {
    }

    /**
     * What the stop cannot be done without: the spade, the dibber, an axe for a tree to
     * fell, the gardener's coins, and the seeds. The bucket, the seed box
     * and the like make the stop easier but never stop it, so they raise no warning.
     */
    private static final Set<Integer> NEEDED = needed();

    private static Set<Integer> needed() {
        Set<Integer> ids = new HashSet<>(CarryPlanner.formsOf(ItemID.BRONZE_AXE));
        ids.add(ItemID.SPADE);
        ids.add(ItemID.DIBBER);
        ids.add(ItemID.COINS);
        return ids;
    }

    /**
     * What the next stop needs that the bag lacks: "No axe in your bag. Bank at Catherby
     * first.", or "Not enough ranarr seed" where some are carried. Empty when nothing is
     * missing.
     *
     * <p>Only what the stop itself uses: the way there is left out, since a player standing
     * at the stop has spent the tablet that brought them. Only what is owned: an item owned
     * nowhere is already greyed on the packing list, and no bank holds it. A tool stored with
     * the leprechaun counts as missing only where no leprechaun stands.
     *
     * <p>A seed line's carried count includes saplings, so a carried seed of a tree crop
     * reads as some in the bag.
     *
     * @param here        the next arrival's stops, its plantings index for index
     * @param leprechaun  whether a tool leprechaun stands at that arrival
     * @param bank        the bank to name, or null to name none
     */
    static String at(List<StopPlan> here, List<List<Crop>> plantedHere, boolean leprechaun,
            Bank bank, PlayerState state, CapabilityResolver resolver, FarmingInputs inputs) {
        List<StopPlan> standingThere = here.stream().map(CarryPlanner::withoutTravel).collect(Collectors.toList());
        List<FarmingCarryItem> missing = new ArrayList<>();
        List<FarmingCarryItem> tooFew = new ArrayList<>();
        for (FarmingCarryItem line : CarryPlanner.plan(standingThere, List.of(), plantedHere, state, resolver, inputs)) {
            boolean needed = line.getKind() == FarmingCarryItem.Kind.SEED || NEEDED.contains(line.getItemId());
            boolean away = line.getAvailability() == FarmingCarryItem.Availability.BANKED || (!leprechaun
                            && line.getAvailability() == FarmingCarryItem.Availability.AT_LEPRECHAUN);
            if (!needed || !away) {
                continue;
            }
            if (line.getCarriedCount() > 0) {
                tooFew.add(line);
            } else {
                missing.add(line);
            }
        }
        if (missing.isEmpty() && tooFew.isEmpty()) {
            return "";
        }
        StringBuilder said = new StringBuilder();
        if (!missing.isEmpty()) {
            said.append("No ").append(LoadoutPlanner.inSentence(missing, "or")).append(" in your bag.");
        }
        if (!tooFew.isEmpty()) {
            said.append(said.length() == 0 ? "" : " ").append("Not enough ")
                    .append(LoadoutPlanner.inSentence(tooFew, "and")).append(" in your bag.");
        }
        if (bank != null) {
            said.append(' ').append(bank.getRowTitle()).append(" first.");
        }
        return said.toString();
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.farming.catalogue.PatchAttributes;
import com.larryfarming.farming.detection.CapabilityState;
import com.larryfarming.farming.detection.DiaryTiers;
import com.larryfarming.farming.model.PatchRef;
import com.larryfarming.model.PlayerState;
import com.larryfarming.model.QuestStatus;
import java.util.List;

/**
 * How good a home a patch is for a seed, as a score the allocator sorts on.
 *
 * <p>The score knows nothing about travel and does not change with the walk.
 * {@link Itinerary} reads it separately to order the herb rotation's visits.
 *
 * <p><b>Everything here is a function of player state.</b> Hosidius is disease-free only
 * with the Easy Kourend &amp; Kebos diary; Catherby's yield bonus is +5/+10/+15% at
 * Kandarin Medium/Hard/Elite; Trollheim and Weiss are granted theirs by quests. So the
 * score is recomputed rather than declared.
 *
 * <h2>The ranking</h2>
 *
 * <p>Bands, high to low: <b>yield bonus, disease immunity, experience bonus, easy travel,
 * ordinary, reserved.</b> Within a band the bonus is graded, so a Kandarin Elite Catherby
 * outranks a Hard one. The weights encode only that ordering, not an exchange rate between
 * bands.
 *
 * <p>Reserved sits <em>below</em> ordinary. The Farming Guild herb patch has a yield bonus,
 * but the default route holds it back for contracts, so it must not draw a rotation seed.
 */
public final class PatchPriority {

    /**
     * Band weights, spaced so a graded bonus (at most 15) can never lift a patch out of its
     * band.
     */
    private static final int BAND_YIELD = 1000;
    private static final int BAND_DISEASE_FREE = 100;
    private static final int BAND_XP = 50;
    private static final int BAND_EASY_TRAVEL = 10;
    private static final int BAND_ORDINARY = 0;
    private static final int BAND_RESERVED = -1000;

    private PatchPriority() {
    }

    /**
     * This patch's score for this player, higher being a better home for a better seed.
     *
     * <p>Unknown reads as unearned. {@link DiaryTiers#completed} answers UNKNOWN until the
     * flag is reported, and crediting a bonus on that could put the best seed in a patch
     * without the bonus. Under-crediting only costs seed placement.
     *
     * @param patch the patch being scored
     * @param state the player, or null before anything has been reported
     */
    public static int scoreOf(PatchRef patch, PlayerState state) {
        PatchAttributes.Entry entry = PatchAttributes.of(patch);
        if (entry == null) {
            return BAND_ORDINARY;
        }
        if (entry.isReservedForContracts()) {
            return BAND_RESERVED;
        }

        int yield = bestBonus(entry.getYieldTiers(), state);
        if (yield > 0) {
            return BAND_YIELD + yield;
        }
        if (isDiseaseFree(entry, state)) {
            return BAND_DISEASE_FREE;
        }
        int xp = bestBonus(entry.getXpTiers(), state);
        if (xp > 0) {
            return BAND_XP + xp;
        }
        return entry.isEasyTravel() ? BAND_EASY_TRAVEL : BAND_ORDINARY;
    }

    /**
     * Whether this patch is held back for contracts.
     *
     * <p>Asked directly because {@link #scoreOf}'s floor band cannot enforce it alone: the
     * reserved patch is the only patch in its family, so with nothing ranked against it,
     * it would still draw the best herb. Callers use this to exclude it when counting the
     * good seeds a run has to place.
     *
     * <p>Not a function of player state: the reservation is a routing choice, not an
     * earned bonus.
     */
    public static boolean isReservedForContracts(PatchRef patch) {
        PatchAttributes.Entry entry = PatchAttributes.of(patch);
        return entry != null && entry.isReservedForContracts();
    }

    /**
     * The best percentage this player has earned from a graded set of bonuses, or 0.
     *
     * <p>The best rather than the sum: the tiers do not stack. Kandarin Elite <em>is</em>
     * 15%, not 15% on top of Hard's 10%.
     */
    private static int bestBonus(List<PatchAttributes.BonusTier> tiers, PlayerState state) {
        int best = 0;
        for (PatchAttributes.BonusTier tier : tiers) {
            if (DiaryTiers.completed(tier.getDiaryArea(), tier.getDiaryTier(), state) == CapabilityState.HAVE) {
                best = Math.max(best, tier.getPercent());
            }
        }
        return best;
    }

    /** Whether disease cannot touch this patch for this player, by diary or by quest. */
    private static boolean isDiseaseFree(PatchAttributes.Entry entry, PlayerState state) {
        if (entry.isAlwaysDiseaseFree()) {
            return true;
        }
        if (entry.getDiseaseFreeDiaryArea() != null && DiaryTiers.completed(entry.getDiseaseFreeDiaryArea(),
                        entry.getDiseaseFreeDiaryTier(), state) == CapabilityState.HAVE) {
            return true;
        }
        return entry.getDiseaseFreeQuest() != null && state != null
                && state.getQuests().get(entry.getDiseaseFreeQuest()) == QuestStatus.COMPLETED;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.farming.model.FarmingPreferences;
import com.larryfarming.model.PlayerState;
import com.larryfarming.farming.model.RunStop;
import java.util.List;
import lombok.AllArgsConstructor;

/**
 * What one patch is asking for, read against the stop that works it.
 *
 * <p>The runs list and the walkthrough both ask this class, so they cannot disagree about
 * whether a patch has work.
 *
 * <p>The verb comes from the stop's actions ({@link RunStop.StopAction#defaultsFor}), not
 * the patch type: bushes and cacti want a health check <em>and</em> a harvest.
 *
 * <p>A stop naming both does them as separate acts: the check first, then the produce.
 * Only the lumber trees (regular, hardwood and redwood) name a check and no harvest, since
 * logs are a Woodcutting errand.
 */
final class PatchWork {

    private PatchWork() {
    }

    /**
     * The one thing worth doing to this patch, or null when there is nothing — or nothing
     * we can see.
     *
     * <p>Readiness goes through {@link PatchPrediction#isReadyAt}, never a local copy, so
     * this agrees with every other "is it ready" answer. That keeps the
     * {@code LIKELY_READY} window (up to a full growth tick before a farm tick is witnessed)
     * on the side of saying nothing rather than sending the player early.
     */
    static Act at(PatchPrediction seen, RunStop stop, FarmingPreferences prefs, long nowEpochSec) {
        // Never seen is not empty: say nothing.
        if (seen == null || seen.getCrop() == null || seen.isIdle()) {
            return null;
        }
        if (seen.getState() == CropState.DISEASED) {
            return Act.CURE;
        }
        if (seen.getState() == CropState.DEAD) {
            return Act.CLEAR_DEAD;
        }
        // A standing guard crop, such as a white lily, wants nothing while it lives. Checked
        // after disease and death, the states where a guard does need help.
        if (FixedCrops.stands(stop, seen.getCrop(), prefs) && FixedCrops.grows(stop, seen.getCrop())) {
            return null;
        }
        if (!seen.isReadyAt(nowEpochSec)) {
            return null;
        }
        // An anima plant's growth ends in its death, so one whose time has run out is dead,
        // seen or not.
        if (stop.patchType() == PatchType.ANIMA && seen.getCrop() != Crop.WEEDS) {
            return Act.CLEAR_DEAD;
        }

        List<RunStop.StopAction> actions = stop.getActions();
        if (actions.contains(RunStop.StopAction.KILL_HESPORI)) {
            return Act.KILL;
        }
        // The pre-check state is GROWING at max stage, so an unchecked patch asks for its
        // check whatever else the stop can do there.
        if (actions.contains(RunStop.StopAction.CHECK_HEALTH) && seen.getState() == CropState.GROWING) {
            return Act.CHECK;
        }
        // Everything else is picked, including a patch that has had its check. Lumber trees
        // declare no HARVEST and return null here; their replanting is standsEmpty's job.
        //
        // This does not require CropState.HARVESTABLE, which the tracker sets only from a
        // direct sighting, so a crop that finished unobserved still reads GROWING. The
        // readiness check above makes this safe.
        //
        // Crop#isProduce excludes the scarecrow, which ticks like a crop in a flower patch
        // but has nothing to pick.
        return actions.contains(RunStop.StopAction.HARVEST) && seen.getCrop().isProduce() ? Act.HARVEST : null;
    }

    /**
     * Whether this patch is ground waiting for a seed.
     *
     * <p>Weeds mean empty. So does a spent crop: a checked tree, or its stump, is something
     * to clear before a sapling goes in, not a crop to wait for.
     *
     * <p><b>"Empty" means a seed can be spent on it, not that the ground is bare.</b> A
     * checked tree still rooted answers yes. Whether it is worth felling is asked of
     * {@link com.larryfarming.engine.farming.PatchPrediction#isFellable()} by
     * {@code StopSkipRules.stillStandingIn}.
     *
     * <p>A spent crop counts only where the stop replants, and only where picking is not
     * the whole of what it offers: a bush or allotment between pickings is still working.
     * A stop that also checks health (fruit tree, calquat,
     * celastrus) is judged as spent once its fruit is taken. Bushes and cacti check health as
     * well, but a picked one keeps growing, so it is never spent.
     *
     * <p>{@link #at} has the last word, because state alone cannot separate spent from
     * waiting: a hespori ready to fight decodes HARVESTABLE with no HARVEST action, and a
     * fruit tree with fruit back reports work.
     */
    static boolean standsEmpty(PatchPrediction seen, RunStop stop, FarmingPreferences prefs, long nowEpochSec) {
        // Unseen is not empty; treating it as empty would drop a stop with real work.
        if (seen == null || seen.getCrop() == null) {
            return false;
        }
        if (seen.getCrop() == Crop.WEEDS) {
            return true;
        }
        boolean pickingIsAllItOffers = stop.getActions().contains(RunStop.StopAction.HARVEST)
                        && (!stop.getActions().contains(RunStop.StopAction.CHECK_HEALTH) || growsAbushOrCactus(stop));
        if (!stop.isPlanting() || seen.getState() != CropState.HARVESTABLE || pickingIsAllItOffers) {
            return false;
        }
        return at(seen, stop, prefs, nowEpochSec) == null;
    }

    /**
     * Whether this patch holds a grown bush or cactus to dig up this visit, so a fresh one
     * goes in after the picking.
     *
     * <p>Replanted every visit, its own crop included. A fresh plant pays its health check
     * again, which is most of a bush's or cactus's experience; picking a kept one pays only
     * the harvest. A whiteberry bush checks for 437.5 and picks for 29 a berry, and it grows
     * in 160 minutes, as long as the two herb runs between visits. A potato cactus checks
     * for 230 and grows in 70.
     *
     * <p>Grown means growing done, checked or not: a bush still filling out keeps its patch
     * until then, and a diseased one wants curing, not digging up.
     *
     * <p>Only where the next crop can go in: the player has the Farming level and is not
     * known to be out of its seed. Otherwise digging up a bearing bush gains nothing.
     */
    static boolean comesOut(PatchPrediction seen, RunStop stop, FarmingPreferences prefs, PlayerState player) {
        if (seen == null || seen.getCrop() == null || seen.isIdle() || !growsAbushOrCactus(stop)
                || !stop.isFixedCrop() || !stop.isPlanting()) {
            return false;
        }
        CropState state = seen.getState();
        if (state == CropState.DEAD || state == CropState.DISEASED || StopSkipRules.isStillGrowing(seen)) {
            return false;
        }
        Crop next = FixedCrops.cropFor(stop, prefs, player);
        CropData data = next == null ? null : CropData.forCrop(next);
        return data != null && !FixedCrops.belowLevel(player, data) && !SeedSelector.definitelyOutOf(next, player, data.getSeedsPerPatch());
    }

    /**
     * Whether a bush or cactus grows here. Both are checked, then picked again and again,
     * so a picked one is never spent ground; it comes out when it dies or by
     * {@link #comesOut}.
     */
    private static boolean growsAbushOrCactus(RunStop stop) {
        PatchType type = stop.patchType();
        return type == PatchType.BUSH || type == PatchType.CACTUS;
    }

    /**
     * What a patch is waiting for, most urgent first. The order is the ranking readers
     * walk, so a diseased patch outranks a harvest at the same arrival.
     */
    @AllArgsConstructor
    enum Act {
        CURE("Cure"),
        // Not DIG_UP, which StopAction uses for taking a stump out after a check.
        CLEAR_DEAD("Clear dead"),
        KILL("Kill"),
        CHECK("Check"),
        HARVEST("Harvest");

        /** The act as a row's leading verb; the row adds the crop and the patch count. */
        final String verb;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.model.*;

/**
 * Which stops the player has switched off, and which runs that empties out entirely.
 *
 * <p>Switching a crop off silences it rather than skipping it with a reason: the stop
 * leaves the walkthrough, the run leaves the list, and the patch leaves the timers. Dropping
 * a site from a run does the same.
 *
 * <p>The scheduler, the advice builder and the patch timers all read the rule here, so a
 * run, its walkthrough and the timers always agree about which patches exist.
 */
public final class PlantingGate {

    private PlantingGate() {
    }

    /**
     * Whether this stop should vanish.
     *
     * <p>Contracts are always exempt: crop preferences cover the player's own runs, and
     * silencing Guildmaster Jane's request would leave a contract that cannot be completed.
     */
    static boolean silences(FarmingRun run, RunStop stop, FarmingPreferences prefs) {
        if (run.getId() == RunId.CONTRACT) {
            return false;
        }
        // A run switched off takes every stop with it, woven-in extras included.
        if (silencesWholeRun(run, prefs)) {
            return true;
        }
        if (dropsSite(stop, prefs)) {
            return true;
        }
        return stop.isFixedCrop() && FixedCrops.ticked(stop, prefs).isEmpty();
    }

    /**
     * Whether the player has dropped this stop's site from their runs. A farm's allotments
     * and flower patch go with its herb site, as they are worked only beside it.
     */
    private static boolean dropsSite(RunStop stop, FarmingPreferences prefs) {
        String site = FarmingCatalogue.siteKey(stop.primaryPatch());
        return site != null && !prefs.visits(site);
    }

    /**
     * Whether the player has switched this whole run off.
     *
     * <p>A run is defined by the crop it exists to grow, so switching that crop off ends
     * the run. The herb run's woven-in extras (snape grass, potato cactus and the like) are
     * secondaries of that run and go with it.
     */
    static boolean silencesWholeRun(FarmingRun run, FarmingPreferences prefs) {
        if (run.getId() == RunId.CONTRACT) {
            return false;
        }
        // Every site dropped: the woven-in extras are no reason to go on their own. A site the
        // account is seen unable to reach counts as dropped, so Harmony before the elite
        // Morytania diary cannot keep a run open alone. Asked of the family, not the variant,
        // so every spellbook's run agrees. False for a family with no site switches.
        if (prefs.dropsEverySiteOf(FarmingCatalogue.siteKeys(run.getId()))) {
            return true;
        }
        // A run naming its own seeds is defined by them — every tree of the family unticked,
        // or the single crop of a one-crop run switched off.
        if (run.getSeedPatchType() != null) {
            return SeedSelector.plantingLadder(prefs, run.getSeedPatchType()).isEmpty();
        }
        PatchType rotation = rotationFamilyOf(run);
        if (rotation != null) {
            return prefs.isFamilyOff(rotation);
        }
        // Left: runs of fixed-crop stops (hespori, seaweed), off once all of them are.
        boolean plants = false;
        for (RunStop stop : run.getStops()) {
            if (!stop.isPlanting() || !stop.isFixedCrop()) {
                continue;
            }
            plants = true;
            if (!FixedCrops.ticked(stop, prefs).isEmpty()) {
                return false;
            }
        }
        return plants;
    }

    /**
     * The patch family this run's seed rotation fills, or null when it has no rotation.
     *
     * <p>Read off the first planting stop with no fixed crop, rather than the run id. Only
     * called for runs that name no seeds of their own, so such a stop draws on the
     * rotation. Woven-in extras name their crop and are skipped.
     */
    static PatchType rotationFamilyOf(FarmingRun run) {
        for (RunStop stop : run.getStops()) {
            if (stop.isPlanting() && !stop.isFixedCrop()) {
                return stop.patchType();
            }
        }
        return null;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.engine.farming.PatchType;
import com.larryfarming.farming.model.RunStop;
import com.larryfarming.model.PlayerState;
import java.util.Map;
import lombok.AllArgsConstructor;

/**
 * What a farmer takes to protect a stop's patches, planned only from what the player already
 * owns.
 *
 * <p>Protection is worth paying for only with the payment to spare, so a player short of it
 * is never sent to gather it. Owned counts the bank, as the bag does: the trip starts at a
 * bank, so a banked payment comes along.
 *
 * <p>Paid per patch planted this visit. A patch left growing was paid for when it went in,
 * and a player owning one patch's fee of two protects one.
 */
final class Protection {

    /** Fossil Island's currency. Stackable, so any amount takes one slot. */
    static final int NUMULITE = 21555;

    /** Mernia's fee for one seaweed patch. */
    private static final int NUMULITE_PER_SEAWEED_PATCH = 200;

    private static final Map<PatchType, Fee> PER_PATCH = Map.of(PatchType.SEAWEED,
            new Fee("Mernia", NUMULITE, "Numulite", NUMULITE_PER_SEAWEED_PATCH, 1));

    private Protection() {
    }

    /** One farmer's payment: who takes it, what, how many, and for how many patches. */
    @AllArgsConstructor
    static final class Fee {
        final String farmer;
        final int itemId;
        final String name;
        final int amount;
        final int patches;
    }

    /**
     * What this stop pays its farmer this visit, or null where it pays nobody: the stop does
     * not ask to, no fee is known for its patch type, nothing goes in, or the player owns too
     * little for one patch.
     *
     * @param planting how many of the stop's patches are planted this visit
     */
    static Fee paymentAt(RunStop stop, int planting, PlayerState state) {
        if (planting <= 0 || !stop.getActions().contains(RunStop.StopAction.PAY_PROTECTION)) {
            return null;
        }
        PatchType type = stop.patchType();
        Fee each = type == null ? null : PER_PATCH.get(type);
        if (each == null) {
            return null;
        }
        int affordable = ItemCounts.countOwned(state, each.itemId, null) / each.amount;
        int patches = Math.min(Math.min(planting, stop.getPatches().size()), affordable);
        return patches == 0 ? null : new Fee(each.farmer, each.itemId, each.name, each.amount * patches, patches);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.farming.detection.CapabilityState;
import com.larryfarming.farming.detection.DiaryTiers;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.model.Skill;
import java.util.*;

/**
 * Whether an {@link UnlockGate} lets a run or stop into this player's game at all.
 *
 * <p>Unlike a travel rung in {@link com.larryfarming.farming.detection.CapabilityResolver}, a
 * gate decides whether a patch is part of the account at all, so it keeps its own
 * three-valued certainty rather than degrading to a best guess.
 *
 * <p>Reads base skill levels. Where the gate names a boosted floor
 * ({@link UnlockGate#getBoostedFromLevel()}), it also checks whether the player owns the
 * boosting item; see {@code boostState}.
 *
 * <p>{@link UnlockGate#getRecommendedFromLevel()} remains advisory and plays no part.
 */
public final class RunAvailability {

    private RunAvailability() {
    }

    /**
     * Whether the gate is satisfied. Three-valued: an unreported diary or skill is
     * UNKNOWN, not LACK. A gate naming both a skill and a diary needs both; one certain
     * shortfall gives LACK, and HAVE mixed with UNKNOWN gives UNKNOWN. A null gate is HAVE.
     */
    public static CapabilityState of(UnlockGate gate, PlayerState state) {
        if (gate == null) {
            return CapabilityState.HAVE;
        }
        List<CapabilityState> parts = new ArrayList<>(2);
        if (gate.getSkill() != null) {
            parts.add(skillState(gate, state));
        }
        if (gate.getDiaryArea() != null) {
            parts.add(DiaryTiers.completed(gate.getDiaryArea(), gate.getDiaryTier(), state));
        }
        // An empty list is an empty gate: available from the start.
        return parts.isEmpty() ? CapabilityState.HAVE : CapabilityState.all(parts);
    }

    /**
     * The gate a run actually puts in front of this player.
     *
     * <p>A run naming its own seeds opens at the Farming level of the cheapest crop the
     * player has ticked for it: below that it can plant nothing, and from there it plants
     * something. So a player who ticks oak has a tree run at 15, and one who ticks only
     * magic has none before 75.
     *
     * <p>The catalogue's gate answers for every other run, and for a seed run with nothing
     * ticked, which {@link PlantingGate#silencesWholeRun} switches off regardless.
     */
    public static UnlockGate gateOf(FarmingRun run, FarmingPreferences prefs) {
        UnlockGate written = run.getUnlock();
        if (prefs == null || run.getSeedPatchType() == null || !isPlainFarmingGate(written)) {
            return written;
        }
        int cheapest = Integer.MAX_VALUE;
        for (Crop crop : SeedSelector.plantingLadder(prefs, run.getSeedPatchType())) {
            cheapest = Math.min(cheapest, CropData.forCrop(crop).getFarmingLevel());
        }
        return cheapest == Integer.MAX_VALUE ? written : UnlockGate.skill(Skill.FARMING, cheapest);
    }

    /**
     * A Farming level and nothing else: no diary, boost or recommendation, so a level can
     * replace it whole.
     */
    private static boolean isPlainFarmingGate(UnlockGate gate) {
        return gate.getSkill() == Skill.FARMING && gate.getDiaryArea() == null
                && !gate.isBoostable() && gate.getRecommendedFromLevel() == 0;
    }

    /**
     * The base level against {@link UnlockGate#getLevel()}. UNKNOWN when the skill is
     * missing from the state, which only a profile built without its constructor (by Gson,
     * for one) can be: {@link PlayerState}'s constructor seeds every skill at level 1.
     */
    private static CapabilityState skillState(UnlockGate gate, PlayerState state) {
        if (state == null || !state.getSkills().containsKey(gate.getSkill())) {
            return CapabilityState.UNKNOWN;
        }
        int level = state.getSkillLevel(gate.getSkill());
        if (level >= gate.getLevel()) {
            return CapabilityState.HAVE;
        }
        if (gate.isBoostable() && level >= gate.getBoostedFromLevel()) {
            return boostState(gate, state);
        }
        return CapabilityState.LACK;
    }

    /**
     * Whether a player short of the gate could raise themselves over it today.
     *
     * <p>Only boosts from an owned item count, such as a garden pie for the Farming Guild
     * door. An owned boost item gives HAVE; an unseen bank gives UNKNOWN rather than LACK.
     */
    private static CapabilityState boostState(UnlockGate gate, PlayerState state) {
        int[] boosts = BOOSTS_FOR.get(gate.getSkill());
        // A skill with no modelled boost answers on the base level alone. The Lunar herb
        // run's 96 Magic gate is deliberately unboosted: the run casts throughout, so a
        // short boost does not make it the player's. A door needs one boosted step.
        if (boosts == null) {
            return CapabilityState.LACK;
        }
        for (int itemId : boosts) {
            if (ItemCounts.countOwned(state, itemId, null) > 0) {
                return CapabilityState.HAVE;
            }
        }
        return state.getBankLastSeen() == null ? CapabilityState.UNKNOWN : CapabilityState.LACK;
    }

    /**
     * What raises a skill far enough to matter to a gate, by skill.
     *
     * <p>Only Farming, and only the garden pie, whole and half (each bite boosts). A pie
     * gives +3, matching every boosted floor in the catalogue; a gate needing a different
     * margin needs its own entry.
     */
    private static final Map<Skill, int[]> BOOSTS_FOR = Map.of(Skill.FARMING, new int[]{7178, 7180});

    /**
     * One player-facing clause naming what stands between this player and the gate, or
     * the empty string once it is satisfied. Names every part not definitely held, so an
     * unresolved diary reads the same as a missing one.
     */
    public static String shortfall(UnlockGate gate, PlayerState state) {
        if (gate == null || of(gate, state) == CapabilityState.HAVE) {
            return "";
        }
        List<String> needs = new ArrayList<>(2);
        if (gate.getSkill() != null && skillState(gate, state) != CapabilityState.HAVE) {
            needs.add(gate.getLevel() + " " + gate.getSkill().getDisplayName());
        }
        if (gate.getDiaryArea() != null && DiaryTiers.completed(gate.getDiaryArea(), gate.getDiaryTier(), state) != CapabilityState.HAVE) {
            needs.add("the " + gate.getDiaryTier().toLowerCase(Locale.ROOT) + " " + gate.getDiaryArea() + " diary");
        }
        return needs.isEmpty() ? "" : "needs " + String.join(" and ", needs);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.FarmingWorldMap;
import com.larryfarming.engine.farming.PatchType;
import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.detection.*;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.FarmingSkipReason;
import java.util.*;
import lombok.Value;

/**
 * Turns each stop's ranked routes into a decision: for each stop on a run, the best
 * route this player can take, or the catalogue's reason for dropping the patch.
 */
public final class RunPlanner {

    private final CapabilityResolver resolver;

    /**
     * The same resolver with the player's position withheld, for every stop but the one
     * they are travelling to.
     */
    private final CapabilityResolver blind;

    public RunPlanner(CapabilityResolver resolver) {
        this.resolver = resolver;
        this.blind = resolver.blindToPosition();
    }

    /**
     * The resolver a stop may be asked with.
     *
     * <p>Position answers only for the stop the player is heading to. A route that is free
     * from where they stand now is not free from where they will stand twenty minutes into
     * the trip, so answering a later stop from position would drop a teleport they need
     * from the packing list. See {@link CapabilityResolver#blindToPosition()}.
     */
    private CapabilityResolver resolverFor(boolean mayStandHere) {
        return mayStandHere ? resolver : blind;
    }

    /**
     * Plans every stop on a run, in the catalogue's order.
     *
     * <p>Stops are planned in sequence because a later rung can depend on an earlier stop
     * being visited: the Taverley route ends with a walk from the Falador tree
     * patch, which is only free if Falador is on the day's itinerary.
     *
     * <p>The player's position is spent on the first arrival that takes it. By the next
     * journey they are somewhere else. See {@link Allowance}.
     */
    public List<StopPlan> plan(FarmingRun run, PlayerState state) {
        List<StopPlan> plans = new ArrayList<>();
        Map<PatchRef, CapabilityState> reached = new LinkedHashMap<>();
        Allowance allowance = new Allowance();
        for (RunStop stop : run.getStops()) {
            // A stop gated behind something the player definitely lacks (Harmony Island
            // behind the Elite Morytania diary) is not on their route yet, so it drops out
            // instead of becoming a SKIP or UNREACHABLE row. An unresolved gate leaves the
            // stop in place.
            if (RunAvailability.of(stop.getGate(), state) == CapabilityState.LACK) {
                continue;
            }
            StopPlan plan = planStop(stop, state, reached, allowance.covers(stop));
            plans.add(plan);
            allowance.spendOn(plan);
            // Recorded with the visit's confidence, so a rung that leans on an uncertain
            // stop inherits its doubt.
            stood(reached, plan);
        }
        return Collections.unmodifiableList(plans);
    }

    /**
     * Which stops may be routed from where the player is standing, over one walk of the
     * stops.
     *
     * <p><b>The allowance belongs to an arrival, not to a stop.</b> Catherby's herb patch,
     * flower patch and allotment are three stops reached on one teleport. Planning the
     * siblings blind would pack a teleport the lead stop already got free. So every stop
     * at the first arrival the player travels to gets the allowance, and every stop after
     * that arrival does not.
     *
     * <p>Only a visit spends position: a skipped stop leaves the player where they were.
     * Rebuilt per walk instead of recorded on the plan, so a stop dropped later for what is
     * in its ground hands the allowance to whichever stop inherits the walk.
     */
    public static final class Allowance {

        private Arrival spentAt;

        /** Whether this stop may be routed from where the player stands. */
        public boolean covers(RunStop stop) {
            return spentAt == null || spentAt == stop.getArrival();
        }

        /**
         * Spends the allowance on this plan's arrival if it is the first visit. A skipped
         * stop leaves the player where they were and spends nothing.
         */
        public void spendOn(StopPlan plan) {
            if (spentAt == null && plan.isVisit()) {
                spentAt = plan.getStop().getArrival();
            }
        }
    }

    /**
     * Records that a plan's patches have been stood at, with the plan's confidence. Shared
     * with the trip, which must record visits the same way.
     *
     * <p>A plan that is not a visit records nothing: the resolver reads an absent patch as
     * {@code LACK}. A patch recorded twice keeps the surer visit, so the result does not
     * depend on caller order.
     */
    public static void stood(Map<PatchRef, CapabilityState> reached, StopPlan plan) {
        if (!plan.isVisit()) {
            return;
        }
        for (PatchRef patch : plan.getStop().getPatches()) {
            reached.merge(patch, plan.getConfidence(), (already, now) -> CapabilityState.any(List.of(already, now)));
        }
    }

    /**
     * Picks a route for one stop.
     *
     * <p>Takes the first rung the player certainly has. Failing that, it takes the best
     * rung that <em>might</em> work. It never skips on uncertainty: the things we cannot
     * see are the things a well-equipped player most likely owns, and telling them to skip
     * a reachable patch is the worst mistake this can make. Only when every rung is a
     * definite no does the chain's terminal decision apply.
     *
     * <p>One uncertainty is never guessed: a rung that states a fact about the account,
     * such as "with your house in Hosidius" (see {@link TravelOption#isCertainOnly()}).
     * When that rung is the only maybe left, the stop has no route yet rather than a skip,
     * and the row says what is unread: "not sure where your house is".
     *
     * @param mayStandHere true for the stop the player is travelling to, so a route free
     *     from where they stand is offered; false for every later stop
     */
    public StopPlan planStop(RunStop stop, PlayerState state, Map<PatchRef, CapabilityState> reached, boolean mayStandHere) {
        return planStop(stop, state, reached, mayStandHere, null);
    }

    /**
     * The same, for a stop whose route can begin where the previous stop left the player.
     *
     * @param start what the previous stop already gives this one, or null for nothing
     */
    StopPlan planStop(RunStop stop, PlayerState state, Map<PatchRef, CapabilityState> reached, boolean mayStandHere, Start start) {
        StopPlan shutOut = shutOut(stop, state);
        if (shutOut != null) {
            return shutOut;
        }
        CapabilityResolver asked = resolverFor(mayStandHere);
        StopPlan routed = routeBy(stop, stop.getTravel(), start, state, reached, asked);
        if (routed != null) {
            return routed;
        }
        StopPlan unread = waitingOnAfact(stop, state, reached, asked);
        return unread != null ? unread : giveUp(stop, state, asked);
    }

    /**
     * A visit to the stop by the first rung of this ladder the player certainly has, else
     * by the best rung that might work, or null when every rung is a definite no.
     */
    private StopPlan routeBy(RunStop stop, List<TravelOption> travel, Start start, PlayerState state,
            Map<PatchRef, CapabilityState> reached, CapabilityResolver asked) {
        List<TravelOption> ladder = ladderFor(travel, start, state, reached, asked);
        TravelOption certain = firstCertain(ladder, state, reached, asked);
        if (certain != null) {
            return visit(stop, certain, CapabilityState.HAVE, state, reached, asked);
        }
        TravelOption guess = bestGuess(ladder, state, reached, asked);
        return guess == null ? null : visit(stop, guess, CapabilityState.UNKNOWN, state, reached, asked);
    }

    /**
     * No route yet, because the one rung that might hold states an account fact not read
     * yet. Null when no such rung is in doubt.
     *
     * <p>Its confidence is {@code UNKNOWN}, not {@code LACK}: the rung may well hold once the
     * fact is read, so the runs list must not report the run as having no route.
     */
    private static StopPlan waitingOnAfact(RunStop stop, PlayerState state,
            Map<PatchRef, CapabilityState> reached, CapabilityResolver asked) {
        for (TravelOption option : stop.getTravel()) {
            if (!option.isCertainOnly() || asked.evaluate(option.getRequires(), state, reached) != CapabilityState.UNKNOWN) {
                continue;
            }
            return new StopPlan(stop, StopPlan.Outcome.UNROUTED, null, CapabilityState.UNKNOWN, unreadFact(option, state, asked),
                    FarmingSkipReason.NO_ROUTE_LISTED, 0L, Collections.emptySet(), null);
        }
        return null;
    }

    /**
     * How to reach a place when the visit works several of its patches, or null when the
     * arrival has no ranking of its own or the player can take none of its rungs.
     *
     * <p>A stop's chain ranks routes by their cost to reach <em>that</em> patch. Where an
     * arrival's patches are far apart, the best route to one is the worst to the other, so
     * {@code Arrivals} carries a third chain ranked for the pair. The plan comes back on
     * the lead stop; only the rung, the sentence and the teleport are the arrival's.
     *
     * <p>Returns null rather than a give-up when nothing resolves, because each stop's own
     * chain still has its own terminal. Falling back is the caller's job.
     *
     * @param mayStandHere as on {@link #planStop(RunStop, PlayerState, Map, boolean)}
     * @param start as on {@link #planStop(RunStop, PlayerState, Map, boolean, Start)}
     */
    StopPlan planArrival(RunStop lead, PlayerState state, Map<PatchRef, CapabilityState> reached, boolean mayStandHere, Start start) {
        return routeBy(lead, FarmingCatalogue.combinedRoute(lead.getArrival()), start, state, reached, resolverFor(mayStandHere));
    }

    /**
     * Part of a journey the previous stop already made, such as standing beside a fairy
     * ring: the part reads as held on every rung asking for it, and the walk from there
     * opens the rung's sentence.
     */
    @Value
    static class Start {
        Requirement granted;
        /** A whole sentence, ending in ". ", which the rung's own sentence follows. */
        String walk;
        /** The walk's length in tiles, which a started rung counts in place of an approach. */
        int tiles;
    }

    /**
     * The ladder as this player, starting from {@code start}, climbs it: each rung ranked by
     * its whole walk for this account ({@link #ranked}).
     */
    static List<TravelOption> ladderFor(List<TravelOption> ladder, Start start, PlayerState state,
            Map<PatchRef, CapabilityState> reached, CapabilityResolver asked) {
        List<TravelOption> from = ladderFrom(ladder, start);
        // Planning runs on every snapshot. With no start and no approach, every figure is the
        // catalogue's own, so its ranking stands and ranking again would change nothing.
        // A started rung has a walk the catalogue could not know, so a start always re-ranks.
        return start == null && !asksForAnApproach(from) ? from : ranked(from, state, reached, asked);
    }

    /** Whether any rung leaves out an approach whose walk this account decides. */
    private static boolean asksForAnApproach(List<TravelOption> ladder) {
        for (TravelOption rung : ladder) {
            if (!rung.hasWalkFigure()) {
                continue;
            }
            for (Approach approach : FarmingCatalogue.approaches()) {
                if (rung.getRequires().contains(approach.getWay())) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * The ladder as a player starting from {@code start} climbs it. A rung waiting for a
     * start ({@link TravelOption#isStartOnly()}) stays on only when this start grants it.
     * A started rung counts the start's walk in place of its approach.
     */
    private static List<TravelOption> ladderFrom(List<TravelOption> ladder, Start start) {
        List<TravelOption> from = new ArrayList<>(ladder.size());
        for (TravelOption rung : ladder) {
            TravelOption started = start == null ? rung : rung.startingFrom(start.getGranted(), start.getWalk(), start.getTiles());
            if (!started.isStartOnly()) {
                from.add(started);
            }
        }
        return from;
    }

    /**
     * The ladder ranked by walk for this account ({@link RungOrder}). The catalogue has
     * already ranked every rung whose walk is the same for everyone. A rung asking for an
     * approach ({@link FarmingCatalogue#approaches()}) adds the walk of the way in this player
     * takes, the one the bag packs for, and costs the dearer of the two. So whether a fairy
     * ring rung ranks above a teleport depends on whether the player reaches a ring by a house
     * ring or by a Salve graveyard tablet.
     *
     * <p>A rung whose every way in is a definite no has no total, so it keeps its place
     * among the rest: it cannot be taken.
     */
    private static List<TravelOption> ranked(List<TravelOption> ladder, PlayerState state,
            Map<PatchRef, CapabilityState> reached, CapabilityResolver asked) {
        if (ladder.size() < 2) {
            return ladder;
        }
        int[] walks = new int[ladder.size()];
        TravelOption.Cost[] costs = new TravelOption.Cost[ladder.size()];
        for (int i = 0; i < walks.length; i++) {
            TravelOption rung = ladder.get(i);
            walks[i] = rung.getWalk();
            costs[i] = rung.getCost();
            if (!rung.hasWalkFigure()) {
                continue;
            }
            for (Approach approach : FarmingCatalogue.approaches()) {
                if (!rung.getRequires().contains(approach.getWay())) {
                    continue;
                }
                Approach.Leg leg = approach.legFor(asked.takenBranch(approach.getWay(), state, reached));
                if (leg == null) {
                    walks[i] = TravelOption.UNMEASURED;
                    break;
                }
                walks[i] += leg.getWalk();
                costs[i] = RungOrder.dearer(costs[i], leg.getCost());
            }
        }
        return RungOrder.rank(ladder, new RungOrder.Figures() {
            @Override
            public int walk(int rung) {
                return walks[rung];
            }

            @Override
            public TravelOption.Cost cost(int rung) {
                return costs[rung];
            }
        });
    }

    /** The resolver every stop is asked with, before position is withheld. */
    CapabilityResolver resolver() {
        return resolver;
    }

    /** The first rung on this ladder the player certainly holds, or null. */
    private TravelOption firstCertain(List<TravelOption> ladder, PlayerState state,
            Map<PatchRef, CapabilityState> reached, CapabilityResolver asked) {
        for (TravelOption option : ladder) {
            if (asked.evaluate(option.getRequires(), state, reached) == CapabilityState.HAVE) {
                return option;
            }
        }
        return null;
    }

    /**
     * The detector's own words for the unread fact, such as "not sure where your house is",
     * rather than the resolver's generic "not sure whether you have".
     */
    private static String unreadFact(TravelOption option, PlayerState state, CapabilityResolver asked) {
        for (Capability capability : option.getRequires().leafCapabilities()) {
            if (asked.resolve(capability, state).getState() != CapabilityState.UNKNOWN) {
                continue;
            }
            CapabilityVerdict own = CapabilitySources.resolve(capability, state);
            if (own.getState() == CapabilityState.UNKNOWN) {
                return own.getBecause();
            }
        }
        String shortfall = asked.explainShortfall(option.getRequires(), state);
        return shortfall.isEmpty() ? "no route you can use right now" : shortfall;
    }

    /**
     * The best rung that merely <em>might</em> work, or null when every one is a definite no.
     *
     * <p>A rung whose only doubt is an earlier stop on this run, itself routed on a guess,
     * beats a rung with a doubt of its own. The player already sees the inherited doubt on
     * an earlier row, and resolving it answers both. Taverley shows why: with the bank
     * unread, its chain ranks an uncertain ring of dueling and balloon above "run north from
     * the Falador tree patch", and the free walk should win whenever Falador was a guess.
     *
     * <p>A rung marked {@link TravelOption#isCertainOnly()} is never a guess. Its sentence
     * states a fact about the account, which is wrong advice until the fact is read.
     *
     * <p>Chain order decides everything else, because it is the route ranking.
     */
    private TravelOption bestGuess(List<TravelOption> ladder, PlayerState state,
            Map<PatchRef, CapabilityState> reached, CapabilityResolver asked) {
        Map<PatchRef, CapabilityState> asIfSettled = asIfThoseVisitsHold(reached);
        TravelOption independent = null;
        for (TravelOption option : ladder) {
            if (option.isCertainOnly()) {
                continue;
            }
            if (asked.evaluate(option.getRequires(), state, reached) != CapabilityState.UNKNOWN) {
                continue;
            }
            if (asked.evaluate(option.getRequires(), state, asIfSettled) == CapabilityState.HAVE) {
                // Certain but for the guess it inherited, so there is nothing else to ask.
                return option;
            }
            if (independent == null) {
                independent = option;
            }
        }
        return independent;
    }

    /**
     * The reached set with every uncertain visit read as though it had happened, used to
     * separate a doubt a rung inherited from one it owns. Absent patches stay absent: a
     * stop the run is not making is a {@code LACK}, not a maybe.
     */
    private static Map<PatchRef, CapabilityState> asIfThoseVisitsHold(Map<PatchRef, CapabilityState> reached) {
        if (reached == null || reached.isEmpty()) {
            return reached;
        }
        Map<PatchRef, CapabilityState> settled = new LinkedHashMap<>(reached);
        settled.replaceAll((patch, held) -> held == CapabilityState.UNKNOWN ? CapabilityState.HAVE : held);
        return settled;
    }

    /**
     * A stop the player cannot work whatever route they hold, or null when the place is
     * open to them or we cannot tell.
     *
     * <p>Checked before the chain. Weiss is reached by an icy basalt, whose requirement
     * knows nothing of the fire of nourishment the patch needs, so the chain alone would
     * never report the gate. Only a certain {@code LACK} shuts a stop out, and the reason
     * comes from the gate rather than from a rung.
     */
    private StopPlan shutOut(RunStop stop, PlayerState state) {
        if (stop.getAccessGate() == null) {
            return null;
        }
        CapabilityVerdict access = resolver.resolve(stop.getAccessGate(), state);
        if (access.getState() != CapabilityState.LACK) {
            return null;
        }
        // The gate's own words, unprefixed: the heading already says "no way in".
        return new StopPlan(stop, StopPlan.Outcome.UNREACHABLE, null, CapabilityState.LACK, access.getBecause(),
                FarmingSkipReason.NO_ROUTE, 0L, Collections.emptySet(), null);
    }

    /**
     * A settled stop, with the teleport picked before the instruction is written: a rung
     * named by its destination opens its instruction with whatever the player casts or
     * breaks.
     *
     * <p>A rung that only <em>leans</em> on a place also gets its teleport worked out, so
     * the means is packed. "Fairy ring ALQ" is one: its requirement accepts a Salve
     * graveyard teleport as a way to a ring. It keeps its own wording, because
     * {@link TravelOption#instructionFor} reads the rung's declared destination and naming
     * the means here cannot rewrite the sentence.
     */
    private StopPlan visit(RunStop stop, TravelOption option, CapabilityState confidence,
            PlayerState state, Map<PatchRef, CapabilityState> reached, CapabilityResolver asked) {
        Destination arriveAt = option.getDestination() != null ? option.getDestination()
                : asked.reliedOnDestination(option.getRequires(), state, reached);
        TeleportPlanner.Choice arriving = arriveAt == null ? null : asked.teleportFor(option.getRequires(), arriveAt, state);
        // Null for a player already standing there. CarryPlanner counts runes and tablets
        // from this, so null keeps the teleport off the packing list.
        TeleportMeans means = arriving == null ? null : arriving.getMeans();
        // Only a certainty with no means says "you are there". An unread bank also returns
        // no means while its rung is still the best guess, so a null means alone must not
        // read as arrival.
        boolean alreadyThere = arriving != null && means == null && arriving.getState() == CapabilityState.HAVE;
        return new StopPlan(stop, StopPlan.Outcome.VISIT, option, confidence,
                sayWhatItLeansOn(option.instructionFor(means, alreadyThere), option, reached),
                null, 0L, asked.reliedOn(option.getRequires(), state, reached), means);
    }

    /**
     * The route sentence, with the stop it depends on named when that stop is itself a guess.
     *
     * <p>A hedged row is drawn in orange. Most routes name their own doubt: in "House
     * spirit tree to the Grand Tree" the house tree is right there. A route leaning on an
     * earlier stop does not: "Run west to the Stronghold spirit tree" says nothing about the
     * Grand Tree visit it assumes. The sentence states the dependency; it does not ask the
     * player whether that stop will happen.
     */
    private static String sayWhatItLeansOn(String because, TravelOption option, Map<PatchRef, CapabilityState> reached) {
        if (reached == null || because == null) {
            return because;
        }
        for (PatchRef patch : option.getRequires().leafPatches()) {
            if (reached.get(patch) != CapabilityState.UNKNOWN) {
                continue;
            }
            String name = nameOf(patch);
            // Don't name the patch twice when the rung already does ("Run north-west from
            // the Falador tree patch").
            // A rung written as sentences gets a sentence; a bare clause gets a clause.
            if (because.endsWith(".")) {
                return because + " This assumes you stopped at the " + name + " patch.";
            }
            return because.contains(name) ? because + ", if you stopped there" : because + ", if you stopped at the " + name + " patch";
        }
        return because;
    }

    /**
     * A patch as the player would say it: "Falador tree", "Gnome Stronghold fruit tree".
     * {@code PatchRef.getLabel()} prints the enum spelling ("Falador TREE"), and
     * {@code StopRowWriter.patchLabel} drops the location, which this sentence needs.
     */
    private static String nameOf(PatchRef patch) {
        FarmingWorldMap.PatchDef def = patch.resolve();
        if (def == null) {
            return patch.getLabel();
        }
        // Hespori is a name, so it keeps its capital.
        String kind = def.getType() == PatchType.HESPORI ? "Hespori"
                : StopRowWriter.kindOf(def.getType());
        return def.getLocation() + " " + kind;
    }

    /**
     * What the chain says to do when the player has none of the routes.
     *
     * <p>The three terminals mean different things. "Drop it" means the patch is reachable
     * but not worth the walk. "No alternative" means the stop is shut. No terminal means
     * the chain gives no advice, which says nothing about the patch. All three carry the
     * bare shortfall, and the heading is written from {@link FarmingSkipReason}.
     */
    private StopPlan giveUp(RunStop stop, PlayerState state, CapabilityResolver asked) {
        // Lost for want of a ring when a ring rung would reach the stop but for a way to stand
        // at a ring. Not when the network itself is shut (Fairytale II, or no staff): that
        // rung reads LACK even with the approach granted, so its own reason stands.
        boolean noRing = withAwayToAring(stop, state, asked) != CapabilityState.LACK;
        String shortfall = noRing ? NO_RING_BECAUSE : shortfallOf(stop, state, asked);
        StopPlan.Outcome outcome;
        FarmingSkipReason reason;
        switch (stop.getTerminal()) {
            case SKIP_PATCH:
                outcome = StopPlan.Outcome.SKIP;
                reason = FarmingSkipReason.NOT_WORTH_TRIP;
                break;
            case NO_ALTERNATIVE:
                outcome = StopPlan.Outcome.UNREACHABLE;
                reason = FarmingSkipReason.NO_ROUTE;
                break;
            default:
                outcome = StopPlan.Outcome.UNROUTED;
                reason = FarmingSkipReason.NO_ROUTE_LISTED;
        }
        return new StopPlan(stop, outcome, null, CapabilityState.LACK, shortfall,
                noRing ? FarmingSkipReason.NO_FAIRY_RING_ROUTE : reason, 0L, Collections.emptySet(), null);
    }

    private static final String NO_RING_BECAUSE = "nothing you own and have switched on reaches a fairy ring. " + "See Travel";

    /**
     * How surely this stop's fairy ring rungs would reach it, given a way to stand at a ring:
     * the best of them with that approach granted, or LACK when it has none. A rung that
     * states an account fact is left out, as the planner never guesses one.
     */
    static CapabilityState withAwayToAring(RunStop stop, PlayerState state, CapabilityResolver asked) {
        Requirement approach = FarmingCatalogue.toAfairyRing();
        List<CapabilityState> rungs = new ArrayList<>();
        for (TravelOption option : stop.getTravel()) {
            if (!option.isCertainOnly() && option.getRequires().contains(approach)) {
                rungs.add(asked.evaluateGranting(option.getRequires(), approach, state, Collections.emptyMap()));
            }
        }
        return CapabilityState.any(rungs);
    }

    /**
     * The reason drawn from the rung the player is nearest to holding, which is the one worth
     * working toward. Nearest is {@link CapabilityResolver.Gap} order: a restock of something
     * they have, then a teleport to a place, then items, then unlocks. Ties go to the higher
     * rung.
     * A rung that wants only a stop the run is not making has nothing to name.
     *
     * <p>Asked with the resolver that made the decision. The sighted resolver answers a
     * destination the player stands in with {@code HAVE}, and {@code explainShortfall}
     * skips anything that holds, so explaining a blind refusal with it would read "no route
     * you can use right now" instead of naming the missing tablet.
     */
    private String shortfallOf(RunStop stop, PlayerState state, CapabilityResolver asked) {
        TravelOption nearest = null;
        CapabilityResolver.Gap nearestGap = CapabilityResolver.Gap.NONE;
        for (TravelOption option : stop.getTravel()) {
            // Each start-only rung has a plain twin lower down, which speaks for it.
            if (option.isStartOnly()) {
                continue;
            }
            CapabilityResolver.Gap gap = asked.gapTo(option.getRequires(), state);
            if (gap != CapabilityResolver.Gap.NONE && (nearest == null || gap.compareTo(nearestGap) < 0)) {
                nearest = option;
                nearestGap = gap;
            }
        }
        String shortfall = nearest == null ? "" : asked.explainShortfall(nearest.getRequires(), state);
        return shortfall.isEmpty() ? "no route you can use right now" : shortfall;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.detection.CapabilityResolver;
import com.larryfarming.farming.detection.CapabilityState;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import java.util.*;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;

/**
 * One run planned on its own, before anything about how it is shown: the stops worth
 * making, the seeds sized for them, and the crop each patch takes. Then the routes that
 * lean on another stop, re-decided once the stops and the walking order have settled.
 *
 * <p>Routes come from {@link RunPlanner}, which plans travel alone. This class adds the
 * ground and the seeds, through {@link StopSkipRules} and {@link CropAssigner}.
 */
final class RunPlanning {

    private RunPlanning() {
    }

    /**
     * One run planned as far as it can be on its own: which stops are worth making, what
     * each patch takes, and the seeds that answer came out of.
     *
     * <p>Held together because the three only agree with each other: crops are allocated
     * against seeds sized for these stops, then stops the seeds ran out before are dropped.
     *
     * <p><b>{@link #plans} and {@link #cropFor} stay index-aligned only because
     * {@link StopSkipRules#dropStopsTheSeedsRanOutBefore} turns a stop into a SKIP in
     * place</b> rather than removing it. {@link Itinerary.Planned} rejects a mismatch. A drop
     * that removes entries must filter {@code cropFor} alongside.
     */
    @AllArgsConstructor(access = AccessLevel.PRIVATE)
    static final class RunPlan {

        private final FarmingRun run;
        final List<StopPlan> plans;
        final List<List<Crop>> cropFor;
        final SeedPlan seeds;
        /** Which patch each seed landed in; {@link #cropFor} is per stop, not per patch. */
        final Map<PatchRef, Crop> plantedIn;

        Itinerary.Planned forTrip() {
            return new Itinerary.Planned(run.getId(), plans, cropFor);
        }
    }

    /**
     * Plan one run, up to but not including anything about how it is shown.
     *
     * <p>Stays per run even on a merged trip: the seed rotation is sized against
     * <em>this</em> run's patches and allocated in the catalogue's patch order, so merging
     * first would hand a patch another's seed. Trip-wide concerns (circuit order, shared
     * visits, the bag) work on the results.
     *
     * @param tripBook the book of the merged trip this run is part of, whose seats its seeds
     *     are dealt down, or null for a run walked on its own
     * @param contractSeedTaken whether {@link #takeTheContractsSeedFirst} has already taken
     *     this run's contract seed out of the stock
     */
    static RunPlan planRun(FarmingRun run, PlayerState state, FarmingInputs inputs,
            CapabilityResolver resolver, SeedSelector.Stock rotationStock, Spellbook tripBook, boolean contractSeedTaken) {
        RunPlanner planner = new RunPlanner(resolver);
        List<StopPlan> plans = plansOf(run, planner, state, inputs);
        // Read once so the quota and the allocation below rank patches the same way.
        int[] walk = CropAssigner.walkPositions(plans, tripBook);

        // Counts only patches worth a good seed, which enforces the reserved band: the
        // contract's guild patch is its own whole family, so assignCrops would otherwise
        // give it the top seat and the player's best herb.
        int rotationPatches = countRotationPatches(plans, state, inputs);
        // Taken before the rotation draws, so the guild's seed is not also offered to a
        // herb patch. A trip takes it earlier still, in takeTheContractsSeedFirst.
        if (!contractSeedTaken) {
            takeTheContractsSeed(plans, state, inputs, rotationStock);
        }
        // The good-seed quota is spent, not re-reserved: sized against seats already in the
        // ground, so planting the two best patches does not free the quota to promote the
        // next two.
        //
        // A player who puts the best seeds everywhere has no quota: every patch worth a good
        // seed takes one. The reserved guild patch still is not, so it keeps the filler.
        int quota = FarmingCatalogue.seedPolicy().getGoodSeedsPerRun();
        int goodPatches = inputs.getPreferences().plantsBestSeedsEverywhere() ? Math.min(countGoodHomes(plans), rotationPatches)
                : Math.min(countGoodHomes(plans), quota - CropAssigner.goodSeatsSpent(plans, state, inputs, quota, walk));
        // A run naming its own seeds (every tree run) gets a ranked ladder, not the herb
        // rotation. Only the rotation draws from the shared stock: a tree run's ladder
        // covers one patch type, so two tree families never compete for a sapling. A patch
        // a diary claims takes its crop in assignCrops, outside the ladder.
        SeedPlan seeds = run.getSeedPatchType() == null ? SeedSelector.select(inputs.getPreferences(), state, goodPatches,
                        rotationPatches - goodPatches, rotationStock) : SeedSelector.forPreference(inputs.getPreferences(),
                        run.getSeedPatchType(), state, countPlanting(plans) - countDiaryClaims(plans, state, inputs),
                        DiaryPlantings.withheld(state, inputs.getPreferences()));

        // Dealt in walk order, or a seed box lands seeds elsewhere. plantedIn records the
        // patch, not just the stop, so planting one teak at Fossil Island does not ask for
        // the trees in the other two patches to come down.
        Map<PatchRef, Crop> plantedIn = new HashMap<>();
        List<List<Crop>> cropFor = CropAssigner.assignCrops(plans, seeds, state, inputs, walk, plantedIn);
        List<StopPlan> settled = replanWhatLeanedOnAstopThatLeft(
                StopSkipRules.dropStopsTheSeedsRanOutBefore(plans, cropFor, inputs), planner, state);
        return new RunPlan(run, settled, cropsWithoutTheStopsThatLeft(settled, cropFor), seeds, plantedIn);
    }

    /**
     * Routes re-decided against the run the player is actually walking, for rungs that lean
     * on another stop.
     *
     * <p>{@link RunPlanner#plan} answers "have we been there" from every stop it routed, but
     * stops have since been dropped for what is in their ground. A rung riding the Grand
     * Tree's spirit tree is wrong once that still-growing patch is no longer a stop.
     *
     * <p>Only visits that {@link #wantsReplanning} are re-asked; a stop skipped for its
     * ground stays skipped. Walked in order with the reached set rebuilt as it goes, so a
     * rung is never satisfied by a later stop. One pass, not to a fixed point: no chain in
     * the catalogue is three deep.
     */
    private static List<StopPlan> replanWhatLeanedOnAstopThatLeft(List<StopPlan> plans, RunPlanner planner, PlayerState state) {
        List<StopPlan> settled = new ArrayList<>(plans);
        Map<PatchRef, CapabilityState> reached = new LinkedHashMap<>();
        RunPlanner.Allowance allowance = new RunPlanner.Allowance();
        for (int index = 0; index < settled.size(); index++) {
            replanOne(settled, index, planner, state, reached, allowance.covers(settled.get(index).getStop()), null);
            allowance.spendOn(settled.get(index));
            RunPlanner.stood(reached, settled.get(index));
        }
        return settled;
    }

    /**
     * The same re-planning over a drawn order: the stops in the order they will be walked,
     * grouped by the arrival they share. The circuit can reverse a run's own order (it walks
     * Taverley before Falador), so a rung like "run north from the Falador tree patch" must
     * be re-decided against it.
     *
     * <p>A whole group is re-planned before any of it is stood at, so no stop is satisfied by
     * a patch at its own arrival. One forward sweep suffices: a lean is only satisfied by an
     * earlier group, and each stop is stood at in its settled form, so a stop that loses its
     * route strands anything leaning on it at any depth.
     *
     * @param groups every index in {@code plans} exactly once, in the order reached. A
     *     partial grouping drops the missing stops from the reached set and withdraws rungs
     *     that were fine. A group is a journey only when its row is a visit
     *     ({@link StopRowWriter#isJourney}); anything else spends no allowance, reaches
     *     nothing and passes the previous journey's start on, as the row walk reads it.
     */
    static List<StopPlan> replanLeaningRungs(List<StopPlan> plans, List<List<Integer>> groups, RunPlanner planner, PlayerState state) {
        List<StopPlan> settled = new ArrayList<>(plans);
        Map<PatchRef, CapabilityState> reached = new LinkedHashMap<>();
        RunPlanner.Allowance allowance = new RunPlanner.Allowance();
        // What the last journey made leaves the next one: a ring beside the Monastery bushes.
        RunPlanner.Start start = null;
        for (List<Integer> group : groups) {
            for (int index : group) {
                replanOne(settled, index, planner, state, reached, allowance.covers(settled.get(index).getStop()), start);
            }
            // Spent after the whole group: the stops at one arrival are one journey, and
            // only when the drawn row is a visit. A visit under a skipped lead is no journey,
            // so it spends nothing and reaches nothing.
            if (!StopRowWriter.isJourney(group, settled)) {
                continue;
            }
            for (int index : group) {
                allowance.spendOn(settled.get(index));
                RunPlanner.stood(reached, settled.get(index));
            }
            start = CloakToTheRings.after(start, group, settled, planner.resolver(), state);
        }
        return settled;
    }

    /**
     * One stop re-asked, if it is being visited and anything about its chain can have
     * changed since it was routed: it leans on a stop, a position or a teleport already spent
     * on the way, or the journey before it left the player at the start of a route
     * ({@code start} not null).
     */
    private static void replanOne(List<StopPlan> settled, int index, RunPlanner planner,
            PlayerState state, Map<PatchRef, CapabilityState> reached, boolean mayStandHere, RunPlanner.Start start) {
        StopPlan plan = settled.get(index);
        // Visits only. A stop written off for having no route stays written off even if a
        // second look could reach it: the standing-crop gates, seed checks and crop
        // allocation never read a non-visit's ground, so resurrecting one would draw a full
        // visit to a patch nothing has checked.
        if (plan.isVisit() && (start != null || wantsReplanning(plan.getStop(), planner.resolver()))) {
            settled.set(index, planner.planStop(plan.getStop(), state, reached, mayStandHere, start));
        }
    }

    /**
     * The crops, less the ones allocated to a stop that has since lost its route.
     *
     * <p>{@code adviseOnGroup}'s planting tally counts every stop at an arrival whose lead is
     * visited, so a stranded stop beside a visited one would otherwise print "plant a yew"
     * for a patch the row is not working. Both re-planning passes need this.
     */
    static List<List<Crop>> cropsWithoutTheStopsThatLeft(List<StopPlan> plans, List<List<Crop>> cropFor) {
        List<List<Crop>> kept = new ArrayList<>(cropFor);
        for (int index = 0; index < plans.size(); index++) {
            if (!plans.get(index).isVisit()) {
                kept.set(index, List.of());
            }
        }
        return kept;
    }

    /**
     * Whether any rung of this stop is one that leans on another stop.
     *
     * <p>Asked of the whole chain, not the chosen route, because the question runs both ways:
     * a rung that leaned and no longer can must be taken back, and one that could not lean
     * and now can must be offered. The second stop's chosen route names no patch.
     */
    private static boolean leansOnApatch(RunStop stop) {
        for (TravelOption rung : stop.getTravel()) {
            if (!rung.getRequires().leafPatches().isEmpty()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Whether re-asking this stop can give a different answer from the one it already has.
     *
     * <p>Two ways it can: it leans on another stop and the run has changed underneath it, or
     * it is answerable from where the player stands, or from a teleport already spent on the
     * way there, and this pass may hand the position allowance to a different stop than the
     * first pass did. Asked of the whole chain, for the reason {@link #leansOnApatch} gives.
     */
    private static boolean wantsReplanning(RunStop stop, CapabilityResolver resolver) {
        if (leansOnApatch(stop)) {
            return true;
        }
        for (TravelOption rung : stop.getTravel()) {
            // Covers a zone named outright and a reach(...) leaf to a place whose ground is
            // known. TravelOption.to always builds such a leaf, so the declared destination
            // needs no separate check.
            if (rung.getRequires().readableFromPosition() || resolver.leansOnTravelTaken(rung.getRequires())) {
                return true;
            }
        }
        return false;
    }

    /**
     * The whole trip's leaning rungs, re-decided in circuit order.
     *
     * <p>The per-run pass only knows its own stops. Here a tree run's Grand Tree stop can
     * serve the fruit run's Village stop.
     */
    static Itinerary.Trip replanAcrossTheCircuit(Itinerary.Trip trip, RunPlanner planner, PlayerState state) {
        List<StopPlan> settled = replanLeaningRungs(trip.getPlans(), trip.getVisits(), planner, state);
        return trip.rerouted(settled, cropsWithoutTheStopsThatLeft(settled, trip.getCropFor()));
    }

    /**
     * Patches being planted today, each needing seeds.
     *
     * <p>Patches, not stops: a stop is a <em>visit</em>, and Fossil Island is three hardwood
     * patches reached by one journey.
     */
    private static int countPlanting(List<StopPlan> plans) {
        int count = 0;
        for (StopPlan plan : plans) {
            if (plan.isVisit() && plan.getStop().isPlanting()) {
                count += plan.getStop().getPatches().size();
            }
        }
        return count;
    }

    /** Patches being planted today that a diary claims, out of {@link #countPlanting}. */
    private static int countDiaryClaims(List<StopPlan> plans, PlayerState state, FarmingInputs inputs) {
        return (int) visitedRotation(plans).stream().filter(patch -> DiaryPlantings.claimedBy(patch, state,
                        inputs.getPreferences()) != null).count();
    }

    /** The patches of the visited stops that plant from a seed list, not one fixed crop. */
    private static List<PatchRef> visitedRotation(List<StopPlan> plans) {
        List<PatchRef> patches = new ArrayList<>();
        for (StopPlan plan : plans) {
            if (plan.isVisit() && plan.getStop().isPlanting() && !plan.getStop().isFixedCrop()) {
                patches.addAll(plan.getStop().getPatches());
            }
        }
        return patches;
    }

    /**
     * Patches this run's rotation has to fill: the ones being planted today that do not
     * name their own crop.
     *
     * <p>Counted over visited stops, in patches, as {@link #countPlanting} is. Contract
     * patches are excluded.
     */
    private static int countRotationPatches(List<StopPlan> plans, PlayerState state, FarmingInputs inputs) {
        return (int) visitedRotation(plans).stream().filter(ref -> !CropAssigner.heldForTheNextContract(ref, state)
                        && CropAssigner.contractedInto(ref, state, inputs) == null).count();
    }

    /**
     * Takes the contract's seed out of the stack the rotation is about to draw from.
     *
     * <p>A contracted patch is dealt outside the shared allocation (see
     * {@link SeedSelector#select}'s {@code stock}), so without this the same seed would be
     * promised to the guild and to a herb patch on the round. Drawn one per patch, the
     * stock's unit throughout.
     */
    private static void takeTheContractsSeed(List<StopPlan> plans, PlayerState state, FarmingInputs inputs, SeedSelector.Stock stock) {
        for (PatchRef ref : visitedRotation(plans)) {
            Crop crop = CropAssigner.contractedInto(ref, state, inputs);
            if (crop != null) {
                stock.spendOne(crop);
            }
        }
    }

    /**
     * Takes this run's contract seed out of the stock before any family on the trip draws
     * the rotation, so {@link #drawsOnlyFiller} families can draw last. Plans the run the
     * way {@link #planRun} does, because only a visited stop takes its seed; a run with no
     * reserved patch, or no contract crop to take, is not planned.
     *
     * @return whether the seed was taken here, which {@link #planRun} must then skip
     */
    static boolean takeTheContractsSeedFirst(FarmingRun run, PlayerState state, FarmingInputs inputs, CapabilityResolver resolver,
            SeedSelector.Stock rotationStock) {
        if (inputs.getContractCrop() == null || rotationPatchesOf(run).stream().noneMatch(PatchPriority::isReservedForContracts)) {
            return false;
        }
        List<StopPlan> plans = plansOf(run, new RunPlanner(resolver), state, inputs);
        takeTheContractsSeed(plans, state, inputs, rotationStock);
        return true;
    }

    /**
     * The run's stop plans before any seed is dealt. {@link #planRun} and
     * {@link #takeTheContractsSeedFirst} both read visits off these, so they must agree.
     */
    private static List<StopPlan> plansOf(FarmingRun run, RunPlanner planner, PlayerState state, FarmingInputs inputs) {
        return StopSkipRules.leaveStandingCrops(run, planner.plan(run, state), inputs, state);
    }

    /**
     * Whether this run draws on the herb rotation through reserved patches alone: the
     * contract's guild herb patch. Such a run sizes no good seeds and takes only filler.
     *
     * <p>A trip draws these families last. The filler end takes carried seeds first, so a
     * filler draw ahead of the herb run would plant the toadflax the player has just
     * withdrawn for the herb run's best patches, and the plan would change mid-withdrawal.
     */
    static boolean drawsOnlyFiller(FarmingRun run) {
        List<PatchRef> patches = rotationPatchesOf(run);
        return run.getSeedPatchType() == null && !patches.isEmpty() && patches.stream().allMatch(PatchPriority::isReservedForContracts);
    }

    /** The patches this run plants from a seed list rather than one fixed crop. */
    private static List<PatchRef> rotationPatchesOf(FarmingRun run) {
        List<PatchRef> patches = new ArrayList<>();
        for (RunStop stop : run.getStops()) {
            if (stop.isPlanting() && !stop.isFixedCrop()) {
                patches.addAll(stop.getPatches());
            }
        }
        return patches;
    }

    /**
     * Rotation patches a good seed may go in: every one not reserved for contracts.
     *
     * <p>The good end is sized against this, not the whole rotation. The Farming Guild herb
     * patch is the contract's entire family, so {@link PatchPriority}'s ranking alone would
     * still put it first within that family. Zero here means the contract, which draws from
     * the filler end.
     */
    private static int countGoodHomes(List<StopPlan> plans) {
        return (int) visitedRotation(plans).stream().filter(ref -> !PatchPriority.isReservedForContracts(ref)).count();
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.*;
import com.larryfarming.farming.detection.*;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.model.Skill;
import com.larryfarming.snapshot.*;
import java.util.*;
import java.util.function.BooleanSupplier;
import lombok.extern.slf4j.Slf4j;

/**
 * Which farming runs are worth doing, and in what order.
 *
 * <p>Ordered by the value of each run rather than by whichever timer
 * expired first: an idle hardwood patch costs more than an idle herb patch, because it is
 * the best farming experience in the game on the longest cadence.
 * {@link FarmingPreferences#priorityOf} holds that ranking, which the player can lead with
 * the herb run.
 *
 * <p>A run is due when any one of its patches needs a visit, or, for a player who waits
 * for every patch, once none is still growing or any is diseased or dead.
 *
 * <p>Pure: everything it needs arrives as arguments, including the current second.
 */
@Slf4j
public final class RunScheduler {

    private RunScheduler() {
    }

    /**
     * How long a gap between one patch and the next still counts as the same trip.
     *
     * <p>Generous, because real runs have long gaps: a quetzal out to Ortus Farm, a bank
     * detour for a seed. It only needs to notice that the player has <em>stopped</em>, so
     * a run with an extra left undone releases the tab once they have.
     */
    private static final long ONE_TRIP_SECONDS = 20 * 60L;

    /**
     * The longest a trip is taken to last. A trip runs from its first patch while the player
     * keeps working patches, but standing beside one keeps re-reading it, so without a ceiling
     * an afternoon at the Farming Guild would stretch one trip back to the run before.
     */
    private static final long LONGEST_TRIP_SECONDS = 2 * 60 * 60L;

    // Whether checking the patch's health completes a contract for it, rather than picking
    // the produce: PatchType.isHealthCheckRequired. A contract for a crop with a health
    // check completes on the check, so a jangerberry bush finishes its contract before its
    // berries are picked. A crop without one completes once the patch is fully harvested. A
    // crop whose health is already checked cannot satisfy a contract handed out afterwards;
    // that contract needs one grown from seed.

    /**
     * How a contract waiting on a crop elsewhere begins its detail when its reserved herb patch
     * has work. The guild row's own work line already names that work, so the row never
     * borrows a detail that starts with this.
     */
    static final String HERB_PATCH_WORK = "guild herb patch: ";

    /** Everywhere a contracted crop could be growing. */
    private static final List<PatchRef> CONTRACT_PATCHES = FarmingCatalogue.contractPatches();

    /**
     * Every run, best first.
     *
     * @param openBook which spellbook the player is on, deciding which variant of a run
     *                 that has two gets scheduled. Null follows neither.
     */
    public static List<FarmingRunStatus> schedule(PlayerState state, FarmingInputs inputs, Spellbook openBook, long nowEpochSec) {
        FarmingInputs given = (inputs != null ? inputs : FarmingInputs.none()).seeing(state);
        // One resolver per book, cached across the schedule: a run written for another book
        // is measured on both, and building a resolver is the expensive half.
        Map<Spellbook, CapabilityResolver> resolvers = RunVariants.newResolverCache();
        // Once for every run: a trip spans whichever runs the player is doing.
        long tripStart = tripStartedAt(given, nowEpochSec);
        List<FarmingRunStatus> statuses = new ArrayList<>();
        // One variant of each run. The herb run is in the catalogue once per spellbook, and
        // RunVariants picks between them on reachable patches.
        for (List<FarmingRun> variants : FarmingCatalogue.runsById().values()) {
            RunVariants.Choice choice = RunVariants.best(variants, state, openBook, given, resolvers);
            // A run with every crop switched off is one the player has said they do not do,
            // so it leaves the list.
            if (PlantingGate.silencesWholeRun(choice.getRun(), given.getPreferences())) {
                continue;
            }
            // Scoring the variant already planned it, so reuse those plans, and the resolver
            // they were planned with.
            CapabilityResolver resolver = resolvers.computeIfAbsent(choice.getPlanFor(), given::resolverOn);
            statuses.add(statusOf(choice.getRun(), state, given, choice.getPlans(), resolver, nowEpochSec, tripStart));
        }
        FarmingPreferences prefs = given.getPreferences();
        statuses.sort(Comparator.comparingInt(status -> rankOf(status, prefs)));
        return statuses;
    }

    /**
     * Due runs first in priority order, then everything waiting in the order it will come
     * ready, then the unseen, then the locked, last because the player can do nothing about
     * them on the run today. Within a group, the player's run priority decides.
     */
    private static int rankOf(FarmingRunStatus status, FarmingPreferences prefs) {
        RunStatus state = RunStatus.valueOf(status.getStatus());
        int priority = prefs.priorityOf(RunId.valueOf(status.getRunId()));
        switch (state) {
            case DUE:
                return priority;
            case PENDING:
                return 100 + priority;
            case UNSEEN:
                return 200 + priority;
            default:
                return 300 + priority;
        }
    }

    private static FarmingRunStatus statusOf(FarmingRun run, PlayerState state,
            FarmingInputs inputs, List<StopPlan> plans, CapabilityResolver resolver, long nowEpochSec, long tripStart) {
        UnlockGate gate = RunAvailability.gateOf(run, inputs.getPreferences());
        if (RunAvailability.of(gate, state) == CapabilityState.LACK) {
            return build(run, RunStatus.LOCKED, RunAvailability.shortfall(gate, state), 0L);
        }
        if (run.getId() == RunId.HERB && herbRunsWaitForTheLevel(inputs.getPreferences(), state)) {
            return build(run, RunStatus.PENDING, "from " + Preset.HERB_RUN_LEVEL + " Farming", 0L);
        }
        if (run.getId() == RunId.CONTRACT) {
            // The contract answers from the guild's varbits, and walks its stop only for the
            // herb patch a contract waiting elsewhere leaves owed a filler herb. It needs no
            // reachability guard: the guild chain ends in a minecart rung open to everyone.
            FarmingRunStatus contract = contractStatus(run, state, inputs, nowEpochSec);
            CropData wanted = CropData.forCrop(inputs.getContractCrop());
            if (!RunStatus.PENDING.name().equals(contract.getStatus()) || wanted == null || wanted.getPatchType() == PatchType.HERB) {
                return contract;
            }
            // A contract waiting on a crop outside the herb patch leaves that patch owed a
            // filler herb, and the contract's stop is the only one that visits it.
            Tally tally = walkPatches(run, plans, inputs, state, nowEpochSec, false, tripStart);
            return tally.actionable == 0 ? contract : build(run, RunStatus.DUE,
                    HERB_PATCH_WORK + dueDetail(tally), 0L);
        }

        String noRoute = noRouteDetail(run, plans, inputs.getPreferences(), state, resolver);
        if (noRoute != null) {
            return build(run, RunStatus.LOCKED, noRoute, 0L);
        }

        Tally tally = walkPatches(run, plans, inputs, state, nowEpochSec, false, tripStart);

        if (tally.seen == 0 && tally.unseen == 0) {
            // Nothing observed, and no unseen patch the player could plant. Nothing seen
            // is also nothing to be halfway round, so the trip is never unfinished, whatever
            // the extras say.
            return build(run, RunStatus.UNSEEN, UNSEEN_DETAIL, 0L);
        }

        Tally extras = walkPatches(run, plans, inputs, state, nowEpochSec, true, tripStart);
        // A route proper never seen is nothing to be halfway round, however fresh an extra.
        boolean unfinished = tally.seen > 0 && tripUnfinished(tally, extras, nowEpochSec);

        // Waiting for every patch, one still growing holds the run back. Only a growing
        // crop can: an unseen patch and a seedless empty one have nothing to wait for, so
        // each is left out here as it is from the verdict below. A diseased or dead patch
        // never waits: a diseased crop dies on its next growth tick, and a dead one is a
        // patch growing nothing until it is cleared. A crop planted on this trip holds
        // nothing back either, or the run would leave the walkthrough at its first
        // replanted patch.
        boolean waits = inputs.getPreferences().waitsForEveryPatch();
        boolean urgent = tally.needsHelp + tally.needsClearing > 0;
        boolean holding = tally.growing > tally.plantedThisTrip;
        // Short of a sapling for every patch, the fruit trees wait for more, unless a tree
        // is diseased or dead.
        String saplings = saplingsShort(run, tally, inputs.getPreferences(), state);
        if (saplings != null && !urgent) {
            return build(run, RunStatus.PENDING, saplings, 0L, unfinished, false);
        }
        if (tally.actionable > 0 && (!waits || !holding || urgent)) {
            return build(run, RunStatus.DUE, dueDetail(tally), 0L, unfinished, false);
        }
        // The run comes due when its last patch does. A crop with no estimate leaves that
        // undated, rather than naming a time the run would still be waiting at.
        long readyAt = !waits ? tally.earliestReady : tally.undated > 0 ? 0L : tally.latestReady;
        return build(run, RunStatus.PENDING, pendingDetail(tally, readyAt, waits, nowEpochSec),
                readyAt, unfinished, false);
    }

    /** Whether the player's herb runs wait for {@link Preset#HERB_RUN_LEVEL} Farming. */
    static boolean herbRunsWaitForTheLevel(FarmingPreferences prefs, PlayerState state) {
        return prefs.herbRunsWaitForLevel() && state != null && state.getSkillLevel(Skill.FARMING) < Preset.HERB_RUN_LEVEL;
    }

    /**
     * The fruit tree run's line while the player owns too few saplings for every patch due
     * one on this visit, such as "2 of 5 saplings", or null when they have enough, the
     * switch is off, or nothing proves the count.
     *
     * <p>A patch is due a sapling when it stands bare, holds a dead tree, which is cleared and
     * replanted, or holds a checked tree, when grown trees are replanted. A tree kept for its
     * fruit is checked and picked, and felled only for a better one, so it needs none. Nor
     * does a diseased tree, which is cured, or a growing one. A run with a tree planted on
     * this trip is under way and never held, or planting the first sapling would end the
     * walkthrough.
     *
     * <p>A seed counts, since the player can grow a sapling from it before setting off. So
     * does any ticked sapling, though a standing tree takes only one as good as itself: five
     * checked dragonfruit trees and five saplings, one of them a palm, release the run, which
     * then plants four.
     */
    private static String saplingsShort(FarmingRun run, Tally tally, FarmingPreferences prefs, PlayerState state) {
        if (run.getSeedPatchType() != PatchType.FRUIT_TREE || !prefs.fruitTreesWaitForSaplings() || tally.plantedThisTrip > 0) {
            return null;
        }
        int patches = tally.bare + tally.needsClearing + tally.grownTrees;
        if (patches == 0) {
            return null;
        }
        int owned = SeedSelector.plantableAcross(prefs, PatchType.FRUIT_TREE, state);
        if (owned < 0 || owned >= patches) {
            return null;
        }
        return owned + " of " + patches + (patches == 1 ? " sapling" : " saplings");
    }

    /**
     * Why no stop on the run proper can be reached, or null when one can or might.
     *
     * <p>Reads the plans the variant was scored on, so it costs no second planning pass.
     * Only the route proper counts, as in {@link #walkPatches}: an extra is no reason to
     * go, so reaching one does not make the run possible. A stop the player switched off
     * is left out too, or a run would read as having no route because of the one stop the
     * player chose not to plant.
     *
     * <p>Every counted stop must be a definite refusal. A stop waiting on an unread fact
     * carries {@code UNKNOWN} confidence (see {@link RunPlanner#planStop}), and a guessed
     * route is a visit, so unread state never greys a run.
     *
     * <p>Names the fairy ring when a way to a ring is the one thing a route could fix: at
     * least one stop wants only that, and every other stop is shut by its access gate
     * (Fossil Island before Bone Voyage). Hardwood shows why: the Locus Oasis is reached
     * only by a fairy ring, and Fossil Island is shut to anyone without the barge.
     *
     * <p>Only when the ring rung certainly holds once a way to a ring is granted. Where the
     * network itself is unread (no staff seen, a quest not yet reported), switching an
     * approach on might still not open the run, so the detail says only "no route".
     *
     * @param resolver the one the plans were made with, to tell a stop shut by its access
     *     gate from one refused for want of a route, as {@link RunPlanner} does
     * @return {@link FarmingSkipReason#NO_FAIRY_RING_ROUTE}'s label when the fairy ring is
     *     the shared blocker; otherwise {@link #NO_ROUTE_DETAIL}
     */
    // No catalogue run has a required stop the player can switch off beside others, so no
    // run reaches the switched-off rule.
    static String noRouteDetail(FarmingRun run, List<StopPlan> plans,
            FarmingPreferences prefs, PlayerState state, CapabilityResolver resolver) {
        boolean anyStop = false;
        boolean anyForWantOfAring = false;
        boolean onlyTheRing = true;
        for (StopPlan plan : plans) {
            RunStop stop = plan.getStop();
            if (stop.isOptional() || PlantingGate.silences(run, stop, prefs)) {
                continue;
            }
            if (!definitelyUnrouted(plan)) {
                return null;
            }
            anyStop = true;
            // HAVE only: a ring rung that would certainly reach the stop if the player had a
            // way to stand at a ring. Stricter than the planner's own test, which also
            // accepts a network it cannot read yet.
            if (plan.getSkipReason() == FarmingSkipReason.NO_FAIRY_RING_ROUTE
                    && RunPlanner.withAwayToAring(stop, state, resolver) == CapabilityState.HAVE) {
                anyForWantOfAring = true;
            } else if (!shutByItsGate(stop, state, resolver)) {
                onlyTheRing = false;
            }
        }
        if (!anyStop) {
            return null;
        }
        return anyForWantOfAring && onlyTheRing ? FarmingSkipReason.NO_FAIRY_RING_ROUTE.getLabel() : NO_ROUTE_DETAIL;
    }

    /** Whether the stop's access gate definitely keeps the player out, whatever the route. */
    private static boolean shutByItsGate(RunStop stop, PlayerState state, CapabilityResolver resolver) {
        return stop.getAccessGate() != null && resolver.resolve(stop.getAccessGate(), state).getState() == CapabilityState.LACK;
    }

    /**
     * Whether the planner refused this stop for want of a route, with every rung a definite
     * no. "Not worth the trip" counts: the planner reaches it only when every listed route
     * has failed, so the walkthrough never sends the player there either.
     */
    private static boolean definitelyUnrouted(StopPlan plan) {
        if (plan.isVisit() || plan.getConfidence() != CapabilityState.LACK) {
            return false;
        }
        FarmingSkipReason reason = plan.getSkipReason();
        return reason == FarmingSkipReason.NO_ROUTE || reason == FarmingSkipReason.NO_ROUTE_LISTED
                || reason == FarmingSkipReason.NO_FAIRY_RING_ROUTE || reason == FarmingSkipReason.NOT_WORTH_TRIP;
    }

    /**
     * Whether the player is out on this run right now with something still to do at it.
     *
     * <p>Both halves are needed. "Something left" reads the woven-in extras, which stay out
     * of the due verdict but separate a finished trip from an abandoned one. "Out there"
     * needs recency, because a run can have an extra left undone for days (limpwurt seeds
     * never planted). Patches only report while the player stands beside them, so the last
     * observation records where they have actually been.
     */
    private static boolean tripUnfinished(Tally proper, Tally extras, long nowEpochSec) {
        if (extras.actionable == 0) {
            return false;
        }
        return seenThisTrip(Math.max(proper.lastSeen, extras.lastSeen), nowEpochSec);
    }

    /**
     * Whether a patch last seen at {@code observedAtEpochSec} was seen within one trip's gap
     * of now. Zero means never seen.
     *
     * <p>This asks whether the player is out on a trip at all, and is shared with the
     * walkthrough, which reads a fresh sighting of a growing patch as the player being partway
     * round, so the runs list and the walkthrough agree on when a trip ends. Whether a crop
     * went in on this trip is a different question, answered from the whole trip's span by
     * {@link #tripStartedAt}.
     */
    static boolean seenThisTrip(long observedAtEpochSec, long nowEpochSec) {
        return observedAtEpochSec > 0 && nowEpochSec - observedAtEpochSec <= ONE_TRIP_SECONDS;
    }

    /**
     * Whether nobody can yet say what the next contract will ask for.
     *
     * <p>True in the two windows where Jane has not named a crop: no contract taken
     * ({@link CapabilitySources#CONTRACT_PRODUCE_VARBIT} zero), and one finished but not
     * handed in ({@link CapabilitySources#CONTRACT_COMPLETE_VARBIT} set), after which the
     * next contract is a fresh roll.
     *
     * <p><b>False when the varbits have not arrived.</b> Reading silence as "no contract"
     * would hold the reserved patch empty for a contract that may not exist.
     *
     * <p>Kept beside {@link #contractStatus}, which reads the same two varbits. Both read
     * them by the detection tables' ids, so they and the login scan cannot drift apart.
     */
    public static boolean nextContractCropUnknown(PlayerState state) {
        if (state == null) {
            return false;
        }
        Integer produce = state.getVarbits().get(CapabilitySources.CONTRACT_PRODUCE_VARBIT);
        if (produce == null) {
            return false;
        }
        if (produce == 0) {
            return true;
        }
        Integer complete = state.getVarbits().get(CapabilitySources.CONTRACT_COMPLETE_VARBIT);
        return complete != null && complete != 0;
    }

    /**
     * The contract, answered from three sources because no one of them is enough: the
     * varbits say whether a contract exists and whether it is finished, and the plugin
     * decodes which crop it wants. Without the crop, reading the whole guild
     * would report a contract ready whenever any guild crop is.
     */
    private static FarmingRunStatus contractStatus(FarmingRun run, PlayerState state, FarmingInputs inputs, long nowEpochSec) {
        Integer produce = state == null ? null : state.getVarbits().get(CapabilitySources.CONTRACT_PRODUCE_VARBIT);
        if (produce == null) {
            return build(run, RunStatus.UNSEEN, "contract not checked yet", 0L);
        }
        if (produce == 0) {
            return build(run, RunStatus.DUE, "get a contract from Guildmaster Jane", 0L);
        }
        // Set when the contract's finishing act is done, not when the crop matures: it goes
        // 0 to 1 as the last snape grass leaves the ground. Only the walk to Jane is left.
        // The act depends on the crop: see completedByCheck.
        Integer complete = state.getVarbits().get(CapabilitySources.CONTRACT_COMPLETE_VARBIT);
        if (complete != null && complete != 0) {
            return build(run, RunStatus.DUE, "hand the contract to Guildmaster Jane", 0L);
        }

        Crop crop = inputs.getContractCrop();
        if (crop == null) {
            // A contract value the decoding table does not know, so the contract's patch is
            // unknown and nothing the player does here changes that.
            return build(run, RunStatus.UNSEEN, "contract crop not recognised", 0L);
        }

        CropData data = CropData.forCrop(crop);
        if (data == null) {
            // A crop CropData does not carry (easy-tier produce no run plants).
            // Nothing here can find its patch, so say only what is certain.
            log.debug("No crop data for farming contract produce {}", crop);
            return build(run, RunStatus.PENDING, CropNames.inSentence(crop) + " growing", 0L);
        }
        return contractPatchStatus(run, crop, data, state, inputs, nowEpochSec);
    }

    /**
     * The contract read off the patch its crop actually goes in.
     *
     * <p>A crop with a health check completes the contract on the check, which is the
     * {@link CropState#GROWING} state at the final stage (the "Check-health" reading). Once
     * checked, the patch turns {@link CropState#HARVESTABLE} and its crop can no longer
     * satisfy a contract, so it falls through to "plant one" even though the patch is not
     * empty. For a crop without a health check, HARVESTABLE is the crop waiting to be
     * picked, and picking it completes the contract.
     */
    private static FarmingRunStatus contractPatchStatus(FarmingRun run, Crop crop,
            CropData data, PlayerState state, FarmingInputs inputs, long nowEpochSec) {
        boolean completedByCheck = data.getPatchType().isHealthCheckRequired();
        String name = CropNames.inSentence(crop);
        boolean seen = false;
        boolean needsCuring = false;
        boolean needsClearing = false;
        long soonest = 0;

        // The guild patches the crop can be planted in: usually one, but two for an
        // allotment, and a contract fills whichever of the pair is free.
        for (PatchRef ref : CONTRACT_PATCHES) {
            if (ref.type() != data.getPatchType()) {
                continue;
            }
            PatchPrediction patch = inputs.patchAt(ref);
            if (patch == null) {
                continue;
            }
            seen = true;
            // Weeds, or somebody else's crop in the patch the contract wants. Either way
            // there is no contract crop here, so it reads as one still to plant.
            if (patch.getCrop() != crop) {
                continue;
            }
            // Remembered rather than returned on, because the other patch of the same crop
            // may be ready, and harvesting it finishes the contract outright. Diseased and
            // dead are kept apart: a plant cure saves a diseased crop, and a dead one needs
            // a spade.
            if (patch.getState() == CropState.DISEASED) {
                needsCuring = true;
                continue;
            }
            if (patch.getState() == CropState.DEAD) {
                needsClearing = true;
                continue;
            }
            // Already checked, so spent for the contract whatever produce it still carries.
            if (completedByCheck && patch.getState() == CropState.HARVESTABLE) {
                continue;
            }
            if (patch.isReadyAt(nowEpochSec)) {
                // Not possessive: crop names mix singular and plural ("jangerberries's").
                return dueAtThePatch(run, completedByCheck ? "check the health of your " + name : "harvest your " + name);
            }
            long done = patch.getDoneEstimateEpochSec();
            soonest = earlier(done, soonest);
        }

        // Curing first: a diseased patch dies on the next growth tick, and a dead one
        // will keep.
        if (needsCuring) {
            return dueAtThePatch(run, "your " + name + " is diseased");
        }
        if (needsClearing) {
            // "And replant" only when they have the seed, as in the empty-patch branch
            // below. Still DUE either way: the patch is not free until it is dug.
            return dueAtThePatch(run, outOfSeedFor(crop, state) ? "dig up your dead " + name
                    : "dig up your dead " + name + " and replant");
        }
        if (soonest > 0) {
            return build(run, RunStatus.PENDING, "ready in " + FarmingDurations.describe(soonest - nowEpochSec), soonest);
        }
        // The contract's patch is visible and its crop is not growing in it.
        if (seen) {
            // An empty patch is a reason to go only while the player has the seed, as for
            // every other run. Only a definite nothing counts, so an unopened bank still
            // sends them.
            return outOfSeedFor(crop, state) ? build(run, RunStatus.PENDING, "no " + CropNames.inSentence(data.getSeedName()), 0L)
                    : dueAtThePatch(run, "plant " + name + " at the guild");
        }
        // Not been to the guild since the plugin started, so there is nothing to read.
        return build(run, RunStatus.UNSEEN, "guild patches not checked yet", 0L);
    }

    /**
     * Whether this one crop is one the player is known to have no seed for: a contract's
     * crop, or a fixed-crop stop's.
     *
     * <p>Asked of the crop itself rather than through {@link #definitelyOutOfSeeds}: a
     * contract accepts only the crop it names, so preferences and the seed ladder have no
     * say.
     */
    static boolean outOfSeedFor(Crop crop, PlayerState state) {
        CropData data = CropData.forCrop(crop);
        return data != null && SeedSelector.definitelyOutOf(crop, state, data.getSeedsPerPatch());
    }

    /** What each of a run's patches is doing, rolled up. */
    private static final class Tally {
        int seen;
        int actionable;
        int ready;
        /** Diseased, and still savable with a plant cure. */
        int needsHelp;
        /** Dead, and waiting on a spade. */
        int needsClearing;
        int empty;
        /** Patches never seen, assumed empty, that the player has a seed for. */
        int unseen;
        /** Empty patches with no tree rooted in them, the ground a sapling goes into. */
        int bare;
        /** Patches standing empty that the player has no seed for. */
        int seedless;
        /** Of the empty patches with a seed: a fruit tree, calquat, bush or cactus picked bare. */
        int picked;
        /** Of the empty patches with a seed: a lumber tree checked and still standing. */
        int checked;
        /** Checked fruit trees the run chops down and replants. */
        int grownTrees;
        /** Crops still growing, with or without an estimate. */
        int growing;
        /** Growing crops with no estimate of when they finish. */
        int undated;
        /** Growing crops the player put in on this trip. */
        int plantedThisTrip;
        long earliestReady;
        /** When the last estimated crop finishes. */
        long latestReady;
        /** The most recent time any of these patches was actually observed. */
        long lastSeen;
        /** When the player's trip began, from {@link #tripStartedAt}; zero for none. */
        long tripStart;
    }

    /**
     * What the run's own patches are doing: the route proper, without the woven-in extras
     * and without stops this player cannot reach.
     *
     * <p>The extras are things to do while already out there, not reasons to go. An
     * unreachable patch is not somewhere the player can act. Both would otherwise make a
     * run report itself due off a patch nothing can clear.
     *
     * <p>Only reachability filters stops here, unlike the walkthrough. The runs list counts
     * down to a crop still growing, so dropping it would replace a due date with silence.
     *
     * @param extras false for the route proper, which makes the verdict; true for the
     *               woven-in stops alone. Two passes keep every {@link Tally} meaning one
     *               side only.
     */
    private static Tally walkPatches(FarmingRun run, List<StopPlan> plans,
            FarmingInputs inputs, PlayerState state, long nowEpochSec, boolean extras, long tripStart) {
        Tally tally = new Tally();
        tally.tripStart = tripStart;
        for (StopPlan plan : plans) {
            if (!plan.isVisit()) {
                continue;
            }
            RunStop stop = plan.getStop();
            if (stop.isOptional() != extras) {
                continue;
            }
            // A silenced stop is a patch the player switched off, not an empty patch.
            if (PlantingGate.silences(run, stop, inputs.getPreferences())) {
                continue;
            }
            boolean seedless = definitelyOutOfSeeds(run, stop, state, inputs.getPreferences());
            walkPatches(stop, inputs, state, nowEpochSec, seedless, () -> knowsAseedFor(run, stop, state, inputs.getPreferences()), tally);
        }
        return tally;
    }

    /**
     * Whether this stop has nothing the player could put in the ground.
     *
     * <p>The choices are exactly the ones the walkthrough allocates from, via
     * {@link SeedSelector#plantableFrom}. A wider list would let a run report itself due
     * and then name no crop at any stop. A stop with a fixed crop accepts only the crop
     * {@link FixedCrops#cropFor} chooses.
     *
     * <p>A player holding only magic saplings with only yew ticked is out of seeds here;
     * ticking magic fixes it.
     *
     * <p>A crop the player has switched off counts as one they cannot plant. Only a
     * definite nothing counts: an unopened bank is silence, and dropping a patch on
     * silence is the expensive mistake.
     */
    // Package-private: the walkthrough asks the same question of a single stop, and one
    // implementation keeps the two from disagreeing on the same screen.
    static boolean definitelyOutOfSeeds(FarmingRun run, RunStop stop, PlayerState state, FarmingPreferences prefs) {
        // A stop that plants nothing, such as the contract errand, cannot be short of seeds.
        if (!stop.isPlanting()) {
            return false;
        }
        if (stop.isFixedCrop()) {
            // The crop the stop would plant, which has already fallen past every ticked
            // crop the player is out of.
            Crop crop = FixedCrops.cropFor(stop, prefs, state);
            return crop == null || outOfSeedFor(crop, state);
        }
        PatchType type = stop.patchType();
        if (type == null) {
            return false;
        }
        return SeedSelector.definitelyOutOfAll(ladderAt(run, stop, type, state, prefs), state, CropData.seedsPerPatch(type));
    }

    /** The crops this stop may take, best first. */
    private static List<Crop> ladderAt(FarmingRun run, RunStop stop, PatchType type, PlayerState state, FarmingPreferences prefs) {
        return DiaryPlantings.ladderAt(SeedSelector.plantableFrom(prefs, run.getSeedPatchType(), type), stop, state, prefs);
    }

    /**
     * Whether a store Larry has seen holds enough seed to fill one patch at this stop, over
     * the same choices as {@link #definitelyOutOfSeeds}. With the bank unopened, neither
     * holds.
     */
    static boolean knowsAseedFor(FarmingRun run, RunStop stop, PlayerState state, FarmingPreferences prefs) {
        if (!stop.isPlanting() || state == null) {
            return false;
        }
        if (stop.isFixedCrop()) {
            Crop crop = FixedCrops.cropFor(stop, prefs, state);
            CropData data = crop == null ? null : CropData.forCrop(crop);
            return data != null && SeedSelector.knownToHold(crop, state, data.getSeedsPerPatch());
        }
        PatchType type = stop.patchType();
        if (type == null) {
            return false;
        }
        int needed = CropData.seedsPerPatch(type);
        for (Crop crop : ladderAt(run, stop, type, state, prefs)) {
            if (SeedSelector.knownToHold(crop, state, needed)) {
                return true;
            }
        }
        return false;
    }

    /**
     * @param known whether Larry knows of a seed for the stop, which an unseen patch needs;
     *     asked only once a patch proves unseen, since the ladder costs a walk per stop
     */
    private static void walkPatches(RunStop stop, FarmingInputs inputs, PlayerState state,
            long nowEpochSec, boolean seedless, BooleanSupplier known, Tally tally) {
        Boolean knownHere = null;
        for (PatchRef patch : stop.getPatches()) {
            PatchPrediction prediction = inputs.patchAt(patch);
            // A patch never seen, counted as empty ground. Anything planted before Larry was
            // watching finished long ago, so the visit pays either way, and a run that waited
            // to see the patch would never send the player to see it. Counted apart from the
            // patches seen empty, so the detail can say the emptiness is assumed.
            //
            // Only a stop that plants, and only with a seed Larry knows of: planting is all
            // there is to do at ground assumed empty, so without one the patch counts for
            // nothing, neither "nothing to plant" nor ground waiting, and the player is asked
            // to open the seed stores instead.
            //
            // Never bare ground for the sapling count: a tree planted before Larry was
            // watching still stands, so an unseen patch asks for no sapling, and a fruit tree
            // run never waits for saplings to cover patches nobody has seen.
            if (prediction == null) {
                if (knownHere == null) {
                    knownHere = known.getAsBoolean();
                }
                if (stop.isPlanting() && knownHere) {
                    tally.unseen++;
                    tally.actionable++;
                }
                continue;
            }
            tally.seen++;
            tally.lastSeen = Math.max(tally.lastSeen, prediction.getObservedAtEpochSec());
            classify(prediction, stop, inputs.getPreferences(), state, tally, nowEpochSec, seedless);
        }
    }

    /**
     * One patch, sorted into the roll-up. Every question about what is waiting at it goes
     * through {@link PatchWork}, which the walkthrough also reads, so the runs list and the
     * walkthrough on screen beside it agree.
     */
    private static void classify(PatchPrediction prediction, RunStop stop,
            FarmingPreferences prefs, PlayerState player, Tally tally, long nowEpochSec, boolean seedless) {
        CropState state = prediction.getState();
        PatchWork.Act act = PatchWork.at(prediction, stop, prefs, nowEpochSec);
        PatchType type = stop.patchType();
        // An anima plant dies at the end of its time, seen or not, and is cleared only to
        // plant the next one: with no seed for that, it is ground with nothing to plant.
        if (type == PatchType.ANIMA && act == PatchWork.Act.CLEAR_DEAD) {
            if (seedless) {
                tally.empty++;
                tally.seedless++;
            } else {
                tally.needsClearing++;
                tally.actionable++;
            }
            return;
        }
        if (state == CropState.DISEASED || state == CropState.DEAD) {
            // Disease and death come only from a direct observation, never a prediction.
            // Counted apart: a plant cure saves a diseased patch, and a dead one wants a
            // spade.
            if (state == CropState.DEAD) {
                tally.needsClearing++;
            } else {
                tally.needsHelp++;
            }
            tally.actionable++;
            return;
        }
        // A checked fruit tree the run replants wants a sapling as bare ground does. One still
        // waiting on its check is worth the trip for the check alone, and so is ripe fruit the
        // player picks in passing, so neither is counted.
        if (prefs.replantsGrownTrees() && type == PatchType.FRUIT_TREE && prediction.isFellable()
                && !(prefs.picksFruitInPassing() && act == PatchWork.Act.HARVEST)) {
            tally.grownTrees++;
        }
        // A ripe or unchecked bush counts as ready below, though it comes out after.
        if (PatchWork.standsEmpty(prediction, stop, prefs, nowEpochSec) || act == null
                        && PatchWork.comesOut(prediction, stop, prefs, player)) {
            // An empty patch is as good a reason to go as a finished crop; see
            // RunStatus.DUE. A checked tree lands here rather than under "ready": it
            // decodes identically to its own stump, so it would read ready for ever. A bush
            // picked bare lands here too: with nothing to pick, it is dug up for a fresh one.
            tally.empty++;
            // Bare ground takes a sapling. A tree still rooted here is not bare ground; one the
            // run replants was counted above, in grownTrees.
            if (!prediction.isFellable()) {
                tally.bare++;
            }
            // An empty patch is a reason to go only while the player has a seed for it.
            // Recorded rather than dropped, so the detail can say why the run went quiet.
            if (seedless) {
                tally.seedless++;
            } else {
                tally.actionable++;
                // Named apart from bare ground, which is all "empty" means to the player.
                if (prediction.isFellable()) {
                    // A calquat bears fruit like a fruit tree, so picked bare it is picked.
                    if (type == PatchType.FRUIT_TREE || type == PatchType.CALQUAT) {
                        tally.picked++;
                    } else {
                        tally.checked++;
                    }
                } else if (prediction.getCrop() != Crop.WEEDS && (type == PatchType.BUSH
                                || type == PatchType.CACTUS)) {
                    tally.picked++;
                }
            }
            return;
        }
        if (prediction.isIdle()) {
            return;
        }
        if (act != null) {
            tally.ready++;
            tally.actionable++;
            return;
        }
        long done = prediction.getDoneEstimateEpochSec();
        tally.growing++;
        if (done <= 0) {
            tally.undated++;
        } else if (plantedThisTrip(prediction, done, tally.tripStart)) {
            tally.plantedThisTrip++;
        }
        tally.earliestReady = earlier(done, tally.earliestReady);
        tally.latestReady = Math.max(tally.latestReady, done);
    }

    /**
     * Whether this growing crop went in on the trip the player is on now: seen this trip,
     * and finishing no sooner than a crop planted a trip's length ago would. A crop merely
     * passed on another run (Catherby's herb patch beside its fruit tree) was planted long
     * before, so it fails the second half.
     */
    private static boolean plantedThisTrip(PatchPrediction prediction, long done, long tripStart) {
        if (tripStart <= 0) {
            return false;
        }
        // Seen going in: exact, so no slack. A fruit tree passed on this trip and planted
        // two hours before on another would pass the estimate below, since its stage is
        // 160 minutes.
        if (prediction.getPlantedAtEpochSec() > 0) {
            return prediction.getPlantedAtEpochSec() >= tripStart;
        }
        // The finish estimate snaps to the crop's growth ticks, so the planting it implies
        // can read up to one stage earlier than the crop went in.
        long stage = prediction.getCrop().getTickRateMinutes() * 60L;
        long plantedAt = done - prediction.getCrop().totalGrowSeconds();
        return prediction.getObservedAtEpochSec() >= tripStart && plantedAt + stage >= tripStart;
    }

    /**
     * When the trip the player is on began, or zero when they are on none: the earliest
     * sighting in the run of patch sightings that reaches back from now with no gap longer
     * than {@link #ONE_TRIP_SECONDS}. A trip lasts as long as the player keeps working
     * patches, however long that is, and ends once they stop.
     */
    static long tripStartedAt(FarmingInputs inputs, long nowEpochSec) {
        // A player standing near patches re-stamps them every few minutes, so the chain alone
        // could reach back to an earlier run hours ago. No farm run lasts longer than this.
        long earliest = nowEpochSec - LONGEST_TRIP_SECONDS;
        List<Long> sightings = new ArrayList<>();
        for (FarmingWorldMap.PatchDef patch : FarmingWorldMap.allPatches()) {
            PatchPrediction seen = inputs.patchAt(PatchRef.of(patch.getRegionId(), patch.getVarbitId(), patch.displayName()));
            if (seen != null && seen.getObservedAtEpochSec() > 0 && seen.getObservedAtEpochSec() <= nowEpochSec) {
                sightings.add(seen.getObservedAtEpochSec());
            }
        }
        sightings.sort(Comparator.reverseOrder());
        long start = 0;
        long previous = nowEpochSec;
        for (long at : sightings) {
            if (previous - at > ONE_TRIP_SECONDS) {
                break;
            }
            start = at;
            previous = at;
        }
        return start > 0 ? Math.max(start, earliest) : 0;
    }

    private static String dueDetail(Tally tally) {
        List<String> parts = new ArrayList<>();
        // Counts without "patches": the row is one short line, and a longer one is cut off.
        if (tally.ready > 0) {
            parts.add(tally.ready + " ready");
        }
        if (tally.needsHelp > 0) {
            parts.add(tally.needsHelp + " diseased");
        }
        // Its own clause: "diseased" over a dead crop reads as something a plant cure fixes.
        if (tally.needsClearing > 0) {
            parts.add(tally.needsClearing + " dead");
        }
        // A seedless patch is also an empty one. Counting it twice cuts off the line, so the
        // count names only the empty patches the player can fill.
        int plantable = tally.empty - tally.seedless - tally.picked - tally.checked;
        if (plantable > 0) {
            parts.add(plantable + " empty");
        }
        if (tally.picked > 0) {
            parts.add(tally.picked + " picked");
        }
        if (tally.checked > 0) {
            parts.add(tally.checked + " checked");
        }
        // Apart from "empty": the emptiness is assumed until the player passes the patch.
        if (tally.unseen > 0) {
            parts.add(tally.unseen + " unseen");
        }
        // Said last: it explains why the run is smaller than it looks, and is no reason to go.
        // "Plant", not "seed": seaweed grows from spores.
        if (tally.seedless > 0) {
            parts.add(NOTHING_TO_PLANT);
        }
        return String.join(", ", parts);
    }

    /** The earlier of two dates, where zero is no date. */
    private static long earlier(long first, long second) {
        if (first <= 0) {
            return second;
        }
        return second <= 0 ? first : Math.min(first, second);
    }

    /**
     * @param readyAt when the run comes due, or zero for no date
     * @param waits whether the run waits for every patch
     */
    private static String pendingDetail(Tally tally, long readyAt, boolean waits, long nowEpochSec) {
        if (readyAt <= 0) {
            // A crop growing with no estimate holds a waiting run back without a date.
            if (waits && tally.growing > 0) {
                return "growing";
            }
            // Nothing is growing, so there is no date. With seedless patches the player
            // needs seeds, and "nothing waiting" would mislead.
            return tally.seedless > 0 ? NOTHING_TO_PLANT : "nothing waiting";
        }
        return "ready in " + FarmingDurations.describe(readyAt - nowEpochSec);
    }

    private static final String NOTHING_TO_PLANT = "nothing to plant";

    /** A run with no route to any of its stops, for any reason but a missing fairy ring. */
    private static final String NO_ROUTE_DETAIL = "no route";

    /** Worded for one patch or many: Hespori is a single patch. */
    private static final String UNSEEN_DETAIL = "not checked yet";

    // Durations are rounded by FarmingDurations, shared with the stop rows so one screen
    // never rounds the same number two ways.

    /**
     * For runs that cannot be a trip in progress: the contract, a locked run, and one with
     * no route.
     */
    private static FarmingRunStatus build(FarmingRun run, RunStatus status, String detail, long readyAt) {
        return build(run, status, detail, readyAt, false, false);
    }

    /**
     * @param aboutThePatch a contract verdict about the guild patch itself; see
     *                      {@link FarmingRunStatus#isAboutThePatch()}
     */
    private static FarmingRunStatus build(FarmingRun run, RunStatus status, String detail,
            long readyAt, boolean tripUnfinished, boolean aboutThePatch) {
        return new FarmingRunStatus(run.getId().name(), run.getId().getDisplayName(),
                status.name(), detail, readyAt, run.getId().getIconItemId(), tripUnfinished, aboutThePatch);
    }

    /** Due now, with the act at the contract's patch named in {@code detail}. */
    private static FarmingRunStatus dueAtThePatch(FarmingRun run, String detail) {
        return build(run, RunStatus.DUE, detail, 0L, false, true);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.*;
import com.larryfarming.engine.ItemCounts;
import com.larryfarming.farming.detection.*;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.*;
import com.larryfarming.snapshot.*;
import java.util.*;

/**
 * The farming settings the panel draws under each run, read off the run's structure and the
 * player's preferences, plus the travel switches.
 *
 * <p>A run's controls follow from what defines it, the same test {@link PlantingGate} uses
 * to switch it off: the herb rotation and each tree family take a tick per crop, and a run
 * of one switchable crop takes one checkbox. Calquat has site switches as well, so it opens
 * like the tree runs, onto one square for its crop.
 *
 * <p>Each control carries its {@link FarmingKeys} key, because the snapshot takes it to the
 * panel, which passes a click back to the plugin unread.
 */
public final class RunSettings {

    /** A switched-off run's status in {@code FarmingAdvice.switchedOff}. */
    public static final String STATUS_OFF = "OFF";

    private RunSettings() {
    }

    /**
     * The runs the player has switched off, as rows for the panel to draw dimmed. The panel puts
     * them after the scheduled runs, in priority order among themselves.
     */
    public static List<FarmingRunStatus> switchedOff(FarmingPreferences prefs) {
        List<FarmingRunStatus> off = new ArrayList<>();
        for (Map.Entry<RunId, List<FarmingRun>> entry : FarmingCatalogue.runsById().entrySet()) {
            if (!PlantingGate.silencesWholeRun(entry.getValue().get(0), prefs)) {
                continue;
            }
            RunId id = entry.getKey();
            // Named, so a run whose crop switches are still on does not read as plainly off.
            String detail = prefs.dropsEverySiteOf(FarmingCatalogue.siteKeys(id)) ? "no patches on" : "off";
            off.add(new FarmingRunStatus(id.name(), id.getDisplayName(), STATUS_OFF, detail, 0L, id.getIconItemId(), false, false));
        }
        off.sort(Comparator.comparingInt(s -> RunId.valueOf(s.getRunId()).getPriority()));
        return off;
    }

    /**
     * The settings behind every run that has any.
     *
     * @param sight what the patches were last seen holding, which settles whether some
     *     sites are open, such as Weiss once its patch has been seen
     * @param quiet {@link #quietPicks} for these preferences, this player and this sight
     */
    public static List<FarmingRunSettings> forRuns(FarmingPreferences prefs, PlayerState state, PatchSight sight,
            CompostStock compost, Set<String> quiet) {
        int level = farmingLevel(state);
        List<FarmingRunSettings> all = new ArrayList<>();
        for (Map.Entry<RunId, List<FarmingRun>> entry : FarmingCatalogue.runsById().entrySet()) {
            FarmingRunSettings settings = forRun(entry.getKey(), entry.getValue(), prefs, level, sites(entry.getKey(), prefs, state, sight),
                    FertileSoil.couldCast(state), quiet, compost);
            if (settings != null) {
                all.add(settings);
            }
        }
        return all;
    }

    /** Null for a run the player has no say over, such as the contract. */
    private static FarmingRunSettings forRun(RunId id, List<FarmingRun> variants,
            FarmingPreferences prefs, int level, List<FarmingSettingChoice> sites, boolean castsFertileSoil,
            Set<String> quiet, CompostStock compost) {
        // Jane decides what the contract grows.
        if (id == RunId.CONTRACT) {
            return null;
        }
        FarmingRun run = variants.get(0);
        if (run.getSeedPatchType() != null) {
            return forNamedSeeds(id, run.getSeedPatchType(), prefs, level, sites);
        }
        PatchType rotation = PlantingGate.rotationFamilyOf(run);
        if (rotation == PatchType.HERB) {
            return herbs(id, variants, prefs, level, sites, castsFertileSoil, quiet, compost);
        }
        Set<Crop> fixed = switchableFixedCrops(variants);
        if (fixed.size() == 1) {
            Crop only = fixed.iterator().next();
            return oneCrop(id, only, prefs, level, sites);
        }
        if (fixed.size() > 1) {
            return severalCrops(id, fixed, prefs, level, sites);
        }
        return null;
    }

    /**
     * A run naming its own seeds: a tick per crop of a tree family, or its one crop.
     */
    private static FarmingRunSettings forNamedSeeds(RunId id, PatchType family,
            FarmingPreferences prefs, int level, List<FarmingSettingChoice> sites) {
        List<Crop> trees = FarmingPreferences.familyChoices(family);
        if (!trees.isEmpty()) {
            List<FarmingSettingChoice> switches = family == PatchType.FRUIT_TREE ? List.of(checkbox(FarmingKeys.PICK_FRUIT_IN_PASSING,
                                    "Pick fruit from trees you pass", prefs.picksFruitInPassing()),
                            checkbox(FarmingKeys.FRUIT_TREES_WAIT_FOR_SAPLINGS, "Wait for a sapling for every patch",
                                    prefs.fruitTreesWaitForSaplings()), checkbox(FarmingKeys.REPLANT_GROWN_TREES, "Replant grown trees",
                                    prefs.replantsGrownTrees()).withTip("Chop down a grown tree and replant it when you have a sapling as"
                                            + " good or better, to earn its health check again.")) : List.of();
            List<FarmingSettingChoice> choices = new ArrayList<>(trees.size());
            // The tree drawn, not its sapling: every sapling shares one pot sprite.
            for (Crop crop : byLevel(trees)) {
                choices.add(toggle(crop, crop.getItemId(), prefs, level, null));
            }
            return seeds(id, choices, sites).choicesCaption("Trees to plant").switches(switches).build();
        }
        List<Crop> crops = CropData.plantableIn(family);
        if (crops.size() == 1 && FarmingPreferences.hasAswitch(crops.get(0))) {
            return oneCrop(id, crops.get(0), prefs, level, sites);
        }
        return null;
    }

    /** The crops in Farming level order, lowest first, as every grid draws them. */
    private static List<Crop> byLevel(List<Crop> crops) {
        List<Crop> sorted = new ArrayList<>(crops);
        sorted.sort(Comparator.comparingInt(c -> CropData.forCrop(c).getFarmingLevel()));
        return sorted;
    }

    /**
     * The herb grid in Farming level order and the crops the run plants in passing.
     */
    private static FarmingRunSettings herbs(RunId id, List<FarmingRun> variants,
            FarmingPreferences prefs, int level, List<FarmingSettingChoice> sites, boolean castsFertileSoil,
            Set<String> quiet, CompostStock compost) {
        // The herb drawn, not its seed: every herb seed is the same pile of seeds. The tags
        // are longer than the bag's one-letter ones, since here they are the only name.
        List<FarmingSettingChoice> seeds = new ArrayList<>();
        for (Crop herb : byLevel(FarmingPreferences.HERB_CHOICES)) {
            seeds.add(toggle(herb, herb.getItemId(), prefs, level, CropData.forCrop(herb).getGridTag()));
        }
        // The inventory's own tags. Only herbs and saplings draw one in the bag, but here each
        // extra stands beside the herbs and wants a name.
        List<FarmingSettingChoice> extras = new ArrayList<>();
        for (Crop crop : switchableFixedCrops(variants)) {
            extras.add(toggle(crop, prefs, level, CropData.forCrop(crop).getStoredTag()));
        }
        // Each drawn only where it does something: the level wait below the level it waits
        // for, and the spell for a player who could cast it.
        List<FarmingSettingChoice> switches = new ArrayList<>(2);
        if (level < Preset.HERB_RUN_LEVEL) {
            switches.add(checkbox(FarmingKeys.HERB_RUNS_WAIT_FOR_LEVEL, "Wait for " + Preset.HERB_RUN_LEVEL + " Farming",
                    prefs.herbRunsWaitForLevel()));
        }
        if (castsFertileSoil) {
            switches.add(checkbox(FarmingKeys.COMPOST_WITH_FERTILE_SOIL,
                    "Cast Fertile Soil with volcanic ash", prefs.compostsWithFertileSoil()));
        }
        List<FarmingPatchPick> patchPicks = patchPicks(prefs, level, sites, quiet);
        // The thresholds, the stock and the paused line show only while some allotment would
        // plant for compost. The thresholds come last, so the stock sits under them and their
        // coming and going moves no other row.
        boolean composting = patchPicks.stream().anyMatch(FarmingPatchPick::isComposting);
        List<FarmingSettingPick> picks = new ArrayList<>();
        picks.add(favouriteHerb(prefs));
        picks.add(bestSeeds(prefs));
        String stocked = null;
        if (composting) {
            stocked = compost.stockedLine(prefs.makeCompostBelow());
            // Each offers only steps that keep "Stop at" above "Restock below", so the saved
            // pair is the pair in force.
            picks.add(compostSteps("Restock below", FarmingKeys.MAKE_COMPOST_BELOW, FarmingPreferences.COMPOST_STEP,
                    prefs.stopCompostAt() - FarmingPreferences.COMPOST_STEP, prefs.makeCompostBelow(),
                    "Make compost again when your stock drops below this many uses"));
            picks.add(compostSteps("Stop at", FarmingKeys.STOP_COMPOST_AT, prefs.makeCompostBelow() + FarmingPreferences.COMPOST_STEP,
                    FarmingPreferences.COMPOST_MOST, prefs.stopCompostAt(), "Stop making compost once you have this many uses"));
        }
        return seeds(id, seeds, sites).choicesCaption("Herbs to plant").extras(extras).patchPicks(patchPicks)
                .switches(switches).picks(picks).paused(composting ? compost.pausedLine(prefs.makeCompostBelow()) : null)
                .stocked(stocked).stockedTip(stocked == null ? null : String.format(Locale.ENGLISH,
                        "Stop making compost until your stock drops below %,d", prefs.makeCompostBelow())).build();
    }

    /** A threshold dropdown offering each step from {@code least} to {@code most}. */
    private static FarmingSettingPick compostSteps(String label, String key, int least, int most, int selected,
            String hint) {
        List<FarmingSettingPick.Option> steps = new ArrayList<>();
        for (int step = least; step <= most; step += FarmingPreferences.COMPOST_STEP) {
            steps.add(new FarmingSettingPick.Option(String.valueOf(step), String.format(Locale.ENGLISH, "%,d", step), null));
        }
        return new FarmingSettingPick(key, label, FarmingSettingPick.Shape.DROPDOWN, steps, String.valueOf(selected), hint);
    }

    /**
     * Each allotment and flower patch, in the stops table's order, which groups them by farm.
     * Each offers Off, then every crop of its patch in level order. A quiet preset pick shows
     * as picked: it plants once the account can. A farm whose herb patch is switched off or
     * shut to the account, as Harmony is before the elite Morytania diary, shows none: its
     * patches are worked only beside the herb patch.
     */
    private static List<FarmingPatchPick> patchPicks(FarmingPreferences prefs, int level, List<FarmingSettingChoice> sites,
            Set<String> quiet) {
        List<FarmingPatchPick> picks = new ArrayList<>();
        for (Map.Entry<PatchRef, PatchPick> patch : FarmingCatalogue.picksByPatch().entrySet()) {
            PatchPick pick = patch.getValue();
            String herb = FarmingCatalogue.siteKey(patch.getKey());
            if (sites.stream().anyMatch(site -> site.getKey().equals(herb) && (!site.isOn() || site.isLocked()))) {
                continue;
            }
            Crop picked = prefs.picks().get(pick.getSite());
            List<FarmingSettingChoice> options = new ArrayList<>();
            options.add(new FarmingSettingChoice(FarmingKeys.OFF, "Off", 0, "OFF", 0, picked == null, false, false));
            for (Crop crop : byLevel(CropData.plantableIn(patch.getKey().type()))) {
                CropData data = CropData.forCrop(crop);
                options.add(new FarmingSettingChoice(crop.name(), crop.getDisplayName(), crop.getItemId(), data.getStoredTag(),
                        data.getFarmingLevel(), crop == picked, false, data.getFarmingLevel() > level));
            }
            picks.add(new FarmingPatchPick(pick.getFarm(), pick.getTitle(), pick.getKey(), pick.getCompostKey(),
                    prefs.plantsForCompost(pick.getSite()), CompostBins.composts(pick.getSite(), prefs, quiet), options));
        }
        return picks;
    }

    /**
     * A checkbox per site the run may drop, in the registry's fixed order. A site the
     * account cannot reach yet is locked: its own gate is shut, as Harmony is before the
     * elite Morytania diary, or the place itself is, as Weiss is before its fire.
     */
    private static List<FarmingSettingChoice> sites(RunId id, FarmingPreferences prefs, PlayerState state, PatchSight sight) {
        List<FarmingSettingChoice> sites = new ArrayList<>();
        for (FarmingCatalogue.SiteSwitch site : FarmingCatalogue.siteSwitches(id)) {
            sites.add(new FarmingSettingChoice(site.getKey(), site.getLabel(), 0, null, 0,
                    prefs.visits(site.getKey()), false, shutTo(site.getStop(), state, sight)));
        }
        return sites;
    }

    /**
     * The keys of every site this account certainly cannot work yet, the ones the sites list
     * locks. Empty for an unread state.
     */
    static Set<String> shutSites(PlayerState state, PatchSight sight) {
        Set<String> shut = new HashSet<>();
        for (RunId id : RunId.values()) {
            for (FarmingCatalogue.SiteSwitch site : FarmingCatalogue.siteSwitches(id)) {
                if (shutTo(site.getStop(), state, sight)) {
                    shut.add(site.getKey());
                }
            }
        }
        return shut;
    }

    /**
     * Whether this account certainly cannot work the stop yet. An unread answer leaves it
     * open, so a login still being read locks nothing.
     */
    private static boolean shutTo(RunStop stop, PlayerState state, PatchSight sight) {
        if (state == null) {
            return false;
        }
        if (RunAvailability.of(stop.getGate(), state) == CapabilityState.LACK) {
            return true;
        }
        Capability access = stop.getAccessGate();
        return access != null && CapabilitySources.resolve(access, state, sight).getState() == CapabilityState.LACK;
    }

    /** No favourite, then every herb the grid ticks, in the grid's order. */
    private static FarmingSettingPick favouriteHerb(FarmingPreferences prefs) {
        List<FarmingSettingPick.Option> options = new ArrayList<>();
        options.add(new FarmingSettingPick.Option(FarmingKeys.NO_FAVOURITE, "None", null));
        for (Crop herb : byLevel(FarmingPreferences.HERB_CHOICES)) {
            options.add(new FarmingSettingPick.Option(herb.name(), herb.getDisplayName(), null));
        }
        Crop favourite = prefs.favouriteHerb();
        return new FarmingSettingPick(FarmingKeys.FAVOURITE_HERB, "Favourite herb", FarmingSettingPick.Shape.DROPDOWN, options,
                favourite == null ? FarmingKeys.NO_FAVOURITE : favourite.name(), "Planted before your other herbs");
    }

    private static FarmingSettingPick bestSeeds(FarmingPreferences prefs) {
        return new FarmingSettingPick(FarmingKeys.BEST_SEEDS_EVERYWHERE, "Best seeds in", FarmingSettingPick.Shape.CHIPS, List.of(
                        new FarmingSettingPick.Option("false", "Bonus patches", "The few patches with the biggest yield bonus"),
                        new FarmingSettingPick.Option("true", "All", null)), String.valueOf(prefs.plantsBestSeedsEverywhere()), null);
    }

    /** Which run leads when several are due: the preset's first run, hardwood, or herbs. */
    public static FarmingSettingPick runFirst(FarmingPreferences prefs) {
        return new FarmingSettingPick(FarmingKeys.HERB_RUN_FIRST, "Herbs and hardwood both ready", FarmingSettingPick.Shape.CHIPS, List.of(
                        new FarmingSettingPick.Option("true", "Herbs first", null),
                        new FarmingSettingPick.Option("false", "Hardwood first", null)), String.valueOf(prefs.herbRunFirst()), null);
    }

    /** The checkbox that holds a run back until every patch on it needs a visit. */
    public static FarmingSettingChoice waitForEveryPatch(FarmingPreferences prefs) {
        return checkbox(FarmingKeys.WAIT_FOR_EVERY_PATCH, "Wait for every patch on a run", prefs.waitsForEveryPatch());
    }

    /**
     * Every switchable crop the runs' fixed-crop stops may grow, in registry order rather
     * than route order so the grid never moves when a route does, each stop's crops lowest
     * level first as the grids draw them.
     */
    private static Set<Crop> switchableFixedCrops(List<FarmingRun> variants) {
        Set<Crop> crops = new LinkedHashSet<>();
        for (FarmingRun run : variants) {
            for (RunStop stop : FarmingCatalogue.stopsInRegistryOrder(run)) {
                if (!stop.isPlanting() || stop.isPicked()) {
                    continue;
                }
                for (Crop crop : byLevel(FarmingCatalogue.cropChoices(stop))) {
                    if (FarmingPreferences.hasAswitch(crop) && !FarmingPreferences.HERB_CHOICES.contains(crop)) {
                        crops.add(crop);
                    }
                }
            }
        }
        return crops;
    }

    /**
     * A run of one switchable crop. With no site switches it takes a checkbox on its row,
     * drawn as its seed. With site switches, as calquat has, it opens like the tree runs: its
     * crop is one square, drawn as the crop itself, above its sites.
     */
    private static FarmingRunSettings oneCrop(RunId id, Crop crop, FarmingPreferences prefs, int level, List<FarmingSettingChoice> sites) {
        if (sites.isEmpty()) {
            return runSwitch(id, toggle(crop, prefs, level, null));
        }
        return seeds(id, List.of(toggle(crop, crop.getItemId(), prefs, level, null)), sites).build();
    }

    /**
     * A run whose patches take any of several crops, the anima plants: a square per crop,
     * drawn as its seed with the inventory's tag, as the tree runs open. Larry plants the first
     * one ticked that the player holds seeds for.
     */
    private static FarmingRunSettings severalCrops(RunId id, Set<Crop> crops,
            FarmingPreferences prefs, int level, List<FarmingSettingChoice> sites) {
        List<FarmingSettingChoice> choices = new ArrayList<>(crops.size());
        for (Crop crop : crops) {
            choices.add(toggle(crop, prefs, level, CropData.forCrop(crop).getStoredTag()));
        }
        return seeds(id, choices, sites).choicesCaption("Plant one of").build();
    }

    private static FarmingRunSettings runSwitch(RunId id, FarmingSettingChoice choice) {
        return settings(id, FarmingRunSettings.Shape.SWITCH, List.of(), null).runSwitch(choice).build();
    }

    private static FarmingRunSettings.FarmingRunSettingsBuilder seeds(RunId id,
            List<FarmingSettingChoice> choices, List<FarmingSettingChoice> sites) {
        return settings(id, FarmingRunSettings.Shape.SEEDS, choices, sites);
    }

    /** A run's settings with no extras and no switches until the caller sets them. */
    private static FarmingRunSettings.FarmingRunSettingsBuilder settings(RunId id,
            FarmingRunSettings.Shape shape, List<FarmingSettingChoice> choices, List<FarmingSettingChoice> sites) {
        return FarmingRunSettings.builder().runId(id.name()).shape(shape).choices(choices)
                .sites(sites).extras(List.of()).switches(List.of());
    }

    /** One crop's tick, drawn as its seed: a click writes the opposite of what is set. */
    private static FarmingSettingChoice toggle(Crop crop, FarmingPreferences prefs, int level, String tag) {
        return toggle(crop, CropData.forCrop(crop).getSeedItemId(), prefs, level, tag);
    }

    private static FarmingSettingChoice toggle(Crop crop, int itemId, FarmingPreferences prefs, int level, String tag) {
        CropData data = CropData.forCrop(crop);
        boolean on = prefs.allows(crop);
        return new FarmingSettingChoice(FarmingKeys.CROPS.get(crop), crop.getDisplayName(), itemId, tag != null ? tag : data.getTag(),
                data.getFarmingLevel(), on, false, data.getFarmingLevel() > level);
    }

    private static FarmingSettingChoice checkbox(String key, String label, boolean on) {
        return new FarmingSettingChoice(key, label, 0, null, 0, on, false, false);
    }

    /**
     * The picked patches whose crop is the preset's and the account can't plant: above its
     * Farming level, or certainly out of the seed with none of the crop in the patch to
     * pick. They say nothing until the account can plant them. A crop the player picked
     * keeps its reasons.
     */
    static Set<String> quietPicks(FarmingPreferences prefs, PlayerState state, PatchSight sight) {
        int level = farmingLevel(state);
        Set<String> quiet = new HashSet<>();
        for (Map.Entry<PatchRef, PatchPick> picked : FarmingCatalogue.picksByPatch().entrySet()) {
            String site = picked.getValue().getSite();
            Crop crop = prefs.picks().get(site);
            CropData data = crop == null ? null : CropData.forCrop(crop);
            if (data == null || prefs.picksChosen().contains(site)) {
                continue;
            }
            PatchPrediction seen = sight.at(picked.getKey());
            boolean standing = seen != null && seen.getCrop() == crop;
            if (data.getFarmingLevel() > level || !standing && SeedSelector.definitelyOutOf(crop, state, data.getSeedsPerPatch())) {
                quiet.add(site);
            }
        }
        return quiet;
    }

    /**
     * The player's Farming level, or no ceiling at all when the game has not reported it,
     * so an unread level locks nothing.
     */
    static int farmingLevel(PlayerState state) {
        if (state == null || state.getSkills() == null || !state.getSkills().containsKey(Skill.FARMING)) {
            return Integer.MAX_VALUE;
        }
        return state.getSkillLevel(Skill.FARMING);
    }

    // --- Travel --------------------------------------------------------------

    /**
     * The travel squares under their captions, each group in {@link TravelMethod}'s order,
     * which never moves. A click writes the opposite of what is set. A square for a method
     * the player has nothing for is marked missing; a house method greys only when the house
     * holds none of it, seen or declared.
     */
    public static List<FarmingSettingGroup> travelGroups(FarmingPreferences prefs, PlayerState state, HouseSight house) {
        List<FarmingSettingGroup> groups = new ArrayList<>();
        for (TravelMethod.Group group : TravelMethod.Group.values()) {
            List<FarmingSettingChoice> inGroup = new ArrayList<>();
            for (TravelMethod method : TravelMethod.values()) {
                if (method.getGroup() == group) {
                    inGroup.add(travelSquare(method, prefs, state, house));
                }
            }
            if (!inGroup.isEmpty()) {
                groups.add(new FarmingSettingGroup(group.getLabel(), inGroup));
            }
        }
        return groups;
    }

    private static FarmingSettingChoice travelSquare(TravelMethod method, FarmingPreferences prefs, PlayerState state, HouseSight house) {
        int sprite = method == TravelMethod.SPELLBOOK_SWAP ? Teleports.SPELLBOOK_SWAP.getSpriteId() : 0;
        boolean missing = !owns(method, state, house, prefs.houseDeclared());
        return new FarmingSettingChoice(method.getKey(), method.getLabel(),
                sprite > 0 ? 0 : itemFor(method), tagFor(method), 0, prefs.uses(method), missing, false, sprite,
                missing && isSeenAbsent(method, house) ? notBuilt(method) : null, false, null);
    }

    /**
     * Whether a method is furniture the house was seen without, every piece of it, so its
     * square can say so rather than "None seen yet".
     */
    private static boolean isSeenAbsent(TravelMethod method, HouseSight house) {
        return !method.getCapabilities().isEmpty() && method.getCapabilities().stream()
                .allMatch(capability -> CapabilitySources.houseSighting(capability, house) == HouseSighting.ABSENT);
    }

    private static String notBuilt(TravelMethod method) {
        return method.getCapabilities().size() == 1 ? "Not built" : "None built";
    }

    /**
     * The item a method's square draws: its first capability's, or for a method with no item
     * of its own a tablet that stands for it, tagged by {@link #tagFor}.
     */
    private static int itemFor(TravelMethod method) {
        switch (method) {
            case SALVE_GRAVEYARD_TABLETS:
                return SALVE_GRAVEYARD_TABLET;
            case TELEPORT_TABLETS:
                return CAMELOT_TABLET;
            case HOUSE_PORTALS:
            case HOUSE_FAIRY_RING:
                return HOUSE_TABLET;
            default:
                return CarryItems.iconFor(method.getCapabilities().get(0));
        }
    }

    /** The word on a square whose sprite stands for something else, or null. */
    private static String tagFor(TravelMethod method) {
        switch (method) {
            case TELEPORT_TABLETS:
                return "TABS";
            case HOUSE_PORTALS:
                return "PORT";
            case HOUSE_FAIRY_RING:
                return "RING";
            default:
                return null;
        }
    }

    /**
     * Whether the player has anything this method uses: one of its items, any teleport
     * tablet, the Salve graveyard tablet, or Spellbook Swap's level and quest. An unread
     * answer counts as owned, so an unopened bank never greys a square. A house item counts
     * as owned while declared and not seen otherwise.
     */
    private static boolean owns(TravelMethod method, PlayerState state, HouseSight house, Set<Capability> houseDeclared) {
        if (state == null) {
            return true;
        }
        switch (method) {
            case SALVE_GRAVEYARD_TABLETS:
                return state.getBankLastSeen() == null || ItemCounts.ownsAny(state, SALVE_GRAVEYARD_TABLET);
            case TELEPORT_TABLETS:
                return state.getBankLastSeen() == null || ownsAnyTablet(state) || ownsAnyOf(method, state, house, houseDeclared);
            case SPELLBOOK_SWAP:
                return canSwap(state);
            default:
                return ownsAnyOf(method, state, house, houseDeclared);
        }
    }

    private static boolean ownsAnyOf(TravelMethod method, PlayerState state, HouseSight house, Set<Capability> houseDeclared) {
        for (Capability capability : method.getCapabilities()) {
            if (CapabilitySources.resolve(capability, state, PatchSight.blind(), house, houseDeclared).getState() != CapabilityState.LACK) {
                return true;
            }
        }
        return false;
    }

    private static boolean ownsAnyTablet(PlayerState state) {
        return Arrays.stream(TABLETS).anyMatch(tablet -> ItemCounts.ownsAny(state, tablet));
    }

    /**
     * Whether Spellbook Swap's Magic level and quest are met. A quest not yet read leaves it
     * open, as an unread bank does an item.
     */
    private static boolean canSwap(PlayerState state) {
        TeleportMeans swap = Teleports.SPELLBOOK_SWAP;
        if (state.getSkills() != null && state.getSkills().containsKey(Skill.MAGIC)
                && state.getSkillLevel(Skill.MAGIC) < swap.getMagicLevel()) {
            return false;
        }
        QuestStatus quest = state.getQuests().get(swap.getQuestName());
        return quest == null || quest == QuestStatus.COMPLETED;
    }

    // --- The house -----------------------------------------------------------

    /**
     * Every house item as a row under its group, in {@link HouseItem}'s order, and how much
     * of the house Larry has seen. An item Larry has seen is settled by the sighting and
     * takes no click; an item a level or quest rules out is locked, seen or not, unless seen
     * built. Every other item is the player's declaration.
     */
    public static FarmingHouse house(FarmingPreferences prefs, PlayerState state, HouseSight house) {
        Map<HouseItem.Group, List<FarmingSettingChoice>> rows = new EnumMap<>(HouseItem.Group.class);
        boolean nexusUnseen = false;
        for (HouseItem item : HouseItem.values()) {
            Capability capability = item.getCapability();
            HouseSighting sighting = CapabilitySources.houseSighting(capability, house);
            boolean built = sighting == HouseSighting.BUILT;
            boolean outOfReach = !built && CapabilitySources.isHouseItemOutOfReach(capability, state);
            int level = outOfReach ? CapabilitySources.houseItemLevelShort(capability, state) : 0;
            boolean locked = outOfReach || sighting == HouseSighting.ABSENT;
            if (item.getGroup() == HouseItem.Group.NEXUS && sighting == HouseSighting.UNSEEN) {
                nexusUnseen = true;
            }
            rows.computeIfAbsent(item.getGroup(), g -> new ArrayList<>())
                    .add(new FarmingSettingChoice(item.getKey(), item.getLabel(), 0, null, level,
                            built || prefs.declares(item), false, locked, 0, null, sighting != HouseSighting.UNSEEN, null));
        }
        List<FarmingSettingGroup> groups = new ArrayList<>(rows.size());
        for (Map.Entry<HouseItem.Group, List<FarmingSettingChoice>> group : rows.entrySet()) {
            groups.add(new FarmingSettingGroup(group.getKey().getLabel(), List.copyOf(group.getValue())));
        }
        FarmingHouse.Sight sight = house == null || !house.isScanned() ? FarmingHouse.Sight.NOT_SEEN
                : nexusUnseen ? FarmingHouse.Sight.NEXUS_NOT_SEEN : FarmingHouse.Sight.SEEN;
        return new FarmingHouse(sight, List.copyOf(groups));
    }

    /** Teleport to house, the tablet drawn for the house's portals and fairy ring. */
    private static final int HOUSE_TABLET = 8013;

    /** Camelot teleport, the tablet drawn for every teleport tablet. */
    private static final int CAMELOT_TABLET = 8010;

    /** The tablet the Salve graveyard rung spends, read off the catalogue's teleports. */
    private static final int SALVE_GRAVEYARD_TABLET = salveGraveyardTablet();

    /** Every teleport tablet the catalogue names, for whether the player owns any. */
    private static final int[] TABLETS = tablets();

    private static int salveGraveyardTablet() {
        for (TeleportMeans means : Teleports.to(Destination.SALVE_GRAVEYARD)) {
            if (means.isTablet()) {
                return means.getItemId();
            }
        }
        throw new IllegalStateException("the catalogue has no Salve graveyard tablet");
    }

    private static int[] tablets() {
        Set<Integer> ids = new LinkedHashSet<>();
        for (Destination destination : Destination.values()) {
            for (TeleportMeans means : Teleports.to(destination)) {
                if (means.isTablet()) {
                    ids.add(means.getItemId());
                }
            }
        }
        return ids.stream().mapToInt(Integer::intValue).toArray();
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.farming.detection.CapabilityResolver;
import com.larryfarming.farming.detection.CapabilityState;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import java.util.*;
import lombok.Value;
import lombok.With;

/**
 * Which version of a run to show a player, and which spellbook to plan it on.
 *
 * <p>The default herb run is written for the Arceuus book, which is the best route only for a
 * player who can cast its spells. So every variant is planned against the book the player
 * is on and the book the variant is written for, and the pairing that reaches the most
 * patches wins. The same pairing decides both the walkthrough and the run's readiness, so
 * the two screens agree.
 *
 * <p>Ties go to the book already open: a swap costs a trip to an altar, so it has to earn
 * its keep in patches.
 */
public final class RunVariants {

    private RunVariants() {
    }

    /** A run, the book to plan it on, and what that pairing is worth. */
    @Value
    public static class Choice {
        FarmingRun run;
        @With
        Spellbook planFor;
        /**
         * Patches on stops we can see a route to, which is the strongest evidence.
         *
         * <p><b>Counted as though the player were nowhere in particular</b>, unlike
         * {@code plans}. Standing at an arrival makes it free on every book at once, which
         * erases the differences between books. Changing book is a whole-run commitment, so
         * it must not turn on one arrival the player will have left by the second stop.
         */
        int certainPatches;
        /** Those plus the ones whose route rests on something we cannot check. */
        int reachablePatches;

        /**
         * The pairing already planned, so the caller does not plan it again on a path that
         * reruns for every game event.
         *
         * <p><b>Planned knowing where the player is</b>, unlike the counts above.
         * {@code RunScheduler} walks these to decide whether a run is due and skips any stop
         * that is not a visit, so a blind plan would hide work the player can do from where
         * they stand.
         *
         * <p>Empty on a {@link Choice} built without scoring (the preview path, which names
         * a book outright); its caller plans for itself.
         */
        List<StopPlan> plans;
    }

    /**
     * The best pairing of variant and book among runs that share an id.
     *
     * @param variants every version of one run; never empty
     * @param openBook the book the player is on, which wins ties because a swap it does
     *                 not pay for is advice the player is right to ignore
     * @param resolvers a cache of one resolver per book, since building one is the
     *                  expensive half of answering this and a schedule asks it repeatedly
     */
    public static Choice best(List<FarmingRun> variants, PlayerState state, Spellbook openBook, FarmingInputs inputs,
            Map<Spellbook, CapabilityResolver> resolvers) {
        Choice best = null;
        for (FarmingRun run : variants) {
            for (Spellbook book : booksWorthTrying(run, openBook)) {
                CapabilityResolver resolver = resolvers.computeIfAbsent(book, inputs::resolverOn);
                Choice candidate = score(run, book, state, resolver, inputs.getPreferences());
                if (best == null || beats(candidate, best, state, inputs.getPreferences(), openBook)) {
                    best = candidate;
                }
            }
        }
        return best;
    }

    /**
     * The books this variant is worth measuring on: the one the player has open, and the
     * one the variant is written for.
     *
     * <p>The open book says what the run is worth if they set off now. The variant's own
     * book says what it would be worth after the swap it asks for.
     */
    private static List<Spellbook> booksWorthTrying(FarmingRun run, Spellbook openBook) {
        Spellbook book = openBook != null ? openBook : Spellbook.STANDARD;
        List<Spellbook> books = new ArrayList<>(2);
        books.add(book);
        if (run.getSpellbook() != Spellbook.ANY && run.getSpellbook() != book) {
            books.add(run.getSpellbook());
        }
        return books;
    }

    /**
     * Whether this pairing is the better one to put in front of the player.
     *
     * <p>Locked last, then the variant written for the open book, then patches, then the
     * open book as the tie-break. A run the player cannot start is worth nothing however
     * many patches it names: a Lunar variant gated behind Lunar Diplomacy must not win on
     * patches alone.
     */
    private static boolean beats(Choice candidate, Choice best, PlayerState state, FarmingPreferences prefs, Spellbook openBook) {
        boolean candidateOpen = isAvailable(candidate.run, state, prefs);
        boolean bestOpen = isAvailable(best.run, state, prefs);
        if (candidateOpen != bestOpen) {
            return candidateOpen;
        }
        // A player on a book a run is written for has already chosen it. The Lunar run adds
        // Harmony Island, which a tablet reaches from any book, so it can name one patch
        // more than the Arceuus run for a player on Arceuus. Patch count must not overturn
        // the book they are on.
        boolean candidateIsTheirs = candidateOpen && candidate.run.getSpellbook() == openBook;
        boolean bestIsTheirs = bestOpen && best.run.getSpellbook() == openBook;
        if (candidateIsTheirs != bestIsTheirs) {
            return candidateIsTheirs;
        }
        // Certain patches decide it before possible ones, so a book whose every arrival is a
        // maybe cannot beat one whose arrivals are known to work.
        if (candidate.certainPatches != best.certainPatches) {
            return candidate.certainPatches > best.certainPatches;
        }
        if (candidate.reachablePatches != best.reachablePatches) {
            return candidate.reachablePatches > best.reachablePatches;
        }
        return candidate.planFor == openBook && best.planFor != openBook;
    }

    private static boolean isAvailable(FarmingRun run, PlayerState state, FarmingPreferences prefs) {
        return RunAvailability.of(RunAvailability.gateOf(run, prefs), state)
                != CapabilityState.LACK;
    }

    /**
     * Patches this player could work, counted on the route proper. Optional stops are no
     * reason to prefer one route over another, and neither are stops the player has
     * switched off: Harmony, once dropped, must not tip the herb run to the Lunar variant.
     */
    private static Choice score(FarmingRun run, Spellbook book, PlayerState state, CapabilityResolver resolver, FarmingPreferences prefs) {
        // Sometimes two plans: the counts are blind to position and the kept plans are not
        // (see the fields on Choice). A sighted and a blind resolver differ only where a
        // zone covers the player's region or a teleport is spent on the way, because
        // STANDING_IN answers LACK elsewhere and TeleportPlanner's short-circuit uses the
        // same test. Otherwise the two plans are provably the same list, so the second is
        // skipped.
        List<StopPlan> plans = new RunPlanner(resolver).plan(run, state);
        boolean positionCouldMatter = resolver.readsPosition() && (Zone.covering(state == null ? null : state.getRegionId()) != null
                        || resolver.hasTravelTaken());
        List<StopPlan> anywhere = positionCouldMatter ? new RunPlanner(resolver.blindToPosition()).plan(run, state) : plans;
        int certain = 0;
        int reachable = 0;
        for (StopPlan plan : anywhere) {
            if (!plan.isVisit() || plan.getStop().isOptional() || PlantingGate.silences(run, plan.getStop(), prefs)) {
                continue;
            }
            int patches = plan.getStop().getPatches().size();
            reachable += patches;
            if (!plan.isUncertain()) {
                certain += patches;
            }
        }
        return new Choice(run, book, certain, reachable, plans);
    }

    /** A fresh cache, for a caller that has no schedule to share one with. */
    public static Map<Spellbook, CapabilityResolver> newResolverCache() {
        return new EnumMap<>(Spellbook.class);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.Crop;
import java.util.List;
import lombok.Value;

/**
 * The seeds for one end of the rotation, one per patch.
 *
 * <p>A list rather than a single crop because the rotation's unit is the seed: two good
 * seeds are two seeds off the top of the tier list, and a player whose best stack has one
 * seed left takes that one and the next one down.
 *
 * <p>Shorter than {@link #getWanted()} when the stock could not fill every patch.
 */
@Value
public class SeedAllocation {

    /**
     * One crop per patch, best seed first. Never null.
     *
     * <p>Best-first rather than in visit order, because the per-player patch ranking
     * decides which patch gets which seed. Catherby is worth the best seed only to a player
     * with the Kandarin diary.
     */
    List<Crop> perPatch;

    /** How many patches this end has to fill. */
    int wanted;

    /** The crop for the nth best patch of this end, or null once the seeds run out. */
    public Crop at(int index) {
        return index >= 0 && index < perPatch.size() ? perPatch.get(index) : null;
    }

    /** One crop and how many patches take it. */
    @Value
    public static class Tally {
        Crop crop;
        int count;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.farming.Crop;
import java.util.*;
import lombok.Value;

/**
 * Every seed a run plants, resolved together against one reading of the stock.
 */
@Value
public class SeedPlan {

    /**
     * The better seeds, for however many of the run's best-ranked patches the rotation sets
     * aside. Which patches those are is scored per player rather than declared here.
     */
    SeedAllocation good;

    /** The filler, for every patch the good end does not reach. */
    SeedAllocation bad;

    /**
     * What to carry out of the bank for a trip: every crop across both ends of every run
     * with its patch count, in the order the trip first meets each, good seeds first.
     *
     * <p>Each run allocates against its own rotation, so a trip has one plan per run. The
     * crops merge because late in the rotation both ends can land on one crop, and
     * "2 avantoe, 5 avantoe" describes one handful of seeds.
     */
    public static List<SeedAllocation.Tally> shoppingList(List<SeedPlan> plans) {
        Map<Crop, Integer> perCrop = new LinkedHashMap<>();
        for (SeedPlan plan : plans) {
            for (Crop crop : plan.good.getPerPatch()) {
                perCrop.merge(crop, 1, Integer::sum);
            }
            for (Crop crop : plan.bad.getPerPatch()) {
                perCrop.merge(crop, 1, Integer::sum);
            }
        }
        return tallies(perCrop);
    }

    /**
     * What the trip is actually going to put in the ground, one entry per crop with the
     * patches taking it.
     *
     * <p>The allocation records the seeds a run was <em>dealt</em>, and a dealt seed can be
     * declined:
     * {@code dealOutUpgrades} will not fell a living fruit tree for a worse sapling. Six
     * papaya saplings against five bearing palms and one bare patch is an allocation of six
     * and a planting of one, so the bag answers from the planting.
     *
     * <p>Stops naming their own crop are left out: the bag's fixed-seed line counts them
     * per patch.
     *
     * @param cropFor what each stop is planting, index-aligned with {@code plans}
     */
    public static List<SeedAllocation.Tally> goingInTheGround(List<StopPlan> plans, List<List<Crop>> cropFor) {
        Map<Crop, Integer> perCrop = new LinkedHashMap<>();
        for (int index = 0; index < plans.size(); index++) {
            StopPlan plan = plans.get(index);
            if (!plan.isVisit() || plan.getStop().isFixedCrop()) {
                continue;
            }
            for (Crop crop : cropFor.get(index)) {
                perCrop.merge(crop, 1, Integer::sum);
            }
        }
        return tallies(perCrop);
    }

    private static List<SeedAllocation.Tally> tallies(Map<Crop, Integer> perCrop) {
        List<SeedAllocation.Tally> tallies = new ArrayList<>(perCrop.size());
        for (Map.Entry<Crop, Integer> wanted : perCrop.entrySet()) {
            tallies.add(new SeedAllocation.Tally(wanted.getKey(), wanted.getValue()));
        }
        return tallies;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.ItemCounts;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.engine.farming.PatchType;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.model.Skill;
import java.util.*;

/**
 * Picks the seeds a herb run plants, from the tier list and what the player owns.
 *
 * <p>The rotation is a pair of pointers walking inward from the ends of the tier
 * list's ticked herbs. Each run takes two seeds off the good end for the run's best patches
 * and five off the bad end for the rest. When either stack runs out the pointer steps
 * inward, and when the two meet the whole thing restarts from the outside.
 *
 * <p>This class says only how many patches take each end. {@code PatchPriority} scores
 * which patches earn the better seed per player at planning time, so both ends come back
 * best seed first.
 *
 * <p>Ticks are hard. An unticked herb is never allocated, even when the result is an empty
 * allocation.
 *
 * <p>What is allocated is <em>seeds</em> (see {@link SeedAllocation}). Both ends draw from
 * the same stock, so a seed spent on a good patch is not also offered to a filler patch.
 *
 * <p>Nothing is remembered between runs. The best seed the player still holds marks where
 * the good pointer got to, so reading the pointers off current stock gives the same answer
 * as tracking them, and cannot drift.
 *
 * <p>Torstol tops the list but starts unticked, saved for hard contracts, so both ends
 * skip it unless the player ticks it.
 */
public final class SeedSelector {

    /** The Farming level that opens the Farming Guild, and the seed vault inside it. */
    static final int FARMING_GUILD_LEVEL = 45;

    private SeedSelector() {
    }

    /**
     * The rotation's seeds, counted once so several runs can draw on them in turn.
     *
     * <p>A trip can walk several families that draw on the herb rotation. Passing this one
     * mutable stock through each stops the second family spending the first family's seeds.
     * Built from the preferences rather than the run, because the window is the player's.
     *
     * <p>Package-private with its overload of {@code select}: the shared stock belongs to one
     * trip's planning.
     */
    static Stock rotationStock(FarmingPreferences prefs, PlayerState state) {
        return stockOf(state, herbWindow(prefs));
    }

    /**
     * Both ends of the rotation for one run, drawn against a stock the caller owns.
     *
     * <p>Together because the ends compete for the same seeds: allocating them apart would
     * hand the same stack to both.
     *
     * <p><b>Carried seeds are the player's choice only when they cover the run.</b> A player
     * who brings enough herb seeds for every patch to fill has chosen what to plant, and
     * being told to fetch others ignores that choice. Then only the carried seeds are
     * allocated, the best of them to the good end.
     *
     * <p>Short of that, the bag says nothing about intent. Seeds are withdrawn one click at a
     * time and each click is a new reading, so a player halfway through taking out what the
     * plan asked for carries a partial handful, and so does one with leftovers in a seed box.
     * Letting that handful lead the good end would flip the plan under them mid-withdrawal.
     * So the good end ranks over all the stock as it would with nothing carried, and only the
     * filler end draws the carried seeds first.
     *
     * <p>Ticks stay a hard rule: an unticked seed is outside the window however it got into
     * the bag.
     *
     * @param stock <b>mutated</b> as seeds are taken so several runs share one seed vault.
     *     Must come from {@link #rotationStock} on the same preferences; a stock
     *     built from another pair reads as empty
     */
    static SeedPlan select(FarmingPreferences prefs, PlayerState state, int goodPatches, int badPatches, Stock stock) {
        List<Crop> window = herbWindow(prefs);
        // A bag that covers the run draws on the carried half alone.
        List<Map<Crop, Integer>> sources = stock.carriedCovers(goodPatches + badPatches) ? List.of(stock.carried) : stock.carriedFirst();

        // The good end draws first, so the best seeds go where the yield bonus applies. It
        // walks crop by crop over every source, so a carried seed never outranks a better
        // one in the bank.
        List<Crop> good = new ArrayList<>();
        for (int i = 0; i < window.size() && good.size() < goodPatches; i++) {
            for (Map<Crop, Integer> source : sources) {
                take(window.get(i), source, good, goodPatches);
            }
        }

        // The filler end works up from the floor toward the good end, on what is left, and
        // empties one source before the next so the carried seeds go in first.
        List<Crop> bad = new ArrayList<>();
        for (Map<Crop, Integer> source : sources) {
            for (int i = window.size() - 1; i >= 0 && bad.size() < badPatches; i--) {
                take(window.get(i), source, bad, badPatches);
            }
        }

        // Handed over best-first: patches are dealt seeds best patch first, so the best
        // seed of each end must lead. A carried filler seed drawn ahead of a better banked
        // one would otherwise lead out of rank.
        Comparator<Crop> byRank = Comparator.comparingInt(window::indexOf);
        good.sort(byRank);
        bad.sort(byRank);

        return new SeedPlan(new SeedAllocation(List.copyOf(good), goodPatches),
                new SeedAllocation(List.copyOf(bad), badPatches));
    }

    /**
     * The herb seeds the player carries but has not ticked, best first, so the advice can
     * say why they are not being planted.
     *
     * <p>Only crops the player could otherwise plant: one above their Farming level is not a
     * missing tick. Nor is a herb the preset keeps for contracts (torstol): carried, it is
     * most likely bound for one, and the note would push against the preset's own advice.
     */
    public static List<Crop> carriedButUnticked(FarmingPreferences prefs, PlayerState state) {
        List<Crop> unticked = new ArrayList<>();
        for (Crop crop : FarmingCatalogue.seedPolicy().getHerbTierList()) {
            if (!FarmingPreferences.HERB_CHOICES.contains(crop) || prefs.allows(crop)
                    || Preset.DEFAULT.getHerbsKeptForContracts().contains(crop)) {
                continue;
            }
            CropData data = CropData.forCrop(crop);
            // plantableCount reads zero for a crop above the player's level.
            if (data != null && plantableCount(state, crop) > 0 && formsHeld(state, data, true) > 0) {
                unticked.add(crop);
            }
        }
        return List.copyOf(unticked);
    }

    /**
     * The seeds a run plants when it names its own seed patch type rather than drawing on
     * the herb rotation — every tree run.
     *
     * <p>The ladder ranks the type's ticked crops. A player out of mahogany plants teak, so the
     * walk continues down the {@linkplain #plantingLadder ladder} before giving up. Stock
     * is drawn down as it goes, because two patches cannot both have the last sapling.
     *
     * <p>Everything goes on the filler end: tree runs have no yield-bonus patches to hold
     * a better seed back for.
     *
     * <p>Some crops are kept off the ladder because a diary keeps them for one patch (see
     * {@link DiaryPlantings}). That patch takes its crop outside this plan.
     *
     * @param patches how many patches draw on the ladder, so without the claimed patch
     */
    static SeedPlan forPreference(FarmingPreferences prefs, PatchType seedPatchType, PlayerState state, int patches, Set<Crop> withheld) {
        List<Crop> ladder = new ArrayList<>(plantingLadder(prefs, seedPatchType));
        ladder.removeAll(withheld);
        Map<Crop, Integer> stock = new EnumMap<>(Crop.class);
        List<Crop> chosen = new ArrayList<>();
        for (Crop crop : ladder) {
            stock.put(crop, plantableCount(state, crop));
            take(crop, stock, chosen, patches);
        }
        return new SeedPlan(new SeedAllocation(List.of(), 0), new SeedAllocation(List.copyOf(chosen), patches));
    }

    /**
     * Everything a run will actually accept: the ticked crops of the patch type it names,
     * best first, or nothing when it names none.
     *
     * <p>The ticks decide the crops, so a player out of mahogany plants teak when teak is
     * ticked. A single-crop run (calquat) has one crop in its type and follows that crop's
     * tick. A diary can keep one crop for one patch; {@link DiaryPlantings#ladderAt} narrows
     * this list per stop.
     */
    public static List<Crop> plantingLadder(FarmingPreferences prefs, PatchType seedPatchType) {
        if (seedPatchType == null) {
            return List.of();
        }
        return prefs.ticked(CropData.plantableIn(seedPatchType));
    }

    /**
     * Everything a stop on this run could actually be filled from, best first.
     *
     * <p>The one answer to both "what will go in this patch" and "could anything go in it",
     * so the scheduler never counts seeds the walkthrough would not allocate.
     *
     * <p>Herbs use the rotation's ticked herbs in the tier list's order, not
     * {@link CropData#plantableIn}: the rotation ranks by experience and {@code plantableIn}
     * by level.
     */
    public static List<Crop> plantableFrom(FarmingPreferences prefs, PatchType seedPatchType, PatchType type) {
        if (seedPatchType != null) {
            return plantingLadder(prefs, seedPatchType);
        }
        if (type == PatchType.HERB) {
            return herbWindow(prefs);
        }
        // Everything else the rotation touches — allotments, flowers — takes no tick, so
        // the patch itself decides what could go in it.
        return CropData.plantableIn(type);
    }

    /**
     * The ticked herbs of the tier list, best first, with the player's favourite herb at the
     * top. The good end therefore plants the favourite first, and the filler end reaches it
     * last.
     *
     * <p>{@link #rotationStock}, {@link #select} and {@link #plantableFrom} must all read
     * this same list, or the allocation draws seeds the stock never counted.
     */
    private static List<Crop> herbWindow(FarmingPreferences prefs) {
        return prefs.ticked(prefs.favouriteFirst(FarmingCatalogue.seedPolicy().getHerbTierList()));
    }

    /**
     * Whether the player is known to hold nothing any of these crops could be planted from.
     *
     * <p>False before any seed container has been seen, as for {@link #definitelyOutOf}.
     *
     * @param needed how many one patch swallows, so an allotment's three is not read as
     *               three separate plantings' worth
     */
    public static boolean definitelyOutOfAll(List<Crop> crops, PlayerState state, int needed) {
        if (!seedsSeen(state)) {
            return false;
        }
        for (Crop crop : crops) {
            if (plantableCount(state, crop) >= needed) {
                return false;
            }
        }
        return true;
    }

    /**
     * Whether the player is known to have nothing to plant here.
     *
     * <p>False before any seed container has been seen: a stack we have never been shown is
     * not an empty one, and dropping a stop on a guess is the expensive mistake.
     *
     * @param needed how many the patch swallows, since an allotment wants three
     */
    public static boolean definitelyOutOf(Crop crop, PlayerState state, int needed) {
        return definitelyOutOfAll(List.of(crop), state, needed);
    }

    /**
     * How many patches of this tree family the player can fill: every form of every ticked
     * crop on the family's ladder they own and have the level for. -1 until every store
     * that could hold saplings has been seen, so a short count is never a guess: the bank,
     * and the seed vault once the player can enter the Farming Guild at
     * {@value #FARMING_GUILD_LEVEL}.
     */
    static int plantableAcross(FarmingPreferences prefs, PatchType seedPatchType, PlayerState state) {
        if (state == null || state.getBankLastSeen() == null || state.getSeedVaultLastSeen() == null
                        && state.getSkillLevel(Skill.FARMING) >= FARMING_GUILD_LEVEL) {
            return -1;
        }
        int owned = 0;
        for (Crop crop : plantingLadder(prefs, seedPatchType)) {
            owned += plantableCount(state, crop);
        }
        return owned;
    }

    /**
     * Whether the stores Larry has seen hold enough of this crop to fill one patch, at a
     * Farming level that plants it. Counted as the allocator counts, so the scheduler never
     * calls a patch plantable that the walkthrough would leave empty.
     *
     * @param needed the seeds one patch takes
     */
    static boolean knownToHold(Crop crop, PlayerState state, int needed) {
        return plantableCount(state, crop) >= needed;
    }

    /** How many of this crop the player could put in the ground right now. */
    private static int plantableCount(PlayerState state, Crop crop) {
        CropData data = CropData.forCrop(crop);
        if (data == null || state == null || state.getSkillLevel(Skill.FARMING) < data.getFarmingLevel()) {
            return 0;
        }
        return formsHeld(state, data, false);
    }

    /**
     * The planting stock for one crop, owned or only carried, counting every form it comes
     * in.
     *
     * <p>A tree patch takes a sapling, which players usually prepare at the bank from a
     * seed, through seedling stages in between. Every form fills a patch, so the forms are
     * summed.
     */
    private static int formsHeld(PlayerState state, CropData data, boolean carriedOnly) {
        int stock = 0;
        for (int itemId : data.getPlantingForms()) {
            stock += carriedOnly ? ItemCounts.countCarried(state, itemId, null) : ItemCounts.countOwned(state, itemId, null);
        }
        return stock;
    }

    /** Moves as many seeds of this crop into the allocation as it can still use. */
    private static void take(Crop crop, Map<Crop, Integer> stock, List<Crop> into, int wanted) {
        Integer available = stock.get(crop);
        if (available == null || available <= 0) {
            return;
        }
        int left = available;
        while (left > 0 && into.size() < wanted) {
            into.add(crop);
            left--;
        }
        stock.put(crop, left);
    }

    /** How many of each tier the player could plant right now (see {@link Stock}). */
    private static Stock stockOf(PlayerState state, List<Crop> tiers) {
        Stock stock = new Stock();
        for (Crop crop : tiers) {
            int held = plantableCount(state, crop);
            CropData data = CropData.forCrop(crop);
            // Capped at what is owned: the two counts read different containers, and a
            // carried seed is never one the player does not own.
            int carried = held == 0 || data == null ? 0 : Math.min(held, formsHeld(state, data, true));
            stock.carried.put(crop, carried);
            stock.elsewhere.put(crop, held - carried);
        }
        return stock;
    }

    /**
     * How many of each tier the player could plant right now, split into the seeds they
     * carry and the rest they own.
     *
     * <p>Zero covers above their Farming level and absent alike: the allocation walks past
     * both the same way.
     *
     * <p>Mutable, and shared by every family one trip plans, so a seed one family takes is
     * gone for the next whichever side of the split it came from.
     */
    static final class Stock {
        private final Map<Crop, Integer> carried = new EnumMap<>(Crop.class);
        private final Map<Crop, Integer> elsewhere = new EnumMap<>(Crop.class);

        private Stock() {
        }

        /** The two halves in the order the rotation draws from them. */
        private List<Map<Crop, Integer>> carriedFirst() {
            return List.of(carried, elsewhere);
        }

        /**
         * Whether the carried seeds left could fill this many patches on their own. Zero
         * patches is covered by anything, which changes nothing: there is nothing to fill.
         */
        private boolean carriedCovers(int patches) {
            return carried.values().stream().mapToInt(Integer::intValue).sum() >= patches;
        }

        /**
         * Takes one seed of this crop out of the stock, a carried one first, or nothing
         * when none is left. A seed planted outside the rotation is most likely the one in
         * the bag.
         */
        void spendOne(Crop crop) {
            for (Map<Crop, Integer> source : carriedFirst()) {
                Integer held = source.get(crop);
                if (held != null && held > 0) {
                    source.put(crop, held - 1);
                    return;
                }
            }
        }
    }

    /**
     * Whether we have been shown where seeds live. An account keeps its seeds in one of
     * these three, so having heard from none of them means every "you have none" would be
     * guesswork.
     *
     * <p>The seed box is the weak source. The vault and the bank are read while open, so
     * their stamps mean the contents were counted. The box's stamp comes from a chat line
     * about seeds going in or out, because the game never reports the box itself, so it is
     * a running tally rather than a snapshot. It still counts, so a player who keeps seeds
     * only in the box is not told to open a vault.
     */
    private static boolean seedsSeen(PlayerState state) {
        return state != null && (state.getSeedVaultLastSeen() != null || state.getBankLastSeen() != null
                        || state.getSeedBoxLastSeen() != null);
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.farming.model.GearPick;
import com.larryfarming.farming.model.LoadoutSlot;
import lombok.Value;
import lombok.With;

/**
 * What one equipment slot should hold, judged against what the player has.
 */
@Value
public class SlotAdvice {

    /** What the slot as a whole says. */
    public enum Verdict {
        /**
         * The best tier the player owns is where the run wants it: worn, or carried when
         * it works from the inventory.
         */
        SET,
        /** They own something better than what is on hand, or nothing is on hand. */
        SWAP,
        /** Nothing in this chain has been earned yet, or the bank has not been seen. */
        NOTHING_YET
    }

    LoadoutSlot slot;

    Verdict verdict;

    /** The tier to wear: the best one owned, in the form held, or null when none is. */
    GearPick best;

    /**
     * The sentence for the upgrade list when the verdict is {@link Verdict#SWAP}, already
     * naming the item, or empty for any other verdict.
     */
    @With
    String tip;
}

package com.larryfarming.farming.engine;

import com.larryfarming.farming.detection.CapabilityState;
import com.larryfarming.farming.model.*;
import com.larryfarming.snapshot.FarmingSkipReason;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.Value;
import lombok.With;

/**
 * What to do about one stop on a run: how to get there, or why not to bother.
 */
@Value
public class StopPlan {

    public enum Outcome {
        /** Go, by the named route. */
        VISIT,
        /** The route says to drop this patch when it cannot be reached cheaply. */
        SKIP,
        /**
         * Nothing reaches this patch, and the catalogue states that nothing does. The only
         * outcome that makes a claim about the game.
         */
        UNREACHABLE,
        /**
         * Every listed route has failed and the catalogue gives no fallback. A claim about
         * the catalogue, not the game: the patch may be reachable
         * by an unlisted route, so never present this as a dead end.
         */
        UNROUTED
    }

    RunStop stop;
    Outcome outcome;

    /** The route to take, or null when not visiting. */
    @With
    TravelOption route;

    /**
     * How sure we are the route works. Present a route offered on
     * {@link CapabilityState#UNKNOWN} as unsettled.
     *
     * <p>On a stop not visited, {@link CapabilityState#LACK} means every rung is a definite
     * no, and {@link CapabilityState#UNKNOWN} means a rung waits on an unread fact.
     */
    CapabilityState confidence;

    /** One clause for the player, whichever way this went. */
    String because;

    /**
     * Which kind of "not this one" this is, or null for a visit. The walkthrough sorts and
     * colours on this; {@link #because} is the sentence the player reads.
     */
    FarmingSkipReason skipReason;

    /**
     * When whatever is growing here finishes, as an epoch second, or 0 when nothing is
     * growing or the tracker has never seen the patch.
     *
     * <p>A raw instant rather than a worded countdown: it holds still, so the panel can
     * key its rebuilds on it and re-word the countdown in place without rebuilding the row
     * every minute.
     *
     * <p>Carried whenever it is known, including on {@link FarmingSkipReason#NO_SEED}
     * skips: a patch can be both growing and short of a seed for the next planting.
     */
    @With
    long readyAtEpochSec;

    /**
     * What the chosen route leans on, with any "or" already decided. The packing list is
     * built from this. Empty when not visiting or when the route asks for nothing.
     */
    @With
    Set<Capability> needs;

    /**
     * The teleport this player is making, when the route is written as a place. Null for
     * a route that names its own item, and null when not visiting.
     * It decides whether the bag packs a tablet or runes.
     */
    @With
    TeleportMeans teleport;

    /** A skip for a reason found in the ground or the stock, after the route was settled. */
    static StopPlan skip(RunStop stop, String because, FarmingSkipReason reason, long readyAtEpochSec) {
        return new StopPlan(stop, Outcome.SKIP, null, CapabilityState.HAVE, because, reason, readyAtEpochSec, Collections.emptySet(), null);
    }

    /**
     * The entries of {@code all} at these indices, in the order given: the stops, or what
     * they plant, at one arrival of a trip.
     */
    static <T> List<T> pick(List<T> all, List<Integer> indices) {
        return indices.stream().map(all::get).collect(Collectors.toList());
    }

    public boolean isVisit() {
        return outcome == Outcome.VISIT;
    }

    /** True when the route is worth flagging as a guess rather than stated flatly. */
    public boolean isUncertain() {
        return outcome == Outcome.VISIT && confidence != CapabilityState.HAVE;
    }
}

package com.larryfarming.farming.engine;

import static com.larryfarming.farming.engine.CropNames.displayNameOf;
import static com.larryfarming.farming.engine.CropNames.inSentence;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.*;
import com.larryfarming.farming.detection.CapabilityState;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.*;
import java.util.*;
import java.util.stream.Collectors;
import lombok.AllArgsConstructor;

/**
 * One arrival of a walkthrough written as its row: the heading, the route, the work waiting,
 * the plantings, the patches set aside, and the quiet note.
 *
 * <p>Everything here is already decided by the time it is called. {@link FarmingAdviceBuilder}
 * plans the run and the trip and hands each arrival over, as indices into its plans.
 */
final class StopRowWriter {

    private StopRowWriter() {
    }

    /**
     * One arrival, rendered: where it is, how to get there, and everything to plant.
     *
     * @param routing where the row's travel is read from: its instruction, clause and two
     *     icons, nothing else. Null reads them from the lead stop. Non-null only for a visit
     *     working several patches at an arrival whose stops rank their routes differently.
     *     Which patches are worked always comes from the lead.
     * @param state the player, which names the crop a fixed-crop stop plants when it plants
     *     nothing this trip; null skips the level and stock checks behind that choice
     */
    static FarmingStopAdvice adviseOnGroup(List<Integer> group, List<StopPlan> plans,
            List<List<Crop>> cropFor, Map<PatchRef, Crop> plantedIn, FarmingInputs inputs, StopPlan routing, PlayerState state) {
        StopPlan lead = leadOf(group, plans);
        StopPlan travel = routing != null ? routing : lead;
        // The two enums name the same four outcomes.
        FarmingStopAdvice.Outcome outcome = FarmingStopAdvice.Outcome.valueOf(lead.getOutcome().name());

        // Tallied by crop across the arrival, in first-met order. Counted in patches, not
        // seeds; the bag answers how many seeds a patch takes.
        boolean visiting = lead.isVisit();
        Map<Crop, Integer> patchesPerCrop = new LinkedHashMap<>();
        // The hedge belongs to the route this row prints. A sibling's doubt is moot: an
        // arrival is one journey, so reaching it reaches every patch there.
        boolean uncertain = travel.isUncertain();
        boolean anyWork = false;
        boolean workedAreExtras = true;
        boolean everyStopIsAnExtra = true;
        String note = "";
        CompostBins.Row bin = visiting ? CompostBins.rowAt(group, plans, inputs, state) : CompostBins.Row.NONE;
        for (int index : group) {
            StopPlan plan = plans.get(index);
            // Only where the player is going, so a skipped arrival lists no plantings. The
            // allotments harvested into the bin come after the rest, below.
            if (visiting && !bin.getFills().contains(index)) {
                for (Crop crop : cropFor.get(index)) {
                    patchesPerCrop.merge(crop, 1, Integer::sum);
                }
            }
            // Optional only when everything being worked here is optional. A required patch
            // left growing contributes no work, so it does not count.
            if (plan.isVisit()) {
                anyWork = true;
                workedAreExtras &= plan.getStop().isOptional();
            }
            everyStopIsAnExtra &= plan.getStop().isOptional();
            String own = noteFor(plan, cropFor.get(index), inputs, state);
            if (note.isEmpty() && !own.isEmpty()) {
                note = own;
            }
        }
        // The allotments harvested into the bin replant with the rest, so a crop is planted in
        // one line. Last, so the row is still pictured by what the farm's other patches plant.
        bin.getFills().forEach(index -> cropFor.get(index).forEach(crop -> patchesPerCrop.merge(crop, 1, Integer::sum)));
        // With no work, workedAreExtras is vacuously true, so every stop at the place
        // answers. Not the lead: a seedless limpwurt skip outranks a growing herb.
        boolean optional = anyWork ? workedAreExtras : everyStopIsAnExtra;

        List<FarmingPlantAdvice> plants = new ArrayList<>(patchesPerCrop.size());
        for (Map.Entry<Crop, Integer> planted : patchesPerCrop.entrySet()) {
            Crop crop = planted.getKey();
            plants.add(new FarmingPlantAdvice(displayNameOf(crop), crop.getItemId(), planted.getValue()));
        }

        Map<PatchRef, Crop> felling = plants.isEmpty() ? Collections.emptyMap() : treesMakingWay(group, plans, plantedIn, inputs);
        Map<PatchRef, Crop> diggingUp = visiting ? plantsComingOut(group, plans, cropFor, inputs, state) : Collections.emptyMap();
        // Only where the player is going: leadOf hands the row to a skip when every visit
        // here is an extra. Read once, for the sentence and for the contract-line check.
        List<Work> waiting = visiting ? worksAt(group, plans, cropFor, inputs, bin.getFills(), felling, diggingUp, plantedIn) : Collections.emptyList();
        int iconItemId = pictureOf(plants, waiting);
        List<String> actions = actionAt(waiting, plants, felling.values(), diggingUp.values(), state);
        // The bin first: emptying it stocks the bucket for the patches here, and a full bin
        // closed at once starts rotting sooner.
        actions.addAll(0, bin.getLines());
        if (visiting) {
            // Last, because the farmer protects what has gone in. The bag packs the same fee.
            actions.addAll(payTheFarmer(group, plans, cropFor, state));
        }
        // The errand goes first: Jane names the next contract's crop, and planting the guild
        // patches before hearing her can fill the very patch it wants. The sentence is
        // borrowed from RunScheduler so the two never disagree.
        if (visiting && anErrandIsBeingRun(group, plans) && !theWorkLineAlreadySaysIt(waiting, patchesPerCrop.keySet(), inputs)
                && !inputs.contractDetail().isEmpty() && !inputs.contractDetail().startsWith(RunScheduler.HERB_PATCH_WORK)) {
            actions.add(0, capitalise(inputs.contractDetail()));
        }

        // Every patch here not being worked, except the lead, which speaks for the row.
        List<FarmingPatchNote> setAside = new ArrayList<>();
        for (int index : group) {
            StopPlan plan = plans.get(index);
            PatchPick pick = FarmingCatalogue.pickOf(plan.getStop());
            // A player's own pick harvested with no seed to replant says why it stays empty.
            if (visiting && plan.isVisit() && pick != null && cropFor.get(index).isEmpty()
                    && inputs.getPreferences().picksChosen().contains(pick.getSite())) {
                StopPlan unplanted = StopSkipRules.skipIfNoSeed(plan.getStop(),
                        FixedCrops.cropFor(plan.getStop(), inputs.getPreferences(), state), state);
                setAside.add(new FarmingPatchNote(patchLabel(plan.getStop().primaryPatch()),
                        unplanted != null ? unplanted.getSkipReason() : FarmingSkipReason.NO_SEED,
                        unplanted != null ? unplanted.getBecause() : "", 0L));
                continue;
            }
            // A preset pick past the seed stock says nothing, as one wholly out of its seed does.
            if (plan.isVisit() || plan == lead || pick != null && plan.getSkipReason() == FarmingSkipReason.NO_SEED
                    && plan.getBecause().isEmpty() && !inputs.getPreferences().picksChosen().contains(pick.getSite())) {
                continue;
            }
            setAside.add(new FarmingPatchNote(patchLabel(plan.getStop().primaryPatch()),
                    plan.getSkipReason(), plan.getBecause(), plan.getReadyAtEpochSec()));
        }

        return FarmingStopAdvice.builder().patchName(nameOfGroup(group, plans)).arrival(lead.getStop().getArrival().name()).outcome(outcome)
                // The planner's composed sentence. A destination-named rung stores only its
                // tail ("then run east"); the teleport clause is added at planning time.
                .instruction(visiting ? travel.getBecause() : "").actions(actions).iconItemId(iconItemId).because(travel.getBecause())
                // No skip reason on a visited arrival; set-aside lines carry per-patch
                // detail. From the lead, so heading and sentence describe the same patch.
                .skipReason(visiting ? null : lead.getSkipReason()).subject(subjectOf(lead, inputs))
                // The lead's clock, matching the rest of the heading.
                .readyAtEpochSec(lead.getReadyAtEpochSec()).uncertain(uncertain).optional(optional)
                .optionalReason(optional && lead.getStop().getOptionalReason() != null ? lead.getStop().getOptionalReason() : "")
                .plants(plants).setAside(setAside).travelItemId(travelItemOf(travel)).travelSpriteId(travelSpriteOf(travel))
                .landing(landingOf(travel)).note(note).assumption(visiting ? assumptionAt(group, plans, inputs) : "").build();
    }

    /** Whether a stop being visited here is an errand rather than patch work. */
    private static boolean anErrandIsBeingRun(List<Integer> group, List<StopPlan> plans) {
        for (StopPlan plan : visitsIn(group, plans)) {
            if (plan.getStop().isErrand()) {
                return true;
            }
        }
        return false;
    }

    /** The stops at this arrival the player is visiting, in the arrival's order. */
    static List<StopPlan> visitsIn(List<Integer> group, List<StopPlan> plans) {
        List<StopPlan> visits = new ArrayList<>(group.size());
        for (int index : group) {
            if (plans.get(index).isVisit()) {
                visits.add(plans.get(index));
            }
        }
        return visits;
    }

    /**
     * Whether the row's own work line is already saying what the contract's line would.
     *
     * <p>When the contract's instruction is about a guild patch this row is already working
     * or planting, borrowing it prints the same act twice.
     *
     * <p>Two halves. The runs list says whether the instruction is about the patch at all
     * (a hand-in to Jane names the crop too, and must survive). This row says whether the
     * arrival is working that patch.
     *
     * <p>Matched on the crop, not the act: both come from one prediction of one patch, but a
     * health check and a harvest word the same tree differently. An act covering two crops
     * names neither, so the contract's line survives.
     */
    private static boolean theWorkLineAlreadySaysIt(List<Work> waiting, Collection<Crop> planting, FarmingInputs inputs) {
        Crop contracted = inputs.getContractCrop();
        if (contracted == null || !inputs.contractIsAboutThePatch()) {
            return false;
        }
        if (planting.contains(contracted)) {
            return true;
        }
        for (Work work : waiting) {
            if (work.crop == contracted) {
                return true;
            }
        }
        return false;
    }

    /**
     * The row's work: the most urgent errand at this arrival first, then every other
     * errand waiting there, one entry each.
     *
     * <p>Every act, since several families can share one place. One line each, ordered by
     * {@code Act}'s ranking; joined clauses are unreadable in the narrow panel column.
     *
     * @param plants the arrival's plantings, which an act line that replants a crop marks as said
     * @param felling grown trees coming down for a sapling, one entry per tree
     * @param diggingUp grown bushes, cacti and calquats coming out for a fresh plant
     */
    private static List<String> actionAt(List<Work> waiting, List<FarmingPlantAdvice> plants, Collection<Crop> felling,
            Collection<Crop> diggingUp, PlayerState state) {
        // The +3 is the chopping, paying and digging lines, which no work carries.
        List<String> lines = new ArrayList<>(waiting.size() + 3);
        boolean dugUpSaid = false;
        // Where the first check or harvest line sits, which the felling lines go ahead of; -1 until one is.
        int firstRoutine = -1;
        // Trees still owed a mention; crossed off as lines below speak for them.
        List<Crop> unspoken = new ArrayList<>(felling);
        for (int i = 0; i < waiting.size(); i++) {
            Work work = waiting.get(i);
            // The lead is the only one that may absorb a planting or announce itself a
            // replacement; the rest name their act plainly.
            String phrase;
            if (i == 0 && work.crop != null && unspoken.contains(work.crop)) {
                phrase = sayItIsAreplacement(work, plants, state);
                // Crossed off only for a harvest, which is the only act sayItIsAreplacement
                // words as a felling, and only for as many trees as it claimed.
                if (work.act == PatchWork.Act.HARVEST) {
                    for (int spoken = 0; spoken < work.count; spoken++) {
                        unspoken.remove(work.crop);
                    }
                }
            } else if (i == 0) {
                // A check never says a digging: the check of a plant coming out goes unsaid.
                boolean digs = work.act == PatchWork.Act.HARVEST && !diggingUp.isEmpty() && Collections.frequency(diggingUp, work.crop) == diggingUp.size()
                        && diggingUp.size() == work.count;
                // A digging the fold cannot say would follow its replant, so no fold then.
                phrase = digs || diggingUp.isEmpty() ? foldReplantIntoHarvest(work, plants, digs) : work.word();
                // A fold says the digging with it.
                dugUpSaid = digs && !phrase.equals(work.word());
            } else {
                phrase = work.word();
            }
            if (firstRoutine < 0 && (work.act == PatchWork.Act.CHECK || work.act == PatchWork.Act.HARVEST)) {
                firstRoutine = lines.size();
            }
            // Bare hands take damage instead of the nightshade. The gloves that work run to
            // over a hundred items, so the line asks for gloves without checking which.
            if (work.act == PatchWork.Act.HARVEST && work.crop == Crop.BELLADONNA) {
                lines.add(GLOVES_FOR_NIGHTSHADE);
            }
            if (!phrase.isEmpty()) {
                lines.add(phrase);
            }
        }
        // A spent tree has no act of its own: PatchWork.at answers null to a checked lumber
        // tree, and worksAt leaves out the check of a tree coming down. Either way its clearing
        // line comes before the checks and picking and before the plantings. Felling is the
        // long job, and the fruit tree lies nearer the way in at Kastori, the stop with both.
        // The trees the player chops get one line and the trees the gardener clears another.
        List<Crop> paid = new ArrayList<>();
        List<Crop> chopped = new ArrayList<>();
        for (Crop tree : unspoken) {
            (gardenerClears(tree, state) ? paid : chopped).add(tree);
        }
        int clearing = firstRoutine < 0 ? lines.size() : firstRoutine;
        int saidBefore = plants.size() - unsaid(plants).size();
        if (!chopped.isEmpty()) {
            lines.add(clearing++, sayItMustComeDown(chopped, false, plants));
        }
        if (!paid.isEmpty()) {
            lines.add(clearing, sayItMustComeDown(paid, true, plants));
        }
        // These lines go ahead of the routine line that may already have claimed a planting,
        // so their plantings move ahead of it too, and the margin keeps the row's order.
        int said = plants.size() - unsaid(plants).size();
        Collections.rotate(plants.subList(0, said), said - saidBefore);
        // After any picking of the old plant, before the new one goes in. A grown bush still
        // unchecked reads only "Dig up": picking the load the check grows is the player's
        // call, and the plant comes out either way.
        if (!diggingUp.isEmpty() && !dugUpSaid) {
            lines.add(chain("Dig up", diggingUp, plants));
        }
        return lines;
    }

    /**
     * One row line: the verb, the crop when one covers every patch, and the patch count past
     * one. "Harvest ranarr ×3", "Check maple", "Cure ×2". The margin icon pictures the crop.
     */
    static String line(String verb, Crop crop, int patches) {
        return verb + (crop == null ? "" : " " + inSentence(crop)) + FarmingPlantAdvice.countOf(patches);
    }

    /**
     * The line for trees that have to be felled before the patches under them can be
     * replanted, one entry per tree from {@link #treesMakingWay}. Clearing the stump goes
     * unsaid: a player does not leave a felled tree to regrow.
     *
     * @param paid whether the bag packs the gardener's fee for these trees rather than an axe
     * @param plants the arrival's plantings, which the line marks as said for the crops it replants
     */
    private static String sayItMustComeDown(List<Crop> felling, boolean paid, List<FarmingPlantAdvice> plants) {
        // "to clear" says what the fee buys, since a farmer's fee beside it protects crops.
        return chain(paid ? "Pay the gardener to clear" : "Chop down", felling, plants);
    }

    /**
     * An act on plants coming out, naming each crop with its patch count. When the same crops
     * go back in, in the same counts, the line says their replanting too: "Chop down, replant
     * yew, dragonfruit". Otherwise it reads "Chop down yew, dragonfruit", and the
     * planting keeps its place in the planting line.
     *
     * @param crops one entry per plant coming out
     * @param plants the arrival's plantings, which the line marks as said for the crops it replants
     */
    private static String chain(String verb, Collection<Crop> crops, List<FarmingPlantAdvice> plants) {
        Map<String, Integer> out = new LinkedHashMap<>();
        crops.forEach(crop -> out.merge(displayNameOf(crop), 1, Integer::sum));
        StringJoiner names = new StringJoiner(", ", verb + (claim(plants, out) ? ", replant " : " "), "");
        out.forEach((name, patches) -> names.add(inSentence(name) + FarmingPlantAdvice.countOf(patches)));
        return names.toString();
    }

    /**
     * Marks as said the plantings an act line replants, so the planting line leaves them
     * out. All or none: each crop must still be unsaid and planted in as many patches as the
     * line counts, or the line says no replanting.
     *
     * <p>The claimed plantings move up behind those already said, so the margin pictures
     * the act lines' crops first, as the row says them, and the planting line's after.
     *
     * @param replanted the patches of each crop, by its planting's name
     * @return whether the line says the replanting
     */
    private static boolean claim(List<FarmingPlantAdvice> plants, Map<String, Integer> replanted) {
        List<FarmingPlantAdvice> claimed = unsaid(plants).stream()
                .filter(plant -> Integer.valueOf(plant.getPatches()).equals(replanted.get(plant.getName()))).collect(Collectors.toList());
        // One planting per crop, so a match for every crop is as many matches as crops.
        if (claimed.size() != replanted.size()) {
            return false;
        }
        plants.removeAll(claimed);
        plants.addAll(plants.size() - unsaid(plants).size(), claimed.stream().map(plant -> plant.withSaid(true)).collect(Collectors.toList()));
        return true;
    }

    /** Whether the gardener clears this grown tree, the same answer the bag packs by. */
    private static boolean gardenerClears(Crop tree, PlayerState state) {
        CropData data = CropData.forCrop(tree);
        return data != null && CarryPlanner.gardenerClears(data.getPatchType(), tree, state);
    }

    /**
     * Each grown plant at this arrival that a seed now replaces, by its patch: a bush or
     * cactus, or a calquat. Only where the stop plants: with no seed for the next crop the
     * old plant is left to bear.
     *
     * <p>A calquat is a tree the player clears with a spade, as a bush, not with an axe, and
     * the game offers that only after its health check. So a calquat being replanted is dug
     * up, checked or not; a dead one has its own line. Only the wording treats it as a bush:
     * planning keeps it a tree, spent once picked.
     */
    private static Map<PatchRef, Crop> plantsComingOut(List<Integer> group, List<StopPlan> plans,
            List<List<Crop>> cropFor, FarmingInputs inputs, PlayerState state) {
        Map<PatchRef, Crop> out = new LinkedHashMap<>();
        for (int index : group) {
            StopPlan plan = plans.get(index);
            if (!plan.isVisit() || cropFor.get(index).isEmpty()) {
                continue;
            }
            for (PatchRef ref : plan.getStop().getPatches()) {
                PatchPrediction seen = inputs.patchAt(ref);
                // A calquat stop has one patch, so planting here is planting in it, and the seed
                // dealt there already rules out a calquat still growing or diseased.
                boolean calquatStands = ref.type() == PatchType.CALQUAT && seen != null && seen.getCrop() != null && !seen.isIdle()
                        && seen.getState() != CropState.DEAD;
                if (calquatStands || PatchWork.comesOut(seen, plan.getStop(), inputs.getPreferences(), state)) {
                    out.put(ref, seen.getCrop());
                }
            }
        }
        return out;
    }

    /** Said before a belladonna harvest: bare hands cannot pick nightshade. */
    static final String GLOVES_FOR_NIGHTSHADE = "Wear gloves to pick the nightshade";

    /**
     * The protection payment at this arrival, worded for the row. {@link Protection} decides
     * it from the same planting the bag reads, so the act and the packed fee always match.
     */
    private static List<String> payTheFarmer(List<Integer> group, List<StopPlan> plans, List<List<Crop>> cropFor, PlayerState state) {
        List<String> lines = new ArrayList<>(1);
        for (int index : group) {
            StopPlan plan = plans.get(index);
            if (!plan.isVisit()) {
                continue;
            }
            Protection.Fee fee = Protection.paymentAt(plan.getStop(), cropFor.get(index).size(), state);
            if (fee != null) {
                lines.add("Pay " + fee.farmer + " " + fee.amount + " " + fee.name.toLowerCase(Locale.ROOT) + " for " + fee.patches
                        + (fee.patches == 1 ? " patch" : " patches"));
            }
        }
        return lines;
    }

    /**
     * The line for an arrival whose reason to exist is the replanting, not the fruit.
     *
     * <p>Fruit on a tree will still be there next time, so the trip is for the better tree
     * going in. The line reads as a tree picked clean does, from {@link #sayItMustComeDown}:
     * fruit or none, the tree comes down. The planting keeps its own line unless the same
     * crop goes back in.
     */
    private static String sayItIsAreplacement(Work work, List<FarmingPlantAdvice> plants, PlayerState state) {
        return work.act != PatchWork.Act.HARVEST ? work.word()
                : sayItMustComeDown(Collections.nCopies(work.count, work.crop), gardenerClears(work.crop, state), plants);
    }

    /**
     * The trees at this arrival that a sapling is going in place of, by their patch.
     *
     * <p>Named as crops, not answered yes-or-no, because the wording belongs to one stop of
     * the arrival: Catherby's standing-crop flower patch must not turn "Harvest toadflax"
     * into "Chop down toadflax, clear stump".
     *
     * <p>Any grown tree, fruit or lumber, checked or still owed its health check, asked of
     * the patch by the rule the bag packs by. Read per patch from the allocation: Fossil
     * Island's three hardwood patches may take one sapling, and only that patch's tree comes
     * down. Only the allocation knows whether a tree is replaced ({@code dealOutUpgrades}
     * declines unworthy trades), and {@code CarryPlanner} packs its axe or the gardener's fee
     * from the same allocation.
     *
     * @param plantedIn which patch each seed landed in, from {@code assignCrops}; empty when
     *     the caller has no allocation, which under-states rather than invents
     */
    private static Map<PatchRef, Crop> treesMakingWay(List<Integer> group, List<StopPlan> plans,
            Map<PatchRef, Crop> plantedIn, FarmingInputs inputs) {
        Map<PatchRef, Crop> felling = new LinkedHashMap<>();
        for (StopPlan plan : visitsIn(group, plans)) {
            for (PatchRef ref : plan.getStop().getPatches()) {
                // Nothing going in here, so nothing comes out.
                if (!plantedIn.containsKey(ref)) {
                    continue;
                }
                PatchPrediction seen = inputs.patchAt(ref);
                if (seen != null && seen.getCrop() != null && CarryPlanner.treeStandsAt(ref.type(), ref, inputs)) {
                    felling.put(ref, seen.getCrop());
                }
            }
        }
        return felling;
    }

    /**
     * The produce to picture an arrival by: what goes in first, else the crop being
     * harvested or checked. 0 when neither names one.
     *
     * <p>Harvest and check only. The other acts carry a crop too, but picturing it would
     * be wrong: a dead or diseased crop is not what the player gets from the patch.
     */
    private static int pictureOf(List<FarmingPlantAdvice> plants, List<Work> waiting) {
        if (!plants.isEmpty() && plants.get(0).getProduceItemId() > 0) {
            return plants.get(0).getProduceItemId();
        }
        for (Work work : waiting) {
            boolean pictured = work.act == PatchWork.Act.HARVEST || work.act == PatchWork.Act.CHECK;
            if (pictured && work.crop != null && work.crop.getItemId() > 0) {
                return work.crop.getItemId();
            }
        }
        return 0;
    }

    /**
     * The harvest and replanting of one crop, said once: "Harvest, replant ranarr ×2".
     *
     * <p>Only where the crops and counts match (the rotation often picks a ranarr and
     * replants a toadflax), and only where the harvested patches are the ones replanted: a
     * ranarr going into the empty patch beside a harvested one is no replant of it. Other
     * crops planted here stay in the planting line.
     *
     * @param plants the arrival's plantings, which a fold marks as said for its crop
     * @param digs whether every harvested plant is dug up before its replanting, which the
     *     folded line then says between the two
     */
    private static String foldReplantIntoHarvest(Work work, List<FarmingPlantAdvice> plants, boolean digs) {
        if (work.crop == null || work.act != PatchWork.Act.HARVEST || !work.replanted
                || !claim(plants, Collections.singletonMap(displayNameOf(work.crop), work.count))) {
            return work.word();
        }
        return line(digs ? "Harvest, dig up, replant" : "Harvest, replant", work.crop, work.count);
    }

    /** The plantings no act line has claimed, which the planting line says. */
    private static List<FarmingPlantAdvice> unsaid(List<FarmingPlantAdvice> plants) {
        return plants.stream().filter(plant -> !plant.isSaid()).collect(Collectors.toList());
    }

    /** One act waiting at an arrival, and how much of it. */
    @AllArgsConstructor
    private static final class Work {
        private final PatchWork.Act act;
        private final int count;
        /** The crop covering every patch of this act, or null when they differ. */
        private final Crop crop;
        /** Whether each patch of this act takes its own crop back in, by the seeds dealt. */
        private final boolean replanted;

        /** The act said plainly, naming the crop where one covers it. */
        String word() {
            return line(act.verb, crop, count);
        }
    }

    /**
     * The work already waiting at this arrival, most urgent first, and empty when there is
     * none — or none we have seen.
     *
     * <p>Judged per patch: one grown tree beside a growing one is a visit, and the grown one
     * is the reason. Ranked, not reduced to one, because {@link #actionAt} prints every act,
     * one line each, in this order.
     *
     * <p>A plant being felled or dug up is checked on the way, which the player knows, so its
     * check is not work of its own here; that line says only the checks of plants staying.
     *
     * @param cropFor the seeds dealt to each stop, which say a fixed-crop stop's replanting
     * @param plantedIn which patch each seed landed in, which says whether any other stop's
     *     patches are the ones replanted; empty claims none of those
     */
    private static List<Work> worksAt(List<Integer> group, List<StopPlan> plans, List<List<Crop>> cropFor, FarmingInputs inputs,
            Set<Integer> except, Map<PatchRef, Crop> felling, Map<PatchRef, Crop> diggingUp, Map<PatchRef, Crop> plantedIn) {
        Map<PatchWork.Act, Integer> counts = new EnumMap<>(PatchWork.Act.class);
        Map<PatchWork.Act, Crop> only = new EnumMap<>(PatchWork.Act.class);
        // The acts with a patch that does not take its own crop back.
        Set<PatchWork.Act> notReplanted = EnumSet.noneOf(PatchWork.Act.class);
        for (int index : group) {
            StopPlan plan = plans.get(index);
            if (!plan.isVisit() || except.contains(index)) {
                continue;
            }
            for (PatchRef ref : plan.getStop().getPatches()) {
                // Predicted once, so the act and the crop come from one reading.
                PatchPrediction seen = inputs.patchAt(ref);
                PatchWork.Act act = PatchWork.at(seen, plan.getStop(), inputs.getPreferences(), inputs.getNowEpochSec());
                if (act == null || act == PatchWork.Act.CHECK && (felling.containsKey(ref) || diggingUp.containsKey(ref))) {
                    continue;
                }
                int found = counts.merge(act, 1, Integer::sum);
                // Kept only while one crop covers this act, so the wording can name it.
                only.put(act, found == 1 || only.get(act) == seen.getCrop() ? seen.getCrop() : null);
                // A fixed-crop stop's seeds are dealt by count, not patch, so none is in plantedIn.
                Crop replanting = plan.getStop().isFixedCrop() && cropFor.get(index).contains(seen.getCrop()) ? seen.getCrop() : plantedIn.get(ref);
                if (replanting != seen.getCrop()) {
                    notReplanted.add(act);
                }
            }
        }

        // In Act's declaration order, which is the ranking.
        List<Work> waiting = new ArrayList<>();
        for (PatchWork.Act act : PatchWork.Act.values()) {
            Integer count = counts.get(act);
            if (count != null && count > 0) {
                waiting.add(new Work(act, count, only.get(act), !notReplanted.contains(act)));
            }
        }
        return waiting;
    }

    /**
     * What a skipped arrival is waiting on, for the heading to name, or empty when it has
     * nothing to add.
     *
     * <p>Only the skips about something in the ground, and only from the patch the row is
     * headed by, so heading and hover name the same crop. A seed shortfall stays empty —
     * its own clause names the seed, and "no seed" cannot absorb it.
     */
    private static String subjectOf(StopPlan lead, FarmingInputs inputs) {
        if (lead.getSkipReason() != FarmingSkipReason.STILL_GROWING && lead.getSkipReason() != FarmingSkipReason.STANDING_CROP) {
            return "";
        }
        PatchPrediction seen = inputs.patchAt(lead.getStop().primaryPatch());
        if (seen == null || seen.getCrop() == null) {
            return "";
        }
        return inSentence(seen.getCrop());
    }

    /**
     * Which plan speaks for an arrival.
     *
     * <p>The first visited stop that is a reason to go: worked, and not an extra. Failing
     * that, the most urgent skip, because the row's heading, reason and sentence all come
     * from the lead and must describe the same patch.
     *
     * <p><b>An optional stop never speaks for a place anything is waiting at.</b> Its
     * {@link RunStop#getOptionalReason()} says it is worth working in passing, not worth the
     * journey.
     *
     * <p>Any skip outranks an optional visit, except a skip of a picked patch, which is
     * worked beside the herb patch: at Ortus Farm, whose herb patch has no fixed place in
     * the run, a growing allotment leaves the ready herb patch to speak.
     */
    static StopPlan leadOf(List<Integer> group, List<StopPlan> plans) {
        StopPlan inPassing = null;
        StopPlan waiting = null;
        boolean onlyPicksWait = true;
        for (int index : group) {
            StopPlan plan = plans.get(index);
            if (plan.isVisit()) {
                if (plan.getStop().isOptional()) {
                    if (inPassing == null) {
                        inPassing = plan;
                    }
                } else {
                    return plan;
                }
                continue;
            }
            onlyPicksWait &= plan.getStop().isPicked();
            if (waiting == null || FarmingSkipReason.moreUrgent(waiting.getSkipReason(), plan.getSkipReason()) != waiting.getSkipReason()) {
                waiting = plan;
            }
        }
        // A stop that cannot justify a journey does not become one by being the only thing
        // ready: the row says what the place is waiting on instead.
        if (waiting != null && !(onlyPicksWait && inPassing != null)) {
            return waiting;
        }
        // Only extras here.
        return inPassing != null ? inPassing : plans.get(group.get(0));
    }

    /**
     * Whether the player travels to this group: its row is a visit, which its lead decides.
     * A visit under a skipped lead is worked only by someone already there.
     *
     * <p>Every pass that walks the trip must read journeys this way, or the position
     * allowance and the reached patches go to an arrival the walkthrough never sends the
     * player to. False for an empty group, which {@link #leadOf} cannot answer.
     */
    static boolean isJourney(List<Integer> group, List<StopPlan> plans) {
        return !group.isEmpty() && leadOf(group, plans).isVisit();
    }

    /**
     * A patch named for a row that already says where it is: "Flower", "North allotment".
     *
     * <p>{@link FarmingWorldMap.PatchDef#displayName()} leads with the location, which would
     * repeat the block's heading.
     */
    static String patchLabel(PatchRef patch) {
        FarmingWorldMap.PatchDef def = patch.resolve();
        if (def == null) {
            return patch.getLabel();
        }
        String kind = kindOf(def.getType());
        String name = def.getPatchName();
        if (name == null || name.isEmpty()) {
            return capitalise(kind);
        }
        // Hespori, anima and mushroom patches are named for their kind: "Hespori patch",
        // never "Hespori hespori".
        if (name.equalsIgnoreCase(kind)) {
            return name + " patch";
        }
        return compassPoint(name) + " " + kind;
    }

    /** A patch kind as a player says it: "hardwood tree", "allotment". */
    static String kindOf(PatchType type) {
        return type.name().toLowerCase(Locale.ROOT).replace('_', ' ');
    }

    /** "North West" as the game writes a direction: "North-west". Other names unchanged. */
    private static String compassPoint(String name) {
        String[] words = name.split(" ");
        boolean direction = words.length == 2 && (words[0].equals("North") || words[0].equals("South"))
                && (words[1].equals("East") || words[1].equals("West"));
        return direction ? words[0] + "-" + words[1].toLowerCase(Locale.ROOT) : name;
    }

    /**
     * What to call an arrival: the place when it covers several patches, the patch itself
     * when it is only one.
     *
     * <p>Counts patches, not plans: one Fossil Island stop is three hardwood patches.
     */
    private static String nameOfGroup(List<Integer> group, List<StopPlan> plans) {
        PatchRef primary = plans.get(group.get(0)).getStop().primaryPatch();
        int patches = 0;
        for (int index : group) {
            patches += plans.get(index).getStop().getPatches().size();
        }
        if (patches == 1) {
            return nameOf(primary);
        }
        FarmingWorldMap.PatchDef def = primary.resolve();
        return def != null ? def.getLocation() : nameOf(primary);
    }

    /**
     * The arrival's own route for a visit that earns one, or null to keep the lead's.
     *
     * <p>The visit must work <em>more than one</em> patch. With a single patch actionable,
     * that patch's own chain is right, and the combined ranking would trade its best rung
     * for one suited to a patch the player is not visiting today.
     *
     * <p>Says whether this is the visit the player is travelling to and what the journey
     * before it left them ({@link RunPlanner#planArrival} with a start).
     *
     * @param reached the patches this trip has already worked, which a rung leaning on
     *     another stop is answered from. It must hold this visit's predecessors and nothing
     *     later.
     */
    static StopPlan routeForVisit(List<Integer> visit, List<StopPlan> plans, StopPlan lead, RunPlanner planner, PlayerState state,
            Map<PatchRef, CapabilityState> reached, boolean mayStandHere, RunPlanner.Start start) {
        if (!lead.isVisit()) {
            return null;
        }
        return visitsIn(visit, plans).size() < 2 ? null : planner.planArrival(lead.getStop(), state, reached, mayStandHere, start);
    }

    /**
     * A quiet aside about this stop, worth saying even about a confident visit. Why a stop
     * was skipped lives in {@link StopPlan#getBecause()} instead.
     *
     * <p>Two sources, joined when both apply: the stop's own caveat from the catalogue, and,
     * for a paced extra whose patch is unseen, a note that the visit follows the crop's
     * pacing rather than the patch. Once seen, {@link StopSkipRules#skipIfStillGrowing}
     * decides.
     *
     * @param planted what the stop is planting, which names the crop being paced
     */
    private static String noteFor(StopPlan plan, List<Crop> planted, FarmingInputs inputs, PlayerState state) {
        RunStop stop = plan.getStop();
        Crop crop = planted.isEmpty() ? FixedCrops.cropFor(stop, inputs.getPreferences(), state) : planted.get(0);
        int everyNth = FarmingCatalogue.everyNthRun(stop, crop);
        if (plan.isVisit() && everyNth > 1 && inputs.patchAt(stop.primaryPatch()) == null) {
            return "Planted once in " + everyNth + " herb runs.";
        }
        return "";
    }

    /**
     * What the row owns up to guessing: the scheduler counts an unseen patch as empty
     * ground, which may be what sent the player here. "Unseen, assumed empty", with a count
     * when only some are. Empty when every patch the row visits to plant has been seen.
     */
    private static String assumptionAt(List<Integer> group, List<StopPlan> plans, FarmingInputs inputs) {
        // Every patch, as the scheduler counts them: Fossil Island's three hardwood patches
        // are one stop.
        int planting = 0;
        int unseen = 0;
        for (StopPlan plan : visitsIn(group, plans)) {
            if (!plan.getStop().isPlanting()) {
                continue;
            }
            for (PatchRef patch : plan.getStop().getPatches()) {
                planting++;
                if (inputs.patchAt(patch) == null) {
                    unseen++;
                }
            }
        }
        if (unseen == 0) {
            return "";
        }
        return (unseen == planting ? "Unseen" : unseen + " unseen") + ", assumed empty";
    }

    // --- What a route looks like ---------------------------------------------

    /**
     * The item this stop's route is taken on, or 0 for one that is cast or walked.
     *
     * <p>A tablet answers for itself. Otherwise the first of the route's needs with an icon:
     * a rung is often an item plus something invisible (a cloak and a diary tier), and the
     * player clicks the item.
     */
    private static int travelItemOf(StopPlan plan) {
        if (!plan.isVisit()) {
            return 0;
        }
        TeleportMeans means = plan.getTeleport();
        if (means != null && means.isTablet()) {
            return means.getItemId();
        }
        for (Capability capability : plan.getNeeds()) {
            int itemId = CarryItems.iconFor(capability);
            if (itemId > 0) {
                return itemId;
            }
        }
        return 0;
    }

    /** The spell icon this stop's route is cast from, or 0 when it is not a spell. */
    private static int travelSpriteOf(StopPlan plan) {
        TeleportMeans means = plan.isVisit() ? plan.getTeleport() : null;
        return means != null && means.isSpell() ? means.getSpriteId() : 0;
    }

    /** The place this route's teleport lands at, or null for a route written as an item. */
    private static String landingOf(StopPlan plan) {
        Destination landing = plan.isVisit() && plan.getRoute() != null ? plan.getRoute().getDestination() : null;
        return landing == null ? null : landing.name();
    }

    // --- Plumbing ------------------------------------------------------------

    /** A mid-sentence clause, such as the runs list's contract detail, made to open a line. */
    private static String capitalise(String sentence) {
        return sentence == null || sentence.isEmpty() ? "" : Character.toUpperCase(sentence.charAt(0)) + sentence.substring(1);
    }

    /** The game's own name for the patch, so the panel and the world agree. */
    private static String nameOf(PatchRef patch) {
        FarmingWorldMap.PatchDef def = patch.resolve();
        return def != null ? def.displayName() : patch.getLabel();
    }
}

package com.larryfarming.farming.engine;

import static com.larryfarming.farming.engine.CropNames.inSentence;

import com.larryfarming.engine.farming.*;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.farming.catalogue.FarmingCatalogue;
import com.larryfarming.farming.model.*;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.FarmingSkipReason;
import java.util.ArrayList;
import java.util.List;

/**
 * The stops a run leaves alone for what is in their ground or in the player's stock: a
 * standing crop still doing its job, a patch still growing, a seed the player does not
 * have.
 *
 * <p>Route refusals are {@link RunPlanner}'s. These rules run after it, on the stops it
 * routed, and turn a visit into a skip or drop it.
 */
final class StopSkipRules {

    private StopSkipRules() {
    }

    /**
     * Drops the stops that today's trip has nothing to do at: a standing crop still doing
     * its job, an every-second-run extra whose patch is not due yet, or a patch simply
     * still occupied.
     *
     * <p>A white lily protects the allotments beside it until it dies, so a patch seen
     * holding a living one has nothing to do at it. The bush and cactus crops are visited
     * every few runs; rather than count runs, the pacing is read off the patch: still
     * growing means not due.
     *
     * <p>Only when the patch has been seen. Patch varbits read true only while the player is
     * in the region, so an unknown patch keeps its stop: a missed lily costs a diseased
     * crop and a skipped ready cactus a whole harvest, while a wasted visit costs a moment.
     */
    static List<StopPlan> leaveStandingCrops(FarmingRun run, List<StopPlan> plans, FarmingInputs inputs, PlayerState state) {
        List<StopPlan> kept = new ArrayList<>(plans.size());
        for (StopPlan plan : plans) {
            RunStop stop = plan.getStop();
            // Dropped, not skipped: a switched-off crop needs no row explaining it.
            if (PlantingGate.silences(run, stop, inputs.getPreferences())) {
                continue;
            }
            if (!plan.isVisit()) {
                kept.add(plan);
                continue;
            }
            // Before the patch rules below. The contract's stop names the guild herb patch
            // only as a place to be; its verdict comes from the runs list, which reads the
            // contract's own varbits.
            if (stop.isErrand()) {
                kept.add(inputs.contractIsStillGrowing() ? skipUntilTheErrandIsDue(stop, inputs) : plan);
                continue;
            }
            PatchPrediction seen = inputs.patchAt(stop.primaryPatch());
            StopPlan skip = null;
            if (stop.isFixedCrop()) {
                Crop crop = FixedCrops.cropFor(stop, inputs.getPreferences(), state);
                boolean workWaiting = anythingToDoAt(stop, inputs);
                if (seen != null && FixedCrops.stands(stop, seen.getCrop(), inputs.getPreferences())) {
                    skip = skipIfStanding(stop, seen);
                } else if (FarmingCatalogue.everyNthRun(stop, crop) > 1) {
                    skip = skipIfStillGrowing(stop, seen);
                }
                // The standing and pacing rules read only the stop's own crops. Any crop
                // still growing in every patch blocks the seed, as at a rotation stop, so
                // the visit would have nothing to do. A redberry bush growing in the
                // whiteberry patch skips the stop.
                if (skip == null && stop.isPlanting()) {
                    skip = skipIfPatchesStillFull(stop, inputs);
                }
                // A bush or cactus picked bare reads HARVESTABLE while it restocks, so the
                // growth rules above miss it. With nothing to pick and no room for a seed,
                // the visit would have nothing to do.
                if (skip == null && stop.isPlanting() && !workWaiting
                        && CropAssigner.openFixedPatches(stop, inputs, state) == 0) {
                    skip = skipWhileRestocking(stop, inputs);
                }
                // A missing seed may take over a growth skip: the wait resolves itself, the
                // empty stack does not. foldIn keeps the growth estimate. Not asked where
                // work is waiting: a ready limpwurt is worth the harvest without a seed to
                // follow, and the runs list counts it ready. A dead anima plant is not such
                // work: it is cleared only to plant the next. A preset pick says nothing of its
                // seed, so its growing crop keeps the growth skip.
                StopPlan shortfall = skipIfNoSeed(stop, crop, state);
                PatchPick pick = FarmingCatalogue.pickOf(stop);
                boolean quietOnSeed = skip != null && shortfall != null && shortfall.getSkipReason() == FarmingSkipReason.NO_SEED
                        && pick != null && !inputs.getPreferences().picksChosen().contains(pick.getSite());
                if ((!workWaiting || stop.patchType() == PatchType.ANIMA) && !quietOnSeed) {
                    skip = foldIn(skip, shortfall);
                }
            } else if (stop.isPlanting()) {
                skip = skipIfPatchesStillFull(stop, inputs);
                skip = foldIn(skip, skipIfNoRotationSeed(run, stop, inputs, state));
            } else if (everyPatchLookedAt(stop, inputs) && !anythingToDoAt(stop, inputs)) {
                // A stop that puts nothing in the ground, every patch looked at and none
                // wanting anything, is dropped, not skipped: there is no decision to explain.
                // Never on a guess: an unseen patch keeps it.
                continue;
            }
            if (skip == null && stop.isPlanting()) {
                skip = skipIfUnseenWithNoKnownSeed(run, stop, inputs, state);
            }
            kept.add(skip != null ? skip : plan);
        }
        return kept;
    }

    /**
     * Whether anything at this stop is worth the trip on its own account — a harvest, a
     * health check, a cure — whatever the seed stock turns out to say.
     *
     * <p>{@link PatchWork} answers it, as it does for the runs list, so the two cannot
     * contradict each other on screen.
     */
    private static boolean anythingToDoAt(RunStop stop, FarmingInputs inputs) {
        for (PatchRef ref : stop.getPatches()) {
            if (PatchWork.at(inputs.patchAt(ref), stop, inputs.getPreferences(), inputs.getNowEpochSec()) != null) {
                return true;
            }
        }
        return false;
    }

    /**
     * Whether every patch at this stop has been seen.
     */
    private static boolean everyPatchLookedAt(RunStop stop, FarmingInputs inputs) {
        for (PatchRef ref : stop.getPatches()) {
            PatchPrediction seen = inputs.patchAt(ref);
            if (seen == null || seen.getCrop() == null) {
                return false;
            }
        }
        return true;
    }

    /**
     * Stops the allocation could not reach, dropped once it is known which those are.
     *
     * <p>{@link #skipIfNoRotationSeed} only catches a player with <em>no</em> eligible seed.
     * One palm sapling and five fruit tree patches passes it, so the stops the sapling
     * never reached must be dropped here.
     *
     * <p>Runs after {@link CropAssigner#assignCrops}, the first point where it is known which
     * stops draw a seed. It never reassigns seeds. Same guards as the run-wide check: only
     * planting stops whose every patch stands empty, since a crop in a patch is a reason to
     * go.
     */
    static List<StopPlan> dropStopsTheSeedsRanOutBefore(List<StopPlan> plans, List<List<Crop>> cropFor, FarmingInputs inputs) {
        List<StopPlan> kept = new ArrayList<>(plans.size());
        for (int i = 0; i < plans.size(); i++) {
            StopPlan plan = plans.get(i);
            boolean ranOut = seedRanOutAt(plan, cropFor.get(i), inputs);
            if (!ranOut && !leftStandingAt(plan, cropFor.get(i), inputs)) {
                kept.add(plan);
                continue;
            }
            // A tree the run declined to fell is not a seed that ran out; "no seed" would
            // send the player to buy a sapling they hold.
            kept.add(StopPlan.skip(plan.getStop(), "", ranOut && !anythingStandingAt(plan, inputs) ? FarmingSkipReason.NO_SEED
                    : FarmingSkipReason.STANDING_CROP, 0L));
        }
        return kept;
    }

    /**
     * Whether any patch at this stop still holds a living crop the run is keeping.
     *
     * <p>Only names a skip {@link #seedRanOutAt} already decided. Reads patches through
     * {@link #stillStandingIn}, as the planting does, so the row's reason matches why no
     * sapling was seated.
     */
    static boolean anythingStandingAt(StopPlan plan, FarmingInputs inputs) {
        for (PatchRef ref : plan.getStop().getPatches()) {
            if (stillStandingIn(ref, plan.getStop(), inputs) != null) {
                return true;
            }
        }
        return false;
    }

    /**
     * What is growing in this patch that picking it would leave behind, or null.
     *
     * <p>Null means there is room: bare ground, or a crop the harvest removes (a herb is
     * uprooted when picked, an allotment pulled). The exceptions are trees. A fruit tree goes
     * on fruiting after picking, and a grown lumber tree stays rooted after its check, so a
     * sapling goes in only once the tree is chopped down. Naming the tree makes that a cost
     * {@code CropAssigner.dealOutUpgrades} must justify.
     *
     * <p>Asks what is alive in the patch, not what it offers today, so it does not use
     * {@link PatchWork#standsEmpty} for trees: a picked tree is still a tree. Growth matters
     * only to tell a grown lumber tree from bare ground; whether a half-grown tree is worth
     * trading is {@link CropAssigner#assignCrops}'s call.
     */
    static Crop stillStandingIn(PatchRef ref, RunStop stop, FarmingInputs inputs) {
        PatchPrediction seen = inputs.patchAt(ref);
        // A checked lumber tree is still rooted, though no stop declares it a standing crop.
        // Asked first because the patch knows: the object offers "Chop down".
        if (seen != null && seen.isFellable()) {
            return seen.getCrop();
        }
        // So does one still owed its check, which the check leaves rooted. If it read as
        // ground, checking it would move it behind every bare patch mid-visit, and the
        // sapling it was dealt would go elsewhere.
        if (owedItsCheckBeforeTheAxe(ref, seen)) {
            return seen.getCrop();
        }
        if (seen == null || !FixedCrops.stands(stop, seen.getCrop(), inputs.getPreferences()) || seen.getCrop() == null
                || seen.getCrop() == Crop.WEEDS) {
            return null;
        }
        // A dead crop is dug out, leaving bare ground. A diseased one is cured and stays.
        if (seen.getState() == CropState.DEAD) {
            return null;
        }
        // A regrowing crop stands between harvests, fruit on it or not. Fellable trees
        // returned above, so HARVESTABLE here is the stump of a felled tree: bare ground. A
        // tree still filling out counts as standing.
        if (seen.getCrop().getRegrowTickRateMinutes() > 0) {
            return seen.getState() == CropState.HARVESTABLE ? null : seen.getCrop();
        }
        // A standing crop that does not regrow: a white lily picked for a flower patch. A
        // guard flower stands while it lives, so standsEmpty decides.
        return PatchWork.standsEmpty(seen, stop, inputs.getPreferences(), inputs.getNowEpochSec()) ? null : seen.getCrop();
    }

    /**
     * Whether this patch holds a grown regular or hardwood tree awaiting its health check,
     * which then has to be chopped down. A redwood is cleared with a spade after its check,
     * so it is ground on both sides of it.
     */
    private static boolean owedItsCheckBeforeTheAxe(PatchRef ref, PatchPrediction seen) {
        if (seen == null || seen.getCrop() == null || seen.isIdle() || seen.getState() != CropState.GROWING || isStillGrowing(seen)) {
            return false;
        }
        PatchType type = ref.type();
        return type == PatchType.TREE || type == PatchType.HARDWOOD_TREE;
    }

    /**
     * Whether the only thing left here is fruit on a tree the player would rather keep.
     *
     * <p>Felling a tree you cannot replant turns a renewable patch into an empty one, so
     * with no sapling to plant the advice is to leave it standing.
     *
     * <p>Only where nothing is assigned: {@code CropAssigner.dealOutUpgrades} has already
     * decided whether an upgrade is worth felling for. And only where a harvest is the sole
     * act; a diseased, dead or grown-and-unchecked tree is a reason to go on its own, and
     * {@link PatchWork#at} ranks those above a harvest.
     */
    static boolean leftStandingAt(StopPlan plan, List<Crop> assigned, FarmingInputs inputs) {
        if (!plan.isVisit() || !plan.getStop().isStandingCrop() || !assigned.isEmpty() || inputs.getPreferences().picksFruitInPassing()
                || plan.getStop().isErrand()) {
            return false;
        }
        boolean anythingToPick = false;
        for (PatchRef ref : plan.getStop().getPatches()) {
            PatchWork.Act act = PatchWork.at(inputs.patchAt(ref), plan.getStop(), inputs.getPreferences(), inputs.getNowEpochSec());
            if (act == null) {
                continue;
            }
            if (act != PatchWork.Act.HARVEST) {
                return false;
            }
            anythingToPick = true;
        }
        // A stop with no work at all is dropped elsewhere; "left standing" would name a tree
        // that is not there.
        return anythingToPick;
    }

    /**
     * Whether this stop was going to plant and the stock ran out before it.
     */
    static boolean seedRanOutAt(StopPlan plan, List<Crop> assigned, FarmingInputs inputs) {
        if (!plan.isVisit() || !plan.getStop().isPlanting() || !assigned.isEmpty()) {
            return false;
        }
        // An errand is the reason to go, so no seed shortage drops it. The contract's held
        // patch is assigned nothing, which would otherwise read as a seed running out.
        return !plan.getStop().isErrand() && everyPatchStandsEmpty(plan.getStop(), inputs);
    }

    private static boolean everyPatchStandsEmpty(RunStop stop, FarmingInputs inputs) {
        for (PatchRef ref : stop.getPatches()) {
            if (!PatchWork.standsEmpty(inputs.patchAt(ref), stop, inputs.getPreferences(), inputs.getNowEpochSec())) {
                return false;
            }
        }
        return true;
    }

    /**
     * A stop for one particular crop, dropped when the player cannot plant it: below its
     * Farming level, or holding none of its seed.
     *
     * <p>A stop naming its own crop bypasses the rotation's stock allocation, so it needs
     * its own check. Only on a definite answer: an unread level grows anything, and an
     * unseen stack is not an empty one.
     *
     * @param crop what {@link FixedCrops#cropFor} would plant here: the best growable
     *     ticked crop, or the lowest ticked one when none is growable
     */
    static StopPlan skipIfNoSeed(RunStop stop, Crop crop, PlayerState state) {
        CropData data = crop == null ? null : CropData.forCrop(crop);
        if (data == null) {
            return null;
        }
        // Checked first: below the level, "no seed" is false and would send the player to
        // buy seeds they hold, and holding the seed would not make it plantable.
        if (FixedCrops.belowLevel(state, data)) {
            return StopPlan.skip(stop, inSentence(crop) + " needs " + data.getFarmingLevel() + " Farming",
                    FarmingSkipReason.NEEDS_LEVEL, 0L);
        }
        if (!SeedSelector.definitelyOutOf(crop, state, data.getSeedsPerPatch())) {
            return null;
        }
        // A tree names both forms: potting a held seed is a bank trip, buying a sapling a
        // shop trip. Item names are the game's ("no oak sapling or acorn"). Any ticked
        // anima seed would do, so the line names none of the three.
        String stock = data.isSaplingPlanted() ? data.getSaplingName() + " or " + data.getSeedName()
                : data.getPatchType() == PatchType.ANIMA ? "anima seed" : data.getSeedName();
        return StopPlan.skip(stop, "no " + inSentence(stock), FarmingSkipReason.NO_SEED, 0L);
    }

    /**
     * The rotation's own seed shortfall: patches standing empty and nothing in stock to
     * fill them.
     *
     * <p>What goes in a herb, allotment or tree patch is chosen from stock each run, so the
     * question is asked of the rotation (or ladder) as a whole, matching
     * {@link RunScheduler}'s count of seedless patches.
     *
     * <p>Only when every patch {@link PatchWork#standsEmpty}: a crop in a patch is a reason to
     * go whether or not a seed follows. A tree already checked counts as empty, because
     * replanting is the only thing left to do at it. Unobserved patches never count.
     */
    private static StopPlan skipIfNoRotationSeed(FarmingRun run, RunStop stop, FarmingInputs inputs, PlayerState state) {
        if (!RunScheduler.definitelyOutOfSeeds(run, stop, state, inputs.getPreferences()) || !everyPatchStandsEmpty(stop, inputs)) {
            return null;
        }
        // No clause: the rotation has no one seed to name.
        return StopPlan.skip(stop, "", FarmingSkipReason.NO_SEED, 0L);
    }

    /**
     * A stop whose every patch is unseen, with no seed Larry knows the player holds for it.
     * The patch is assumed empty, so planting is the only thing to do there, and without a
     * known seed the row could name nothing to plant. The scheduler counts such a patch for
     * nothing, by the same {@link RunScheduler#knowsAseedFor}.
     */
    private static StopPlan skipIfUnseenWithNoKnownSeed(FarmingRun run, RunStop stop, FarmingInputs inputs, PlayerState state) {
        for (PatchRef ref : stop.getPatches()) {
            if (inputs.patchAt(ref) != null) {
                return null;
            }
        }
        return RunScheduler.knowsAseedFor(run, stop, state, inputs.getPreferences()) ? null
                : StopPlan.skip(stop, "", FarmingSkipReason.NO_SEED, 0L);
    }

    /**
     * Two reasons for skipping one stop, resolved into the one worth showing.
     *
     * <p>The reason is ranked by {@link FarmingSkipReason}, but the later growth estimate is
     * kept from either, so a patch both growing and short of a seed names the errand and
     * still counts down. A tie goes to {@code current}.
     *
     * <p>A level shortfall takes no estimate. The crop finishing does not let the player
     * plant, so "Farming level too low, ready in 2h" would promise a wait that fixes
     * nothing.
     */
    private static StopPlan foldIn(StopPlan current, StopPlan candidate) {
        if (current == null) {
            return candidate;
        }
        if (candidate == null) {
            return current;
        }
        FarmingSkipReason winner = FarmingSkipReason.moreUrgent(current.getSkipReason(), candidate.getSkipReason());
        StopPlan kept = winner == current.getSkipReason() ? current : candidate;
        if (winner == FarmingSkipReason.NEEDS_LEVEL) {
            return kept;
        }
        return kept.withReadyAtEpochSec(Math.max(current.getReadyAtEpochSec(), candidate.getReadyAtEpochSec()));
    }

    /**
     * The errand skip: an errand whose run is not calling for it yet.
     *
     * <p>A skip, not a drop: the clicked-run path plans whatever was clicked, and clicking
     * "Contract" must show something. The row borrows the runs list's sentence and clock so
     * the two agree and the row counts down.
     */
    private static StopPlan skipUntilTheErrandIsDue(RunStop stop, FarmingInputs inputs) {
        String because = inputs.contractDetail();
        return StopPlan.skip(stop, because.isEmpty() ? "nothing to do for the contract yet" : because,
                FarmingSkipReason.STILL_GROWING, inputs.contractReadyAtEpochSec());
    }

    /**
     * The standing-crop skip: nothing to do at a patch already holding a live one of the
     * crops the stop may grow.
     */
    private static StopPlan skipIfStanding(RunStop stop, PatchPrediction seen) {
        if (seen == null || !FixedCrops.grows(stop, seen.getCrop()) || !isAlive(seen.getState())) {
            return null;
        }
        return StopPlan.skip(stop, "your " + inSentence(seen.getCrop()) + " is still growing here",
                FarmingSkipReason.STANDING_CROP, seen.getDoneEstimateEpochSec());
    }

    /** The paced skip: nothing to harvest yet at a patch still filling out. */
    private static StopPlan skipIfStillGrowing(RunStop stop, PatchPrediction seen) {
        if (!isStillGrowing(seen) || !FixedCrops.grows(stop, seen.getCrop())) {
            return null;
        }
        return StopPlan.skip(stop, "your " + inSentence(seen.getCrop()) + " is still growing",
                FarmingSkipReason.STILL_GROWING, seen.getDoneEstimateEpochSec());
    }

    /**
     * The rotation's own skip: a patch we can see already has a crop growing in it.
     *
     * <p>Used by rotation stops, which have no fixed crop for the other checks to key on, and
     * by fixed-crop stops whose own rules found no skip. Any growing crop counts, chosen by
     * this run or not.
     *
     * <p>Only a crop still filling out. Ready, diseased, dead and empty patches all have work
     * waiting. Weeds read as idle, not as a crop.
     */
    private static StopPlan skipIfPatchesStillFull(RunStop stop, FarmingInputs inputs) {
        // Every patch must be growing, not just the primary: Fossil Island is three hardwood
        // patches on one journey. The stop is ready when its last patch finishes.
        long readyAt = 0L;
        for (PatchRef ref : stop.getPatches()) {
            PatchPrediction seen = inputs.patchAt(ref);
            if (!isStillGrowing(seen)) {
                return null;
            }
            readyAt = Math.max(readyAt, seen.getDoneEstimateEpochSec());
        }
        // Named from the primary patch, which the row's heading also names.
        PatchPrediction primary = inputs.patchAt(stop.primaryPatch());
        if (primary == null || primary.getCrop() == null) {
            return null;
        }
        return StopPlan.skip(stop, "your " + inSentence(primary.getCrop()) + " is still growing here",
                FarmingSkipReason.STILL_GROWING, readyAt);
    }

    /**
     * A skip for a stop whose every patch holds a plant restocking its produce, dated by
     * the last of them to restock. Called only once no patch is open and nothing waits.
     */
    private static StopPlan skipWhileRestocking(RunStop stop, FarmingInputs inputs) {
        PatchPrediction primary = inputs.patchAt(stop.primaryPatch());
        if (primary == null || primary.getCrop() == null) {
            return null;
        }
        long readyAt = 0L;
        for (PatchRef ref : stop.getPatches()) {
            PatchPrediction seen = inputs.patchAt(ref);
            if (seen != null) {
                readyAt = Math.max(readyAt, seen.getDoneEstimateEpochSec());
            }
        }
        return StopPlan.skip(stop, "your " + inSentence(primary.getCrop()) + " is regrowing here",
                FarmingSkipReason.STILL_GROWING, readyAt);
    }

    /** Whether what is in the patch is still doing its job. */
    private static boolean isAlive(CropState state) {
        return state == CropState.GROWING || state == CropState.HARVESTABLE;
    }

    /**
     * Whether the crop here is still growing rather than ready to be harvested.
     *
     * <p>Narrower than {@link #isAlive}: for an every-second-run stop the harvest is the
     * reason to go, so HARVESTABLE does not count.
     *
     * <p>The tracker sets HARVESTABLE only from a direct observation (see
     * {@link PatchPrediction}), so the state is read as-is. {@link
     * com.larryfarming.engine.farming.FarmingTracker#predict} advances {@code stage} to now, so a
     * stage short of the last is still growing. A prediction with no timing carries 0 of 0
     * stages, so the stage comparison is skipped when there is no count.
     *
     * <p>False for an unseen patch, one with no crop, and an idle one: weeds are not a crop.
     */
    static boolean isStillGrowing(PatchPrediction prediction) {
        if (prediction == null || prediction.getCrop() == null || prediction.isIdle() || prediction.getState() != CropState.GROWING) {
            return false;
        }
        return prediction.getStages() <= 0 || prediction.getStage() < prediction.getStages() - 1;
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.farming.model.Arrival;
import java.util.ArrayList;
import java.util.List;

/**
 * The order a single run's stops are walked in, and those stops grouped into arrivals.
 *
 * <p>Shared by the crop allocation, which deals seeds in walking order, and the walkthrough,
 * which draws one row per arrival. A merged trip walks {@link Itinerary}'s circuit instead.
 */
final class TripOrder {

    private TripOrder() {
    }

    /**
     * The stops in the order they will actually be walked, with each woven-in extra beside
     * the patch it shares a trip with.
     *
     * <p>A catalogue run lists its stops in seat order, which already puts each extra beside
     * the patch it shares an arrival with: the Catherby white lily beside the Catherby herb
     * patch, not after a lap of the map. This keeps that so for a list in any other order.
     *
     * <p>Matched on the {@link Arrival}, so "same trip" means one visit. An extra with no
     * matching stop (a cactus at Al Kharid, the Ardougne Monastery bushes) stays where the
     * list puts it.
     *
     * <p>Order only. Seeds are settled against the catalogue's order before this runs.
     */
    static List<Integer> inTripOrder(List<StopPlan> plans) {
        // Decided up front because the match looks both ways: an extra written last can
        // belong early.
        boolean[] movesToItsPatch = new boolean[plans.size()];
        for (int i = 0; i < plans.size(); i++) {
            movesToItsPatch[i] = plans.get(i).getStop().isOptional() && sharesAnArrival(plans, arrivalOf(plans.get(i)));
        }

        List<Integer> ordered = new ArrayList<>(plans.size());
        boolean[] placed = new boolean[plans.size()];
        for (int i = 0; i < plans.size(); i++) {
            if (movesToItsPatch[i]) {
                continue;
            }
            ordered.add(i);
            if (plans.get(i).getStop().isOptional()) {
                continue;
            }
            Arrival arrival = arrivalOf(plans.get(i));
            for (int extra = 0; extra < plans.size(); extra++) {
                if (movesToItsPatch[extra] && !placed[extra] && arrivalOf(plans.get(extra)) == arrival) {
                    ordered.add(extra);
                    placed[extra] = true;
                }
            }
        }
        return ordered;
    }

    /** Whether the run proper already goes to this arrival, so an extra there rides along. */
    private static boolean sharesAnArrival(List<StopPlan> plans, Arrival arrival) {
        return plans.stream().anyMatch(plan -> !plan.getStop().isOptional() && arrivalOf(plan) == arrival);
    }

    /**
     * The trip as arrivals rather than patches: consecutive stops at the same place become
     * one visit.
     *
     * <p>Two stops naming one {@link Arrival} are one journey; different arrivals are two
     * journeys however close on the map. Catherby's herb, flower and allotment patches are
     * one row, while Ardougne's patches and its Monastery bushes are two: one cloak serves
     * both but lands in a different place for each.
     *
     * <p><b>Skipped stops merge too</b>, or a skip between two visits to one place would
     * split them and the list would reshape around patch state. The set-aside lines inside
     * the row say which patch each reason is about.
     *
     * @param order indices into {@code plans} in walking order, which must already keep each
     *     arrival's stops together
     */
    static List<List<Integer>> groupByArrival(List<Integer> order, List<StopPlan> plans) {
        List<List<Integer>> groups = new ArrayList<>();
        Arrival last = null;
        for (int index : order) {
            Arrival arrival = arrivalOf(plans.get(index));
            // A new arrival opens a group; a stop at the same one joins the last.
            if (groups.isEmpty() || arrival != last) {
                groups.add(new ArrayList<>());
            }
            groups.get(groups.size() - 1).add(index);
            last = arrival;
        }
        return groups;
    }

    /**
     * The place a stop is worked from. Two stops with the same arrival are one visit.
     *
     * <p>Stated by the catalogue, not derived from map regions, which mislead both ways.
     * Catherby's herb cluster and its fruit tree are two regions but one arrival. Ardougne's
     * farm and its Monastery bushes share one cloak teleport but are two arrivals, 150 tiles
     * apart.
     */
    private static Arrival arrivalOf(StopPlan plan) {
        return plan.getStop().getArrival();
    }
}

package com.larryfarming.farming.engine;

import com.larryfarming.engine.SeedBox;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.catalogue.CropData;
import com.larryfarming.farming.detection.CapabilityResolver;
import com.larryfarming.farming.model.Arrival;
import com.larryfarming.model.ItemStack;
import com.larryfarming.model.PlayerState;
import com.larryfarming.snapshot.FarmingCarryItem;
import java.util.*;
import java.util.stream.Collectors;
import lombok.*;
import net.runelite.api.gameval.ItemID;

/**
 * What to take out of the bank at each stop, for the stretch to the next one and no further.
 *
 * <p>The packing list answers "what does this trip need" once, before the player leaves, so it
 * fills the bag with things for stops far ahead. Every bank the trip passes is a chance to fetch
 * the next thing instead.
 *
 * <p><b>Every bank row on the way is a chance to fetch</b>, whether the bag simulation
 * prescribed it or only offered it. A trip whose bag never fills (most herb runs) has no prescribed bank after
 * the first, yet still walks past banks. An offered bank counts only while the panel draws
 * it, and only when it is on the way or a short detour.
 *
 * <p>Each stretch between bank rows is planned as its own little trip, and the answers are
 * walked in order against a running picture of the bag. An item wanted early and again later
 * is withdrawn once if it is a tool and twice if it is a seed, because a seed goes in the
 * ground.
 *
 * <p><b>Nothing is assumed to be deposited.</b> The picture only grows by withdrawals and
 * shrinks by plantings. These are recommendations: a player who skips a bank or deposits
 * something gets a fresh answer from the next snapshot, built from the bag they actually have.
 */
public final class WithdrawalPlanner {

    private WithdrawalPlanner() {
    }

    /**
     * What each bank row on the walkthrough should say to take out.
     *
     * <p>Three lookups because the rows are placed by three rules, each with its own key: the
     * starting row has none, a prescribed bank knows which leg it opens, and an offered bank
     * knows which arrival it sits at.
     */
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    public static final class Withdrawals {

        private static final Withdrawals NONE = new Withdrawals(List.of(), Map.of(), Map.of(), List.of(), List.of(), false);

        /** What to set off carrying, or empty where the packing list already says it. */
        @Getter
        private final List<FarmingCarryItem> beforeSettingOff;
        private final Map<Integer, List<FarmingCarryItem>> atLeg;
        private final Map<Integer, List<FarmingCarryItem>> offeredAt;

        /**
         * Everything the first stretch wants in the bag, carried or not, as packing-list
         * lines: the "now" half of the packing list. Boxed seeds count at the whole trip's
         * quantity, since they all come out up front. Empty when no later bank splits the
         * trip, where the whole packing list is the first stretch, and once underway.
         */
        @Getter
        private final List<FarmingCarryItem> firstStretch;

        /**
         * What to put back next time the player banks, for the starting row, which partway
         * round stands for that bank. Empty before setting off: nothing from this trip is in
         * the bag yet.
         */
        @Getter
        private final List<FarmingCarryItem> deposits;

        /** Whether the bag lacks room without those deposits. */
        @Getter
        private final boolean depositsUrgent;

        /** Nothing anywhere, for a caller that has not worked any of this out. */
        public static Withdrawals none() {
            return NONE;
        }

        /** What to take out at the bank that opens this leg. */
        public List<FarmingCarryItem> atLeg(int leg) {
            return atLeg.getOrDefault(leg, List.of());
        }

        /** What to take out at the bank offered at this arrival. */
        public List<FarmingCarryItem> offeredAt(int arrival) {
            return offeredAt.getOrDefault(arrival, List.of());
        }

    }

    /**
     * Every bank row's list, worked out in the order the player walks them.
     *
     * @param made  the arrivals the bag was planned over, each a list of positions in
     *              {@code plans} — the same list handed to {@code InventoryDemands.forTrip},
     *              since a leg's ends and an offer's index are positions in it
     * @param seeds every run's allocation, read only where {@code cropFor} cannot answer
     * @param underway whether the player is partway round. The starting chance then stands
     *     for the next bank they reach rather than the one they pack at, so it keeps its
     *     list even with no bank after it
     */
    static Withdrawals forBankStops(InventorySim.Plan bag, List<List<Integer>> made,
            List<StopPlan> plans, List<List<Crop>> cropFor, List<SeedPlan> seeds,
            PlayerState state, CapabilityResolver resolver, FarmingInputs inputs, boolean underway) {
        Trip trip = new Trip(made, plans, cropFor, seeds, state, resolver, inputs);
        List<Chance> chances = bankStopsIn(bag, !inputs.hidesOfferedBanks());
        // With only the starting bank, its list would repeat the packing list. With any later
        // bank, the starting row is drawn even if the later banks want nothing. Partway
        // round, the bag left the bank long ago, and the starting row alone says what the
        // rest of the trip is short of.
        if (chances.size() < 2 && !underway) {
            return Withdrawals.none();
        }
        // The bag as the player fills it, carried across the whole walk so a tool is asked
        // for once.
        Map<Integer, Integer> bagHolds = new HashMap<>();
        // Boxed seeds are recorded in bagHolds before the walk, so no stretch asks for them.
        List<FarmingCarryItem> boxedLines = new ArrayList<>();
        List<FarmingCarryItem> boxed = seedsForTheWholeTripUpFront(trip, bagHolds, boxedLines);
        // The empty buckets are one noted stack in one slot, decided on every bin the trip
        // reaches, so they come out whole at the first bank and no stretch asks for its own.
        List<FarmingCarryItem> buckets = CarryPlanner.emptyBuckets(CompostBins.over(plans, inputs, state), state);
        List<FarmingCarryItem> start = List.of();
        List<FarmingCarryItem> firstStretch = List.of();
        Map<Integer, List<FarmingCarryItem>> atLeg = new LinkedHashMap<>();
        Map<Integer, List<FarmingCarryItem>> offeredAt = new LinkedHashMap<>();
        for (int index = 0; index < chances.size(); index++) {
            Chance chance = chances.get(index);
            // Up to the next chance to fetch, which is not always the next leg: a leg with no
            // bank adds no chance, so its arrivals are packed for at the last bank before it.
            Chance next = index + 1 < chances.size() ? chances.get(index + 1) : null;
            int lastArrival = next != null ? next.firstArrival - 1 : made.size() - 1;
            // A bank met on the way in stands at the arrival it packs for first, so the
            // player reaches it carrying the way there from the stretch before.
            boolean starting = chance.leg < 0 && chance.arrival < 0;
            List<FarmingCarryItem> needs = new ArrayList<>(trip.needsOf(chance.firstArrival, lastArrival, chance.onTheWayIn));
            needs.removeIf(line -> CarryPlanner.formsOf(ItemID.BUCKET_EMPTY).contains(line.getItemId()));
            if (starting) {
                needs.addAll(buckets);
            }
            if (next != null && next.onTheWayIn) {
                needs = withTravelOn(needs, CarryPlanner.travelFor(StopPlan.pick(trip.plans, trip.made.get(next.firstArrival)), state, resolver));
            }
            List<FarmingCarryItem> take = shortfallOn(needs, bagHolds);
            // Underway the starting chance stands for the next bank, not the first stretch.
            if (starting && !underway) {
                firstStretch = withBoxedSeeds(boxedLines, needs);
            }
            if (starting && !boxed.isEmpty()) {
                // The trip's seeds lead the starting row, above the routine tools.
                List<FarmingCarryItem> both = new ArrayList<>(boxed);
                both.addAll(take);
                take = both;
            }
            if (take.isEmpty()) {
                continue;
            }
            if (starting) {
                start = take;
            } else if (chance.leg >= 0) {
                atLeg.put(chance.leg, take);
            } else {
                offeredAt.put(chance.arrival, take);
            }
        }
        List<FarmingCarryItem> deposits = List.of();
        boolean urgent = false;
        if (underway) {
            // Which bank comes next is not known, so the whole remaining trip counts as after
            // it: an item a stop before that bank uses stays too, the safe way.
            deposits = DepositPlanner.atNextBank(state, inputs.getPackedThisTrip(), trip.wholeTrip(), chances.size() < 2);
            urgent = !deposits.isEmpty() && DepositPlanner.bagWouldFill(state, start);
        }
        return new Withdrawals(start, atLeg, offeredAt, firstStretch, deposits, urgent);
    }

    /**
     * The first stretch's lines with each boxed seed at the whole trip's count, in place of
     * the stretch's own line for it.
     */
    private static List<FarmingCarryItem> withBoxedSeeds(List<FarmingCarryItem> boxedLines, List<FarmingCarryItem> needs) {
        Set<Integer> boxedIds = boxedLines.stream().map(FarmingCarryItem::getItemId).collect(Collectors.toSet());
        List<FarmingCarryItem> lines = new ArrayList<>(boxedLines);
        needs.stream().filter(line -> !boxedIds.contains(line.getItemId())).forEach(lines::add);
        return lines;
    }

    /**
     * The trip's seeds, taken in one go at the first bank, when a seed box makes that free.
     *
     * <p>Spreading withdrawals across banks saves bag slots. A seed box holds six types in
     * one slot the player already carries, so for seeds the spread saves nothing and costs a
     * bank visit per stop. Saplings do not go in the box; {@link CropData#boxesAsAseed} draws
     * that line, so tree runs keep the per-stretch schedule.
     *
     * <p>The box holds six kinds, counted over what the trip plants. A kind already in it
     * that the trip does not plant is emptied out at the bank, so it takes no room. Past that,
     * {@link #kindsToBox} picks which kinds ride in the box, and the rest keep the per-stretch
     * schedule. Box contents count only when {@link SeedBox#contentsCarried} says the tally
     * was read; being wrong costs one inventory slot, not a lost seed.
     *
     * <p>Availability stays as {@code CarryPlanner} judged it, including
     * {@code IN_SEED_BOX}, for the reason {@link #shortfallOn} gives.
     *
     * @param bagHolds <b>mutated</b>: each boxed seed is recorded at the whole trip's
     *     count, so no later stretch asks for it again
     * @param boxedLines <b>mutated</b>: each boxed kind's packing-list line at the whole
     *     trip's count, for the first stretch's half of the packing list
     * @return the lines to withdraw, empty when the box needs nothing taken out.
     *     {@code bagHolds} gets an entry for every boxed kind either way
     */
    private static List<FarmingCarryItem> seedsForTheWholeTripUpFront(Trip trip,
            Map<Integer, Integer> bagHolds, List<FarmingCarryItem> boxedLines) {
        PlayerState state = trip.state;
        if (!SeedBox.carried(state)) {
            return List.of();
        }
        List<FarmingCarryItem> boxable = new ArrayList<>();
        Set<Integer> types = new LinkedHashSet<>();
        for (FarmingCarryItem line : trip.wholeTrip()) {
            if (line.getKind() != FarmingCarryItem.Kind.SEED || !CropData.boxesAsAseed(line.getItemId())
                    // Skipped as in shortfallOn: nothing to fetch for either.
                    || cannotFetch(line)) {
                continue;
            }
            boxable.add(line);
            types.add(line.getItemId());
        }
        if (boxable.isEmpty()) {
            return List.of();
        }
        // Only the kinds the trip plants hold their room: the rest are emptied out at the
        // bank, which the seed box's line asks for.
        Set<Integer> held = new LinkedHashSet<>();
        if (SeedBox.contentsCarried(state)) {
            for (ItemStack stack : state.getSeedBox()) {
                if (types.contains(stack.getItemId())) {
                    held.add(stack.getItemId());
                }
            }
        }
        Set<Integer> boxed = kindsToBox(types, held, trip);

        List<FarmingCarryItem> withdraw = new ArrayList<>();
        for (FarmingCarryItem line : boxable) {
            if (!boxed.contains(line.getItemId())) {
                // Left to the per-stretch schedule, like any loose seed.
                continue;
            }
            boxedLines.add(line);
            int wants = line.getQuantity();
            int has = line.getCarriedCount();
            if (has < wants) {
                withdraw.add(line.withQuantity(wants - has));
            }
            // Nothing is deposited, so the bag holds the larger of the two.
            bagHolds.put(line.getItemId(), Math.max(has, wants));
        }
        return withdraw;
    }

    /**
     * Which of the trip's seed kinds ride in the box: all of them while they fit, and past
     * its room, a choice.
     *
     * <p>Kinds already in the box stay there. The rest of its room goes to the kinds the trip
     * plants latest: a loose kind for an early patch comes out at the first bank and is in
     * the ground soon after, while a boxed late kind spares every later bank a withdrawal.
     * Ties keep the trip's own order. The last planting stands in for what a loose kind
     * costs, which is the number of later banks that fetch it; two kinds with no bank
     * between their last patches cost the same, and the earlier still loses.
     *
     * @param types the trip's boxable kinds, in the order the packing list names them
     * @param held  the trip's kinds the box was read to hold already
     */
    private static Set<Integer> kindsToBox(Set<Integer> types, Set<Integer> held, Trip trip) {
        Set<Integer> boxed = new LinkedHashSet<>();
        List<Integer> loose = new ArrayList<>();
        for (int type : types) {
            if (held.contains(type)) {
                boxed.add(type);
            } else {
                loose.add(type);
            }
        }
        int room = SeedBox.KINDS_HELD - held.size();
        if (loose.size() <= room) {
            boxed.addAll(loose);
            return boxed;
        }
        if (room <= 0) {
            return boxed;
        }
        // Read per arrival only on this path: a trip within the box's room never needs it.
        Map<Integer, Integer> lastPlanted = new HashMap<>();
        for (int arrival = 0; arrival < trip.made.size(); arrival++) {
            for (FarmingCarryItem line : trip.needsOf(arrival, arrival, false)) {
                if (line.getKind() == FarmingCarryItem.Kind.SEED) {
                    lastPlanted.put(line.getItemId(), arrival);
                }
            }
        }
        // Stable, so equal arrivals keep the trip's order.
        loose.sort((a, b) -> Integer.compare(lastPlanted.getOrDefault(b, -1), lastPlanted.getOrDefault(a, -1)));
        boxed.addAll(loose.subList(0, room));
        return boxed;
    }

    /**
     * Somewhere the player can open a bank, and the first arrival it packs for. Prescribed
     * and offered banks share this one type so the walk sees them in one sequence.
     */
    @AllArgsConstructor
    private static final class Chance {
        private final int firstArrival;
        private final int leg;
        private final int arrival;
        /**
         * Whether the player opens this bank between the first arrival's landing and its
         * patches, so its own travel is already spent.
         */
        private final boolean onTheWayIn;
    }

    /**
     * Every bank row the walkthrough draws that is worth fetching at, in the order it draws
     * them: the prescribed banks, and the offered ones unless a long detour.
     *
     * <p>A prescribed bank, and an offered bank on the way in, are spliced <em>before</em>
     * their arrival and pack for it. An offered bank graded only by its arrival is spliced
     * <em>after</em> it and packs from the next. So that offer at arrival five and a
     * prescribed stop opening at arrival six both begin packing at six, offer first. The offer
     * then covers an empty stretch and says nothing, and the prescribed bank carries the list.
     *
     * @param offered whether the walkthrough draws the banks the route only passes. A row
     *     the player never sees is no chance to fetch, so its stretch joins the one before.
     *     A long-detour offer is skipped either way
     */
    private static List<Chance> bankStopsIn(InventorySim.Plan bag, boolean offered) {
        List<Chance> chances = new ArrayList<>();
        for (int index = 0; index < bag.getLegs().size(); index++) {
            InventorySim.Leg leg = bag.getLegs().get(index);
            if (index == 0) {
                // The trip starts at a bank whatever else it does — the player packs there.
                chances.add(new Chance(0, -1, -1, false));
            } else if (leg.getBankAt() != null) {
                chances.add(new Chance(leg.getFrom(), index, -1, true));
            }
            if (!offered) {
                continue;
            }
            for (InventorySim.Opportunity passed : leg.getPassableBanks()) {
                // A long detour is no place to send the player for something they could
                // have packed: its items come out of the bank before it instead. The row
                // still stands as an offer.
                if (passed.getCost() == Arrival.BankProximity.FAR) {
                    continue;
                }
                chances.add(passed.isOnTheWayIn() ? new Chance(passed.getIndex(), -1, passed.getIndex(), true)
                        : new Chance(passed.getIndex() + 1, -1, passed.getIndex(), false));
            }
        }
        // By where each starts packing. On a tie the bank after the arrival before goes
        // ahead of the bank on the way in, as the rows are drawn. The sort is stable, so
        // everything else keeps the sim's walk order.
        Collections.sort(chances, (a, b) -> a.firstArrival != b.firstArrival ? Integer.compare(a.firstArrival, b.firstArrival)
                : Boolean.compare(a.onTheWayIn, b.onTheWayIn));
        return chances;
    }

    /** The trip being split into stretches, which every stretch's packing list reads. */
    @AllArgsConstructor
    private static final class Trip {
        private final List<List<Integer>> made;
        private final List<StopPlan> plans;
        private final List<List<Crop>> cropFor;
        private final List<SeedPlan> seeds;
        private final PlayerState state;
        private final CapabilityResolver resolver;
        private final FarmingInputs inputs;

        /**
         * The packing list for one stretch alone, built by handing the planner only its
         * stops.
         *
         * <p>Slicing works because the planner derives its seed tallies from the stops it is
         * given ({@code SeedPlan.goingInTheGround}), and reads the run-wide allocation only
         * where nothing says what is going in the ground. Travel lines dedupe per arrival
         * within the slice.
         *
         * @param arrived whether the player is already standing at the first arrival, so its
         *     travel was packed for by the stretch before
         */
        List<FarmingCarryItem> needsOf(int firstArrival, int lastArrival, boolean arrived) {
            List<StopPlan> stretchPlans = new ArrayList<>();
            List<List<Crop>> stretchCrops = new ArrayList<>();
            for (int arrival = firstArrival; arrival <= lastArrival; arrival++) {
                for (int index : made.get(arrival)) {
                    stretchPlans.add(arrived && arrival == firstArrival ? CarryPlanner.withoutTravel(plans.get(index)) : plans.get(index));
                    // Unguarded, like InventoryDemands.forTrip: plans and cropFor are built
                    // aligned. An empty fallback would mean "nothing planted here" and drop
                    // the axe.
                    stretchCrops.add(cropFor.get(index));
                }
            }
            if (stretchPlans.isEmpty()) {
                return List.of();
            }
            return CarryPlanner.plan(stretchPlans, seeds, stretchCrops, state, resolver, inputs);
        }

        /** The whole trip's packing list. */
        List<FarmingCarryItem> wholeTrip() {
            return needsOf(0, made.size() - 1, false);
        }
    }

    /**
     * A stretch's needs with the way to the next bank added, one line per item.
     *
     * <p>Merged rather than appended, because {@link #shortfallOn} walks lines in order: a
     * tablet used in the stretch and again to reach the bank would come out as two
     * withdrawals of one item. Stock counts add up; a tool stays one line.
     */
    private static List<FarmingCarryItem> withTravelOn(List<FarmingCarryItem> needs, List<FarmingCarryItem> travel) {
        if (travel.isEmpty()) {
            return needs;
        }
        Map<Integer, FarmingCarryItem> byItem = new LinkedHashMap<>();
        for (FarmingCarryItem line : needs) {
            byItem.put(line.getItemId(), line);
        }
        for (FarmingCarryItem line : travel) {
            FarmingCarryItem already = byItem.get(line.getItemId());
            if (already == null || already.getQuantity() == 0) {
                // A counted line outranks a named one, so its count is not lost.
                if (already == null || line.getQuantity() > 0) {
                    byItem.put(line.getItemId(), line);
                }
            } else {
                // A note explains one half's count, so the sum keeps it only if both agree:
                // a gardener's fee plus a fare is no longer "to have a tree cleared".
                byItem.put(line.getItemId(), already.withQuantity(already.getQuantity() + line.getQuantity())
                        .withNote(Objects.equals(already.getNote(), line.getNote()) ? already.getNote() : ""));
            }
        }
        return new ArrayList<>(byItem.values());
    }

    /**
     * What this stretch is short of, given what the bag already holds — and what it holds
     * after.
     *
     * <p>The {@code quantity} field splits two rules. A line with a count is stock: this
     * stretch spends it, so the next stretch fetches again. A line without one is a tool: it
     * stays in the bag, so it is asked for once, at the last bank before it is needed.
     *
     * <p>Lines the player cannot act on at a bank are skipped: the leprechaun already holds
     * an {@code AT_LEPRECHAUN} line, and a {@code MISSING} one cannot be withdrawn. The
     * trip's packing list still shows both. {@code IN_SEED_BOX} counts as a shortfall,
     * because checking the box at the bank settles whether to withdraw.
     *
     * <p><b>Not modelled</b>, since each would need the bank's stock simulated alongside the
     * bag's:
     * <ul>
     * <li>The bank is bottomless: nothing debits owned stock as withdrawals come out. The
     * rotation deals seeds from stock, so only fixed crops can over-ask.</li>
     * <li>A seed nobody owns enough of is dropped by {@code CarryPlanner}, so its planting is
     * never debited from the bag.</li>
     * <li>Ultracompost has no quantity, so it is asked for once, as for the bottomless
     * bucket.</li>
     * <li>Past the seed box's room, the bag simulation charges each leg's kinds beyond six,
     * not the loose kinds {@link #kindsToBox} leaves out. An early leg can carry a loose
     * kind the simulation charges nothing for, which the harvest headroom absorbs.</li>
     * </ul>
     *
     * @param bagHolds what the player is carrying, per item id, mutated as the stretch is
     *                 walked. An item first met here is seeded from what is genuinely in the
     *                 bag now
     */
    static List<FarmingCarryItem> shortfallOn(List<FarmingCarryItem> needs, Map<Integer, Integer> bagHolds) {
        List<FarmingCarryItem> withdraw = new ArrayList<>();
        for (FarmingCarryItem line : needs) {
            // IN_SEED_BOX stays and counts as a shortfall; the panel words it as a check.
            if (cannotFetch(line)) {
                continue;
            }
            boolean stock = line.getQuantity() > 0;
            int wants = stock ? line.getQuantity() : 1;
            int has = bagHolds.getOrDefault(line.getItemId(), line.getCarriedCount());
            if (has < wants) {
                // Ask for the shortfall, not the whole want.
                withdraw.add(line.withQuantity(stock ? wants - has : 0));
                has = wants;
            }
            bagHolds.put(line.getItemId(), stock ? has - wants : has);
        }
        return withdraw;
    }

    /** Whether a bank cannot supply this line: the leprechaun holds it, or nobody owns it. */
    private static boolean cannotFetch(FarmingCarryItem line) {
        return line.getAvailability() == FarmingCarryItem.Availability.AT_LEPRECHAUN
                || line.getAvailability() == FarmingCarryItem.Availability.MISSING;
    }
}

package com.larryfarming.farming.model;

import java.util.ArrayList;
import java.util.List;
import lombok.*;

/**
 * A way onto a travel network that rungs ask for as an "or" of ways in, such as standing at
 * a fairy ring by house, quest cape or Salve graveyard teleport. Each way in carries its
 * walk from its landing to the network.
 *
 * <p>A rung asking for an approach leaves the approach's walk out of its own figure, because
 * which way in a player takes depends on the account: the first they certainly have, else
 * the first they might. The planner adds that leg's walk and cost per account, so a ring
 * rung can rank above a teleport for one player and below it for another.
 */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class Approach {

    /** The "or" the rungs write, one part per leg in the legs' order. */
    Requirement way;

    List<Leg> legs;

    /** One way in, with the tiles walked from its landing to the network. */
    @Value
    public static class Leg {
        Requirement requires;
        int walk;
        TravelOption.Cost cost;
    }

    /** One way in. */
    public static Leg leg(Requirement requires, int walk, TravelOption.Cost cost) {
        if (walk < 0) {
            throw new IllegalArgumentException("a walk cannot be negative");
        }
        if (cost == null) {
            throw new IllegalArgumentException("a leg has to say what it spends");
        }
        return new Leg(requires, walk, cost);
    }

    /** The approach whose ways in are these legs, tried in this order. */
    public static Approach of(Leg... legs) {
        List<Requirement> parts = new ArrayList<>(legs.length);
        for (Leg leg : legs) {
            parts.add(leg.getRequires());
        }
        return new Approach(Requirement.any(parts.toArray(new Requirement[0])), List.of(legs));
    }

    /** The leg whose requirement is this part of {@link #getWay()}, or null for none. */
    public Leg legFor(Requirement part) {
        for (Leg leg : legs) {
            if (leg.getRequires().equals(part)) {
                return leg;
            }
        }
        return null;
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.data.Tables;
import lombok.Getter;

/**
 * One place on the trip: somewhere the player travels to, and every patch they work
 * before travelling again.
 *
 * <p>A trip is a sequence of arrivals, and everything the player does at one costs a single
 * journey however many patches, runs or crop families it spans. The catalogue decides the
 * grouping patch by patch; distance does not. Falador's farm and park tree are two arrivals,
 * because eighty-five tiles through the city is a journey.
 *
 * <p><b>Not a {@link Destination}.</b> A destination is where a teleport puts you; an
 * arrival is a stop on the itinerary. Falador's park tree is reached by a ring of wealth, a
 * respawn teleport or the Falador spell, and all three are the same stop.
 *
 * <p><b>Not a map region either.</b> Catherby's herb cluster and fruit tree are two regions
 * and one arrival: no teleport lands nearer the fruit tree than Catherby town. Ardougne's
 * farm and Monastery bushes share one cloak but sit 150 tiles apart, so they are two
 * arrivals.
 *
 * <p>Each arrival's name and bank grade come from the arrivals table.
 */
@Getter
public enum Arrival {

    // --- Kourend --------------------------------------------------------------
    /** Contract, hespori and every guild patch: one walled garden. */
    FARMING_GUILD,
    HOSIDIUS,

    // --- Varlamore ------------------------------------------------------------
    /**
     * The patches are a run north of the Hunter Guild. The Civitas illa Fortis teleport
     * banks on the way, fifteen tiles of detour; the Hunter cape detours thirty-six tiles
     * to the guild's chest, and a quetzal to the guild eighty-seven. Graded SHORT_WALK, on
     * the teleport's fifteen.
     */
    ORTUS_FARM,
    LOCUS_OASIS,
    KASTORI,
    NEMUS_RETREAT,
    /** The belladonna patch at the east end of town. Graded NONE. */
    AUBURNVALE,

    // --- Tirannwn -------------------------------------------------------------
    /**
     * The bank is five tiles from the patch in a straight line and thirty-one walked, because
     * a building stands between them. It is not on the walk in either: the crystal lands
     * seventeen tiles from the patch and twenty-seven from the bank. Graded FAR.
     */
    LLETYA,

    // --- Kandarin and the gnome lands ----------------------------------------
    /** Tree and fruit tree both: every arrival here falls between the two patches. */
    GNOME_STRONGHOLD,
    TREE_GNOME_VILLAGE,
    /**
     * Seventy tiles to the nearest bank: ninety-eight tiles of detour by fairy ring, a
     * hundred and forty-two by the cloak.
     */
    ARDOUGNE_MONASTERY,
    ARDOUGNE_FARM,
    /** Herb cluster, two allotments, flowers, and the fruit tree east of them. */
    CATHERBY,

    // --- Karamja --------------------------------------------------------------
    BRIMHAVEN,
    TAI_BWO_WANNAI,

    // --- Asgarnia -------------------------------------------------------------
    TAVERLEY,
    /**
     * Thirty-seven tiles to Falador east bank walked, not the sixteen of the straight line:
     * the park is fenced and the bank sits behind the south-east wall. The rungs differ
     * widely: a skills necklace passes the bank on the way out of the Mining Guild, while
     * the ring of wealth makes it a fifty-tile round trip.
     */
    FALADOR_PARK,
    /** Eighty-five tiles from the park through the city, and never the same stop. */
    FALADOR_FARM,

    // --- Misthalin ------------------------------------------------------------
    /**
     * The belladonna patch inside the manor's fence. The nearest bank, Draynor Village's, is
     * about 110 tiles from the teleport landing, past the ninety that still grades, so it is
     * graded NONE.
     */
    DRAYNOR_MANOR,
    LUMBRIDGE,
    VARROCK_PARK,
    AL_KHARID,

    // --- Morytania ------------------------------------------------------------
    /**
     * The bittercap patch west of Canifis, which the default route leaves out and a player can
     * switch on. Five tiles from fairy ring CKS and about twenty-five from the Salve
     * graveyard teleport landing, so it is passed on the way into the region.
     *
     * <p>Graded FAR from the Canifis bank, so the leg claims nothing about the route.
     */
    MORT_MYRE,
    CANIFIS,
    HARMONY_ISLAND,

    // --- Fossil Island --------------------------------------------------------
    /**
     * Three hardwood patches inside an eighteen-by-nine box: one journey, one stop. The
     * Museum Camp bank chest is ten tiles off the route in from the barge, which grades
     * SHORT_WALK. The chest is a one-off Construction 21 repair and no varbit reports it, so it
     * is assumed built.
     */
    FOSSIL_ISLAND_HARDWOOD,
    /** Underwater, and reached from the surface separately. Never the hardwood stop. */
    FOSSIL_ISLAND_SEAWEED,

    // --- The far north --------------------------------------------------------
    WEISS,
    TROLL_STRONGHOLD,

    // --- The Great Conch ------------------------------------------------------
    GREAT_CONCH;

    static {
        Rows.TABLE.requireAll(values());
    }

    /**
     * How much a bank costs once the player is standing here.
     *
     * <p><b>Stated per arrival, which is coarser than the truth.</b> The real cost depends
     * on the leg, landing to patch: Ortus Farm banks fifteen tiles off the Civitas illa
     * Fortis teleport and over a hundred out on fairy ring AJP, and at the Tree Gnome
     * Stronghold the spirit tree and the slayer ring favour opposite patches. This records
     * the best a player at the arrival can do. Deciding where a trip breaks must ask the
     * leg, not read this as final.
     */
    public enum BankProximity {
        /** On the walk in, or close enough that stopping costs nothing measurable. */
        AT_ARRIVAL,
        /** A short detour — worth it to avoid a dedicated trip, not worth it otherwise. */
        SHORT_WALK,
        /** A real detour. Bank here only when there is nowhere better in reach. */
        FAR,
        /**
         * Nowhere a trip can break: either there is no bank, or reaching one costs more
         * than the trip it would save.
         */
        NONE;

        /**
         * What changing floor costs, in tiles, on top of the walk.
         *
         * <p>Unmeasured: walks count the ground floor only, so a bank up a staircase reads
         * as a ground-level walk. Lumbridge measures five tiles of detour and is two
         * flights and about twelve tiles each way in game. Twenty puts Lumbridge at the far
         * end of {@link #SHORT_WALK}.
         */
        public static final int FLOOR_CHANGE_TILES = 20;

        /**
         * Whether a bank at this grade is close enough that a trip passing here walks by it.
         *
         * <p>For a bank with no figure, where the grade is all there is. {@link #FAR} spans
         * twenty-five to ninety tiles, so it could mean either end. A measured route is
         * judged on its tiles instead; see {@code InventorySim.offeredHere}.
         */
        public boolean onTheWay() {
            return this == AT_ARRIVAL || this == SHORT_WALK;
        }

        /**
         * The grade a measured leg earns.
         *
         * <p>The lower cutoffs read as time at about 3.3 tiles a second: five tiles is
         * beneath noticing, twenty-five is eight seconds and worth it against a dedicated
         * trip. Both sit in gaps in the measured detours.
         *
         * <p>The top cutoff of ninety is a player's judgement, not a reading of the data:
         * Al Kharid's bank, 105 tiles from the cactus patch, is not a detour anyone wants
         * offered.
         *
         * @param tiles    extra tiles walked, as {@code TravelOption.getBankDetour()} gives
         * @param upstairs whether the bank is on another floor
         */
        public static BankProximity of(int tiles, boolean upstairs) {
            int cost = costInTiles(tiles, upstairs);
            if (cost <= 5) {
                return AT_ARRIVAL;
            }
            if (cost <= 25) {
                return SHORT_WALK;
            }
            return cost <= 90 ? FAR : NONE;
        }

        /** A bank detour's walked tiles with {@link #FLOOR_CHANGE_TILES} added when it changes floor. */
        public static int costInTiles(int tiles, boolean upstairs) {
            return upstairs ? tiles + FLOOR_CHANGE_TILES : tiles;
        }
    }

    /**
     * Player-facing, written to sit mid-sentence: "travel to the Farming Guild". A caller
     * wanting a heading capitalises and strips the article.
     */
    private final String displayName;
    private final BankProximity bank;

    Arrival() {
        Tables.Row row = Rows.TABLE.of(name());
        this.displayName = row.text(1);
        this.bank = row.constant(BankProximity.class, 2);
    }

    /**
     * The arrivals table, held apart so the constructors can read it; see
     * {@link Tables#byName}.
     */
    private static final class Rows {
        static final Tables.Named TABLE = Tables.byName("/com/larryfarming/arrivals.tsv", 3);
    }
}

package com.larryfarming.farming.model;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The bank a {@link TravelOption}'s detour figure was walked to.
 *
 * <p>Lets a row name the bank rather than the arrival: two Ortus Farm rungs bank in Civitas
 * illa Fortis and four at the Hunter Guild, none at Ortus Farm.
 *
 * <p><b>On the rung, beside the tiles, never on the {@link Arrival}</b>, because one arrival's
 * rungs can land near different banks: the Tree Gnome Stronghold's royal seed pod puts the
 * player at the north bank while every other rung there walks to the south.
 *
 * <p>Each bank was identified by walking the route to it, by being the town's
 * only bank, or (Civitas illa Fortis) by checking in game.
 */
@Getter
@RequiredArgsConstructor
public enum Bank {

    /**
     * Falador east, for the park and the farm alike. The walk to this bank reproduces the
     * park and farm detour figures to within a few tiles.
     */
    FALADOR_EAST("Falador east"),

    /** Varrock east, which reproduces the detour figures; the west bank is out by thirty tiles. */
    VARROCK_EAST("Varrock east"),

    /** Canifis, the only bank in the town. */
    CANIFIS("Canifis"),

    /** Al Kharid, the only bank in the city. */
    AL_KHARID("Al Kharid"),

    /** Ardougne south, for the cloak and fairy ring Monastery rungs; the north bank is further. */
    ARDOUGNE_SOUTH("Ardougne south"),

    /**
     * Ardougne north, for the farm. The cloak lands on the farm patch, so the detour is an
     * out-and-back: 87 tiles to this bank against 131 to the south bank.
     */
    ARDOUGNE_NORTH("Ardougne north"),

    /** Hosidius, the only bank in the town. */
    HOSIDIUS("Hosidius"),

    /**
     * The Farming Guild's bank chest, in the middle tier. Covers every rung to the guild; the
     * north-wing bank is only a few seconds away.
     */
    FARMING_GUILD("Farming Guild bank chest"),

    /** Catherby, the only bank in the town, and the one both the herb and fruit figures cross. */
    CATHERBY("Catherby"),

    /**
     * Lumbridge Castle, on the second floor.
     *
     * <p>Its rungs use {@code banksUpstairs}: the walked tiles count the ground floor only,
     * so they miss two flights of stairs.
     */
    LUMBRIDGE_CASTLE("Lumbridge Castle"),

    /** Lletya, reached from the teleport crystal's landing. */
    LLETYA("Lletya"),

    /** The Museum Camp chest; named a chest because it is one. */
    MUSEUM_CAMP("Museum Camp bank chest"),

    /** Gnome Stronghold south, dead on the route from the spirit tree to the tree patch. */
    GNOME_STRONGHOLD_SOUTH("Gnome Stronghold south"),

    /**
     * Gnome Stronghold north, on the second level of the Grand Tree. Reached only by the royal
     * seed pod, which lands inside the Grand Tree a level below it.
     */
    GNOME_STRONGHOLD_NORTH("Gnome Stronghold north"),

    /**
     * Civitas illa Fortis west, for the two Ortus Farm rungs that land away from the Hunter
     * Guild: the Civitas teleport and fairy ring AJP. Identified in game.
     */
    CIVITAS_ILLA_FORTIS_WEST("Civitas illa Fortis west"),

    /**
     * The Hunter Guild's bank chest, for the Ortus Farm rungs that land at the guild. Anyone
     * can use the chest; only the banker beside it asks for guild membership.
     */
    HUNTER_GUILD("Hunter Guild bank chest");

    /**
     * Player-facing: a place to follow "Bank at" ("Falador east"), or a bank chest that
     * names itself ("Museum Camp bank chest"). Qualified only where a town has more than
     * one bank.
     */
    private final String displayName;

    /** "Bank at Falador east", or the chest's own name, which already says "bank". */
    public String getRowTitle() {
        return displayName.endsWith("bank chest") ? displayName : "Bank at " + displayName;
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.data.Tables;
import java.util.Collection;
import lombok.Getter;

/**
 * Something a player can or cannot do, referenced by the ordered travel chains in
 * {@link RunStop}. Every route is a ranked list of alternatives
 * ("Ardougne cloak 4, else cloak 3, else the Fishing Guild teleport"). Downgrading walks
 * such a list and stops at the first capability the player has.
 *
 * <p>This enum carries no item IDs, varbit IDs or skill thresholds. It names what a
 * route requires, and the detection layer answers it against game state, so improving
 * detection never forces an edit to the catalogue. {@link Detectability} is the
 * exception, because whether a capability is observable at all is a property of the thing.
 * Each constant's attributes come from the capabilities table.
 *
 * <p>Some capabilities are rationed per day: an Explorer's ring 2 teleports to the Falador
 * cabbage patch three times a day, an Ardougne cloak 2 three times and a cloak 3 five, and
 * the higher tiers without limit. {@link #getDailyUses()} holds each allowance. Which
 * allowances the game reports lives with the detection code.
 *
 * <p>Charge counts on rechargeable items are not modelled: item IDs distinguish "holds a
 * charged one" but never "has two left", and no daily reset gives a count to start from.
 */
@Getter
public enum Capability {

    // --- Achievement diary reward items -------------------------------------
    // Each diary tier replaces the cloak or ring the player holds, so asking for a low tier
    // accepts any higher one (see isSatisfiedBy).
    // Answered from the diary flag, not the item: the item may sit in a bank the plugin has not
    // seen, while the diary flag is readable from login.
    // Ardougne cloak 1 matters only for its Monastery teleport, which lands beside a fairy
    // ring.
    ARDOUGNE_CLOAK_1,
    ARDOUGNE_CLOAK_2,
    ARDOUGNE_CLOAK_3,
    ARDOUGNE_CLOAK_4,
    EXPLORERS_RING_2,
    EXPLORERS_RING_3,
    EXPLORERS_RING_4,
    DIARY_CAPE,
    /**
     * The medium Varrock diary. Its reward adds the Grand Exchange as a second landing for
     * the Varrock Teleport spell and tablet, which the player picks per cast. Read from the
     * diary flag, since no item carries it.
     */
    VARROCK_DIARY_MEDIUM,

    // --- Skill capes --------------------------------------------------------
    FARMING_CAPE,
    CONSTRUCTION_CAPE,
    HUNTER_CAPE,
    FISHING_CAPE,
    QUEST_CAPE,

    // --- Jewellery and charged teleport items -------------------------------
    SKILLS_NECKLACE,
    GAMES_NECKLACE,
    COMBAT_BRACELET,
    RING_OF_DUELING,
    RING_OF_WEALTH,
    AMULET_OF_GLORY,
    RING_OF_THE_ELEMENTS,
    SLAYER_RING,
    ROYAL_SEED_POD,
    XERICS_TALISMAN,
    /**
     * Kharedst's memoirs with its Lunch by the Lancalliums page added and a charge left.
     * The page and the charges are the player's varbits, not the book's.
     */
    KHAREDSTS_MEMOIRS,
    /** The memoirs' upgrade from A Kingdom Divided, with the same page and charges. */
    BOOK_OF_THE_DEAD,
    DIGSITE_PENDANT,
    TELEPORT_CRYSTAL,
    CHRONICLE,
    /**
     * Ghosts Ahoy's reward, which teleports to the Ectofuntus and refills there on landing,
     * so it never runs out. The empty one is not a route: it must be refilled at the
     * Ectofuntus first.
     */
    ECTOPHIAL,

    // --- Consumable teleports ------------------------------------------------
    ICY_BASALT,
    STONY_BASALT,
    MOKHAIOTL_WAYSTONE,

    /**
     * A redirected house tab: a teleport-to-house tablet with a scroll of
     * redirection used on it, open to a player housed anywhere. It lands where
     * {@link #POH_IN_BRIMHAVEN} does, with different unlocks and costs.
     */
    BRIMHAVEN_TABLET,

    // --- Spells --------------------------------------------------------------
    // Teleports to a fixed place are not capabilities: a tablet and a spell to the same
    // spot are one requirement, expressed as a Destination. Respawn Teleport stays here
    // because it lands at a setting rather than a place.
    RESPAWN_TELEPORT,
    FERTILE_SOIL,

    /**
     * Where the player respawns, which decides where Respawn Teleport lands. The default
     * route uses Camelot for the Catherby patches and Falador for the tree patch.
     *
     * <p>The game keeps one flag per town, with all zero meaning Lumbridge. The client names
     * the flags by town ({@code CAMELOT_SPAWN}, {@code FALADOR_SPAWN}), so search for
     * {@code _SPAWN}, not {@code RESPAWN}.
     */
    RESPAWN_AVAILABLE_CAMELOT,
    RESPAWN_AVAILABLE_FALADOR,

    // --- Transport networks --------------------------------------------------
    // Fairy-ring codes and glider stations are instruction text, not capabilities: the
    // player has or lacks access to the network.
    FAIRY_RINGS,
    /**
     * Using a fairy ring without a staff. Fairytale I and the Fairy Godfather's permission
     * in Fairytale II open the rings, but until the elite Lumbridge &amp; Draynor diary is
     * finished every trip needs a dramen or lunar staff wielded.
     */
    STAFFLESS_FAIRY_RINGS,
    /**
     * The three Varlamore ring codes, which the rest of the network does not open. Each
     * requires having travelled to Civitas illa Fortis via Regulus Cento after Children of
     * the Sun.
     */
    VARLAMORE_FAIRY_RINGS,
    /**
     * Reaching Varlamore at all. Every route in (charter ships, fairy rings, spells,
     * quetzals) works only once Children of the Sun is done and Regulus Cento has carried
     * the player over once.
     *
     * <p>The bottom of every Varlamore chain: without it the run drops the patch rather
     * than inventing a route.
     */
    VARLAMORE_ACCESS,
    GNOME_GLIDER,
    /**
     * One balloon station. Flights are gated per station: Enlightened Journey opens only
     * Entrana-to-Taverley, and each other station opens by flying to it from Entrana once.
     * Opened stations then connect to each other, so a rung names both ends.
     *
     * <p>Each station's varbit is set only after its Firemaking level is met (20 Taverley,
     * 40 Varrock, 50 Castle Wars, 60 Grand Tree, all boostable) and the opening trip made,
     * so the flag alone is the test.
     *
     * <p>Every flight burns a log, which is not modelled. Balloon rungs rank below free ones
     * for that reason.
     *
     * <p>Only stations the runs use are named. Entrana and the Crafting Guild have varbits
     * too ({@code ZEP_MULTI_BASKET}, {@code ZEP_MULTI_CRAFT}).
     */
    BALLOON_STATION_TAVERLEY,
    BALLOON_STATION_CASTLE_WARS,
    BALLOON_STATION_GRAND_TREE,
    BALLOON_STATION_VARROCK,
    LOVAKENGJ_MINECART,
    /**
     * The charter ships, which sail for anyone who pays. The fare is halved by Cabin Fever
     * or a ring of charos(a).
     */
    CHARTER_SHIP,
    QUETZAL_WHISTLE,
    /**
     * Renu, the quetzal Twilight's Promise gifts, ridden from a landing site.
     *
     * <p>Not interchangeable with {@link #QUETZAL_WHISTLE}: the whistle calls a quetzal from
     * anywhere, but Renu has to be walked to. Chains carry the leg that reaches a site.
     */
    RENU,
    /**
     * The Kastori landing site, which the player builds (ten quetzal feed, three limestone
     * bricks, four soft clay, no Construction level). Without it a quetzal flies to Tal
     * Teklan instead of the patch.
     */
    QUETZAL_SITE_KASTORI,
    MOUNTAIN_GUIDE,
    CANAL_BARGE,
    /**
     * Being allowed onto Harmony Island at all, which starting The Great Brain Robbery
     * opens: Brother Tranquility ferries anyone who has begun it. The Harmony stop's access
     * gate. The teleports, house portals included, also need the quest finished, which
     * each one checks for itself.
     */
    HARMONY_ISLAND_ACCESS,
    FOSSIL_ISLAND_ZIPLINE,
    /** The Hole under the hill from the Museum Camp to the hardwood patches. */
    FOSSIL_ISLAND_HOLE,
    /** The climbing rocks on Taverley's east wall, crossed east to west only. */
    TAVERLEY_CLIMBING_ROCKS,

    // --- Sailing travel ------------------------------------------------------
    // Holding the item is readable, and so is statue activation for the two pendant
    // destinations the runs use. Each statue is its own capability because a chain asks
    // for one destination on the pendant.
    //
    // The pendant's other four destinations and the Sailors' amulet's docks have no known
    // flag, so they count as available. Unlocking one is a one-off trip, and the
    // instruction tells the player to activate it.
    PENDANT_OF_ATES,
    ATES_STATUE_KASTORI,
    ATES_STATUE_NEMUS_RETREAT,
    SAILORS_AMULET,

    // --- Player-owned house --------------------------------------------------
    // The house's town is a varbit (2187), readable anywhere. The portals, the spirit tree
    // and the fairy ring are SEEN: their objects load only inside the house, so they are
    // read on a visit to the player's own house and absent until one. The Nexus's attuned
    // destinations are varbits, but proven absent only from a full read on its teleport
    // menu, so they are SEEN too.
    //
    // A "redirected" tab's landing spot belongs to the tab, not the house: see
    // BRIMHAVEN_TABLET.
    POH_IN_HOSIDIUS,
    POH_IN_BRIMHAVEN,
    POH_IN_TAVERLEY,
    POH_PORTAL_WEISS,
    /**
     * The Troll Stronghold Portal, directed with stony basalt's salts, which lands where the
     * basalt does: the stronghold entrance, or its roof after the hard Fremennik diary with
     * 73 Agility. Not the Trollheim Portal, which lands on the mountain far from the patch.
     */
    POH_PORTAL_TROLL_STRONGHOLD,
    POH_PORTAL_KOUREND,
    /** Lands where Fenkenstrain's Castle Teleport does, west of the Morytania herb patch. */
    POH_PORTAL_FENKENSTRAIN,
    /** Lands where Harmony Island Teleport does, 27 walked tiles north of the herb patch. */
    POH_PORTAL_HARMONY,
    // A Portal Nexus destination is a separate build from a portal room portal, and
    // the chains rank them as separate rungs, so they cannot share a constant.
    POH_NEXUS_WEISS,
    POH_NEXUS_HARMONY,
    /** The Nexus's stony basalt slot, which lands where the Troll Stronghold Portal does. */
    POH_NEXUS_TROLL_STRONGHOLD,
    POH_SPIRIT_TREE,
    POH_FAIRY_RING,
    /** Teleports beside the Wizards' Tower ring, for accounts with no Ardougne diary. */
    NECKLACE_OF_PASSAGE,

    /**
     * Permission to ride the spirit tree network, which Tree Gnome Village grants. Eight
     * destinations are permanent: Tree Gnome Village, the Gnome Stronghold, the Battlefield
     * of Khazard, the Grand Exchange, Feldip Hills, the Poison Waste, Prifddinas and Laguna
     * Aurorae. The rest are trees the player plants in farming patches, so a rung landing at
     * one also asks for that patch's tree ({@link #SPIRIT_TREE_GROWN_BRIMHAVEN}).
     *
     * <p>Riding still means walking to a tree, so a rung asking for this alone belongs below
     * any rung that names a way to one.
     *
     * <p>Departing the Gnome Stronghold tree also needs {@link #SPIRIT_TREE_STRONGHOLD}.
     */
    SPIRIT_TREE_NETWORK,

    /**
     * Boarding the Gnome Stronghold's own spirit tree at (2461, 3444), which The Grand Tree
     * opens. Arriving there needs only {@link #SPIRIT_TREE_NETWORK}.
     *
     * <p>Kept out of {@link #SPIRIT_TREE_NETWORK} so that the second quest gates only rungs
     * departing from this tree. Kept apart from {@link #GNOME_GLIDER}, which shares the
     * unlock, because the packing list names what the player is about to click.
     */
    SPIRIT_TREE_STRONGHOLD,

    /**
     * A spirit tree grown in one patch, which adds that location as a destination.
     *
     * <p>Answered from the patch as last seen (see {@code CapabilitySources}). An unseen
     * patch counts as empty.
     */
    SPIRIT_TREE_GROWN_BRIMHAVEN,
    SPIRIT_TREE_GROWN_FARMING_GUILD,
    SPIRIT_TREE_GROWN_PORT_SARIM,

    /**
     * Being allowed into Lletya, which Mourning's End Part I opens once <em>started</em>.
     * It gates the patch rather than any one rung: without it no route in exists.
     */
    LLETYA_ACCESS,

    // --- Whether a patch is the player's to work at all -----------------------
    // Each of these is a stop's accessGate: without it the patch cannot be worked by any
    // means, because the place is shut or the patch is not built. Access gates are checked
    // before any travel chain is walked.

    MORYTANIA_ACCESS,

    /**
     * The Troll Stronghold herb patch, which sits on the stronghold roof and is a reward of
     * My Arm's Big Adventure, not of Eadgar's Ruse (which only opens a teleport). That quest
     * requires Death Plateau and Troll Stronghold, so anyone who can work the patch can walk
     * to it.
     */
    TROLL_STRONGHOLD_HERB_PATCH,

    /**
     * The fire of nourishment, without which the Weiss patch cannot be farmed.
     *
     * <p>No varbit names it: the five {@code MY2ARM_FIRE_*} flags are other fires. It needs
     * Construction 35, Firemaking 66 and three hundred salt, so many players past the quest
     * lack it. Detection reads it from whether the Weiss patch has been seen (see
     * {@code CapabilitySources}).
     */
    WEISS_HERB_PATCH,

    /**
     * The Locus Oasis hardwood patches, behind a quest of their own on top of Varlamore.
     */
    LOCUS_OASIS_PATCH,

    /**
     * The Great Conch, which Troubled Tortugans opens partway through, when the player hands
     * Floopa the bandage. Neither Varlamore nor the Sailing level for its dock is needed: a
     * fairy ring and a charter both reach it.
     */
    GREAT_CONCH_ACCESS,

    // --- Farming supplies ----------------------------------------------------
    // Inventory-space downgrades, ranked the same way as travel ones.
    ULTRACOMPOST,
    MAGIC_SECATEURS,
    SEED_DIBBER,
    SPADE,

    /**
     * Planting seeds by hand, which the Farming part of Barbarian Training teaches and
     * which removes the need for a seed dibber.
     */
    BARE_HAND_PLANTING;

    static {
        Rows.TABLE.requireAll(values());
    }

    /**
     * A set of items that are upgrades of one another, where owning a higher one means
     * owning everything the lower ones could do.
     */
    public enum TierFamily {
        /** Stands alone; nothing else substitutes for it. */
        NONE,
        EXPLORERS_RING,
        ARDOUGNE_CLOAK
    }

    /** How, if at all, this capability can be answered from observable game state. */
    public enum Detectability {
        /** Answerable from what the player is carrying, wearing, or banking. */
        ITEM,
        /** Answerable from a quest, diary, spellbook, or other game flag. */
        VARBIT,
        /** Answerable from a base skill level. Boosts are never read. */
        SKILL,
        /**
         * Answerable only from what loads around the player while they stand in it: the
         * furniture of their own house, read on a visit. Until then it is taken to be
         * absent, and the player is never asked. Assuming absence costs at worst a slower
         * route, never a wrong instruction.
         */
        SEEN
    }

    /** A capability with no per-day cap, which is most of them. */
    public static final int UNLIMITED = 0;

    /** Player-facing name, phrased as the game phrases it. */
    private final String displayName;
    private final Detectability detectability;
    /** How many times a day this can be used, or {@link #UNLIMITED} for no cap. */
    private final int dailyUses;
    private final TierFamily tierFamily;
    /** Position within {@link #tierFamily}, higher being better. Zero if untiered. */
    private final int tier;

    Capability() {
        Tables.Row row = Rows.TABLE.of(name());
        this.displayName = row.text(1);
        this.detectability = row.constant(Detectability.class, 2);
        this.dailyUses = row.integer(3);
        this.tierFamily = row.constant(TierFamily.class, 4);
        this.tier = row.integer(5);
    }

    /**
     * The capabilities table, held apart so the constructors can read it; see
     * {@link Tables#byName}.
     */
    private static final class Rows {
        static final Tables.Named TABLE = Tables.byName("/com/larryfarming/capabilities.tsv", 6);
    }

    public boolean isRationedDaily() {
        return dailyUses != UNLIMITED;
    }

    /**
     * Whether holding {@code held} is enough to satisfy a requirement for this one.
     *
     * <p>A higher tier of the same family satisfies a lower one: a player past the elite
     * diary holds a ring 4 and no ring 2.
     */
    public boolean isSatisfiedBy(Capability held) {
        if (held == this) {
            return true;
        }
        return tierFamily != TierFamily.NONE && held.tierFamily == tierFamily && held.tier >= tier;
    }

    /**
     * The tier of this family the player actually holds, given everything they have, or
     * null if they hold none of it.
     *
     * <p>Use this rather than the tier a chain names when checking daily allowances: a
     * player asked for a ring 2 while holding a ring 3 has no daily limit.
     */
    public static Capability bestHeldTier(TierFamily family, Collection<Capability> held) {
        if (family == TierFamily.NONE) {
            return null;
        }
        Capability best = null;
        for (Capability capability : held) {
            if (capability.tierFamily == family && (best == null || capability.tier > best.tier)) {
                best = capability;
            }
        }
        return best;
    }

}

package com.larryfarming.farming.model;

import com.larryfarming.data.Tables;
import lombok.Getter;

/**
 * Somewhere a farm run teleports to, as opposed to the particular way of getting there.
 *
 * <p>A chain rung such as "Catherby teleport tablet" really means "be at Catherby". A
 * player on the Lunar book with the runes should cast instead of spending a tablet.
 * Naming the place lets one rung serve both means without changing the chain's ordering
 * between places.
 *
 * <p>A destination may also name the {@link Zone} it lands in. A player already inside
 * that zone reaches the rung for free: no cast, no tablet, nothing to pack. The zone is
 * null for destinations whose regions have not been walked, so the shortcut never fires
 * there. A zone is set only from a walked or checked tile. A wrong one would drop a
 * teleport from the packing list that the player then needs.
 *
 * <p>Each destination's name and zone come from the destinations table.
 */
public enum Destination {

    CATHERBY,
    CAMELOT,
    VARROCK,
    /**
     * The Varrock teleport's second landing (3165, 3479), which the medium Varrock diary
     * adds. Its means are Varrock's spell and tablet, which carry no diary gate, so every
     * rung that asks for this place also asks for {@link Capability#VARROCK_DIARY_MEDIUM}.
     */
    GRAND_EXCHANGE,
    LUMBRIDGE,
    FALADOR,
    ARDOUGNE,
    /** Never zoned: the house is wherever the player built it, which nothing reports. */
    HOUSE,
    FISHING_GUILD,
    FENKENSTRAINS_CASTLE,
    SALVE_GRAVEYARD,
    DRAYNOR_MANOR,
    ARCEUUS_LIBRARY,
    HARMONY_ISLAND,
    KOUREND_CASTLE,
    CIVITAS_ILLA_FORTIS;

    static {
        Rows.TABLE.requireAll(values());
    }

    @Getter
    private final String displayName;
    /** The zone this lands in, or null where it has not been walked. */
    @Getter
    private final Zone zone;

    Destination() {
        Tables.Row row = Rows.TABLE.of(name());
        this.displayName = row.text(1);
        this.zone = row.optionalConstant(Zone.class, 2);
    }

    /**
     * The destinations table, held apart so the constructors can read it; see
     * {@link Tables#byName}.
     */
    private static final class Rows {
        static final Tables.Named TABLE = Tables.byName("/com/larryfarming/destinations.tsv", 3);
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.data.Tables;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.engine.farming.FarmingWorldMap;
import java.util.*;

/**
 * The config keys of every farming setting, spelled once.
 *
 * <p>The side panel writes these keys, the plugin listens for them, and the planner reads
 * them, all through this class. None is a {@code @ConfigItem}, so none shows on RuneLite's
 * settings page.
 */
public final class FarmingKeys {

    // Switches that plant nothing.
    public static final String PICK_FRUIT_IN_PASSING = "pickFruitInPassing";
    // Travel methods' keys come from the travel methods table: TravelMethod.getKey().
    // What the player says their house holds is keyed by each HouseItem: HouseItem.getKey().

    /**
     * Every site's key, each true while the run includes the site, in the stops table's
     * order: its {@code switch} lines. Callers read it as a set. Each key is named for its
     * place rather than derived from the site's key. The herb run's extras have their crop
     * switches or their picks instead.
     */
    public static final List<String> SITES;

    /**
     * The allotments and flower patches whose crop the player picks, in the stops table's
     * order: its {@code pick} lines. Keyed by site.
     */
    public static final Map<String, PatchPick> PICKS;

    static {
        List<Tables.Row> stops = Tables.read("/com/larryfarming/stops.tsv");
        SITES = siteKeys(stops);
        PICKS = picks(stops);
    }

    /** A pick's value when the patch plants nothing. */
    public static final String OFF = "OFF";

    // How the planner ranks and paces. The favourite herb holds a herb's Crop name, or
    // NO_FAVOURITE; the others are booleans.
    public static final String FAVOURITE_HERB = "favouriteHerb";
    public static final String BEST_SEEDS_EVERYWHERE = "bestSeedsInEveryPatch";
    public static final String HERB_RUN_FIRST = "herbRunFirst";
    public static final String WAIT_FOR_EVERY_PATCH = "waitForEveryPatch";
    public static final String FRUIT_TREES_WAIT_FOR_SAPLINGS = "fruitTreesWaitForSaplings";
    public static final String REPLANT_GROWN_TREES = "replantGrownTrees";
    public static final String HERB_RUNS_WAIT_FOR_LEVEL = "herbRunsWaitForLevel";
    public static final String COMPOST_WITH_FERTILE_SOIL = "compostWithFertileSoil";

    // The compost thresholds hold whole numbers.
    public static final String MAKE_COMPOST_BELOW = "makeCompostBelow";
    public static final String STOP_COMPOST_AT = "stopCompostAt";

    /** The favourite herb's value when there is none. */
    public static final String NO_FAVOURITE = "none";

    /** Each crop's tick, for every crop {@link FarmingPreferences#hasAswitch} accepts. */
    public static final Map<Crop, String> CROPS = cropKeys();

    private static final Set<String> ALL = allKeys();

    private FarmingKeys() {
    }

    /** The crop data table's config key column, for the crops that have one. */
    private static Map<Crop, String> cropKeys() {
        Map<Crop, String> keys = new EnumMap<>(Crop.class);
        Set<String> seen = new HashSet<>();
        for (Tables.Row row : Tables.read("/com/larryfarming/crop-data.tsv", 15)) {
            String key = row.text(13);
            if (key.isEmpty()) {
                continue;
            }
            if (!seen.add(key)) {
                throw row.error("a second crop keyed " + key);
            }
            keys.put(row.constant(Crop.class, 0), key);
        }
        return Collections.unmodifiableMap(keys);
    }

    /** The stops table's switch keys, in its order. */
    private static List<String> siteKeys(List<Tables.Row> stops) {
        List<String> keys = new ArrayList<>();
        for (Tables.Row row : stops) {
            if (row.text(0).equals("switch")) {
                String key = row.requireWidth(3).text(1);
                if (keys.contains(key)) {
                    throw row.error("a second switch " + key);
                }
                keys.add(key);
            }
        }
        return List.copyOf(keys);
    }

    /**
     * The stops table's pick lines, each under the site it picks for: the pick's key, the
     * For compost key or - for a patch with no bin, the farm, the picker's title, and the crop
     * switches read while the pick is unsaved.
     */
    private static Map<String, PatchPick> picks(List<Tables.Row> stops) {
        Map<String, PatchPick> picks = new LinkedHashMap<>();
        String site = null;
        for (Tables.Row row : stops) {
            if (row.text(0).equals("site")) {
                site = row.text(1);
            } else if (row.text(0).equals("pick")) {
                row.requireWidth(6);
                if (FarmingWorldMap.byCatalogueKey(site) == null) {
                    throw row.error("a pick at " + site + ", which is no patch's key");
                }
                if (picks.put(site, new PatchPick(site, row.text(1), row.optionalText(2), row.text(3), row.text(4),
                        row.constants(Crop.class, 5))) != null) {
                    throw row.error("a second pick at " + site);
                }
            }
        }
        return Collections.unmodifiableMap(picks);
    }

    private static Set<String> allKeys() {
        Set<String> all = new HashSet<>(CROPS.values());
        all.addAll(List.of(PICK_FRUIT_IN_PASSING, FAVOURITE_HERB, BEST_SEEDS_EVERYWHERE, HERB_RUN_FIRST, WAIT_FOR_EVERY_PATCH,
                FRUIT_TREES_WAIT_FOR_SAPLINGS, REPLANT_GROWN_TREES, HERB_RUNS_WAIT_FOR_LEVEL, COMPOST_WITH_FERTILE_SOIL,
                MAKE_COMPOST_BELOW, STOP_COMPOST_AT));
        for (TravelMethod method : TravelMethod.values()) {
            all.add(method.getKey());
        }
        all.addAll(SITES);
        for (PatchPick pick : PICKS.values()) {
            all.add(pick.getKey());
            if (pick.getCompostKey() != null) {
                all.add(pick.getCompostKey());
            }
        }
        for (HouseItem item : HouseItem.values()) {
            all.add(item.getKey());
        }
        return Collections.unmodifiableSet(all);
    }

    /** Every key a farming setting is saved under. */
    public static Set<String> all() {
        return ALL;
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.engine.farming.Crop;
import com.larryfarming.engine.farming.PatchType;
import com.larryfarming.farming.catalogue.CropData;
import java.util.*;
import lombok.*;
import lombok.experimental.Accessors;

/**
 * What the player is willing to plant, and what they would rather leave alone.
 *
 * <p>Every crop the player has a say in carries one tick. Herbs and the three tree families
 * are ticked crop by crop: a patch takes the best ticked crop the player has the seed for,
 * and a family with nothing ticked is switched off. Every other crop the catalogue grows
 * takes the same tick as a plain on/off switch.
 *
 * <p>The defaults are {@link Preset#DEFAULT}'s, so an untouched install plants what the
 * runs are written for. Each default must agree with the catalogue, so retune a run there
 * too.
 *
 * <p>Ticks are hard: an unticked crop is never suggested, even when that leaves a patch
 * empty and a run unproposed.
 *
 * <p>Some settings plant nothing themselves but change how the planner ranks and paces:
 * the favourite herb, where the best herb seeds go, which run goes first, and whether a
 * run waits for every patch.
 */
@EqualsAndHashCode
@Getter
@Accessors(fluent = true)
public final class FarmingPreferences {

    /**
     * Every herb the player ticks, best first by the preset's ranking.
     *
     * <p>The herb ranking is by experience and disagrees with level order at three places,
     * so the order here is not the Farming level's.
     *
     * <p>Torstol is here though the preset leaves it unticked, kept for hard contracts.
     */
    public static final List<Crop> HERB_CHOICES = Preset.DEFAULT.getHerbRanking();

    /**
     * Every crop of each tree family, best first, which for trees is level order: each is
     * every crop its patch takes, so no tree is missing a tick.
     */
    public static final Map<PatchType, List<Crop>> TREE_CHOICES = treeChoices();

    private static Map<PatchType, List<Crop>> treeChoices() {
        Map<PatchType, List<Crop>> families = new EnumMap<>(PatchType.class);
        for (PatchType family : EnumSet.of(PatchType.TREE, PatchType.FRUIT_TREE, PatchType.HARDWOOD_TREE)) {
            families.put(family, CropData.plantableIn(family));
        }
        return Collections.unmodifiableMap(families);
    }

    private final Set<Crop> enabled;

    /**
     * Whether a fruit tree is worth stopping at purely to pick it. Off by default: a living
     * fruit tree keeps its fruit until the next visit, and the fruit alone does not repay
     * the trip. Replanting is offered regardless of this setting.
     */
    private final boolean picksFruitInPassing;

    /**
     * The travel methods the player has switched off. Each refusal is hard and covers every
     * use: a stop that only a refused method reaches loses that rung. See
     * {@link TravelMethod}.
     */
    private final Set<TravelMethod> travelOff;

    /**
     * The sites the player has dropped from their runs, by {@link FarmingKeys#SITES} key. A
     * dropped site is silenced as a switched-off crop is: gone from the walkthrough, the runs
     * list and the timers.
     */
    private final Set<String> sitesOff;

    /**
     * The sites this account is seen unable to reach yet, by key: a fact about the account,
     * not a setting, so it is never saved. Only {@link #dropsEverySiteOf} reads it, so a run
     * whose every reachable site is dropped switches off; a shut site still keeps its stop.
     * Empty until the engine reads the account.
     */
    private final Set<String> sitesShut;

    /**
     * What the player says their house holds, as the {@link HouseItem} capabilities. A
     * declaration counts only until the item has been seen; what was seen wins, and the
     * declaration stays saved.
     */
    private final Set<Capability> houseDeclared;

    /**
     * The herb the rotation ranks above every other, or null for the preset's ranking.
     * Always a ticked herb: a favourite the player cannot plant would rank nothing.
     */
    private final Crop favouriteHerb;

    /** Whether every herb patch takes the best seeds, not only the yield-bonus ones. */
    private final boolean plantsBestSeedsEverywhere;

    /** Whether the herb run goes first among runs due together. */
    private final boolean herbRunFirst;

    /** Whether a run waits until every patch on it needs a visit before it is due. */
    private final boolean waitsForEveryPatch;

    /** Whether the fruit tree run waits until the player owns a sapling for every patch. */
    private final boolean fruitTreesWaitForSaplings;

    /** Whether a grown fruit tree is felled for a sapling no worse than itself. */
    private final boolean replantsGrownTrees;

    /** Whether the herb run waits for {@link Preset#HERB_RUN_LEVEL} Farming. */
    private final boolean herbRunsWaitForLevel;

    /**
     * Whether patches are treated with Fertile Soil cast with volcanic ash, which needs the
     * Ash covered tome read, instead of carried ultracompost.
     */
    private final boolean compostsWithFertileSoil;

    /**
     * The compost stock, in patches it can treat, below which the bins are worked again.
     * Always a whole step, from {@link #COMPOST_STEP} up to one step below {@link #COMPOST_MOST}.
     */
    private final int makeCompostBelow;

    /**
     * The compost stock at which the bins are left alone. Always a step above
     * {@link #makeCompostBelow}, and at most {@link #COMPOST_MOST}.
     */
    private final int stopCompostAt;

    /** The compost thresholds move in steps of this many patches, starting at one step. */
    public static final int COMPOST_STEP = 100;

    /** The highest compost threshold: the tool leprechaun holds 1,000 of each compost. */
    public static final int COMPOST_MOST = 1000;

    /** Each picked patch's crop, by site ({@link FarmingKeys#PICKS}); a patch missing plants nothing. */
    private final Map<String, Crop> picks;

    /** The picked allotments that plant for compost, by site. */
    private final Set<String> forCompost;

    /**
     * The picked patches whose crop the player chose, by site, as against the preset's. A
     * crop the player chose says why it isn't planting; the preset's stays quiet.
     */
    private final Set<String> picksChosen;

    /**
     * The picked patches that plant nothing and say nothing for now, by site, and the
     * settings still show their pick. A pick is quiet while the account can't plant its
     * preset crop yet. It is also quiet while its farm's compost thermostat holds it: the
     * thermostat is off, the bank is unseen, or Larry leaves the bin beside it this run with
     * a crop standing in the patch (the bin rotting, full, short of potion, ash or buckets,
     * or at Ortus Farm with no bottomless bucket).
     */
    private final Set<String> picksQuiet;

    /**
     * @param enabled every crop the player has ticked; a crop missing from it is unticked
     * @param travelOff every travel method switched off
     * @param sitesOff every site dropped, by key; a key naming no site is ignored
     * @param sitesShut every site the account is seen unable to reach, by key
     * @param houseDeclared every house item declared built; any other capability is ignored
     * @param favouriteHerb read as none unless it is a ticked herb
     * @param makeCompostBelow rounded down to a step and kept below {@link #COMPOST_MOST}
     * @param stopCompostAt rounded down to a step, and raised a step above
     *     {@code makeCompostBelow} if it is not already above it
     */
    // Copied into fresh EnumSets because EnumSet.copyOf throws on an empty plain
    // collection, which "everything switched off" produces.
    //
    // No public builder(): a fresh builder defaults every switch to false, which is not the
    // default route. Callers start from defaults().toBuilder() and change only what they
    // mean to.
    @Builder(toBuilder = true, builderMethodName = "")
    private FarmingPreferences(Set<Crop> enabled, boolean picksFruitInPassing, Set<TravelMethod> travelOff, Set<String> sitesOff,
            Set<String> sitesShut, Set<Capability> houseDeclared, Crop favouriteHerb,
            boolean plantsBestSeedsEverywhere, boolean herbRunFirst, boolean waitsForEveryPatch, boolean fruitTreesWaitForSaplings,
            boolean replantsGrownTrees, boolean herbRunsWaitForLevel, boolean compostsWithFertileSoil, Map<String, Crop> picks,
            Set<String> forCompost, Set<String> picksChosen, Set<String> picksQuiet, int makeCompostBelow, int stopCompostAt) {
        this.enabled = copy(Crop.class, enabled);
        this.picksFruitInPassing = picksFruitInPassing;
        this.travelOff = copy(TravelMethod.class, travelOff);
        // Sorted, so equal preferences print alike; filtered, so a stray key cannot make two
        // identical sets of choices unequal.
        this.sitesOff = knownSites(sitesOff);
        this.sitesShut = knownSites(sitesShut);
        EnumSet<Capability> declaredCopy = EnumSet.noneOf(Capability.class);
        if (houseDeclared != null) {
            for (Capability capability : houseDeclared) {
                if (HouseItem.of(capability) != null) {
                    declaredCopy.add(capability);
                }
            }
        }
        this.houseDeclared = Collections.unmodifiableSet(declaredCopy);
        this.favouriteHerb = favouriteHerb != null && HERB_CHOICES.contains(favouriteHerb)
                && this.enabled.contains(favouriteHerb) ? favouriteHerb : null;
        this.plantsBestSeedsEverywhere = plantsBestSeedsEverywhere;
        this.herbRunFirst = herbRunFirst;
        this.waitsForEveryPatch = waitsForEveryPatch;
        this.fruitTreesWaitForSaplings = fruitTreesWaitForSaplings;
        this.replantsGrownTrees = replantsGrownTrees;
        this.herbRunsWaitForLevel = herbRunsWaitForLevel;
        this.compostsWithFertileSoil = compostsWithFertileSoil;
        // The pair stays valid whatever was saved: the low threshold leaves room for one
        // step above it, and the high one is always above the low one.
        this.makeCompostBelow = toStep(makeCompostBelow, COMPOST_STEP, COMPOST_MOST - COMPOST_STEP);
        this.stopCompostAt = toStep(stopCompostAt, this.makeCompostBelow + COMPOST_STEP, COMPOST_MOST);
        // Sorted, less any site the settings don't know, any patch picked for nothing and any
        // crop its patch can't grow.
        Map<String, Crop> picked = new TreeMap<>(picks != null ? picks : Map.of());
        picked.keySet().retainAll(FarmingKeys.PICKS.keySet());
        picked.values().removeIf(Objects::isNull);
        picked.entrySet().removeIf(pick -> !CropData.plantableIn(FarmingKeys.PICKS.get(pick.getKey()).getPatchType())
                .contains(pick.getValue()));
        this.picks = Collections.unmodifiableMap(picked);
        this.forCompost = knownPicks(forCompost);
        this.picksChosen = knownPicks(picksChosen);
        this.picksQuiet = knownPicks(picksQuiet);
    }

    /** A threshold rounded down to a whole step and held between the two bounds. */
    private static int toStep(int value, int least, int most) {
        int stepped = value / COMPOST_STEP * COMPOST_STEP;
        return Math.max(least, Math.min(most, stepped));
    }

    private static Set<String> knownPicks(Set<String> sites) {
        return known(sites, FarmingKeys.PICKS.keySet());
    }

    private static <E extends Enum<E>> Set<E> copy(Class<E> type, Set<E> from) {
        EnumSet<E> copy = EnumSet.noneOf(type);
        if (from != null) {
            copy.addAll(from);
        }
        return Collections.unmodifiableSet(copy);
    }

    private static Set<String> knownSites(Set<String> keys) {
        return known(keys, FarmingKeys.SITES);
    }

    /** These keys less any the settings don't know, sorted. */
    private static Set<String> known(Set<String> keys, Collection<String> known) {
        Set<String> copy = new TreeSet<>();
        if (keys != null) {
            for (String site : keys) {
                if (known.contains(site)) {
                    copy.add(site);
                }
            }
        }
        return Collections.unmodifiableSet(copy);
    }

    /** The default route's settings, which an untouched install runs on. */
    public static FarmingPreferences defaults() {
        return Preset.DEFAULT.preferences();
    }

    /** Whether this travel method may be used. Every method is on by default. */
    public boolean uses(TravelMethod method) {
        return !travelOff.contains(method);
    }

    /** Whether the runs visit the site with this key. Every site is visited by default. */
    public boolean visits(String siteKey) {
        return !sitesOff.contains(siteKey);
    }

    /**
     * Whether the player has dropped every one of these sites they can reach, and at least
     * one: a site the account is seen unable to reach counts as dropped, so it cannot hold a
     * run open on its own. False for no sites, and while none is dropped.
     */
    public boolean dropsEverySiteOf(List<String> sites) {
        if (sites.isEmpty() || sitesOff.isEmpty()) {
            return false;
        }
        boolean anyDropped = false;
        for (String site : sites) {
            if (sitesOff.contains(site)) {
                anyDropped = true;
            } else if (!sitesShut.contains(site)) {
                return false;
            }
        }
        return anyDropped;
    }

    /**
     * The same preferences, with these sites known to be out of the account's reach. See
     * {@link #sitesShut}.
     */
    public FarmingPreferences withSitesShut(Set<String> shut) {
        return knownSites(shut).equals(sitesShut) ? this : toBuilder().sitesShut(shut).build();
    }

    /** The same preferences with these picked patches quiet. See {@link #picksQuiet}. */
    public FarmingPreferences withPicksQuiet(Set<String> quiet) {
        return knownPicks(quiet).equals(picksQuiet) ? this : toBuilder().picksQuiet(quiet).build();
    }

    /** The crop this picked patch plants, or null for none or for a quiet preset crop. */
    public Crop pickAt(String site) {
        return picksQuiet.contains(site) ? null : picks.get(site);
    }

    /** Whether this picked allotment plants for compost. */
    public boolean plantsForCompost(String site) {
        return forCompost.contains(site);
    }

    /** Whether the player says their house holds this. Nothing is declared by default. */
    public boolean declares(HouseItem item) {
        return houseDeclared.contains(item.getCapability());
    }

    /**
     * A herb ranking with the favourite moved to the top and the rest left in order. The
     * ranking itself when there is no favourite.
     */
    public List<Crop> favouriteFirst(List<Crop> ranking) {
        if (favouriteHerb == null || !ranking.contains(favouriteHerb)) {
            return ranking;
        }
        List<Crop> ranked = new ArrayList<>(ranking);
        ranked.removeIf(herb -> herb == favouriteHerb);
        ranked.add(0, favouriteHerb);
        return List.copyOf(ranked);
    }

    /** Where this run sorts among runs due together; lower goes first, starting at 1. */
    public int priorityOf(RunId run) {
        return Preset.DEFAULT.priorityOf(run, herbRunFirst);
    }

    /**
     * The crops ticked one by one for this family, best first: the herbs, or a tree
     * family's crops. Empty for a family whose crops are plain switches or have no tick.
     */
    public static List<Crop> familyChoices(PatchType type) {
        if (type == PatchType.HERB) {
            return HERB_CHOICES;
        }
        return TREE_CHOICES.getOrDefault(type, List.of());
    }

    /**
     * Whether this family is one the player has switched off entirely: a family ticked crop
     * by crop with nothing ticked. Other patch types (bushes, flowers) answer
     * false: {@link #allows} covers them.
     */
    public boolean isFamilyOff(PatchType type) {
        List<Crop> choices = familyChoices(type);
        return !choices.isEmpty() && Collections.disjoint(enabled, choices);
    }

    /**
     * Whether this crop is one the player still wants planted. A crop with no tick answers
     * true: the player has no say in it.
     */
    public boolean allows(Crop crop) {
        return !hasAswitch(crop) || enabled.contains(crop);
    }

    /** Whether the player is offered a say in this crop at all. */
    public static boolean hasAswitch(Crop crop) {
        return FarmingKeys.CROPS.containsKey(crop);
    }

    /**
     * The ticked crops of a ranking, in the ranking's order. A crop with no tick is never in
     * the answer, so a ranking that names one cannot plant it.
     *
     * @param ranking every crop a patch could take, best first
     */
    public List<Crop> ticked(List<Crop> ranking) {
        List<Crop> wanted = new ArrayList<>(ranking);
        wanted.retainAll(enabled);
        return List.copyOf(wanted);
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.engine.farming.PatchType;
import java.util.List;
import lombok.*;

/** One repeatable farming activity: an ordered set of stops, and what unlocks it. */
@Value
@Builder(toBuilder = true)
public class FarmingRun {

    @NonNull
    RunId id;

    @NonNull
    Spellbook spellbook;

    @NonNull
    UnlockGate unlock;

    /**
     * The town this run prefers its respawn point set to, or null when it has no
     * preference.
     *
     * <p>Advisory, not a requirement. Runs prefer different respawn points, and switching costs a trip across the map. The run is planned
     * around wherever the respawn point actually is.
     */
    String respawnTown;

    @Singular("stop")
    List<RunStop> stops;

    /**
     * The patch type whose ticked crops this run plants, or null when the shared seed
     * policy decides. The player's ticks pick the crops, best first; a player out of the
     * best seed drops a tier rather than skipping the run.
     *
     * <p>A run states its seeds in at most one way: this type, or a stop that names its
     * crop outright ({@link RunStop.Builder#plants}). Stating neither hands the patch to the
     * shared herb rotation. Stating both packs the same seed twice.
     */
    PatchType seedPatchType;
}

package com.larryfarming.farming.model;

import java.util.ArrayList;
import java.util.List;
import lombok.Value;

/**
 * One item worth wearing on a farm run, and why.
 *
 * <p>Named by item rather than by {@link Capability} because the panel draws the item.
 *
 * <p>A pick usually has several IDs: charged jewellery has a different ID at every charge
 * level, and skill capes come trimmed and untrimmed.
 *
 * <p>A pick can also stand for interchangeable items with names of their own, such as the
 * dramen and lunar staves, which open fairy rings alike. Each is one of its
 * {@link #forms}, so the panel can name and draw the one the player holds.
 */
@Value
public class GearPick {

    /** Every item ID that counts as wearing this. The first is the sprite shown. */
    List<Integer> itemIds;

    String displayName;

    /** One clause on what it buys, for the row under the slot. */
    String benefit;

    /** The named items this pick accepts alike, or empty when it is one item. */
    List<GearPick> forms;

    public static GearPick of(String displayName, String benefit, int... itemIds) {
        if (itemIds.length == 0) {
            throw new IllegalArgumentException(displayName + " needs at least one item id");
        }
        List<Integer> ids = new ArrayList<>(itemIds.length);
        for (int id : itemIds) {
            ids.add(id);
        }
        return new GearPick(List.copyOf(ids), displayName, benefit, List.of());
    }

    /**
     * A pick any of these items fills, alike. The first form is drawn while the player
     * holds none of them.
     */
    public static GearPick anyOf(String displayName, String benefit, GearPick... forms) {
        if (forms.length == 0) {
            throw new IllegalArgumentException(displayName + " needs at least one form");
        }
        List<Integer> ids = new ArrayList<>();
        for (GearPick form : forms) {
            ids.addAll(form.getItemIds());
        }
        return new GearPick(List.copyOf(ids), displayName, benefit, List.of(forms));
    }

    /** The form that accepts this item, or this pick when it has no forms or none fits. */
    public GearPick formHolding(int itemId) {
        for (GearPick form : forms) {
            if (form.getItemIds().contains(itemId)) {
                return form;
            }
        }
        return this;
    }

    /** The sprite to draw for this pick. */
    public int getIconItemId() {
        return itemIds.get(0);
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.data.Tables;
import java.util.*;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Something in the player's own house that a farm run can travel by, which the player may
 * declare built before Larry has seen it.
 *
 * <p>Declared in the order the settings draw them, which never changes: the portal chamber,
 * then the Portal Nexus, then the garden.
 *
 * <p>Each item's group, label, config key and capability come from the house items table.
 */
@Getter
public enum HouseItem {
    WEISS_PORTAL,
    TROLL_STRONGHOLD_PORTAL,
    KOUREND_PORTAL,
    FENKENSTRAIN_PORTAL,
    HARMONY_PORTAL,
    WEISS_IN_NEXUS,
    TROLL_STRONGHOLD_IN_NEXUS,
    HARMONY_IN_NEXUS,
    SPIRIT_TREE,
    FAIRY_RING;

    static {
        Rows.TABLE.requireAll(values());
    }

    /** Where in the house an item stands, as the settings caption it. */
    @Getter
    @RequiredArgsConstructor
    public enum Group {
        PORTALS("Portals"),
        NEXUS("Portal Nexus"),
        GARDEN("Garden");

        private final String label;
    }

    private static final Map<Capability, HouseItem> BY_CAPABILITY = byCapability();

    private final Group group;
    /** Short enough for two columns at sidebar width, beside its group's caption. */
    private final String label;
    /**
     * The config key that holds the declaration, true while the player says it is built. A
     * declaration counts only until Larry has seen the item. Players' saved settings sit
     * under these keys.
     */
    private final String key;
    private final Capability capability;

    HouseItem() {
        Tables.Row row = Rows.TABLE.of(name());
        this.group = row.constant(Group.class, 1);
        this.label = row.text(2);
        this.key = row.text(3);
        this.capability = row.constant(Capability.class, 4);
    }

    /**
     * The house items table, held apart so the constructors can read it; see
     * {@link Tables#byName}.
     */
    private static final class Rows {
        static final Tables.Named TABLE = Tables.byName("/com/larryfarming/house-items.tsv", 5);
    }

    private static Map<Capability, HouseItem> byCapability() {
        Map<Capability, HouseItem> map = new EnumMap<>(Capability.class);
        for (HouseItem item : values()) {
            map.put(item.capability, item);
        }
        return Collections.unmodifiableMap(map);
    }

    /** The item this capability is, or null for a capability no house item answers. */
    public static HouseItem of(Capability capability) {
        return BY_CAPABILITY.get(capability);
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.model.EquipmentSlot;
import java.util.List;
import lombok.Value;

/**
 * What goes in one equipment slot on a farm run, best first.
 *
 * <p>Shaped like a travel chain: gear comes as ordered fallbacks, such as
 * "Max cape → Farming cape → Ardougne cloak". A player wears the best tier they have
 * reached. The panel shows every tier so the player can see the next upgrade.
 */
@Value
public class LoadoutSlot {

    EquipmentSlot slot;

    /** Best first. Never empty. */
    List<GearPick> tiers;

    /**
     * True when leaving the slot empty costs only convenience: a missing cape costs a
     * walk, while missing magic secateurs cost yield on every patch they work on.
     */
    boolean niceToHave;

    /**
     * The group this slot belongs to, or null when it stands alone. The farmer's outfit
     * spans four slots that the panel lists as one item.
     */
    String group;

    /**
     * True when carrying the item does not serve the run. The Farmer's outfit and a staff
     * for fairy rings work only while worn, and the log basket's only gain is the inventory
     * slot that wearing it frees. Everything else works from the inventory too, so carrying
     * it fills the slot as far as the run is concerned.
     */
    boolean mustWear;

    /**
     * The sentence for an owned item that is not where the run wants it, with {@code %s}
     * for the item's name mid-sentence: "Wear your %s to save an inventory slot."
     */
    String tip;

    /**
     * The tier to work toward while none is owned. The cheapest rung by default, since it
     * is the one within reach.
     */
    GearPick goal;

    /** The whole sentence for the goal row: "Earn Ardougne cloak 2 for …". */
    String goalSentence;
}

package com.larryfarming.farming.model;

