package com.larryfarming.farming.model;

import com.larryfarming.engine.farming.FarmingWorldMap;
import com.larryfarming.engine.farming.PatchType;
import lombok.*;

/**
 * A reference to one farming patch, by the same (region, transmit varbit) pair that
 * {@link FarmingWorldMap} keys on. The varbit alone is ambiguous: the same transmit
 * varbit carries different patches in different regions.
 *
 * <p>Equality ignores the label, so a hand-written reference matches the catalogue's
 * constant for the same patch.
 */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class PatchRef {

    int regionId;
    int varbitId;

    @EqualsAndHashCode.Exclude
    String label;

    public static PatchRef of(int regionId, int varbitId, String label) {
        return new PatchRef(regionId, varbitId, label);
    }

    /**
     * The patch the registry keys {@code key}, such as {@code WEISS_HERB}, labelled with its
     * location, name and type.
     *
     * @throws IllegalArgumentException if no patch has that key
     */
    public static PatchRef named(String key) {
        FarmingWorldMap.PatchDef def = FarmingWorldMap.byCatalogueKey(key);
        if (def == null) {
            throw new IllegalArgumentException("the registry has no patch " + key);
        }
        return new PatchRef(def.getRegionId(), def.getVarbitId(), def.displayName() + " " + def.getType());
    }

    /** The registry key, in the same {@code region.varbit} form used for persistence. */
    public String configKey() {
        return regionId + "." + varbitId;
    }

    /** The registry entry this points at, or null if it names no known patch. */
    public FarmingWorldMap.PatchDef resolve() {
        return FarmingWorldMap.byConfigKey(configKey());
    }

    /** The type of patch this points at, or null if it names no known patch. */
    public PatchType type() {
        FarmingWorldMap.PatchDef def = resolve();
        return def != null ? def.getType() : null;
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.data.Tables;
import com.larryfarming.engine.farming.Crop;
import com.larryfarming.farming.catalogue.CropData;
import java.util.*;
import lombok.AccessLevel;
import lombok.Getter;

/**
 * One full set of answers to the choices a farmer could reasonably make differently: which
 * crops to plant, how the herb rotation ranks its seeds, what the Farming Guild is kept for,
 * and which run goes first.
 *
 * <p>Holds opinions only. Game facts (levels, unlocks, growth times, diary bonuses) are read
 * from the game or the catalogue, never from here.
 *
 * <p>Two kinds of opinion live here. The ones the player can change are the
 * {@link #preferences() settings}, which "Reset to the default route" puts back. The rest
 * are fixed; the planner reads each from {@link #DEFAULT}.
 */
@Getter
public final class Preset {

    /**
     * The Farming level from which the default route includes herb runs. A real level, not
     * a boosted one: Larry reads base levels only.
     */
    public static final int HERB_RUN_LEVEL = 82;

    /** The default route, which an untouched install runs on. */
    public static final Preset DEFAULT = new Preset(Tables.byName("/com/larryfarming/preset.tsv", 2));

    /**
     * Every herb, best first. Ranked by experience per seed including the time to gather
     * secondaries, so it disagrees with level order: snapdragon sits below irit.
     */
    private final List<Crop> herbRanking;

    /**
     * Herbs ranked at or above the cutoff that still start unticked. Torstol tops the
     * ranking but is hard to gather in bulk, so it is kept for hard contracts.
     */
    private final Set<Crop> herbsKeptForContracts;

    /** The worst herb worth planting: it and every herb ranked above it start ticked. */
    private final Crop herbCutoff;

    /**
     * How many good seeds a herb run plants, in the patches with the best yield bonus. The
     * other patches take the worst seed at or above the cutoff, so the scarce seeds go
     * where they yield most.
     */
    private final int goodSeedsPerRun;

    /**
     * Whether the Farming Guild herb patch is kept out of herb runs. Its yield bonus goes to
     * contracts instead, which pay in seed packs.
     *
     * <p>Needs no level gate. The patch stands in the guild's west wing, which opens at 65
     * Farming (62 with a boost), and every herb contract also needs 65, boostable. So no
     * player reaches the patch before the contracts can use it.
     */
    private final boolean guildHerbPatchReserved;

    /**
     * Whether a ticked magic goes only to the Falador tree patch once the elite Falador
     * diary protects it, while every other tree patch takes the ticked trees below magic.
     * Before the diary a ticked magic is planted at every tree patch.
     */
    private final boolean magicAtFaladorWithEliteDiary;

    /** The tree-family crops ticked: regular, fruit and hardwood trees. */
    private final Set<Crop> treesOn;

    /** The crops switched on outright: the extras a run plants in passing, and whole runs. */
    private final Set<Crop> switchedOn;

    /** Every run, most valuable first, for ordering runs that are due together. */
    private final List<RunId> runPriority;

    /**
     * The player's settings as this preset sets them, filled once while the preset is read.
     * Each value is documented on its {@link FarmingPreferences} field.
     *
     * <p>Private and never handed out: a setter called on it would change the defaults
     * every later {@link #preferences()} builds. Holding the builder does not initialise
     * {@link FarmingPreferences}, whose {@code HERB_CHOICES} reads {@link #DEFAULT}.
     */
    @Getter(AccessLevel.NONE)
    private final FarmingPreferences.FarmingPreferencesBuilder settings;

    /** Read from the preset table, one row per field, keyed by the field's name. */
    private Preset(Tables.Named row) {
        herbRanking = row.of("herbRanking").constants(Crop.class, 1);
        herbsKeptForContracts = setOf(row.of("herbsKeptForContracts"), Crop.class);
        herbCutoff = row.of("herbCutoff").constant(Crop.class, 1);
        goodSeedsPerRun = row.of("goodSeedsPerRun").integer(1);
        guildHerbPatchReserved = row.of("guildHerbPatchReserved").flag(1, YES);
        magicAtFaladorWithEliteDiary = row.of("magicAtFaladorWithEliteDiary").flag(1, YES);
        treesOn = setOf(row.of("treesOn"), Crop.class);
        switchedOn = setOf(row.of("switchedOn"), Crop.class);
        runPriority = row.of("runPriority").constants(RunId.class, 1);
        if (runPriority.size() != RunId.values().length || !EnumSet.copyOf(runPriority).equals(EnumSet.allOf(RunId.class))) {
            throw row.of("runPriority").error("run priority must name every run once");
        }
        if (!herbRanking.contains(herbCutoff)) {
            throw row.of("herbCutoff").error("herb cutoff " + herbCutoff + " is unranked");
        }
        EnumSet<Crop> on = EnumSet.copyOf(herbsOn());
        on.addAll(treesOn);
        on.addAll(switchedOn);
        String sites = row.of("sitesOff").text(1);
        settings = new FarmingPreferences.FarmingPreferencesBuilder().enabled(on)
                .picksFruitInPassing(row.of("picksFruitInPassing").flag(1, YES))
                .travelOff(setOf(row.of("travelOff"), TravelMethod.class))
                .sitesOff(sites.isEmpty() ? Set.of() : Set.of(sites.split(" ")))
                .houseDeclared(setOf(row.of("houseDeclared"), Capability.class))
                .favouriteHerb(row.of("favouriteHerb").optionalConstant(Crop.class, 1))
                .plantsBestSeedsEverywhere(row.of("goodSeedsInEveryPatch").flag(1, YES))
                .herbRunFirst(row.of("herbRunFirst").flag(1, YES))
                .waitsForEveryPatch(row.of("waitsForEveryPatch").flag(1, YES))
                .fruitTreesWaitForSaplings(row.of("fruitTreesWaitForSaplings").flag(1, YES))
                .replantsGrownTrees(row.of("replantsGrownTrees").flag(1, YES))
                .herbRunsWaitForLevel(row.of("herbRunsWaitForLevel").flag(1, YES))
                .compostsWithFertileSoil(row.of("compostsWithFertileSoil").flag(1, YES))
                .makeCompostBelow(row.of("makeCompostBelow").integer(1))
                .stopCompostAt(row.of("stopCompostAt").integer(1))
                .picks(picks(row.of("patchPicks")))
                .forCompost(forCompost(row.of("forCompost")));
        row.requireAllRead();
    }

    /** SITE:CROP pairs separated by single spaces, each a crop the site's patch grows. */
    static Map<String, Crop> picks(Tables.Row row) {
        Map<String, Crop> picks = new HashMap<>();
        for (String pair : row.text(1).split(" ")) {
            String[] parts = pair.split(":");
            Crop crop;
            try {
                crop = Crop.valueOf(parts[1]);
            } catch (IllegalArgumentException | ArrayIndexOutOfBoundsException e) {
                throw row.error("a pick is SITE:CROP, not " + pair);
            }
            PatchPick pick = pickAt(row, parts[0]);
            if (!CropData.plantableIn(pick.getPatchType()).contains(crop)) {
                throw row.error(parts[0] + " can't grow " + crop);
            }
            picks.put(parts[0], crop);
        }
        return Collections.unmodifiableMap(picks);
    }

    /** Sites separated by single spaces, each an allotment with a pick. */
    static Set<String> forCompost(Tables.Row row) {
        String sites = row.text(1);
        if (sites.isEmpty()) {
            return Set.of();
        }
        for (String site : sites.split(" ")) {
            if (pickAt(row, site).getCompostKey() == null) {
                throw row.error(site + " has no compost bin beside it");
            }
        }
        return Set.of(sites.split(" "));
    }

    /** The pick at this site, or an error naming the row when the site has none. */
    private static PatchPick pickAt(Tables.Row row, String site) {
        PatchPick pick = FarmingKeys.PICKS.get(site);
        if (pick == null) {
            throw row.error("no patch at " + site + " has a pick");
        }
        return pick;
    }

    /** A switch's value in the preset table; the other is {@link Tables#EMPTY}. */
    private static final String YES = "yes";

    private static <E extends Enum<E>> Set<E> setOf(Tables.Row row, Class<E> type) {
        EnumSet<E> set = EnumSet.noneOf(type);
        set.addAll(row.constants(type, 1));
        return Collections.unmodifiableSet(set);
    }

    /** The herbs ticked: the cutoff and every herb ranked above it but those kept for contracts. */
    public Set<Crop> herbsOn() {
        EnumSet<Crop> on = EnumSet.copyOf(herbRanking.subList(0, herbRanking.indexOf(herbCutoff) + 1));
        on.removeAll(herbsKeptForContracts);
        return Collections.unmodifiableSet(on);
    }

    /** Where this run sorts among runs due together; lower goes first, starting at 1. */
    public int priorityOf(RunId run) {
        return runPriority.indexOf(run) + 1;
    }

    /**
     * Where this run sorts with the herb run lifted to the top, or not: the herb run takes
     * 1 and every run it passed moves down one, so the rest keep their order.
     */
    public int priorityOf(RunId run, boolean herbsFirst) {
        int preset = priorityOf(run);
        if (!herbsFirst) {
            return preset;
        }
        if (run == RunId.HERB) {
            return 1;
        }
        return preset < priorityOf(RunId.HERB) ? preset + 1 : preset;
    }

    /** The settings this preset sets, as the planner reads them. */
    public FarmingPreferences preferences() {
        return settings.build();
    }
}

package com.larryfarming.farming.model;

import java.util.*;
import java.util.function.Function;
import lombok.*;

/**
 * What a single travel rung asks of the player, as a boolean expression. Usually one
 * {@link Capability}, but some rungs need an "or" inside an "and": "Royal seed pod/slayer
 * ring to Grand Tree spirit tree to Port Sarim" needs either of two items <em>and</em> a
 * grown spirit tree.
 *
 * <p>A rung can also depend on having reached another stop. The Taverley chain
 * ends with "run from Falador tree", which is free after the Falador patch and impossible
 * if it was skipped ({@link Kind#REACHED_PATCH}).
 *
 * <p>This type carries no evaluation. Answering it needs three-valued logic, where
 * {@code any(HAVE, UNKNOWN)} is HAVE but {@code all(HAVE, UNKNOWN)} is UNKNOWN, and the
 * resolver owns that logic.
 */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class Requirement {

    public enum Kind {
        CAPABILITY,
        /**
         * Being able to reach a place, by whatever means this player has. Distinct from a
         * capability because the means depend on the open spellbook: the same arrival is a
         * cast on one book and a tablet on another.
         */
        DESTINATION,
        /**
         * Depends on having already worked another stop: within the run when a run is
         * walked alone, or in any family when a combined trip is re-checked in circuit
         * order.
         */
        REACHED_PATCH,
        /**
         * Depends on where the game reports the player standing now, unlike
         * {@link #REACHED_PATCH}, which depends on where the plan routed them. Never
         * {@code UNKNOWN}: an unread position is a no. See {@link Zone}.
         */
        STANDING_IN,
        /** Every part must hold. An empty ALL is vacuously satisfied. */
        ALL,
        /** At least one part must hold. An empty ANY can never be satisfied. */
        ANY
    }

    Kind kind;

    /** Set only when {@link #kind} is {@link Kind#CAPABILITY}. */
    Capability capability;

    /** Set only when {@link #kind} is {@link Kind#DESTINATION}. */
    Destination destination;

    /** Set only when {@link #kind} is {@link Kind#REACHED_PATCH}. */
    PatchRef patch;

    /** Set only when {@link #kind} is {@link Kind#STANDING_IN}. */
    Zone zone;

    /**
     * True on a {@link Kind#DESTINATION} reached by Spellbook Swap and that place's spell
     * from another book. Only this kind of rung offers the swap.
     */
    boolean bySwap;

    /** Immutable; empty unless {@link #kind} is {@link Kind#ALL} or {@link Kind#ANY}. */
    List<Requirement> parts;

    /**
     * A leaf holding exactly one value, the one its kind names.
     *
     * @throws IllegalArgumentException when that value is null, so a null leaf never reaches
     *     the capability set
     */
    private static Requirement leaf(Kind kind, Capability capability, Destination destination, PatchRef patch, Zone zone,
            boolean bySwap) {
        if (capability == null && destination == null && patch == null && zone == null) {
            throw new IllegalArgumentException("a " + kind + " requirement needs a value");
        }
        return new Requirement(kind, capability, destination, patch, zone, bySwap, List.of());
    }

    private static Requirement of(Kind kind, List<Requirement> parts) {
        return new Requirement(kind, null, null, null, null, false, parts);
    }

    public static Requirement cap(Capability capability) {
        return leaf(Kind.CAPABILITY, capability, null, null, null, false);
    }

    /** Being able to get to a place, however this player gets there. */
    public static Requirement reach(Destination destination) {
        return leaf(Kind.DESTINATION, null, destination, null, null, false);
    }

    /**
     * Being able to get to a place by Spellbook Swap, then its spell from another book.
     * Never answered by a tablet or by a spell on the open book; a rung beside it asks for
     * those.
     */
    public static Requirement reachBySwap(Destination destination) {
        return leaf(Kind.DESTINATION, null, destination, null, null, true);
    }

    public static Requirement reachedPatch(PatchRef patch) {
        return leaf(Kind.REACHED_PATCH, null, null, patch, null, false);
    }

    /**
     * Being somewhere already, as the game reports it.
     *
     * <p>Used on a rung that is free only from that ground, such as the Stronghold's spirit
     * tree for a player standing beside it. Rank the rung by its real cost, not at the top
     * for being free: a whistle still beats a short walk to a tree.
     */
    public static Requirement standingIn(Zone zone) {
        return leaf(Kind.STANDING_IN, null, null, null, zone, false);
    }

    public static Requirement all(Requirement... parts) {
        return of(Kind.ALL, List.of(parts));
    }

    public static Requirement any(Requirement... parts) {
        return of(Kind.ANY, List.of(parts));
    }

    /** A rung that asks for nothing — the floor of a chain with no skip. */
    public static Requirement none() {
        return of(Kind.ALL, List.of());
    }

    /**
     * This expression with every occurrence of {@code part} read as held, for a player the
     * trip has already put where {@code part} would take them. Returns this same object when
     * {@code part} does not occur.
     */
    public Requirement granting(Requirement part) {
        if (equals(part)) {
            return none();
        }
        if (parts.isEmpty()) {
            return this;
        }
        List<Requirement> granted = new ArrayList<>(parts.size());
        boolean changed = false;
        for (Requirement each : parts) {
            Requirement after = each.granting(part);
            changed |= after != each;
            granted.add(after);
        }
        return changed ? new Requirement(kind, capability, destination, patch, zone, bySwap, List.copyOf(granted)) : this;
    }

    /** Whether this expression, or any part of it, is exactly {@code other}. */
    public boolean contains(Requirement other) {
        if (equals(other)) {
            return true;
        }
        for (Requirement part : parts) {
            if (part.contains(other)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Every capability mentioned anywhere in this expression.
     */
    public Set<Capability> leafCapabilities() {
        return leaves(Kind.CAPABILITY, Requirement::getCapability);
    }

    /**
     * Every patch this expression asks the player to have already worked. These rungs start
     * where the trip has already put the player, which makes them free.
     */
    public Set<PatchRef> leafPatches() {
        return leaves(Kind.REACHED_PATCH, Requirement::getPatch);
    }

    /** What every leaf of this kind anywhere in this expression holds, first found first. */
    public <T> Set<T> leaves(Kind leafKind, Function<Requirement, T> value) {
        Set<T> found = new LinkedHashSet<>();
        collect(leafKind, value, found);
        return Collections.unmodifiableSet(found);
    }

    private <T> void collect(Kind leafKind, Function<Requirement, T> value, Set<T> into) {
        if (kind == leafKind) {
            into.add(value.apply(this));
            return;
        }
        for (Requirement part : parts) {
            part.collect(leafKind, value, into);
        }
    }

    /**
     * Whether anything in here can be answered from where the player is standing — either
     * a zone named outright, or a place whose ground is known.
     *
     * <p>Answers what the zone and destination leaves answer together, without allocating,
     * because the planner calls this for every rung on every snapshot.
     */
    public boolean readableFromPosition() {
        if (kind == Kind.STANDING_IN) {
            return true;
        }
        if (kind == Kind.DESTINATION) {
            return destination.getZone() != null;
        }
        for (Requirement part : parts) {
            if (part.readableFromPosition()) {
                return true;
            }
        }
        return false;
    }

    /** True for {@link #none()} — a rung every player can take. */
    public boolean isUnconditional() {
        return kind == Kind.ALL && parts.isEmpty();
    }
}

package com.larryfarming.farming.model;

import java.util.List;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The repeatable farming activities.
 *
 * <p>Tree running is four separate runs. Tree patches have no single order: they are
 * grouped by category, each with its own travel chains. The scheduler
 * combines runs that fall due together.
 */
@Getter
@RequiredArgsConstructor
public enum RunId {

    HARDWOOD("Hardwood run", 6332),       // Mahogany logs
    CONTRACT("Farming contract", 22993),  // Seed pack
    HESPORI("Hespori", 22875),            // Hespori seed
    ANIMA("Anima plant", 22881),          // Attas seed
    CALQUAT("Calquat run", 5980),         // Calquat fruit
    FRUIT_TREE("Fruit tree run", 5972),   // Papaya fruit
    HERB("Herb run", 207),                // Grimy ranarr weed
    REGULAR_TREE("Tree run", 1515),       // Yew logs
    SEAWEED("Seaweed run", 21504);        // Giant seaweed

    /**
     * The order the side panel lists the runs in, fixed so no row moves when a run comes
     * due or is switched off. Display only: {@link #getPriority()} still orders the planning.
     */
    public static final List<RunId> DISPLAY_ORDER = List.of(HERB, REGULAR_TREE, FRUIT_TREE,
            HARDWOOD, CALQUAT, SEAWEED, HESPORI, ANIMA, CONTRACT);

    private final String displayName;

    /**
     * The item that stands for this run, for the infobox and the run list: one fixed piece
     * of what it harvests, whatever the player has ticked. Seed piles all look alike in a
     * list, and produce does not. Hespori keeps its seed, which is the one sprite players
     * know it by, and the anima plant shows the Attas seed. The contract shows the seed pack
     * it pays in. Ids come from the game's item table ({@code gameval.ItemID}), unnoted forms
     * throughout.
     */
    private final int iconItemId;

    /**
     * Lower sorts first when several runs are due at once. Follows each run's value, not
     * which timer expired first, as {@link Preset#getRunPriority()} ranks it. The player's
     * own order, which may lead with the herb run, is {@link FarmingPreferences#priorityOf}.
     */
    public int getPriority() {
        return Preset.DEFAULT.priorityOf(this);
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.engine.farming.*;
import java.util.ArrayList;
import java.util.List;
import lombok.*;

/**
 * One stop on a run: somewhere the player travels to, and what they do once there.
 *
 * <p>A stop is a visit, not a patch. Fossil Island's three hardwood patches are one stop
 * over three {@link PatchRef}s. Conversely, Weiss and Trollheim share one travel chain but
 * sit apart in the Lunar run's order, so they are two stops holding the same chain.
 *
 * <p>Stops keep the default route's order, which is already travel-optimised.
 */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class RunStop {

    /**
     * What happens when the chain runs out of rungs the player can take.
     *
     * <p>A chain ends one of three ways. Most end in an explicit "skip patch". A few say
     * no alternative exists, so a player who cannot take the route is missing part of the
     * run. The rest say nothing, which must not be read as either of the other two.
     */
    public enum TerminalBehavior {
        /** Drop the patch this run. */
        SKIP_PATCH,
        /** No alternative exists; without it the run is incomplete. */
        NO_ALTERNATIVE,
        /** The chain states no fallback for when it runs out. */
        UNSTATED
    }

    /** An action performed at the patch, in the order a run performs them. */
    public enum StopAction {
        CHECK_HEALTH,
        HARVEST,
        DIG_UP,
        COMPOST,
        PLANT,
        PAY_PROTECTION,
        KILL_HESPORI;

        /**
         * The ordinary working of a patch of this type.
         *
         * <p>Stops use these defaults unless a stop states its own technique.
         *
         * <p>Every supported type is named explicitly, so an unhandled type (a spirit tree,
         * a vinery) throws instead of getting a tree's actions.
         */
        public static List<StopAction> defaultsFor(PatchType type) {
            switch (type) {
                // Picked clean and then gone, with nothing to dig up. Mushrooms belong
                // here, not with the bushes: the patch has no regrow and goes straight to
                // weeds after the last picking.
                //
                // No PAY_PROTECTION: the wiki lists the mushroom patch "unprotectable", no
                // gardener stands by the belladonna, and InventoryDemands.collectProtection
                // reads this list to know that.
                case HERB:
                case ALLOTMENT:
                case FLOWER:
                case HOPS:
                case SEAWEED:
                case MUSHROOM:
                case BELLADONNA:
                    return List.of(HARVEST, COMPOST, PLANT);
                // A grown bush or cactus wants its health check before the first picking,
                // as a fruit tree does. Unlike a fruit tree, picking never makes it spent
                // ground (PatchWork.standsEmpty). Once grown it is dug up and replanted each
                // visit, so a fresh plant pays its check again (PatchWork.comesOut).
                //
                // Fruit trees, calquat and celastrus are checked and then picked: fruit trees
                // and calquat offer Pick-fruit once healthy, and celastrus offers Harvest.
                // Without HARVEST a grown fruit tree reads as empty ground wanting a replant.
                case BUSH:
                case CACTUS:
                case FRUIT_TREE:
                case CALQUAT:
                case CELASTRUS:
                    return List.of(CHECK_HEALTH, HARVEST, DIG_UP, COMPOST, PLANT);
                case HESPORI:
                    return List.of(KILL_HESPORI, COMPOST, PLANT);
                // Nothing to pick and no disease to compost against: an anima plant is
                // planted, and cleared once it dies.
                case ANIMA:
                    return List.of(PLANT);
                // The health check pays the Farming experience. Cutting the logs is a
                // Woodcutting errand, so it is not an action here.
                case TREE:
                case HARDWOOD_TREE:
                case REDWOOD:
                    return List.of(CHECK_HEALTH, DIG_UP, COMPOST, PLANT);
                default:
                    throw new IllegalArgumentException("no default actions for a " + type + " patch");
            }
        }
    }

    /** One or more patches worked as a single visit. Never empty. */
    List<PatchRef> patches;

    /**
     * Where this stop is worked from. Two stops naming the same arrival are one visit,
     * whichever runs they belong to and whatever map regions their patches sit in. A
     * combined trip interleaves runs on this, not on region equality, which misgroups
     * Catherby and Ardougne.
     */
    Arrival arrival;

    /** Ordered best-first; the first rung the player can take is the one to use. */
    List<TravelOption> travel;

    TerminalBehavior terminal;

    List<StopAction> actions;

    /**
     * What the player needs before this stop is worth including, or null when the run's
     * own gate is the only one. Harmony Island, for example, sits in the Lunar run but
     * needs the Elite Morytania diary.
     */
    UnlockGate gate;

    /**
     * The crop this patch grows by default, or null when the run's seeds decide.
     *
     * <p>Which of the run's seeds a patch without a fixed crop gets depends on the player's
     * diaries and quests, so {@code PatchPriority} scores it at planning time.
     */
    Crop fixedCrop;

    /** Whether the player picks this patch's crop, so it has no default of its own here. */
    boolean picked;

    /**
     * Why this stop is worth weaving in rather than part of the route proper, or null
     * for an ordinary stop. Optional stops do not count toward a run's stop total.
     */
    String optionalReason;

    /**
     * Visit this stop on every nth run, for the default crop. Normally 1. Slow crops such as
     * whiteberries use more, since their regrow does not line up with a herb run.
     */
    int everyNthRun;

    /**
     * Why this stop's patch does not, on its own, decide whether to go, or null for an
     * ordinary stop.
     *
     * <p>Used only by the farming contract, whose work is an errand with Guildmaster Jane.
     * The stop still names the guild herb patch, which the contract replants.
     *
     * <p>An errand stop is visited when its run says so. The contract's run also comes due
     * for herb patch work while the contract waits on a crop elsewhere. Everything else stays
     * patch work: the stop still plants, counts toward the bag and draws seeds from the
     * rotation.
     */
    String errandReason;

    /**
     * What the player needs before this patch is theirs to work at all, or null when
     * anyone who gets there can farm it.
     *
     * <p>The planner checks this before the travel chain. It covers a place that cannot be
     * entered (Lletya, before Mourning's End Part I) and a patch that cannot be farmed
     * (Weiss, before the fire of nourishment).
     */
    Capability accessGate;

    /** The patch that identifies this stop; the first when a visit works several. */
    public PatchRef primaryPatch() {
        return patches.get(0);
    }

    /**
     * The same stop with its rungs in another order, as {@link RungOrder} ranks them.
     *
     * @throws IllegalArgumentException unless {@code ladder} holds exactly this stop's rungs
     */
    public RunStop withLadder(List<TravelOption> ladder) {
        List<TravelOption> left = new ArrayList<>(travel);
        boolean same = true;
        for (TravelOption rung : ladder) {
            same &= left.remove(rung);
        }
        if (!same || !left.isEmpty()) {
            throw new IllegalArgumentException("a reordered ladder may only reorder at " + primaryPatch().getLabel());
        }
        return new RunStop(patches, arrival, List.copyOf(ladder), terminal, actions, gate,
                fixedCrop, picked, optionalReason, everyNthRun, errandReason, accessGate);
    }

    /** @see #errandReason */
    public boolean isErrand() {
        return errandReason != null;
    }

    /**
     * Whether this stop names its crop, rather than leaving it to the run's seeds. The crop
     * the stop plants can still differ from the default: see
     * {@code FarmingCatalogue.cropChoices}.
     */
    public boolean isFixedCrop() {
        return fixedCrop != null || picked;
    }

    /** Whether something is planted here, as against a contract errand alone. */
    public boolean isPlanting() {
        return actions != null && actions.contains(StopAction.PLANT);
    }

    /**
     * What kind of patch this stop works, or null if the patch is unknown. The builder
     * refuses mixed patch types, so the first patch answers for all.
     */
    public PatchType patchType() {
        return primaryPatch().type();
    }

    /**
     * Whether what grows here is meant to stand rather than be harvested, so a living one is
     * a reason to leave the patch alone. Only a fruit tree keeps fruiting after a pick;
     * calquat and celastrus are used up by the harvest: a calquat goes barren after its
     * sixth fruit and is cleared with a spade.
     */
    public boolean isStandingCrop() {
        return patchType() == PatchType.FRUIT_TREE;
    }

    public boolean isOptional() {
        return optionalReason != null;
    }

    public static Builder builder(PatchRef... patches) {
        return new Builder(patches);
    }

    /**
     * Hand-written rather than Lombok's so it can derive the action list from the patch
     * type and reject a stop that does not hold together.
     */
    public static final class Builder {

        private final List<PatchRef> patches;
        private Arrival arrival;
        private final List<TravelOption> travel = new ArrayList<>();
        private TerminalBehavior terminal;
        private List<StopAction> actions;
        private UnlockGate gate;
        private Crop fixedCrop;
        private boolean picked;
        private String optionalReason;
        private String errandReason;
        private int everyNthRun = 1;
        private Capability accessGate;

        private Builder(PatchRef... patches) {
            if (patches.length == 0) {
                throw new IllegalArgumentException("a stop must name at least one patch");
            }
            this.patches = List.of(patches);
        }

        /** Where the stop is worked from. Required. */
        public Builder at(Arrival arrival) {
            this.arrival = arrival;
            return this;
        }

        /** The stop's route, every rung in ranking order, each already carrying its figures. */
        public Builder chain(List<TravelOption> shared) {
            for (TravelOption option : shared) {
                add(option);
            }
            return this;
        }

        private Builder add(TravelOption option) {
            // A destination rung supplies its own opening clause once the teleport is
            // chosen, so an empty instruction is normal there.
            if (option.getDestination() == null && (option.getInstruction() == null || option.getInstruction().isBlank())) {
                throw new IllegalArgumentException("a route needs an instruction at " + patches.get(0).getLabel());
            }
            travel.add(option);
            return this;
        }

        public Builder skipIfUnreachable() {
            this.terminal = TerminalBehavior.SKIP_PATCH;
            return this;
        }

        public Builder noAlternative() {
            this.terminal = TerminalBehavior.NO_ALTERNATIVE;
            return this;
        }

        public Builder noFallbackGiven() {
            this.terminal = TerminalBehavior.UNSTATED;
            return this;
        }

        public Builder actions(StopAction... actions) {
            this.actions = List.of(actions);
            return this;
        }

        /** What the player needs before the place is somewhere they can go at all. */
        public Builder accessGate(Capability capability) {
            this.accessGate = capability;
            return this;
        }

        public Builder gate(UnlockGate gate) {
            this.gate = gate;
            return this;
        }

        public Builder plants(Crop crop) {
            this.fixedCrop = crop;
            return this;
        }

        public Builder picked() {
            this.picked = true;
            return this;
        }

        public Builder optional(String reason) {
            this.optionalReason = reason;
            return this;
        }

        /** @see RunStop#errandReason */
        public Builder errand(String reason) {
            this.errandReason = reason;
            return this;
        }

        public Builder everyNthRun(int n) {
            if (n < 1) {
                throw new IllegalArgumentException("a stop cannot be visited every " + n + " runs");
            }
            this.everyNthRun = n;
            return this;
        }

        public RunStop build() {
            PatchType type = resolvePatchType();
            if (arrival == null) {
                throw new IllegalStateException("no arrival named for " + patches.get(0).getLabel());
            }
            if (travel.isEmpty()) {
                throw new IllegalStateException("no way to reach " + patches.get(0).getLabel());
            }
            if (terminal == null) {
                throw new IllegalStateException("unstated fallback behaviour for " + patches.get(0).getLabel());
            }
            // A chain anyone can complete never reaches its terminal, so a stated terminal
            // on one is a catalogue error.
            if (terminal != TerminalBehavior.UNSTATED) {
                for (TravelOption option : travel) {
                    if (option.getRequires().isUnconditional()) {
                        throw new IllegalStateException(patches.get(0).getLabel() + " can always be reached, so it "
                                        + "never falls through to " + terminal);
                    }
                }
            }
            List<StopAction> resolved = actions != null ? actions : StopAction.defaultsFor(type);
            return new RunStop(patches, arrival, List.copyOf(travel), terminal, resolved, gate, fixedCrop, picked, optionalReason, everyNthRun,
                    errandReason, accessGate);
        }

        /**
         * The patch type shared by every patch in this visit. Throws on a mix, since one
         * visit needs one action list.
         */
        private PatchType resolvePatchType() {
            PatchType shared = null;
            for (PatchRef patch : patches) {
                FarmingWorldMap.PatchDef def = patch.resolve();
                if (def == null) {
                    throw new IllegalStateException("unknown patch " + patch.getLabel());
                }
                if (shared == null) {
                    shared = def.getType();
                } else if (shared != def.getType()) {
                    throw new IllegalStateException("one visit mixes " + shared + " and "
                            + def.getType() + " patches at " + patches.get(0).getLabel());
                }
            }
            return shared;
        }
    }
}

