package com.larryfarming.farming.model;

import java.util.*;

/**
 * The order a ladder's rungs are tried in: fewest walked tiles first, over the whole route as
 * the player takes it.
 *
 * <ul>
 * <li>Rungs within {@link #TIE_BAND} tiles of the shortest walk not yet placed are tied, and
 * a tie goes to the cheaper rung: free, then a charge, then a consumable. Equal cost keeps
 * the order the ladder lists them in.</li>
 * <li>A rung with no figure keeps its place: it follows the last of the measured rungs listed
 * above it, or leads when none is.</li>
 * <li>A floor, which starts wherever the player is, comes last.</li>
 * </ul>
 *
 * <p>The tie band is anchored on the shortest walk in it rather than chained from rung to
 * rung, so a tie never spans more than the band, and which rungs tie depends on their walks
 * alone, not on the order they are listed in. This is a grouping, not a comparator: two
 * rungs within the band of each other can still fall in different ties.
 */
public final class RungOrder {

    /** Walks this many tiles apart or fewer are tied. */
    public static final int TIE_BAND = 3;

    private RungOrder() {
    }

    /**
     * What ranking reads from one rung, by its index in the ladder.
     *
     * <p>A walk is tiles, {@link TravelOption#UNMEASURED} or {@link TravelOption#FLOOR}; a
     * measured walk has a cost.
     */
    public interface Figures {
        int walk(int rung);

        TravelOption.Cost cost(int rung);
    }

    /** The ladder ranked by the figures given, which may differ from the rungs' own. */
    public static List<TravelOption> rank(List<TravelOption> ladder, Figures figures) {
        int[] order = order(ladder.size(), figures);
        List<TravelOption> ranked = new ArrayList<>(order.length);
        for (int index : order) {
            ranked.add(ladder.get(index));
        }
        return ranked;
    }

    /** The indices of {@code size} rungs in ranked order. */
    public static int[] order(int size, Figures figures) {
        int[] walks = new int[size];
        List<Integer> measured = new ArrayList<>(size);
        for (int i = 0; i < size; i++) {
            walks[i] = figures.walk(i);
            if (walks[i] != TravelOption.UNMEASURED && walks[i] != TravelOption.FLOOR) {
                measured.add(i);
            }
        }
        measured.sort(Comparator.<Integer>comparingInt(i -> walks[i]).thenComparingInt(i -> i));
        List<Integer> ranked = new ArrayList<>(size);
        int from = 0;
        while (from < measured.size()) {
            int anchor = walks[measured.get(from)];
            int to = from;
            while (to < measured.size() && walks[measured.get(to)] - anchor <= TIE_BAND) {
                to++;
            }
            List<Integer> tied = new ArrayList<>(measured.subList(from, to));
            tied.sort(Comparator.<Integer>comparingInt(i -> figures.cost(i).ordinal()).thenComparingInt(i -> i));
            ranked.addAll(tied);
            from = to;
        }
        return withTheRestPlaced(ranked, walks);
    }

    /**
     * The measured rungs in rank, with each unmeasured rung after the last-ranked measured
     * rung listed above it, and the floors at the end.
     */
    private static int[] withTheRestPlaced(List<Integer> ranked, int[] walks) {
        int size = walks.length;
        int[] rankOf = new int[size];
        for (int position = 0; position < ranked.size(); position++) {
            rankOf[ranked.get(position)] = position;
        }
        // Slot 0 holds the rungs leading the ladder; slot p + 1 those after ranked position p.
        List<List<Integer>> after = new ArrayList<>(ranked.size() + 1);
        for (int i = 0; i <= ranked.size(); i++) {
            after.add(new ArrayList<>());
        }
        List<Integer> floors = new ArrayList<>();
        int lastAbove = -1;
        for (int i = 0; i < size; i++) {
            if (walks[i] == TravelOption.FLOOR) {
                floors.add(i);
            } else if (walks[i] == TravelOption.UNMEASURED) {
                after.get(lastAbove + 1).add(i);
            } else {
                lastAbove = Math.max(lastAbove, rankOf[i]);
            }
        }
        int[] order = new int[size];
        int next = 0;
        for (int index : after.get(0)) {
            order[next++] = index;
        }
        for (int position = 0; position < ranked.size(); position++) {
            order[next++] = ranked.get(position);
            for (int index : after.get(position + 1)) {
                order[next++] = index;
            }
        }
        for (int index : floors) {
            order[next++] = index;
        }
        return order;
    }

    /** The cost of a route made of two parts: the dearer of the two. */
    public static TravelOption.Cost dearer(TravelOption.Cost a, TravelOption.Cost b) {
        if (a == null) {
            return b;
        }
        if (b == null) {
            return a;
        }
        return a.compareTo(b) >= 0 ? a : b;
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.engine.farming.Crop;
import java.util.List;
import lombok.*;

/**
 * How the herb rotation decides which herb seeds go in the ground.
 *
 * <p>The rotation plants two good seeds where diary yield bonuses apply and five or
 * six filler seeds elsewhere, walking inward from both ends of the tier list as each
 * stack runs out and restarting from the outside when the two pointers meet. The
 * tier list is in XP order, not Farming level order: snapdragon sits below irit despite
 * needing eighteen more levels.
 *
 * <p>The Farming Guild herb patch stays out of herb runs so its yield goes to contracts.
 * Torstol tops the list but is a tick like any other herb, unticked by default.
 */
@Value
@Builder
public class SeedPolicy {

    /**
     * A crop that replaces the usual choice at one patch once a diary tier is done. For
     * example, Falador Elite makes the Falador tree patch disease-free, so it takes magic
     * saplings while other patches keep yew.
     */
    @Value
    public static class DiaryOverride {
        String diaryArea;
        String diaryTier;
        PatchRef patch;
        Crop crop;
    }

    /** Best to worst by experience. */
    @Singular("tier")
    List<Crop> herbTierList;

    @Singular("override")
    List<DiaryOverride> diaryOverrides;

    /**
     * How many good seeds a run plants. The rest of the patches take filler.
     *
     * <p>Planning chooses which patches get them per player, because each patch's yield
     * bonus (Kandarin at Catherby, Kourend at Hosidius) depends on a diary the player may
     * not have done.
     */
    int goodSeedsPerRun;
}

package com.larryfarming.farming.model;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Which spellbook a run is written for. Herb runs are written once per book, because the
 * teleports change the fallback chains; every book walks the same circuit.
 */
@Getter
@RequiredArgsConstructor
public enum Spellbook {
    /** The run does not depend on a spellbook. */
    ANY("any"),
    ARCEUUS("Arceuus"),
    LUNAR("Lunar"),

    /**
     * No run is written for the standard book, but it carries most fallback teleports, so
     * castability checks need to name it.
     */
    STANDARD("standard");

    /** How to say this in a sentence: "you are on the Arceuus spellbook". */
    private final String displayName;
}

package com.larryfarming.farming.model;

import java.util.*;
import lombok.Getter;

/**
 * One way of reaching a {@link Destination}: a spell on a particular spellbook, or a
 * tablet that works from any of them.
 *
 * <p>A spell costs only runes but needs the right book open. A tablet is a consumable but
 * works on any book. The planner chooses between them against live state.
 *
 * <p>A third kind is a spell reached through Spellbook Swap: two casts, both paid in runes,
 * which a rung asks for by name ({@link #afterSwap}).
 */
@Getter
public final class TeleportMeans {

    public enum Kind {
        SPELL,
        TABLET
    }

    private final Kind kind;
    /** What to call this in an instruction: "Catherby Teleport", "Camelot teleport tablet". */
    private final String displayName;
    /** The book this spell lives on, or {@link Spellbook#ANY} for a tablet. */
    private final Spellbook spellbook;
    private final int magicLevel;
    /** The quest behind the spell or tablet, or null when there is none. */
    private final String questName;
    /** What one cast costs. Empty for a tablet. */
    private final Map<Rune, Integer> runes;
    /** The tablet's item ID, or 0 for a spell. */
    private final int itemId;
    /** The spell's icon in the game's spellbook, or 0 for a tablet. */
    private final int spriteId;
    /** The spell cast after the swap, or null when this is not a swap. */
    private final TeleportMeans swappedSpell;

    private TeleportMeans(Kind kind, String displayName, Spellbook spellbook, int magicLevel,
            String questName, Map<Rune, Integer> runes, int itemId, int spriteId, TeleportMeans swappedSpell) {
        this.kind = kind;
        this.displayName = displayName;
        this.spellbook = spellbook;
        this.magicLevel = magicLevel;
        this.questName = questName;
        this.runes = Collections.unmodifiableMap(runes);
        this.itemId = itemId;
        this.spriteId = spriteId;
        this.swappedSpell = swappedSpell;
    }

    /**
     * A teleport spell.
     *
     * @param questName the quest it is locked behind, or null when only the level gates it
     * @param spriteId  the spell's icon in the game's spellbook
     * @param runes     what one cast costs, each rune with its count
     */
    public static TeleportMeans spell(String displayName, Spellbook spellbook, int magicLevel,
            String questName, int spriteId, Map<Rune, Integer> runes) {
        if (runes.isEmpty()) {
            throw new IllegalArgumentException(displayName + ": a teleport spell costs runes");
        }
        return new TeleportMeans(Kind.SPELL, displayName, spellbook, magicLevel, questName, new EnumMap<>(runes), 0, spriteId, null);
    }

    /**
     * A teleport tablet, usable on any spellbook once a quest is finished. Breaking one asks
     * for no Magic level.
     *
     * @param questName the quest the tablet refuses to work without, or null for none
     */
    public static TeleportMeans tablet(String displayName, int itemId, String questName) {
        return new TeleportMeans(Kind.TABLET, displayName, Spellbook.ANY, 0, questName, new EnumMap<>(Rune.class), itemId, 0, null);
    }

    /**
     * Two casts as one way there: {@code swap}, which opens another book for a single
     * spell, then {@code spell} from that book.
     *
     * <p>Reads as the swap for its book, level, quest and icon, since the player casts it
     * first and from the book they are on. The runes are both casts' together, so the bag
     * packs them as one line each. {@link #getSwappedSpell()} keeps the second spell's own
     * level and quest.
     */
    public static TeleportMeans afterSwap(TeleportMeans swap, TeleportMeans spell) {
        if (!swap.isSpell() || !spell.isSpell() || swap.isSwap() || spell.isSwap()) {
            throw new IllegalArgumentException("a swap joins two plain spells");
        }
        if (swap.getSpellbook() == spell.getSpellbook()) {
            throw new IllegalArgumentException(spell.getDisplayName() + " is on the book the swap is cast from");
        }
        Map<Rune, Integer> both = new EnumMap<>(Rune.class);
        both.putAll(swap.getRunes());
        spell.getRunes().forEach((rune, count) -> both.merge(rune, count, Integer::sum));
        return new TeleportMeans(Kind.SPELL, swap.getDisplayName() + ", then " + spell.getDisplayName(),
                swap.getSpellbook(), swap.getMagicLevel(), swap.getQuestName(), both, 0, swap.getSpriteId(), spell);
    }

    public boolean isSpell() {
        return kind == Kind.SPELL;
    }

    public boolean isTablet() {
        return kind == Kind.TABLET;
    }

    /** Whether this is a swap followed by a spell from another book; see {@link #afterSwap}. */
    public boolean isSwap() {
        return swappedSpell != null;
    }
}

package com.larryfarming.farming.model;

import com.larryfarming.data.Tables;
import java.util.*;
import lombok.Getter;

/**
 * A way of travelling the player can switch off in the side panel: one teleport item, a
 * family of them, or a group of spells or tablets.
 *
 * <p>Switched off, the method is never used, wherever a route would take it: a switched-off
 * quest cape reaches neither a fairy ring nor anywhere else. A ladder then falls to its next
 * rung, and a stop whose only rungs need the method is skipped with the switch named.
 *
 * <p>Each method covers a group of {@link Capability capabilities}, and three cover
 * teleports that are a place rather than an item: every teleport tablet, the Salve graveyard
 * tablet alone, and Spellbook Swap. Switching tablets off leaves the spells to the same
 * places.
 *
 * <p>Networks the player walks onto (spirit trees, gliders, charter ships, minecarts) and
 * the house's own location are not methods: nothing is spent on them.
 *
 * <p>Each method's key, names, group and capabilities come from the travel methods table.
 * The panel draws the squares under their {@link Group} captions, each group in declared
 * order.
 */
public enum TravelMethod {
    RING_OF_WEALTH,
    AMULET_OF_GLORY,
    GAMES_NECKLACE,
    COMBAT_BRACELET,
    SKILLS_NECKLACE,
    RING_OF_DUELING,
    RING_OF_THE_ELEMENTS,
    DIGSITE_PENDANT,
    NECKLACE_OF_PASSAGE,
    SLAYER_RING,
    XERICS_TALISMAN,
    KHAREDSTS_MEMOIRS,
    PENDANT_OF_ATES,
    SAILORS_AMULET,
    TELEPORT_CRYSTAL,
    CHRONICLE,
    QUETZAL_WHISTLE,
    ROYAL_SEED_POD,
    ECTOPHIAL,
    BASALT,
    MOKHAIOTL_WAYSTONE,
    EXPLORERS_RING,
    ARDOUGNE_CLOAK,
    DIARY_CAPE,
    QUEST_CAPE,
    SKILL_CAPES,
    CONSTRUCTION_CAPE,
    /** Every teleport tablet, the redirected house tab among them. The spells still count. */
    TELEPORT_TABLETS,
    /** The Salve graveyard tablet alone. The Arceuus spell still counts. */
    SALVE_GRAVEYARD_TABLETS,
    /** Spellbook Swap, and so every spell borrowed from another book for one cast. */
    SPELLBOOK_SWAP,
    HOUSE_PORTALS,
    HOUSE_FAIRY_RING;

    static {
        Rows.TABLE.requireAll(values());
    }

    private static final Map<Capability, TravelMethod> BY_CAPABILITY = byCapability();

    /** The config key that switches it, true while it may be used. */
    @Getter
    private final String key;
    /** Named for a player: "Necklace of passage". */
    @Getter
    private final String label;
    private final String inSentence;
    /** The caption the method's square sits under in the side panel. */
    @Getter
    private final Group group;
    /**
     * The capabilities this method covers, the one drawn on its square first. Empty for a
     * method that covers a place's tablet or spell rather than an item.
     */
    @Getter
    private final List<Capability> capabilities;

    TravelMethod() {
        Tables.Row row = Rows.TABLE.of(name());
        this.key = row.text(1);
        this.group = row.constant(Group.class, 2);
        this.label = row.text(3);
        this.inSentence = row.text(4);
        this.capabilities = row.constants(Capability.class, 5);
    }

    /**
     * The travel methods table, held apart so the constructors can read it; see
     * {@link Tables#byName}.
     */
    private static final class Rows {
        static final Tables.Named TABLE = Tables.byName("/com/larryfarming/travel-methods.tsv", 6);
    }

    private static Map<Capability, TravelMethod> byCapability() {
        Map<Capability, TravelMethod> map = new EnumMap<>(Capability.class);
        for (TravelMethod method : values()) {
            for (Capability capability : method.capabilities) {
                if (map.put(capability, method) != null) {
                    throw new IllegalStateException(capability + " is in two travel methods");
                }
            }
        }
        return Collections.unmodifiableMap(map);
    }

    /** The method this capability belongs to, or null when no switch covers it. */
    public static TravelMethod of(Capability capability) {
        return BY_CAPABILITY.get(capability);
    }

    /** The panel's captions over the travel squares, in the order drawn. */
    public enum Group {
        JEWELLERY("Jewellery"),
        ITEMS("Other items"),
        REWARDS("Capes and diary rewards"),
        SPELLS("Spells and tablets"),
        HOUSE("House");

        @Getter
        private final String label;

        Group(String label) {
            this.label = label;
        }
    }

    /** Why a route needing it is not taken: "you switched off the slayer ring". */
    public String switchedOffReason() {
        return "you switched off " + inSentence;
    }
}

package com.larryfarming.farming.model;

import lombok.*;

/**
 * One rung of a {@link RunStop}'s downgrade chain: a way of reaching the patch,
 * together with what it asks of the player. Chains are ordered best-first, so the
 * first rung whose requirement holds is the one to show. {@link RungOrder} ranks them.
 */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class TravelOption {

    /**
     * What {@link #getBankDetour()} and {@link #getWalk()} read when nobody has measured
     * this rung.
     */
    public static final int UNMEASURED = -1;

    /**
     * What {@link #getWalk()} reads on a floor: a route that starts from wherever the player
     * is, so no walk can be measured for it. A floor ranks last.
     */
    public static final int FLOOR = Integer.MAX_VALUE;

    /**
     * What a rung spends, which breaks a tie between rungs that walk about as far. Declared
     * cheapest first.
     */
    public enum Cost {
        /** Unlimited: a cape, a house amenity, a walk. */
        FREE,
        /** A daily allowance or charges that recharge: a ring, a necklace, a diary cloak. */
        CHARGE,
        /** Spent for good: a tablet, a spell's runes, a basalt, a log. */
        CONSUMABLE
    }

    Requirement requires;

    /**
     * What to tell the player, imperative and in game terms: "Icy basalt to Weiss".
     * Never contains item IDs. Daily limits live on the {@link Capability}, not here.
     */
    String instruction;

    /**
     * The place this rung arrives at, when the rung is written as a place rather than as
     * a particular item. Null for every other rung.
     *
     * <p>When set, the instruction is only the tail of the sentence ("then run east"). The
     * head is whichever teleport the planner picks for this account.
     */
    Destination destination;

    /** Coins this rung costs to travel, or zero when it is free. */
    @With(AccessLevel.PRIVATE)
    int fareCoins;

    /**
     * Extra tiles walked to touch a bank between landing here and reaching the patch, or
     * {@link #UNMEASURED} when the rung has no figure.
     *
     * <p>{@code landing→bank + bank→patch − landing→patch}, so zero means the bank is on the
     * route. Walked over the game's collision map, not straight-line distance: walls can
     * double the real walk.
     *
     * <p>Held on the rung, not the {@link Arrival}, because the figure depends on both the
     * landing and the patch. Rungs to one arrival land far apart, and one landing can bank
     * free on the way to one patch but not another.
     *
     * <p>A figure replaces the entry in the stop's own list rather than mutating the rung, so
     * a shared chain can carry different figures per stop.
     */
    int bankDetour;

    /**
     * Whether reaching that bank changes floor. The tile figure counts the ground floor
     * only and omits the stairs: Lumbridge measures five tiles but also climbs
     * two flights.
     */
    boolean bankUpstairs;

    /**
     * Which bank those tiles were walked to, or null when this rung has no figure.
     *
     * <p>Always set together with the figure, since a detour only means something for one
     * particular bank.
     */
    Bank bank;

    /**
     * True when the planner may take this rung only if it certainly holds, never as a guess.
     *
     * <p>For a rung whose sentence asserts something about the account. "With your house in
     * Hosidius" is wrong advice for a player housed anywhere else, so it waits for the
     * house's town to be read.
     */
    @With(AccessLevel.PRIVATE)
    boolean certainOnly;

    /**
     * True when the planner may take this rung only where the previous stop left the player
     * at its approach, as {@link #startingFrom} grants it. Anywhere else the rung is not on
     * the ladder.
     *
     * <p>For a chain whose ranking turns on where the player stands. Lunar's Morytania
     * chain ranks fairy ring ALQ above the Fenkenstrain's tablet only for a player already
     * beside a ring, so it carries the ring twice: once marked this way above the tablet,
     * and once plainly below it.
     */
    @With(AccessLevel.PRIVATE)
    boolean startOnly;

    /**
     * Tiles walked over the whole route, as the player takes it, from the first landing to
     * the patch. Teleports and rides count nothing; the walks to a fairy ring, a spirit tree,
     * a boat or a station count, and so does the walk from the last landing to the patch.
     * {@link #UNMEASURED} when the rung has no figure, {@link #FLOOR} on a floor.
     *
     * <p>A rung that asks for a way onto a network by an {@link Approach} leaves that
     * approach's walk out: it depends on which way in the player has, so the planner adds it
     * per account. A rung that leans on a patch is measured from that patch.
     */
    int walk;

    /** What this rung spends, or null when it has no walk figure. */
    Cost cost;

    /** A rung with no figures, fare or conditions yet. */
    private static TravelOption rung(Requirement requires, String instruction, Destination destination) {
        return new TravelOption(requires, instruction, destination, 0, UNMEASURED, false, null, false, false, UNMEASURED, null);
    }

    public static TravelOption via(Requirement requires, String instruction) {
        return rung(requires, instruction, null);
    }

    /**
     * A rung that gets the player to a place, however they get there.
     *
     * @param rest what to do after arriving, or "" when arriving is the whole of it
     */
    public static TravelOption to(Destination destination, String rest) {
        return rung(Requirement.reach(destination), rest, destination);
    }

    /** Arriving somewhere, plus something else that also has to hold. */
    public static TravelOption to(Destination destination, Requirement alsoNeeds, String rest) {
        return rung(Requirement.all(Requirement.reach(destination), alsoNeeds), rest, destination);
    }

    /**
     * A rung that gets the player to a place by Spellbook Swap and the place's spell from
     * another book. The planner opens the sentence with both casts: "Spellbook Swap, then
     * Harmony Island Teleport".
     *
     * <p>Rank it below the place's tablet: the swap spends its own runes and a second cast,
     * where a tablet is one click.
     *
     * @param rest what to do after arriving, or "" when arriving is the whole of it
     */
    public static TravelOption swapTo(Destination destination, String rest) {
        return rung(Requirement.reachBySwap(destination), rest, destination);
    }

    /** The same rung, offered only when it certainly holds. See {@link #isCertainOnly()}. */
    public TravelOption onlyWhenCertain() {
        return withCertainOnly(true);
    }

    /**
     * The same rung, offered only where the previous stop left the player at its approach.
     * See {@link #isStartOnly()}.
     */
    public TravelOption onlyFromAstart() {
        return withStartOnly(true);
    }

    /**
     * The same rung, with a fare to pay on the way.
     *
     * <p>The packing list carries the coins. The fare lives on the rung rather than the
     * capability because the same charter costs a different fare from each port.
     */
    public TravelOption withFare(int coins) {
        if (coins <= 0) {
            throw new IllegalArgumentException("a fare has to cost something");
        }
        return withFareCoins(coins);
    }

    /**
     * The same rung, with the walk to a bank measured.
     *
     * <p>The bank is required so every figure can be re-walked.
     *
     * @param tiles    extra tiles the bank stop costs, zero when it is on the route
     * @param upstairs true when the bank is on another floor, which the tiles do not cover
     * @param bank     the bank they were walked to
     */
    public TravelOption withBank(int tiles, boolean upstairs, Bank bank) {
        if (tiles < 0) {
            throw new IllegalArgumentException("a bank detour cannot be negative");
        }
        if (bank == null) {
            throw new IllegalArgumentException("a bank detour has to name its bank");
        }
        return new TravelOption(requires, instruction, destination, fareCoins, tiles, upstairs, bank, certainOnly, startOnly, walk, cost);
    }

    /**
     * The same rung, with its walk measured.
     *
     * @param tiles walked over the whole route; see {@link #getWalk()}
     * @param spends what the rung spends, which breaks ties
     */
    public TravelOption withWalk(int tiles, Cost spends) {
        if (tiles < 0) {
            throw new IllegalArgumentException("a walk cannot be negative");
        }
        if (spends == null) {
            throw new IllegalArgumentException("a walk figure has to say what the rung spends");
        }
        return new TravelOption(requires, instruction, destination, fareCoins, bankDetour,
                bankUpstairs, bank, certainOnly, startOnly, tiles, spends);
    }

    /** The same rung, as a floor: it starts wherever the player is, so it ranks last. */
    public TravelOption asFloor() {
        return new TravelOption(requires, instruction, destination, fareCoins, bankDetour,
                bankUpstairs, bank, certainOnly, startOnly, FLOOR, null);
    }

    /** Whether anybody has walked this rung. A floor has no figure. */
    public boolean hasWalkFigure() {
        return walk != UNMEASURED && walk != FLOOR;
    }

    /**
     * The same rung for a player the previous stop left a short walk from where
     * {@code granted} would take them: that part reads as held, so it packs nothing, and
     * the walk opens the sentence.
     *
     * <p>Returns this same rung when it does not ask for {@code granted}, or when it is
     * written as a place, whose sentence the planner opens with the teleport instead. The
     * rung it returns is never {@link #isStartOnly()}, since the start it waited for has
     * come.
     *
     * <p>The walk's tiles replace whatever the granted part would have cost to reach, so a
     * fairy ring rung started beside a ring counts the walk to it rather than an approach.
     *
     * @param walk a whole sentence, ending in ". ", that the rung's own sentence follows
     * @param tiles the walk's length, added to this rung's figure
     */
    public TravelOption startingFrom(Requirement granted, String walk, int tiles) {
        if (destination != null || !requires.contains(granted)) {
            return this;
        }
        return new TravelOption(requires.granting(granted), walk + instruction, null,
                fareCoins, bankDetour, bankUpstairs, bank, certainOnly, false, hasWalkFigure() ? this.walk + tiles : this.walk, cost);
    }

    /** Whether anybody has walked the bank from this rung. */
    public boolean hasBankFigure() {
        return bankDetour != UNMEASURED;
    }

    /**
     * The whole instruction, given the way this player is actually travelling: the
     * teleport's own name, then whatever the rung says to do on arrival.
     *
     * <p>For a player standing at the place already, the teleport is dropped and the tail
     * promoted to a sentence: "then run east to the quetzal landing site" becomes "Run east
     * to the quetzal landing site". An empty tail says the player is already there.
     *
     * <p>Takes an explicit flag rather than reading a null {@code means} as "already there":
     * {@code TeleportPlanner} also returns no means when the player's bank is unread.
     *
     * @param alreadyThere true only when the player's position is known to be the place
     */
    public String instructionFor(TeleportMeans means, boolean alreadyThere) {
        if (destination != null && alreadyThere) {
            return standingThere();
        }
        if (destination == null || means == null) {
            return instruction;
        }
        return instruction == null || instruction.isEmpty() ? means.getDisplayName() : means.getDisplayName() + ", " + instruction;
    }

    /**
     * The tail of a destination rung, read as a sentence by a player already at it.
     *
     * <p>The tail from its {@link #THEN} on is promoted. Whatever comes before describes the
     * arrival itself ("choosing the Grand Exchange, then run north-east"), which a player
     * standing there has already made. A tail with no {@link #THEN} names only the place.
     */
    private String standingThere() {
        if (instruction == null) {
            return alreadyAt();
        }
        int then = instruction.startsWith(THEN) ? 0 : instruction.indexOf(", " + THEN);
        if (then < 0) {
            return alreadyAt();
        }
        String rest = instruction.substring(then == 0 ? THEN.length() : then + 2 + THEN.length());
        return rest.isEmpty() ? alreadyAt() : Character.toUpperCase(rest.charAt(0)) + rest.substring(1);
    }

    /**
     * Names the zone, matching {@code TeleportPlanner}'s reason text. Falls back to the
     * destination when it has no zone.
     */
    private String alreadyAt() {
        return "You are already at " + (destination.getZone() != null ? destination.getZone().getDisplayName()
                        : destination.getDisplayName());
    }

    /**
     * How a destination rung's tail joins the teleport in front of it. Every catalogue rung
     * with a zoned destination leaves its tail empty or opens it with this word.
     */
    public static final String THEN = "then ";
}

package com.larryfarming.farming.model;

import com.larryfarming.model.Skill;
import lombok.Builder;
import lombok.Value;

/**
 * What has to be true before a run or stop is available, and separately, when it
 * becomes worth doing.
 *
 * <p>The two differ. Seaweed spores plant at 23 Farming, but the default route waits until
 * an Attas plant can run alongside at 76. {@link #level} holds what the game enforces and
 * {@link #recommendedFromLevel} holds what the default route advises.
 *
 * <p>Gates record the true level, never the boosted one. Recommendations are often quoted
 * as boosted numbers (a garden pie covers the difference), but the plugin reads base
 * levels only, so a gate at the boosted number would never fire. The boosted figure is
 * kept only to tell the player.
 */
@Value
@Builder
public class UnlockGate {

    /** Null when there is no skill requirement. */
    Skill skill;

    /** The real requirement, as the game enforces it. Zero when there is no skill gate. */
    int level;

    /**
     * The level from which a boost reaches {@link #level}, or zero when the requirement
     * cannot be boosted. Advisory only: never gates availability.
     */
    int boostedFromLevel;

    /**
     * The level from which the run is worth doing, or zero when that
     * is simply {@link #level}. Never gates availability.
     */
    int recommendedFromLevel;

    /** Diary area and tier, both null unless a diary tier is required. */
    String diaryArea;
    String diaryTier;

    public static UnlockGate skill(Skill skill, int level) {
        return UnlockGate.builder().skill(skill).level(level).build();
    }

    public boolean isBoostable() {
        return boostedFromLevel > 0;
    }
}

package com.larryfarming.farming.model;

import java.util.*;

/**
 * Somewhere the player can be standing, as the game reports it: a named place over a set
 * of map regions.
 *
 * <p>A {@link Destination} is where a teleport puts the player and
 * {@link Requirement.Kind#REACHED_PATCH} is where the trip has taken them. A zone is where
 * the game reports them now, whether the plan sent them or not. A player already in a zone
 * should not be asked for the teleport there, and a ride free from here should outrank
 * one that is not.
 *
 * <p>Zones use map regions (64 by 64 tiles), the resolution {@code PlayerState.getRegionId()}
 * carries. Every rung written against a zone must be true anywhere in it.
 *
 * <p>Each id comes from a tile checked against the wiki or in game, by
 * {@code regionId = (x >> 6) << 8 | (y >> 6)}, or from a walk. {@code FarmingWorldMap}'s ids
 * for a place of the same name cover where a patch cluster's varbits transmit, not where a
 * teleport lands. A missing id only leaves a rung unused. A wrong one drops a teleport from
 * the player's bag.
 */
public enum Zone {

    /**
     * Where the Civitas illa Fortis teleport lands: the landing, not the whole city.
     *
     * <p>A zone on a destination claims that arriving costs nothing, which holds only near
     * the landing. Sunrise Palace ({@code 1681,3136}) and the city's quetzal landing site,
     * where the Renu rungs after a Civitas illa Fortis cast depart ({@code 1697,3140}), both
     * fall in region 6705.
     *
     * <p>{@code FarmingWorldMap}'s six Ortus Farm ids (x 1536–1663) stop short of the palace,
     * and the farm itself is 100 tiles from the quetzal site.
     *
     * <p>The palace lands on the region's southern edge ({@code y == 3136} is its first
     * row), so the zone extends east and north along the run to Renu. The city's west bank
     * lies south-west. The zone leaves it out, because the run to Renu is not free from the
     * bank.
     */
    CIVITAS_ILLA_FORTIS("Civitas illa Fortis", 6705),

    /**
     * The Tree Gnome Stronghold, for the rung that rides its spirit tree.
     *
     * <p>Three ids, each with a tile behind it: the spirit tree {@code 2461,3444}, the tree
     * patch {@code 2436,3415} and the fruit patch {@code 2476,3446} all fall in 9781, the
     * Grand Tree in 9782, and the Slayer cave entrance in 9525.
     *
     * <p>9526 is deliberately absent despite appearing in {@code FarmingWorldMap}'s
     * registration. It covers x 2368–2431, y 3456–3519, north-west of the tree, and no rung
     * conditioned on this zone starts there.
     */
    GNOME_STRONGHOLD("the Tree Gnome Stronghold", 9781, 9782, 9525);

    private final String displayName;
    private final Set<Integer> regionIds;

    Zone(String displayName, int... regionIds) {
        if (regionIds.length == 0) {
            throw new IllegalArgumentException(displayName + ": a zone is somewhere");
        }
        this.displayName = displayName;
        Set<Integer> ids = new LinkedHashSet<>(regionIds.length * 2);
        for (int regionId : regionIds) {
            ids.add(regionId);
        }
        this.regionIds = Collections.unmodifiableSet(ids);
    }

    /**
     * Player-facing, written to sit mid-sentence with its article: "you are already at the
     * Tree Gnome Stronghold".
     */
    public String getDisplayName() {
        return displayName;
    }

    /**
     * Whether a player in this region is standing in this place.
     *
     * <p>Null answers false, unlike other unreadable state that answers {@code UNKNOWN}. A
     * false "already here" would remove a teleport from the player's bag.
     */
    public boolean covers(Integer regionId) {
        return regionId != null && regionIds.contains(regionId);
    }

    /**
     * The zone this region is in, or null when no zone covers it.
     *
     * <p>A cheap pre-check, run on every game event. A null means position cannot change
     * any answer, so a position-aware plan would equal a blind one and can be skipped.
     */
    public static Zone covering(Integer regionId) {
        for (Zone zone : values()) {
            if (zone.covers(regionId)) {
                return zone;
            }
        }
        return null;
    }
}

