package com.larryfarming.overlay;

import com.larryfarming.snapshot.FarmingRunStatus;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Comparator;
import java.util.List;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import net.runelite.api.MenuAction;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * One box naming the farming run to do next, shown only while a run is due.
 *
 * <p>It carries no idle countdown on purpose: a box that is always on screen stops being
 * read. The countdown to the next run lives in the tooltip.
 *
 * <p>The plugin adds the box when something is due and removes it when nothing is.
 */
public class FarmingAdvisorInfoBox extends InfoBox {

    /** Actionable amber, the colour this plugin's infoboxes use for "ready". */
    private static final Color COLOR_DUE = new Color(255, 200, 50);

    private final Supplier<List<FarmingRunStatus>> runs;

    // RuneLite calls getText() and getTooltip() every frame for every visible box, so both
    // strings are rebuilt only when the supplier returns a new run list. Render calls are
    // single-threaded, so no locking.
    private String textCache;
    private String tooltipCache;
    private List<FarmingRunStatus> cachedRuns;

    /**
     * @param runs supplies every run and its status, best first; the same list the
     *             side panel draws, so the two agree about what is due
     */
    public FarmingAdvisorInfoBox(BufferedImage image, Plugin plugin, Supplier<List<FarmingRunStatus>> runs) {
        super(image, plugin);
        this.runs = runs;
        // Right-clicking the box opens the side panel. Added to InfoBox's own list, which
        // must stay mutable: InfoBoxManager.addInfoBox appends its own "Detach"/"Flip"
        // entries, and an immutable list makes addInfoBox throw.
        getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_INFOBOX, MENU_OPTION, MENU_TARGET));
    }

    /** The right-click entry that opens the side panel, matched by the plugin. */
    public static final String MENU_OPTION = "View";
    public static final String MENU_TARGET = "Farming runs";

    @Override
    public String getText() {
        refreshCache();
        return textCache;
    }

    @Override
    public Color getTextColor() {
        return COLOR_DUE;
    }

    @Override
    public String getTooltip() {
        refreshCache();
        return tooltipCache;
    }

    private void refreshCache() {
        List<FarmingRunStatus> current = runs.get();
        if (current == cachedRuns && textCache != null) {
            return;
        }
        cachedRuns = current;

        List<FarmingRunStatus> due = due(current);
        if (due.isEmpty()) {
            // Reachable only in the frame before the plugin removes the box.
            textCache = "";
            tooltipCache = "Nothing due";
            return;
        }

        // A count of the other due runs, never a name. The plugin sets the icon to the top
        // run's item. An infobox is 35 pixels wide and InfoBoxComponent centres text at
        // (size - stringWidth) / 2, so text wider than the box spills out of both sides.
        textCache = due.size() == 1 ? "" : "+" + (due.size() - 1);

        StringBuilder tooltip = new StringBuilder("Farming");
        for (FarmingRunStatus run : due) {
            appendLine(tooltip, "", run, " — ");
        }
        FarmingRunStatus next = soonest(current);
        if (next != null) {
            appendLine(tooltip, "Next: ", next, " ");
        }
        tooltipCache = tooltip.toString();
    }

    /** A tooltip line: the run's name, then its detail after {@code gap} when it has one. */
    private static void appendLine(StringBuilder tooltip, String lead, FarmingRunStatus run, String gap) {
        tooltip.append("</br>").append(lead).append(run.getRunName());
        if (run.getDetail() != null && !run.getDetail().isEmpty()) {
            tooltip.append(gap).append(run.getDetail());
        }
    }

    private static List<FarmingRunStatus> due(List<FarmingRunStatus> runs) {
        return runs == null ? List.of()
                : runs.stream().filter(run -> "DUE".equals(run.getStatus())).collect(Collectors.toList());
    }

    /** The pending run that finishes first; of two finishing together, the earlier listed. */
    private static FarmingRunStatus soonest(List<FarmingRunStatus> runs) {
        return runs == null ? null : runs.stream()
                .filter(run -> "PENDING".equals(run.getStatus()) && run.getReadyAtEpochSec() > 0)
                .min(Comparator.comparingLong(FarmingRunStatus::getReadyAtEpochSec)).orElse(null);
    }

    /** True when at least one run is due; the plugin shows the box only then. */
    public static boolean anythingDue(List<FarmingRunStatus> runs) {
        return !due(runs).isEmpty();
    }
}

package com.larryfarming.panel;

import java.awt.*;
import java.awt.image.BufferedImage;
import javax.swing.*;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ImageUtil;

/**
 * The strip at the top of the panel, logged in or out: Larry's face, his name with his mood
 * under it, and the plugin's version on the right.
 */
class BrandHeader extends JPanel
{
	/** Larry's own 16-pixel sidebar art, which every face in the panel scales up. */
	private static final String FACE = "/com/larryfarming/panel_icon.png";

	/**
	 * Leprechaun green, for the rule under the strip. The green that means "carried" is a
	 * different colour and belongs to item squares alone.
	 */
	private static final Color BRAND = new Color(0x2f9e4f);
	/** Leprechaun green lightened, for Larry's name on the dark panel. */
	private static final Color BRAND_LIGHT = new Color(0x46b866);

	/** Under the name while logged out, where Larry has no mood to show. */
	static final String DESCRIPTOR = "Farming Runs";

	private final JLabel mood;

	BrandHeader()
	{
		super(new BorderLayout(6, 0));
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
		// The rule under the strip, then a gap before whatever the panel shows below it.
		setBorder(BorderFactory.createCompoundBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0), BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, 2, 0, BRAND), BorderFactory.createEmptyBorder(0, 2, 6, 0))));

		add(new JLabel(face(2)), BorderLayout.WEST);

		JPanel name = PanelText.stack();
		name.add(PanelText.label("Larry", FontManager.getRunescapeBoldFont(), BRAND_LIGHT));
		mood = PanelText.label(DESCRIPTOR, PanelColors.META);
		name.add(mood);
		add(name, BorderLayout.CENTER);

		JLabel version = PanelText.label(LarryVersion.SHOWN, PanelColors.META);
		version.setVerticalAlignment(SwingConstants.TOP);
		add(version, BorderLayout.EAST);

		setMaximumSize(new Dimension(Short.MAX_VALUE, getPreferredSize().height));
	}

	/**
	 * Words the line under Larry's name in place. A plain label that never wraps, so a new
	 * mood on any refresh never changes the panel's height.
	 *
	 * @param tooltip shown on hover, or null for none
	 */
	void showMood(String text, String tooltip)
	{
		mood.setText(text);
		mood.setForeground(DESCRIPTOR.equals(text) ? PanelColors.META : PanelColors.HEADER);
		mood.setToolTipText(tooltip);
	}

	/** Larry's face at a whole multiple of its 16 pixels, kept sharp. */
	static ImageIcon face(int scale)
	{
		BufferedImage art = ImageUtil.loadImageResource(BrandHeader.class, FACE);
		return new ImageIcon(art.getScaledInstance(art.getWidth() * scale, art.getHeight() * scale, Image.SCALE_REPLICATE));
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingCarryItem;
import java.awt.*;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * The bag for a run, laid out the way the game lays out an inventory.
 *
 * <p>Sprites in a four-wide grid, with names on hover, so the player can check the bag at a
 * glance.
 */
class CarryView extends StretchPanel
{
	/** The game inventory's width. */
	static final int COLUMNS = 4;

	/** Already in the bag. */
	private static final Color COLOR_HELD = ColorScheme.PROGRESS_COMPLETE_COLOR;
	/** Owned but not carried: one withdrawal away. */
	static final Color COLOR_TO_WITHDRAW = ColorScheme.BRAND_ORANGE;

	/**
	 * Shown when the seeds are only accounted for inside a seed box whose contents have not
	 * been checked. Worded as the in-game errand that settles it.
	 * {@code CarryPlanner.theBoxWouldFinishIt} explains the state.
	 *
	 * <p>Shared by this grid's hover and the bank row's line so the two cannot drift.
	 */
	static final String CHECK_SEED_BOX = "Check your seed box";

	CarryView()
	{
		PanelText.stack(this);
		setBorder(BorderFactory.createEmptyBorder(2, 4, 4, 0));
	}

	/**
	 * Redraws the bag. Called only when the carry signature has changed, since the caller
	 * guards structural rebuilds. An empty or null bag hides the view.
	 */
	void rebuild(List<FarmingCarryItem> carry, IconProvider icons)
	{
		removeAll();
		setVisible(carry != null && !carry.isEmpty());
		if (isVisible())
		{
			add(SettingGrid.grid(carry.stream().map(item -> square(item, icons)).collect(Collectors.toList()), icons));
		}
	}

	/**
	 * A hover of two lines: the item, then what to know about it. Separate lines, so the
	 * note reads as its own sentence instead of hanging off the name by a dash.
	 */
	static String twoLines(String first, String second)
	{
		return "<html>" + PanelText.escape(first) + "<br>" + PanelText.escape(second) + "</html>";
	}

	/** "3 × Toadflax seed", or a bare name where the count is not the point. */
	static String label(FarmingCarryItem item)
	{
		return item.getQuantity() > 0 ? item.getQuantity() + " × " + item.getName() : item.getName();
	}

	/**
	 * One inventory square, bordered green when carried or with the leprechaun, orange when
	 * banked or in the seed box, and unbordered when the player owns none.
	 */
	private static JPanel square(FarmingCarryItem item, IconProvider icons)
	{
		ItemSquare cell = ItemSquare.of(item, icons, item.isOwned());

		// The tooltip names the item and the border gives its state. The tooltip adds words
		// only for what a border cannot show: an item note, or the two states below.
		cell.setToolTipText(item.getNote() == null || item.getNote().isEmpty() ? label(item) : twoLines(label(item), item.getNote()));
		switch (item.getAvailability())
		{
			case CARRIED:
				cell.setBorder(BorderFactory.createLineBorder(COLOR_HELD));
				break;
			case AT_LEPRECHAUN:
				// Green like CARRIED: nothing to do before leaving. Taken out on arrival.
				cell.setBorder(BorderFactory.createLineBorder(COLOR_HELD));
				cell.setToolTipText(twoLines(label(item), "With the leprechaun."));
				break;
			case IN_SEED_BOX:
				// Orange like BANKED: not settled until the player checks the box.
				cell.setBorder(BorderFactory.createLineBorder(COLOR_TO_WITHDRAW));
				cell.setToolTipText(twoLines(label(item), CHECK_SEED_BOX + "."));
				break;
			case BANKED:
				cell.setBorder(BorderFactory.createLineBorder(COLOR_TO_WITHDRAW));
				break;
			default:
				cell.setBorder(BorderFactory.createEmptyBorder(1, 1, 1, 1));
				break;
		}
		return cell;
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingSettingPick;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.BorderFactory;
import javax.swing.JPanel;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;

/**
 * A setting that takes one of a few values, drawn as a row of chips. The picked chip wears
 * the green outline a ticked {@link SettingSquare} does, and a click on another picks it at
 * once and sends its value.
 *
 * <p>Each chip is a {@link SmallButton} as wide as its text, and the row's spare width is
 * shared out in the same proportion. Refreshes restyle the chips in place, rebuilding them
 * only when the options change, so a refresh cannot flicker.
 */
class ChoiceChips extends JPanel
{
	private static final int CHIP_HEIGHT = 20;
	private static final int GAP = 2;
	private static final Border ON_BORDER = BorderFactory.createLineBorder(ColorScheme.PROGRESS_COMPLETE_COLOR);

	private final BiConsumer<String, String> send;
	private final List<SmallButton> chips = new ArrayList<>();
	private final List<String> values = new ArrayList<>();
	/** The button look before any outline, put back when a chip is no longer picked. */
	private Border plainBorder;
	private Color plainText;
	private List<FarmingSettingPick.Option> shownOptions = List.of();
	private String key;
	private String selected;

	/** @param send receives the setting's key and the picked value */
	ChoiceChips(BiConsumer<String, String> send)
	{
		super(new GridBagLayout());
		this.send = send;
		setOpaque(false);
	}

	/** Shows this setting, rebuilding the chips only when its options have changed. */
	void show(FarmingSettingPick pick)
	{
		key = pick.getKey();
		if (!pick.getOptions().equals(shownOptions))
		{
			build(pick.getOptions());
		}
		select(pick.getSelected());
	}

	private void build(List<FarmingSettingPick.Option> options)
	{
		removeAll();
		chips.clear();
		values.clear();
		shownOptions = List.copyOf(options);
		for (int i = 0; i < options.size(); i++)
		{
			FarmingSettingPick.Option option = options.get(i);
			SmallButton chip = new SmallButton(option.getLabel());
			if (plainBorder == null)
			{
				plainBorder = chip.getBorder();
				plainText = chip.getForeground();
			}
			chip.setToolTipText(option.getHint());
			// Measured before any outline, so picking a chip never changes its size.
			int width = chip.getPreferredSize().width;
			chip.setPreferredSize(new Dimension(width, CHIP_HEIGHT));
			chip.addActionListener(e -> pick(option.getValue()));
			GridBagConstraints c = new GridBagConstraints();
			c.gridx = i;
			c.weightx = width;
			c.fill = GridBagConstraints.HORIZONTAL;
			c.insets = new Insets(0, i == 0 ? 0 : GAP, 0, 0);
			add(chip, c);
			chips.add(chip);
			values.add(option.getValue());
		}
		revalidate();
	}

	private void pick(String value)
	{
		if (value.equals(selected))
		{
			return;
		}
		select(value);
		if (key != null)
		{
			send.accept(key, value);
		}
	}

	private void select(String value)
	{
		selected = value;
		for (int i = 0; i < chips.size(); i++)
		{
			boolean on = values.get(i).equals(value);
			SmallButton chip = chips.get(i);
			chip.setBorder(on ? ON_BORDER : plainBorder);
			chip.setForeground(on ? Color.WHITE : plainText);
		}
	}
}

package com.larryfarming.panel;

import java.awt.*;
import javax.swing.Icon;

/**
 * An icon drawn faint, as an unticked setting square draws its sprite.
 *
 * <p>Wraps rather than copies, so an item sprite that loads after the row is built still
 * paints through it.
 */
final class DimmedIcon implements Icon
{
	private final Icon icon;

	DimmedIcon(Icon icon)
	{
		this.icon = icon;
	}

	/** The icon drawn faint. */
	Icon getIcon()
	{
		return icon;
	}

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			// The same strength as an unticked setting square's sprite.
			g2.setComposite(SettingSquare.DIM);
			icon.paintIcon(c, g2, x, y);
		}
		finally
		{
			g2.dispose();
		}
	}

	@Override
	public int getIconWidth()
	{
		return icon.getIconWidth();
	}

	@Override
	public int getIconHeight()
	{
		return icon.getIconHeight();
	}
}

package com.larryfarming.panel;

import java.awt.*;
import java.awt.geom.Path2D;

/**
 * The open eye that marks a setting Larry has seen for himself, drawn in a row's checkbox
 * place. It sits beside the {@link Padlock}: seen built shows the eye, impossible the lock.
 */
final class Eye extends Mark
{
	/** The eye's own width and height, corner to corner. */
	static final int WIDTH = 11;
	static final int HEIGHT = 8;

	private static final Stroke STROKE = new BasicStroke(1.2f);

	/** The lids, two arcs meeting at the corners, drawn once and translated to each place. */
	private static final Path2D LIDS = lids();

	/**
	 * An eye icon that takes up {@code width} by {@code height}, with the eye centred in it,
	 * so it can stand where another icon would.
	 */
	Eye(Color colour, int width, int height)
	{
		super(colour, WIDTH, HEIGHT, width, height);
	}

	private static Path2D lids()
	{
		Path2D lids = new Path2D.Float();
		lids.moveTo(0, 4);
		lids.quadTo(5.5, -2, 11, 4);
		lids.quadTo(5.5, 10, 0, 4);
		return lids;
	}

	/** Draws the eye with its bounding box's top-left corner at x, y. */
	@Override
	void drawAt(Graphics2D g, int x, int y, Color colour)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(colour);
		g.setStroke(STROKE);
		g.translate(x, y);
		g.draw(LIDS);
		g.fillOval(3, 1, 5, 5);
		g.translate(-x, -y);
	}
}

