	/**
	 * Reports a click on a route switch, and redraws at once rather than waiting for a
	 * snapshot that may not come while the player is idle or logged out.
	 */
	private void reportAndRedraw(Consumer<Boolean> callback, boolean show)
	{
		if (callback != null)
		{
			callback.accept(show);
		}
		display(lastAdvice, lastIcons);
	}

	/**
	 * Receives a farming setting the player changed in the panel, as its config key and the
	 * value to write. The plugin saves it, and the re-plan that follows redraws the panel.
	 */
	public void setSettingCallback(BiConsumer<String, String> callback)
	{
		settingCallback = callback;
	}

	/** Receives the player's click on "Stop now" beside the compost stock. The plugin passes it to the planner. */
	public void setStopCompostCallback(Runnable callback)
	{
		stopCompostCallback = callback;
	}

	private void sendSetting(String key, String value)
	{
		if (settingCallback != null && key != null)
		{
			settingCallback.accept(key, value);
		}
	}

	/**
	 * Shows the settings that order and pace every run. Each sits on a long-lived control
	 * and is set in place, so calling this on every refresh cannot flicker.
	 */
	private void showRunPacing(FarmingAdvice advice)
	{
		FarmingSettingPick runFirst = advice.getRunFirst();
		if (runFirst != null)
		{
			runFirstCaption.setText(runFirst.getLabel());
			runFirstChips.show(runFirst);
		}
		runFirstCaption.setVisible(runFirst != null);
		runFirstChips.setVisible(runFirst != null);
		FarmingSettingChoice wait = advice.getWaitForEveryPatch();
		if (wait != null)
		{
			waitKey = wait.getKey();
			waitBox.setText(wait.getLabel());
			waitBox.setSelected(wait.isOn());
		}
		waitBox.setVisible(wait != null);
		planning.setVisible(runFirst != null || wait != null);
	}

	/**
	 * The panel's one checkbox style, for the fold boxes and the farming settings alike,
	 * with {@code top} pixels of space above it.
	 */
	static JCheckBox checkbox(String text, int top)
	{
		JCheckBox box = new JCheckBox(text);
		box.setFont(FontManager.getRunescapeSmallFont());
		box.setForeground(PanelColors.HEADER);
		box.setOpaque(false);
		box.setFocusPainted(false);
		box.setAlignmentX(LEFT_ALIGNMENT);
		box.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		box.setBorder(BorderFactory.createEmptyBorder(top, 0, 0, 0));
		return box;
	}

	/**
	 * Forces the next {@link #display} to rebuild even if the advice is unchanged.
	 *
	 * <p>Call when the panel is switched to: its rows wrapped against a width from when it was
	 * last visible, and the guard's signature cannot see a layout change.
	 */
	public void forgetLastBuild()
	{
		guard.reset();
	}

	/**
	 * Receives a request to plan for a different spellbook, as the book's name, or null to
	 * follow the player's own.
	 */
	public void setSpellbookCallback(Consumer<String> callback)
	{
		spellbookPicker.setSpellbookCallback(callback);
	}

	/**
	 * Shows a run, rebuilding only when the advice itself has changed.
	 *
	 * <p>Called on every game event. The rows hold wrapping text, and recreating it on each
	 * call would flicker the panel.
	 */
	public void display(FarmingAdvice advice, IconProvider icons)
	{
		lastAdvice = advice;
		lastIcons = icons;

		if (advice == null)
		{
			// reset() rather than a sentinel signature: the containers are emptied out of
			// band here, so a stale signature must not later read as "unchanged".
			guard.reset();
			countdowns.clear();
			nowContainer.removeAll();
			stopsContainer.removeAll();
			runsList.clear();
			carryView.rebuild(null, icons);
			laterContainer.removeAll();
			wearList.rebuild(null, icons, 0);
			goalsList.rebuild(null, icons, 0);
			titleLabel.setVisible(false);
			loggedOutCard.setVisible(true);
			brandHeader.showMood(BrandHeader.DESCRIPTOR, null);
			showSections(Phase.NONE, false, false, false, false);
			revalidate();
			repaint();
			return;
		}

		int visits = countFrom(advice, 0, FarmingPanel::isNumbered);
		Phase phase = visits == 0 ? Phase.IDLE : advice.isUnderway() ? Phase.UNDERWAY : Phase.PACKING;
		// Underway, every row before the next stop is behind the player: a finished stop (it
		// turned into a skip when planted) or a bank already passed. Those rows are never
		// drawn, so the switches' counts start where the drawing does.
		int from = phase == Phase.UNDERWAY ? nextStopIndex(advice) : 0;
		// Counted from the rows so the fold label matches exactly what the fold hides: every
		// arrival that is not a VISIT. Must match the fold rule below, so the label never
		// offers more or fewer rows than clicking reveals.
		int foldedStops = countFrom(advice, from, stop -> stop.getOutcome() != FarmingStopAdvice.Outcome.VISIT);
		int foldedPatches = foldedPatches(advice);

		boolean drawSkipped = showSkippedBox.isSelected();
		boolean drawBanks = showBanksBox.isSelected();

		// Live values, set before the guard on every refresh. Each sits on a long-lived,
		// non-wrapping component, so re-wording it cannot flicker. Keep them out of the
		// signature, or every change would tear down the wrapping rows below.
		// A day with nothing due has no run to name, and the header above already says Larry.
		titleLabel.setText(phase == Phase.IDLE ? "" : advice.getRunName());
		titleLabel.setVisible(phase != Phase.IDLE);
		loggedOutCard.setVisible(false);
		boolean idle = phase == Phase.IDLE;
		boolean underway = phase == Phase.UNDERWAY;
		boolean pending = anyRunIn(advice.getRuns(), STATUS_PENDING);
		boolean due = anyRunIn(advice.getRuns(), RunsListView.STATUS_DUE);
		brandHeader.showMood(mood(idle, underway, pending || due), idle && pending && !due ? HUNGRY_PATIENCE : null);
		// The picker keeps its own change check, so calling it every refresh is cheap.
		spellbookPicker.rebuild(advice.getCarryFor(), advice.getSpellbookOpen(), icons);
		String nextRun = nextRunText(advice.getRuns(), Instant.now().getEpochSecond());
		nextRunLabel.setText(nextRun);

		// The same text whether open or shut, so the label does not change under the cursor.
		// One number counts skipped stops and set-aside patches together, and the box shows
		// only while that total is above zero. Counting stops alone could read "0 skipped"
		// while patches are set aside.
		showSkippedBox.setText((foldedStops + foldedPatches) + " skipped");
		// The optional banks still ahead. Recommended bank stops are always drawn.
		int banks = countFrom(advice, from, stop -> stop.getKind() == FarmingStopAdvice.Kind.BANK_OPTIONAL);
		showBanksBox.setText(banks == 1 ? "1 bank you may pass" : banks + " banks you may pass");

		boolean suggesting = showNote(respawnNote, advice.getRespawnAction());
		boolean untickedSeeds = showNote(herbNote, advice.getHerbNote());

		String look = advice.getLookOnce();
		boolean unlooked = PanelText.hasText(look);
		if (unlooked && !look.equals(lookOnceNote.getText()))
		{
			lookOnceNote.setText(look);
			lookOnceIdleNote.setText(look);
		}

		// Visibility changes relayout the parent, but the guard's early return skips
		// revalidate(). Sections and switches are safe only while every input deciding their
		// visibility (the phase, outcomes, kinds, each stop's set-aside list) is also in the
		// signature. The notes and the next-run line are live values on long-lived
		// components, deliberately outside it.
		showSections(phase, suggesting, untickedSeeds, unlooked, !nextRun.isEmpty());
		showSkippedBox.setVisible(foldedStops > 0 || foldedPatches > 0);
		showBanksBox.setVisible(visits > 0 && banks > 0);
		routeHeading.setVisible(showSkippedBox.isVisible() || showBanksBox.isVisible());
		placeRunsList(phase);
		showRunPacing(advice);
		travel.show(advice, icons);
		house.show(advice);
		// Mirrors the travel fold's own warning, which it shows only while it has squares.
		settingsFold.warn(travel.isVisible() && advice.isFairyRingBlocked(), TravelFold.BLOCKED);

		if (!guard.shouldRebuild(signatureOf(advice, phase, drawSkipped, drawBanks)))
		{
			// Same rows: only re-word the countdowns in place.
			for (Runnable countdown : countdowns)
			{
				countdown.run();
			}
			runsList.showDetails(advice);
			return;
		}

		// The rows wrap against the panel's inner width less the route box's border. Read off
		// the panel, since a box hidden until now reports no width of its own.
		int width = Math.max(0, getWidth() - getInsets().left - getInsets().right - 2);

		countdowns.clear();
		nowContainer.removeAll();
		stopsContainer.removeAll();
		drawingUnderway = phase == Phase.UNDERWAY;
		laterBandsDrawn = phase == Phase.PACKING && !carryNow(advice).isEmpty();
		boolean haveNow = false;
		int number = 0;
		boolean divider = false;
		List<FarmingStopAdvice> stops = advice.getStops();
		for (int index = 0; index < stops.size(); index++)
		{
			FarmingStopAdvice stop = stops.get(index);
			// Every VISIT is numbered, extras included, except unnumbered bank rows. Numbered
			// before the fold, so folded skips leave no gaps.
			//
			// Numbering and drawing are separate decisions. Optional banks are unnumbered but
			// follow the bank switch, not the skipped-stops fold.
			boolean numbered = isNumbered(stop);
			if (numbered)
			{
				number++;
			}
			// The starting bank row stays: it names what to fetch at the next bank opened.
			if (index < from && stop.getKind() != FarmingStopAdvice.Kind.BANK_START)
			{
				continue;
			}
			if (stop.getKind() == FarmingStopAdvice.Kind.BANK_OPTIONAL)
			{
				if (!drawBanks)
				{
					continue;
				}
			}
			else if (stop.getKind() == FarmingStopAdvice.Kind.BANK_START)
			{
				// Before the trip, the packing grid above already lists what to withdraw.
				if (phase == Phase.PACKING)
				{
					continue;
				}
			}
			else if (stop.getOutcome() != FarmingStopAdvice.Outcome.VISIT && !drawSkipped)
			{
				continue;
			}
			JPanel row = buildStopRow(stop, number, icons, drawSkipped);
			// Partway round, a starting row with something to fetch is fetched before the next
			// stop, so it sits above that stop's card rather than among the stops after it.
			if (stop.getKind() == FarmingStopAdvice.Kind.BANK_START && !haveNow && !stop.getWithdraw().isEmpty())
			{
				nowContainer.add(sized(row, width));
				continue;
			}
			// The first numbered stop is where the player is heading: finished stops turn
			// into skips, so the card moves down the route on its own.
			if (numbered && !haveNow)
			{
				// The card has no box around it, so it takes the border's two pixels back. Not
				// before layout: sized() would wrap the card against a 2px width.
				nowContainer.add(sized(asNowCard(row), width > 0 ? width + 2 : 0));
				haveNow = true;
				continue;
			}
			if (divider)
			{
				stopsContainer.add(PanelColors.divider());
			}
			stopsContainer.add(sized(row, width));
			divider = true;
		}
		nowHeading.setText(sectionLabel(phase == Phase.UNDERWAY ? "Next stop" : "First stop"));
		boolean haveBankFirst = nowContainer.getComponentCount() > (haveNow ? 1 : 0);
		nowHeading.setVisible(haveNow || haveBankFirst);
		nowContainer.setVisible(haveNow || haveBankFirst);
		stopsHeading.setText(sectionLabel(haveNow ? "Then" : "Route"));
		stopsHeading.setVisible(divider);
		stopsContainer.setVisible(divider);

		List<FarmingCarryItem> carry = advice.getCarry();
		// Split at the first later bank: what to pack now, then what each bank hands over.
		boolean split = !carryNow(advice).isEmpty();
		carryView.rebuild(phase == Phase.PACKING ? (split ? carryNow(advice) : carry) : null, icons);
		carryHeading.setVisible(carry != null && !carry.isEmpty());
		rebuildLater(phase == Phase.PACKING && split ? stops : null, drawBanks, icons, width);

		boolean wear = wearList.rebuild(phase == Phase.PACKING ? advice.getUpgrades() : null, icons, width);
		wearHeading.setVisible(wear);
		boolean goals = goalsList.rebuild(phase == Phase.IDLE ? advice.getUpgrades() : null, icons, width);
		goalsHeading.setVisible(goals);

		// Inside the settings fold the list sits behind the fold content's left inset.
		int runsWidth = phase == Phase.IDLE || width == 0 ? width : Math.max(0, width - settingsFold.content().getInsets().left);
		runsList.rebuild(advice, icons, runsWidth);

		revalidate();
		repaint();
	}

	/**
	 * A band and a grid for every later bank that hands something over, in walk order. An
	 * optional bank counts only while the bank switch draws it.
	 *
	 * @param stops the walkthrough, or null to clear the bands
	 */
	private void rebuildLater(List<FarmingStopAdvice> stops, boolean drawBanks, IconProvider icons, int width)
	{
		laterContainer.removeAll();
		boolean any = false;
		if (stops != null)
		{
			for (FarmingStopAdvice stop : stops)
			{
				boolean later = stop.getKind() == FarmingStopAdvice.Kind.BANK
					|| (drawBanks && stop.getKind() == FarmingStopAdvice.Kind.BANK_OPTIONAL);
				if (!later || stop.getWithdraw().isEmpty())
				{
					continue;
				}
				laterContainer.add(laterBand(stop.getPatchName()));
				// The bank row's own grid, so a band and its row below cannot drift apart.
				JPanel grid = PanelText.stack();
				addWithdrawals(grid, stop, icons, false);
				laterContainer.add(grid);
				any = true;
			}
		}
		laterContainer.setVisible(any);
	}

	/** The packing list's "now" half, empty when no later bank splits the trip. */
	private static List<FarmingCarryItem> carryNow(FarmingAdvice advice)
	{
		return PanelText.listOf(advice.getCarryNow());
	}

	/** "LATER: BANK AT CATHERBY" on a filled strip, so the band reads apart from the bag. */
	private static JPanel laterBand(String bank)
	{
		JLabel label = PanelText.label(sectionLabel("Later: " + bank), PanelColors.META);
		JPanel strip = new JPanel(new BorderLayout());
		strip.setBackground(PanelColors.CONTAINER_BG);
		strip.setBorder(BorderFactory.createEmptyBorder(3, 4, 3, 4));
		strip.add(label);
		JPanel band = PanelText.panel(new BorderLayout());
		band.setBorder(BorderFactory.createEmptyBorder(8, 0, 2, 0));
		band.add(strip);
		band.setMaximumSize(new Dimension(Integer.MAX_VALUE, band.getPreferredSize().height));
		return band;
	}

	/**
	 * Where the player is in a farm run, which decides what the top of the panel shows: the
	 * runs on a day with nothing due, the packing list before setting off, the next stop
	 * once underway.
	 */
	private enum Phase
	{
		NONE,
		IDLE,
		PACKING,
		UNDERWAY
	}

	/**
	 * Shows the sections the phase always has and hides the rest. Sections that also hide
	 * themselves when empty (bag, gear lists, route boxes) are only ever turned off here;
	 * the rebuild turns them on, so the guard's early return cannot leave one on screen
	 * empty.
	 */
	private void showSections(Phase phase, boolean respawn, boolean herbs, boolean unlooked, boolean nextRun)
	{
		boolean any = phase != Phase.NONE;
		boolean idle = phase == Phase.IDLE;
		boolean packing = phase == Phase.PACKING;
		respawnNote.setVisible(any && respawn);
		herbNote.setVisible(any && herbs);
		nextRunLabel.setVisible(idle && nextRun);
		idleRunsSlot.setVisible(idle);
		carryRow.setVisible(packing);
		lookOnceNote.setVisible(packing && unlooked);
		lookOnceIdleNote.setVisible(idle && unlooked);
		spellbookPicker.setVisible(packing);
		carryView.setVisible(packing && carryView.isVisible());
		laterContainer.setVisible(packing && laterContainer.isVisible());
		wearHeading.setVisible(packing && wearHeading.isVisible());
		wearList.setVisible(packing && wearList.isVisible());
		goalsHeading.setVisible(idle && goalsHeading.isVisible());
		goalsList.setVisible(idle && goalsList.isVisible());
		settingsFold.setVisible(any);
		if (!any)
		{
			nowHeading.setVisible(false);
			nowContainer.setVisible(false);
			stopsHeading.setVisible(false);
			stopsContainer.setVisible(false);
			showSkippedBox.setVisible(false);
			showBanksBox.setVisible(false);
			routeHeading.setVisible(false);
			travel.setVisible(false);
			house.setVisible(false);
		}
	}

	/**
	 * Receives the player's confirmed "Reset to the default route". The plugin writes the
	 * default route's value for every farming setting.
	 */
	public void setResetCallback(Runnable callback)
	{
		resetCallback = callback;
	}

	/** Asks before a reset, since it overwrites every farming setting at once. */
	private void confirmReset()
	{
		String[] options = {"Reset", "Cancel"};
		boolean reset = JOptionPane.showOptionDialog(this, "Every farming setting goes back to the default route.", "Larry",
			JOptionPane.DEFAULT_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[1]) == 0;
		if (reset && resetCallback != null)
		{
			resetCallback.run();
		}
	}

	/**
	 * Puts the runs list on the panel itself on a day with nothing due, where it answers "when
	 * is my next run", and into the settings fold otherwise, where it holds the run switches.
	 */
	private void placeRunsList(Phase phase)
	{
		JPanel home = phase == Phase.IDLE ? idleRunsSlot : settingsFold.content();
		if (runsList.getParent() == home)
		{
			return;
		}
		if (runsList.getParent() != null)
		{
			runsList.getParent().remove(runsList);
		}
		// First in the settings fold, ahead of the settings that order the runs.
		home.add(runsList, 0);
		home.revalidate();
		settingsFold.content().revalidate();
	}

	/** Restyles a stop row as the card for the stop the player is heading to. */
	private static JPanel asNowCard(JPanel row)
	{
		row.setOpaque(true);
		row.setBackground(PanelColors.CONTAINER_BG);
		row.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 3, 0, 0, COLOR_DUE),
			BorderFactory.createEmptyBorder(6, 4, 6, 4)));
		return row;
	}

	/**
	 * Larry's mood under his name: his one line of personality, so it never carries a fact
	 * the plan needs. The plan below says what is due and when.
	 *
	 * @param timed whether any run is due or counting down
	 */
	static String mood(boolean idle, boolean underway, boolean timed)
	{
		if (underway)
		{
			return "Keeping watch.";
		}
		if (!idle)
		{
			return "Up and about.";
		}
		// A day with no run counting down and none due means no patch has been seen yet,
		// or every run is shut.
		return timed ? "Having a drink." : "Waiting on your patches.";
	}

	private static boolean anyRunIn(List<FarmingRunStatus> runs, String status)
	{
		return runs != null && runs.stream().anyMatch(run -> status.equals(run.getStatus()));
	}

	/**
	 * "Herb run ready in 1h 20m" for the run that finishes soonest, or "" when no run is
	 * counting down. Worded on every refresh, so the countdown ticks in place.
	 *
	 * @param now the current epoch second
	 */
	static String nextRunText(List<FarmingRunStatus> runs, long now)
	{
		return PanelText.listOf(runs).stream().filter(run -> run.getReadyAtEpochSec() > now)
			.min(Comparator.comparingLong(FarmingRunStatus::getReadyAtEpochSec))
			.map(run -> run.getRunName() + " ready in " + FarmingDurations.until(run.getReadyAtEpochSec(), now)).orElse("");
	}

	/**
	 * Draws what to fetch at this bank as a captioned grid of inventory squares, using the
	 * packing grid's sprites. Draws nothing when there is nothing to fetch.
	 *
	 * <p>Every square is orange. The list holds only what is missing at this point in the
	 * route, so the packing grid's green "already carried" border never applies. An item's
	 * availability describes the bag at departure, not at this bank.
	 *
	 * <p>Exception: {@code IN_SEED_BOX} items leave the grid and become one "check your seed
	 * box" line underneath ({@code CarryPlanner.theBoxWouldFinishIt} sets that state only
	 * where fetching would be unnecessary).
	 *
	 * @param captioned whether to head the grid "Withdraw". The starting row's heading says
	 *     it already before setting off, and a Later band names its bank instead
	 */
	private static void addWithdrawals(JPanel text, FarmingStopAdvice stop, IconProvider icons, boolean captioned)
	{
		List<FarmingCarryItem> withdraw = stop.getWithdraw();
		if (withdraw.isEmpty())
		{
			return;
		}
		List<FarmingCarryItem> fetch = new ArrayList<>(withdraw.size());
		boolean checkSeedBox = false;
		for (FarmingCarryItem item : withdraw)
		{
			if (item.getAvailability() == FarmingCarryItem.Availability.IN_SEED_BOX)
			{
				checkSeedBox = true;
			}
			else
			{
				fetch.add(item);
			}
		}
		if (!fetch.isEmpty())
		{
			if (captioned)
			{
				text.add(PanelText.small("Withdraw", COLOR_DUE));
			}
			addBankGrid(text, fetch, icons, true);
		}
		// One line however many seeds: checking the box once answers them all.
		if (checkSeedBox)
		{
			text.add(PanelText.small(CarryView.CHECK_SEED_BOX, COLOR_DUE));
		}
	}

	/**
	 * A bank row's grid of squares, deposits and withdrawals alike.
	 *
	 * @param due whether they are something to do, bordered orange. A deposit the bag has
	 *     room to keep draws without one
	 */
	private static void addBankGrid(JPanel text, List<FarmingCarryItem> items, IconProvider icons, boolean due)
	{
		List<JPanel> squares = new ArrayList<>(items.size());
		for (FarmingCarryItem item : items)
		{
			ItemSquare cell = ItemSquare.of(item, icons, true);
			cell.setBorder(due ? BorderFactory.createLineBorder(CarryView.COLOR_TO_WITHDRAW) : BorderFactory.createEmptyBorder(1, 1, 1, 1));
			cell.setToolTipText(CarryView.label(item));
			squares.add(cell);
		}
		InventoryBackdrop grid = SettingGrid.grid(squares, icons);
		grid.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		text.add(grid);
	}

	/**
	 * Draws what to put back at this bank, above what to take out. Orange when the bag lacks
	 * room without it; grey, as a tidy-up, while the bag has room.
	 */
	private static void addDeposits(JPanel text, FarmingStopAdvice stop, IconProvider icons)
	{
		List<FarmingCarryItem> deposit = stop.getDeposit();
		if (deposit.isEmpty())
		{
			return;
		}
		boolean urgent = stop.isDepositUrgent();
		text.add(PanelText.small("Deposit", urgent ? COLOR_DUE : PanelColors.META));
		addBankGrid(text, deposit, icons, urgent);
	}

	/** Every kind of bank row. All get the same margin mark. */
	private static boolean isBankRow(FarmingStopAdvice stop)
	{
		return stop.getKind() == FarmingStopAdvice.Kind.BANK || isUnnumberedBankRow(stop);
	}

	/**
	 * Bank rows that take no number: an optional bank is outside the sequence, and the
	 * starting bank comes before it. Decides numbering only, not drawing.
	 */
	private static boolean isUnnumberedBankRow(FarmingStopAdvice stop)
	{
		return stop.getKind() == FarmingStopAdvice.Kind.BANK_OPTIONAL || stop.getKind() == FarmingStopAdvice.Kind.BANK_START;
	}

	/**
	 * A row that takes a number, by the rule that numbers the rows: every {@code VISIT}
	 * except unnumbered bank rows. A bank stop at an arrival already listed counts separately.
	 */
	private static boolean isNumbered(FarmingStopAdvice stop)
	{
		return stop.getOutcome() == FarmingStopAdvice.Outcome.VISIT && !isUnnumberedBankRow(stop);
	}

	/** Counts the stops from {@code from} on that {@code which} picks. */
	private static int countFrom(FarmingAdvice advice, int from, Predicate<FarmingStopAdvice> which)
	{
		List<FarmingStopAdvice> stops = advice.getStops();
		return (int) stops.subList(from, stops.size()).stream().filter(which).count();
	}

	private static JLabel sectionHeading(String text)
	{
		return SiteList.caption(sectionLabel(text), 10);
	}

	/** A section heading's text as drawn: every section label is upper case. */
	private static String sectionLabel(String text)
	{
		return text.toUpperCase();
	}

	/**
	 * Gives a row its wrapping width before first paint. Without it the text measures as one
	 * line and visibly reflows once layout assigns a width.
	 */
	static JPanel sized(JPanel row, int width)
	{
		if (width > 0)
		{
			row.setSize(width, row.getPreferredSize().height);
			row.doLayout();
		}
		return row;
	}

	/**
	 * Where the next stop sits in the stop list: the first numbered visit, or the list's
	 * end when none is left.
	 */
	private static int nextStopIndex(FarmingAdvice advice)
	{
		List<FarmingStopAdvice> stops = advice.getStops();
		for (int i = 0; i < stops.size(); i++)
		{
			if (isNumbered(stops.get(i)))
			{
				return i;
			}
		}
		return stops.size();
	}

	/**
	 * Counts the set-aside patch lines inside visited stops. A skipped stop's lines are not
	 * counted: they reveal with their row, which the folded stops already count.
	 */
	private static int foldedPatches(FarmingAdvice advice)
	{
		return advice.getStops().stream().filter(stop -> stop.getOutcome() == FarmingStopAdvice.Outcome.VISIT)
			.mapToInt(stop -> setAside(stop).size()).sum();
	}

	/** An empty, long-lived note line, worded in place on each refresh. */
	private static JTextArea note(Color colour, Border border)
	{
		JTextArea line = PanelText.small("", colour);
		line.setBorder(border);
		return line;
	}

	/**
	 * Puts a live note's words on its long-lived area, when there are any.
	 *
	 * @return whether the note has anything to say
	 */
	private static boolean showNote(JTextArea note, String words)
	{
		boolean any = PanelText.hasText(words);
		if (any)
		{
			note.setText(words);
		}
		return any;
	}

	/** Adds a small line in {@code colour}, when there is anything to say. */
	private static void addLine(JPanel text, String line, Color colour)
	{
		if (PanelText.hasText(line))
		{
			text.add(PanelText.small(line, colour));
		}
	}

	/**
	 * One stop: its seed sprite, the patch, the route, and what goes in the ground.
	 *
	 * @param drawSkipped whether the skipped-stops fold is open, which also lists a stop's
	 *     set-aside patches
	 */
	private JPanel buildStopRow(FarmingStopAdvice stop, int number, IconProvider icons, boolean drawSkipped)
	{
		boolean visiting = stop.getOutcome() == FarmingStopAdvice.Outcome.VISIT;
		String note = stop.getNote();
		boolean hasNote = PanelText.hasText(note);

		JPanel row = PanelText.panel(new GridBagLayout());
		row.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 4));

		GridBagConstraints gbc = PanelText.marginConstraints();

		// Margin: one crop per planting, stacked, at the game's sprite size (rescaling
		// distorts it). A row planting nothing shows the crop it harvests, and a bank row
		// the minimap bank symbol. A skipped stop gets no crop.
		Component margin = marginOf(stop, visiting, icons);
		if (margin == null && visiting && stop.getKind() == FarmingStopAdvice.Kind.PATCH)
		{
			// No crop to show (a contract errand alone, say). Reserve the margin so every visited
			// patch row's text shares one left edge. Other non-patch rows keep full width.
			margin = Box.createRigidArea(new Dimension(ITEM_SPRITE_WIDTH + 5, 0));
		}
		if (margin != null)
		{
			gbc.gridheight = GridBagConstraints.REMAINDER;
			row.add(margin, gbc);
			gbc.gridheight = 1;
		}

		JPanel text = PanelText.stack();

		// A wrapping area, not a JLabel: a skipped stop's heading is long and a JLabel
		// would truncate it with an ellipsis.
		// An offered bank is a choice, not a step, so it reads quieter than the stops.
		boolean step = visiting && stop.getKind() != FarmingStopAdvice.Kind.BANK_OPTIONAL;
		JTextArea name = PanelText.textArea(headingOf(stop, number), headingColour(stop),
			step ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
		text.add(name);
		if (!visiting && stop.getReadyAtEpochSec() > 0)
		{
			countdowns.add(() -> name.setText(headingOf(stop, number)));
		}

		// A skip shows its reason on the row, not only in the hover, unless the heading
		// already carries it (the stop has a subject).
		if (!visiting)
		{
			String tooltip = hover(stop.getBecause(), hasNote ? note : null);
			row.setToolTipText(tooltip);
			name.setToolTipText(tooltip);
			if (!PanelText.hasText(stop.getSubject()) && !headingCarriesBecause(stop))
			{
				addLine(text, stop.getBecause(), PanelColors.SKIPPED);
			}
			// The heading covers only the most urgent patch. These lines cover the rest.
			addSetAside(text, stop, drawSkipped);
			PanelText.addFill(row, gbc, 1, text);
			return row;
		}

		String detail = stop.getInstruction();
		if (PanelText.hasText(detail))
		{
			text.add(routeLine(stop, detail, icons));
		}
		// Before anything to do here: the stop cannot be done without it. Orange, as
		// everything still needed is.
		addLine(text, stop.getWarning(), CarryView.COLOR_TO_WITHDRAW);

		// Check/harvest acts, above the planting lines. One line per act in the given
		// order. The sequence matters (a bush checked before it is dug up), so the lines
		// stay unsorted and unmerged.
		for (String act : stop.getActions())
		{
			addLine(text, act, COLOR_DUE);
		}

		addDeposits(text, stop, icons);
		// While packing, a later bank's withdrawals stand in its band at the top; drawing
		// them here too would show the same grid twice.
		boolean inABand = laterBandsDrawn && (stop.getKind() == FarmingStopAdvice.Kind.BANK
			|| stop.getKind() == FarmingStopAdvice.Kind.BANK_OPTIONAL);
		if (!inABand)
		{
			// Before setting off the starting row's heading says "Withdraw" already.
			addWithdrawals(text, stop, icons, stop.getKind() != FarmingStopAdvice.Kind.BANK_START || drawingUnderway);
		}

		// One line for every crop, counted in patches, not seeds (an allotment takes three seeds
		// but is one planting), leaving out the crops an act line already replants.
		List<FarmingPlantAdvice> plants = plants(stop).stream().filter(plant -> !plant.isSaid()).collect(Collectors.toList());
		if (!plants.isEmpty())
		{
			text.add(PanelText.small(plantingOf(plants), COLOR_DUE));
		}

		// After the plantings, since the tools are needed until the stop is done. Grey: it
		// saves slots, and nothing fails without it.
		addLine(text, stop.getLeprechaun(), PanelColors.META);

		// Grey and last of the stop's own lines: it qualifies the work above, and the guess
		// may be why the player is sent here at all.
		addLine(text, stop.getAssumption(), PanelColors.META);

		// Below the plantings: a row leads with what the player acts on.
		addSetAside(text, stop, drawSkipped);

		// isOptional is not displayed: optional crops already have a player toggle in
		// settings, and the flag only drives routing.

		// Route hedges and default-route hints go in the hover.
		if (hasNote)
		{
			row.setToolTipText(note);
			name.setToolTipText(note);
		}

		PanelText.addFill(row, gbc, 1, text);
		return row;
	}

	/**
	 * A hover from the clauses that have something to say, or null for none.
	 *
	 * <p>Null rather than "": {@code setToolTipText("")} shows an empty tooltip box.
	 */
	private static String hover(String... clauses)
	{
		StringBuilder joined = new StringBuilder();
		for (String clause : clauses)
		{
			if (!PanelText.hasText(clause))
			{
				continue;
			}
			if (joined.length() > 0)
			{
				joined.append(" — ");
			}
			joined.append(clause);
		}
		return joined.length() == 0 ? null : joined.toString();
	}

	/**
	 * One grey line per patch at this arrival that nobody is working, with its reason in
	 * the hover. Drawn on visited and skipped rows alike, so every patch gets either a
	 * planting line or one of these. Hidden with the skipped stops when the fold is shut.
	 */
	private void addSetAside(JPanel text, FarmingStopAdvice stop, boolean drawSkipped)
	{
		if (!drawSkipped)
		{
			return;
		}
		for (FarmingPatchNote aside : setAside(stop))
		{
			JTextArea line = PanelText.small(patchNoteText(aside), PanelColors.SKIPPED);
			line.setToolTipText(hover(aside.getBecause()));
			text.add(line);
			if (aside.getReadyAtEpochSec() > 0)
			{
				countdowns.add(() -> line.setText(patchNoteText(aside)));
			}
		}
	}

	/**
	 * A row's heading: its number and place when the trip is on, its place and why not
	 * when it is off.
	 *
	 * <p>A skipped heading carries a countdown, so {@link #countdowns} re-words it in place.
	 */
	private static String headingOf(FarmingStopAdvice stop, int number)
	{
		// No number: the counter has not advanced for this row, so prefixing it would
		// repeat the previous row's number.
		if (isUnnumberedBankRow(stop))
		{
			return stop.getPatchName();
		}
		return stop.getOutcome() == FarmingStopAdvice.Outcome.VISIT ? number + ". " + stop.getPatchName()
			: stop.getPatchName() + " — " + statusOf(stop);
	}

	/**
	 * The route line, with its teleport icon inline on the first line. The row's margin
	 * column belongs to the crop.
	 */
	private static JPanel routeLine(FarmingStopAdvice stop, String detail, IconProvider icons)
	{
		JPanel line = PanelText.panel(new GridBagLayout());
		PanelText.addIconAndFill(line, GridBagConstraints.NORTHWEST, travelIcon(stop, icons), 4,
			PanelText.small(detail, detailColour(stop)));
		return line;
	}

	/**
	 * The planting line, each crop counted in patches as the act lines are: "Plant toadflax",
	 * "Plant toadflax, limpwurt, watermelon ×2". The crops read lower case mid-sentence, as the
	 * game writes them.
	 */
	static String plantingOf(List<FarmingPlantAdvice> plants)
	{
		return "Plant " + plants.stream()
			.map(plant -> inSentence(plant.getName()) + FarmingPlantAdvice.countOf(plant.getPatches()))
			.collect(Collectors.joining(", "));
	}

	/** A crop name for mid-sentence: lower case, except Hespori, which is a name. */
	private static String inSentence(String crop)
	{
		return "Hespori".equals(crop) ? crop : crop.toLowerCase(java.util.Locale.ROOT);
	}

	/**
	 * A stop's margin: the bank symbol on a bank row; on a visit, one crop per planting
	 * stacked top to bottom, or the crop it harvests when it plants nothing. Null for a
	 * skipped stop or a visit with nothing to picture.
	 */
	private static JComponent marginOf(FarmingStopAdvice stop, boolean visiting, IconProvider icons)
	{
		if (isBankRow(stop))
		{
			ImageIcon bank = icons == null ? null : icons.getSpriteIcon(SpriteID.Mapfunction.BANK, 16);
			return bank == null ? null : marginLabel(bank);
		}
		if (!visiting)
		{
			return null;
		}
		List<FarmingPlantAdvice> pictured = plants(stop).stream().filter(plant -> plant.getProduceItemId() > 0)
			.collect(Collectors.toList());
		if (pictured.isEmpty())
		{
			int harvest = stop.getIconItemId();
			ImageIcon crop = icons == null || harvest <= 0 ? null : icons.getInventoryIcon(harvest, true);
			return crop == null ? null : marginLabel(crop);
		}
		JPanel column = PanelText.stack();
		column.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 4));
		for (int i = 0; i < pictured.size(); i++)
		{
			if (i > 0)
			{
				column.add(Box.createRigidArea(new Dimension(0, 2)));
			}
			column.add(cropIcon(pictured.get(i), icons));
		}
		return column;
	}

	/** A lone margin icon, inset as the stacked crops are. */
	private static JLabel marginLabel(ImageIcon sprite)
	{
		JLabel icon = new JLabel(sprite);
		icon.setBorder(BorderFactory.createEmptyBorder(1, 0, 0, 5));
		return icon;
	}

	/** One planting's crop in the margin, named in the hover. */
	private static JLabel cropIcon(FarmingPlantAdvice plant, IconProvider icons)
	{
		JLabel icon = new JLabel(icons == null ? null : icons.getInventoryIcon(plant.getProduceItemId(), true));
		icon.setAlignmentX(LEFT_ALIGNMENT);
		icon.setBorder(BorderFactory.createEmptyBorder(1, 1, 1, 1));
		icon.setToolTipText(plant.getName());
		return icon;
	}

	/** The tablet, worn item or spell icon this route is taken on, or null for neither. */
	private static ImageIcon travelIcon(FarmingStopAdvice stop, IconProvider icons)
	{
		if (icons == null)
		{
			return null;
		}
		if (stop.getTravelItemId() > 0)
		{
			// Cropped to the art: a lone icon needs no shared scale, and a tablet needs
			// every pixel at this size.
			return icons.getGearIcon(stop.getTravelItemId(), TRAVEL_ICON, true, true);
		}
		return icons.getSpriteIcon(stop.getTravelSpriteId(), TRAVEL_ICON);
	}

	/**
	 * A skipped stop's short status from its skip reason, plus time left where something is
	 * growing.
	 */
	private static String statusOf(FarmingStopAdvice stop)
	{
		FarmingSkipReason reason = stop.getSkipReason();
		String subject = stop.getSubject();
		boolean hasSubject = PanelText.hasText(subject);
		if (reason == FarmingSkipReason.STANDING_CROP)
		{
			// Left in on purpose, so no countdown: nothing is waited for.
			return hasSubject ? "keep the " + subject : reason.getLabel();
		}
		if (headingCarriesBecause(stop))
		{
			return stop.getBecause();
		}
		return (hasSubject ? subject + " " : "") + reasonText(reason, stop.getReadyAtEpochSec());
	}

	/**
	 * A skip reason's words, "skipped" when it has none, plus time left where something is
	 * growing. A standing crop is left in on purpose, so it gets no countdown.
	 */
	private static String reasonText(FarmingSkipReason reason, long readyAtEpochSec)
	{
		if (reason == FarmingSkipReason.STANDING_CROP)
		{
			return reason.getLabel();
		}
		return withCountdown(reason != null ? reason.getLabel() : "skipped", readyAtEpochSec);
	}

	/**
	 * Whether a skip's heading says its whole reason: a seed or level shortfall, whose
	 * clause ("no acorn", "toadflax needs 38 Farming") is short and more exact than the
	 * label. The row then draws no second line saying the same thing.
	 */
	private static boolean headingCarriesBecause(FarmingStopAdvice stop)
	{
		FarmingSkipReason reason = stop.getSkipReason();
		String because = stop.getBecause();
		return (reason == FarmingSkipReason.NO_SEED || reason == FarmingSkipReason.NEEDS_LEVEL) && PanelText.hasText(because);
	}

	/** "growing, ready in 2h 10m", or the label alone when no finish time is known. */
	private static String withCountdown(String label, long readyAtEpochSec)
	{
		String left = FarmingDurations.until(readyAtEpochSec, Instant.now().getEpochSecond());
		return left.isEmpty() ? label : label + ", ready in " + left;
	}

	private static Color headingColour(FarmingStopAdvice stop)
	{
		// Checked before the outcome: an overflow row is a VISIT (so the fold never hides
		// it) and would otherwise draw white like an ordinary stop.
		if (stop.getKind() == FarmingStopAdvice.Kind.OVERFLOW)
		{
			return COLOR_SHORTFALL;
		}
		// Optional banks draw light, not grey: grey means "nobody is going here".
		if (stop.getKind() == FarmingStopAdvice.Kind.BANK_OPTIONAL)
		{
			return PanelColors.ROUTE;
		}
		switch (stop.getOutcome())
		{
			case VISIT:
				return stop.isUncertain() ? COLOR_UNCERTAIN : Color.WHITE;
			case SKIP:
				return PanelColors.SKIPPED;
			default:
				return COLOR_SHORTFALL;
		}
	}

	private static Color detailColour(FarmingStopAdvice stop)
	{
		return stop.isUncertain() ? COLOR_UNCERTAIN : PanelColors.ROUTE;
	}

	/**
	 * A stop's plants, never null: a builder that sets no plants leaves the field null. Its
	 * acts, withdrawals and deposits default to empty lists, so they are read directly.
	 */
	private static List<FarmingPlantAdvice> plants(FarmingStopAdvice stop)
	{
		return PanelText.listOf(stop.getPlants());
	}

	private static List<FarmingPatchNote> setAside(FarmingStopAdvice stop)
	{
		return PanelText.listOf(stop.getSetAside());
	}

	/** A set-aside patch line, e.g. "Flower — growing, ready in 32m". */
	private static String patchNoteText(FarmingPatchNote aside)
	{
		return aside.getPatchName() + " — " + reasonText(aside.getReason(), aside.getReadyAtEpochSec());
	}

	/**
	 * Every structural input of the rebuilt rows, and nothing that ticks. Live values set in
	 * place (title, notes, worded countdowns) stay out, or each change would rebuild the
	 * wrapping rows and flicker.
	 *
	 * @param drawSkipped whether the skipped-stops fold is open
	 */
	private static List<Object> signatureOf(FarmingAdvice advice, Phase phase, boolean drawSkipped, boolean drawBanks)
	{
		// Each entry sits at a fixed position, so no two inputs can be mistaken for each other.
		List<Object> signature = new ArrayList<>();
		// The phase and both folds decide which rows and sections exist. So does the cut-off
		// for rows behind the player, which needs no entry of its own: it follows from the
		// phase and each stop's kind and outcome, all signed below.
		signature.add(phase);
		signature.add(drawSkipped);
		signature.add(drawBanks);
		RunsListView.addSignature(signature, advice);
		// Previewing a book with the same kit changes no item but must still rebuild.
		signature.add(advice.getCarryFor());
		signature.add(advice.getSpellbookOpen());
		List<List<Object>> stops = new ArrayList<>(advice.getStops().size());
		for (FarmingStopAdvice stop : advice.getStops())
		{
			stops.add(shapeOf(stop));
		}
		signature.add(stops);
		// The note can change alone (e.g. owning a ring of charos changes the coins note, not
		// the quantity).
		signature.add(shapesOf(PanelText.listOf(advice.getCarry())));
		signature.add(shapesOf(carryNow(advice)));
		signature.add(PanelText.listOf(advice.getUpgrades()));
		return signature;
	}

	/**
	 * A stop as its row is built. The finish instant stays in, never the worded countdown,
	 * and so does each set-aside line's reason, the tooltip set only on a rebuild. The landing
	 * goes, since no row draws it. The deposits are their item ids alone, since a deposit
	 * tile draws no count, so a harvest piling up does not redraw.
	 */
	private static List<Object> shapeOf(FarmingStopAdvice stop)
	{
		List<Integer> deposit = stop.getDeposit().stream().map(FarmingCarryItem::getItemId).collect(Collectors.toList());
		return List.of(stop.toBuilder().landing(null)
			// The list changes while the player stands at the bank, so the guard must see it.
			.withdraw(shapesOf(stop.getWithdraw())).deposit(List.of()).build(), deposit);
	}

	/**
	 * Carry lines as the panel draws them: without the count already carried, which no line
	 * shows. Availability stays, since it decides grid square versus seed-box line.
	 */
	private static List<FarmingCarryItem> shapesOf(List<FarmingCarryItem> items)
	{
		return items.stream().map(item -> item.withCarriedCount(0)).collect(Collectors.toList());
	}
}

package com.larryfarming.panel;

import java.awt.Color;
import java.util.function.Consumer;
import javax.swing.*;
import net.runelite.client.ui.FontManager;

/**
 * A clickable header line over content that shows only while open. Every fold on the
 * side panel is one of these, so their headers cannot drift apart.
 *
 * <p>The header can carry a suffix and colour of its owner's choosing, so a consequence
 * stays readable with the fold shut (see {@link TravelFold}).
 */
class Fold extends JPanel
{
	/** The header's arrows, which the runs list's rows share. */
	static final String SHUT = "▸";
	static final String OPEN = "▾";

	private final String title;
	private final JLabel toggle;
	private final JPanel content;

	private boolean open;
	private String suffix = "";
	private Color colour = PanelColors.HEADER;
	private Consumer<Boolean> openCallback;

	Fold(String title)
	{
		this.title = title;
		PanelText.stack(this);
		setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));

		toggle = new JLabel();
		toggle.setFont(FontManager.getRunescapeSmallFont());
		toggle.setAlignmentX(LEFT_ALIGNMENT);
		toggle.setBorder(BorderFactory.createEmptyBorder(0, 2, 3, 0));
		PanelText.onLeftClick(toggle, () ->
		{
			open = !open;
			showOpen();
			if (openCallback != null)
			{
				openCallback.accept(open);
			}
		});

		content = PanelText.stack();
		content.setBorder(BorderFactory.createEmptyBorder(2, 2, 0, 0));

		add(toggle);
		add(content);
		showOpen();
	}

	/** What the fold shows while open. */
	JPanel content()
	{
		return content;
	}

	/**
	 * Puts the remembered open state back on screen, without reporting a change.
	 *
	 * @param callback receives the fold's new state when the player opens or shuts it, or
	 *     null for nobody
	 */
	void restore(boolean open, Consumer<Boolean> callback)
	{
		this.open = open;
		this.openCallback = callback;
		showOpen();
	}

	/**
	 * Words after the title and the header's colour, kept while the fold is shut. Set in
	 * place, and only on a change, since the header relays out when set.
	 */
	void setHeader(String suffix, Color colour)
	{
		if (suffix.equals(this.suffix) && colour.equals(this.colour))
		{
			return;
		}
		this.suffix = suffix;
		this.colour = colour;
		showOpen();
	}

	/** Appends {@code words} to the header in amber while {@code on}, and nothing otherwise. */
	void warn(boolean on, String words)
	{
		setHeader(on ? words : "", on ? FarmingPanel.COLOR_DUE : PanelColors.HEADER);
	}

	private void showOpen()
	{
		content.setVisible(open);
		toggle.setText((open ? OPEN : SHUT) + " " + title + suffix);
		toggle.setForeground(colour);
		revalidate();
		repaint();
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingUpgrade;
import java.awt.*;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;

/**
 * One kind of farm-run gear advice as a boxed list: the gear to put on before setting off
 * ({@link FarmingUpgrade.Kind#EQUIP}), or the gear worth earning between runs
 * ({@link FarmingUpgrade.Kind#GOAL}). Hides itself when it has no rows.
 */
class GearList extends StretchPanel
{
	private static final int ROW_ICON = 20;
	/** Owned and worth putting on now. */
	private static final Color COLOR_EQUIP = ColorScheme.BRAND_ORANGE;

	private final FarmingUpgrade.Kind kind;

	GearList(FarmingUpgrade.Kind kind)
	{
		this.kind = kind;
		PanelColors.container(this);
		setVisible(false);
	}

	/**
	 * Redraws the rows of this list's kind. Called only when the upgrades have changed, since
	 * the caller guards structural rebuilds.
	 *
	 * @param width the width rows should wrap against, or 0 if not laid out yet
	 * @return whether any row was drawn, so the caller can hide the list's heading too
	 */
	boolean rebuild(List<FarmingUpgrade> upgrades, IconProvider icons, int width)
	{
		removeAll();
		List<FarmingUpgrade> rows = PanelText.listOf(upgrades).stream().filter(upgrade -> upgrade.getKind() == kind)
			.collect(Collectors.toList());
		setVisible(!rows.isEmpty());
		boolean divider = false;
		for (FarmingUpgrade upgrade : rows)
		{
			if (divider)
			{
				add(PanelColors.divider());
			}
			add(row(upgrade, icons, width));
			divider = true;
		}
		return !rows.isEmpty();
	}

	/** One line of the list. A GridBag lets the text wrap to the sidebar width. */
	private JPanel row(FarmingUpgrade upgrade, IconProvider icons, int width)
	{
		boolean equip = upgrade.getKind() == FarmingUpgrade.Kind.EQUIP;

		JPanel row = PanelText.panel(new GridBagLayout());
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 4));

		// Colour if owned, grey if not.
		ImageIcon sprite = icons != null && upgrade.getItemId() > 0
			? icons.getGearIcon(upgrade.getItemId(), ROW_ICON, equip, false) : null;
		// The engine words the whole sentence, so the row adds nothing to it.
		PanelText.addIconAndFill(row, GridBagConstraints.CENTER, sprite, 5,
			PanelText.small(upgrade.getDetail(), equip ? COLOR_EQUIP : PanelColors.HEADER));
		return FarmingPanel.sized(row, width);
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingAdvice;
import com.larryfarming.snapshot.FarmingHouse;
import java.util.function.BiConsumer;

/**
 * The side panel's house fold: what the player's house holds, as two columns of rows under
 * "Portals", "Portal Nexus" and "Garden", in a fixed order.
 *
 * <p>An item Larry has not seen is the player's to declare, ticked for built. An item he
 * has seen shows what he saw and takes no click: an eye for built, the padlock for not
 * built. A player with something they would rather Larry not use switches it off in Travel.
 *
 * <p>The header says how much of the house is still unseen, readable with the fold shut.
 *
 * <p>The rows are rebuilt only when what they show moves, so a refresh arriving before a
 * click's re-plan leaves the click on screen. Nothing here wraps, so a rebuild cannot
 * flicker.
 */
class HouseFold extends Fold
{
	private final RebuildGuard guard = new RebuildGuard();
	private final BiConsumer<String, String> send;

	/** @param send receives each ticked row as its config key and new value */
	HouseFold(BiConsumer<String, String> send)
	{
		super("Your house");
		this.send = send;
		setVisible(false);
	}

	/** Draws the fold's rows from the advice. Hidden for advice without them. */
	void show(FarmingAdvice advice)
	{
		FarmingHouse house = advice.getHouse();
		setVisible(house != null);
		if (house == null)
		{
			return;
		}
		// The header is set in place: a one-line label cannot flicker.
		setHeader(suffix(house.getSight()), PanelColors.HEADER);
		if (!guard.shouldRebuild(house.getGroups()))
		{
			return;
		}
		content().removeAll();
		content().add(SiteList.inGroups(house.getGroups(), send));
		content().revalidate();
		content().repaint();
	}

	private static String suffix(FarmingHouse.Sight sight)
	{
		switch (sight)
		{
			case NOT_SEEN:
				return ": not seen yet";
			case NEXUS_NOT_SEEN:
				return ": Nexus not opened yet";
			default:
				return "";
		}
	}
}

package com.larryfarming.panel;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.*;
import javax.swing.ImageIcon;
import javax.swing.SwingUtilities;
import net.runelite.api.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The item and interface sprites the side panel draws, fetched from the client and cached so
 * a rebuild never asks twice.
 *
 * <p>Every icon is handed out at its final size and fills in place when its pixels arrive,
 * so a row is laid out once.
 */
public class IconProvider
{
	private static final Logger log = LoggerFactory.getLogger(IconProvider.class);

	private final ItemManager itemManager;
	private final SpriteManager spriteManager;

	private final Map<String, ImageIcon> cache = new ConcurrentHashMap<>();

	private volatile Color inventoryPanelColour;
	private volatile boolean inventoryPanelColourAsked;

	/** The magic tab icon per spellbook, keyed by {@code Spellbook} name. */
	private final Map<String, ImageIcon> spellbookIcons = new ConcurrentHashMap<>();

	private static final int SPELLBOOK_ICON_SIZE = 16;

	/** Callback to repaint the panel when an async item sprite finishes loading. */
	private volatile Runnable onImageLoaded;

	public IconProvider(ItemManager itemManager, SpriteManager spriteManager)
	{
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
	}

	public void setOnImageLoaded(Runnable callback)
	{
		this.onImageLoaded = callback;
	}

	/**
	 * An item's sprite, drawn for a stack of {@code quantity} when {@code stackable}. Every
	 * item lookup goes through here and {@link #spriteAsync}.
	 */
	protected AsyncBufferedImage itemImage(int itemId, int quantity, boolean stackable)
	{
		return itemManager.getImage(itemId, quantity, stackable);
	}

	/**
	 * A game interface sprite, delivered to the callback once the client has decoded it.
	 * Never delivered when there is no client to decode it, which every caller already
	 * treats as "not loaded yet".
	 */
	protected void spriteAsync(int spriteId, int file, Consumer<BufferedImage> callback)
	{
		if (spriteManager != null)
		{
			spriteManager.getSpriteAsync(spriteId, file, callback);
		}
	}

	/**
	 * Pre-fetches the spellbook sprites. Call from the client thread. The panel reads the
	 * results on the EDT.
	 */
	@SuppressWarnings("deprecation") // SpriteID — gameval equivalent uses unreadable Jagex names
	public void loadSprites()
	{
		loadSpellbookIcon("STANDARD", SpriteID.TAB_MAGIC);
		loadSpellbookIcon("LUNAR", SpriteID.TAB_MAGIC_SPELLBOOK_LUNAR);
		loadSpellbookIcon("ARCEUUS", SpriteID.TAB_MAGIC_SPELLBOOK_ARCEUUS);
	}

	/** Fetches one spellbook sprite, once, into an icon handed out blank at full size. */
	private void loadSpellbookIcon(String book, int spriteId)
	{
		spellbookIcons.computeIfAbsent(book, b -> getSpriteIcon(spriteId, SPELLBOOK_ICON_SIZE));
	}

	/**
	 * The colour of the game's inventory panel, or null until the sprite has loaded.
	 *
	 * <p>Null is the normal first answer. The caller falls back to the flat container
	 * colour, and the repaint hook brings the real colour in once it lands.
	 *
	 * <p>Call <b>from the EDT</b> only. The asked flag is a plain check-then-set, so a
	 * caller on another thread could trigger a second fetch. On a {@code SpriteManager}
	 * cache hit the callback runs inline, so the averaging can run on the EDT inside a paint.
	 */
	@SuppressWarnings("deprecation") // SpriteID — gameval equivalent uses unreadable Jagex names
	public Color getInventoryPanelColour()
	{
		if (inventoryPanelColour != null)
		{
			return inventoryPanelColour;
		}
		if (!inventoryPanelColourAsked)
		{
			inventoryPanelColourAsked = true;
			spriteAsync(SpriteID.FIXED_MODE_SIDE_PANEL_BACKGROUND, 0, img ->
			{
				if (img == null)
				{
					return;
				}
				Color average = averageOfMiddle(img);
				if (average == null)
				{
					log.debug("Inventory panel sprite had no opaque middle to average");
					return;
				}
				SwingUtilities.invokeLater(() ->
				{
					inventoryPanelColour = average;
					repaintLater();
				});
			});
		}
		return null;
	}

	/**
	 * The mean colour of a sprite's middle, ignoring the outer quarter on every side.
	 *
	 * <p>The edges hold the panel's bevel decoration, which would skew the average.
	 * Mostly-transparent pixels are skipped so cut-away areas do not darken the result.
	 * Returns null when nothing in the middle is opaque.
	 */
	static Color averageOfMiddle(BufferedImage sprite)
	{
		int insetX = sprite.getWidth() / 4;
		int insetY = sprite.getHeight() / 4;
		long red = 0;
		long green = 0;
		long blue = 0;
		long counted = 0;
		for (int y = insetY; y < sprite.getHeight() - insetY; y++)
		{
			for (int x = insetX; x < sprite.getWidth() - insetX; x++)
			{
				int argb = sprite.getRGB(x, y);
				if ((argb >>> 24) < 128)
				{
					continue;
				}
				red += (argb >> 16) & 0xFF;
				green += (argb >> 8) & 0xFF;
				blue += argb & 0xFF;
				counted++;
			}
		}
		if (counted == 0)
		{
			return null;
		}
		return new Color((int) (red / counted), (int) (green / counted), (int) (blue / counted));
	}

	/**
	 * A sprite at the size asked for, handed back untouched when it is already that size.
	 *
	 * <p>This guards correctness, not speed. Spellbook teleport icons are 20×20 and differ
	 * mainly by a five-pixel letter (Salve graveyard's S, Fenkenstrain's F). Any smooth
	 * rescale smears that letter, so callers wanting a spellbook sprite ask for its native size.
	 */
	static BufferedImage fitTo(BufferedImage sprite, int size)
	{
		return sprite.getWidth() == size && sprite.getHeight() == size ? sprite : ImageUtil.resizeImage(squared(sprite), size, size);
	}

	/**
	 * The sprite centred on a transparent square as wide as its longer side, so scaling it
	 * to a square keeps its shape. A tall item cropped to its art, such as the ectophial,
	 * would otherwise be squashed flat.
	 */
	static BufferedImage squared(BufferedImage sprite)
	{
		int width = sprite.getWidth();
		int height = sprite.getHeight();
		if (width == height)
		{
			return sprite;
		}
		int side = Math.max(width, height);
		BufferedImage square = new BufferedImage(side, side, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = square.createGraphics();
		g.drawImage(sprite, (side - width) / 2, (side - height) / 2, null);
		g.dispose();
		return square;
	}

	/**
	 * Any game sprite by ID, at a fixed size. Returns a blank icon at full size that fills
	 * in place when the sprite loads, or null for an id &lt;= 0.
	 *
	 * <p>The panel rebuilds its rows only when the advice changes, so it never asks again
	 * for an icon that was missing at rebuild time. Publishing the instance up front lets
	 * the load land in a label already on screen. Every deferred-fill icon in this class
	 * relies on this rule.
	 *
	 * @param spriteId the game's sprite ID
	 * @param size     width and height in pixels
	 */
	public ImageIcon getSpriteIcon(int spriteId, int size)
	{
		return getSpriteIcon(spriteId, size, true);
	}

	/**
	 * The same sprite, drained of colour when the player cannot use what it stands for.
	 *
	 * @param held false to render in greyscale
	 */
	public ImageIcon getSpriteIcon(int spriteId, int size, boolean held)
	{
		if (spriteId <= 0)
		{
			return null;
		}
		// The callback only queues work for the EDT and never touches the cache, so it may
		// run inline inside computeIfAbsent. The map's bin lock is held while the load is
		// requested, which is safe because the loaders only queue work: none re-enters the
		// cache, and none blocks on another thread that could.
		return cache.computeIfAbsent("sprite:" + spriteId + ":" + size + (held ? "" : ":grey"), key ->
		{
			ImageIcon icon = new ImageIcon(new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB));
			spriteAsync(spriteId, 0, img ->
			{
				if (img == null)
				{
					return;
				}
				BufferedImage fitted = fitTo(img, size);
				BufferedImage sized = held ? fitted : ImageUtil.grayscaleImage(fitted);
				SwingUtilities.invokeLater(() ->
				{
					icon.setImage(sized);
					repaintLater();
				});
			});
			return icon;
		});
	}

	/**
	 * The magic tab icon for a spellbook.
	 *
	 * @param book "STANDARD", "LUNAR" or "ARCEUUS"
	 * @return the icon, blank until the sprite loads, or null for an unknown book
	 */
	public ImageIcon getSpellbookIcon(String book)
	{
		return book != null ? spellbookIcons.get(book) : null;
	}

	/**
	 * An item sprite at a fixed size, greyed out for gear the player has not earned yet,
	 * with the option of cropping the sprite's transparent margin first.
	 *
	 * <p>Cropping keeps a small icon legible by spending its pixels on the art. Use it only
	 * for a row showing one item at a time: cropping gives each sprite its own scale, which
	 * breaks a gear grid where a ring should look smaller than a cape.
	 *
	 * @param itemId     the item to draw
	 * @param size       width and height in pixels
	 * @param earned     false to render in greyscale
	 * @param fillSquare true to crop the transparent margin away before scaling
	 */
	public ImageIcon getGearIcon(int itemId, int size, boolean earned, boolean fillSquare)
	{
		return cache.computeIfAbsent("gear:" + itemId + ":" + size + ":" + earned + ":" + fillSquare,
			key -> styled(() -> itemImage(itemId, 1, false), "gear", itemId, art -> styleGear(art, size, earned, fillSquare)));
	}

	/**
	 * An icon of the item's sprite from {@code load}, styled now or once its pixels arrive,
	 * or null when the client cannot give one. Null is never cached (computeIfAbsent records
	 * no mapping for it), so a failed load is asked again next time.
	 */
	private ImageIcon styled(Supplier<BufferedImage> load, String kind, int itemId, UnaryOperator<BufferedImage> style)
	{
		BufferedImage sprite;
		try
		{
			sprite = load.get();
		}
		catch (RuntimeException e)
		{
			log.debug("Failed to load {} icon for item {}", kind, itemId, e);
			return null;
		}
		if (sprite == null)
		{
			return null;
		}
		ImageIcon icon = new ImageIcon(sprite);
		styleWhenLoaded(icon, sprite, style);
		return icon;
	}

	/**
	 * Gives the icon its sprite styled, now or once its pixels arrive.
	 *
	 * <p>Resizing and greyscaling read pixels an AsyncBufferedImage does not have yet, so
	 * styling waits for the load. It restyles the same ImageIcon in place because labels
	 * already hold this instance. Replacing it would leave a greyed item in full colour.
	 */
	private void styleWhenLoaded(ImageIcon icon, BufferedImage sprite, UnaryOperator<BufferedImage> style)
	{
		if (sprite instanceof AsyncBufferedImage)
		{
			AsyncBufferedImage async = (AsyncBufferedImage) sprite;
			async.onLoaded(() -> SwingUtilities.invokeLater(() ->
			{
				icon.setImage(style.apply(async));
				repaintLater();
			}));
		}
		else
		{
			icon.setImage(style.apply(sprite));
		}
	}

	/**
	 * An item sprite at the size the game draws it, drained of colour when the player has
	 * not got it.
	 *
	 * <p>Unresized on purpose, unlike {@link #getGearIcon}: a grid drawn as an inventory
	 * should hold the same 36×32 sprites the inventory does.
	 *
	 * @param held false to render in greyscale
	 */
	public ImageIcon getInventoryIcon(int itemId, boolean held)
	{
		return getInventoryIcon(itemId, 1, held);
	}

	/**
	 * The same sprite, drawn for a stack of this size.
	 *
	 * @param quantity how many, which changes the sprite for anything stackable
	 */
	public ImageIcon getInventoryIcon(int itemId, int quantity, boolean held)
	{
		int stack = Math.max(1, quantity);
		// A non-stackable item ignores the stackable flag and draws a single sprite. A held
		// item wraps the async image as-is; greying waits for the pixels and restyles the
		// same instance, since labels already hold it.
		return cache.computeIfAbsent("inv:" + itemId + ":" + stack + ":" + held, key -> styled(() -> itemImage(itemId, stack, stack > 1),
			"inventory", itemId, held ? UnaryOperator.identity() : ImageUtil::grayscaleImage));
	}

	private static BufferedImage styleGear(BufferedImage sprite, int size, boolean earned, boolean fillSquare)
	{
		BufferedImage styled = earned ? sprite : ImageUtil.grayscaleImage(sprite);
		return fitTo(fillSquare ? cropToArt(styled) : styled, size);
	}

	/**
	 * The sprite with its fully transparent margin cropped away.
	 *
	 * <p>The result shares pixels with the sprite, which {@code ItemManager} shares with
	 * every caller, so nothing may write to it.
	 *
	 * <p>A fully transparent sprite, such as an item not yet loaded, is returned untouched.
	 */
	static BufferedImage cropToArt(BufferedImage sprite)
	{
		int left = sprite.getWidth();
		int top = sprite.getHeight();
		int right = -1;
		int bottom = -1;
		for (int y = 0; y < sprite.getHeight(); y++)
		{
			for (int x = 0; x < sprite.getWidth(); x++)
			{
				if ((sprite.getRGB(x, y) >>> 24) == 0)
				{
					continue;
				}
				left = Math.min(left, x);
				right = Math.max(right, x);
				top = Math.min(top, y);
				bottom = Math.max(bottom, y);
			}
		}
		if (right < 0)
		{
			return sprite;
		}
		return sprite.getSubimage(left, top, right - left + 1, bottom - top + 1);
	}

	/** Runs the repaint hook, if one is set. EDT. */
	private void repaintLater()
	{
		Runnable repaint = onImageLoaded;
		if (repaint != null)
		{
			repaint.run();
		}
	}
}

package com.larryfarming.panel;

import java.awt.*;
import javax.swing.JComponent;
import javax.swing.JPanel;

/**
 * The colour of the game's inventory panel, painted behind the slots of an item grid.
 *
 * <p>Only slot cells are filled. The gaps between them keep the panel's own background.
 *
 * <p>A flat colour, not the sprite: the inventory sprite carries a bevel and shading that
 * show up as artifacts when tiled or scaled into a sidebar grid. The colour still comes from
 * the sprite so it follows any change the game makes.
 */
class InventoryBackdrop extends JPanel
{
	/**
	 * Client-property key marking a child as a slot rather than a blank padding out a row.
	 * Blanks stay unfilled.
	 *
	 * <p>Stored on the child, not in a side list, so removing a child can never leave a stale
	 * entry that paints a rectangle where it used to be.
	 */
	private static final String SLOT = "larryfarming.inventorySlot";

	private IconProvider icons;

	InventoryBackdrop(LayoutManager layout)
	{
		super(layout);
		// Transparent: paintComponent fills only the slots.
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
	}

	/**
	 * Sets the colour source on each rebuild. Not a constructor argument because some grids
	 * are built before {@code LarryPlugin.startUp} creates the {@link IconProvider}.
	 */
	void setIcons(IconProvider icons)
	{
		this.icons = icons;
	}

	/** Adds a cell that should have the game's panel colour behind it. */
	void addSlot(JComponent slot)
	{
		slot.putClientProperty(SLOT, Boolean.TRUE);
		add(slot);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Color panel = icons == null ? null : icons.getInventoryPanelColour();
		// Fallback until the sprite loads (every first paint of a session).
		g.setColor(panel == null ? PanelColors.CONTAINER_BG : panel);
		// Reads x/y/width/height directly: getBounds() allocates a Rectangle per child, and
		// this runs on every snapshot's repaint.
		for (int i = 0, count = getComponentCount(); i < count; i++)
		{
			Component child = getComponent(i);
			if (!(child instanceof JComponent) || ((JComponent) child).getClientProperty(SLOT) == null)
			{
				continue;
			}
			int width = child.getWidth();
			int height = child.getHeight();
			if (width > 0 && height > 0)
			{
				g.fillRect(child.getX(), child.getY(), width, height);
			}
		}
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingCarryItem;
import java.awt.*;
import javax.swing.ImageIcon;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * One inventory square: a sprite, its stack count, and a seed tag along the bottom.
 *
 * <p>Painted by hand because a Swing label puts its text beside the icon, and the count and
 * tag both belong on top of the sprite.
 *
 * <p>Shared by the packing grid ({@link CarryView}) and the bank rows so both read as the
 * same inventory.
 */
class ItemSquare extends JPanel
{
	/**
	 * An item sprite (36×32) plus a margin. Sprites draw at full size because shrunken seed
	 * sprites are hard to tell apart.
	 */
	static final int SIZE = 42;
	static final int GAP = 3;

	/** The game's own stack-count colour. */
	private static final Color COLOR_COUNT = Color.YELLOW;
	/** The seed tag, drawn over a dark shadow that keeps it readable on a pale sprite. */
	private static final Color COLOR_TAG = Color.WHITE;

	private final ImageIcon sprite;
	private final String count;
	private final String tag;

	ItemSquare(ImageIcon sprite, String count, String tag)
	{
		this.sprite = sprite;
		this.count = count;
		this.tag = tag;
		// Transparent so the InventoryBackdrop slot colour shows through.
		setOpaque(false);
		setFont(FontManager.getRunescapeSmallFont());
	}

	/**
	 * The square for a packing or bank line, at full size and without a border.
	 *
	 * @param owned whether to draw the sprite in colour rather than greyscale
	 */
	static ItemSquare of(FarmingCarryItem item, IconProvider icons, boolean owned)
	{
		ImageIcon sprite = icons != null && item.getItemId() > 0 ? icons.getInventoryIcon(item.getItemId(), item.getQuantity(), owned)
			: null;
		// The game draws the count into the sprite for stacks of two or more. Only a single
		// item needs one drawn here.
		ItemSquare cell = new ItemSquare(sprite, item.getQuantity() == 1 ? "1" : null, item.getTag());
		Dimension size = new Dimension(SIZE, SIZE);
		cell.setPreferredSize(size);
		cell.setMinimumSize(size);
		return cell;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (sprite != null)
		{
			sprite.paintIcon(this, g, (getWidth() - sprite.getIconWidth()) / 2, (getHeight() - sprite.getIconHeight()) / 2);
		}
		if (count != null)
		{
			g.setFont(getFont());
			g.setColor(COLOR_COUNT);
			g.drawString(count, 3, g.getFontMetrics().getAscent() + 1);
		}
		if (tag != null && !tag.isEmpty())
		{
			// Bottom edge, so it never collides with the count at the top.
			g.setFont(getFont());
			PanelText.drawShadowed(g, tag, 2, getHeight() - 2, COLOR_TAG);
		}
	}
}

package com.larryfarming.panel;

import com.larryfarming.farming.FarmingPlanner;
import com.larryfarming.snapshot.FarmingAdvice;
import java.awt.*;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * The sidebar: the farm run as last planned, drawn by {@link FarmingPanel}.
 *
 * <p>Redraws when the planner publishes new advice. A ticker re-words the countdowns between
 * plans, so "ready in" lines keep moving while nothing in the game changes.
 */
public class LarryPanel extends PluginPanel
{
	/** Scrollbar width plus the right border and padding of the RuneLite sidebar icons. */
	private static final int SIDEBAR_TRIM = 14;
	/** The content width. Anything wider runs under the sidebar icons. */
	static final int CONTENT_WIDTH = PluginPanel.PANEL_WIDTH - SIDEBAR_TRIM;

	/** How often the countdowns are re-worded between plans. */
	private static final int COUNTDOWN_TICK_MS = 15_000;

	private final FarmingPanel farmingPanel;

	/** Re-words the countdowns between plans; runs only while the panel is on screen. */
	private final Timer countdownTicker;

	private volatile FarmingPlanner planner;
	private volatile IconProvider iconProvider;

	/** The advice version last handed to the EDT; -1 forces the next refresh through. */
	private long lastAdviceVersion = -1;

	/**
	 * While no account is logged in the panel asks the player to log in, whatever the planner
	 * still holds for the account that left. Volatile: set on the client thread, read by the
	 * ticker on the EDT.
	 */
	private volatile boolean loggedOut = true;

	/** The advice on screen, re-shown by the ticker. EDT only. */
	private FarmingAdvice shown;

	public LarryPanel(FarmingPanel farmingPanel)
	{
		super(false);
		this.farmingPanel = farmingPanel;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		farmingPanel.setAlignmentX(LEFT_ALIGNMENT);
		JScrollPane scroll = new JScrollPane(wrapForScrolling(farmingPanel));
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);

		// Started in addNotify, not here: a panel built but never shown would otherwise tick
		// forever through a dropped classloader.
		countdownTicker = new Timer(COUNTDOWN_TICK_MS, e -> farmingPanel.display(shown, iconProvider));
		farmingPanel.display(null, null);
	}

	/** The planner whose advice the panel draws, or null to draw none. */
	public void setPlanner(FarmingPlanner planner)
	{
		this.planner = planner;
		this.lastAdviceVersion = -1;
	}

	public void setIconProvider(IconProvider iconProvider)
	{
		this.iconProvider = iconProvider;
	}

	/**
	 * The sidebar opening re-shows the panel, and its rows wrapped against the width from when
	 * it was last on screen. Forget the last build so the redraw re-measures.
	 */
	@Override
	public void onActivate()
	{
		farmingPanel.forgetLastBuild();
		farmingPanel.display(shown, iconProvider);
	}

	@Override
	public void addNotify()
	{
		super.addNotify();
		countdownTicker.start();
	}

	@Override
	public void removeNotify()
	{
		countdownTicker.stop();
		super.removeNotify();
	}

	/** Stops the ticker. Call when tearing the panel down. */
	public void dispose()
	{
		countdownTicker.stop();
	}

	/**
	 * Draws the planner's advice if a new plan was published since the last call. Call from
	 * the thread that drives the planner, once per tick. The drawing runs on the EDT.
	 */
	public void refresh()
	{
		FarmingPlanner current = planner;
		if (current == null || loggedOut)
		{
			return;
		}
		long version = current.getAdviceVersion();
		if (version == lastAdviceVersion)
		{
			return;
		}
		lastAdviceVersion = version;
		FarmingAdvice advice = current.getAdvice();
		SwingUtilities.invokeLater(() -> show(advice));
	}

	/**
	 * Asks the player to log in. The planner still holds the account that left until the
	 * next login replaces it, so its advice stays off screen until then.
	 */
	public void showLoggedOut()
	{
		loggedOut = true;
		SwingUtilities.invokeLater(() -> show(null));
	}

	/** An account has loaded: the next {@link #refresh} draws its plan. */
	public void showLoggedIn()
	{
		if (loggedOut)
		{
			loggedOut = false;
			lastAdviceVersion = -1;
		}
	}

	/** Repaints after an icon arrives. Safe from any thread. */
	public void iconLoaded()
	{
		SwingUtilities.invokeLater(this::repaint);
	}

	private void show(FarmingAdvice advice)
	{
		shown = advice;
		farmingPanel.display(advice, iconProvider);
	}

	/**
	 * Packs a panel to the top of its scroll pane at a fixed width, so wrapping text
	 * knows where to break and short content does not stretch to fill the viewport.
	 */
	private static JPanel wrapForScrolling(JPanel content)
	{
		JPanel fixedWidth = new FixedWidthPanel();
		fixedWidth.setLayout(new BoxLayout(fixedWidth, BoxLayout.Y_AXIS));
		fixedWidth.setBackground(ColorScheme.DARK_GRAY_COLOR);
		fixedWidth.add(content);

		JPanel northWrapper = new ScrollAnchoredPanel();
		northWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		northWrapper.add(fixedWidth, BorderLayout.NORTH);
		return northWrapper;
	}

	/**
	 * The scroll pane's view, which stops its contents from scrolling the viewport.
	 *
	 * <p>Rows rebuild while the player reads, and Swing components ask to be scrolled into
	 * view when added or focused. {@code scrollRectToVisible} propagates up the parent chain,
	 * so swallowing it here, directly below the viewport, blocks every such request. The
	 * scrollbar and mouse wheel drive the viewport directly and still work.
	 */
	private static class ScrollAnchoredPanel extends JPanel
	{
		ScrollAnchoredPanel()
		{
			super(new BorderLayout());
		}

		@Override
		public void scrollRectToVisible(Rectangle aRect)
		{
			// Empty on purpose. See class doc.
		}
	}

	/**
	 * A JPanel whose preferred width is {@link #CONTENT_WIDTH}, so text does not render
	 * behind the RuneLite sidebar icon strip.
	 */
	private static class FixedWidthPanel extends JPanel
	{
		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(CONTENT_WIDTH, super.getPreferredSize().height);
		}
	}
}

package com.larryfarming.panel;

import com.larryfarming.LarryPlugin;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.externalplugins.PluginHubManifest;

/**
 * The plugin's version as the Plugin Hub lists it, or "dev" for a build the Hub did not ship.
 */
public final class LarryVersion
{
	/** The version as drawn: "v" and the Hub's version, or "dev". */
	public static final String SHOWN = shown(hubVersion());

	private LarryVersion()
	{
	}

	static String shown(String version)
	{
		if (version == null || version.isBlank())
		{
			return "dev";
		}
		return Character.isDigit(version.charAt(0)) ? "v" + version : version;
	}

	/** Null outside a Hub build: the Hub's class loader is what carries the listing. */
	private static String hubVersion()
	{
		PluginHubManifest.DisplayData listing = ExternalPluginManager.getDisplayData(LarryPlugin.class);
		return listing == null ? null : listing.getVersion();
	}
}

