package com.larryfarming.panel;

import java.awt.*;
import javax.swing.Icon;

/**
 * A small drawing centred in an icon of a size the caller picks, so it can stand where
 * another icon would, such as a checkbox's.
 */
abstract class Mark implements Icon
{
	private final Color colour;
	private final int markWidth;
	private final int markHeight;
	private final int width;
	private final int height;

	/** A mark {@code markWidth} by {@code markHeight}, in an icon at least that size. */
	Mark(Color colour, int markWidth, int markHeight, int width, int height)
	{
		this.colour = colour;
		this.markWidth = markWidth;
		this.markHeight = markHeight;
		this.width = Math.max(markWidth, width);
		this.height = Math.max(markHeight, height);
	}

	/** Draws the mark with its bounding box's top-left corner at x, y. */
	abstract void drawAt(Graphics2D g, int x, int y, Color colour);

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			drawAt(g2, x + (width - markWidth) / 2, y + (height - markHeight) / 2, colour);
		}
		finally
		{
			g2.dispose();
		}
	}

	@Override
	public int getIconWidth()
	{
		return width;
	}

	@Override
	public int getIconHeight()
	{
		return height;
	}
}

package com.larryfarming.panel;

import java.awt.*;

/**
 * The padlock that marks a setting the player cannot change: drawn on a locked setting
 * square, and in a locked row's checkbox place.
 *
 * <p>One drawing for both, so a locked square and a locked row read as the same thing.
 */
final class Padlock extends Mark
{
	/** The lock's own width and height, shackle to base. */
	static final int WIDTH = 8;
	static final int HEIGHT = 11;

	private static final Stroke STROKE = new BasicStroke(1.4f);
	private static final Color KEYHOLE = new Color(40, 40, 40);

	/**
	 * A padlock icon that takes up {@code width} by {@code height}, with the lock centred in
	 * it, so it can stand where another icon would.
	 */
	Padlock(Color colour, int width, int height)
	{
		super(colour, WIDTH, HEIGHT, width, height);
	}

	/** Draws the lock with its shackle's top-left corner at x, y. */
	static void draw(Graphics2D g, int x, int y, Color colour)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(colour);
		g.setStroke(STROKE);
		g.drawArc(x + 1, y, 6, 8, 0, 180);
		g.drawLine(x + 1, y + 4, x + 1, y + 5);
		g.drawLine(x + 7, y + 4, x + 7, y + 5);
		g.fillRoundRect(x, y + 5, 8, 6, 2, 2);
		g.setColor(KEYHOLE);
		g.fillRect(x + 3, y + 7, 2, 2);
	}

	@Override
	void drawAt(Graphics2D g, int x, int y, Color colour)
	{
		draw(g, x, y, colour);
	}
}

package com.larryfarming.panel;

import java.awt.Color;
import java.awt.Dimension;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;

/**
 * Shared visual constants used across panel classes. Colors that appear in
 * two or more panels live here; single-use colors stay in their panel file.
 */
final class PanelColors
{
	/** Muted text for section headings and labels. */
	static final Color HEADER = ColorScheme.LIGHT_GRAY_COLOR;
	/** Light route text: a stop's travel line, an offered bank, a due run's status. */
	static final Color ROUTE = ColorScheme.LIGHT_GRAY_COLOR;
	/** Grey means "not possible": a skipped stop, or a run not unlocked or with no route. */
	static final Color SKIPPED = ColorScheme.MEDIUM_GRAY_COLOR;
	/** Muted list content, such as the unresolved-items line. */
	static final Color META = new Color(130, 130, 130);
	/** Divider line between items in a container. */
	static final Color DIVIDER = new Color(55, 55, 55);
	static final Color CONTAINER_BG = ColorScheme.DARKER_GRAY_COLOR.darker();
	static final Color CONTAINER_BORDER = ColorScheme.MEDIUM_GRAY_COLOR.darker();
	/** The level a locked setting needs, in the game's dark stack-count yellow. */
	static final Color LEVEL = new Color(178, 140, 35);

	private PanelColors()
	{
	}

	/** Makes {@code panel} a list container: a vertical stack on a filled, outlined box. */
	static <T extends JPanel> T container(T panel)
	{
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(CONTAINER_BG);
		panel.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		panel.setBorder(BorderFactory.createLineBorder(CONTAINER_BORDER, 1));
		return panel;
	}

	/** A 1px horizontal divider line for use inside list containers. */
	static JPanel divider()
	{
		JPanel line = new JPanel();
		line.setBackground(DIVIDER);
		line.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
		line.setPreferredSize(new Dimension(0, 1));
		return line;
	}
}

package com.larryfarming.panel;

import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.*;
import javax.swing.text.DefaultCaret;
import net.runelite.client.ui.FontManager;

/** The panel's one wrapping-text component, and the small builders every view shares. */
final class PanelText
{
	private PanelText()
	{
	}

	/**
	 * A read-only, word-wrapping text area that draws like a label.
	 *
	 * <p>Wraps to its parent's width. A {@code JLabel} cannot wrap without HTML, which
	 * measures its height wrongly inside a {@code BoxLayout}.
	 */
	static JTextArea textArea(String text, Color color, Font font)
	{
		JTextArea area = new JTextArea(text);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setEditable(false);
		area.setFocusable(false);
		area.setOpaque(false);
		area.setForeground(color);
		area.setFont(font);
		area.setAlignmentX(Component.LEFT_ALIGNMENT);
		area.setBorder(BorderFactory.createEmptyBorder());
		area.setCaret(new NonScrollingCaret());
		return area;
	}

	static JLabel label(String text, Font font, Color colour)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(colour);
		return label;
	}

	static JLabel label(String text, Color colour)
	{
		return label(text, FontManager.getRunescapeSmallFont(), colour);
	}

	/** Draws text with a black drop shadow one pixel down and right, as the game draws its item text. */
	static void drawShadowed(Graphics g, String text, int x, int y, Color colour)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(colour);
		g.drawString(text, x, y);
	}

	/** {@link #textArea} in the small font, which nearly every line of the panel uses. */
	static JTextArea small(String text, Color color)
	{
		return textArea(text, color, FontManager.getRunescapeSmallFont());
	}

	/** Lays {@code panel} out as a transparent, left-aligned vertical stack. */
	static <T extends JPanel> T stack(T panel)
	{
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	/** A new {@link #stack}. */
	static JPanel stack()
	{
		return stack(new JPanel());
	}

	/**
	 * A new transparent, left-aligned panel on {@code layout}. The alignment matters only in
	 * a vertical stack; any other parent ignores it.
	 */
	static JPanel panel(LayoutManager layout)
	{
		JPanel panel = new JPanel(layout);
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	/**
	 * Constraints for a row's margin icon: the first cell, pinned to the top left. The
	 * text column then goes in through {@link #addFill}.
	 */
	static GridBagConstraints marginConstraints()
	{
		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridx = 0;
		gbc.gridy = 0;
		gbc.anchor = GridBagConstraints.NORTHWEST;
		return gbc;
	}

	/** Adds a row's text column at {@code column}, taking the spare width. */
	static void addFill(JPanel row, GridBagConstraints gbc, int column, Component text)
	{
		gbc.gridx = column;
		gbc.weightx = 1.0;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		row.add(text, gbc);
	}

	/** An optional icon on the left of the row, then text that fills and wraps the rest. */
	static void addIconAndFill(JPanel row, int anchor, ImageIcon sprite, int gap, Component text)
	{
		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridy = 0;
		gbc.anchor = anchor;
		if (sprite != null)
		{
			JLabel icon = new JLabel(sprite);
			icon.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, gap));
			gbc.gridx = 0;
			row.add(icon, gbc);
		}
		addFill(row, gbc, sprite == null ? 0 : 1, text);
	}

	/** Gives {@code target} a hand cursor and runs {@code action} on each left click. */
	static void onLeftClick(Component target, Runnable action)
	{
		target.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		target.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					action.run();
				}
			}
		});
	}

	/** Escapes text for an HTML label. */
	static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Whether there is anything to show: not null and not blank. */
	static boolean hasText(String text)
	{
		return text != null && !text.isBlank();
	}

	/** The list, or an empty one for null. */
	static <T> List<T> listOf(List<T> list)
	{
		return list != null ? list : List.of();
	}

	/**
	 * Caret that never scrolls its enclosing scroll pane.
	 *
	 * <p>{@code DefaultCaret.adjustVisibility()} calls {@code scrollRectToVisible()}
	 * whenever a rebuilt text component is added. The request bubbles up to the
	 * sidebar's {@code JScrollPane}, which jumps to the new component and loses the
	 * player's scroll position. Panel text is never editable or focusable, so there
	 * is no caret worth following.
	 */
	static final class NonScrollingCaret extends DefaultCaret
	{
		@Override
		protected void adjustVisibility(Rectangle nloc)
		{
			// Empty on purpose: never move the viewport.
		}
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingPatchPick;
import com.larryfarming.snapshot.FarmingSettingChoice;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.swing.*;
import net.runelite.api.gameval.ItemID;

/**
 * The herb farms' allotments and flower patches: a row per farm with a square per patch,
 * drawn as its pick, and under the row the picker of the patch opened. One picker is open at
 * a time, and its square takes the gold outline that marks what is current.
 *
 * <p>Opening and closing a picker rebuilds this block alone. It holds no wrapping text, so
 * the rebuild cannot flicker.
 */
final class PatchPicks extends JPanel
{
	private static final int LABEL_WIDTH = 58;
	private static final int BADGE_SIZE = 14;

	private final List<FarmingPatchPick> picks;
	private final IconProvider icons;
	private final BiConsumer<String, String> send;
	/** Hears which patch's picker is open, or null, so a rebuild of the list reopens it. */
	private final Consumer<String> remember;
	private String open;

	PatchPicks(List<FarmingPatchPick> picks, String open, IconProvider icons, BiConsumer<String, String> send, Consumer<String> remember)
	{
		this.picks = picks;
		this.open = open;
		this.icons = icons;
		this.send = send;
		this.remember = remember;
		PanelText.stack(this);
		build();
	}

	/** The picks come farm by farm, so a farm's row ends where the next farm's begins. */
	private void build()
	{
		removeAll();
		int start = 0;
		for (int i = 1; i <= picks.size(); i++)
		{
			if (i == picks.size() || !picks.get(i).getFarm().equals(picks.get(start).getFarm()))
			{
				List<FarmingPatchPick> farm = picks.subList(start, i);
				List<JComponent> squares = new ArrayList<>();
				for (FarmingPatchPick patch : farm)
				{
					squares.add(patchSquare(patch));
				}
				JLabel name = PanelText.label(farm.get(0).getFarm(), PanelColors.HEADER);
				name.setPreferredSize(new Dimension(LABEL_WIDTH, ItemSquare.SIZE));
				add(row(name, SettingGrid.grid(squares, icons, squares.size())));
				for (FarmingPatchPick patch : farm)
				{
					if (patch.getKey().equals(open))
					{
						add(picker(patch));
					}
				}
				start = i;
			}
		}
		revalidate();
		repaint();
	}

	private void show(String key)
	{
		open = key;
		remember.accept(key);
		build();
	}

	/** The patch as picked: its crop at full colour, or faint and tagged OFF, with a bucket for compost. */
	private SettingSquare patchSquare(FarmingPatchPick patch)
	{
		FarmingSettingChoice picked = patch.getOptions().stream().filter(FarmingSettingChoice::isOn).findFirst().orElse(patch.getOptions().get(0));
		boolean on = picked.getItemId() > 0;
		ImageIcon sprite = icons == null || !on ? null : icons.getInventoryIcon(picked.getItemId(), true);
		SettingSquare square = new SettingSquare(sprite, null, picked.getTag(), picked.getLevel(), false, on, false);
		// A pick above the player's level plants once they reach it, so it keeps its colour.
		if (on && picked.isLocked())
		{
			square.showLevel();
		}
		if (icons != null && patch.isComposting())
		{
			square.setBadge(icons.getGearIcon(ItemID.BUCKET_COMPOST, BADGE_SIZE, true, true));
		}
		boolean opened = patch.getKey().equals(open);
		// The patch square summarises the pick, so it takes no green on-outline: gold while
		// its picker is open, the mark of what is current.
		square.setBorder(opened ? BorderFactory.createLineBorder(FarmingPanel.COLOR_DUE) : BorderFactory.createEmptyBorder(1, 1, 1, 1));
		square.setToolTipText(patch.getTitle() + ": " + picked.getLabel() + (patch.isComposting() ? ", for compost" : ""));
		PanelText.onLeftClick(square, () -> show(opened ? null : patch.getKey()));
		return square;
	}

	/**
	 * The open patch's picker: Off and its crops, the pick outlined green. A patch beside a
	 * compost bin has For compost beside the last crop, so it costs no row of its own.
	 */
	private JPanel picker(FarmingPatchPick patch)
	{
		JPanel picker = PanelText.stack();
		picker.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 2, 0, 0, FarmingPanel.COLOR_DUE),
			BorderFactory.createEmptyBorder(2, 6, 6, 0)));
		picker.add(SiteList.caption(patch.getTitle(), 0));
		List<JComponent> options = new ArrayList<>();
		for (FarmingSettingChoice option : patch.getOptions())
		{
			SettingSquare square = SettingGrid.square(option, icons);
			square.outlineWhileLocked();
			if (!option.isLocked())
			{
				PanelText.onLeftClick(square, () ->
				{
					// The pick saved again would turn a quiet default into the player's choice.
					if (!option.isOn())
					{
						send.accept(patch.getKey(), option.getKey());
					}
					show(null);
				});
			}
			options.add(square);
		}
		if (patch.getCompostKey() == null)
		{
			picker.add(SettingGrid.grid(options, icons));
			return picker;
		}
		JComponent last = options.remove(options.size() - 1);
		picker.add(SettingGrid.grid(options, icons));
		JCheckBox compost = FarmingPanel.checkbox("For compost", 0);
		compost.setSelected(patch.isForCompost());
		compost.setToolTipText("Plant only while your compost is low");
		compost.addActionListener(e -> send.accept(patch.getCompostKey(), String.valueOf(compost.isSelected())));
		JPanel lastRow = row(SettingGrid.grid(List.of(last), icons, 1), compost);
		lastRow.setBorder(BorderFactory.createEmptyBorder(ItemSquare.GAP, 0, 0, 0));
		picker.add(lastRow);
		return picker;
	}

	/** A line of the block: the lead, then the rest, each at its own width so no grid stretches. */
	private static JPanel row(JComponent lead, JComponent rest)
	{
		JPanel row = PanelText.panel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		row.setBorder(BorderFactory.createEmptyBorder(0, 0, ItemSquare.GAP, 0));
		row.add(lead);
		row.add(Box.createHorizontalStrut(ItemSquare.GAP * 2));
		row.add(rest);
		row.setMaximumSize(new Dimension(Short.MAX_VALUE, ItemSquare.SIZE + ItemSquare.GAP));
		return row;
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingSettingPick;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JComboBox;
import net.runelite.client.ui.FontManager;

/**
 * A setting that takes one of many values, as a dropdown of the options' labels in their
 * fixed order. Picking one sends its value; a selection made in code never does, so a
 * refresh cannot write a setting back.
 *
 * <p>The side panel's one dropdown: a RuneLite combo box in the small font that never takes
 * the focus.
 */
class PickDropdown extends JComboBox<String>
{
	private final DefaultComboBoxModel<String> model;
	private final BiConsumer<String, String> send;
	private final List<String> values = new ArrayList<>();
	private List<FarmingSettingPick.Option> shownOptions = List.of();
	private String key;
	/** True while the dropdown is changed in code, so its selection events are not a pick. */
	private boolean updating;

	/** @param send receives the setting's key and the picked value */
	PickDropdown(BiConsumer<String, String> send)
	{
		super(new DefaultComboBoxModel<>());
		// The model handed to super just above, kept typed for refilling.
		this.model = (DefaultComboBoxModel<String>) getModel();
		this.send = send;
		setFont(FontManager.getRunescapeSmallFont());
		setFocusable(false);
		addActionListener(e -> picked());
	}

	/** Shows this setting, refilling the list only when its options have changed. */
	void show(FarmingSettingPick pick)
	{
		updating = true;
		try
		{
			key = pick.getKey();
			setToolTipText(pick.getHint());
			if (!pick.getOptions().equals(shownOptions))
			{
				shownOptions = List.copyOf(pick.getOptions());
				model.removeAllElements();
				values.clear();
				for (FarmingSettingPick.Option option : shownOptions)
				{
					model.addElement(option.getLabel());
					values.add(option.getValue());
				}
			}
			int at = values.indexOf(pick.getSelected());
			if (at >= 0 && at != getSelectedIndex())
			{
				setSelectedIndex(at);
			}
		}
		finally
		{
			updating = false;
		}
	}

	/** The value picked, or null when nothing is. */
	String selectedValue()
	{
		int at = getSelectedIndex();
		return at >= 0 && at < values.size() ? values.get(at) : null;
	}

	private void picked()
	{
		String value = selectedValue();
		if (updating || value == null || key == null)
		{
			return;
		}
		send.accept(key, value);
	}
}

package com.larryfarming.panel;

import java.util.Objects;

/**
 * Gates structural rebuilds of a Swing container so it recreates its children
 * only when its <em>structure</em> changes, not on every per-tick refresh.
 *
 * <p>The sidebar refreshes on every snapshot (one per game event). A freshly
 * added wrapping {@code JTextArea} reports a one-line preferred height until
 * layout assigns its width, then re-wraps on the next pass. Recreating it every
 * tick therefore makes its height oscillate and the panel flicker. Keeping the
 * component alive keeps its width and wrapped height stable.
 *
 * <p>Usage: build a value-equality <em>signature</em> from the structural inputs
 * only (row identities, text, met/unmet state). Progress values change
 * continuously and belong in in-place updates, <strong>not</strong> in the
 * signature. Rebuild only when the signature changes:
 *
 * <pre>{@code
 * if (guard.shouldRebuild(rowSignature(rows))) {
 *     container.removeAll();
 *     // ... add rows ...
 *     container.revalidate();
 *     container.repaint();
 * }
 * }</pre>
 *
 * <p>A signature is typically a list of value objects compared by equals: the
 * snapshot's own values with their ticking fields taken out. See
 * {@code FarmingPanel.signatureOf}.
 *
 * <p>Not thread-safe. Use only on the Swing EDT.
 */
final class RebuildGuard
{
	/** Signature of the last rebuild, or null before the first one. */
	private Object lastSignature;

	/**
	 * Returns true and records {@code signature} when it differs from the last
	 * one. Returns false when nothing structural changed, and the caller updates
	 * dynamic values in place instead.
	 *
	 * <p>A caller that builds its children at construction time must prime the
	 * guard with the initial signature, or the first refresh rebuilds needlessly.
	 */
	boolean shouldRebuild(Object signature)
	{
		if (Objects.equals(lastSignature, signature))
		{
			return false;
		}
		lastSignature = signature;
		return true;
	}

	/**
	 * Clears the recorded signature so the next {@link #shouldRebuild} call
	 * forces a rebuild. Call it whenever the container is emptied outside the
	 * guard, such as on a null snapshot.
	 */
	void reset()
	{
		lastSignature = null;
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.*;
import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The side panel's RUNS section: one row per run with its status, and under each row the
 * settings that decide what the run plants.
 *
 * <p>Clicking a row opens or shuts its settings. A run one setting switches carries that
 * checkbox on its row instead, and a click anywhere on its row flips the box.
 */
class RunsListView extends JPanel
{
	/** A run switched off: the light text faded, as an unticked square fades its sprite. */
	static final Color COLOR_OFF = new Color(ColorScheme.LIGHT_GRAY_COLOR.getRed(), ColorScheme.LIGHT_GRAY_COLOR.getGreen(),
		ColorScheme.LIGHT_GRAY_COLOR.getBlue(), 90);
	/** An opened run and its settings share this, so they read as one block. */
	private static final Color COLOR_OPEN = ColorScheme.DARKER_GRAY_COLOR;
	/** {@code RunStatus} names, as the runs list carries them. */
	static final String STATUS_DUE = "DUE";
	private static final String STATUS_LOCKED = "LOCKED";

	private final JPanel container;
	private final BiConsumer<String, String> send;

	/**
	 * The runs whose settings are open, by run id. Kept across rebuilds, so a re-plan after a
	 * click leaves the run open; the panel's own, not saved.
	 */
	private final Set<String> openRuns = new HashSet<>();

	/** The key of the patch whose picker is open, or null; kept across rebuilds as above. */
	private String openPick;

	/**
	 * The detail label of each run row, by run id. The engine words this countdown itself,
	 * so each refresh copies the newest text onto the existing label. The label does not
	 * wrap, so it stays out of the guard's signature.
	 */
	private final Map<String, JLabel> runDetails = new HashMap<>();

	/**
	 * The paused line under each run row, by run id. Its stock count changes with every
	 * bucket reading, so only the line's wording without its numbers is in the signature, and
	 * each refresh copies the newest text onto the existing area.
	 */
	private final Map<String, JTextArea> pausedLines = new HashMap<>();

	/** The compost stock beside the thresholds, by run id; updated in place as {@link #pausedLines} are. */
	private final Map<String, JLabel> stockedCounts = new HashMap<>();

	private final Runnable stopCompost;

	/**
	 * @param send receives each setting changed here as its config key and new value
	 * @param stopCompost runs when the player clicks "Stop now" beside the compost stock
	 */
	RunsListView(JLabel heading, JPanel container, BiConsumer<String, String> send, Runnable stopCompost)
	{
		this.container = container;
		this.send = send;
		this.stopCompost = stopCompost;
		PanelText.stack(this);
		add(heading);
		add(container);
	}

	/** Empties the list, for a panel with no advice. */
	void clear()
	{
		dropRows();
		setVisible(false);
	}

	/**
	 * Forgets every row and its remembered lines without touching visibility, so a rebuild
	 * never hides the list between the old rows and the new.
	 */
	private void dropRows()
	{
		runDetails.clear();
		pausedLines.clear();
		stockedCounts.clear();
		container.removeAll();
	}

	/**
	 * Builds every row afresh from the advice. The caller decides when, through its guard,
	 * and passes the width the rows wrap against.
	 */
	void rebuild(FarmingAdvice advice, IconProvider icons, int width)
	{
		dropRows();
		Map<String, FarmingRunSettings> settingsFor = settingsByRun(advice);
		List<FarmingRunStatus> off = PanelText.listOf(advice.getSwitchedOff());
		boolean divider = false;
		for (FarmingRunStatus run : rowsOf(advice.getRuns(), off, advice.getRunOrder()))
		{
			if (divider)
			{
				container.add(PanelColors.divider());
			}
			FarmingRunSettings settings = settingsFor.get(run.getRunId());
			// Built whether open or shut, then shown and hidden in place by a click on the row.
			JPanel opened = settings != null && settings.getShape() != FarmingRunSettings.Shape.SWITCH
				? buildRunSettings(settings, icons) : null;
			if (opened != null)
			{
				opened.setVisible(openRuns.contains(run.getRunId()));
			}
			container.add(FarmingPanel.sized(buildRunRow(run, advice, icons, settings, off.contains(run), opened), width));
			if (opened != null)
			{
				container.add(opened);
			}
			divider = true;
		}
		setVisible(!PanelText.listOf(advice.getRuns()).isEmpty() || !off.isEmpty());
	}

	/** Copies each run row's detail text and paused line from the newest advice onto the existing ones. */
	void showDetails(FarmingAdvice advice)
	{
		for (FarmingRunStatus run : PanelText.listOf(advice.getRuns()))
		{
			JLabel detail = runDetails.get(run.getRunId());
			if (detail != null)
			{
				showRunDetail(detail, run.getDetail());
			}
		}
		for (FarmingRunSettings settings : PanelText.listOf(advice.getRunSettings()))
		{
			JTextArea paused = pausedLines.get(settings.getRunId());
			// The signature holds the line's presence, so a shown line still has text.
			if (paused != null && !paused.getText().equals(settings.getPaused()))
			{
				paused.setText(settings.getPaused());
			}
			JLabel stocked = stockedCounts.get(settings.getRunId());
			if (stocked != null && !stocked.getText().equals(settings.getStocked()))
			{
				stocked.setText(settings.getStocked());
			}
		}
	}

	/**
	 * The list's structural inputs, for the panel's guard. A scheduled run gives its id and
	 * status only: its detail text is a worded countdown, updated in place through
	 * {@link #runDetails}. A paused line gives its wording without numbers, as
	 * {@link #pausedLines} explains, and the compost stock likewise.
	 * Which runs are open is not here either: a click shows and hides a block in place, and
	 * a rebuild reopens it from {@link #openRuns}.
	 */
	static void addSignature(List<Object> signature, FarmingAdvice advice)
	{
		List<List<String>> runs = new ArrayList<>();
		for (FarmingRunStatus run : PanelText.listOf(advice.getRuns()))
		{
			runs.add(Arrays.asList(run.getRunId(), run.getStatus()));
		}
		signature.add(runs);
		// Trip membership decides each row's colour and weight.
		signature.add(advice.getTripRuns());
		signature.add(advice.getRunOrder());
		// A setting the player changes moves the re-planned advice here, which rebuilds the
		// blocks with the confirmed state. An off row's detail is fixed text, not a
		// countdown, and showDetails never reaches it, so it goes in whole.
		List<List<String>> off = new ArrayList<>();
		for (FarmingRunStatus run : PanelText.listOf(advice.getSwitchedOff()))
		{
			off.add(Arrays.asList(run.getRunId(), run.getDetail()));
		}
		signature.add(off);
		for (FarmingRunSettings run : PanelText.listOf(advice.getRunSettings()))
		{
			signature.add(run.toBuilder().paused(withoutNumbers(run.getPaused())).stocked(withoutNumbers(run.getStocked())).build());
		}
	}

	/** A line's wording without its counts, "null" for no line. */
	private static String withoutNumbers(String line)
	{
		return String.valueOf(line).replaceAll("[\\d,]", "");
	}

	/**
	 * One run and its status.
	 *
	 * @param settings the run's settings, or null for a run with none
	 * @param switchedOff whether the player switched the run off; drawn dimmed
	 * @param opened the run's settings block, which a click on the row shows and hides, or
	 *     null for a run with no block
	 */
	private JPanel buildRunRow(FarmingRunStatus run, FarmingAdvice advice, IconProvider icons,
		FarmingRunSettings settings, boolean switchedOff, JPanel opened)
	{
		// Membership of the trip: a trip covers several families.
		boolean onTrip = !switchedOff && coversRun(advice, run.getRunId());
		boolean due = !switchedOff && STATUS_DUE.equals(run.getStatus());
		// Grey means not possible: locked behind an unlock, or no route to any stop. A run
		// merely not due yet keeps its colours.
		boolean impossible = !switchedOff && STATUS_LOCKED.equals(run.getStatus());

		JPanel row = new JPanel(new GridBagLayout());
		// Opaque only while open, so the row and its settings read as one block.
		row.setOpaque(opened != null && opened.isVisible());
		row.setBackground(COLOR_OPEN);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 4));
		row.setAlignmentX(LEFT_ALIGNMENT);

		GridBagConstraints gbc = PanelText.marginConstraints();

		JLabel icon = null;
		if (icons != null && run.getIconItemId() > 0)
		{
			// Greyscale only for a run that cannot be done; faint for one switched off.
			ImageIcon sprite = icons.getInventoryIcon(run.getIconItemId(), !impossible);
			if (sprite != null)
			{
				icon = new JLabel(switchedOff ? new DimmedIcon(sprite) : sprite);
				icon.setBorder(BorderFactory.createEmptyBorder(1, 0, 0, 5));
				gbc.gridheight = GridBagConstraints.REMAINDER;
				row.add(icon, gbc);
				gbc.gridheight = 1;
			}
		}

		JPanel text = PanelText.stack();
		JLabel name = PanelText.label(run.getRunName(),
			onTrip || due ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont(),
			switchedOff ? COLOR_OFF : runColour(run.getStatus(), onTrip));
		name.setAlignmentX(LEFT_ALIGNMENT);
		text.add(name);

		// Always added, even when empty, so showDetails can fill it in place later. Its
		// colour depends on status, which is in the signature. A run not due yet keeps a
		// quieter status line, but grey only when the run is not possible.
		JLabel detail = PanelText.label("", switchedOff ? COLOR_OFF : due ? PanelColors.ROUTE : impossible ? PanelColors.SKIPPED : PanelColors.META);
		detail.setAlignmentX(LEFT_ALIGNMENT);
		text.add(detail);
		runDetails.put(run.getRunId(), detail);
		showRunDetail(detail, run.getDetail());

		PanelText.addFill(row, gbc, 1, text);
		// Its wording is in the signature and its count is updated in place, so only a new
		// wording rebuilds the wrapping area. In the row's own grid, so sizing the row wraps
		// it. The area takes its own clicks, so the row's control is wired to it too.
		JTextArea paused = null;
		if (settings != null && PanelText.hasText(settings.getPaused()))
		{
			paused = PanelText.small(settings.getPaused(), PanelColors.META);
			pausedLines.put(run.getRunId(), paused);
			gbc.gridy = 1;
			row.add(paused, gbc);
			gbc.gridy = 0;
		}

		JComponent accessory = accessory(settings, row, paused, name, detail, icon, opened);
		if (accessory != null)
		{
			gbc.gridheight = GridBagConstraints.REMAINDER;
			gbc.gridx = 2;
			gbc.weightx = 0;
			gbc.fill = GridBagConstraints.NONE;
			gbc.anchor = GridBagConstraints.CENTER;
			row.add(accessory, gbc);
		}
		return row;
	}

	/** Hidden rather than blank, so an empty detail takes no room. */
	private static void showRunDetail(JLabel detail, String text)
	{
		boolean anything = PanelText.hasText(text);
		detail.setVisible(anything);
		detail.setText(anything ? text : "");
	}

	/**
	 * The control at a run row's right end: a checkbox for a run one setting switches, a
	 * chevron for a run with a settings block, or null for a run with neither. Either way a
	 * left click on the whole row does what the control does: it flips the box, or it opens
	 * and shuts the block.
	 *
	 * @param paused the row's paused line, or null for none
	 */
	private JComponent accessory(FarmingRunSettings settings, JPanel row, JTextArea paused, JLabel name, JLabel detail, JLabel icon,
		JPanel opened)
	{
		if (settings == null)
		{
			return null;
		}
		FarmingSettingChoice only = settings.getRunSwitch();
		if (settings.getShape() == FarmingRunSettings.Shape.SWITCH && only != null)
		{
			JCheckBox box = runSwitch(only, settings.getRunId(), name, detail, icon);
			// A click anywhere on the row flips the box, as a click on a family row opens
			// it. The box itself takes its own clicks, so they never reach the row.
			onRowClick(row, paused, () -> box.doClick(0));
			return box;
		}
		if (opened == null)
		{
			return null;
		}
		JLabel chevron = new JLabel();
		chevron.setFont(FontManager.getRunescapeSmallFont());
		chevron.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 2));
		showChevron(chevron, opened.isVisible());
		String runId = settings.getRunId();
		onRowClick(row, paused, () ->
		{
			boolean open = !opened.isVisible();
			if (open)
			{
				openRuns.add(runId);
			}
			else
			{
				openRuns.remove(runId);
			}
			opened.setVisible(open);
			row.setOpaque(open);
			showChevron(chevron, open);
			container.revalidate();
			container.repaint();
		});
		return chevron;
	}

	/** Runs the row's control on a left click on the row, or on its paused line, which takes its own clicks. */
	private static void onRowClick(JPanel row, JTextArea paused, Runnable toggle)
	{
		PanelText.onLeftClick(row, toggle);
		if (paused != null)
		{
			PanelText.onLeftClick(paused, toggle);
		}
	}

	private static void showChevron(JLabel chevron, boolean open)
	{
		// The folds' own arrows.
		chevron.setText(open ? Fold.OPEN : Fold.SHUT);
		chevron.setForeground(open ? Color.WHITE : PanelColors.HEADER);
	}

	/**
	 * The checkbox on a run one setting switches. Dims the row at once, before the re-plan.
	 */
	private JCheckBox runSwitch(FarmingSettingChoice only, String runId, JLabel name, JLabel detail, JLabel icon)
	{
		Icon builtIcon = icon != null ? icon.getIcon() : null;
		JCheckBox box = FarmingPanel.checkbox(null, 0);
		box.setSelected(only.isOn());
		box.setToolTipText(switchTip(only.isOn()));
		// The row as built, put back by a re-tick. Untick then re-tick before the re-plan
		// leaves the preferences where they started, so no re-plan comes to redraw it.
		Color builtColour = name.getForeground();
		Font builtFont = name.getFont();
		Color builtDetailColour = detail.getForeground();
		String builtDetail = detail.getText();
		box.addActionListener(e ->
		{
			boolean on = box.isSelected();
			box.setToolTipText(switchTip(on));
			// Switching on restores the row as built, and the re-plan, which knows the
			// status, redraws it if that has moved.
			if (on)
			{
				name.setForeground(builtColour);
				name.setFont(builtFont);
				detail.setForeground(builtDetailColour);
				if (icon != null)
				{
					icon.setIcon(builtIcon instanceof DimmedIcon ? ((DimmedIcon) builtIcon).getIcon() : builtIcon);
				}
				// Back in the in-place updates, so the next refresh brings the countdown up
				// to date.
				showRunDetail(detail, builtDetail);
				runDetails.put(runId, detail);
			}
			else
			{
				name.setForeground(COLOR_OFF);
				name.setFont(FontManager.getRunescapeSmallFont());
				detail.setForeground(COLOR_OFF);
				if (icon != null && builtIcon != null && !(builtIcon instanceof DimmedIcon))
				{
					icon.setIcon(new DimmedIcon(builtIcon));
				}
				// Out of the in-place updates, which would write the old status back before
				// the re-plan arrives.
				runDetails.remove(runId);
				showRunDetail(detail, "off");
			}
			revalidate();
			repaint();
			send.accept(only.getKey(), String.valueOf(on));
		});
		return box;
	}

	private static String switchTip(boolean on)
	{
		return on ? "Switch this run off" : "Switch this run on";
	}

	/**
	 * A run's settings block, shown under its row while open: the crop grid, then the sites
	 * it visits, then the crops it plants in passing, then its checkboxes, then its labelled
	 * picks. Nothing here wraps, so the block can be rebuilt without the re-measure flicker.
	 */
	private JPanel buildRunSettings(FarmingRunSettings settings, IconProvider icons)
	{
		// As wide as the row above it, even when nothing in it stretches: a block of only a
		// grid and a checkbox otherwise stops at their width and leaves a strip of the
		// list's colour beside it.
		JPanel block = new JPanel()
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Short.MAX_VALUE, getPreferredSize().height);
			}
		};
		block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));
		block.setOpaque(true);
		block.setBackground(COLOR_OPEN);
		block.setAlignmentX(LEFT_ALIGNMENT);
		// Indented to the row's own inset. The row's text column sits too far right for a
		// four-wide grid to fit the sidebar.
		block.setBorder(BorderFactory.createEmptyBorder(0, 6, 7, 4));

		if (settings.getChoicesCaption() != null)
		{
			block.add(SiteList.caption(settings.getChoicesCaption(), 0));
		}
		block.add(SettingGrid.toggles(PanelText.listOf(settings.getChoices()), icons, send));

		List<FarmingSettingChoice> sites = PanelText.listOf(settings.getSites());
		if (!sites.isEmpty())
		{
			block.add(SiteList.caption("Patches", 6));
			block.add(new SiteList(sites, send));
		}

		List<FarmingSettingChoice> extras = PanelText.listOf(settings.getExtras());
		if (!extras.isEmpty())
		{
			block.add(SiteList.caption("Also plant on this run", 6));
			block.add(SettingGrid.toggles(extras, icons, send));
		}
		List<FarmingPatchPick> patchPicks = PanelText.listOf(settings.getPatchPicks());
		if (!patchPicks.isEmpty())
		{
			block.add(SiteList.caption("Allotments and flowers", 6));
			block.add(new PatchPicks(patchPicks, openPick, icons, send, key -> openPick = key));
		}
		for (FarmingSettingChoice choice : PanelText.listOf(settings.getSwitches()))
		{
			JCheckBox box = FarmingPanel.checkbox(choice.getLabel(), 5);
			box.setSelected(choice.isOn());
			box.setToolTipText(choice.getTip());
			box.addActionListener(e -> send.accept(choice.getKey(), String.valueOf(box.isSelected())));
			block.add(box);
		}
		List<FarmingSettingPick> picks = PanelText.listOf(settings.getPicks());
		for (int i = 0; i < picks.size(); i++)
		{
			JPanel row = SettingRow.of(picks.get(i), send);
			if (i == 0)
			{
				// Set apart from the grids above, as the extras' caption is.
				row.setBorder(BorderFactory.createEmptyBorder(8, 2, 0, 0));
			}
			block.add(row);
		}
		if (PanelText.hasText(settings.getStocked()))
		{
			// Its count is updated in place, so only its coming and going rebuilds the block.
			JLabel count = PanelText.label(settings.getStocked(), PanelColors.ROUTE);
			stockedCounts.put(settings.getRunId(), count);
			SmallButton stop = new SmallButton("Stop now");
			stop.setToolTipText(settings.getStockedTip());
			stop.addActionListener(e -> stopCompost.run());
			JPanel control = PanelText.panel(new BorderLayout(4, 0));
			control.add(count, BorderLayout.CENTER);
			control.add(stop, BorderLayout.EAST);
			block.add(SettingRow.of("Stocked", control));
		}
		return block;
	}

	/**
	 * @param onTrip whether the trip on screen has stops for this family. White (on the
	 *     trip now) outranks amber (due). A due family the trip left out stays amber.
	 */
	private static Color runColour(String status, boolean onTrip)
	{
		if (onTrip)
		{
			return Color.WHITE;
		}
		if (STATUS_DUE.equals(status))
		{
			return FarmingPanel.COLOR_DUE;
		}
		// Grey only for a run that cannot be done. Waiting, unseen or growing is not that.
		return STATUS_LOCKED.equals(status) ? PanelColors.SKIPPED : PanelColors.ROUTE;
	}

	/**
	 * Whether today's trip has a stop for this family. A missing trip list covers nothing.
	 *
	 * <p>The null-id check comes first because the trip list is immutable and its
	 * {@code contains(null)} throws.
	 */
	private static boolean coversRun(FarmingAdvice advice, String runId)
	{
		List<String> onTrip = advice.getTripRuns();
		return runId != null && onTrip != null && onTrip.contains(runId);
	}

	private static Map<String, FarmingRunSettings> settingsByRun(FarmingAdvice advice)
	{
		Map<String, FarmingRunSettings> byRun = new HashMap<>();
		for (FarmingRunSettings settings : PanelText.listOf(advice.getRunSettings()))
		{
			byRun.put(settings.getRunId(), settings);
		}
		return byRun;
	}

	/**
	 * Every run, scheduled or switched off, in the advice's fixed order, so no row moves when
	 * a run comes due or is switched. A run the order does not name goes last, in the order
	 * it came.
	 */
	static List<FarmingRunStatus> rowsOf(List<FarmingRunStatus> runs, List<FarmingRunStatus> off, List<String> order)
	{
		List<FarmingRunStatus> rows = new ArrayList<>(PanelText.listOf(runs));
		rows.addAll(off);
		List<String> fixed = PanelText.listOf(order);
		rows.sort(Comparator.comparingInt(run ->
		{
			// An immutable list's indexOf(null) throws.
			int at = run.getRunId() == null ? -1 : fixed.indexOf(run.getRunId());
			return at < 0 ? Integer.MAX_VALUE : at;
		}));
		return rows;
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingSettingChoice;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.*;

/**
 * The side panel's grids of setting squares: one {@link SettingSquare} per choice, laid out
 * four across over the inventory colour, as the game lays out an inventory.
 */
final class SettingGrid
{
	/** A spell's icon on a square, about an inventory sprite's height. */
	private static final int SPRITE_SIZE = 28;

	private SettingGrid()
	{
	}

	/**
	 * Ticks: a click flips the one square at once and sends its new state. A locked square
	 * takes no click.
	 */
	static InventoryBackdrop toggles(List<FarmingSettingChoice> choices, IconProvider icons, BiConsumer<String, String> send)
	{
		List<SettingSquare> squares = new ArrayList<>(choices.size());
		for (FarmingSettingChoice choice : choices)
		{
			squares.add(toggle(choice, icons, send));
		}
		return grid(squares, icons);
	}

	/** One tick square, flipping itself on a click and sending its new state. */
	private static SettingSquare toggle(FarmingSettingChoice choice, IconProvider icons, BiConsumer<String, String> send)
	{
		SettingSquare square = square(choice, icons);
		if (!choice.isLocked())
		{
			PanelText.onLeftClick(square, () ->
			{
				boolean on = !square.isOn();
				square.setOn(on);
				send.accept(choice.getKey(), String.valueOf(on));
			});
		}
		return square;
	}

	/**
	 * A square showing the choice's item, tag, lock, ownership and state. Takes no click by
	 * itself.
	 */
	static SettingSquare square(FarmingSettingChoice choice, IconProvider icons)
	{
		boolean grey = choice.isLocked() || choice.isMissing();
		ImageIcon sprite = icon(choice, icons, true);
		ImageIcon greySprite = grey ? icon(choice, icons, false) : null;
		SettingSquare square = new SettingSquare(sprite, greySprite, choice.getTag(),
			choice.getLevel(), choice.isLocked(), choice.isOn(), choice.isMissing());
		square.setToolTipText(tooltip(choice));
		return square;
	}

	/** The choice's game sprite where it names one, else its item, or null for neither. */
	private static ImageIcon icon(FarmingSettingChoice choice, IconProvider icons, boolean held)
	{
		if (icons == null)
		{
			return null;
		}
		if (choice.getSpriteId() > 0)
		{
			return icons.getSpriteIcon(choice.getSpriteId(), SPRITE_SIZE, held);
		}
		return choice.getItemId() > 0 ? icons.getInventoryIcon(choice.getItemId(), held) : null;
	}

	private static String tooltip(FarmingSettingChoice choice)
	{
		if (choice.isLocked())
		{
			return choice.getLabel() + " needs " + choice.getLevel() + " Farming";
		}
		if (!choice.isMissing())
		{
			return choice.getLabel();
		}
		String note = choice.getMissingNote();
		return choice.getLabel() + ". " + (note != null ? note : "None seen yet");
	}

	/**
	 * Squares four across over the inventory colour, trailing cells left blank. The packing
	 * grid and the settings grids share it.
	 */
	static InventoryBackdrop grid(List<? extends JComponent> cells, IconProvider icons)
	{
		return grid(cells, icons, CarryView.COLUMNS);
	}

	static InventoryBackdrop grid(List<? extends JComponent> cells, IconProvider icons, int columns)
	{
		int rows = Math.max(1, (cells.size() + columns - 1) / columns);
		InventoryBackdrop grid = new InventoryBackdrop(new GridLayout(rows, columns, ItemSquare.GAP, ItemSquare.GAP));
		grid.setIcons(icons);
		// GridLayout divides all the width it gets. Cap it so squares stay sprite-sized.
		Dimension size = new Dimension(columns * ItemSquare.SIZE + (columns - 1) * ItemSquare.GAP,
			rows * ItemSquare.SIZE + (rows - 1) * ItemSquare.GAP);
		grid.setMaximumSize(size);
		grid.setPreferredSize(size);
		for (JComponent cell : cells)
		{
			grid.addSlot(cell);
		}
		// Trailing cells are blanks, not empty slots, which would imply "room for more".
		for (int i = cells.size(); i < rows * columns; i++)
		{
			JPanel blank = new JPanel();
			blank.setOpaque(false);
			grid.add(blank);
		}
		return grid;
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingSettingPick;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.function.BiConsumer;
import javax.swing.*;

/**
 * A setting's label beside its control. Every such row in the panel is built here, so the
 * labels share one width and the controls line up down the panel.
 */
final class SettingRow
{
	/**
	 * Wide enough for the longest label, "Favourite herb" (74 pixels in the small font), and
	 * no wider, so the chips beside "Best seeds in" keep their room at sidebar width.
	 */
	private static final int LABEL_WIDTH = 75;
	private static final int ROW_HEIGHT = 23;

	private SettingRow()
	{
	}

	static JPanel of(String label, JComponent control)
	{
		JPanel row = PanelText.panel(new BorderLayout(4, 0));
		row.setBorder(BorderFactory.createEmptyBorder(3, 2, 0, 0));
		JLabel name = PanelText.label(label, PanelColors.HEADER);
		name.setPreferredSize(new Dimension(LABEL_WIDTH, ROW_HEIGHT - 3));
		row.add(name, BorderLayout.WEST);
		row.add(control, BorderLayout.CENTER);
		row.setMaximumSize(new Dimension(Short.MAX_VALUE, ROW_HEIGHT));
		return row;
	}

	/**
	 * A row for a setting of several values, drawn as its shape asks: chips or a dropdown.
	 * Built from scratch, for a block that is rebuilt whole.
	 *
	 * @param send receives the setting's key and the picked value
	 */
	static JPanel of(FarmingSettingPick pick, BiConsumer<String, String> send)
	{
		if (pick.getShape() == FarmingSettingPick.Shape.DROPDOWN)
		{
			PickDropdown dropdown = new PickDropdown(send);
			dropdown.show(pick);
			return of(pick.getLabel(), dropdown);
		}
		ChoiceChips chips = new ChoiceChips(send);
		chips.show(pick);
		return of(pick.getLabel(), chips);
	}
}

package com.larryfarming.panel;

import java.awt.*;
import javax.swing.*;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * One clickable square in a farming setting grid: a crop or item to switch on or off.
 *
 * <p>Drawn like an {@link ItemSquare}, with three states on top. On draws a green outline, the
 * spellbook picker's live-choice green, because faint alone reads too close to full colour on
 * a grid of similar sprites. Off draws the sprite faint with no outline. Locked draws it grey,
 * faint, with a padlock and the level it needs; a square not yet plantable but not impossible
 * shows the level alone, at full colour. Missing, for an item the player does not own,
 * draws it grey with no padlock and stays clickable; off as well draws it grey and faint.
 *
 * <p>Every setting grid in the panel uses this one square, so on and off read the same in each.
 *
 * <p>The states change in place, so a click shows at once without waiting for the re-plan
 * that follows it.
 */
class SettingSquare extends JPanel
{
	/** How strongly an unticked sprite shows, and any other faint icon. */
	static final AlphaComposite DIM = AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.35f);
	/** The tag fades less than the sprite, so it stays readable. */
	private static final AlphaComposite DIM_TAG = AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.45f);

	private static final Color COLOR_TAG = Color.WHITE;
	private static final Color COLOR_LEVEL = PanelColors.LEVEL;
	private static final Color COLOR_LOCK = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color COLOR_LOCK_BACK = new Color(0, 0, 0, 160);

	private static final Border PLAIN_BORDER = BorderFactory.createEmptyBorder(1, 1, 1, 1);
	private static final Border ON_BORDER = BorderFactory.createLineBorder(ColorScheme.PROGRESS_COMPLETE_COLOR);

	private final ImageIcon sprite;
	private final ImageIcon greySprite;
	private final String tag;
	private final String level;
	private final boolean locked;
	private final boolean missing;
	private boolean on;
	/** Whether a locked square that is on still shows the outline; see {@link #outlineWhileLocked}. */
	private boolean lockedOutline;
	/** Whether an unlocked square shows its level in the corner; see {@link #showLevel}. */
	private boolean levelShown;
	/** A small icon in the bottom-right corner at full strength, or null for none. */
	private ImageIcon badge;

	/**
	 * @param greySprite the sprite drained of colour, drawn while locked or missing
	 * @param missing    true for an item the player does not own
	 */
	SettingSquare(ImageIcon sprite, ImageIcon greySprite, String tag, int level, boolean locked, boolean on, boolean missing)
	{
		this.sprite = sprite;
		this.greySprite = greySprite;
		this.tag = tag;
		this.level = String.valueOf(level);
		this.locked = locked;
		this.on = on;
		this.missing = missing;
		// Transparent so the InventoryBackdrop slot colour shows through.
		setOpaque(false);
		setFont(FontManager.getRunescapeSmallFont());
		Dimension size = new Dimension(ItemSquare.SIZE, ItemSquare.SIZE);
		setPreferredSize(size);
		setMinimumSize(size);
		setBorder(isOutlined() ? ON_BORDER : PLAIN_BORDER);
		if (!locked)
		{
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		}
	}

	boolean isOn()
	{
		return on;
	}

	/** Whether the sprite is drawn drained of colour: locked, or not owned. */
	boolean isGrey()
	{
		return (locked || missing) && greySprite != null;
	}

	/** Whether the sprite is drawn faint: locked, or switched off. */
	boolean isFaint()
	{
		return locked || !on;
	}

	/**
	 * Whether the square shows the green outline that marks it on. A locked square does only
	 * when {@link #outlineWhileLocked} asked for it.
	 */
	boolean isOutlined()
	{
		return on && (!locked || lockedOutline);
	}

	/** Outlines the square while it is on, even locked: a preset pick above the player's level is still the pick. */
	void outlineWhileLocked()
	{
		lockedOutline = true;
		setBorder(isOutlined() ? ON_BORDER : PLAIN_BORDER);
	}

	/**
	 * Shows the level in the corner, as a locked square does, on a square drawn at full
	 * colour: a pick that plants once the player reaches the level, which is not impossible.
	 */
	void showLevel()
	{
		levelShown = true;
		repaint();
	}

	void setBadge(ImageIcon badge)
	{
		this.badge = badge;
		repaint();
	}

	void setOn(boolean on)
	{
		if (this.on != on)
		{
			this.on = on;
			setBorder(isOutlined() ? ON_BORDER : PLAIN_BORDER);
			repaint();
		}
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			Composite full = g2.getComposite();
			ImageIcon shown = isGrey() ? greySprite : sprite;
			boolean faint = isFaint();
			if (shown != null)
			{
				if (faint)
				{
					g2.setComposite(DIM);
				}
				shown.paintIcon(this, g2, (getWidth() - shown.getIconWidth()) / 2, (getHeight() - shown.getIconHeight()) / 2);
				g2.setComposite(full);
			}
			g2.setFont(getFont());
			if (locked || levelShown)
			{
				int ascent = g2.getFontMetrics().getAscent();
				PanelText.drawShadowed(g2, level, 3, ascent + 1, COLOR_LEVEL);
			}
			if (locked)
			{
				drawLock(g2, getWidth() - 12, 3);
			}
			else if (tag != null && !tag.isEmpty())
			{
				if (!on)
				{
					g2.setComposite(DIM_TAG);
				}
				PanelText.drawShadowed(g2, tag, 3, getHeight() - 3, COLOR_TAG);
			}
			if (badge != null)
			{
				g2.setComposite(full);
				badge.paintIcon(this, g2, getWidth() - badge.getIconWidth() - 2, getHeight() - badge.getIconHeight() - 2);
			}
		}
		finally
		{
			g2.dispose();
		}
	}

	/** The padlock on a dark backing, so it reads over any sprite. */
	private static void drawLock(Graphics2D g, int x, int y)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(COLOR_LOCK_BACK);
		g.fillRoundRect(x - 1, y + 3, 10, 9, 2, 2);
		Padlock.draw(g, x, y, COLOR_LOCK);
	}
}

package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingSettingChoice;
import com.larryfarming.snapshot.FarmingSettingGroup;
import java.awt.*;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Settings as two columns of whole-row checkboxes, in the order given, which never changes:
 * the sites a run visits, filled top to bottom, and what the player's house holds, filled
 * row by row under captions.
 *
 * <p>On is ticked. Off is an empty box with faded text, as a switched-off run row fades. A
 * setting that cannot apply shows a padlock in the box's place and grey text, and takes no
 * click: grey means impossible. A locked setting short of a level shows that level in the
 * box's place instead, in a locked seed's level colour. A house item Larry has seen built
 * shows an eye in the box's place and white text, and takes no click either: what he saw
 * is not the player's to change.
 *
 * <p>A click flips the box and its text at once, before the re-plan that follows it. Nothing
 * here wraps, so the block holding it can be rebuilt without the re-measure flicker.
 */
final class SiteList extends JPanel
{
	private static final int COLUMNS = 2;
	private static final int ROW_HEIGHT = 19;
	private static final int COLUMN_GAP = 10;
	/** Above every caption but the first, so each group reads apart from the one before. */
	private static final int CAPTION_GAP = 5;

	private SiteList()
	{
		super(new GridBagLayout());
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
	}

	/** The sites, two columns filled top to bottom. */
	SiteList(List<FarmingSettingChoice> sites, BiConsumer<String, String> send)
	{
		this();
		int rows = (sites.size() + COLUMNS - 1) / COLUMNS;
		for (int i = 0; i < sites.size(); i++)
		{
			addRow(sites.get(i), i / rows, i % rows, send);
		}
		setMaximumSize(new Dimension(Short.MAX_VALUE, rows * ROW_HEIGHT));
	}

	/**
	 * Each group under its caption, two columns filled left to right, all in one grid so the
	 * columns line up down the whole list.
	 */
	static SiteList inGroups(List<FarmingSettingGroup> groups, BiConsumer<String, String> send)
	{
		SiteList list = new SiteList();
		int y = 0;
		for (FarmingSettingGroup group : groups)
		{
			GridBagConstraints c = new GridBagConstraints();
			c.gridx = 0;
			c.gridy = y;
			c.gridwidth = COLUMNS;
			c.anchor = GridBagConstraints.WEST;
			list.add(caption(group.getLabel(), y == 0 ? 0 : CAPTION_GAP), c);
			y++;
			List<FarmingSettingChoice> choices = group.getChoices();
			for (int i = 0; i < choices.size(); i++)
			{
				list.addRow(choices.get(i), i % COLUMNS, y + i / COLUMNS, send);
			}
			y += (choices.size() + COLUMNS - 1) / COLUMNS;
		}
		list.setMaximumSize(new Dimension(Short.MAX_VALUE, list.getPreferredSize().height));
		return list;
	}

	/** A caption over settings, as every settings block in the panel heads its groups. */
	static JLabel caption(String text, int gapAbove)
	{
		JLabel caption = PanelText.label(text, PanelColors.HEADER);
		caption.setAlignmentX(LEFT_ALIGNMENT);
		caption.setBorder(BorderFactory.createEmptyBorder(gapAbove, 2, 3, 0));
		return caption;
	}

	private void addRow(FarmingSettingChoice choice, int column, int line, BiConsumer<String, String> send)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridx = column;
		c.gridy = line;
		c.anchor = GridBagConstraints.WEST;
		c.fill = GridBagConstraints.HORIZONTAL;
		// The last column takes the spare width, so every name keeps its own.
		c.weightx = column == COLUMNS - 1 ? 1 : 0;
		c.insets = new Insets(0, 0, 0, column < COLUMNS - 1 ? COLUMN_GAP : 0);
		JComponent row = row(choice, send);
		row.setPreferredSize(new Dimension(row.getPreferredSize().width, ROW_HEIGHT));
		add(row, c);
	}

	/**
	 * One setting: the panel's checkbox, or in the box's place an eye for a seen house item,
	 * and for a locked one the level it needs or else a padlock.
	 */
	private static JComponent row(FarmingSettingChoice choice, BiConsumer<String, String> send)
	{
		JCheckBox box = FarmingPanel.checkbox(choice.getLabel(), 0);
		if (choice.isSeen() && !choice.isLocked())
		{
			return marked(choice.getLabel(), box, new Eye(PanelColors.HEADER, boxWidth(), boxHeight()), Color.WHITE);
		}
		if (choice.isLocked())
		{
			Icon mark = choice.getLevel() > 0 ? new LevelMark(choice.getLevel(), boxWidth(), boxHeight())
				: new Padlock(ColorScheme.MEDIUM_GRAY_COLOR, boxWidth(), boxHeight());
			return marked(choice.getLabel(), box, mark, ColorScheme.MEDIUM_GRAY_COLOR);
		}
		box.setSelected(choice.isOn());
		box.setForeground(colour(choice.isOn()));
		box.addActionListener(e ->
		{
			box.setForeground(colour(box.isSelected()));
			send.accept(choice.getKey(), String.valueOf(box.isSelected()));
		});
		return box;
	}

	/**
	 * A label laid out as the checkbox it stands for, with a mark in the box's place, so its
	 * text lines up with the rest.
	 */
	private static JLabel marked(String name, JCheckBox like, Icon mark, Color text)
	{
		JLabel label = new JLabel(name, mark, SwingConstants.LEFT);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(text);
		label.setIconTextGap(like.getIconTextGap());
		label.setBorder(like.getBorder());
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * The level a locked setting needs, in the box's place, drawn as a locked seed's level
	 * is: the stack-count yellow over a dark shadow. It takes the box's place rather than
	 * following the name, because two columns of names with a level after each are wider
	 * than the sidebar.
	 */
	static final class LevelMark extends Mark
	{
		private final String level;

		LevelMark(int level, int width, int height)
		{
			super(PanelColors.LEVEL, width, height, width, height);
			this.level = String.valueOf(level);
		}

		@Override
		void drawAt(Graphics2D g, int x, int y, Color colour)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics metrics = g.getFontMetrics();
			int textX = x + (getIconWidth() - metrics.stringWidth(level)) / 2;
			int baseline = y + (getIconHeight() + metrics.getAscent()) / 2 - 1;
			PanelText.drawShadowed(g, level, textX, baseline, colour);
		}
	}

	private static int boxWidth()
	{
		Icon boxIcon = UIManager.getIcon("CheckBox.icon");
		return boxIcon != null ? boxIcon.getIconWidth() : Padlock.WIDTH + 4;
	}

	private static int boxHeight()
	{
		Icon boxIcon = UIManager.getIcon("CheckBox.icon");
		return boxIcon != null ? boxIcon.getIconHeight() : Padlock.HEIGHT + 2;
	}

	private static Color colour(boolean on)
	{
		return on ? PanelColors.HEADER : RunsListView.COLOR_OFF;
	}
}

