package com.larryfarming.panel;

import com.larryfarming.snapshot.FarmingAdvice;
import com.larryfarming.snapshot.FarmingSettingGroup;
import java.util.Arrays;
import java.util.List;
import java.util.function.BiConsumer;

/**
 * The side panel's travel fold: one on/off square per travel method, in a fixed order,
 * under captions such as "Jewellery". Off means never use it, on any route. A method the
 * player has nothing for draws grey and still switches.
 *
 * <p>When nothing switched on and owned reaches a fairy ring, while the network itself is
 * open, the header turns amber and says so, readable with the fold shut.
 *
 * <p>The squares are rebuilt only when the advice's answer moves, so a refresh arriving
 * before a click's re-plan leaves the click on screen. Nothing here wraps, so a rebuild
 * cannot flicker.
 */
class TravelFold extends Fold
{
	/**
	 * Appended while nothing the player uses reaches a ring, so a shut fold still says so.
	 * It names the rings: the fold holds every travel method, and most still work. The
	 * settings header repeats it, so it reads with both folds shut.
	 */
	static final String BLOCKED = ": no way to a fairy ring";

	private final BiConsumer<String, String> send;

	/** Keyed on the groups and the icons, so a provider arriving later redraws the squares. */
	private final RebuildGuard guard = new RebuildGuard();

	/** @param send receives each switched square as its config key and new value */
	TravelFold(BiConsumer<String, String> send)
	{
		super("Travel");
		this.send = send;
		setVisible(false);
	}

	/** Draws the fold's squares from the advice. Hidden for advice without them. */
	void show(FarmingAdvice advice, IconProvider icons)
	{
		List<FarmingSettingGroup> groups = PanelText.listOf(advice.getTravelGroups());
		setVisible(!groups.isEmpty());
		if (groups.isEmpty())
		{
			return;
		}
		// The header's text and colour are set in place: a one-line label cannot flicker.
		warn(advice.isFairyRingBlocked(), BLOCKED);
		if (!guard.shouldRebuild(Arrays.asList(groups, icons)))
		{
			return;
		}

		content().removeAll();
		for (FarmingSettingGroup group : groups)
		{
			int gapAbove = content().getComponentCount() == 0 ? 0 : 6;
			content().add(SiteList.caption(group.getLabel(), gapAbove));
			content().add(SettingGrid.toggles(group.getChoices(), icons, send));
		}
		content().revalidate();
		content().repaint();
	}
}

package com.larryfarming.persistence;

import net.runelite.client.config.ConfigManager;

/**
 * The slice of {@link ConfigManager} that the plugin's persistence reads and writes.
 *
 * <p>The plugin persists only pre-encoded strings, so this needs none of ConfigManager's
 * typed overloads. The interface keeps the persistence independent of an injected client.
 */
public interface ConfigStore {

    String getRSProfileConfiguration(String group, String key);

    void setRSProfileConfiguration(String group, String key, String value);

    void unsetRSProfileConfiguration(String group, String key);

    String getConfiguration(String group, String key);

    void setConfiguration(String group, String key, String value);

    /** The live client's store. */
    static ConfigStore of(ConfigManager configManager) {
        return new ConfigStore() {
            @Override
            public String getRSProfileConfiguration(String group, String key) {
                return configManager.getRSProfileConfiguration(group, key);
            }

            @Override
            public void setRSProfileConfiguration(String group, String key, String value) {
                configManager.setRSProfileConfiguration(group, key, value);
            }

            @Override
            public void unsetRSProfileConfiguration(String group, String key) {
                configManager.unsetRSProfileConfiguration(group, key);
            }

            @Override
            public String getConfiguration(String group, String key) {
                return configManager.getConfiguration(group, key);
            }

            @Override
            public void setConfiguration(String group, String key, String value) {
                configManager.setConfiguration(group, key, value);
            }
        };
    }
}

package com.larryfarming.persistence;

import com.google.gson.*;
import com.larryfarming.LarryConfig;
import com.larryfarming.engine.farming.FarmingTracker;
import com.larryfarming.engine.farming.FarmingWorldMap;
import com.larryfarming.model.ItemStack;
import com.larryfarming.model.PlayerState;
import lombok.extern.slf4j.Slf4j;

import java.time.Instant;
import java.util.*;

/**
 * What the plugin saves per RS profile about the account: its {@link PlayerState}, the last
 * seen contents of every farming patch, and the learned farm-tick offset.
 *
 * <p>The player state is written on a debounce, because it changes with every inventory
 * move. Patch observations are written as they change, so offline growth survives a crash.
 */
@Slf4j
public class StatePersistence {

    private static final String CONFIG_GROUP = LarryConfig.GROUP;

    private static final String KEY_PLAYER_STATE = "playerState";
    /** {@code PlayerState}'s own field, which a save replaces with {@link #KEY_BANK_HELD}. */
    private static final String KEY_BANK = "bank";
    private static final String KEY_BANK_HELD = "bankHeld";
    private static final String KEY_FARMING_PREFIX = "farming.";
    private static final String KEY_FARMING_TICK_OFFSET = "farmingTickOffset";

    private static final long SAVE_DEBOUNCE_MS = 5000;

    private final ConfigStore store;
    private final Gson gson;

    private long lastSaveTime;
    private boolean dirty;

    public StatePersistence(ConfigStore store, Gson base) {
        this.store = store;
        this.gson = buildGson(base);
    }

    /**
     * Build the Gson used for the saved player state.
     *
     * <p>The {@link Instant} adapter is required. {@link PlayerState} holds {@code Instant}
     * fields, and Gson's reflective fallback calls {@code setAccessible} on {@code Instant}'s
     * private fields, which JDK 17+ module encapsulation refuses. Instants are stored as epoch
     * seconds.
     *
     * <p>{@code base} is the client's injected Gson. The adapter registered here is added
     * later and wins.
     */
    static Gson buildGson(Gson base) {
        return base.newBuilder().registerTypeAdapter(Instant.class, (JsonSerializer<Instant>) (src, type, ctx) ->
                                new JsonPrimitive(src.getEpochSecond())).registerTypeAdapter(Instant.class,
                        (JsonDeserializer<Instant>) (json, type, ctx) -> Instant.ofEpochSecond(json.getAsLong())).create();
    }

    /** The current RS profile's saved player state, or null when it has none or it is unreadable. */
    public PlayerState loadPlayerState() {
        String json = store.getRSProfileConfiguration(CONFIG_GROUP, KEY_PLAYER_STATE);
        if (json == null || json.isEmpty()) {
            return null;
        }
        try {
            JsonObject tree = gson.fromJson(json, JsonObject.class);
            JsonElement held = tree.remove(KEY_BANK_HELD);
            if (held != null && held.isJsonArray()) {
                tree.add(KEY_BANK, expandBank(held.getAsJsonArray()));
            }
            return gson.fromJson(tree, PlayerState.class);
        } catch (RuntimeException e) {
            log.warn("Failed to read the saved account state, starting fresh", e);
            return null;
        }
    }

    /**
     * The bank as flat id, quantity pairs: {@code [952,1,5343,1]}.
     *
     * <p>A bank holds up to 1,250 stacks, and their names alone would run a save to 60 KB of
     * config that RuneLite syncs on every write. Names come back the next time the bank
     * opens. Placeholders hold nothing, so they are left out.
     */
    static JsonArray compactBank(List<ItemStack> bank) {
        JsonArray pairs = new JsonArray();
        for (ItemStack stack : bank) {
            if (stack.getQuantity() > 0) {
                pairs.add(stack.getItemId());
                pairs.add(stack.getQuantity());
            }
        }
        return pairs;
    }

    /** {@link #compactBank}'s pairs as the stacks {@code PlayerState} reads, unnamed. */
    private static JsonArray expandBank(JsonArray pairs) {
        JsonArray stacks = new JsonArray();
        for (int i = 0; i + 1 < pairs.size(); i += 2) {
            JsonObject stack = new JsonObject();
            stack.addProperty("itemId", pairs.get(i).getAsInt());
            stack.addProperty("quantity", pairs.get(i + 1).getAsInt());
            stacks.add(stack);
        }
        return stacks;
    }

    /** Mark state dirty; the write happens on the next debounced save or {@link #forceSave}. */
    public void markDirty() {
        dirty = true;
    }

    /** Save if dirty and the debounce period has elapsed. Call once per game tick. */
    public void saveIfNeeded(PlayerState playerState) {
        if (!dirty) {
            return;
        }
        if (System.currentTimeMillis() - lastSaveTime < SAVE_DEBOUNCE_MS) {
            return;
        }
        forceSave(playerState);
    }

    /** Save immediately, ignoring the debounce. Call at logout and shutdown. */
    public void forceSave(PlayerState playerState) {
        if (playerState == null) {
            return;
        }
        try {
            JsonObject tree = gson.toJsonTree(playerState).getAsJsonObject();
            tree.remove(KEY_BANK);
            tree.add(KEY_BANK_HELD, compactBank(playerState.getBank()));
            store.setRSProfileConfiguration(CONFIG_GROUP, KEY_PLAYER_STATE, gson.toJson(tree));
            lastSaveTime = System.currentTimeMillis();
            dirty = false;
        } catch (RuntimeException e) {
            log.warn("Failed to save the account state", e);
        }
    }

    /**
     * Persist observed farming patch states, one key per patch, as
     * "varbitValue:observedAtEpochSec" under "farming.&lt;regionId&gt;.&lt;varbitId&gt;".
     * No unset pass: a patch is never un-observed.
     */
    public void saveFarmingPatches(Collection<FarmingTracker.PersistedEntry> entries) {
        if (entries == null) {
            return;
        }
        for (FarmingTracker.PersistedEntry e : entries) {
            store.setRSProfileConfiguration(CONFIG_GROUP, KEY_FARMING_PREFIX + e.getConfigKey(),
                    e.getVarbitValue() + ":" + e.getObservedAtEpochSec());
        }
    }

    /** Load the persisted farming patch observations for the current RS profile. */
    public Collection<FarmingTracker.PersistedEntry> loadFarmingPatches() {
        List<FarmingTracker.PersistedEntry> out = new ArrayList<>();
        for (FarmingWorldMap.PatchDef patch : FarmingWorldMap.allPatches()) {
            String[] parts = fields(KEY_FARMING_PREFIX + patch.configKey(), 2);
            if (parts == null) {
                continue;
            }
            try {
                int value = Integer.parseInt(parts[0]);
                long ts = Long.parseLong(parts[1]);
                out.add(new FarmingTracker.PersistedEntry(patch.configKey(), value, ts));
            } catch (NumberFormatException ex) {
                // ignore malformed entry
            }
        }
        return out;
    }

    /**
     * Persist the learned farming tick offset as
     * "offsetSeconds:precisionMins:resolutionSeconds". The offset aligns growth predictions
     * to the player's farm-tick grid. Losing it only widens estimates until the next
     * observed growth tick.
     */
    public void saveFarmingTickOffset(int offsetSeconds, int precisionMins, int resolutionSeconds) {
        store.setRSProfileConfiguration(CONFIG_GROUP, KEY_FARMING_TICK_OFFSET,
                offsetSeconds + ":" + precisionMins + ":" + resolutionSeconds);
    }

    /**
     * Load the learned farming tick offset as {offsetSeconds, precisionMins,
     * resolutionSeconds}. When none was ever observed or the value is malformed, it is
     * {-1, -1, 1}: no offset learned yet, at one-second resolution.
     */
    public int[] loadFarmingTickOffset() {
        String[] parts = fields(KEY_FARMING_TICK_OFFSET, 3);
        if (parts != null) {
            try {
                return new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2])};
            } catch (NumberFormatException ex) {
                // Malformed: read as never observed.
            }
        }
        return new int[]{-1, -1, 1};
    }

    /**
     * This RS profile's colon-separated value for {@code key}, split, or null when unset or
     * when it does not hold exactly {@code count} fields.
     */
    private String[] fields(String key, int count) {
        String stored = store.getRSProfileConfiguration(CONFIG_GROUP, key);
        if (stored == null || stored.isEmpty()) {
            return null;
        }
        String[] parts = stored.split(":");
        return parts.length == count ? parts : null;
    }
}

package com.larryfarming.snapshot;

import java.util.List;
import lombok.Builder;
import lombok.Value;

/**
 * A farming run, worked out for this player: the stops in the default route's order, each with
 * the best route they can actually take.
 *
 * <p>Everything here is already decided. The panel only shows it; route choice stays in
 * the engine.
 */
@Value
@Builder(toBuilder = true)
public class FarmingAdvice {

    /** The run this walks, named for a player: "Herb run", or "Farm run" for a trip. */
    String runName;

    /**
     * Every crop family with a stop on what is showing, as {@code RunId.name()}, in the
     * order the trip reaches them. One entry for a single run, so trips and single runs read
     * the same way.
     *
     * <p>Order is the circuit's, not the ranking's: a trip opening at the Farming Guild
     * covers the contract first whatever the scheduler ranked it.
     */
    List<String> tripRuns;

    /**
     * True when the player is partway round: a patch on this walkthrough was seen growing
     * within one trip's span, in a family with an arrival still to make. The packing list
     * then describes a bank the player has already left, so the panel heads it as what the
     * rest of the run needs rather than what to take.
     *
     * <p>A primitive, so every builder path that never looks reads false.
     */
    boolean underway;

    /** The trip stop by stop, in the order it is walked. Derive stop counts from this list. */
    List<FarmingStopAdvice> stops;

    /** Gear to put on now, then gear to work toward. Already grouped and ordered. */
    List<FarmingUpgrade> upgrades;

    /** What to have in the bag: tools, seeds, and what the chosen routes need. */
    List<FarmingCarryItem> carry;

    /**
     * What the first stretch, up to the first later bank, needs in the bag: the "now" half
     * of {@link #getCarry()}. The rest comes out of the later banks, whose rows list it.
     * Empty when no later bank splits the trip, where the whole list is needed now, and once
     * underway, where the packing list is not drawn.
     */
    @Builder.Default
    List<FarmingCarryItem> carryNow = List.of();

    /**
     * The stores Larry has never looked in, asked for in one line, such as "Check your bank
     * and seed vault." Empty once he has seen every store the player can reach.
     */
    String lookOnce;

    /**
     * The respawn point the default route uses for this run, when it is not the one set.
     * Empty otherwise.
     *
     * <p>A suggestion, not a step: an account has one respawn point and the default route
     * uses different ones on different runs. The run is planned around the respawn point
     * actually set, never around this.
     */
    String respawnAction;

    /**
     * Which carried herb seeds the run leaves in the bag because the player has not ticked
     * them, as a sentence telling them where to tick. Empty otherwise.
     *
     * <p>Ticks decide what is planted, so the run never plants an unticked herb. This tells
     * the player why the seeds they brought are passed over.
     */
    String herbNote;

    /**
     * The book the bag was packed for: "STANDARD", "LUNAR" or "ARCEUUS". It decides which
     * teleports are free and which cost a tablet.
     */
    String carryFor;

    /** The book the player is actually on. {@link #getCarryFor()} follows it unless previewing. */
    String spellbookOpen;

    /**
     * Every farming run and whether it is worth doing, best first.
     *
     * <p>Includes every family the trip covers; the panel marks the trip's families by
     * checking this list against {@link #getTripRuns()}. Ordered by each run's value,
     * not by which timer expired first: an idle hardwood patch costs
     * more than an idle herb patch.
     *
     * <p>This ranking differs from the trip's circuit order on purpose. The panel draws the
     * list in {@link #getRunOrder()} instead and marks it from the trip.
     */
    List<FarmingRunStatus> runs;

    /**
     * Every run id in the order the RUNS list draws them. Fixed, so a row never moves when
     * a run comes due or is switched off. Rows not named here go last.
     */
    List<String> runOrder;

    /**
     * The runs the player has switched off, with status {@code OFF}. Kept out of
     * {@link #getRuns()}, which lists only runs worth planning, so the panel can still draw
     * the row that switches one back on.
     */
    List<FarmingRunStatus> switchedOff;

    /** The settings behind each run, as the side panel draws them under its row. */
    List<FarmingRunSettings> runSettings;

    /** Which run goes first when several are due, drawn under the RUNS heading. */
    FarmingSettingPick runFirst;

    /** The checkbox under the runs list: whether a run waits for every patch to need a visit. */
    FarmingSettingChoice waitForEveryPatch;

    /**
     * Every travel method under its caption, in a fixed order, each switched on or off. A
     * square marked missing is one the player has nothing for.
     */
    List<FarmingSettingGroup> travelGroups;

    /** What the player's house holds, seen or declared, drawn after the travel methods. */
    FarmingHouse house;

    /**
     * True when the player has no usable way to stand at a fairy ring, through their
     * switches or by owning none. False when the network itself is shut, by quest or
     * staff, since no switch helps then.
     */
    boolean fairyRingBlocked;

    /**
     * The volcanic ash this trip's Fertile Soil casts take. The planner reads it to leave the
     * compost bins only what the casts don't use, and the panel never reads it. It is
     * transient, so it stays out of equality: two pieces of advice that differ only here
     * compare equal.
     */
    transient int fertileAsh;
}

package com.larryfarming.snapshot;

import lombok.Value;
import lombok.With;

/**
 * One thing to have in the bag before setting off.
 */
@Value
public class FarmingCarryItem {

    /** Why it is on the list; also how the rows are grouped. */
    public enum Kind {
        /** Spade, dibber, compost — the same every run. */
        TOOL,
        /** Seeds for the patches, in the quantities the rotation worked out. */
        SEED,
        /**
         * Whatever a chosen route depends on being in the bag — a tablet, a piece of
         * jewellery, or the coins a minecart fare is paid in.
         */
        TRAVEL,
        /** Runes for a teleport a chosen route casts. */
        RUNES
    }

    /** How close this line is to being sorted. */
    public enum Availability {
        /** In the bag or worn: nothing to do, this one is ready to go. */
        CARRIED,
        /**
         * In tool-leprechaun storage: no inventory slot and no detour before leaving, but
         * still a withdrawal on arrival. Leprechaun storage is per-account, so anything in
         * it is reachable at every patch that has a leprechaun.
         */
        AT_LEPRECHAUN,
        /**
         * Owned, and the only place it can be is the seed box in the bag, which has not
         * been checked, or seen to take in or give out seeds, this session, so we cannot
         * confirm the seeds are still there.
         *
         * <p>Not {@link #CARRIED}, because the seeds may have been used in an unseen session.
         * Not {@link #BANKED}, because the player is very likely carrying them. Checking the
         * box settles it before the player walks anywhere.
         *
         * <p>Counted as a withdrawal everywhere a count is taken, so the bag is sized for the
         * seeds coming out of a bank.
         */
        IN_SEED_BOX,
        /** Owned, but in a bank or vault — still a withdrawal between here and leaving. */
        BANKED,
        /** Not owned anywhere we can see. */
        MISSING
    }

    Kind kind;

    int itemId;

    String name;

    /** How many, or 0 when the count is not the point (one spade is one spade). */
    @With
    int quantity;

    /** Where this item is, in the degrees that change what the player does next. */
    Availability availability;

    /** The short tag drawn over a seed ("TOA", "SNA"), or empty for anything else. */
    String tag;

    /**
     * A short caveat about this line (a cheaper fare on a condition, say), or empty.
     *
     * <p>Kept out of {@link #name} because the name feeds the hover and the still-to-get
     * line, while the panel draws the note under the grid.
     */
    @With
    String note;

    /**
     * How many of this are on the player right now, counting every form that would do.
     *
     * <p>{@link #availability} is a verdict and cannot be spent. A trip that breaks at
     * several banks draws on the same stack more than once, so it needs this count: two
     * guam seeds cover a planting before the bank stop and another after it, where the
     * {@code CARRIED} verdict read twice would cover both from one seed.
     *
     * <p>Counted over the same ids as the verdict, so a line a sapling satisfies counts
     * saplings. Zero when the player holds none, and zero for
     * {@link Availability#IN_SEED_BOX}: that is a deliberate under-claim, so an unconfirmed
     * seed box cannot settle a shortfall.
     *
     * <p><b>True only of a packing-list line.</b> On a bank row's withdrawal the quantity is
     * a shortfall against a simulated future bag, while this still reports the real bag.
     * The two describe different moments and must not be subtracted from one another.
     */
    @With
    int carriedCount;

    /** True when the player owns it at all, wherever it happens to be. */
    public boolean isOwned() {
        return availability != Availability.MISSING;
    }
}

package com.larryfarming.snapshot;

/**
 * How long, in words, for everything farming counts down to. The run list and the stop
 * rows share it so the same countdown never rounds two ways on one screen.
 *
 * <p>Lives beside the DTOs so the panel can reach it. The snapshot carries raw epoch
 * seconds and the panel words them here, so a countdown ticks by relabelling in place
 * rather than rebuilding its row and re-measuring the wrapping column.
 */
public final class FarmingDurations {

    private FarmingDurations() {
    }

    /** Rounded to the largest unit that still says something useful. */
    public static String describe(long seconds) {
        if (seconds <= 60) {
            return "under a minute";
        }
        long minutes = seconds / 60;
        if (minutes < 60) {
            return minutes + "m";
        }
        long hours = minutes / 60;
        if (hours < 24) {
            long spare = minutes % 60;
            return spare == 0 ? hours + "h" : hours + "h " + spare + "m";
        }
        long days = hours / 24;
        long spare = hours % 24;
        return spare == 0 ? days + "d" : days + "d " + spare + "h";
    }

    /**
     * How long until a moment, or empty when it is unknown or already past. An expired
     * prediction means the tracker has not seen the crop since, not that it just finished.
     *
     * @param epochSec when it happens, or 0 when unknown
     * @param nowEpochSec the current time
     */
    public static String until(long epochSec, long nowEpochSec) {
        if (epochSec <= 0 || epochSec <= nowEpochSec) {
            return "";
        }
        return describe(epochSec - nowEpochSec);
    }
}

