import lombok.Value;

/**
 * One farming run, and whether it is worth doing right now.
 *
 * <p>Everything is already decided and worded. The panel and the infobox both read this
 * and neither works anything out.
 */
@Value
public class FarmingRunStatus {

    /** The activity, as {@code RunId.name()}, so a click can ask for this run back. */
    String runId;

    /** Named for a player: "Hardwood run". */
    String runName;

    /**
     * {@code RunStatus.name()}: DUE, PENDING, LOCKED or UNSEEN. A run the player
     * has switched off reads OFF ({@code RunSettings.STATUS_OFF}).
     */
    String status;

    /**
     * The one line that goes beside the name: "3 ready", "ready in 2d 4h",
     * "needs 65 Farming", "not checked yet". Worded here, not in the panel.
     */
    String detail;

    /**
     * When the first patch finishes growing, or 0 when there is nothing to count down
     * to. Only meaningful while {@link #getStatus()} is PENDING.
     *
     * <p>A raw second rather than a formatted string so the panel can tick it down in
     * place without a structural rebuild of the row.
     */
    long readyAtEpochSec;

    /** The run's characteristic item, for the row icon and the infobox. */
    int iconItemId;

    /**
     * True when the player is out on this run right now and one of its woven-in extras is
     * still to do (an empty Ortus Farm patch, whiteberries ready at the Monastery), with
     * the run proper already worked out.
     *
     * <p>Kept apart from {@link #getStatus()}: extras are things to do while out there, not
     * reasons to go, so they must not make a run due. This flag tells a finished trip from
     * one abandoned early, so the walkthrough does not move to another run before the last
     * stop. Requiring "right now" keeps a run with a leftover extra from reading as an
     * unfinished trip for days.
     */
    boolean tripUnfinished;

    /**
     * True when the detail names work in the contract's own patch ("harvest your
     * avantoes") rather than an errand only Guildmaster Jane can settle.
     *
     * <p>The walkthrough borrows {@link #detail} for the guild's row. A patch-work detail
     * would repeat the row's own harvest clause, so the walkthrough leads with the detail
     * only for Jane's errands. A contract waiting on a crop elsewhere can instead name work
     * in the guild herb patch; that detail starts with {@code RunScheduler.HERB_PATCH_WORK},
     * and the row never borrows it either.
     *
     * <p>Set where the verdict is composed.
     */
    boolean aboutThePatch;
}

package com.larryfarming.snapshot;

import lombok.*;

/**
 * One control in the side panel's settings: a crop to tick, an item to switch, or a
 * checkbox.
 *
 * <p>Carries the config key, so the panel never decides which setting a control means.
 * Every key is a boolean read as "on": a click writes the control's new state to it.
 */
@Value
@AllArgsConstructor
public class FarmingSettingChoice {

    /** The {@code FarmingKeys} key this control writes, such as {@code plantRanarr}. */
    String key;

    /** Named for a player: "Ranarr", "Pick fruit from trees you pass". */
    String label;

    /** The sprite to draw, or 0 for a checkbox, which draws none. */
    int itemId;

    /** The short tag drawn on the sprite, as the inventory labels it. */
    String tag;

    /** The Farming level the crop needs. */
    int level;

    /** True when the setting is in force: the crop or checkbox is ticked, the item picked. */
    boolean on;

    /**
     * True for an item the player does not own, drawn grey but still clickable. Never set
     * while ownership is unread: an unread bank shows the item as owned.
     */
    boolean missing;

    /**
     * True when the setting cannot apply: the player's Farming level is below
     * {@link #level}, or for a patch, the account cannot reach it yet. Not clickable.
     */
    boolean locked;

    /**
     * A game sprite to draw instead of an item, such as a spell's icon, or 0 to draw
     * {@link #itemId}.
     */
    int spriteId;

    /**
     * Why a missing item is missing, said after its label, or null for the usual "None seen
     * yet": "None built" for house furniture seen absent.
     */
    String missingNote;

    /**
     * True for a house item Larry has seen, built or not. The player cannot change it, so it
     * takes no click.
     */
    boolean seen;

    /**
     * One short line for a checkbox whose label cannot make its effect obvious, or null for
     * none.
     */
    @With
    String tip;

    /** A control drawn as an item, or as a plain checkbox for item 0. */
    public FarmingSettingChoice(String key, String label, int itemId, String tag, int level, boolean on, boolean missing, boolean locked) {
        this(key, label, itemId, tag, level, on, missing, locked, 0, null, false, null);
    }
}

